        }

        // Maps PitchZones to a conceptual (column, row) grid for distance calculation
        // Column: 1=Left Flank, 2=Center, 3=Right Flank
        // Row: 1=Defensive Third, 2=Midfield, 3=Attacking Third
        // Special zones will have specific conceptual coordinates.
        private static readonly Dictionary<Enums.PitchZone, ZoneCoordinate> _zoneCoordinates = new Dictionary<Enums.PitchZone, ZoneCoordinate>
        {
            // Defensive Third (Home Team's half) - Rows generally start from the home goal (row 1)
            { Enums.PitchZone.HomeDefense_LeftFlank,    new ZoneCoordinate(1, 1) },
            { Enums.PitchZone.HomeDefense_Center,       new ZoneCoordinate(2, 1) }, // This is where Defensive_EdgeOfBox will conceptually be placed as well.
            { Enums.PitchZone.HomeDefense_RightFlank,   new ZoneCoordinate(3, 1) },

            // Midfield
            { Enums.PitchZone.Midfield_LeftFlank,       new ZoneCoordinate(1, 2) },
            { Enums.PitchZone.Midfield_Center,          new ZoneCoordinate(2, 2) },
            { Enums.PitchZone.Midfield_RightFlank,      new ZoneCoordinate(3, 2) },

            // Attacking Third (Home Team's attacking half, Away Team's defensive half) - Rows go towards opponent goal (row 3)
            { Enums.PitchZone.AwayAttack_LeftFlank,     new ZoneCoordinate(1, 3) },
            { Enums.PitchZone.AwayAttack_Center,        new ZoneCoordinate(2, 3) },
            { Enums.PitchZone.AwayAttack_RightFlank,    new ZoneCoordinate(3, 3) },

            // Specific goal-related areas
            { Enums.PitchZone.PenaltyArea_Home,         new ZoneCoordinate(2, 0) }, // Main Home penalty area center
            { Enums.PitchZone.GoalkeeperArea_Home,      new ZoneCoordinate(2, -1) },// Innermost Home goal area
            { Enums.PitchZone.PenaltyArea_Away,         new ZoneCoordinate(2, 4) }, // Main Away penalty area center
            { Enums.PitchZone.GoalkeeperArea_Away,      new ZoneCoordinate(2, 5) }, // Innermost Away goal area

            // Set-piece specific zones (Note: These share coordinates with FarPost penalty areas below.
            // Your game logic will need to differentiate based on context, e.g., if it's a corner kick state).
            { Enums.PitchZone.Corner_HomeLeft,          new ZoneCoordinate(0, 0) },
            { Enums.PitchZone.Corner_HomeRight,         new ZoneCoordinate(4, 0) },
            { Enums.PitchZone.Corner_AwayLeft,          new ZoneCoordinate(0, 4) },
            { Enums.PitchZone.Corner_AwayRight,         new ZoneCoordinate(4, 4) },

            // Kick-off circle is essentially dead center
            { Enums.PitchZone.KickOffCircle,            new ZoneCoordinate(2, 2) },

            // --- NEW ZONES ---
            // These coordinates assume they represent the HOME team's defensive penalty area.
            // For the Away team's defensive penalty area, your game logic needs to dynamically
            // map these conceptual zones to the corresponding physical coordinates (e.g., by adding 4 to the Y-coordinate,
            // or by having a helper function like GetActualDefensiveZoneCoordinate(PitchZone defensiveZone, Team defendingTeam)).

            // Granular Home Defensive Penalty Area Zones (Row 0 for inside the box)
            { Enums.PitchZone.DefensivePenaltyArea_LeftNearPost,    new ZoneCoordinate(1, 0) },   // Left side of goal, inside box
            { Enums.PitchZone.DefensivePenaltyArea_Central,         new ZoneCoordinate(2, 0) },   // Center of goal, inside box (same as general PenaltyArea_Home)
            { Enums.PitchZone.DefensivePenaltyArea_RightNearPost,   new ZoneCoordinate(3, 0) },   // Right side of goal, inside box
            { Enums.PitchZone.DefensivePenaltyArea_LeftFarPost,     new ZoneCoordinate(0, 0) },   // Wide left, inside box (overlaps with Corner_HomeLeft)
            { Enums.PitchZone.DefensivePenaltyArea_RightFarPost,    new ZoneCoordinate(4, 0) },   // Wide right, inside box (overlaps with Corner_HomeRight)

            // Edge of Box (for the defending team)
            // Placed at (2,1) for Home side. This conceptually makes it slightly 'outside' the penalty box (row 0),
            // but it shares the row with HomeDefense_Center. Your logic will need to handle this distinction.
            { Enums.PitchZone.Defensive_EdgeOfBox,                  new ZoneCoordinate(2, 1) }
        };

