        #region Constructors

        public Game(Team homeTeam, Team awayTeam, int minutesPerHalf, bool silvergoalOT, bool traditionalOT, bool penaltyKicksOnlyOT,
            int numberOfsubs, DateTime gameTime,
            string leagueName, int FixtureOrRoundNumber, string gameName,
            bool forceSub = true, bool cup = false, bool isPlayoffOrFriendly = false, bool isEuroKnockoutRound = false)
        {
            this.leagueName = leagueName;
            this.FixtureOrRoundNumber = FixtureOrRoundNumber;
            this.gameName = gameName + " " + FixtureOrRoundNumber.ToString();

            this.HomeTeam = homeTeam;
            this.AwayTeam = awayTeam;
            this.minutesPerHalf = minutesPerHalf;
            this.minutesPerHalfPlusInjury = minutesPerHalf;
            this.referee = new Referee("Enigmatic", "Nobody");
            this.silvergoalOT = silvergoalOT;
            this.traditionalOT = traditionalOT;
            this.penaltyKicksOnlyOT = penaltyKicksOnlyOT;

            weather = Enums.WeatherIssue.None;
            homeGameStats = new GameStats();
            awayGameStats = new GameStats();
            this.gameDate = gameTime;
            this.FACupGame = cup;
            this.isPlayoffOrFriendly = isPlayoffOrFriendly;
            this.isEuroKnockoutRound = isEuroKnockoutRound;

            CurrentMatchState = Enums.MatchState.MatchSetup;

            CurrentHalf = Enums.Half.FirstHalf; // Start in the first half
            TotalGameSecondsElapsed = 0;
            CurrentMinute = 0;
            CurrentSecond = 0;

            // Calculate initial injury time (can be refined later with more event-based logic)
            firstHalfInjuryTimeSeconds = Dice.d121() + 59; // 1 to 3 minutes
            secondHalfInjuryTimeSeconds = Dice.d181() + 119; // 2 to 5 minutes (often more in 2nd half)

            // Initialize penalty shootout properties
            homeTeamPenaltyGoals = 0;
            awayTeamPenaltyGoals = 0;
            penaltyKicksTaken = 0;
            homeTeamPenaltyTakers = new Queue<Player>();
            awayTeamPenaltyTakers = new Queue<Player>();
            currentPenaltyKicker = null;
            currentPenaltyGoalkeeper = null;

            // ... (existing constructor logic) ...
            homeTeamSubstitutionsMade = 0;
            awayTeamSubstitutionsMade = 0;
            this.MAX_SUBSTITUTIONS = numberOfsubs;

            homeTeamPendingSubstitution = false;
            awayTeamPendingSubstitution = false;
            homeTeamSubOutPlayer = null;
            homeTeamSubInPlayer = null;
            awayTeamSubOutPlayer = null;
            awayTeamSubInPlayer = null;

            _currentCommentDisplayCompletionSource = new TaskCompletionSource<bool>();
            _currentCommentDisplayCompletionSource.SetResult(true); // Initially set as complete, so it doesn't block immediately
        }

        #endregion

        #region Initialization

        // NEW: Method for UI to signal completion of *one* commentary display
        public void SignalCommentDisplayComplete()
        {
            _currentCommentDisplayCompletionSource?.TrySetResult(true);
        }

        // NEW: Method for MatchEngine to await the UI
        // This will be called by SimulateMoment().
        private async Task WaitForCommentaryDisplayAsync()
        {
            if (_currentCommentDisplayCompletionSource != null)
            {
                await _currentCommentDisplayCompletionSource.Task; // Wait for the UI to signal completion
            }
            // Reset for the next commentary display
            _currentCommentDisplayCompletionSource = new TaskCompletionSource<bool>();
        }

