        }

        /// <summary>
        /// Populates the _zoneDistanceCache using your original CalculateActualZoneDistance logic.
        /// </summary>
        private void PopulateZoneDistanceCache()
        {
            var allZones = Enum.GetValues(typeof(Enums.PitchZone)).Cast<Enums.PitchZone>()
                               .Where(z => z != Enums.PitchZone.None && z != Enums.PitchZone._ZoneMax).ToList();

            foreach (var z1 in allZones)
            {
                foreach (var z2 in allZones)
                {
                    foreach (bool isHome in new bool[] { true, false })
                    {
                        // YOUR ORIGINAL LOGIC FOR DISTANCE CALCULATION IS USED HERE
                        // It uses GetZoneForwardValue and GetFlankOfZone, which are assumed to be available.
                        int distance = CalculateActualZoneDistance(z1, z2, isHome);
                        _zoneDistanceCache[new ZoneDistanceKey(z1, z2, isHome)] = distance;
                    }
                }
            }
        }

        /// <summary>
        /// Populates the _adjacentZonesCache using your original GetAdjacentZones logic.
        /// </summary>
        private void PopulateAdjacentZonesCache()
        {
            var allZones = Enum.GetValues(typeof(Enums.PitchZone)).Cast<Enums.PitchZone>()
                               .Where(z => z != Enums.PitchZone.None && z != Enums.PitchZone._ZoneMax).ToList();

            foreach (var currentZone in allZones)
            {
                foreach (bool isHome in new bool[] { true, false })
                {
                    // YOUR ORIGINAL GetAdjacentZones LOGIC IS USED HERE
                    // It's adapted to be a private static method for cache population.
                    List<Enums.PitchZone> calculatedAdjacent = CalculateActualAdjacentZones(currentZone, isHome);
                    _adjacentZonesCache[Tuple.Create(currentZone, isHome)] = new ReadOnlyCollection<Enums.PitchZone>(calculatedAdjacent);
                }
            }
        }

        /// <summary>
        /// Populates the _zonePathCache using your original GetZonesAlongPath (BFS) logic.
        /// </summary>
        private void PopulateZonePathCache()
        {
            var allZones = Enum.GetValues(typeof(Enums.PitchZone)).Cast<Enums.PitchZone>()
                               .Where(z => z != Enums.PitchZone.None && z != Enums.PitchZone._ZoneMax).ToList();

            foreach (var startZone in allZones)
            {
                foreach (var endZone in allZones)
                {
                    foreach (bool isHome in new bool[] { true, false })
                    {
                        // YOUR ORIGINAL BFS LOGIC IS USED HERE
                        // It's adapted to be a private static method for cache population.
                        List<Enums.PitchZone> path = CalculateActualZonesAlongPath(startZone, endZone, isHome);
                        _zonePathCache[new PathKey(startZone, endZone, isHome)] = new ReadOnlyCollection<Enums.PitchZone>(path);
                    }
                }
            }
        }

