        private void InitializeZoneHalfMap()
        {
            _zoneHalfMap = new Dictionary<Enums.PitchZone, PitchHalfType>();

            // --- Home Half Zones (Defensive zones for the Home team) ---
            _zoneHalfMap[Enums.PitchZone.HomeDefense_LeftFlank] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.HomeDefense_Center] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.HomeDefense_RightFlank] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.PenaltyArea_Home] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.GoalkeeperArea_Home] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.Corner_HomeLeft] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.Corner_HomeRight] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.DefensivePenaltyArea_LeftNearPost] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.DefensivePenaltyArea_RightNearPost] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.DefensivePenaltyArea_Central] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.DefensivePenaltyArea_LeftFarPost] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.DefensivePenaltyArea_RightFarPost] = PitchHalfType.Home;
            _zoneHalfMap[Enums.PitchZone.Defensive_EdgeOfBox] = PitchHalfType.Home;

            // --- Midfield Zones ---
            _zoneHalfMap[Enums.PitchZone.Midfield_LeftFlank] = PitchHalfType.Midfield;
            _zoneHalfMap[Enums.PitchZone.Midfield_Center] = PitchHalfType.Midfield;
            _zoneHalfMap[Enums.PitchZone.Midfield_RightFlank] = PitchHalfType.Midfield;
            _zoneHalfMap[Enums.PitchZone.KickOffCircle] = PitchHalfType.Midfield;

            // --- Away Half Zones (Defensive zones for the Away team) ---
            _zoneHalfMap[Enums.PitchZone.AwayAttack_LeftFlank] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.AwayAttack_Center] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.AwayAttack_RightFlank] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.PenaltyArea_Away] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.GoalkeeperArea_Away] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.Corner_AwayLeft] = PitchHalfType.Away;
            _zoneHalfMap[Enums.PitchZone.Corner_AwayRight] = PitchHalfType.Away;

            // --- Special Cases ---
            _zoneHalfMap[Enums.PitchZone.None] = PitchHalfType.None; // Default for 'None'
        }

        /// <summary>
        /// Initializes and pre-calculates forward and lateral values for all pitch zones.
        /// This method should be called once at game startup (e.g., in a static constructor,
        /// or explicitly from a game manager).
        /// </summary>
        // Your InitializeZoneData (renamed to InitializeZoneDataMap to match prior code)
        // Make sure it references _zoneCoordinates, which is now a member of MatchEngineHelper.
        private void InitializeZoneDataMap()
        {
            _zoneDataMap = new Dictionary<Enums.PitchZone, ZoneData>();

            foreach (Enums.PitchZone zone in Enum.GetValues(typeof(Enums.PitchZone)))
            {
                if (zone == Enums.PitchZone.None || zone == Enums.PitchZone._ZoneMax) continue;

                if (!_zoneCoordinates.TryGetValue(zone, out ZoneCoordinate coord))
                {
                    throw new Exception($"ERROR: PitchZone {zone} not found in _zoneCoordinates map during initialization. Skipping.");
                }

                ZoneData data = new ZoneData
                {
                    RawX = coord.X,
                    RawY = coord.Y,
                    LateralValue = coord.X - 2 // X-grid 0-4, center is X=2. Lateral value from -2 (left) to +2 (right).
                };

                // --- Home Team Attacking Perspective (attacks towards higher Y values, 0-9 scale from own goal to opponent goal) ---
                switch (zone)
                {
                    // Home Goal side (0-1 on conceptual 0-9 scale)
                    case Enums.PitchZone.GoalkeeperArea_Home: data.ForwardValueHomeAttacking = 0; break;
                    case Enums.PitchZone.PenaltyArea_Home:
                    case Enums.PitchZone.DefensivePenaltyArea_Central:
                    case Enums.PitchZone.DefensivePenaltyArea_LeftNearPost:
                    case Enums.PitchZone.DefensivePenaltyArea_RightNearPost: data.ForwardValueHomeAttacking = 1; break;
                    case Enums.PitchZone.DefensivePenaltyArea_LeftFarPost:
                    case Enums.PitchZone.DefensivePenaltyArea_RightFarPost: data.ForwardValueHomeAttacking = 0; break;
                    case Enums.PitchZone.Corner_HomeLeft:
                    case Enums.PitchZone.Corner_HomeRight: data.ForwardValueHomeAttacking = 1; break;

                    // Home Defense (2 on conceptual 0-9 scale)
                    case Enums.PitchZone.HomeDefense_LeftFlank:
                    case Enums.PitchZone.HomeDefense_Center:
                    case Enums.PitchZone.HomeDefense_RightFlank:
                    case Enums.PitchZone.Defensive_EdgeOfBox: data.ForwardValueHomeAttacking = 2; break;

                    // Midfield (4 on conceptual 0-9 scale)
                    case Enums.PitchZone.Midfield_LeftFlank:
                    case Enums.PitchZone.Midfield_Center:
                    case Enums.PitchZone.Midfield_RightFlank:
                    case Enums.PitchZone.KickOffCircle: data.ForwardValueHomeAttacking = 4; break;

                    // Away Attack (6 on conceptual 0-9 scale)
                    case Enums.PitchZone.AwayAttack_LeftFlank:
                    case Enums.PitchZone.AwayAttack_Center:
                    case Enums.PitchZone.AwayAttack_RightFlank: data.ForwardValueHomeAttacking = 6; break;

                    // Away Goal side (8-9 on conceptual 0-9 scale)
                    case Enums.PitchZone.PenaltyArea_Away: data.ForwardValueHomeAttacking = 8; break;
                    case Enums.PitchZone.GoalkeeperArea_Away: data.ForwardValueHomeAttacking = 9; break;
                    case Enums.PitchZone.Corner_AwayLeft:
                    case Enums.PitchZone.Corner_AwayRight: data.ForwardValueHomeAttacking = 7; break;

                    default:
                        data.ForwardValueHomeAttacking = (int)Math.Round((coord.Y + 1) * (9.0 / 6.0));
                        if (data.ForwardValueHomeAttacking < 0) data.ForwardValueHomeAttacking = 0;
                        if (data.ForwardValueHomeAttacking > 9) data.ForwardValueHomeAttacking = 9;
                        break;
                }

                // --- Away Team Attacking Perspective (attacks towards lower Y values, 0-9 scale from own goal to opponent goal) ---
                switch (zone)
                {
                    // Away Goal side (0-1 on conceptual 0-9 scale)
                    case Enums.PitchZone.GoalkeeperArea_Away: data.ForwardValueAwayAttacking = 0; break;
                    case Enums.PitchZone.PenaltyArea_Away: data.ForwardValueAwayAttacking = 1; break;
                    case Enums.PitchZone.Corner_AwayLeft:
                    case Enums.PitchZone.Corner_AwayRight: data.ForwardValueAwayAttacking = 1; break;

                    // Away Attack (2 on conceptual 0-9 scale) - these are the zones they attack in their half
                    case Enums.PitchZone.AwayAttack_LeftFlank:
                    case Enums.PitchZone.AwayAttack_Center:
                    case Enums.PitchZone.AwayAttack_RightFlank: data.ForwardValueAwayAttacking = 2; break;

                    // Midfield (4 on conceptual 0-9 scale)
                    case Enums.PitchZone.Midfield_LeftFlank:
                    case Enums.PitchZone.Midfield_Center:
                    case Enums.PitchZone.Midfield_RightFlank:
                    case Enums.PitchZone.KickOffCircle: data.ForwardValueAwayAttacking = 4; break;

                    // Home Defense (6 on conceptual 0-9 scale) - these are the zones they attack in opponent half
                    case Enums.PitchZone.HomeDefense_LeftFlank:
                    case Enums.PitchZone.HomeDefense_Center:
                    case Enums.PitchZone.HomeDefense_RightFlank:
                    case Enums.PitchZone.Defensive_EdgeOfBox: data.ForwardValueAwayAttacking = 6; break;

                    // Home Goal side (8-9 on conceptual 0-9 scale)
                    case Enums.PitchZone.PenaltyArea_Home:
                    case Enums.PitchZone.DefensivePenaltyArea_Central:
                    case Enums.PitchZone.DefensivePenaltyArea_LeftNearPost:
                    case Enums.PitchZone.DefensivePenaltyArea_RightNearPost: data.ForwardValueAwayAttacking = 8; break;
                    case Enums.PitchZone.DefensivePenaltyArea_LeftFarPost:
                    case Enums.PitchZone.DefensivePenaltyArea_RightFarPost: data.ForwardValueAwayAttacking = 9; break;
                    case Enums.PitchZone.GoalkeeperArea_Home: data.ForwardValueAwayAttacking = 9; break;
                    case Enums.PitchZone.Corner_HomeLeft:
                    case Enums.PitchZone.Corner_HomeRight: data.ForwardValueAwayAttacking = 7; break;

                    default:
                        data.ForwardValueAwayAttacking = (int)Math.Round((5 - coord.Y) * (9.0 / 6.0));
                        if (data.ForwardValueAwayAttacking < 0) data.ForwardValueAwayAttacking = 0;
                        if (data.ForwardValueAwayAttacking > 9) data.ForwardValueAwayAttacking = 9;
                        break;
                }

                _zoneDataMap[zone] = data;
            }
        }

        // Example of initialization (this would be in your MatchEngineHelper constructor or an Initialize method)
        public void InitializeZoneAdjacency() // Call this once at app startup!
        {
            foreach (Enums.PitchZone zone in Enum.GetValues(typeof(Enums.PitchZone)))
            {
                // Temporarily create a list using your existing switch logic
                List<Enums.PitchZone> tempAdjacentZones = new List<Enums.PitchZone>();
                switch (zone)
                {
                    case Enums.PitchZone.GoalkeeperArea_Home:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                        break;
                    case Enums.PitchZone.GoalkeeperArea_Away:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_Center); // Pushing out from own goal area
                        break;

                    case Enums.PitchZone.PenaltyArea_Home:
                        tempAdjacentZones.Add(Enums.PitchZone.GoalkeeperArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                        break;
                    case Enums.PitchZone.PenaltyArea_Away:
                        tempAdjacentZones.Add(Enums.PitchZone.GoalkeeperArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                        break;

                    case Enums.PitchZone.HomeDefense_LeftFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Corner_HomeLeft);
                        break;
                    case Enums.PitchZone.HomeDefense_Center:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_Center);
                        break;
                    case Enums.PitchZone.HomeDefense_RightFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Corner_HomeRight);
                        break;

                    case Enums.PitchZone.Midfield_LeftFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                        break;
                    case Enums.PitchZone.Midfield_Center:
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.KickOffCircle);
                        break;
                    case Enums.PitchZone.Midfield_RightFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                        break;

                    case Enums.PitchZone.AwayAttack_LeftFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.Corner_AwayLeft);
                        break;
                    case Enums.PitchZone.AwayAttack_Center:
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        break;
                    case Enums.PitchZone.AwayAttack_RightFlank:
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.Corner_AwayRight);
                        break;

                    case Enums.PitchZone.Corner_HomeLeft:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                        break;
                    case Enums.PitchZone.Corner_HomeRight:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                        tempAdjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                        break;
                    case Enums.PitchZone.Corner_AwayLeft:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                        break;
                    case Enums.PitchZone.Corner_AwayRight:
                        tempAdjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                        tempAdjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                        break;

                    case Enums.PitchZone.KickOffCircle:
                        tempAdjacentZones.Add(Enums.PitchZone.Midfield_Center);
                        break;
                    case Enums.PitchZone.None:
                        break;
                }
                _adjacentZonesMap.Add(zone, tempAdjacentZones);
            }
        }

        // Helper for GetIdealThroughBallReceivingZone: Pre-calculate forward neighbors
        private void InitializeForwardNeighborsMap()
        {
            _forwardNeighborsMap = new Dictionary<Enums.PitchZone, List<Enums.PitchZone>>();
            var allZones = Enum.GetValues(typeof(Enums.PitchZone)).Cast<Enums.PitchZone>().ToList();

            foreach (var currentZone in allZones)
            {
                if (currentZone == Enums.PitchZone.None || currentZone == PitchZone._ZoneMax) continue;
                _forwardNeighborsMap[currentZone] = new List<Enums.PitchZone>();

                int currentForwardValueHome = GetZoneForwardValue(currentZone, true);
                int currentForwardValueAway = GetZoneForwardValue(currentZone, false);
                Enums.Flank currentFlank = GetFlankOfZone(currentZone);

                foreach (var potentialNextZone in allZones)
                {
                    if (potentialNextZone == Enums.PitchZone.None || potentialNextZone == Enums.PitchZone._ZoneMax) continue;

                    // Check for Home Attacking perspective
                    int potentialForwardValueHome = GetZoneForwardValue(potentialNextZone, true);
                    if (potentialForwardValueHome == currentForwardValueHome + 1 &&
                        (GetFlankOfZone(potentialNextZone) == currentFlank || GetFlankOfZone(potentialNextZone) == Enums.Flank.Center || currentFlank == Enums.Flank.Center))
                    {
                        if (!_forwardNeighborsMap[currentZone].Contains(potentialNextZone)) // Avoid duplicates
                        {
                            _forwardNeighborsMap[currentZone].Add(potentialNextZone);
                        }
                    }

                    // Check for Away Attacking perspective if different logic needed
                    // int potentialForwardValueAway = GetZoneForwardValue(potentialNextZone, false);
                    // if (potentialForwardValueAway == currentForwardValueAway + 1 && ...)
                    // {
                    //    _forwardNeighborsMap[currentZone].Add(potentialNextZone);
                    // }
                }
                // Sort or filter here if needed for consistency (e.g., prefer central zones)
            }
        }

