        #region GameFlow

        public void SetUpGame(bool watchGame)
        {
            HomeTeam.SetUpMatchLineups();
            AwayTeam.SetUpMatchLineups();
            // 1. Initialize or clear the map for THIS game instance
            if (_coordsToZoneMap == null)
            {
                _coordsToZoneMap = new Dictionary<ZoneCoordinate, Enums.PitchZone>();
            }
            else
            {
                _coordsToZoneMap.Clear(); // Crucial if Game objects are reused for multiple matches
            }
            foreach (var entry in _zoneCoordinates)
            {
                // Skip the 'None' zone, as it's not a real playable coordinate on the pitch
                if (entry.Key == Enums.PitchZone.None)
                {
                    continue;
                }

                // Handle the specific case where KickOffCircle and Midfield_Center share coordinates.
                // We want Midfield_Center to be the primary mapping for that coordinate.
                // If the current entry is KickOffCircle, we only add it IF the coordinate isn't already mapped
                // (which means Midfield_Center hasn't been added yet for this coordinate).
                if (entry.Key == Enums.PitchZone.KickOffCircle)
                {
                    // If Midfield_Center has the same coordinate and has already been added, we do nothing.
                    // Otherwise, add KickOffCircle.
                    if (!_coordsToZoneMap.ContainsKey(entry.Value))
                    {
                        _coordsToZoneMap.Add(entry.Value, entry.Key);
                    }
                }
                else
                {
                    // For all other zones, try to add them.
                    // If a coordinate is already present (e.g., from KickOffCircle being added first,
                    // and now Midfield_Center comes along with the same coordinate),
                    // we prioritize the main playing zone (Midfield_Center).
                    // This 'try-catch' or 'ContainsKey' check is important to prevent
                    // "An item with the same key has already been added" exception.
                    if (_coordsToZoneMap.ContainsKey(entry.Value))
                    {
                        // If the existing entry for this coordinate is KickOffCircle,
                        // and the current entry is Midfield_Center, override it.
                        if (_coordsToZoneMap[entry.Value] == Enums.PitchZone.KickOffCircle && entry.Key == Enums.PitchZone.Midfield_Center)
                        {
                            _coordsToZoneMap[entry.Value] = Enums.PitchZone.Midfield_Center;
                        }
                        // Otherwise, if it's already mapped to something else (e.g., Midfield_Center),
                        // or if the current entry isn't Midfield_Center, just skip.
                    }
                    else
                    {
                        // If the coordinate isn't already in the map, add it.
                        _coordsToZoneMap.Add(entry.Value, entry.Key);
                    }
                }
            }

            _defendersInZoneMap = new Dictionary<Enums.PitchZone, List<Player>>();
            _attackerToMarkerMap = new Dictionary<Player, Player>();

            InitializeZoneDataMap(); // Your existing method, now relies on _zoneCoordinates;
            InitializeZoneHalfMap();
            PopulateAdjacentZonesCache(); // Populate adjacencies first, as pathfinding needs them
            PopulateZoneDistanceCache();
            PopulateZonePathCache();
            InitializeForwardNeighborsMap();
            //InitializeZoneAdjacency();

            if (!isPlayoffOrFriendly)
            {
                foreach (Player p in HomeTeam.completeRoster)
                {
                    p.InitializePlayerStats(leagueName, HomeTeam.Name);
                }

                foreach (Player p in AwayTeam.completeRoster)
                {
                    p.InitializePlayerStats(leagueName, AwayTeam.Name);
                }

                foreach (Player p in HomeTeam.CurrentEleven)
                    p.LeagueTeamSeasonStats[leagueName][HomeTeam.Name].matchesPlayed++;
                foreach (Player p in AwayTeam.CurrentEleven)
                    p.LeagueTeamSeasonStats[leagueName][AwayTeam.Name].matchesPlayed++;

                // TO DO: Random weather based on date and climate area.
                SetMatchWeather(Enums.WeatherType.Sunny);
            }

            this.yellowCardRegs = Enums.YellowCardRegulations.EPL;

            this.watchingGame = watchGame;
            //coin flip to determine who has ball first
            int decider = Dice.d6();
            if (decider <= 3)
            {
                AttackingTeam = HomeTeam;
                DefendingTeam = AwayTeam;
            }
            else
            {
                homeTeamHadBallFirst = false;
                AttackingTeam = AwayTeam;
                DefendingTeam = HomeTeam;
            }

            ResetForKickoff();

            this.HomeTeam.ResetStats();
            this.AwayTeam.ResetStats();

            foreach (Player p in HomeTeam.completeRoster)
            {
                p.InitializePlayerStats(leagueName, HomeTeam.Name);
            }

            foreach (Player p in AwayTeam.completeRoster)
            {
                p.InitializePlayerStats(leagueName, AwayTeam.Name);
            }

            foreach (Player p in HomeTeam.CurrentEleven)
                p.LeagueTeamSeasonStats[leagueName][HomeTeam.Name].matchesPlayed++;
            foreach (Player p in AwayTeam.CurrentEleven)
                p.LeagueTeamSeasonStats[leagueName][AwayTeam.Name].matchesPlayed++;
        }

        public void CleanUpgame()
        {
            NotifyGameIsOver();

            this.HomeTeam.StoreGameStats();
            this.AwayTeam.StoreGameStats();
            if (!this.isPlayoffOrFriendly)
            {
                this.HomeTeam.StoreSeriesOfStats(leagueName);
                this.AwayTeam.StoreSeriesOfStats(leagueName);
            }

            homeGameStats.shotsOnGoal = 0;
            homeGameStats.shotsTotal = 0;
            awayGameStats.shotsOnGoal = 0;
            awayGameStats.shotsTotal = 0;
            StoreStatsForGame(homeGameStats, this.HomeTeam);
            StoreStatsForGame(awayGameStats, this.AwayTeam);

            GamePlayed = true;
        }

        public async Task BeginGame(bool watchingGame = true, Enums.YellowCardRegulations yellowCardRegs = Enums.YellowCardRegulations.EPL)
        {
            this.SetUpGame(watchingGame);
            await this.PlayGame(); // Do NOT await here, as BeginGame is synchronous
            this.CleanUpgame();
            //logger.RecordPlayByPlay();
        }

        public async Task PlayGame()
        {
            while (CurrentMatchState != Enums.MatchState.MatchEnded)
            {
                if (this.watchingGame)
                {
                    if (!Paused)
                    {
                        // **** THIS IS THE ONLY CHANGE NEEDED IN PLAYGAME ****
                        await this.SimulateMoment(); // <--- YOU MUST AWAIT HERE!!!
                    }
                    else
                    {
                        await Task.Delay(100); // Allow UI to process events while paused
                    }
                }
                else // If not watching game, simulate as fast as possible
                {
                    // For non-watching, if SimulateMoment is async Task,
                    // calling it without await here *is* the fire-and-forget behavior for fast sim.
                    await this.SimulateMoment(); // This will not wait, allowing fast simulation.
                }
            }
        }

        private async Task SimulateMoment() // Rename DeterminePitchAction for clarity of new purpose
        {
            if (CurrentBallHolder != null &&
                CurrentBallHolder.Position == Enums.Positions.Goalkeeper &&
                CurrentMatchState == Enums.MatchState.InPlay_Possession)
            {
                throw new Exception("Inconsistent State Detected at Start of SimulateMoment!");
            }

            // --- 1. Advance the Game Clock and Update Display ---
            // Only advance time if the game is actively in a playing state{
            if (CurrentMatchState != Enums.MatchState.MatchSetup &&
                CurrentMatchState != Enums.MatchState.Halftime &&
                CurrentMatchState != Enums.MatchState.Fulltime &&
                CurrentMatchState != Enums.MatchState.PenaltyShootout) // Don't advance time during shootout
            {
                //PopulateAttackerAndDefenderZones();

                if (!ReboundChance && !AerialBattlePending)
                    TotalGameSecondsElapsed += MOMENT_DURATION_SECONDS;

                foreach (Player player in HomeTeam.AvailableOnFieldPlayers.Concat(AwayTeam.AvailableOnFieldPlayers))
                {
                    player.gameStats.SecondsPlayed += MOMENT_DURATION_SECONDS;
                }

                if (AttackingTeam != null)
                    AttackingTeam.gameStats.SecondsWithBall += MOMENT_DURATION_SECONDS;

                // Evaluate tactics every 5 or 10 minutes (adjust as desired)
                if (CurrentMinute % 5 == 0 && CurrentMinute != lastTacticsEvaluationMinute)
                {
                    EvaluateTeamTactics();
                    lastTacticsEvaluationMinute = CurrentMinute;
                }
                ConsiderSubstitutions(HomeTeam, AwayTeam, HomeScore, AwayScore, CurrentMinute);
                ConsiderSubstitutions(AwayTeam, HomeTeam, AwayScore, HomeScore, CurrentMinute);

                // Calculate current minute and second for display relative to the start of the current period
                int secondsPassedInCurrentPeriod = 0;
                int currentPeriodNominalDuration = 0;

                if (CurrentHalf == Enums.Half.FirstHalf)
                {
                    secondsPassedInCurrentPeriod = TotalGameSecondsElapsed;
                    currentPeriodNominalDuration = FIRST_HALF_NOMINAL_DURATION_SECONDS;
                }
                else if (CurrentHalf == Enums.Half.SecondHalf)
                {
                    secondsPassedInCurrentPeriod = TotalGameSecondsElapsed - (FIRST_HALF_NOMINAL_DURATION_SECONDS);
                    currentPeriodNominalDuration = SECOND_HALF_NOMINAL_DURATION_SECONDS;
                }
                else if (CurrentHalf == Enums.Half.ExtraTimeFirst)
                {
                    // Time for ET1 starts after end of regular time + injury time for both halves
                    secondsPassedInCurrentPeriod = TotalGameSecondsElapsed - (FIRST_HALF_NOMINAL_DURATION_SECONDS +
                                                                              SECOND_HALF_NOMINAL_DURATION_SECONDS + secondHalfInjuryTimeSeconds);
                    currentPeriodNominalDuration = EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS;
                }
                else if (CurrentHalf == Enums.Half.ExtraTimeSecond)
                {
                    // Time for ET2 starts after ET1
                    secondsPassedInCurrentPeriod = TotalGameSecondsElapsed - (FIRST_HALF_NOMINAL_DURATION_SECONDS +
                                                                              SECOND_HALF_NOMINAL_DURATION_SECONDS +
                                                                              EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS);
                    currentPeriodNominalDuration = EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS;
                }

                //CurrentMinute = Math.Max(0, secondsPassedInCurrentPeriod / 60);
                //CurrentSecond = Math.Max(0, secondsPassedInCurrentPeriod % 60);
                CurrentMinute = Math.Max(0, TotalGameSecondsElapsed / 60);
                CurrentSecond = Math.Max(0, TotalGameSecondsElapsed % 60);

                OnTimeUpdated?.Invoke(CurrentSecond, CurrentMinute);

                CleanPotentialChances(CurrentSecond);

                // Append injury time display for regular halves
                //string injuryTimeDisplay = "";
                //if (CurrentHalf == Enums.Half.FirstHalf && secondsPassedInCurrentPeriod >= FIRST_HALF_NOMINAL_DURATION_SECONDS)
                //{
                //    injuryTimeDisplay = "+" + ((TotalGameSecondsElapsed - FIRST_HALF_NOMINAL_DURATION_SECONDS) / 60);
                //}
                //else if (CurrentHalf == Enums.Half.SecondHalf && secondsPassedInCurrentPeriod >= SECOND_HALF_NOMINAL_DURATION_SECONDS)
                //{
                //    injuryTimeDisplay = "+" + ((TotalGameSecondsElapsed - FIRST_HALF_NOMINAL_DURATION_SECONDS) / 60);
                //}
                // No injury time for extra time periods in standard rules

                //LogEntry(new MatchEntry
                //{
                //    Level = LogLevel.Info,
                //    EventType = MatchEventType.MomentStart,
                //    Timestamp = DateTime.Now
                //});
            }

            if (CurrentMatchState == Enums.MatchState.InPlay_Possession ||
               CurrentMatchState == Enums.MatchState.ExtraTime_FirstHalf ||
               CurrentMatchState == Enums.MatchState.ExtraTime_SecondHalf) // Drain condition during active play
            {
                if (CurrentBallHolder != null && !CurrentBallHolder.IsInjured)
                {
                    CurrentBallHolder.DecreaseCondition(0.5); // Moderate drain for being active with the ball
                }
            }

            // Restore some condition for all players during non-active states (set-pieces, half-time, goals)
            foreach (var player in HomeTeam.AvailableOnFieldPlayers.Concat(AwayTeam.AvailableOnFieldPlayers)) // Only for active, non-injured players
            {
                if (CurrentMatchState == Enums.MatchState.CornerKick || CurrentMatchState == Enums.MatchState.Foul ||
                    CurrentMatchState == Enums.MatchState.FreeKick || CurrentMatchState == Enums.MatchState.FreeKick_Indirect ||
                    CurrentMatchState == Enums.MatchState.GoalKick || CurrentMatchState == Enums.MatchState.GoalScored ||
                    CurrentMatchState == Enums.MatchState.Offside || CurrentMatchState == Enums.MatchState.PenaltyKick ||
                    CurrentMatchState == Enums.MatchState.KickOff || CurrentMatchState == Enums.MatchState.ThrowIn)
                {
                    player.RestoreCondition(0.1); // Small restoration during stoppages
                }
            }
            // Also restore during HalfTime specifically for a larger boost
            if (CurrentMatchState == Enums.MatchState.Halftime)
            {
                foreach (var player in HomeTeam.AvailableOnFieldPlayers.Concat(AwayTeam.AvailableOnFieldPlayers))
                {
                    player.RestoreCondition(20.0); // Significant restoration at half-time
                }
            }

            if (CurrentMatchState != MatchState.InPlay_Possession)
            {
                AerialBattlePending = false; // aerial battle has been resolved.
                ResetRebounds(); // Can't rebound unless it's immediate
            }

            // --- Core Game Logic Flow based on MatchState ---
            switch (CurrentMatchState)
            {
                case Enums.MatchState.MatchSetup:
                    // This state should typically run only once at the start of the match.
                    // TO DO: Coin toss and keep track of coin toss winner
                    AttackingTeam = HomeTeam; // Initial setup for the first kick-off
                    DefendingTeam = AwayTeam;

                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the more general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase
                        GamePhase = GamePhaseType.MatchStart, // Assuming 'MatchSetup' refers to the start of the match

                        // Use the specific fields for game time
                        CurrentMatchMinute = CurrentMinute,
                        CurrentMatchSecond = CurrentSecond,

                        // Team names remain directly mapped
                        TeamName1 = AttackingTeam.Name,
                        TeamName2 = DefendingTeam.Name
                    });
                    // Set initial teams for kick-off.
                    // For the first kick-off, usually the home team or a coin toss winner.
                    CurrentMatchState = Enums.MatchState.KickOff; // Transition to the KickOff state
                    break;

                case Enums.MatchState.KickOff:
                    // This case handles the actual kick-off.
                    // You'll need a method to determine who is kicking off and where the ball goes.Example: Set possession to a central midfielder after a successful kick-off pass
                    Player kickoffReceiver = AttackingTeam.AvailableOnFieldOutfielders.FirstOrDefault(p => p.Position == Enums.Positions.CentralMidfielder || p.Position == Enums.Positions.CentralAttackingMidfielder); // Example: Find a central midfielder
                    if (kickoffReceiver != null)
                    {
                        SetPossession(kickoffReceiver, Enums.PitchZone.Midfield_Center, AttackingTeam);
                        CurrentMatchState = Enums.MatchState.InPlay_Possession; // Transition to in-play possession
                    }
                    else
                    {
                        kickoffReceiver = AttackingTeam.AvailableOnFieldOutfielders.FirstOrDefault();
                        SetPossession(kickoffReceiver, Enums.PitchZone.Midfield_Center, AttackingTeam);
                        CurrentMatchState = Enums.MatchState.InPlay_Possession; // Transition to in-play possession
                    }
                    kickOff = false; // Reset kickOff flag

                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase for kickoff
                        GamePhase = GamePhaseType.KickOff,

                        // Team and Player details remain directly mapped
                        TeamName1 = AttackingTeam.Name,
                        PlayerName1 = kickoffReceiver.fullName,
                        Player1Pos = kickoffReceiver.Position
                    });

                    break;

                case Enums.MatchState.InPlay_Possession:
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
                        EventType = MatchEventType.PlayerMoved,
                        Timestamp = DateTime.Now, // Always include for precise timing

                        PlayerName1 = CurrentBallHolder.fullName,
                        Player1Pos = CurrentBallHolder.position,
                        TeamName1 = AttackingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
                        Zone1 = CurrentBallZone,
                        IsRebound = ReboundChance,
                        IsAerialBattlePending = AerialBattlePending,

                        // You could optionally add a boolean attribute to MatchEntry like 'IsDribbling'
                        // if you want to explicitly state the nature of the possession.
                        // E.g., IsDribbling = true;
                    });
                    int idOfPlayerGoingIntoPossession = CurrentBallHolder.ID;
                    // --- Crucial: Reset and Populate Per-Moment Caches ---
                    ResetPerMomentCaches(); // Clears all per-moment caches
                    PopulateDefendersInZoneMap(DefendingTeam); // Populates the defenders map
                    // Update marking status for all attackers for this moment
                    UpdateAllMarkingAssignments(AttackingTeam, DefendingTeam, CurrentBallHolder, CurrentMinute, CurrentSecond);

                    // Evaluate off-ball obstruction fouls once per moment
                    EvaluateOffBallObstructionFouls();
                    if (CurrentMatchState == Enums.MatchState.FreeKick)
                    {
                        ResetRebounds();
                        break;
                    }

                    if (CurrentBallHolder != null && CurrentBallHolder.Position != Enums.Positions.Goalkeeper)
                    {
                        // This block runs ONCE per 15-second moment.

                        // 1. Determine Overload Target Zone (if applicable)
                        if (!AerialBattlePending)
                        {
                            // We skip a lot because the play technically isn't over yet!
                            DetermineOverloadTargetZone(AttackingTeam, DefendingTeam, CurrentMinute, CurrentSecond);
                            // 2. Evaluate Attacking Player Movement (Off-ball)
                            foreach (Player player in AttackingTeam.AvailableOnFieldOutfielders)
                            {
                                if (player != CurrentBallHolder) // Ball holder's movement is handled by dribble/pass
                                {
                                    // Pass CurrentMinute and CurrentSecond to EvaluateAttackingMovement
                                    EvaluateAttackingMovement(player, AttackingTeam, DefendingTeam, Enums.SetPieceRoutine.None, CurrentMinute, CurrentSecond);
                                }
                                else // Ensure ball holder's zone is correct (it should be CurrentBallZone)
                                {
                                    if (CurrentBallZone != Enums.PitchZone.None)
                                    {
                                        player.CurrentZone = CurrentBallZone;
                                    }
                                }
                            }

                            // 3. Evaluate Defending Player Movement/Actions
                            foreach (Player player in DefendingTeam.AvailableOnFieldPlayers)
                            {
                                if (player.Position == Enums.Positions.Goalkeeper)
                                {
                                    // DecideGoalkeeperAction(player, CurrentBallHolder, DefendingTeam, AttackingTeam, CurrentMinute, CurrentSecond); // Add minute/second
                                }
                                else
                                {
                                    // DetermineDefensiveZone and DecideDefensiveAction are now called here.
                                    // Pass CurrentMinute and CurrentSecond to DetermineDefensiveZone and DecideDefensiveAction
                                    player.CurrentZone = DetermineDefensiveZone(player, CurrentBallZone, DefendingTeam); // Pass minute/
                                    DecideDefensiveAction(player, CurrentBallHolder, DefendingTeam, AttackingTeam); // Pass minute/second
                                    if (CurrentMatchState != MatchState.InPlay_Possession || CurrentBallHolder.ID != idOfPlayerGoingIntoPossession)
                                        break;
                                }
                            }

                            // Change of possession. Allow SimulateMoment to determine what the new team that possesses the ball do next.
                            if (CurrentMatchState != MatchState.InPlay_Possession || CurrentBallHolder.ID != idOfPlayerGoingIntoPossession)
                            {
                                ResetRebounds(); // whatever happened, a rebound opportunity was obviously denied.
                                break;
                            }
                        }

                        // 4. Ball Holder's Decision (after other players have moved)
                        // Pass CurrentMinute and CurrentSecond to PlayerDecision
                        PlayerDecision(CurrentBallHolder, AttackingTeam, DefendingTeam, CurrentBallHolder.CurrentZone);

                        if (CurrentMatchState == Enums.MatchState.InPlay_Possession && CurrentBallHolder.ID == idOfPlayerGoingIntoPossession)
                        {
                            if (CurrentBallHolder != null)
                            {
                                if (CurrentBallZone == CurrentBallHolder.CurrentZone)
                                {
                                    // 5. Check for Breakaway (after all movement and decisions for this moment)
                                    // Pass CurrentMinute and CurrentSecond to IsAttackerOnBreakaway
                                    if (IsAttackerOnBreakaway(CurrentBallHolder, DefendingTeam, CurrentBallZone))
                                    {
                                        if (CurrentBallHolder != null)
                                        {
                                            if (CurrentBallZone != CurrentBallHolder.CurrentZone)
                                            {
                                                int x = 0;
                                            }
                                        }
                                        Player goalkeeper = DefendingTeam.GoalKeeper;
                                        Enums.ShotOutcome outcome = SimulateOneOnOne(CurrentBallHolder, goalkeeper, AttackingTeam, DefendingTeam);
                                        return; // Exit SimulateMoment if a major event like a breakaway occurs
                                    }
                                }
                                else
                                {
                                    string s = bestAction;
                                }
                            }
                        }
                    }
                    else
                    {
                        int x = 0;
                    }
                    PrevMS = CurrentMatchState;
                    break; // End of MatchState.InPlay_Possession case
                case Enums.MatchState.InPlay_LooseBall:
                    SetLooseBall(false, CurrentBallHolder, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                    break;
                case Enums.MatchState.InPlay_LooseBallHigh:
                    SetLooseBall(true, CurrentBallHolder, LooseBallDeliveryType, AttackingTeam, DefendingTeam);
                    break;
                case Enums.MatchState.GoalScored:
                    ResetForKickoff();
                    CurrentMatchState = Enums.MatchState.KickOff; // Next state after a goal is always a kick-off.
                    break;
                case Enums.MatchState.Foul:
                    // Based on the LastFoulOutcome determined by HandleFoulChance
                    // We should never get here with new code.
                    switch (LastFoulOutcome)
                    {
                        case Enums.FoulOutcome.Foul_Penalty:
                            //ShowMessage("Penalty awarded to " + AttackingTeam.Name + "!");
                            SetPossession(CurrentBallHolder, CurrentBallZone, AttackingTeam); // Ensure attacking team has possession for penalty
                            CurrentMatchState = Enums.MatchState.PenaltyKick;
                            break;

                        case Enums.FoulOutcome.Foul_RedCard:
                            //ShowMessage("The foul was so severe, it's a straight red card! " + CurrentBallHolder.fullName + "'s team has possession.");
                            // The player was already sent off in HandleFoulChance.
                            // Now determine the restart: It's always a direct free kick for a red card foul (unless it was a penalty).
                            SetPossession(CurrentBallHolder, CurrentBallZone, AttackingTeam); // Possession to the fouled team
                            CurrentMatchState = Enums.MatchState.FreeKick; // Direct free kick for serious fouls
                            break;

                        case Enums.FoulOutcome.Foul_YellowCard:
                            //ShowMessage("Yellow card issued. " + CurrentBallHolder.fullName + "'s team gets a free kick.");
                            // Player was already booked (and potentially sent off if it was a second yellow) in HandleFoulChance.
                            // This is usually a direct free kick.
                            SetPossession(CurrentBallHolder, CurrentBallZone, AttackingTeam); // Possession to the fouled team
                            CurrentMatchState = Enums.MatchState.FreeKick; // Most yellow card fouls result in a direct free kick
                            break;

                        case Enums.FoulOutcome.Foul_FreeKick:
                            //ShowMessage("Free kick awarded to " + AttackingTeam.Name + ".");
                            // This could be a direct or indirect free kick depending on the specific foul type
                            // and location (e.g., handball vs. dangerous play). For simplicity, let's make it direct unless specified otherwise.
                            // If you want more nuance here for indirect free kicks, you'd need another enum or flag.
                            SetPossession(CurrentBallHolder, CurrentBallZone, AttackingTeam); // Possession to the fouled team
                            CurrentMatchState = Enums.MatchState.FreeKick; // Default to direct free kick
                            break;

                        case Enums.FoulOutcome.NoFoul: // Should not happen if state is Foul
                        default:
                            //ShowMessage("ERROR: Foul state reached with an unexpected FoulOutcome or NoFoul. Reverting to loose ball.");
                            SetLooseBall(false, CurrentBallHolder, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                            //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
                            break;
                    }
                    break; // End of MatchState.Foul case
                case Enums.MatchState.Offside:
                    //ShowMessage("Offside! Free kick awarded.");
                    // The ball should be placed where the offside offense occurred.
                    // Assuming `CurrentBallZone` was set by `AttemptPass` to the receiver's zone for the offside call.
                    // The defending team (who won the free kick) becomes the new attacking team.
                    // We should never get here with new code.
                    AttackingTeam = DefendingTeam;
                    DefendingTeam = (AttackingTeam == HomeTeam) ? AwayTeam : HomeTeam; // Update defending team
                    CurrentBallHolder = null; // Ball is not in possession yet
                    CurrentMatchState = Enums.MatchState.FreeKick_Indirect; // Or MatchState.FreeKick
                    // We'll add a 'HandleFreeKick' method for the FreeKick_Indirect state.
                    break;

                case Enums.MatchState.CornerKick:
                    CornerKickHandler();

                    break; // End of MatchState.CornerKick case
                case Enums.MatchState.FreeKick_Indirect:
                    IndirectFreeKickHandler(AttackingTeam, DefendingTeam, CurrentBallZone);
                    break; // End of MatchState.FreeKick_Indirect case

                case Enums.MatchState.FreeKick: // Direct Free Kick
                    DirectFreeKickHandler(AttackingTeam, DefendingTeam, CurrentBallZone);
                    break;
                case Enums.MatchState.PenaltyKick:
                    PenaltyKickOpenPlayHandler();
                    break; // End of MatchState.PenaltyKick case
                case Enums.MatchState.ThrowIn:
                    ThrowInHandler();
                    break; // End of MatchState.ThrowIn case
                case Enums.MatchState.GoalKick:
                    HandleGoalkeeperDistribution(true);
                    PrevMS = CurrentMatchState;
                    break; // End of MatchState.GoalKick case
                case Enums.MatchState.GoalkeeperRecycle:
                    HandleGoalkeeperDistribution(false);
                    break; // End of MatchState.GoalKick case
                case Enums.MatchState.Halftime:
                    CurrentHalf = Enums.Half.SecondHalf; // Transition to the second half
                    OnHalfUpdated?.Invoke(CurrentHalf);
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase for Half Time
                        GamePhase = GamePhaseType.HalfTime,

                        // Use the specific score fields
                        HomeScore = TotalHomeScore(),
                        AwayScore = TotalAwayScore(),

                        // Team names remain directly mapped
                        TeamName1 = HomeTeam.Name,
                        TeamName2 = AwayTeam.Name
                    });
                    CurrentMinute = 45;
                    CurrentSecond = 0;
                    TotalGameSecondsElapsed = SECOND_HALF_NOMINAL_DURATION_SECONDS;
                    CurrentMatchState = Enums.MatchState.KickOff; // Second half starts with a kickoff
                    CurrentBallHolder = null; // Clear ball holder for kickoff
                    EvaluateTeamTactics();
                    // No need to reset TotalGameSecondsElapsed; it continues counting up.
                    break;

                case Enums.MatchState.Fulltime:
                    bool isGameOver = false;
                    //ShowMessage("FINAL SCORE: " + homeTeam.Name + ": " + homeScore + " - " + awayTeam {awayTeam.Name}");

                    CurrentMatchState = Enums.MatchState.MatchEnded;

                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase for Regulation Full Time
                        GamePhase = GamePhaseType.RegulationFullTime,

                        // Use the specific score fields
                        HomeScore = TotalHomeScore(),
                        AwayScore = TotalAwayScore(),

                        // Team names remain directly mapped
                        TeamName1 = HomeTeam.Name,
                        TeamName2 = AwayTeam.Name
                    });

                    if (TotalHomeScore() > TotalAwayScore())
                    {
                        isGameOver = true;
                        GameResult = RecordGameResult(HomeTeam, GetHomeScore(), AwayTeam, GetAwayScore(), true);
                    }
                    else if (TotalAwayScore() > TotalHomeScore())
                    {
                        isGameOver = true;
                        GameResult = RecordGameResult(AwayTeam, GetHomeScore(), HomeTeam, GetAwayScore(), true);
                    }
                    else
                    {
                        // This is the point where we determine if we go to extra time OR shootout if ET already happened
                        // The check in the 'end of period checks' (point 4 in previous response) handles the ET transition.
                        // If we reach FullTime and the score is still tied, it means ET already concluded.
                        if (traditionalOT)
                        {
                            CurrentHalf = Enums.Half.ExtraTimeFirst; // Set for first extra time half
                            OnHalfUpdated?.Invoke(CurrentHalf);
                            LogEntry(new MatchEntry
                            {
                                Level = LogLevel.Info,
                                EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                                Timestamp = DateTime.Now, // Always include for precise timing

                                // Set the specific game phase for Regulation Full Time
                                GamePhase = GamePhaseType.OvertimeStart,

                                // Use the specific score fields
                                HomeScore = TotalHomeScore(),
                                AwayScore = TotalAwayScore(),

                                // Team names remain directly mapped
                                TeamName1 = HomeTeam.Name,
                                TeamName2 = AwayTeam.Name

                            });
                            TotalGameSecondsElapsed = (SECOND_HALF_NOMINAL_DURATION_SECONDS * 2);
                            CurrentMinute = 90;
                            CurrentSecond = 0;
                            CurrentMatchState = Enums.MatchState.KickOff; // Start with kickoff for ET1
                            CurrentBallHolder = null; // Clear ball holder for kickoff
                            // Second half should be determined elsewhere.
                        }
                        else if (penaltyKicksOnlyOT)
                        {
                            CurrentMatchState = Enums.MatchState.PenaltyShootout;
                            CurrentHalf = Enums.Half.PenaltyShootout;
                        }
                        else
                        {
                            isGameOver = true;
                            GameResult = RecordGameResult(HomeTeam, GetHomeScore(), AwayTeam, GetAwayScore(), false);
                            CurrentMatchState = Enums.MatchState.MatchEnded;
                        }
                    }
                    if (isGameOver)
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                            Timestamp = DateTime.Now, // Always include for precise timing
                            HomeScore = TotalHomeScore(),
                            AwayScore = TotalAwayScore(),
                            HomePKScores = homeTeamPenaltyGoals,
                            AwayPKScores = awayTeamPenaltyGoals,
                            TeamName1 = HomeTeam.Name,
                            TeamName2 = AwayTeam.Name,

                            // Set the specific game phase for Overtime Start
                            GamePhase = GamePhaseType.MatchEnd
                        });
                    }

                    // You might want to set a flag here to exit the main game loop, e.g., IsMatchOver = true;
                    break;
                case Enums.MatchState.PenaltyShootout:
                    // This state will manage the flow of the shootout
                    // It's a "meta-state" that orchestrates individual kicks

                    // Initial setup if just entering this state
                    if (penaltyKicksTaken == 0 && homeTeamPenaltyGoals == 0 && awayTeamPenaltyGoals == 0)
                    {
                        SetupPenaltyShootout();
                    }

                    ShootOutHandler();
                    // If no winner yet, stay in PenaltyShootout state for the next kick.
                    break; // End of MatchState.PenaltyShootout case
                case Enums.MatchState.MatchEnded:
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase for Regulation Full Time
                        GamePhase = GamePhaseType.MatchEnd,

                        // Use the specific score fields
                        HomeScore = TotalHomeScore(),
                        AwayScore = TotalAwayScore(),
                        HomePKScores = homeTeamPenaltyGoals,
                        AwayPKScores = awayTeamPenaltyGoals,

                        // Team names remain directly mapped
                        TeamName1 = HomeTeam.Name,
                        TeamName2 = AwayTeam.Name
                    });
                    // The match is completely finished. Display final results and statistics.
                    // This state usually means the SimulateMoment loop should no longer be called.
                    break;
                case Enums.MatchState.SubstitutionOpportunity:
                    SubstituteHandler();
                    CurrentMatchState = PrevMS;
                    break; // Stay in SubstitutionOpportunity if more subs are pending (e.g., one team made a sub, other still has one)


                default:
                    throw new Exception($"Unhandled MatchState: {CurrentMatchState}!");
            }

            // TO DO: make sure that the stoppage/substiution logic is working correctly.
            bool isStoppageState = CurrentMatchState == Enums.MatchState.GoalScored ||
                           CurrentMatchState == Enums.MatchState.Offside ||
                           CurrentMatchState == Enums.MatchState.Foul ||
                           CurrentMatchState == Enums.MatchState.ThrowIn ||
                           CurrentMatchState == Enums.MatchState.GoalKick ||
                           CurrentMatchState == Enums.MatchState.CornerKick ||
                           CurrentMatchState == Enums.MatchState.FreeKick ||
                           CurrentMatchState == Enums.MatchState.FreeKick_Indirect ||
                           CurrentMatchState == Enums.MatchState.PenaltyKick ||
                           CurrentMatchState == Enums.MatchState.Halftime ||
                           CurrentMatchState == Enums.MatchState.Fulltime; // FullTime will also handle ET transitions

            if (isStoppageState)
            {
                foreach (Player p in delayedCardsAppliedDueToAdvantage)
                {
                    ApplyCard(p, CardType.Yellow);
                }
                delayedCardsAppliedDueToAdvantage.Clear();
            }

            if (isStoppageState && (homeTeamPendingSubstitution || awayTeamPendingSubstitution))
            {
                this.PrevMS = CurrentMatchState;
                // Only transition if we are NOT already in the SubstitutionOpportunity state
                // This prevents infinite loops if a sub is pending and we keep trying to make it.
                if (CurrentMatchState != Enums.MatchState.SubstitutionOpportunity)
                {
                    CurrentMatchState = Enums.MatchState.SubstitutionOpportunity;
                }
            }

            // --- 3. Check for End of Half/Game (after processing the current state) ---
            // Ensure these checks only happen if the game is in a 'playing' half
            if (CurrentHalf == Enums.Half.FirstHalf)
            {
                if (TotalGameSecondsElapsed >= FIRST_HALF_NOMINAL_DURATION_SECONDS + firstHalfInjuryTimeSeconds)
                {
                    CurrentMatchState = Enums.MatchState.Halftime;
                }
            }
            else if (CurrentHalf == Enums.Half.SecondHalf)
            {
                if (TotalGameSecondsElapsed >= FIRST_HALF_NOMINAL_DURATION_SECONDS +
                                               SECOND_HALF_NOMINAL_DURATION_SECONDS + secondHalfInjuryTimeSeconds)
                {
                    if (CurrentMatchState != Enums.MatchState.MatchEnded)
                    {
                        CurrentMatchState = Enums.MatchState.Fulltime;
                    }
                }
            }
            else if (CurrentHalf == Enums.Half.ExtraTimeFirst)
            {
                if (TotalGameSecondsElapsed >= FIRST_HALF_NOMINAL_DURATION_SECONDS +
                                               SECOND_HALF_NOMINAL_DURATION_SECONDS +
                                               EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS)
                {
                    // Short break, then immediately transition to second extra time half
                    CurrentHalf = Enums.Half.ExtraTimeSecond;
                    OnHalfUpdated?.Invoke(CurrentHalf);
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                        Timestamp = DateTime.Now, // Always include for precise timing

                        // Set the specific game phase for EndOfFirstHalfExtraTimeTraditionalOT
                        GamePhase = GamePhaseType.OvertimeHalfTime
                    });
                    TotalGameSecondsElapsed = (SECOND_HALF_NOMINAL_DURATION_SECONDS * 2) + EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS;
                    CurrentMinute = 105;
                    CurrentSecond = 0;
                    CurrentMatchState = Enums.MatchState.KickOff; // Kickoff for start of new period
                }
            }
            else if (CurrentHalf == Enums.Half.ExtraTimeSecond)
            {
                if (TotalGameSecondsElapsed >= FIRST_HALF_NOMINAL_DURATION_SECONDS +
                                               SECOND_HALF_NOMINAL_DURATION_SECONDS +
                                               EXTRA_TIME_HALF_NOMINAL_DURATION_SECONDS * 2) // Total extra time duration
                {
                    if (CurrentMatchState != Enums.MatchState.MatchEnded)
                    {
                        // After 2nd extra time half, if still tied, we need a shootout!
                        if (TotalHomeScore() == TotalAwayScore())
                        {
                            CurrentMatchState = Enums.MatchState.PenaltyShootout;
                            CurrentHalf = Half.PenaltyShootout;
                        }
                        else
                        {
                            if (TotalHomeScore() > TotalAwayScore())
                            {
                                GameResult = RecordGameResult(HomeTeam, GetHomeScore(), AwayTeam, GetAwayScore(), true);
                            }
                            else if (TotalAwayScore() > TotalHomeScore())
                            {
                                GameResult = RecordGameResult(AwayTeam, GetHomeScore(), HomeTeam, GetAwayScore(), true);
                            }

                            LogEntry(new MatchEntry
                            {
                                Level = LogLevel.Info,
                                EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                                Timestamp = DateTime.Now, // Always include for precise timing

                                // Set the specific game phase for Overtime End
                                GamePhase = GamePhaseType.OvertimeEnd,

                                // Use the specific score fields
                                HomeScore = TotalHomeScore(),
                                AwayScore = TotalAwayScore(),

                                // Team names remain directly mapped
                                TeamName1 = HomeTeam.Name,
                                TeamName2 = AwayTeam.Name
                            });

                            // A goal was scored in extra time, so the match is over!
                            CurrentMatchState = Enums.MatchState.MatchEnded;
                        }
                    }
                }
            }

            //foreach (var player in homeTeam.OnFieldPlayers.Concat(awayTeam.OnFieldPlayers))
            //{
            //    // TO DO: Have to adjust the numbers in this method.
            //    DetermineIfPlayerGotHurtOnPlay(player, CurrentMatchState);
            //}

            CleanupTemporaryPlayerStates();

            if (this.watchingGame)
                await Task.Delay(2000);

            //MyLogger.SubmitMatchEventBatch(_currentMomentLogBuffer); // Hand off the entire batch of structured entries
            //_currentMomentLogBuffer.Clear();

            //// A final check to ensure gameIsGoing aligns with MatchEnded state
            //if (!gameIsGoing && CurrentMatchState != Enums.MatchState.MatchEnded)
            //{
            //    CurrentMatchState = Enums.MatchState.MatchEnded;
            //}
        }

        public void ResetForKickoff()
        {
            // 1. Reset Ball State
            CurrentBallZone = Enums.PitchZone.KickOffCircle; // Ball is at the very center for the kickoff
            CurrentBallHolder = null;                       // No player has possession yet
            kickOff = true;                                 // Flag indicating a kickoff is pending
            ballIsLive = false;                             // Ball is not yet "in play" until the kickoff action is taken

            // 2. Reset Any Temporary Game Flags
            // These are examples; adjust based on what temporary flags your game uses
            specialSaveRequired = false;
            changedPossessionAtLeastOnceOrMidfieldBattle = false;

            // 3. Determine Which Team Kicks Off Next
            // This logic ensures the correct team starts with the ball after a goal or at a new half.
            if (CurrentMatchState == Enums.MatchState.GoalScored)
            {
                // If a goal was just scored, the team that *conceded* the goal gets the next kick-off.
                // AttackingTeam here refers to the team that *scored* the goal in the previous state.
                if (AttackingTeam == HomeTeam) // If homeTeam scored, awayTeam kicks off
                {
                    AttackingTeam = AwayTeam;
                    DefendingTeam = HomeTeam;
                }
                else // If awayTeam scored, homeTeam kicks off
                {
                    AttackingTeam = HomeTeam;
                    DefendingTeam = AwayTeam;
                }
            }
            else // This handles the initial game kickoff and the second-half kickoff.
            {
                // For half-time kickoff, or initial game kickoff, it alternates based on `homeTeamHadBallFirst`.
                // `homeTeamHadBallFirst` should ideally be initialized to `true` or `false` at the very start of the match setup.
                if (homeTeamHadBallFirst) // If home team kicked off the first half, away team kicks off the second.
                {
                    AttackingTeam = AwayTeam;
                    DefendingTeam = HomeTeam;
                    homeTeamHadBallFirst = false; // Toggle for the next half/game start
                }
                else // If away team kicked off the first half, home team kicks off the second.
                {
                    AttackingTeam = HomeTeam;
                    DefendingTeam = AwayTeam;
                    homeTeamHadBallFirst = true; // Toggle for the next half/game start
                }
            }

            // 4. Reset Player Positions to Their Formations
            // This calls the helper method to place all players on the pitch according to their team's formation
            // and the specific pitch zones.
            // Ensure your Team class has a 'CurrentFormation' property holding the Enums.Formation.
            ResetPlayerPositionsToFormation(HomeTeam, HomeTeam.CurrentFormation, true);  // Home team isHomeTeam = true
            ResetPlayerPositionsToFormation(AwayTeam, AwayTeam.CurrentFormation, false); // Away team isHomeTeam = false

            // Important: This method PREPARES for a kick-off.
            // The actual execution of the kick-off and transition to `InPlay_Possession`
            // happens in the `MatchState.KickOff` case within `SimulateMoment`.
        }

        string bestAction = "Dribble"; // Default fallback

        /// <summary>
        /// The central decision-making point for a player in possession.
        /// Calculates scores for various actions and chooses the best one.
        /// </summary>
        private void PlayerDecision(Player player, Team attackingTeam, Team defendingTeam, Enums.PitchZone currentZone)
        {
            int idOfPlayerGoingIntoPossession = CurrentBallHolder.ID;
            //LogEntry(new MatchEntry
            //{
            //    Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
            //    EventType = MatchEventType.PlayerMoved, // Use this event type
            //    Timestamp = DateTime.Now, // Always include for precise timing

            //    PlayerName1 = CurrentBallHolder.fullName,
            //    Player1Pos = CurrentBallHolder.position,
            //    TeamName1 = AttackingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
            //    Zone1 = CurrentBallZone,

            //    // You could optionally add a boolean attribute to MatchEntry like 'IsDribbling'
            //    // if you want to explicitly state the nature of the possession.
            //    // E.g., IsDribbling = true;
            //});

            Dictionary<string, double> actionScores = new Dictionary<string, double>();

            // Calculate scores for each action type, ensuring arguments match signatures
            actionScores["Shoot"] = CalculateShotOpportunity(player, currentZone, attackingTeam, defendingTeam);
            actionScores["Dribble"] = CalculateDribbleOpportunity(player, currentZone, attackingTeam, defendingTeam);
            actionScores["Short Pass"] = GetBestPassOpportunityScore(player, Enums.PassType.Short, currentZone, attackingTeam, defendingTeam);
            actionScores["Long Pass"] = GetBestPassOpportunityScore(player, Enums.PassType.Long, currentZone, attackingTeam, defendingTeam);
            actionScores["Clear"] = CalculateClearOpportunity(player, currentZone); // Assuming this signature is correct
            actionScores["Cross"] = GetBestCrossOpportunityScore(player, currentZone, attackingTeam, defendingTeam);

            double highestScore = -1.0;

            if (AerialBattlePending)
            {
                bestAction = "Short Pass"; // Default fallback for aerial battles
                actionScores["Cross"] = Int32.MinValue; // Nobody is going to cross from an aerial battle
                actionScores["Dribble"] = Int32.MinValue; // Nobody is going to directly dribble from an aerial battle
                int diceRoll = Dice.d100();
                if (diceRoll >= 97)
                {
                    double trapExpertise = player.trueRating.ballControl * 0.4 + player.trueRating.balance * 0.4 +
                        player.trueRating.composure * 0.1 + player.trueRating.header * 0.1;
                    trapExpertise *= 0.2;
                    diceRoll = Dice.d100();
                    if (diceRoll < trapExpertise)
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
                            EventType = MatchEventType.PlayerMoved, // Use this event type
                            Timestamp = DateTime.Now, // Always include for precise timing

                            PlayerName1 = player.fullName,
                            Player1Pos = player.position,
                            TeamName1 = player.Team.Name, // Or CurrentBallHolder.Team.Name if player object has it

                            //PlayerName2 = CurrentBallHolder.fullName,
                            //Player2Pos = CurrentBallHolder.position,
                            TeamName2 = DefendingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
                            Zone1 = CurrentBallZone,
                            TrappedBall = true,

                        });
                        SetPossession(player, CurrentBallZone, player.Team);
                    }
                    else
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
                            EventType = MatchEventType.PlayerMoved, // Use this event type
                            Timestamp = DateTime.Now, // Always include for precise timing

                            PlayerName1 = player.fullName,
                            Player1Pos = player.position,
                            TeamName1 = player.Team.Name, // Or CurrentBallHolder.Team.Name if player object has it

                            //PlayerName2 = CurrentBallHolder.fullName,
                            //Player2Pos = CurrentBallHolder.position,
                            TeamName2 = DefendingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
                            Zone1 = CurrentBallZone,
                            FailedTrapped = true,

                        });
                        SetLooseBall(false, player, CornerDeliveryType.None, AttackingTeam, DefendingTeam, false, false, false);
                    }
                    AerialBattlePending = false;
                    return;
                }
            }

            // Temporarily store the best targets *before* the loop, as the loop itself
            // only determines the *action* and its score, not the specific target for passes/crosses.
            // The GetBest...OpportunityScore methods don't directly set these, so we need to do it here
            // or within GetBest...OpportunityScore methods if they return a tuple (Player, double).
            // For simplicity, we'll run a quick check again to set them *after* the decision.

            // Find the best action based on scores
            foreach (var entry in actionScores)
            {
                double scoreWithRandomness = entry.Value + Dice.d10();

                if (scoreWithRandomness > highestScore)
                {
                    highestScore = scoreWithRandomness;
                    bestAction = entry.Key;
                }
            }

            bool isHeader = AerialBattlePending;

            if (bestAction != "Shoot")
            {
                ResetRebounds(); // whatever happened, the attacker decided not to immediately rebound. Or wasn't in a rebound
                // opportunity in the first place.
            }

            // Execute the chosen action, calling YOUR existing methods
            switch (bestAction)
            {
                case "Shoot":
                    Enums.ShotType st = ShotType.Normal;
                    if (AerialBattlePending)
                    {
                        double volleyChance = (player.trueRating.FinishingForGameCalculations * 0.4 +
                                           player.trueRating.VolleysForGameCalculations * 0.4 +
                                           player.trueRating.BallControlForGameCalculations * 0.2);

                        double qualityInfluence = 49;
                        volleyChance += (50 - qualityInfluence) * 0.2;
                        volleyChance = Math.Max(10, Math.Min(70, volleyChance));

                        if (Dice.d100() < volleyChance)
                        {
                            st = Enums.ShotType.Volley;
                        }
                        else
                        {
                            st = ShotType.Header;
                        }
                    }
                    AerialBattlePending = false;
                    AttemptShot(player, attackingTeam, defendingTeam, st, false, _lastPasser); // Uses existing 'lastPasser'
                    break;
                case "Dribble":
                    AttemptDribble(player, attackingTeam, defendingTeam);
                    break;
                case "Short Pass":
                    Enums.MatchState previousMatchStateSP = CurrentMatchState;
                    // Now, find the actual target for the chosen pass type and store it
                    _lastChosenPassTarget = FindSpecificPassTarget(player, Enums.PassType.Short, currentZone, attackingTeam, defendingTeam);
                    AerialBattlePending = false;
                    Enums.PassOutcome passOutcomeShort = AttemptPass(player, attackingTeam, defendingTeam, Enums.PassType.Short, _lastChosenPassTarget, false, false, false, false, isHeader); // Ensure AttemptPass accepts target
                    if (previousMatchStateSP == CurrentMatchState)
                        ConvertPassResultToMatchCondition(passOutcomeShort, player);
                    break;
                case "Long Pass":
                    Enums.MatchState previousMatchStateLP = CurrentMatchState;
                    _lastChosenPassTarget = FindSpecificPassTarget(player, Enums.PassType.Long, currentZone, attackingTeam, defendingTeam);
                    AerialBattlePending = false;
                    Enums.PassOutcome passOutcomeLong = AttemptPass(player, attackingTeam, defendingTeam, Enums.PassType.Long, _lastChosenPassTarget, false, false, false, false, isHeader); // Ensure AttemptPass accepts target
                    if (previousMatchStateLP == CurrentMatchState)
                        ConvertPassResultToMatchCondition(passOutcomeLong, player, true);
                    break;
                case "Clear":
                    AerialBattlePending = false;
                    AttemptClear(player, attackingTeam, defendingTeam, currentZone, isHeader);
                    break;
                case "Cross":
                    // Now, find the actual target for the chosen cross
                    _lastChosenCrossTarget = FindSpecificCrossTarget(player, currentZone, attackingTeam, defendingTeam);
                    Enums.CrossOutcome crossOutcome = ProcessCrossAttempt(CurrentBallHolder, attackingTeam, defendingTeam, _lastChosenCrossTarget);
                    break;
                default:
                    throw new Exception(string.Format("ERROR: Player decision resulted in unknown action '{0}'. Defaulting to Dribble.", bestAction));
            }

            if (CurrentBallHolder != null)
            {
                if (CurrentBallHolder.ID == idOfPlayerGoingIntoPossession)
                {
                    if (CurrentBallZone != CurrentBallHolder.CurrentZone)
                    {
                        int x = 0;
                        string s = bestAction;
                    }
                }
            }
        }

        private String DetermineCurrentTime()
        {
            int secondHalfTotalTime = this.minutesPerHalf * 2;
            int extraTimeHalfOne = secondHalfTotalTime + 15;
            int extraTimeHalfTwo = extraTimeHalfOne + 15;
            int maxMinutes = this.minutesPlayed;
            if (halfNumber == 1)
                maxMinutes = this.minutesPerHalf;
            if (halfNumber == 2)
                maxMinutes = secondHalfTotalTime;
            if (halfNumber == 3)
                maxMinutes = extraTimeHalfOne;
            if (halfNumber == 4)
                maxMinutes = extraTimeHalfTwo;
            if (halfNumber > 4)
                return "PK";

            if (this.minutesPlayed > maxMinutes)
                return maxMinutes.ToString() + "+" + (this.minutesPlayed - maxMinutes);
            else
                return this.minutesPlayed.ToString();
        }

        private void ClockTick(int timePassed)
        {
            this.minutesPlayed += timePassed;
            NotifyTimeTicked(DetermineCurrentTime());
        }

