        // Helper method to set possession
        private void SetPossession(Player newHolder, Enums.PitchZone newZone, Team newAttackingTeam)
        {
            // First, handle the previous possessing team (if any)
            if (AttackingTeam == newAttackingTeam)
            {
                AttackingTeam.justWonPossessionFlag = false; // The old attacking team no longer just won possession
                AttackingTeam.possessionCounter = 0;        // Reset their counter
            }
            else
            {
                newAttackingTeam.justWonPossessionFlag = true;
                newAttackingTeam.possessionCounter = 0; // Reset counter for the new team as they've just gained it
                                                        // Optional: ShowMessage($"Possession set to {newAttackingTeam.Name} (just won possession).");
            }

            //// Now, set the flag for the *new* attacking team if they've truly gained possession
            //// and weren't already the attacking team.
            //// This check ensures the flag is only set on a *change* of possession.
            //if (newAttackingTeam != null && newAttackingTeam != AttackingTeam) // CORRECTED: newAttackingTeam here
            //{
            //}

            CurrentBallHolder = newHolder;
            CurrentBallZone = newZone;
            newHolder.CurrentZone = newZone;
            AttackingTeam = newAttackingTeam; // This is the new attacking team reference
            DefendingTeam = (AttackingTeam == HomeTeam) ? AwayTeam : HomeTeam; // Update defending team

            if (newAttackingTeam.justWonPossessionFlag)
            {
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
                    EventType = MatchEventType.BallPossessionChanged, // Use this event type
                    Timestamp = DateTime.Now, // Always include for precise timing

                    PlayerName1 = newHolder.fullName,
                    Player1Pos = newHolder.position,
                    TeamName1 = AttackingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it

                    //PlayerName2 = CurrentBallHolder.fullName,
                    //Player2Pos = CurrentBallHolder.position,
                    TeamName2 = DefendingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
                    Zone1 = CurrentBallZone,

                    // You could optionally add a boolean attribute to MatchEntry like 'IsDribbling'
                    // if you want to explicitly state the nature of the possession.
                    // E.g., IsDribbling = true;
                });
            }

            this.CleanPotentialChanceCreatingActions(CurrentSecond);
            this.attackingTeamIsHomeTeam = (AttackingTeam == HomeTeam);

            if (newHolder.position == Positions.Goalkeeper)
            {
                if (CurrentMatchState != MatchState.GoalKick)
                    CurrentMatchState = MatchState.GoalkeeperRecycle;
            }

            //LogEntry(new MatchEntry
            //{
            //    Level = LogLevel.Info, // You might consider Debug or Trace for very frequent possession updates
            //    EventType = MatchEventType.BallPossessionChanged, // Use this event type
            //    Timestamp = DateTime.Now, // Always include for precise timing

            //    PlayerName1 = CurrentBallHolder.fullName,
            //    Player1Pos = CurrentBallHolder.position,
            //    TeamName1 = AttackingTeam.Name, // Or CurrentBallHolder.Team.Name if player object has it
            //    Zone1 = CurrentBallZone,

            //    // You could optionally add a boolean attribute to MatchEntry like 'IsDribbling'
            //    // if you want to explicitly state the nature of the possession.
            //    // E.g., IsDribbling = true;
            //});
            // If the same team keeps possession, we should still increment their counter
            // However, the counter reset (possessionCounter = 0) upon gaining possession
            // ensures the flag is reset after a few ticks in your game loop if they
            // continue to hold it without losing and regaining.
        }

        private void CleanupTemporaryPlayerStates()
        {
            foreach (var player in HomeTeam.AvailableOnFieldPlayers.Concat(AwayTeam.AvailableOnFieldPlayers)) // Clean up ALL players on both teams
            {
                player.OffensiveSetPieceRole = Enums.SetPieceRole.None;
                player.DefensiveSetPieceRole = Enums.SetPieceRole.None; // Ensure defensive roles are also reset
                player.MarkedOpponent = null;
                player.SimulatedSetPieceZone = Enums.PitchZone.None; // Reset this here
            }
        }

