        /// <summary>
        /// Simulates a player attempting a pass to a teammate.
        /// </summary>
        /// <param name="passer">The player attempting the pass.</param>
        /// <param name="attackingTeam">The team in possession.</param>a
        /// <param name="defendingTeam">The team without possession.</param>
        /// <param name="passType">The type of pass (Short, Long, Cross, Through).</param> // Added Through
        /// <param name="targetPlayer">The specific player identified as the best target for the pass.</param>
        /// <param name="isSetPiece">True if the pass originates from a set piece (e.g., corner, free kick).</param>
        /// <returns>The outcome of the pass attempt.</returns>
        public Enums.PassOutcome AttemptPass(Player passer, Team attackingTeam, Team defendingTeam, Enums.PassType passType, Player targetPlayer, bool isSetPiece = false,
                                                 bool isFixedPositionSetPiece = false, bool isFreeKick = false, bool isCorner = false,
                                                 bool isHeader = false)
        {
            bool isThrowIn = CurrentMatchState == Enums.MatchState.ThrowIn;
            bool isHighBall = (passType == Enums.PassType.Long || passType == Enums.PassType.Cross);
            bool gkKick = (CurrentMatchState == MatchState.GoalKick) || (CurrentMatchState == MatchState.GoalkeeperRecycle);

            // --- Handling the case where targetPlayer is invalid/null ---
            if (targetPlayer == null || targetPlayer.isSentOff || targetPlayer == passer)
            {
                throw new Exception("Why are you passing to an empty target player?");
            }

            if (!passer.IsInjured && !passer.isSentOff)
            {
                passer.DecreaseCondition(passType == Enums.PassType.Short ? 0.3 : 0.6);
            }

            // Determine the effective zones for passer and target for calculations
            Enums.PitchZone effectivePasserZone;
            Enums.PitchZone effectiveTargetZone;
            if (isFixedPositionSetPiece)
            {
                effectivePasserZone = passer.CurrentZone;
                effectiveTargetZone = targetPlayer.CurrentZone;
            }
            else if (isSetPiece)
            {
                effectivePasserZone = passer.SimulatedSetPieceZone;
                effectiveTargetZone = targetPlayer.SimulatedSetPieceZone;
            }
            else
            {
                effectivePasserZone = passer.CurrentZone;
                effectiveTargetZone = targetPlayer.CurrentZone;
            }

            // --- STEP 3: OFFSIDE CHECK (After target is chosen, but before pass outcome) ---
            Enums.PitchZone ballPlayedZone;
            if (isFixedPositionSetPiece)
            {
                ballPlayedZone = passer.CurrentZone;
            }
            else if (isSetPiece)
            {
                ballPlayedZone = passer.SimulatedSetPieceZone;
            }
            else
            {
                ballPlayedZone = passer.CurrentZone;
            }

            // 4. Calculate Pass Success Chance
            double passSuccessChance = passer.trueRating.ShortPassForGameCalculations;
            PassStyleType pt = PassStyleType.GroundPass;
            if (isThrowIn)
            {
                if (passType == PassType.Short)
                {
                    pt = PassStyleType.ShortThrowIn;
                }
                else
                {
                    passSuccessChance -= 20;
                    pt = PassStyleType.LongThrowIn;
                }
            }
            else if (isCorner)
            {
                passSuccessChance = passer.trueRating.ShortPassForGameCalculations;
                pt = PassStyleType.ShortCorner;
            }
            else if (passType == PassType.Long)
            {
                passSuccessChance = passer.trueRating.LongPassForGameCalculations;
                pt = PassStyleType.Lob;
            }
            else if (isHeader)
            {
                passSuccessChance = passer.trueRating.HeaderForGameCalculations;
                passSuccessChance -= 5;
                pt = PassStyleType.HeaderPass;
            }
            int distance = (int)CalculateDistance(effectivePasserZone, effectiveTargetZone); // Cast to int
            if (passType == Enums.PassType.Short)
            {
                if (distance > 0)
                    passSuccessChance -= Math.Pow(1.5, distance - 1);
            }
            else // Long pass, Cross, Through
            {
                passSuccessChance -= (distance * 1.5);
            }

            passSuccessChance += passer.trueRating.VisionForGameCalculations * 0.3;

            if (CheckForOffside(passer, targetPlayer, ballPlayedZone, isSetPiece, currentBall: effectiveTargetZone, receiverZoneForCheckOverride: effectiveTargetZone) && !isThrowIn)
            {
                targetPlayer.gameStats.offsides++;
                AttackingTeam.gameStats.offsides++;

                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = passer.fullName,
                    Player1Pos = passer.position,
                    TeamName1 = AttackingTeam.Name,
                    PlayerName2 = targetPlayer.fullName,
                    Player2Pos = targetPlayer.position,
                    PassResult = PassResultType.Completed,
                    Zone1 = passer.CurrentZone,
                    Zone2 = targetPlayer.CurrentZone,
                    PassStyle = pt,

                    IsCorner = isCorner,
                    // Set the appropriate boolean flag for the set piece type
                    IsFreeKick = isFreeKick, // Or IsCorner = true, depending on the context
                                             // You should set only one of these to true, or add logic to determine which it is.
                    IsHeader = isHeader,
                    // IMPORTANT: You'll also need to set the PassResult based on the actual outcome of the pass.
                    // For example:
                    // PassResult = PassResultType.Completed,
                    // PassResult = PassResultType.Intercepted,
                    // PassResult = PassResultType.FailedOutOfPlay,
                });

                CheckForChanceNegation(targetPlayer.Team, CurrentSecond, negatingPlayer: null, majorOffensiveErrorOccurred: true);

                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.OffsideCalled,
                    PlayerName1 = passer.fullName,
                    PlayerName2 = targetPlayer.fullName,
                    Player1Pos = passer.position,
                    Player2Pos = targetPlayer.position,
                    TeamName1 = AttackingTeam.Name,
                    Timestamp = DateTime.Now,
                    PassStyle = pt,
                    IsOffsideTrap = (defendingTeam.CurrentDefensiveLineDepth == DefensiveLineDepth.OffsideTrap)
                });

                this.PassStatsResolve(passer, false, CurrentSecond, isSetPiece, isHeader, gkKick);
                return Enums.PassOutcome.Offside;
            }

            Enums.Flank passerFlank = GetFlankOfZone(effectivePasserZone);

            if (effectivePasserZone == Enums.PitchZone.PenaltyArea_Home || effectivePasserZone == Enums.PitchZone.PenaltyArea_Away)
            {
                passSuccessChance -= 10;
            }

            if (passerFlank != Enums.Flank.Center)
            {
                passSuccessChance -= 3;
            }

            if (isSetPiece)
            {
                passSuccessChance += 10;
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Debug, // Keeping the Debug level as specified
                    EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = passer.fullName,
                    Player1Pos = passer.position,
                    TeamName1 = AttackingTeam.Name,

                    // Set the appropriate boolean flag for the set piece type
                    IsFreeKick = true, // Or IsCorner = true, depending on the context
                                       // You should set only one of these to true, or add logic to determine which it is.

                    // Map the pass success chance to a generic numeric value field
                    Value1 = passSuccessChance,

                    // IMPORTANT: You'll also need to set the PassResult based on the actual outcome of the pass.
                    // For example:
                    // PassResult = PassResultType.Completed,
                    // PassResult = PassResultType.Intercepted,
                    // PassResult = PassResultType.FailedOutOfPlay,
                });
            }

            int passUnderPressureValue = 0;
            int receiverUnderPressureValue = 0;

            // Defensive pressure around passer
            Player nearestDefenderToPasser = FindNearestDefender(passer, defendingTeam, passer.CurrentZone);
            if (nearestDefenderToPasser != null && !nearestDefenderToPasser.IsInjured && !nearestDefenderToPasser.isSentOff)
            {
                double distanceToPasser = CalculateDistance(passer.CurrentZone, nearestDefenderToPasser.CurrentZone);
                if (distanceToPasser <= 1 && !isSetPiece)
                {
                    double defenderInfluence = (nearestDefenderToPasser.trueRating.DefenseAwarenessForGameCalculations * 0.5) +
                                               (nearestDefenderToPasser.trueRating.StandTackleForGameCalculations * 0.5);
                    passSuccessChance -= (defenderInfluence / 8.0);
                    passUnderPressureValue = 50;
                }
            }

            // Adjustments based on pass type specific difficulty
            switch (passType)
            {
                case Enums.PassType.Cross:
                    passSuccessChance -= 15;
                    passSuccessChance += passer.trueRating.CrossingForGameCalculations * 0.2;
                    break;
                case Enums.PassType.ThroughBall:
                    passSuccessChance -= 10;
                    passSuccessChance += passer.trueRating.VisionForGameCalculations * 0.1;
                    break;
            }

            // Defensive pressure around target player
            Player nearestDefenderToTarget = FindNearestDefender(targetPlayer, defendingTeam, effectiveTargetZone);
            if (nearestDefenderToTarget != null && !nearestDefenderToTarget.IsInjured && !nearestDefenderToTarget.isSentOff)
            {
                double distanceToTarget = CalculateDistance(effectiveTargetZone, nearestDefenderToTarget.CurrentZone);
                if (distanceToTarget <= 1)
                {
                    double defenderInfluence = (nearestDefenderToTarget.trueRating.DefenseAwarenessForGameCalculations * 0.5) +
                                               (nearestDefenderToTarget.trueRating.InterceptForGameCalculations * 0.5);
                    passSuccessChance -= (defenderInfluence / 10.0);
                    receiverUnderPressureValue = 50;
                }
            }
            if (passType == Enums.PassType.Short)
            {
                if (distance > 0)
                    passSuccessChance -= Math.Pow(1.5, distance - 1);
                passSuccessChance += 10;
            }

            passSuccessChance = Math.Max(10, Math.Min(100, passSuccessChance));

            // 5. Determine Pass Outcome
            int passRoll = Dice.d100();
            this.PassStatsResolve(passer, passRoll < passSuccessChance, CurrentSecond, isSetPiece, isHeader, gkKick);

            if (passRoll < passSuccessChance) // Pass successful
            {
                // Pass successful. Now, handle specific pass types or contests.

                bool isPotentialThroughBall = (passType == Enums.PassType.ThroughBall ||
                                               (passType == Enums.PassType.Long &&
                                                (targetPlayer.Position == Enums.Positions.Striker || targetPlayer.Position == Enums.Positions.CentralAttackingMidfielder) && // Changed to CAM as ST/CAM are common through ball targets
                                                IsBallInAttackingHalf(effectiveTargetZone, attackingTeam) && // Use effectiveTargetZone
                                                IsZoneInOpponentPenaltyArea(effectiveTargetZone, attackingTeam))); // Use effectiveTargetZone

                if (isPotentialThroughBall)
                {
                    pt = PassStyleType.ThroughBall;
                    // ProcessThroughBall needs to know if it's a set piece or not, as it may influence how it searches for defenders etc.
                    if (ProcessThroughBall(passer, targetPlayer, attackingTeam, defendingTeam, effectiveTargetZone, isSetPiece))
                    {
                        return Enums.PassOutcome.Successful;
                    }
                    else
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            PlayerName1 = passer.fullName,
                            PlayerName2 = targetPlayer.fullName,
                            Player1Pos = passer.position,
                            Player2Pos = targetPlayer.position,
                            TeamName1 = AttackingTeam.Name,
                            PassResult = PassResultType.FailedToTeammate,

                            PassStyle = pt,
                            Value1 = passUnderPressureValue,
                            Value2 = receiverUnderPressureValue,
                            Zone1 = passer.CurrentZone,
                            Zone2 = targetPlayer.CurrentZone
                        });
                        SetLooseBall(false, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                        return Enums.PassOutcome.LooseBall;
                    }
                }
                else if (passType == Enums.PassType.Long && nearestDefenderToTarget != null &&
                         CalculateDistance(effectiveTargetZone, nearestDefenderToTarget.CurrentZone) <= 1) // Use effectiveTargetZone for distance
                {
                    pt = PassStyleType.Lob;
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = passer.fullName,
                        PlayerName2 = targetPlayer.fullName,
                        Player1Pos = passer.position,
                        Player2Pos = targetPlayer.position,
                        TeamName1 = AttackingTeam.Name,

                        PassStyle = pt,
                        Value1 = passUnderPressureValue,
                        Value2 = receiverUnderPressureValue,
                        Zone1 = passer.CurrentZone,
                        Zone2 = targetPlayer.CurrentZone
                    });
                    // Pass effectiveTargetZone to SimulateAerialContest as the contested zone
                    Enums.AerialContestOutcome aerialOutcome = SimulateAerialContest(targetPlayer, nearestDefenderToTarget, attackingTeam, defendingTeam, effectiveTargetZone, isSetPiece);

                    // Determine if the aerial contest originated from a Free Kick or a Corner
                    // You'll need specific logic here, as 'isSetPiece' is generic.
                    bool isFreeKickSource = isSetPiece && isFreeKick;
                    bool isCornerSource = isSetPiece && isCorner;

                    switch (aerialOutcome)
                    {
                        case Enums.AerialContestOutcome.Player1Wins:
                            // Target Player (attacking team) wins the header
                            this.PassStatsResolve(passer, true, CurrentSecond, isSetPiece, isHeader, gkKick); // Your internal stats logic
                            SetPossession(targetPlayer, effectiveTargetZone, attackingTeam); // Your internal possession logic
                            AerialBattlePending = true;
                            //ShowMessage(string.Format("{0} wins the header and receives the ball!", targetPlayer.fullName));
                            return Enums.PassOutcome.Successful; // This is your internal game logic return value

                        case Enums.AerialContestOutcome.Player2Wins:
                            // Defender wins the header 
                            this.PassStatsResolve(passer, false, CurrentSecond, isSetPiece, isHeader, gkKick); // Your internal stats logic
                            SetPossession(nearestDefenderToTarget, nearestDefenderToTarget.CurrentZone, defendingTeam); // Your internal possession logic
                            AerialBattlePending = true;
                            // ShowMessage(string.Format("{0} wins the header and clears/intercepts the pass!", nearestDefenderToTarget.fullName));
                            return Enums.PassOutcome.Intercepted; // Your internal game logic return value

                        case Enums.AerialContestOutcome.LooseBall:
                            // Neither player wins, ball becomes loose
                            this.PassStatsResolve(passer, false, CurrentSecond, isSetPiece, isHeader, gkKick); // Your internal stats logic
                            SetLooseBall(false, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                            // ShowMessage("The aerial contest results in a loose ball!");
                            return Enums.PassOutcome.LooseBall; // Your internal game logic return value

                        case Enums.AerialContestOutcome.FoulOccurred: // A foul happened during the aerial contest
                            // ShowMessage("Foul occurred during aerial contest!");
                            // You'll need to determine which player committed the foul and which player was fouled.
                            // Assuming 'nearestDefenderToTarget' committed the foul on 'targetPlayer' for this example.
                            return Enums.PassOutcome.FoulInAerialContest; // Your internal game logic return value
                    }
                }
                else if (passType == Enums.PassType.Cross)
                {
                    pt = PassStyleType.Cross;
                    // ProcessCrossAttempt will handle the outcome and update state. It already receives isSetPiece.
                    Enums.CrossOutcome crossResult = ProcessCrossAttempt(passer, attackingTeam, defendingTeam, targetPlayer, isSetPiece);
                    if (crossResult == Enums.CrossOutcome.OutOfPlay)
                    {
                        return Enums.PassOutcome.OutOfBounds;
                    }

                    switch (crossResult)
                    {
                        case Enums.CrossOutcome.GoalFromCross:
                        case Enums.CrossOutcome.ShotAttempted:
                            return Enums.PassOutcome.Successful;
                        case Enums.CrossOutcome.CaughtByGK:
                        case Enums.CrossOutcome.PunchedClearByGK:
                        case Enums.CrossOutcome.PunchedToOpponent:
                        case Enums.CrossOutcome.Defended:
                            // If the cross was defended, intercepted, or handled by GK, it's still a "successful" delivery in terms of reaching its target area,
                            // but the outcome isn't necessarily possession retention. Consider a more nuanced PassOutcome if needed.
                            return Enums.PassOutcome.Intercepted;
                        case Enums.CrossOutcome.LooseBall:
                            return Enums.PassOutcome.LooseBall;
                        case Enums.CrossOutcome.FoulByGK:
                        case Enums.CrossOutcome.FreeKickAwarded:
                            return Enums.PassOutcome.FoulInAerialContest;
                        case CrossOutcome.OutOfPlay:
                            break;
                        case Enums.CrossOutcome.CrossMissed:
                        default:
                            return Enums.PassOutcome.LostPossession;
                    }
                }
                else // Standard successful pass
                {
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = passer.fullName,
                        PlayerName2 = targetPlayer.fullName,
                        Player1Pos = passer.position,
                        Player2Pos = targetPlayer.position,
                        TeamName1 = AttackingTeam.Name,

                        PassResult = PassResultType.Completed,
                        PassStyle = pt,
                        Value1 = passUnderPressureValue,
                        Value2 = receiverUnderPressureValue,
                        Zone1 = passer.CurrentZone,
                        Zone2 = targetPlayer.CurrentZone
                    });

                    this.PassStatsResolve(passer, true, CurrentSecond, isSetPiece, isHeader, gkKick);
                    SetPossession(targetPlayer, effectiveTargetZone, attackingTeam); // Set possession to effective target zone
                    return Enums.PassOutcome.Successful;
                }
            }
            else // Pass failed
            {
                this.PassStatsResolve(passer, false, CurrentSecond, isSetPiece, isHeader, gkKick);
                int failureRoll = Dice.d100();
                Player interceptorCandidate = FindNearestDefender(targetPlayer, defendingTeam, effectiveTargetZone); // Find interceptor near target's effective zone

                if (interceptorCandidate != null && !interceptorCandidate.IsInjured && !interceptorCandidate.isSentOff && failureRoll < 60)
                {
                    interceptorCandidate.gameStats.Interceptions++;
                    this.CheckForErrorNegation(interceptorCandidate, CurrentSecond);

                    if (IsZoneDangerous(effectivePasserZone, attackingTeam == HomeTeam)) // Use effectivePasserZone for passer's danger check
                    {
                        _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(passer, CurrentSecond));
                    }
                    if (interceptorCandidate.position == Positions.Goalkeeper)
                    {
                        CurrentMatchState = MatchState.GoalkeeperRecycle;
                    }
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = passer.fullName,
                        PlayerName2 = interceptorCandidate.fullName,
                        Player1Pos = passer.position,
                        Player2Pos = interceptorCandidate.position,
                        TeamName1 = AttackingTeam.Name,

                        PassResult = PassResultType.Intercepted,
                        PassStyle = pt,
                        Value1 = passUnderPressureValue,
                        Value2 = receiverUnderPressureValue,
                        Zone1 = passer.CurrentZone,
                        Zone2 = targetPlayer.CurrentZone
                    });

                    SetPossession(interceptorCandidate, interceptorCandidate.CurrentZone, defendingTeam);
                    return Enums.PassOutcome.Intercepted;
                }
                else if (failureRoll < 85)
                {
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = passer.fullName,
                        PlayerName2 = targetPlayer.fullName,
                        Player1Pos = passer.position,
                        Player2Pos = targetPlayer.position,
                        TeamName1 = AttackingTeam.Name,

                        PassResult = PassResultType.FailedToTeammate,
                        PassStyle = pt,
                        Value1 = passUnderPressureValue,
                        Value2 = receiverUnderPressureValue,
                        Zone1 = passer.CurrentZone,
                        Zone2 = targetPlayer.CurrentZone
                    });
                    SetLooseBall(false, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                    return Enums.PassOutcome.LooseBall;
                }
                else // Failed pass, not intercepted immediately, either loose or out of bounds
                {
                    Enums.PitchZone predictedExitZone;
                    if (passType == Enums.PassType.Short)
                    {
                        predictedExitZone = DetermineRealisticFailedShortPassExitZone(passer.CurrentZone, targetPlayer.CurrentZone, attackingTeam);
                    }
                    else // Long pass, Through Ball, Cross (if not handled by ProcessCrossAttempt for successful crosses)
                    {
                        predictedExitZone = DetermineRealisticFailedLongPassExitZone(passer.CurrentZone, targetPlayer.CurrentZone, attackingTeam);
                    }

                    if (CanBeOutOfBounds(predictedExitZone))
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            PlayerName1 = passer.fullName,
                            PlayerName2 = targetPlayer.fullName,
                            Player1Pos = passer.position,
                            Player2Pos = targetPlayer.position,
                            TeamName1 = AttackingTeam.Name,

                            PassResult = PassResultType.FailedOutOfPlay,
                            PassStyle = pt,
                            Value1 = passUnderPressureValue,
                            Value2 = receiverUnderPressureValue,
                            Zone1 = passer.CurrentZone,
                            Zone2 = targetPlayer.CurrentZone
                        });
                        this.SetMatchStateForOutOfBounds(predictedExitZone, passer.Team);
                        return Enums.PassOutcome.OutOfBounds;
                    }
                    else
                    {
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            PlayerName1 = passer.fullName,
                            PlayerName2 = targetPlayer.fullName,
                            Player1Pos = passer.position,
                            Player2Pos = targetPlayer.position,
                            TeamName1 = AttackingTeam.Name,

                            PassResult = PassResultType.FailedToTeammate,
                            PassStyle = pt,
                            Value1 = passUnderPressureValue,
                            Value2 = receiverUnderPressureValue,
                            Zone1 = CurrentBallZone,
                            Zone2 = targetPlayer.CurrentZone
                        });
                        CurrentBallZone = predictedExitZone; // Set ball zone to where it went loose
                        SetLooseBall(isHighBall, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                        return Enums.PassOutcome.LooseBall;
                    }
                }
            }
            SetLooseBall(false, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
            return Enums.PassOutcome.LooseBall;
        }

        public Player FindAssister(Player shooter, int CurrentSecond)
        {
            if (ReboundChance)
                return null; // nobody gets credit for assists on rebounds.

            for (int i = _potentialChanceCreatingActions.Count - 1; i >= 0; i--)
            {
                var action = _potentialChanceCreatingActions[i];
                Player potentialAssister = action.Item1;
                int actionTimestamp = action.Item2;

                // Check if the action is outside the time window
                if (CurrentSecond - actionTimestamp > CHANCE_CREATED_TIME_WINDOW_SECONDS)
                {
                    // Remove outdated actions
                    _potentialChanceCreatingActions.RemoveAt(i);
                    continue;
                }

                // Check if it's a valid assist
                if (potentialAssister != shooter && potentialAssister == _lastPasser)
                {
                    return potentialAssister;
                }
            }

            return null; // No valid assister found
        }

        private Player FindSpecificPassTarget(Player passingPlayer, Enums.PassType passType, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("FindSpecificPassTarget: passingPlayer:{0},passType:{1},ballZone:{2}," +
            //    "attackingTeam:{3},defendingTeam:{4}", passingPlayer.position, passType, ballZone,
            //    attackingTeam.Name, defendingTeam.Name));


            double maxScore = -9999;
            Player bestTarget = null;
            foreach (Player potentialTarget in attackingTeam.AvailableOnFieldOutfielders.Where(p => p != passingPlayer))
            {
                double currentScore = CalculatePassOpportunity(passingPlayer, potentialTarget, passType, ballZone, attackingTeam, defendingTeam);
                if (currentScore > maxScore)
                {
                    maxScore = currentScore;
                    bestTarget = potentialTarget;
                }
            }
            return bestTarget;
        }

        /// <summary>
        /// Finds the best pass opportunity (score and target) for a given player and pass type.
        /// </summary>
        /// <returns>The highest score found for the given pass type.</returns>
        private double GetBestPassOpportunityScore(Player passingPlayer, Enums.PassType passType, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(
            //    string.Format(
            //        "GetBestPassOpportunityScore: passingPlayer:{0},passType:{1},ballZone:{2} attackingTeam:{3},defendingTeam:{4}",
            //        passingPlayer.position,
            //        passType.ToString(),
            //        ballZone.ToString(),
            //        attackingTeam.Name,
            //        defendingTeam.Name
            //    ));


            double maxScore = -9999;
            Player currentBestTarget = null;

            foreach (Player potentialTarget in attackingTeam.AvailableOnFieldPlayers)
            {
                // A player cannot pass to themselves
                if (potentialTarget == passingPlayer) continue;

                double currentScore = CalculatePassOpportunity(passingPlayer, potentialTarget, passType, ballZone, attackingTeam, defendingTeam);

                if (currentScore > maxScore)
                {
                    maxScore = currentScore;
                    currentBestTarget = potentialTarget;
                }
            }

            // Store the best target found for this specific pass type decision
            return maxScore;
        }

        public Enums.PitchZone GetIdealThroughBallReceivingZone(Player targetPlayer, Team defendingTeam, bool isHomeTeamAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetIdealThroughBallReceivingZone: targetPlayer:{0},defendingTeam:{1}," +
            //    "isHomeTeamAttacking:{2}",
            //    targetPlayer.position, defendingTeam.Name));

            Enums.PitchZone currentZone = targetPlayer.CurrentZone;
            Enums.PitchZone idealZone = currentZone; // Default to current zone if no better found

            // Use the pre-computed forward neighbors map
            List<Enums.PitchZone> potentialThroughBallZones = GetForwardNeighborZones(currentZone);

            double bestScore = -1.0;

            foreach (Enums.PitchZone potentialZone in potentialThroughBallZones)
            {
                double currentZoneScore = 0;

                // Use the optimized CountDefendersInZone
                int defendersInZone = CountDefendersInZone(potentialZone, defendingTeam);

                if (defendersInZone == 0)
                {
                    currentZoneScore += 50; // Big bonus for empty zone
                }
                else if (defendersInZone < 2)
                {
                    currentZoneScore += 20;
                }
                else
                {
                    currentZoneScore -= 100; // Heavy penalty
                }

                int zoneForwardValue = GetZoneForwardValue(potentialZone, isHomeTeamAttacking);
                currentZoneScore += (zoneForwardValue - GetZoneForwardValue(currentZone, isHomeTeamAttacking)) * 10;

                // Player attributes help them receive in challenging situations
                currentZoneScore += targetPlayer.trueRating.PositioningForGameCalculations * 0.5;
                // Assuming you have OffTheBall:
                // currentZoneScore += targetPlayer.trueRating.OffTheBallForGameCalculations * 0.5;

                // Consider defender proximity to this specific zone
                // This is still a conceptual check, but using the _defendersInZoneMap makes it fast.
                bool defenderTooCloseToPotentialZone = false;
                if (_defendersInZoneMap.TryGetValue(potentialZone, out List<Player> currentZoneDefenders))
                {
                    foreach (Player defenderInZone in currentZoneDefenders)
                    {
                        if (GetZoneDistance(potentialZone, defenderInZone.CurrentZone, isHomeTeamAttacking) < 2) // Defender close to or in the zone
                        {
                            defenderTooCloseToPotentialZone = true;
                            break;
                        }
                    }
                }

                if (defenderTooCloseToPotentialZone)
                {
                    currentZoneScore -= 50; // Penalty if defenders are too close
                }

                // Prioritize more dangerous attacking zones
                if (potentialZone == GetOpponentPenaltyAreaForTeam(AttackingTeam) ||
                    potentialZone == GetAttackingCentralZoneForTeam(AttackingTeam))
                {
                    currentZoneScore += 30; // Bonus for dangerous areas
                }

                if (currentZoneScore > bestScore)
                {
                    bestScore = currentZoneScore;
                    idealZone = potentialZone;
                }
            }

            // If no good forward zone found, stick to current. You might also return Enums.PitchZone.None if preferred.
            if (bestScore < 0 && idealZone == currentZone)
            {
                return currentZone;
            }

            return idealZone;
        }

        /// <summary>
        /// Simulates a through ball attempt, aiming to put a player in a dangerous position (potentially 1v1).
        /// This method should be called from AttemptPass if the pass is classified as a through ball.
        /// </summary>
        /// <param name="passer">The player attempting the through ball.</param>
        /// <param name="receiver">The intended recipient of the through ball.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="targetZone">The zone where the through ball is aimed to land/be received.</param>
        /// <returns>True if the through ball creates a 1v1 which is then processed, false if it's intercepted, loose, or just good possession.</returns>
        private bool ProcessThroughBall(Player passer, Player receiver, Team attackingTeam, Team defendingTeam, Enums.PitchZone targetZone, bool isSetPiece)
        {
            // Base success chance based on passer and receiver attributes
            double throughBallSuccessChance = (passer.trueRating.PassingForGameCalculations * 0.3) +
                                              (passer.trueRating.VisionForGameCalculations * 0.3) +
                                              (passer.trueRating.AgilityForGameCalculations * 0.15) + // Creativity to spot the pass
                                              (receiver.trueRating.PositioningForGameCalculations * 0.1) + // Receiver's general positioning
                                              (receiver.trueRating.SprintForGameCalculations * 0.15); // Receiver's ability to make attacking runs

            // Factor in defensive line awareness, pace, defending, and tackling of nearest defenders
            Player nearestDefenderToReceiver = FindNearestDefender(receiver, defendingTeam, targetZone);
            if (nearestDefenderToReceiver != null)
            {
                throughBallSuccessChance -= nearestDefenderToReceiver.trueRating.DefenseAwarenessForGameCalculations * 0.15;
                throughBallSuccessChance -= nearestDefenderToReceiver.trueRating.PaceForGameCalculations * 0.05;
                throughBallSuccessChance -= nearestDefenderToReceiver.trueRating.DefendingForGameCalculations * 0.1;
                throughBallSuccessChance -= nearestDefenderToReceiver.trueRating.StandTackleForGameCalculations * 0.05;

                int defenderDistance = CalculateDistance(receiver.CurrentZone, nearestDefenderToReceiver.CurrentZone);
                if (defenderDistance <= 1)
                {
                    throughBallSuccessChance -= 10;
                }
                else if (defenderDistance <= 2)
                {
                    throughBallSuccessChance -= 5;
                }
            }

            // Adjust for difficulty based on distance of through ball (passer to target zone)
            int distance = CalculateDistance(passer.CurrentZone, targetZone);
            throughBallSuccessChance -= (distance * 0.75);

            // Factor in target zone congestion/difficulty (simplified based on zone type)
            if (IsZoneInOpponentPenaltyArea(targetZone, attackingTeam))
            {
                throughBallSuccessChance -= 7;
            }
            else if (targetZone == Enums.PitchZone.AwayAttack_Center || targetZone == Enums.PitchZone.HomeDefense_Center)
            {
                throughBallSuccessChance -= 3;
            }

            // Incorporate the new 'isSetPiece' factor
            if (isSetPiece)
            {
                // Through balls from set pieces can be harder to execute perfectly due to static defense,
                // but can also exploit specific tactical setups. We'll introduce a slight penalty for general complexity.
                throughBallSuccessChance -= 5; // Example penalty
                // You might later add bonuses/penalties based on specific set piece tactics
            }

            // Clamp the chance
            throughBallSuccessChance = Math.Max(10, Math.Min(90, throughBallSuccessChance));

            int roll = Dice.d100();

            if (roll < throughBallSuccessChance)
            {
                if (IsZoneInOpponentPenaltyArea(targetZone, attackingTeam) ||
                    targetZone == Enums.PitchZone.AwayAttack_Center ||
                    targetZone == Enums.PitchZone.HomeDefense_Center)
                {
                    if (nearestDefenderToReceiver == null || CalculateDistance(receiver.CurrentZone, nearestDefenderToReceiver.CurrentZone) > 1)
                    {
                        Player goalkeeper = defendingTeam.GoalKeeper;
                        if (goalkeeper == null)
                        {
                            // --- CRITICAL ERROR: No Goalkeeper ---
                            LogEntry(new MatchEntry
                            {
                                Level = LogLevel.Fatal, // Log as Fatal error
                                EventType = MatchEventType.SystemMessage, // Or a specific Error event type
                                Timestamp = DateTime.Now,
                                Value1 = (double)TotalHomeScore(), // Log current score for context
                                Value2 = (double)TotalAwayScore(),
                                TeamName1 = attackingTeam.Name,
                                TeamName2 = defendingTeam.Name,
                                Zone1 = targetZone,
                                IsCriticalMoment = true, // Flag as critical
                                PlayerName1 = receiver.fullName, // Player who would have scored
                                PlayerName2 = "No Goalkeeper",
                                // Add a specific error message attribute if you have one
                            });
                            throw new Exception("ERROR: No goalkeeper to face 1v1! Goal conceded automatically.");
                        }

                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info, // Debug level for the attempt itself
                            EventType = MatchEventType.PassOutcome,
                            Timestamp = DateTime.Now,
                            PlayerName1 = passer.fullName,
                            Player1Pos = passer.position,
                            TeamName1 = attackingTeam.Name,
                            PlayerName2 = receiver.fullName,
                            Player2Pos = receiver.position,
                            TeamName2 = defendingTeam.Name, // Receiver's team (for context, even if not receiving yet)
                            Zone1 = passer.CurrentZone,
                            Zone2 = targetZone,
                            PassStyle = PassStyleType.ThroughBall,
                            Value1 = throughBallSuccessChance,
                            PassResult = PassResultType.Completed
                        });

                        SetPossession(receiver, targetZone, attackingTeam);
                        Enums.ShotOutcome oneOnOneOutcome = SimulateOneOnOne(receiver, goalkeeper, attackingTeam, defendingTeam);
                        return true;
                    }
                }

                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PassOutcome,
                    Timestamp = DateTime.Now,
                    PlayerName1 = passer.fullName,
                    Player1Pos = passer.position,
                    TeamName1 = attackingTeam.Name,
                    PlayerName2 = receiver.fullName,
                    Player2Pos = receiver.position,
                    TeamName2 = defendingTeam.Name, // Receiver's team (for context, even if not receiving yet)
                    Zone1 = passer.CurrentZone,
                    Zone2 = targetZone,
                    PassStyle = PassStyleType.ThroughBall,
                    Value1 = throughBallSuccessChance,
                    PassResult = PassResultType.Completed
                });

                SetPossession(receiver, targetZone, attackingTeam);
                return false;
            }
            else // Through ball attempt failed
            {
                // --- Failed Through Ball ---
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PassOutcome,
                    Timestamp = DateTime.Now,
                    PlayerName1 = passer.fullName,
                    Player1Pos = passer.position,
                    TeamName1 = attackingTeam.Name,
                    PlayerName2 = receiver.fullName, // Still log the intended receiver
                    Player2Pos = receiver.position,
                    TeamName2 = attackingTeam.Name,
                    Zone1 = passer.CurrentZone,
                    Zone2 = targetZone,
                    PassStyle = PassStyleType.ThroughBall,
                    PassResult = PassResultType.FailedToTeammate, // Default to failed to teammate if not intercepted
                    Value1 = throughBallSuccessChance, // Log the chance again
                });
                if (nearestDefenderToReceiver != null && Dice.d100() < 70)
                {
                    nearestDefenderToReceiver.gameStats.Interceptions++;
                    CheckForChanceNegation(passer.Team, CurrentSecond, nearestDefenderToReceiver);
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Log the interception as a PassOutcome
                        Timestamp = DateTime.Now,
                        PlayerName1 = passer.fullName, // The passer
                        Player1Pos = passer.position,
                        TeamName1 = attackingTeam.Name,
                        PlayerName2 = nearestDefenderToReceiver.fullName, // The interceptor
                        Player2Pos = nearestDefenderToReceiver.position,
                        TeamName2 = defendingTeam.Name,
                        Zone1 = passer.CurrentZone,
                        Zone2 = targetZone, // Zone of interception
                        PassStyle = PassStyleType.ThroughBall, // Still a through ball context
                        PassResult = PassResultType.Intercepted, // Explicitly intercepted
                    });
                    SetPossession(nearestDefenderToReceiver, nearestDefenderToReceiver.CurrentZone, defendingTeam);
                    return false;
                }
                else
                {
                    // --- Failed Through Ball - Loose Ball ---
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.PassOutcome, // Log the loose ball as a PassOutcome
                        Timestamp = DateTime.Now,
                        PlayerName1 = passer.fullName,
                        Player1Pos = passer.position,
                        TeamName1 = attackingTeam.Name,
                        Zone1 = targetZone, // Zone where ball became loose
                        PassStyle = PassStyleType.ThroughBall,
                        PassResult = PassResultType.FailedOutOfPlay, // Or a specific 'LooseBall' if you add it to PassResultType
                    });
                    SetLooseBall(false, passer, Enums.CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                    return false;
                }
            }
        }

        private void ConvertPassResultToMatchCondition(Enums.PassOutcome passOutcome, Player p, bool isHigh = false, Enums.CornerDeliveryType deliveryType = CornerDeliveryType.None)
        {
            //LoggingStuff.LogMethodCall(string.Format("ConvertPassResultToMatchCondition: passOutcome:{0},p:{1},isHigh:{2},deliveryType:{3}",
            //    passOutcome, p.position, isHigh, deliveryType));


            switch (passOutcome)
            {
                case Enums.PassOutcome.Successful:
                case Enums.PassOutcome.Intercepted:
                    CurrentMatchState = Enums.MatchState.InPlay_Possession;
                    break;
                case Enums.PassOutcome.LostPossession:
                case Enums.PassOutcome.LooseBall:
                    //SetLooseBall(isHigh, p, deliveryType, AttackingTeam, DefendingTeam);
                    break;
                case Enums.PassOutcome.FoulInAerialContest:
                    CurrentMatchState = Enums.MatchState.FreeKick;
                    break;
                case Enums.PassOutcome.Offside:
                    CurrentMatchState = Enums.MatchState.FreeKick_Indirect;
                    break;
                case Enums.PassOutcome.OutOfBounds:
                    CurrentMatchState = Enums.MatchState.ThrowIn;
                    break;
            }
        }

        private Enums.PitchZone DetermineRealisticFailedShortPassExitZone(Enums.PitchZone passerZone, Enums.PitchZone targetZone, Team attackingTeam)
        {
            // This method was a major point of confusion for the GK loop.
            // For a short pass by a GK that fails and goes out, it should result in a goal kick (if by GK team)
            // or a corner (if by opponent), or a throw-in if it went sideways.
            // It should NOT return GoalkeeperArea_X if it's truly an OOB event.

            // This is the specific logic we refined to return proper corner/flank zones for GK area
            if (Dice.d100() < 70) // 70% chance to be a ThrowIn
            {
                // If the pass was short and failed, it's most likely to go out at a nearby flank for a throw-in.
                // Determine which side of the field it's likely to exit.
                if (targetZone.ToString().Contains("Left") || passerZone.ToString().Contains("Left")) return Enums.PitchZone.HomeDefense_LeftFlank;
                if (targetZone.ToString().Contains("Right") || passerZone.ToString().Contains("Right")) return Enums.PitchZone.HomeDefense_RightFlank;
                return Enums.PitchZone.Midfield_Center; // Fallback for a loose ball if it doesn't go out.
            }
            else // 30% chance it might go out for a corner or goal kick (if from GK area)
            {
                // If from GoalkeeperArea, it's likely a miskick over the goal line.
                if (passerZone == Enums.PitchZone.GoalkeeperArea_Home)
                {
                    // Goalkeeper from home team miskicked from home GK area, likely leads to a corner for away team.
                    return Dice.d100() < 50 ? Enums.PitchZone.Corner_HomeLeft : Enums.PitchZone.Corner_HomeRight;
                }
                else if (passerZone == Enums.PitchZone.GoalkeeperArea_Away)
                {
                    // Goalkeeper from away team miskicked from away GK area, likely leads to a corner for home team.
                    return Dice.d100() < 50 ? Enums.PitchZone.Corner_AwayLeft : Enums.PitchZone.Corner_AwayRight;
                }
                // If not from GK area, but still a short pass, might just go loose or very rarely OOB close by.
                // For general short passes, if they hit this 30% branch and aren't from GK area,
                // they might just become loose centrally rather than OOB unless very close to the line.
                // For now, if not GK area, default to a central loose ball.
                return Enums.PitchZone.Midfield_Center;
            }
        }

        private Enums.PitchZone DetermineRealisticFailedLongPassExitZone(Enums.PitchZone passerZone, Enums.PitchZone targetZone, Team attackingTeam)
        {
            // This is a more complex method for long passes.
            // It should also return a specific restart zone (Corner_X, Flank_X) or a general in-play zone.
            bool isHomeTeamAttacking = attackingTeam == HomeTeam;
            bool isLeftFlankZone(Enums.PitchZone zone) => zone.ToString().Contains("Left");
            bool isRightFlankZone(Enums.PitchZone zone) => zone.ToString().Contains("Right");

            // Helper to get correct corner zone
            Enums.PitchZone GetCorrectCornerZone(Enums.PitchZone currentTargetZone, bool isAttackingHome)
            {
                if (isAttackingHome) // Home attacking, ball goes out at away team's end
                {
                    return isLeftFlankZone(currentTargetZone) ? Enums.PitchZone.Corner_AwayLeft : Enums.PitchZone.Corner_AwayRight;
                }
                else // Away attacking, ball goes out at home team's end
                {
                    return isLeftFlankZone(currentTargetZone) ? Enums.PitchZone.Corner_HomeRight : Enums.PitchZone.Corner_HomeLeft; // Note: Right/Left from attacking perspective
                }
            }

            // Helper to get correct Goal Kick zone
            Enums.PitchZone GetCorrectGoalKickZone(bool isAttackingHome)
            {
                return isAttackingHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
            }

            // Helper to get correct Throw-in zone
            Enums.PitchZone GetCorrectThrowInZone(Enums.PitchZone likelyExitZone, bool isAttackingHome)
            {
                // Simplistic: just return a general midfield flank based on the likely exit side
                if (isLeftFlankZone(likelyExitZone)) return Enums.PitchZone.Midfield_LeftFlank;
                if (isRightFlankZone(likelyExitZone)) return Enums.PitchZone.Midfield_RightFlank;
                return Enums.PitchZone.Midfield_Center; // Fallback
            }

            int roll = Dice.d100();

            if (roll < 60) // High chance of being a throw-in if it misses wide/long
            {
                return GetCorrectThrowInZone(targetZone, isHomeTeamAttacking);
            }
            else if (roll < 90) // Medium chance of a goal kick (overshot the goal or went wide and out of bounds behind goal)
            {
                return GetCorrectGoalKickZone(isHomeTeamAttacking); // This is a placeholder, `SetMatchStateForOutOfBounds` needs the actual logic for kick
            }
            else // Smaller chance of a corner
            {
                return GetCorrectCornerZone(targetZone, isHomeTeamAttacking);
            }
        }

        /// <summary>
        /// Determines if a pass from 'fromZone' to 'toZone' is generally "forward" relative to the attacking team's goal.
        /// </summary> 
        private bool IsForwardPass(Enums.PitchZone fromZone, Enums.PitchZone toZone, bool isHomeTeamAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsForwardPass: fromZone:{0},toZone:{1}," +
            //    "isHomeTeamAttacking:{2}", fromZone, toZone, isHomeTeamAttacking));

            int fromValue = GetZoneForwardValue(fromZone, isHomeTeamAttacking);
            int toValue = GetZoneForwardValue(toZone, isHomeTeamAttacking);

            return toValue > fromValue;
        }

        #endregion

        #region Shooting

        public Enums.ShotOutcome AttemptShot(Player shooter, Team attackingTeam, Team defendingTeam, Enums.ShotType shotType, bool isSetPiece = false, Player assister = null, bool isOneOnOne = false)
        {
            CurrentMatchState = Enums.MatchState.InPlay_Possession;

            if (!shooter.IsInjured && !shooter.isSentOff)
            {
                shooter.DecreaseCondition(0.8);
            }

            Player goalkeeper = defendingTeam.GoalKeeper;

            double shotAccuracy = 0;
            double shootingSkillWeight = 0;
            double composureWeight = 0.3;

            switch (shotType)
            {
                case Enums.ShotType.Normal:
                case Enums.ShotType.Volley:
                    shootingSkillWeight = 0.7;
                    shotAccuracy = (shooter.trueRating.VolleysForGameCalculations * shootingSkillWeight) +
                                   (shooter.trueRating.ShootingForGameCalculations * composureWeight);
                    break;
                case Enums.ShotType.DirectFreeKick:
                    shootingSkillWeight = 0.8;
                    shotAccuracy = (shooter.trueRating.freekicks * shootingSkillWeight) +
                                   (shooter.trueRating.ShootingForGameCalculations * composureWeight);
                    break;
                case Enums.ShotType.Header:
                    shootingSkillWeight = 0.6;
                    double headingBonus = (shooter.trueRating.HeaderForGameCalculations * shootingSkillWeight);
                    double jumpingBalanceBonus = (shooter.trueRating.JumpingForGameCalculations * 0.2 + shooter.trueRating.BalanceForGameCalculations * 0.1);
                    shotAccuracy = headingBonus + jumpingBalanceBonus + (shooter.trueRating.ShootingForGameCalculations * composureWeight);
                    break;
                case Enums.ShotType.Penalty:
                    shootingSkillWeight = 0.9;
                    shotAccuracy = (shooter.trueRating.penalties * shootingSkillWeight) +
                                   (shooter.trueRating.ComposureForGameCalculations * composureWeight);
                    break;
                default:
                    shotAccuracy = (shooter.trueRating.ShootingForGameCalculations * 0.7) +
                                   (shooter.trueRating.FinishingForGameCalculations * 0.3);
                    break;
            }
            shotAccuracy /= 100.0;

            // Determine the effective zone for the shot
            // If it's a set piece, use the simulated zone, otherwise use CurrentBallZone
            Enums.PitchZone effectiveShotZone = isSetPiece ? shooter.SimulatedSetPieceZone : CurrentBallZone;
            Enums.Flank currentFlank = GetFlankOfZone(effectiveShotZone); // Use effectiveShotZone for flank calculation

            bool isAttackingPenaltyArea = (attackingTeam == HomeTeam && effectiveShotZone == Enums.PitchZone.PenaltyArea_Away) ||
                                          (attackingTeam == AwayTeam && effectiveShotZone == Enums.PitchZone.PenaltyArea_Home);
            bool isAttackingCentralZone = (attackingTeam == HomeTeam && effectiveShotZone == Enums.PitchZone.AwayAttack_Center) ||
                                          (attackingTeam == AwayTeam && effectiveShotZone == Enums.PitchZone.HomeDefense_Center);
            bool isAttackingFlankZone = (attackingTeam == HomeTeam && (effectiveShotZone == Enums.PitchZone.AwayAttack_LeftFlank || effectiveShotZone == Enums.PitchZone.AwayAttack_RightFlank)) ||
                                        (attackingTeam == AwayTeam && (effectiveShotZone == Enums.PitchZone.HomeDefense_LeftFlank || effectiveShotZone == Enums.PitchZone.HomeDefense_RightFlank));

            if (isAttackingPenaltyArea)
            {
                shotAccuracy += 0.15;
            }
            else if (isAttackingCentralZone)
            {
                shotAccuracy += 0.05;
            }
            else if (isAttackingFlankZone)
            {
                shotAccuracy -= 0.10;
                if (currentFlank != Enums.Flank.Center && !isAttackingPenaltyArea)
                {
                    int zoneForwardValue = GetZoneForwardValue(effectiveShotZone, (attackingTeam == HomeTeam));
                    if (zoneForwardValue < 8)
                    {
                        shotAccuracy -= 0.05;
                    }
                }
            }
            else
            {
                shotAccuracy -= 0.30;
            }

            // Apply specific shot type adjustments
            switch (shotType)
            {
                case Enums.ShotType.DirectFreeKick:
                    // This logic already correctly uses isSetPiece
                    if (isSetPiece && GetAbsolutePitchDepth(effectiveShotZone) >= GetAbsolutePitchDepth(Enums.PitchZone.AwayAttack_Center) - 2)
                    {
                        shotAccuracy -= 0.15;
                    }
                    break;
                case Enums.ShotType.Header:
                    shotAccuracy -= 0.10;
                    break;
                case Enums.ShotType.Penalty:
                    shotAccuracy = Math.Max(0.70, shotAccuracy);
                    break;
                case Enums.ShotType.Volley:
                    shotAccuracy -= 0.07;
                    break;
            }

            if (isOneOnOne)
            {
                shotAccuracy += 0.20;
                shotAccuracy += (shooter.trueRating.ComposureForGameCalculations / 100.0) * 0.10;
                shotAccuracy += (shooter.trueRating.FinishingForGameCalculations / 100.0) * 0.05;
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Debug,
                    EventType = MatchEventType.ShotOutcome,
                    Timestamp = DateTime.Now,

                    PlayerName1 = shooter.fullName,
                    Player1Pos = shooter.position,
                    PlayerName2 = goalkeeper.fullName,
                    Player2Pos = goalkeeper.position,
                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,

                    ShotResult = ShotOutcomeSubType.AccuracyAdjustment,
                    ShotBlockerType = ShotBlockType.DefenderLeg,
                    Zone1 = CurrentBallZone,
                    Value1 = shotAccuracy,
                    IsFreeKick = (shotType == ShotType.DirectFreeKick),
                    IsHeader = (shotType == ShotType.Header),
                    IsPenalty = (shotType == ShotType.Penalty),
                    IsVolley = (shotType == ShotType.Volley),
                    IsRebound = ReboundChance,
                    IsPoorDeflection = PoorDeflection,
                    IsGoodDeflection = GoodDeflection
                });
            }

            if (assister != null && assister != shooter && !assister.IsInjured && !assister.isSentOff)
            {
                double assistBonus = (assister.trueRating.VisionForGameCalculations * 0.05 + assister.trueRating.PassingForGameCalculations * 0.05) / 100.0;
                shotAccuracy += assistBonus;
            }

            // When finding the nearest defender, for set pieces, we should probably look near the target's *simulated* zone
            // if the shooter is also in their simulated zone. For open play, CurrentZone is fine.
            // However, for a shot, the defender is reacting to the shot attempt from the shooter's actual location.
            // So, using shooter.CurrentZone for FindNearestDefender is likely still correct here,
            // as it represents where the shot is physically being taken from.
            // The previous aerial contest handled the pre-shot positioning.
            Player nearestDefender = FindNearestDefender(shooter, defendingTeam, shooter.CurrentZone);

            if (nearestDefender != null && !nearestDefender.IsInjured && !nearestDefender.isSentOff)
            {
                double defenderPressure = (nearestDefender.trueRating.DefenseAwarenessForGameCalculations * 0.7) +
                                          (nearestDefender.trueRating.StandTackleForGameCalculations * 0.3);
                defenderPressure /= 100.0;

                shotAccuracy -= (defenderPressure * 0.2);
            }

            shotAccuracy = Math.Max(0.05, Math.Min(0.95, shotAccuracy));

            // Blocking logic: Use effectiveShotZone for consistency
            bool inBlockingZone = (
                (attackingTeam == HomeTeam && (effectiveShotZone == Enums.PitchZone.PenaltyArea_Away || effectiveShotZone == Enums.PitchZone.AwayAttack_Center)) ||
                (attackingTeam == AwayTeam && (effectiveShotZone == Enums.PitchZone.PenaltyArea_Home || effectiveShotZone == Enums.PitchZone.HomeDefense_Center))
            );

            // Only apply block chance if not a set piece (since set piece blocks are handled differently via wall/etc.)
            // Or if it's a set piece, but specifically not a DirectFreeKick where walls are already accounted for.
            // Let's keep it simple for now and rely on isSetPiece for direct free kicks.
            if (!isSetPiece && nearestDefender != null && !nearestDefender.IsInjured && !nearestDefender.isSentOff && inBlockingZone)
            {
                double blockingValue = nearestDefender.trueRating.DefenseAwarenessForGameCalculations;
                double blockChance = (blockingValue > 0 ? blockingValue : 50.0) / 100.0;
                blockChance += (nearestDefender.trueRating.PositioningForGameCalculations / 100.0) * 0.1;
                blockChance = Math.Max(0, Math.Min(0.5, blockChance));

                if (Dice.d100() < (blockChance * 100))
                {
                    if (DetermineOwnGoalOccurred(nearestDefender, defendingTeam, effectiveShotZone, isFromShotAttempt: true))
                    {
                        nearestDefender.gameStats.OwnGoals++;
                        UpdateScore(null, null, this.DefendingTeam.GoalKeeper, false);
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.ShotOutcome,
                            Timestamp = DateTime.Now,

                            PlayerName1 = shooter.fullName,
                            PlayerName2 = nearestDefender.fullName,
                            Player1Pos = shooter.position,
                            Player2Pos = nearestDefender.position,
                            TeamName1 = AttackingTeam.Name,
                            TeamName2 = DefendingTeam.Name,

                            ShotResult = ShotOutcomeSubType.Goal,
                            ShotBlockerType = ShotBlockType.DefenderLeg,
                            Zone1 = CurrentBallZone,
                            IsOwnGoal = true,
                            IsFreeKick = (shotType == ShotType.DirectFreeKick),
                            IsHeader = (shotType == ShotType.Header),
                            IsPenalty = (shotType == ShotType.Penalty),
                            IsVolley = (shotType == ShotType.Volley),
                            IsRebound = ReboundChance,
                            IsPoorDeflection = PoorDeflection,
                            IsGoodDeflection = GoodDeflection
                        });

                        return Enums.ShotOutcome.Goal;
                    }
                    else
                    {
                        nearestDefender.gameStats.Blocks++;
                        this.CheckForErrorNegation(nearestDefender, CurrentSecond);
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.ShotOutcome,
                            Timestamp = DateTime.Now,

                            PlayerName1 = shooter.fullName,
                            PlayerName2 = nearestDefender.fullName,
                            Player1Pos = shooter.position,
                            Player2Pos = nearestDefender.position,
                            TeamName1 = AttackingTeam.Name,
                            TeamName2 = DefendingTeam.Name,

                            ShotResult = ShotOutcomeSubType.Blocked,
                            ShotBlockerType = ShotBlockType.DefenderLeg,
                            Zone1 = CurrentBallZone,
                            IsFreeKick = (shotType == ShotType.DirectFreeKick),
                            IsHeader = (shotType == ShotType.Header),
                            IsPenalty = (shotType == ShotType.Penalty),
                            IsVolley = (shotType == ShotType.Volley),
                            IsRebound = ReboundChance,
                            IsPoorDeflection = PoorDeflection,
                            IsGoodDeflection = GoodDeflection
                        });
                        SetLooseBall(false, nearestDefender, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                        return Enums.ShotOutcome.Blocked;
                    }
                }
            }

            if (ReboundChance)
            {
                if (GoodDeflection)
                    shotAccuracy += 5;
                else if (PoorDeflection)
                    shotAccuracy += 20; // arbitary - to make more shots on goal after rebound.
            }

            if (Dice.d100() < (shotAccuracy * 100))
            {
                ChanceCreated(shooter);
                double postChance = 5;
                postChance += (95 - shooter.trueRating.ShootingForGameCalculations) * 0.03;
                if (shotType == Enums.ShotType.Header)
                {
                    postChance += 3;
                }
                postChance = Math.Max(0, Math.Min(15, postChance));

                if (Dice.d100() < postChance)
                {
                    IncreaseShotCount(shooter, false, AttackingTeam);
                    MatchEntry me = new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.ShotOutcome,
                        Timestamp = DateTime.Now,

                        PlayerName1 = shooter.fullName,
                        Player1Pos = shooter.position,
                        TeamName1 = AttackingTeam.Name,

                        ShotResult = ShotOutcomeSubType.HitPost,
                        Zone1 = shooter.CurrentZone,
                        IsFreeKick = (shotType == ShotType.DirectFreeKick),
                        IsHeader = (shotType == ShotType.Header),
                        IsPenalty = (shotType == ShotType.Penalty),
                        IsVolley = (shotType == ShotType.Volley),
                        IsRebound = ReboundChance,
                        IsPoorDeflection = PoorDeflection,
                        IsGoodDeflection = GoodDeflection
                    };
                    if (assister != null)
                    {
                        me.PlayerName2 = assister.fullName;
                        me.Player2Pos = assister.position;
                        me.Zone1 = assister.CurrentZone;
                    }
                    LogEntry(me);
                    SetLooseBall(false, shooter, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                    return Enums.ShotOutcome.Post;
                }

                IncreaseShotCount(shooter, true, AttackingTeam);
                double calculatedShotPower = shooter.trueRating.ShootingForGameCalculations;
                double calculatedShotAccuracy = shooter.trueRating.FinishingForGameCalculations;

                if (shotType == Enums.ShotType.DirectFreeKick)
                {
                    calculatedShotPower = shooter.trueRating.freekicks;
                    calculatedShotAccuracy = shooter.trueRating.freekicks;
                }
                else if (shotType == Enums.ShotType.Header)
                {
                    calculatedShotPower = (shooter.trueRating.JumpingForGameCalculations * 0.5 + shooter.trueRating.StrengthForGameCalculations * 0.5);
                    calculatedShotAccuracy = shooter.trueRating.HeaderForGameCalculations;
                }
                else if (shotType == Enums.ShotType.Penalty)
                {
                    calculatedShotPower = 95;
                    calculatedShotAccuracy = 95;
                }

                // Pass the effectiveShotZone to AttemptGoalkeeperSave
                Enums.ShotOutcome outcome = AttemptGoalkeeperSave(shooter, goalkeeper, attackingTeam, defendingTeam, effectiveShotZone, calculatedShotPower, calculatedShotAccuracy, isOneOnOne);
                return outcome;
            }
            else
            {
                IncreaseShotCount(shooter, false, AttackingTeam);
                MatchEntry me = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.ShotOutcome,
                    Timestamp = DateTime.Now,

                    PlayerName1 = shooter.fullName,
                    Player1Pos = shooter.position,
                    TeamName1 = AttackingTeam.Name,

                    ShotResult = ShotOutcomeSubType.MissedWide,
                    Zone1 = CurrentBallZone,
                    IsFreeKick = (shotType == ShotType.DirectFreeKick),
                    IsHeader = (shotType == ShotType.Header),
                    IsPenalty = (shotType == ShotType.Penalty),
                    IsVolley = (shotType == ShotType.Volley),
                    IsRebound = ReboundChance,
                    IsPoorDeflection = PoorDeflection,
                    IsGoodDeflection = GoodDeflection
                };
                if (assister != null)
                {
                    me.Player2Pos = assister.position;
                    me.PlayerName2 = assister.fullName;
                    me.Zone2 = assister.CurrentZone;
                }
                LogEntry(me);
                // If it's a set piece, and the shot goes wide, the ball still goes out.
                // The CurrentBallZone needs to be set appropriately for the subsequent restart.
                // For now, retaining existing logic, but consider if set piece misses have different "out of bounds" zones.
                if (attackingTeam == HomeTeam)
                    CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Away;
                else
                    CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Home;
                this.SetMatchStateForOutOfBounds(CurrentBallZone, shooter.Team);
                return Enums.ShotOutcome.Miss;
            }
        }

        public void ResetRebounds()
        {
            ReboundChance = false;
            PoorDeflection = false;
            GoodDeflection = false;
        }

        #endregion

        #region Dribbling

        /// <summary>
        /// Simulates a player attempting to dribble the ball, potentially against a defender.
        /// </summary>
        /// <param name="dribbler">The player attempting to dribble.</param>
        /// <param name="attackingTeam">The dribbler's team.</param>
        /// <param name="defendingTeam">The opposing team.</param>
        /// <returns>The outcome of the dribble attempt.</returns>
        private Enums.DribbleOutcome AttemptDribble(Player dribbler, Team attackingTeam, Team defendingTeam)
        {
            // Dribbling costs condition
            if (!dribbler.IsInjured && !dribbler.isSentOff)
            {
                dribbler.DecreaseCondition(0.7);
            }

            // Get the flank of the dribbler's current zone
            Enums.Flank dribblerFlank = GetFlankOfZone(dribbler.CurrentZone); // <<< NEW

            // 1. Find Nearest Opposing Player to Dribbler
            Player nearestDefender = FindNearestDefender(dribbler, defendingTeam, dribbler.CurrentZone); // Use dribbler.CurrentZone

            // Check if there's no close defender for a contested dribble
            if (nearestDefender == null || nearestDefender.IsInjured || nearestDefender.isSentOff ||
                GetZoneDistance(dribbler.CurrentZone, nearestDefender.CurrentZone, attackingTeam == HomeTeam) > 3) // Using GetZoneDistance
            {
                dribbler.gameStats.SuccessfulDribbles++;
                MatchEntry meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PlayerMoved,
                    Timestamp = DateTime.Now,
                    DribblePhase = DribblePhaseType.Duel,
                    DribbleResult = DribbleResultType.NoChallenger,

                    PlayerName1 = dribbler.fullName,
                    Player1Pos = dribbler.position,
                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,

                    Zone1 = CurrentBallZone,
                };
                LogEntry(meOpen);
                SetPossession(dribbler, dribbler.CurrentZone, AttackingTeam); // Retain possession
                return Enums.DribbleOutcome.Successful;
            }

            // There is a nearby defender, so a contested dribble or tackle attempt occurs

            // 2. Calculate Dribble Success Chance (to evade without direct tackle)
            double dribbleSkill = (dribbler.trueRating.DribblingForGameCalculations * 0.5) +
                                    (dribbler.trueRating.PaceForGameCalculations * 0.2) +
                                    (dribbler.trueRating.BalanceForGameCalculations * 0.3);
            dribbleSkill /= 100.0;

            // Defender's passive pressure (not a direct tackle, but makes it harder to dribble past)
            double defenderPassivePressure = (nearestDefender.trueRating.DefenseAwarenessForGameCalculations * 0.7 +
                                                nearestDefender.trueRating.DefendingForGameCalculations * 0.3);
            defenderPassivePressure /= 100.0;

            // Adjust for distance: Closer defenders exert more passive pressure
            int distanceToDefender = GetZoneDistance(dribbler.CurrentZone, nearestDefender.CurrentZone, attackingTeam == HomeTeam);
            if (distanceToDefender <= 1)
            {
                defenderPassivePressure += 0.15; // Very close defender is much harder to evade
            }
            else if (distanceToDefender <= 2)
            {
                defenderPassivePressure += 0.05; // Fairly close defender is harder
            }

            // NEW: Adjust dribble difficulty based on flank
            if (dribblerFlank == Enums.Flank.Center)
            {
                // Dribbling in the center might be harder due to more congestion or tighter spaces
                dribbleSkill -= 0.05;
                defenderPassivePressure += 0.05; // Increased pressure in central areas
            }
            else // On a flank
            {
                // Wingers might find it slightly easier to dribble down the line, but still face pressure
                dribbleSkill += 0.02; // Small bonus for utilizing space on the flank
                defenderPassivePressure -= 0.02; // Slightly less passive pressure if player uses the touchline to their advantage
            }

            // Dribbler's chance to simply *evade* the defender without a direct tackle
            double evadeChance = dribbleSkill * 1.5 - defenderPassivePressure;
            evadeChance = Math.Max(0.15, Math.Min(0.95, evadeChance)); // Clamp

            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PlayerMoved,
                Timestamp = DateTime.Now,
                DribblePhase = DribblePhaseType.Duel,
                DribbleResult = DribbleResultType.NoChallenger,

                PlayerName1 = dribbler.fullName,
                Player1Pos = dribbler.position,
                PlayerName2 = nearestDefender.fullName,
                Player2Pos = nearestDefender.position,
                TeamName1 = DefendingTeam.Name,
                TeamName2 = AttackingTeam.Name,

                Value1 = evadeChance,

                Zone1 = CurrentBallZone,
            };

            if (Dice.d100() < (evadeChance * 100))
            {
                dribbler.gameStats.SuccessfulDribbles++;
                dribbler.gameStats.DuelsWon++;
                if (IsZoneDangerous(dribbler.CurrentZone, defendingTeam == HomeTeam))
                {
                    // it's only a potential chance if the move is in a dangerous area.
                    _potentialChanceCreatingActions.Add(new Tuple<Player, int>(dribbler, CurrentSecond));
                }
                me.DribbleResult = DribbleResultType.Success;
                LogEntry(me);
                SetPossession(dribbler, dribbler.CurrentZone, attackingTeam);
                return Enums.DribbleOutcome.Successful;
            }
            else
            {
                // --- NEW: Defender decides on tackle type here for reactive tackle ---
                Enums.TackleType chosenTackleType;
                double standingSkill = nearestDefender.trueRating.StandTackleForGameCalculations;
                double slidingSkill = nearestDefender.trueRating.SlideTackleForGameCalculations;

                // Simplified reactive tackle type decision:
                // Prioritize standing if good at it, or if sliding is risky/bad.
                // Otherwise, if closer to sliding skill or more aggressive, consider slide.
                if (standingSkill >= slidingSkill || nearestDefender.trueRating.ComposureForGameCalculations > 70)
                {
                    chosenTackleType = Enums.TackleType.Standing;
                }
                else // More inclined to slide if better at it or less composed
                {
                    chosenTackleType = Enums.TackleType.Sliding;
                }

                // Add a small chance for aggressive players to always slide when challenged directly
                if (nearestDefender.trueRating.AggressionForGameCalculations > 80 && Dice.d100() < 30)
                {
                    chosenTackleType = Enums.TackleType.Sliding;
                }

                // NEW: Influence defender's tackle choice based on dribbler's flank
                if (dribblerFlank != Enums.Flank.Center)
                {
                    // On flanks, defenders might be more inclined to attempt a standing tackle or simply shepherd out
                    // or if it's very deep, a sliding tackle to ensure the ball goes out
                    if (nearestDefender.trueRating.DefenseAwarenessForGameCalculations > 60 && Dice.d100() < 40)
                    {
                        // Good defenders on the flank might prefer standing tackle to avoid foul and push out
                        chosenTackleType = Enums.TackleType.Standing;
                    }
                    else if (GetZoneDistance(dribbler.CurrentZone, (attackingTeam == HomeTeam ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_RightFlank), attackingTeam == HomeTeam) <= 1 && Dice.d100() < 20) // Deep in opponent's attacking flank
                    {
                        // Aggressive slide to put it out for a throw-in/corner
                        chosenTackleType = Enums.TackleType.Sliding;
                    }
                }

                Enums.TackleOutcome tackleOutcome = AttemptTackle(nearestDefender, dribbler, attackingTeam, defendingTeam, chosenTackleType); // Call with chosen type

                if (tackleOutcome == Enums.TackleOutcome.Successful)
                {
                    dribbler.gameStats.Dispossessed++;
                    return Enums.DribbleOutcome.Tackled;
                }
                else if (tackleOutcome == Enums.TackleOutcome.Foul)
                {
                    if (IsZoneDangerous(dribbler.CurrentZone, attackingTeam == HomeTeam))
                    {
                        // it's only a potential chance if the move is in a dangerous area.
                        _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(dribbler, CurrentSecond));
                    }
                    return Enums.DribbleOutcome.LostBall; // Ball lost due to foul
                }
                else if (tackleOutcome == Enums.TackleOutcome.BallOutOfBounds) // If tackle makes ball go out
                {
                    dribbler.gameStats.Dispossessed++; // Count as dispossessed if it goes out due to defender pressure
                                                       // SetMatchStateForOutOfBounds should already be handled by AttemptTackle
                    return Enums.DribbleOutcome.LostBall; // Lost ball out of bounds
                }
                else if (tackleOutcome == Enums.TackleOutcome.Failed)
                {
                    // The tackle attempt failed to dispossess the dribbler.
                    // Now, determine if the dribbler truly shook them off, or if the ball became loose.
                    // This is where you bring in the "dribbler retains" or "loose ball" logic.

                    double retentionChanceAfterFailedTackle =
                        (dribbler.trueRating.DribblingForGameCalculations * 0.5) +
                        (dribbler.trueRating.BallControlForGameCalculations * 0.5); // Focus on retaining control

                    // You might want to adjust this chance based on the difficulty of the tackle attempt itself.
                    // E.g., if the tackler had a high success chance but just missed, it's more likely to be loose.

                    int finalRetentionRoll = Dice.d100();

                    if (finalRetentionRoll <= retentionChanceAfterFailedTackle)
                    {
                        // Dribbler successfully shrugged off the tackle and maintained control.
                        // This is a "successful dribble" in outcome, even if it was contested.
                        dribbler.gameStats.SuccessfulDribbles++; // It was a successful dribble past a challenge
                        dribbler.gameStats.DuelsWon++; // Count as winning the duel
                        if (IsZoneDangerous(dribbler.CurrentZone, defendingTeam == HomeTeam))
                        {
                            _potentialChanceCreatingActions.Add(new Tuple<Player, int>(dribbler, CurrentSecond));
                        }
                        me.DribbleResult = DribbleResultType.ResistTackle;
                        LogEntry(me);
                        SetPossession(dribbler, dribbler.CurrentZone, attackingTeam); // Dribbler retains possession.
                        return Enums.DribbleOutcome.Successful; // Effectively a successful dribble through a challenge.
                    }
                    else
                    {
                        // The tackle failed to win the ball, but the dribbler also lost tight control.
                        // The ball becomes loose, open for a scramble.
                        dribbler.gameStats.Dispossessed++; // Dribbler loses possession, even if tackler didn't cleanly win it
                        me.DribbleResult = DribbleResultType.OutOfBounds;
                        LogEntry(me);
                        CurrentBallZone = dribbler.CurrentZone;
                        SetLooseBall(false, dribbler, CornerDeliveryType.None, AttackingTeam, DefendingTeam); // This must set CurrentBallHolder = null and CurrentBallZone.
                        return Enums.DribbleOutcome.LostBall; // Ball is now loose, needs to be picked up.
                    }
                }
                else
                {
                    // Fallback for any unhandled TackleOutcome (shouldn't happen with the new enum).
                    return Enums.DribbleOutcome.LostBall;
                }
            }
        }

        private Enums.PitchZone GetBestAdjacentDribbleZone(Enums.PitchZone currentZone, Team attackingTeam, Team defendingTeam, bool isHomeTeamAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestAdjacentDribbleZone: currentZone:{0},attackingTeam:{1}," +
            //    "defendingTeam:{2},isHomeTeamAttacking:{3}", currentZone, attackingTeam.Name, defendingTeam.Name, isHomeTeamAttacking));


            // Now directly using the provided GetAdjacentZones method.
            List<Enums.PitchZone> adjacentZones = GetAdjacentZones(currentZone, isHomeTeamAttacking).ToList(); // Pass isHomeTeamAttacking for perspective if needed by GetAdjacentZones internally

            Enums.PitchZone bestZone = currentZone;
            double highestScore = -9999; // Start with a very low score to ensure any valid zone is better

            foreach (Enums.PitchZone potentialNextZone in adjacentZones)
            {
                if (potentialNextZone == Enums.PitchZone.None) continue; // Skip invalid zones (though your GetAdjacentZones seems to only add valid ones)

                double zoneScore = 0;

                // Prioritize zones that move the ball forward
                int currentForward = GetZoneForwardValue(currentZone, isHomeTeamAttacking);
                int nextForward = GetZoneForwardValue(potentialNextZone, isHomeTeamAttacking);
                if (nextForward > currentForward)
                {
                    zoneScore += 20; // Strong bonus for moving forward
                }
                else if (nextForward == currentForward)
                {
                    zoneScore += 5; // Small bonus for lateral movement (e.g., creating space)
                }
                else
                {
                    // Penalize backward dribble unless it's explicitly to escape very heavy pressure
                    // This is largely covered by the main method's pressure checks, but a small penalty here.
                    zoneScore -= 10;
                }

                // Penalize zones with many defenders
                int defendersInNextZone = CountDefendersInZone(potentialNextZone, defendingTeam);
                zoneScore -= defendersInNextZone * 25; // Heavy penalty for dribbling into congestion

                // Bonus for zones that have attacking teammates (could open up space or a pass option, or pull defenders away)
                int attackersInNextZone = CountAttackersInZone(potentialNextZone, attackingTeam);
                zoneScore += attackersInNextZone * 5;

                // Consider the type of zone (e.g., dribbling into opponent's penalty area is good)
                if ((isHomeTeamAttacking && potentialNextZone == Enums.PitchZone.PenaltyArea_Away) ||
                    (!isHomeTeamAttacking && potentialNextZone == Enums.PitchZone.PenaltyArea_Home))
                {
                    zoneScore += 30; // Significant bonus for dribbling into the penalty area
                }

                if (zoneScore > highestScore)
                {
                    highestScore = zoneScore;
                    bestZone = potentialNextZone;
                }
            }

            // If no adjacent zone is found or all are heavily penalized, bestZone remains None,
            // which the main CalculateDribbleOpportunity method then penalizes.
            return bestZone;
        }

        #endregion

        #region Crossing

        /// <summary>
        /// This is the main entry point for processing a cross attempt in your game.
        /// It orchestrates the cross quality calculation, GK decision, and subsequent interactions.
        /// </summary>
        /// <param name="crosser">The player attempting the cross.</param>
        /// <param name="attackingTeam">The team currently attacking.</param>
        /// <param name="defendingTeam">The team currently defending.</param>
        /// <param name="targetPlayer">The specific player identified as the best target for the cross.</param>
        /// <param name="isSetPiece">True if this cross originates from a set piece (e.g., a corner kick or indirect free kick).</param>
        /// <param name="deliveryType">The type of cross delivery (e.g., Lofted, Driven, Inswinger). Defaults to Unknown for non-set-piece crosses.</param> // NEW PARAMETER
        /// <returns>The outcome of the cross attempt.</returns>
        private Enums.CrossOutcome ProcessCrossAttempt(Player crosser, Team attackingTeam, Team defendingTeam, Player targetPlayer, bool isSetPiece = false, Enums.CornerDeliveryType deliveryType = Enums.CornerDeliveryType.None,
            bool isThrowIn = false)
        {
            _lastPasser = crosser;

            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = crosser.fullName,
                PlayerName2 = targetPlayer.fullName,
                Player1Pos = crosser.position,
                Player2Pos = targetPlayer.position,
                TeamName1 = AttackingTeam.Name,

                PassStyle = PassStyleType.Cross,
                Zone1 = crosser.CurrentZone,
                Zone2 = targetPlayer.CurrentZone
            };

            MatchEntry debugME = new MatchEntry
            {
                Level = LogLevel.Debug,
                EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = crosser.fullName,
                PlayerName2 = targetPlayer.fullName,
                Player1Pos = crosser.position,
                Player2Pos = targetPlayer.position,
                TeamName1 = AttackingTeam.Name,

                PassStyle = PassStyleType.Cross,
                Zone1 = crosser.CurrentZone,
                Zone2 = targetPlayer.CurrentZone
            };

            // --- NEW: Handle case where no suitable target was found by PlayerDecision ---
            if (targetPlayer == null || targetPlayer.IsInjured || targetPlayer.isSentOff || targetPlayer == crosser)
            {
                throw new Exception("No active target is found.");
                // Default to GoalKick for unfindable targets, as cross likely went over/out of play dangerously.
                //CurrentMatchState = (attackingTeam == HomeTeam) ? Enums.MatchState.GoalKick : Enums.MatchState.GoalKick;
                //return Enums.CrossOutcome.CrossMissed;
            }

            // Set the ball holder for the cross (important for game flow)
            SetPossession(crosser, crosser.CurrentZone, attackingTeam); // Ensure the crosser is the current ball holder

            // Get the flank of the crosser's current zone
            Enums.Flank crosserFlank = GetFlankOfZone(crosser.CurrentZone);

            // 1. Calculate Cross Quality
            double crossQuality = (crosser.trueRating.CrossingForGameCalculations * 0.5 +
                                    crosser.trueRating.PassingForGameCalculations * 0.3 +
                                    crosser.trueRating.VisionForGameCalculations * 0.2);
            crossQuality = Math.Max(0, Math.Min(100, crossQuality)); // Initial clamp

            // Apply modifiers based on deliveryType for set pieces
            if (isSetPiece && deliveryType != Enums.CornerDeliveryType.None) // Only apply if it's a set piece and type is known
            {
                switch (deliveryType)
                {
                    case Enums.CornerDeliveryType.InswingerLofted:
                    case Enums.CornerDeliveryType.OutswingerLofted:
                        crossQuality *= 0.95; // Lofted might be slightly less accurate by default, but good for aerials
                        // Crosser's curve attribute can slightly boost accuracy for these types
                        if (crosser.trueRating.CurveForGameCalculations > 75)
                        {
                            crossQuality += (crosser.trueRating.CurveForGameCalculations - 75) * 0.1; // Small boost
                        }
                        debugME.Value1 = crossQuality;
                        if (deliveryType == CornerDeliveryType.InswingerLofted)
                        { me.CrossType = CrossType.InswingerLofted; debugME.CrossType = CrossType.InswingerLofted; }
                        else { me.CrossType = CrossType.OutswingerLofted; debugME.CrossType = CrossType.OutswingerLofted; }
                        break;
                    case Enums.CornerDeliveryType.InswingerDriven:
                    case Enums.CornerDeliveryType.OutswingerDriven:
                        crossQuality *= 0.85; // Driven crosses are riskier and harder to execute perfectly
                        // Higher passing/technique needed for accurate driven crosses
                        crossQuality += (crosser.trueRating.PassingForGameCalculations * 0.1);
                        crossQuality -= (crosser.trueRating.CrossingForGameCalculations < 60 ? 5 : 0); // Penalty for poor technique
                        debugME.Value1 = crossQuality;
                        if (deliveryType == CornerDeliveryType.InswingerDriven)
                        { me.CrossType = CrossType.InswingerDriven; debugME.CrossType = CrossType.InswingerDriven; }
                        else { me.CrossType = CrossType.OutswingerDriven; debugME.CrossType = CrossType.OutswingerDriven; }
                        break;
                    case Enums.CornerDeliveryType.ShortPass:
                        // This scenario should ideally lead to AttemptPass, not ProcessCrossAttempt.
                        // If it somehow lands here, treat as a highly controlled short pass, very high quality if not intercepted.
                        crossQuality = 90; // Short passes from corners are generally high quality if chosen.
                        debugME.Value1 = crossQuality;
                        debugME.CrossType = CrossType.ShortPass;
                        me.CrossType = CrossType.ShortPass;
                        break;
                        // No default needed, as Unknown is handled by the initial 'if' check
                }
            }

            double adjuster = 1.00;

            Player nearestDefenderToCrosser = FindNearestDefender(crosser, defendingTeam, GetPlayerZone(crosser));
            if (nearestDefenderToCrosser != null && CalculateDistance(GetPlayerZone(crosser), nearestDefenderToCrosser.CurrentZone) <= 1)
            {
                crossQuality -= nearestDefenderToCrosser.trueRating.DefenseAwarenessForGameCalculations * 0.3;
                debugME.CrossQuality = CrossQuality.UnderPressure;
                debugME.Value1 = crossQuality;
            }
            crossQuality = Math.Max(10, Math.Min(100, crossQuality)); // Re-clamp after pressure penalty

            // Adjust cross quality based on how deep or wide the crosser is (using GetZoneForwardValue & crosserFlank)
            int crosserForwardValue = GetZoneForwardValue(crosser.CurrentZone, attackingTeam == HomeTeam);
            if (crosserFlank != Enums.Flank.Center) // Only apply this adjustment if truly on a flank
            {
                if (crosserForwardValue < 5) // Deep flank (e.g., own half or very deep midfield flank)
                {
                    crossQuality -= 35; // Significant penalty for crossing from very deep
                    debugME.CrossQuality = CrossQuality.DeepPosition;
                    debugME.Value1 = crossQuality;
                }
                else if (crosserForwardValue < 7) // Mid-flank (e.g., central midfield flank)
                {
                    crossQuality -= 25; // Slight penalty
                    debugME.CrossQuality = CrossQuality.Midfield;
                    debugME.Value1 = crossQuality;
                }
                // No bonus for ideal crossing zones (it's already factored in by base crossing rating)
            }

            crossQuality *= adjuster;

            LogEntry(debugME);

            // Check for a completely missed/poor cross (e.g., overhit, goes straight out)
            if (Dice.d100() > crossQuality * 0.9) // 90% of crossQuality as threshold
            {
                this.PassStatsResolve(crosser, false, CurrentSecond, isSetPiece, false, false);
                me.PassResult = PassResultType.FailedToTeammate;
                LogEntry(me);
                LooseBallDeliveryType = deliveryType;
                //SetLooseBall(true, crosser, deliveryType, AttackingTeam, DefendingTeam);

                //// Determine specific out of bounds based on crosser's flank
                //if (crosserFlank == Enums.Flank.Left)
                //{
                //    if (Dice.d100() < 70)
                //    {
                //        CurrentMatchState = Enums.MatchState.ThrowIn;
                //        CurrentBallZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.HomeDefense_LeftFlank;
                //        ShowMessage(string.Format("    It goes out for a throw-in on the far side ({0}).", CurrentBallZone));
                //    }
                //    else
                //    {
                //        CurrentMatchState = (attackingTeam == HomeTeam) ? Enums.MatchState.GoalKick : Enums.MatchState.GoalKick;
                //        CurrentBallZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                //        ShowMessage("    It goes out for a goal kick!");
                //    }
                //}
                //else if (crosserFlank == Enums.Flank.Right)
                //{
                //    if (Dice.d100() < 70)
                //    {
                //        CurrentMatchState = Enums.MatchState.ThrowIn;
                //        CurrentBallZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_RightFlank;
                //        ShowMessage(string.Format("    It goes out for a throw-in on the far side ({0}).", CurrentBallZone));
                //    }
                //    else
                //    {
                //        CurrentMatchState = (attackingTeam == HomeTeam) ? Enums.MatchState.GoalKick : Enums.MatchState.GoalKick;
                //        CurrentBallZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                //        ShowMessage("    It goes out for a goal kick!");
                //    }
                //}
                //else // Fallback for central crosser (should result in goal kick if out of play)
                //{
                //    CurrentMatchState = (attackingTeam == HomeTeam) ? Enums.MatchState.GoalKick : Enums.MatchState.GoalKick;
                //    ShowMessage("    It goes out for a goal kick!");
                //}
                return Enums.CrossOutcome.LooseBallHigh;
            }

            // 2. Get the Defending Goalkeeper (Robust GK fallback logic)
            Player goalkeeper = defendingTeam.GoalKeeper;

            // 3. Goalkeeper Decision: Decide whether to come out to intercept or stay on the line
            Enums.GKCrossAction gkAction = DecideGoalkeeperCrossInterception(goalkeeper, crossQuality, targetPlayer.CurrentZone, attackingTeam == HomeTeam);

            // 4. Find the nearest defender to the *target player* for the contest
            Player nearestDefenderToTarget = FindNearestDefender(targetPlayer, defendingTeam, GetPlayerZone(targetPlayer));

            // Ensure the nearest defender's SimulatedSetPieceZone is set.
            // For defenders contesting a cross, their "simulated" zone is typically where they are currently,
            // or where they are moving to contest the ball.
            // Assuming their CurrentZone reflects their position relative to the target attacker during the cross:
            nearestDefenderToTarget.SimulatedSetPieceZone = nearestDefenderToTarget.CurrentZone;

            // 5. Simulate Outcome based on GK's decision and player interaction
            if (gkAction == Enums.GKCrossAction.Catch || gkAction == Enums.GKCrossAction.Punch)
            {
                // GK attempts to intercept the cross
                // Pass 'isSetPiece' and 'deliveryType' down here as well
                return AttemptGoalkeeperCrossInterception(goalkeeper, crossQuality, gkAction, attackingTeam, defendingTeam, targetPlayer, crosser, isSetPiece, deliveryType); // UPDATED CALL
            }
            else // GKAction.None (Goalkeeper decided to stay on his line)
            {
                // "{0} decides to stay on his line, allowing outfield players to contest the cross.", goalkeeper.fullName));
                // Outfield players contest the cross
                // Pass 'isSetPiece' down here as well
                return SimulateAttackerOrDefenderCrossInteraction(crosser, targetPlayer, nearestDefenderToTarget, attackingTeam, defendingTeam, crossQuality, isSetPiece);
            }
        }

        /// <summary>
        /// Simulates the interaction between an attacker and defender attempting to get to a cross.
        /// </summary>
        /// <param name="crosser">The player who crossed the ball (for stats/context).</param>
        /// <param name="targetAttacker">The attacking player attempting to receive/contest the cross.</param>
        /// <param name="nearestDefender">The defending player attempting to intercept/clear the cross.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="crossQuality">The quality of the cross (0-100).</param>
        /// <param name="isSetPiece">True if this cross originates from a set piece (e.g., a corner kick or indirect free kick).</param>
        /// <returns>The outcome of the cross interaction.</returns>
        private Enums.CrossOutcome SimulateAttackerOrDefenderCrossInteraction(
            Player crosser, Player targetAttacker, Player nearestDefender,
            Team attackingTeam, Team defendingTeam, double crossQuality, bool isSetPiece)
        {
            // Handle case if no defender is near the target (should be rare in the box)
            if (nearestDefender == null)
            {
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = targetAttacker.fullName,
                    Player1Pos = targetAttacker.position,
                    PlayerName2 = nearestDefender.fullName,
                    Player2Pos = nearestDefender.position,
                    TeamName1 = attackingTeam.Name,
                    TeamName2 = defendingTeam.Name,
                    AerialResult = AerialResult.Uncontested,
                });
                SetPossession(targetAttacker, targetAttacker.CurrentZone, attackingTeam);
                Enums.ShotOutcome shotOutcome = AttemptShot(targetAttacker, attackingTeam, defendingTeam, Enums.ShotType.Header, true, crosser);
                return ConvertShotOutcomeToCrossOutcome(shotOutcome);
            }

            Enums.PitchZone contestZone = CurrentBallZone;
            if (isSetPiece)
                contestZone = targetAttacker.SimulatedSetPieceZone;

            Enums.AerialContestOutcome aerialOutcome = SimulateAerialContest(
                targetAttacker,             // Player 1 (Attacker trying to win)
                nearestDefender,            // Player 2 (Defender trying to contest)
                attackingTeam,              // Team of Player 1
                defendingTeam,              // Team of Player 2
                contestZone, // Use the contestZone which changes depending on whether the cross is coming from a set piece
                isSetPiece);                // Pass isSetPiece to the aerial contest

            switch (aerialOutcome)
            {
                case Enums.AerialContestOutcome.Player1Wins: // Target Attacker wins the aerial duel
                    _potentialChanceCreatingActions.Add(new Tuple<Player, int>(crosser, CurrentSecond));
                    targetAttacker.gameStats.DuelsWon++;
                    // Set possession to the attacker in their SIMULATED zone
                    SetPossession(targetAttacker, contestZone, attackingTeam);

                    // Volley vs. Header Decision (Your existing logic)
                    double volleyChance = (targetAttacker.trueRating.FinishingForGameCalculations * 0.4 +
                                           targetAttacker.trueRating.VolleysForGameCalculations * 0.4 +
                                           targetAttacker.trueRating.BallControlForGameCalculations * 0.2);

                    double qualityInfluence = Math.Abs(crossQuality - 50);
                    volleyChance += (50 - qualityInfluence) * 0.2;
                    volleyChance = Math.Max(10, Math.Min(70, volleyChance));

                    if (Dice.d100() < volleyChance)
                    {
                        Enums.ShotOutcome shotOutcome = AttemptShot(targetAttacker, attackingTeam, defendingTeam, Enums.ShotType.Volley, true, crosser);
                        return ConvertShotOutcomeToCrossOutcome(shotOutcome);
                    }
                    else
                    {
                        Enums.ShotOutcome shotOutcome = AttemptShot(targetAttacker, attackingTeam, defendingTeam, Enums.ShotType.Header, true, crosser);
                        return ConvertShotOutcomeToCrossOutcome(shotOutcome);
                    }

                case Enums.AerialContestOutcome.Player2Wins: // Nearest Defender wins the aerial duel
                    nearestDefender.gameStats.DuelsWon++;

                    // The contestZone is already correctly set to either CurrentBallZone or SimulatedSetPieceZone
                    // for the defender. Use this zone as the context for the clear.

                    // Pass the defender as the clearer, their team as clearing team, attackingTeam as opposing, and the contestZone.
                    AttemptClear(nearestDefender, defendingTeam, attackingTeam, contestZone, true);

                    // After AttemptClear runs, it will have handled setting CurrentBallZone, CurrentMatchState,
                    // and potentially returning for an own goal, throw-in, corner, or goal kick.
                    // The return value of SimulateAttackerOrDefenderCrossInteraction needs to reflect this.

                    // If AttemptClear resulted in an own goal, it handles the score update and returns from *itself*.
                    // So, if we reach here, it wasn't an own goal, and the ball is either loose or out of play.

                    // You'll need to check the CurrentMatchState after AttemptClear to decide the CrossOutcome.
                    // This is the slight complexity.
                    //if (CurrentMatchState == Enums.MatchState.InPlay_LooseBall)
                    //{
                    //    SetLooseBall(true, nearestDefender, Enums.CornerDeliveryType.None, attackingTeam, defendingTeam);
                    //}

                    if (CurrentMatchState == Enums.MatchState.ThrowIn ||
                             CurrentMatchState == Enums.MatchState.CornerKick ||
                             CurrentMatchState == Enums.MatchState.GoalKick)
                    {
                        return Enums.CrossOutcome.OutOfPlay; // Defender cleared it out of bounds
                    }
                    else if (CurrentMatchState == Enums.MatchState.Foul) // If AttemptClear could lead to a foul (unlikely for a clearance)
                    {
                        return Enums.CrossOutcome.FreeKickAwarded;
                    }
                    // Add any other specific outcomes from AttemptClear if they return early

                    if (CurrentMatchState == Enums.MatchState.FreeKick_Indirect)
                    {
                        return Enums.CrossOutcome.IndirectFreeKickAwarded;
                    }

                    // Fallback in case none of the above match (shouldn't happen if AttemptClear is comprehensive)
                    return Enums.CrossOutcome.Defended;

                case Enums.AerialContestOutcome.LooseBall:
                    // Call SetLooseBall with context of no clear winner, ball high, occurring at target attacker's zone
                    CurrentBallZone = contestZone; // Ball is loose at the point of contest
                    SetLooseBall(true, crosser, Enums.CornerDeliveryType.None, attackingTeam, defendingTeam); // No specific source player for loose outcome
                    //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
                    return Enums.CrossOutcome.LooseBall;

                case Enums.AerialContestOutcome.FoulOccurred:
                    // CurrentBallZone is already set by SimulateAerialContest for a foul.
                    // Match state is also set by SimulateAerialContest.
                    // No need to call SetLooseBall here as it implies immediate stoppage for foul.
                    return Enums.CrossOutcome.FreeKickAwarded;
            }

            // Default return (e.g., if targetAttacker/nearestDefender are null unexpectedly or logic issue)
            return Enums.CrossOutcome.CrossMissed;
        }

        // This would be within your MatchEngine or a MatchStateController
        public void ConvertCrossResultToMatchCondition(Enums.CrossOutcome outcome, Player sourcePlayer)
        {
            //LoggingStuff.LogMethodCall(string.Format("ConvertCrossResultToMatchCondition: outcome:{0}",
            //    outcome));


            switch (outcome)
            {
                case Enums.CrossOutcome.GoalFromCross:
                    CurrentMatchState = Enums.MatchState.GoalScored;
                    // You would then trigger goal celebration, reset for kickoff, update score etc.
                    break;
                case Enums.CrossOutcome.AttackerReachedBall:
                    //CurrentMatchState = Enums.MatchState.InPlay_LooseBall; // Or InPlay_Possession if clear control
                    //SetLooseBall(true);
                    CurrentMatchState = Enums.MatchState.InPlay_Possession;
                    // Logic to determine if it leads to shot, header, loose ball
                    break;
                case Enums.CrossOutcome.Defended:
                    CurrentMatchState = Enums.MatchState.InPlay_Possession;
                    //CurrentMatchState = Enums.MatchState.InPlay_LooseBall; // Or DefendingTeam_Possession
                    // Logic for who gains possession/where ball lands
                    break;
                case Enums.CrossOutcome.CaughtByGK:
                    CurrentMatchState = Enums.MatchState.GoalkeeperRecycle; // Goalkeeper now has possession
                    // Trigger goalkeeper distribution logic
                    break;
                case Enums.CrossOutcome.CrossMissed:
                    CurrentMatchState = Enums.MatchState.GoalKick; // Determine actual restart
                    // Logic for throw-in or goal kick
                    break;
                case Enums.CrossOutcome.OutOfPlay:
                    break;
                case Enums.CrossOutcome.IndirectFreeKickAwarded:
                    CurrentMatchState = Enums.MatchState.FreeKick_Indirect;
                    break;
                case Enums.CrossOutcome.LooseBallHigh:
                    CurrentMatchState = Enums.MatchState.InPlay_LooseBallHigh;
                    break;
                default:
                    //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
                    SetLooseBall(false, sourcePlayer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                    break;
            }
        }

        // You'll need this helper method if you don't have it already,
        // to map ShotOutcome to CrossOutcome for the return type of SimulateAttackerOrDefenderCrossInteraction
        private Enums.CrossOutcome ConvertShotOutcomeToCrossOutcome(Enums.ShotOutcome shotOutcome)
        {
            //LoggingStuff.LogMethodCall(string.Format("ConvertShotOutcomeToCrossOutcome: shotOutcome:{0}",
            //    shotOutcome));


            switch (shotOutcome)
            {
                case Enums.ShotOutcome.Goal:
                    return Enums.CrossOutcome.GoalFromCross;
                case Enums.ShotOutcome.Saved:
                case Enums.ShotOutcome.Blocked:
                case Enums.ShotOutcome.Miss:
                case Enums.ShotOutcome.Post:
                    return Enums.CrossOutcome.HeaderAttempted; // Or specific VolleyAttempted if you want
                default:
                    return Enums.CrossOutcome.CrossMissed; // Fallback, though should be covered
            }
        }

        /// <summary>
        /// Simulates the interaction between an attacker and defender attempting to get to a cross.
        /// </summary>
        /// <param name="crosser">The player who crossed the ball (for stats/context).</param>
        /// <param name="targetAttacker">The attacking player attempting to receive/contest the cross.</param>
        /// <param name="nearestDefender">The defending player attempting to intercept/clear the cross.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="crossQuality">The quality of the cross (0-100).</param>
        /// <param name="isSetPiece">True if this cross originates from a set piece (e.g., a corner kick or indirect free kick).</param> // NEW
        /// <returns>The outcome of the cross interaction.</returns>
        public Enums.AerialContestOutcome SimulateAerialContest(
            Player player1, Player player2, // Player1 is attacker, Player2 is defender
            Team team1, Team team2,
            Enums.PitchZone contestZone, // The zone where the contest is occurring
            bool isSetPiece, bool isPoorDeflection = false, bool isGoodDeflection = false)
        {
            // Determine the actual zones players are in for the contest.
            // For set pieces, use their pre-calculated simulated position.
            // For open play, continue to use their current physical zone.
            Enums.PitchZone player1ContestZone = isSetPiece ? player1.SimulatedSetPieceZone : player1.CurrentZone;
            Enums.PitchZone player2ContestZone = isSetPiece ? player2.SimulatedSetPieceZone : player2.CurrentZone;

            // Base attributes for aerial contests
            double player1AerialAbility = (player1.trueRating.HeaderForGameCalculations * 0.4 +
                                           player1.trueRating.JumpingForGameCalculations * 0.3 +
                                           player1.trueRating.AgilityForGameCalculations * 0.2 +
                                           player1.trueRating.AggressionForGameCalculations * 0.1);

            double player2AerialAbility = (player2.trueRating.HeaderForGameCalculations * 0.4 +
                                           player2.trueRating.JumpingForGameCalculations * 0.3 +
                                           player2.trueRating.AgilityForGameCalculations * 0.2 +
                                           player2.trueRating.AggressionForGameCalculations * 0.1);

            //// Height advantage
            //if (player1.heightInCm > player2.heightInCm + 5) // Player 1 is significantly taller
            //{
            //    player1AerialAbility += 5;
            //    ShowMessage(string.Format("  ({0} has a height advantage.)", player1.fullName));
            //}
            //else if (player2.heightInCm > player1.heightInCm + 5) // Player 2 is significantly taller
            //{
            //    player2AerialAbility += 5;
            //    ShowMessage(string.Format("  ({0} has a height advantage.)", player2.fullName));
            //}

            // Positional advantage based on contest zone.
            // A player already in the optimal zone has an advantage.
            // Crucially, use the *contestZone* parameter for this, which should be the *intended* zone.
            if (player1ContestZone == contestZone)
            {
                player1AerialAbility += 10; // Bonus for being in the precise contest zone
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Debug,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = player1.fullName,
                    Player1Pos = player1.position,
                    PlayerName2 = player2.fullName,
                    Player2Pos = player2.position,
                    TeamName1 = team1.Name,
                    TeamName2 = team2.Name,
                    Value1 = player1AerialAbility,
                    AerialPositioningType = AerialPositioningType.Perfect,

                    Zone1 = contestZone,
                });
            }
            if (player2ContestZone == contestZone)
            {
                player2AerialAbility += 10; // Bonus for being in the precise contest zone
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Debug,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = player1.fullName,
                    Player1Pos = player1.position,
                    PlayerName2 = player2.fullName,
                    Player2Pos = player2.position,
                    TeamName1 = team1.Name,
                    TeamName2 = team2.Name,
                    Value1 = player2AerialAbility,
                    AerialPositioningType = AerialPositioningType.Perfect,

                    Zone1 = contestZone,
                });
            }

            // Role-based advantages (specifically for set pieces)
            if (isSetPiece)
            {
                // Player 1 (attacker) bonuses
                if (player1.OffensiveSetPieceRole == Enums.SetPieceRole.TargetMan ||
                    player1.OffensiveSetPieceRole == Enums.SetPieceRole.NearPostRunner ||
                    player1.OffensiveSetPieceRole == Enums.SetPieceRole.FarPostThreat)
                {
                    player1AerialAbility += 10; // Specialist aerial threat
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Debug,
                        EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = player1.fullName,
                        Player1Pos = player1.position,
                        PlayerName2 = player2.fullName,
                        Player2Pos = player2.position,
                        TeamName1 = team1.Name,
                        TeamName2 = team2.Name,
                        Value1 = player1AerialAbility,
                        AerialPositioningType = AerialPositioningType.SetPiece,

                        Zone1 = contestZone,
                    });
                }

                // Player 2 (defender) bonuses
                if (player2.DefensiveSetPieceRole == Enums.SetPieceRole.ManMarker && player2.MarkedOpponent == player1)
                {
                    // The effectiveness of man-marking depends on how close they are.
                    // CalculateDistance uses your provided PitchZone coordinates.
                    int distanceToTarget = CalculateDistance(player2.SimulatedSetPieceZone, player1.SimulatedSetPieceZone);
                    if (distanceToTarget <= 1) // Very tight marking
                    {
                        player2AerialAbility += 15;
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Debug,
                            EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            PlayerName1 = player1.fullName,
                            Player1Pos = player1.position,
                            PlayerName2 = player2.fullName,
                            Player2Pos = player2.position,
                            TeamName1 = team1.Name,
                            TeamName2 = team2.Name,
                            Value1 = player2AerialAbility,
                            AerialPositioningType = AerialPositioningType.Marked,

                            Zone1 = contestZone,
                        });
                    }
                    else if (distanceToTarget <= 2) // Close marking
                    {
                        player2AerialAbility += 5;
                        LogEntry(new MatchEntry
                        {
                            Level = LogLevel.Debug,
                            EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            PlayerName1 = player1.fullName,
                            Player1Pos = player1.position,
                            PlayerName2 = player2.fullName,
                            Player2Pos = player2.position,
                            TeamName1 = team1.Name,
                            TeamName2 = team2.Name,
                            Value1 = player2AerialAbility,
                            AerialPositioningType = AerialPositioningType.Close,

                            Zone1 = contestZone,
                        });
                    }
                }
                else if (player2.DefensiveSetPieceRole == Enums.SetPieceRole.ZonalMarker && player2.SimulatedSetPieceZone == contestZone)
                {
                    player2AerialAbility += 8; // Good zonal coverage
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Debug,
                        EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = player1.fullName,
                        Player1Pos = player1.position,
                        PlayerName2 = player2.fullName,
                        Player2Pos = player2.position,
                        TeamName1 = team1.Name,
                        TeamName2 = team2.Name,
                        Value1 = player2AerialAbility,
                        AerialPositioningType = AerialPositioningType.Zonal,

                        Zone1 = contestZone,
                    });
                }
                else if (player2.DefensiveSetPieceRole == Enums.SetPieceRole.ClearingDefender)
                {
                    player2AerialAbility += 5; // General bonus for clearance specialists
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Debug,
                        EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = player1.fullName,
                        Player1Pos = player1.position,
                        PlayerName2 = player2.fullName,
                        Player2Pos = player2.position,
                        TeamName1 = team1.Name,
                        TeamName2 = team2.Name,
                        Value1 = player2AerialAbility,
                        AerialPositioningType = AerialPositioningType.Clearance,

                        Zone1 = contestZone,
                    });
                }
            }


            // Add a random factor to each player's ability
            //player1AerialAbility += Dice.d100() / 10.0; // +/- 10
            //player2AerialAbility += Dice.d100() / 10.0; // +/- 10

            //double player1successChance = player1AerialAbility;
            //// add or subtract 5 to give a slight advantage to the attacking team
            //if (player1.Team == AttackingTeam)
            //    player1successChance += 5;
            //else
            //    player1successChance -= 5; 
            //player1successChance -= player2AerialAbility;
            //int diceRoll = Dice.d100();
            //// if both players' abilities are equal, then each ball is 50-50, hence the 50.
            //bool player1WinsDuel = diceRoll < (player1successChance + 50);

            double totalContestSkill = player1AerialAbility + player2AerialAbility;
            double attackingTeamRecoveryProbability = (totalContestSkill > 0) ? (player1AerialAbility / totalContestSkill) : 0.5;
            if (PoorDeflection)
                attackingTeamRecoveryProbability += 0.20; // attacking more likely to get it on a poor deflection
            else if (GoodDeflection)
                attackingTeamRecoveryProbability -= 0.20; // defending more likely to get it on a good deflection
            attackingTeamRecoveryProbability = Math.Max(0.05, Math.Min(0.95, attackingTeamRecoveryProbability));
            int diceRoll = Dice.d100();
            bool player1WinsDuel = diceRoll < (attackingTeamRecoveryProbability * 100);

            LogEntry(new MatchEntry
            {
                Level = LogLevel.Debug,
                EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = player1.fullName,
                Player1Pos = player1.position,
                PlayerName2 = player2.fullName,
                Player2Pos = player2.position,
                TeamName1 = team1.Name,
                TeamName2 = team2.Name,
                Value1 = player1AerialAbility,
                Value2 = player2AerialAbility,
                AerialPositioningType = AerialPositioningType.Skillcheck,

                Zone1 = contestZone,
            });

            // Resolve the contest
            if (player1WinsDuel)
            {
                // Small chance of a foul if the defender is overly aggressive or clumsy
                if (Dice.d100() < (player1.trueRating.AggressionForGameCalculations * 0.1) && player1.trueRating.JumpingForGameCalculations < 50)
                {
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = player1.fullName,
                        Player1Pos = player1.position,
                        TeamName1 = team1.Name,
                        Value1 = player1AerialAbility,
                        PlayerName2 = player2.fullName,
                        Player2Pos = player2.position,
                        TeamName2 = team2.Name,
                        AerialResult = AerialResult.Foul,

                        Zone1 = contestZone,
                    });
                    // Set match state for the foul
                    //CurrentMatchState = Enums.MatchState.FreeKick_Indirect; // Or FreeKick_Direct if it's a dangerous foul
                    if (contestZone == Enums.PitchZone.None)
                    {
                        int x = 0;
                    }
                    CurrentBallZone = contestZone; // Ball is where the foul occurred
                    ProcessFoul(player1, player2, Enums.FoulType.AerialFoul, IsBallInPenaltyArea(CurrentBallZone, AttackingTeam), AttackingTeam);
                    // Potentially give a card here
                    return Enums.AerialContestOutcome.FoulOccurred;
                }

                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = player1.fullName,
                    Player1Pos = player1.position,
                    TeamName1 = team1.Name,
                    PlayerName2 = player2.fullName,
                    Player2Pos = player2.position,
                    TeamName2 = team2.Name,
                    Value1 = player1AerialAbility,
                    AerialResult = AerialResult.Won,

                    Zone1 = contestZone,
                });
                return Enums.AerialContestOutcome.Player1Wins;
            }
            else if (diceRoll < 100)
            {
                // Small chance of a foul if the defender is overly aggressive or clumsy
                if (Dice.d100() < (player2.trueRating.AggressionForGameCalculations * 0.1) && player2.trueRating.JumpingForGameCalculations < 50)
                {
                    LogEntry(new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,

                        PlayerName1 = player1.fullName,
                        Player1Pos = player1.position,
                        TeamName1 = team1.Name,
                        PlayerName2 = player2.fullName,
                        Player2Pos = player2.position,
                        TeamName2 = team2.Name,
                        Value2 = player2AerialAbility,
                        AerialResult = AerialResult.Foul,

                        Zone1 = contestZone,
                    });
                    // Set match state for the foul
                    //CurrentMatchState = Enums.MatchState.FreeKick_Indirect; // Or FreeKick_Direct if it's a dangerous foul
                    if (contestZone == Enums.PitchZone.None)
                    {
                        int x = 0;
                    }
                    CurrentBallZone = contestZone; // Ball is where the foul occurred
                    ProcessFoul(player2, player1, Enums.FoulType.AerialFoul, IsBallInPenaltyArea(CurrentBallZone, AttackingTeam), AttackingTeam);
                    // Potentially give a card here
                    return Enums.AerialContestOutcome.FoulOccurred;
                }
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = player1.fullName,
                    Player1Pos = player1.position,
                    TeamName1 = team1.Name,
                    PlayerName2 = player2.fullName,
                    Player2Pos = player2.position,
                    TeamName2 = team2.Name,
                    Value2 = player2AerialAbility,
                    AerialResult = AerialResult.Lost,

                    Zone1 = contestZone,
                });
                return Enums.AerialContestOutcome.Player2Wins;
            }
            else // Critical roll leads to a loose ball
            {
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.AerialBattle, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    Value2 = player2AerialAbility,
                    AerialResult = AerialResult.Contested,
                    PlayerName1 = player1.fullName,
                    Player1Pos = player1.position,
                    TeamName1 = team1.Name,
                    PlayerName2 = player2.fullName,
                    Player2Pos = player2.position,
                    TeamName2 = team2.Name,

                    Zone1 = contestZone,
                });
                return Enums.AerialContestOutcome.LooseBall;
            }
        }

        private Player FindSpecificCrossTarget(Player crossingPlayer, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("FindSpecificCrossTarget: crossingPlayer:{0},ballZone:{1}," +
            //    "attackingTeam:{2},defendingTeam:{3}", crossingPlayer.position, ballZone,
            //    attackingTeam.Name, defendingTeam.Name));


            double maxScore = -9999;
            Player bestTarget = null;

            int lateralDistance = Math.Abs(GetZoneLateralValue(ballZone, attackingTeam == HomeTeam));
            int currentForwardValue = GetZoneForwardValue(ballZone, attackingTeam == HomeTeam);
            int midfieldForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, attackingTeam == HomeTeam);

            if (lateralDistance >= 1 && currentForwardValue >= midfieldForwardValue)
            {
                foreach (Player potentialTarget in attackingTeam.AvailableOnFieldOutfielders.Where(p => p != crossingPlayer))
                {
                    Enums.PitchZone opponentPenaltyArea = (attackingTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
                    Enums.PitchZone opponentGoalArea = (attackingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

                    int targetDistanceToGoal = GetZoneDistance(potentialTarget.CurrentZone, opponentGoalArea, attackingTeam == HomeTeam);

                    if (potentialTarget.CurrentZone == opponentPenaltyArea || potentialTarget.CurrentZone == opponentGoalArea || targetDistanceToGoal <= 2)
                    {
                        double currentScore = CalculateCrossOpportunity(crossingPlayer, potentialTarget, ballZone, attackingTeam, defendingTeam);
                        if (currentScore > maxScore)
                        {
                            maxScore = currentScore;
                            bestTarget = potentialTarget;
                        }
                    }
                }
            }
            return bestTarget;
        }

        /// <summary>
        /// Finds the best cross opportunity (score and target) for a given player.
        /// </summary>
        /// <returns>The highest score found for a cross.</returns>
        private double GetBestCrossOpportunityScore(Player crossingPlayer, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestCrossOpportunityScore: crossingPlayer:{0},ballZone:{1}," + "attackingTeam:{2}defendingTeam:{3}",
            //                             crossingPlayer.position, ballZone, attackingTeam.Name, defendingTeam.Name));

            double maxScore = -9999;
            Player currentBestTarget = null;

            // A cross is only viable from wide, forward areas. Check this first to avoid unnecessary calculations.
            int lateralDistance = Math.Abs(GetZoneLateralValue(ballZone, attackingTeam == HomeTeam));
            int currentForwardValue = GetZoneForwardValue(ballZone, attackingTeam == HomeTeam);
            int midfieldForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, attackingTeam == HomeTeam);

            if (lateralDistance >= 1 && currentForwardValue >= midfieldForwardValue)
            {
                foreach (Player potentialTarget in attackingTeam.AvailableOnFieldOutfielders)
                {
                    // A player cannot cross to themselves
                    if (potentialTarget == crossingPlayer) continue;

                    // Target for a cross should typically be in or very near the opponent's penalty/goal area.
                    Enums.PitchZone opponentPenaltyArea = (attackingTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
                    Enums.PitchZone opponentGoalArea = (attackingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

                    int targetDistanceToGoal = GetZoneDistance(potentialTarget.CurrentZone, opponentGoalArea, attackingTeam == HomeTeam);

                    if (potentialTarget.CurrentZone == opponentPenaltyArea || potentialTarget.CurrentZone == opponentGoalArea || targetDistanceToGoal <= 2)
                    {
                        double currentScore = CalculateCrossOpportunity(crossingPlayer, potentialTarget, ballZone, attackingTeam, defendingTeam);

                        if (currentScore > maxScore)
                        {
                            maxScore = currentScore;
                            currentBestTarget = potentialTarget;
                        }
                    }
                }
            }
            // We'll update the class-level _lastChosenCrossTarget when PlayerDecision makes its final choice
            return maxScore;
        }

        #endregion

        #region Clear

        // Helper for Crosses:
        private Enums.PitchZone GetIdealCrossReceivingZone(Player targetPlayer, Team attackingTeam, bool isHomeTeamAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetIdealCrossReceivingZone: targetPlayer:{0},attackingTeam:{1}," +
            //    "isHomeTeamAttacking:{2}", targetPlayer.position, attackingTeam.Name, isHomeTeamAttacking));


            // This method should find a zone *within or very near* the opponent's penalty area
            // that the target player can run into and is relatively clear.
            Enums.PitchZone opponentPenaltyArea = isHomeTeamAttacking ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            Enums.PitchZone opponentGoalkeeperArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

            // Define preferred target zones within the penalty area based on player role/flank.
            // This would be simplified zones representing near post, far post, penalty spot, etc.
            // For now, let's just check the penalty area itself and its adjacent forward zones.

            List<Enums.PitchZone> potentialZones = new List<Enums.PitchZone>();

            // Start with the penalty area itself
            potentialZones.Add(opponentPenaltyArea);

            // Add zones immediately forward of the penalty area (e.g., GoalkeeperArea, if it's considered within reach for a cross)
            // Or zones that are just slightly ahead/wider of the penalty area but still inside the box conceptually
            // This needs to be consistent with your zone definitions.

            // If the target player is already in/near the penalty area, consider their current zone first.
            if (GetZoneDistance(targetPlayer.CurrentZone, opponentPenaltyArea, isHomeTeamAttacking) <= 1)
            {
                potentialZones.Insert(0, targetPlayer.CurrentZone); // Prioritize current zone if already good
            }

            // Filter and score potential zones based on defender presence and target player's movement
            Enums.PitchZone bestZone = targetPlayer.CurrentZone;
            double highestScore = -1000;

            foreach (Enums.PitchZone pz in potentialZones.Distinct()) // Use Distinct to avoid duplicates
            {
                double zoneScore = 0;
                int defendersInPZ = CountDefendersInZone(pz, DefendingTeam);
                int attackersInPZ = CountAttackersInZone(pz, attackingTeam); // New helper needed

                // Prefer zones with fewer defenders
                zoneScore -= defendersInPZ * 20;

                // Bonus for having attacking teammates in the zone (creates chaos, target might pick up loose ball)
                if (attackersInPZ > 0)
                {
                    zoneScore += attackersInPZ * 5;
                }

                // Penalty if a defender is extremely close to the *center* of this potential zone, even if player isn't there yet
                Player nearestDefenderToZoneCenter = FindNearestDefender(null, DefendingTeam, pz); // Pass null for player-agnostic search near zone
                if (nearestDefenderToZoneCenter != null && GetZoneDistance(pz, nearestDefenderToZoneCenter.CurrentZone, isHomeTeamAttacking) <= 1)
                {
                    zoneScore -= 10;
                }

                // Add bonus for target player's off-the-ball movement and positioning to reach this zone
                zoneScore += targetPlayer.trueRating.AgilityForGameCalculations * 0.1;
                zoneScore += targetPlayer.trueRating.PositioningForGameCalculations * 0.1;

                // Further bonus if the zone is directly ahead of the target player's general direction of movement (conceptual)
                // This requires knowing player's intended movement.

                if (zoneScore > highestScore)
                {
                    highestScore = zoneScore;
                    bestZone = pz;
                }
            }

            return bestZone;
        }

        private double CalculateClearOpportunity(Player player, Enums.PitchZone currentZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateClearOpportunity: player:{0},currentZone:{1}",
            //    player.position, currentZone));


            if (player.IsInjured || player.isSentOff) return -1000;

            double score = 0;
            bool isHomeAttacking = (this.AttackingTeam == HomeTeam);
            // Determine which team is defending (the player's team)
            Team defendingTeam = player.Team;
            bool isHomeDefending = (defendingTeam == HomeTeam);

            // Get the flank of the current zone
            Enums.Flank currentFlank = GetFlankOfZone(currentZone); // <<< NEW: Get flank of current zone

            // Base score: Players with good defending/composure are better at clearing
            score += player.trueRating.DefenseAwarenessForGameCalculations * 0.7;
            score += player.trueRating.ComposureForGameCalculations * 0.3;

            // TACTICAL INFLUENCE on clearing (Defending Team's perspective)
            // Using defendingTeam's tactic now, as clearing is a defensive action
            if (defendingTeam.CurrentTactic == Enums.TeamTactic.Defensive)
            {
                // Prioritize clearing when under pressure or in defensive zones
                score += 20;
                // Still using GetZoneForwardValue for general pitch zone assessment based on attacking team's forward
                if (GetZoneForwardValue(currentZone, isHomeAttacking) < 3) score += 10; // Strong bonus for clearing from deep

                // NEW: Additional bonus for clearing from flanks in defensive tactic
                // As it often leads to a throw-in rather than a central attack
                if (currentFlank != Enums.Flank.Center && GetZoneForwardValue(currentZone, isHomeAttacking) < 4) // In own half flanks
                {
                    score += 5;
                }
            }
            else if (defendingTeam.CurrentTactic == Enums.TeamTactic.Attacking)
            {
                // Discourage clearing unless absolutely necessary (prefer possession)
                score -= 15;
                // NEW: If in a central defensive zone, penalize clearing more heavily, encourage playing out
                if (currentFlank == Enums.Flank.Center && GetZoneForwardValue(currentZone, isHomeAttacking) < 3)
                {
                    score -= 10;
                }
            }
            else if (defendingTeam.CurrentTactic == Enums.TeamTactic.CounterAttack)
            {
                // Encourage clears that can turn into counter opportunities (long clears)
                if (GetZoneForwardValue(currentZone, isHomeAttacking) < 3) score += 10; // Boost if in defensive zone
                // NEW: Long clears from flanks might be less effective for counter, central might be better
                if (currentFlank != Enums.Flank.Center && GetZoneForwardValue(currentZone, isHomeAttacking) < 3)
                {
                    score -= 5; // Slightly discourage uncontrolled wide clears for counter
                }
            }

            // *** ENHANCEMENT: Zone influence using GetZoneDistance to own goal ***
            Enums.PitchZone ownGoalArea = isHomeDefending ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
            // We pass isHomeDefending because we're calculating distance from player's current zone to *their own* goal
            int distanceToOwnGoalHops = GetZoneDistance(currentZone, ownGoalArea, isHomeDefending);

            if (distanceToOwnGoalHops == 0) // In own goal area (very rare for outfield player, but possible for GK/defender)
            {
                score += 40; // Extremely high priority to clear
            }
            else if (distanceToOwnGoalHops <= 1) // In own Penalty Area
            {
                score += 30; // Very high priority to clear from own box
            }
            else if (distanceToOwnGoalHops <= 2) // Just outside own Penalty Area in defensive third
            {
                score += 15; // High priority to clear from own defensive half
            }

            // Defensive pressure around player increases clear opportunity
            Player nearestOpponent = FindNearestDefender(player, AttackingTeam, currentZone); // Find nearest opponent (who is a 'defender' to this player)
            // *** REPLACED CalculateDistance with GetZoneDistance ***
            if (nearestOpponent != null && GetZoneDistance(currentZone, nearestOpponent.CurrentZone, isHomeDefending) <= 1) // Check proximity from player's perspective
            {
                score += 15; // Under pressure, clearing is a good option
            }

            // Role-specific adjustments for clearing (similar to shot/dribble, but inverted logic)
            double roleAdjustment = 0;
            switch (player.Role)
            {
                case Enums.PlayerRole.CenterBack:
                case Enums.PlayerRole.DefensiveMidfielder:
                case Enums.PlayerRole.FullBack:
                    // These roles are primary clearers, especially when under pressure.
                    if (distanceToOwnGoalHops <= 2) // In deep defensive zones
                    {
                        roleAdjustment += 20; // Strong bonus for clearing
                    }
                    if (nearestOpponent != null && GetZoneDistance(currentZone, nearestOpponent.CurrentZone, isHomeDefending) <= 1)
                    {
                        roleAdjustment += 10; // Extra bonus if under pressure
                    }
                    break;
                case Enums.PlayerRole.Goalkeeper:
                    roleAdjustment += 50; // Goalkeepers should almost always clear if ball is in their hands/feet in dangerous area.
                    if (distanceToOwnGoalHops > 0) roleAdjustment -= 10; // Slightly penalize clearing from far away, prefer distribution.
                    break;
                case Enums.PlayerRole.CentralMidfielder:
                case Enums.PlayerRole.BoxToBoxMidfielder:
                    // Can clear, but prefer possession if possible.
                    if (distanceToOwnGoalHops <= 1) // In own penalty area
                    {
                        roleAdjustment += 15; // Good to clear if in immediate danger
                    }
                    else
                    {
                        roleAdjustment -= 5; // Slight disincentive to just clear from midfield
                    }
                    break;
                case Enums.PlayerRole.Winger:
                case Enums.PlayerRole.InsideForward:
                case Enums.PlayerRole.AttackingMidfielder:
                case Enums.PlayerRole.AdvancedPlaymaker:
                case Enums.PlayerRole.DeepLyingForward:
                case Enums.PlayerRole.FalseNine:
                case Enums.PlayerRole.Poacher:
                case Enums.PlayerRole.TargetMan:
                case Enums.PlayerRole.WidePlaymaker:
                    // Attacking roles, should rarely clear unless absolutely no other option.
                    if (distanceToOwnGoalHops <= 1) // In own penalty area
                    {
                        roleAdjustment += 10; // Still clear if in extreme danger in their own box
                    }
                    else
                    {
                        roleAdjustment -= 30; // Heavy penalty for clearing from anywhere else
                    }
                    break;
            }
            score += roleAdjustment;


            score = Math.Max(0, Math.Min(100, score)); // Keep score within 0-100 range

            // Add some small randomness to vary decisions
            score += Dice.d50() * 0.1; // Small random boost

            if (AerialBattlePending)
            {
                if (IsZoneDangerous(CurrentBallZone, AttackingTeam == HomeTeam))
                {
                    if (score > 0)
                        score *= 10;
                }
            }

            return score;
        }

        private void AttemptClear(Player clearer, Team clearingTeam, Team opposingTeam, Enums.PitchZone currentZone,
            bool isHeader)
        {
            //LoggingStuff.LogMethodCall(string.Format("AttemptClear: clearer:{0},clearingTeam:{1},opposingTeam:{2}," +
            //    "currentZone:{3},currentBallZone:{4},CurrentBallHolder:{5}",
            //    clearer.fullName, clearingTeam.Name, opposingTeam.Name, currentZone, CurrentBallZone, CurrentBallHolder.fullName));
            //ShowMessage(string.Format("{0} ({1}) clears the ball!", clearer.fullName, clearingTeam.Name));

            clearer.DecreaseCondition(1.0);

            // The setmatchoutofbounds will determine whether the ball is loose
            //SetLooseBall(true, clearer, Enums.CornerDeliveryType.None, AttackingTeam, DefendingTeam);

            Enums.PitchZone landingZone = CurrentBallZone;
            double clearRoll = Dice.d100() * clearer.trueRating.PassingForGameCalculations;
            if (isHeader)
            {
                clearRoll -= 2500; // weakened due to someone having to use his head.
            }

            bool isHomeClearing = (clearingTeam == HomeTeam);

            Enums.Flank currentClearFlank = GetFlankOfZone(currentZone);

            if (clearRoll > 7000)
            {
                landingZone = isHomeClearing ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
            }
            else if (clearRoll > 4000)
            {
                landingZone = Enums.PitchZone.Midfield_Center;
            }
            else // Poor clear, stays somewhat close or goes out for a throw/corner/goal kick
            {
                // --- NEW: Own Goal Check for a Poor Clear ---
                if (IsZoneDangerous(currentZone, clearingTeam == HomeTeam) && DetermineOwnGoalOccurred(clearer, clearingTeam, currentZone, isFromShotAttempt: false))
                {
                    MatchEntry le = new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.BallCleared,
                        PlayerName1 = clearer.fullName,
                        Player1Pos = clearer.position,
                        TeamName1 = AttackingTeam.Name,
                        Zone1 = currentZone,
                        Timestamp = DateTime.Now,
                        IsOwnGoal = true
                    };
                    LogEntry(le);
                    //ShowMessage(string.Format("Unbelievable! {0} ({1}) slices the clear into their own net! Own Goal!", clearer.fullName, clearingTeam.Name));
                    clearer.gameStats.OwnGoals++;
                    UpdateScore(null, null, this.DefendingTeam.GoalKeeper, false);
                    return; // Exit the method, as the own goal is the outcome
                }

                int roll = Dice.d100();
                if (roll < 30)
                {
                    //CurrentMatchState = Enums.MatchState.ThrowIn;

                    if (currentClearFlank == Enums.Flank.Left)
                    {
                        CurrentBallZone = isHomeClearing ? Enums.PitchZone.Midfield_LeftFlank : Enums.PitchZone.Midfield_LeftFlank;
                    }
                    else if (currentClearFlank == Enums.Flank.Right)
                    {
                        CurrentBallZone = isHomeClearing ? Enums.PitchZone.Midfield_RightFlank : Enums.PitchZone.Midfield_RightFlank;
                    }
                    else
                    {
                        CurrentBallZone = (Dice.d2() == 1) ? Enums.PitchZone.Midfield_LeftFlank : Enums.PitchZone.Midfield_RightFlank;
                    }
                    //ShowMessage(string.Format("The cleared ball goes out for a throw-in near {0}.", CurrentBallZone));
                }
                else if (roll < 60)
                {
                    if (isHomeClearing)
                    {
                        if (currentClearFlank != Enums.Flank.Center)
                        {
                            //CurrentMatchState = (Dice.d2() == 1) ? Enums.MatchState.CornerKick : Enums.MatchState.GoalKick;
                            CurrentBallZone = (currentClearFlank == Enums.Flank.Left) ? Enums.PitchZone.Corner_AwayRight : Enums.PitchZone.Corner_AwayLeft;
                            //if (CurrentMatchState == Enums.MatchState.GoalKick) CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Away;
                        }
                        else
                        {
                            //CurrentMatchState = Enums.MatchState.GoalKick;
                            CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Away;
                        }
                        //ShowMessage(string.Format("The cleared ball goes out for a {0} from {1}'s goal.", CurrentMatchState == Enums.MatchState.CornerKick ? "corner" : "goal kick", opposingTeam.Name));
                    }
                    else
                    {
                        if (currentClearFlank != Enums.Flank.Center)
                        {
                            //CurrentMatchState = (Dice.d2() == 1) ? Enums.MatchState.CornerKick : Enums.MatchState.GoalKick;
                            CurrentBallZone = (currentClearFlank == Enums.Flank.Left) ? Enums.PitchZone.Corner_HomeRight : Enums.PitchZone.Corner_HomeLeft;
                            //if (CurrentMatchState == Enums.MatchState.GoalKick) CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Home;
                        }
                        else
                        {
                            //CurrentMatchState = Enums.MatchState.GoalKick;
                            CurrentBallZone = Enums.PitchZone.GoalkeeperArea_Home;
                        }
                        //ShowMessage(string.Format("The cleared ball goes out for a {0} from {1}'s goal.", CurrentMatchState == Enums.MatchState.CornerKick ? "corner" : "goal kick", opposingTeam.Name));
                    }
                }
                else
                {
                    if (currentClearFlank == Enums.Flank.Left)
                    {
                        landingZone = isHomeClearing ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_LeftFlank;
                    }
                    else if (currentClearFlank == Enums.Flank.Right)
                    {
                        landingZone = isHomeClearing ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_RightFlank;
                    }
                    else
                    {
                        landingZone = isHomeClearing ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                    }
                }
            }

            LogEntry(new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.BallCleared,
                PlayerName1 = clearer.fullName,
                Player1Pos = clearer.position,
                TeamName1 = clearingTeam.Name,
                Zone1 = currentZone,
                Zone2 = landingZone,
                Timestamp = DateTime.Now,
                IsHeader = isHeader,
            });

            //if (clearRoll < 60)
            //{
            //    this.SetMatchStateForOutOfBounds(CurrentBallZone, AttackingTeam);
            //    return;
            //}

            //CurrentBallZone = landingZone;
            //LogEntry(new MatchEntry
            //{
            //    Level = LogLevel.Debug,
            //    EventType = MatchEventType.BallCleared,
            //    PlayerName1 = clearer.fullName,
            //    Player1Pos = clearer.position,
            //    TeamName1 = clearingTeam.Name,
            //    Zone1 = currentZone,
            //    Zone2 = landingZone,
            //    Timestamp = DateTime.Now
            //});
            //ShowMessage(string.Format("The cleared ball lands in {0}.", CurrentBallZone));
            SetLooseBall(true, clearer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
            //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
        }

        #endregion Clear

        #region Goalkeeper Actions

        private void AttemptGoalkeeperInterception(Player goalkeeper, Player ballCarrier, Team attackingTeam, Team defendingTeam)
        {
            double gkInterceptionChance = (goalkeeper.trueRating.GoalKeepingReflexesForGameCalculations + goalkeeper.trueRating.GoalKeepingReflexesForGameCalculations + goalkeeper.trueRating.PositioningForGameCalculations) / 3.0;
            double opponentDribbleChance = ballCarrier.trueRating.DribblingForGameCalculations + ballCarrier.trueRating.AgilityForGameCalculations;

            if (IsBallHolderUnderPressure(ballCarrier))
            {
                opponentDribbleChance *= 0.8;
            }

            // A slightly more complex roll comparison for better nuance
            int gkRoll = Dice.d100();
            int opponentRoll = Dice.d100();

            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PlayerMoved,
                Timestamp = DateTime.Now,
                DribblePhase = DribblePhaseType.Duel,

                PlayerName1 = ballCarrier.fullName,
                Player1Pos = ballCarrier.position,
                PlayerName2 = goalkeeper.fullName,
                Player2Pos = goalkeeper.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,

                Zone1 = CurrentBallZone,
            };

            // Goalkeeper wins if their modified roll is higher
            if ((gkRoll * gkInterceptionChance) > (opponentRoll * opponentDribbleChance))
            {
                me.DribbleResult = DribbleResultType.Fail;
                CurrentBallHolder = goalkeeper;
                CurrentMatchState = MatchState.GoalkeeperRecycle;
                //SetPossession(goalkeeper, GetPlayerZone(goalkeeper), defendingTeam);
            }
            else // Goalkeeper FAILED to cleanly intercept
            {
                // *** NEW: Check for a charging foul ***
                // Only check for a foul if the GK was actively challenging (i.e., failed to intercept cleanly)
                bool foulOccurred = SimulateGoalkeeperCharge(goalkeeper, ballCarrier, ballCarrier.CurrentZone);

                if (foulOccurred)
                {
                    // SimulateGoalkeeperCharge already handles ProcessFoul, so just return
                    return;
                }
                else
                {
                    me.DribbleResult = DribbleResultType.Success;
                    // No foul, but GK failed to intercept cleanly.
                    // Ball carrier retains possession, or it becomes a loose ball in their zone.
                    SetPossession(ballCarrier, GetPlayerZone(ballCarrier), attackingTeam);
                    // Or you could make it a loose ball if you want more unpredictability after failed challenges
                    // SetLooseBall();
                }
            }
            LogEntry(me);
        }

        /// <summary>
        /// Simulates the goalkeeper's actual attempt to either catch or punch a cross, and its immediate outcome.
        /// This is called if DecideGoalkeeperCrossInterception returns Catch or Punch.
        /// </summary>
        /// <param name="goalkeeper">The goalkeeper attempting the interception.</param>
        /// <param name="crossQuality">The quality of the incoming cross (0-100).</param>
        /// <param name="gkAction">The chosen action of the goalkeeper (Catch or Punch).</param>
        /// <param name="attackingTeam">The team that delivered the cross.</param>
        /// <param name="defendingTeam">The team whose goalkeeper is attempting to intercept.</param>
        /// <param name="targetPlayer">The intended attacking recipient of the cross.</param>
        /// <param name="passer">The player who crossed the ball (for statistical purposes).</param>
        /// <param name="isSetPiece">True if this cross originates from a set piece (e.g., a corner kick or indirect free kick).</param>
        /// <param name="deliveryType">The type of cross delivery (e.g., Lofted, Driven, Inswinger).</param> // NEW PARAMETER
        /// <returns>The outcome of the cross interception.</returns>
        private Enums.CrossOutcome AttemptGoalkeeperCrossInterception(Player goalkeeper, double crossQuality, Enums.GKCrossAction gkAction, Team attackingTeam, Team defendingTeam, Player targetPlayer, Player passer, bool isSetPiece, Enums.CornerDeliveryType deliveryType)
        {
            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = passer.fullName,
                Player1Pos = passer.position,
                PlayerName2 = goalkeeper.fullName,
                Player2Pos = goalkeeper.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,

                Zone1 = passer.CurrentZone,
                Zone2 = targetPlayer.CurrentZone
            };

            MatchEntry debugME = new MatchEntry
            {
                Level = LogLevel.Debug,
                EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = passer.fullName,
                Player1Pos = passer.position,
                PlayerName2 = goalkeeper.fullName,
                Player2Pos = goalkeeper.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,

                Zone1 = passer.CurrentZone,
                Zone2 = targetPlayer.CurrentZone
            };

            if (targetPlayer == null)
            {
                me = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    PassResult = PassResultType.FailedToTeammate,

                    PlayerName1 = passer.fullName,
                    Player1Pos = passer.position,
                    PlayerName2 = goalkeeper.fullName,
                    Player2Pos = goalkeeper.position,
                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,

                    Zone1 = CurrentBallZone
                };
                LogEntry(me);
                SetLooseBall(false, passer, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                return Enums.CrossOutcome.CrossMissed;
            }

            double interceptionChance = 0.0;

            interceptionChance += goalkeeper.trueRating.JumpingForGameCalculations * 0.3;
            interceptionChance += goalkeeper.trueRating.ReactionTimeForGameCalculations * 0.2;
            interceptionChance += goalkeeper.trueRating.PositioningForGameCalculations * 0.2;
            interceptionChance += goalkeeper.trueRating.PhysicalityForGameCalculations * 0.1;

            interceptionChance -= (crossQuality * 0.3); // Higher quality cross is harder to intercept

            // Apply delivery type specific adjustments for GK
            if (isSetPiece && deliveryType != Enums.CornerDeliveryType.None)
            {
                switch (deliveryType)
                {
                    case Enums.CornerDeliveryType.InswingerLofted:
                    case Enums.CornerDeliveryType.OutswingerLofted:
                        // Lofted crosses allow GK more time to position and command area
                        interceptionChance += goalkeeper.trueRating.Composure * 0.1;
                        // But can be harder to judge if the cross has heavy curve
                        interceptionChance -= (passer.trueRating.CurveForGameCalculations * 0.05);
                        debugME.PassStyle = PassStyleType.Lob;
                        debugME.Value1 = interceptionChance;
                        break;
                    case Enums.CornerDeliveryType.InswingerDriven:
                    case Enums.CornerDeliveryType.OutswingerDriven:
                        // Driven crosses demand faster reactions and better handling for clean catches
                        interceptionChance += goalkeeper.trueRating.ReactionTime * 0.1;
                        interceptionChance -= goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.05; // Slightly harder to handle cleanly
                        // A small bonus for aggressive GKs who come out hard for driven balls
                        interceptionChance += goalkeeper.trueRating.AggressionForGameCalculations * 0.05;
                        debugME.Value1 = interceptionChance;
                        debugME.PassStyle = PassStyleType.Cross;
                        break;
                    case Enums.CornerDeliveryType.ShortPass:
                        // Short passes usually won't result in GK interception attempts (handled by AttemptPass)
                        // If it somehow ends up here, GK should ideally not be involved, so minimal chance.
                        interceptionChance = 0;
                        debugME.Value1 = interceptionChance;
                        debugME.PassStyle = PassStyleType.GroundPass;
                        break;
                        // No default needed, as Unknown is handled by the initial 'if' check
                }
            }


            if (gkAction == Enums.GKCrossAction.Catch)
            {
                interceptionChance += goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.4;
                interceptionChance -= 10; // Catching is generally riskier than punching
                debugME.Value1 = interceptionChance;
                debugME.PassStyle = PassStyleType.Cross;
            }
            else if (gkAction == Enums.GKCrossAction.Punch)
            {
                interceptionChance += goalkeeper.trueRating.StrengthForGameCalculations * 0.4; // Punching relies on strength
                interceptionChance += 5; // Punching is generally safer
                debugME.Value1 = interceptionChance;
                debugME.PassStyle = PassStyleType.Cross;
            }

            interceptionChance += goalkeeper.trueRating.ComposureForGameCalculations * 0.1;

            // --- EXISTING: Find nearest attacker for contest ---
            Player nearestAttackerForContest = attackingTeam.AvailableOnFieldOutfielders
                .Where(p => (p.CurrentZone == targetPlayer.CurrentZone ||
                             CalculateDistance(p.CurrentZone, targetPlayer.CurrentZone) <= 1)) // Check current or adjacent zones
                .OrderBy(p => CalculateDistance(p.CurrentZone, targetPlayer.CurrentZone)) // Closer first
                .ThenByDescending(p => p.trueRating.JumpingForGameCalculations + p.trueRating.HeaderForGameCalculations) // Then aerial ability
                .FirstOrDefault();

            //if (nearestAttackerForContest != null)
            //{
            //    ShowMessage(string.Format("    {0} is challenged by {1} for the cross!", goalkeeper.fullName, nearestAttackerForContest.fullName));
            //}

            interceptionChance = Math.Max(0, Math.Min(95, interceptionChance)); // Final clamp

            int interceptionRoll = Dice.d100();

            if (interceptionRoll < interceptionChance)
            {
                this.PassStatsResolve(passer, false, CurrentSecond, false, false, false); // Cross failed to reach attacker due to GK action
                if (gkAction == Enums.GKCrossAction.Catch)
                {
                    me.PassResult = PassResultType.GKIntercepted;
                    LogEntry(me);
                    //SetPossession(goalkeeper, GetPlayerZone(goalkeeper), defendingTeam);
                    CurrentMatchState = Enums.MatchState.GoalkeeperRecycle; // this should set the possession properly
                    return Enums.CrossOutcome.CaughtByGK;
                }
                else // GKAction.Punch
                {
                    double punchControlChance = goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.5 +
                                                goalkeeper.trueRating.ComposureForGameCalculations * 0.5;
                    punchControlChance = Math.Max(10, Math.Min(90, punchControlChance));
                    me.PassResult = PassResultType.GKPunch;
                    LogEntry(me);
                    //if (Dice.d100() < punchControlChance)
                    //{
                    //    ShowMessage("    ...and it goes safely out of danger!");
                    //    SetLooseBall(true, goalkeeper, deliveryType, attackingTeam, defendingTeam);
                    //    return Enums.CrossOutcome.PunchedClearByGK;
                    //}
                    //else
                    //{
                    //    ShowMessage("    ...but it lands straight at an opponent's feet!");
                    //    SetLooseBall(true, goalkeeper, deliveryType, attackingTeam, defendingTeam);
                    //    return Enums.CrossOutcome.PunchedToOpponent;
                    //}
                }
            }
            else // Goalkeeper FAILED to cleanly intercept the cross
            {
                _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(goalkeeper, CurrentSecond));

                // --- NEW: Own Goal Check for Fumbled Cross Interception ---
                if (DetermineOwnGoalOccurred(goalkeeper, defendingTeam, GetPlayerZone(goalkeeper), false, true))
                {
                    me.PassResult = PassResultType.GKPunch;
                    me.IsOwnGoal = true;
                    LogEntry(me);
                    goalkeeper.gameStats.OwnGoals++;
                    UpdateScore(null, null, goalkeeper, false);
                    return Enums.CrossOutcome.GoalFromCross;
                }

                // --- If GK fails and no own goal, check for a challenging attacker for an aerial contest ---
                if (nearestAttackerForContest != null)
                {
                    Enums.AerialContestOutcome aerialOutcome = SimulateAerialContest(
                        nearestAttackerForContest, // Contester1: Attacker
                        goalkeeper,                 // Contester2: Goalkeeper (who just fumbled/missed)
                        attackingTeam,
                        defendingTeam,
                        targetPlayer.CurrentZone,   // Contest happens around the target
                        isSetPiece);                // Pass isSetPiece to the aerial contest

                    switch (aerialOutcome)
                    {
                        case Enums.AerialContestOutcome.Player1Wins: // Attacker wins the contest
                            _potentialChanceCreatingActions.Add(new Tuple<Player, int>(passer, CurrentSecond));
                            //ShowMessage(string.Format("{0} wins the aerial battle against {1}!", nearestAttackerForContest.fullName, goalkeeper.fullName));
                            SetPossession(nearestAttackerForContest, nearestAttackerForContest.CurrentZone, attackingTeam);
                            // The cross has now reached an attacker, who might attempt a shot.
                            Enums.ShotOutcome shotOutcome = AttemptShot(nearestAttackerForContest, attackingTeam, defendingTeam, Enums.ShotType.Header, true, passer);
                            return ConvertShotOutcomeToCrossOutcome(shotOutcome);

                        case Enums.AerialContestOutcome.Player2Wins: // Goalkeeper surprisingly recovers and wins
                            //ShowMessage(string.Format("{0} recovers and wins the aerial battle!", goalkeeper.fullName));
                            SetPossession(goalkeeper, goalkeeper.CurrentZone, defendingTeam);
                            return Enums.CrossOutcome.CaughtByGK;

                        case Enums.AerialContestOutcome.LooseBall: // Ball remains loose after contest
                            //ShowMessage("The aerial contest between GK and attacker results in a dangerous loose ball!");
                            SetLooseBall(false, goalkeeper, deliveryType, attackingTeam, defendingTeam);
                            return Enums.CrossOutcome.LooseBall;

                        case Enums.AerialContestOutcome.FoulOccurred: // Goalkeeper commits a foul during the contest
                            //ShowMessage(string.Format("A foul by {0} on {1} during the aerial challenge!", goalkeeper.fullName, nearestAttackerForContest.fullName));
                            return Enums.CrossOutcome.FoulByGK;
                    }
                }
                else // GK failed, but no attacker was close enough for a contest (rare, but possible)
                {
                    //ShowMessage("    The cross drifts past the goalkeeper, and no attacker was in position to contest!");
                    SetLooseBall(false, passer, deliveryType, AttackingTeam, DefendingTeam);
                    return Enums.CrossOutcome.LooseBall;
                }
            }
            // This line should ideally not be reached if all branches return.
            return Enums.CrossOutcome.CrossMissed; // Fallback
        }

        /// <summary>
        /// Goalkeeper decides whether to come out to catch/punch a cross or stay on his line.
        /// </summary>
        private Enums.GKCrossAction DecideGoalkeeperCrossInterception(Player goalkeeper, double crossQuality, Enums.PitchZone targetZone, bool isHomeAttacking)
        {
            // Factors influencing the GK's decision to come out
            double comeOutChance = goalkeeper.trueRating.PhysicalityForGameCalculations * 0.4 +
                                   goalkeeper.trueRating.JumpingForGameCalculations * 0.2 +
                                   goalkeeper.trueRating.PositioningForGameCalculations * 0.2 +
                                   goalkeeper.trueRating.AggressionForGameCalculations * 0.2;

            comeOutChance += crossQuality * 0.2;

            if (!((isHomeAttacking && (targetZone == Enums.PitchZone.PenaltyArea_Away || targetZone == Enums.PitchZone.GoalkeeperArea_Away)) ||
                  (!isHomeAttacking && (targetZone == Enums.PitchZone.PenaltyArea_Home || targetZone == Enums.PitchZone.GoalkeeperArea_Home))))
            {
                return Enums.GKCrossAction.None;
            }

            comeOutChance -= (100 - goalkeeper.trueRating.ComposureForGameCalculations) * 0.1;
            comeOutChance = Math.Max(0, Math.Min(100, comeOutChance));

            if (Dice.d100() < comeOutChance)
            {
                double catchChance = goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.6 +
                                     goalkeeper.trueRating.JumpingForGameCalculations * 0.4;
                catchChance -= crossQuality * 0.1;
                catchChance = Math.Max(10, Math.Min(90, catchChance));

                if (Dice.d100() < catchChance)
                {
                    return Enums.GKCrossAction.Catch;
                }
                else
                {
                    return Enums.GKCrossAction.Punch;
                }
            }
            else
            {
                return Enums.GKCrossAction.None;
            }
        }

        private void DecideGoalkeeperAction(Player goalkeeper, Player ballCarrier, Team defendingTeam, Team attackingTeam)
        {
            if (goalkeeper.IsInjured || goalkeeper.isSentOff)
            {
                return;
            }

            bool isHomeDefendingTeam = (HomeTeam == defendingTeam); // Renamed for clarity
            bool ballIsInDangerousGKArea = IsZoneDangerous(ballCarrier.CurrentZone, attackingTeam == HomeTeam);
            bool attackerThroughOnGoal = (ballIsInDangerousGKArea &&
                                          (ballCarrier.Position == Enums.Positions.Striker || ballCarrier.Position == Enums.Positions.CentralAttackingMidfielder) &&
                                          !defendingTeam.AvailableOnFieldOutfielders.Any(p => p != goalkeeper && p != ballCarrier && IsAdjacentZone(p.CurrentZone, ballCarrier.CurrentZone)));

            // --- 2. Sweeper Keeper Logic ---
            if (attackerThroughOnGoal || ballIsInDangerousGKArea || defendingTeam.SweeperKeeperStyle != Enums.SweeperKeeperStyle.Conservative)
            {
                double sweeperTendencyChance = (goalkeeper.trueRating.GoalKeepingReflexesForGameCalculations * 0.3) +
                                               (goalkeeper.trueRating.PositioningForGameCalculations * 0.3) +
                                               (goalkeeper.trueRating.ComposureForGameCalculations * 0.2) +
                                               (goalkeeper.trueRating.AggressionForGameCalculations * 0.1) +
                                               (goalkeeper.trueRating.SprintForGameCalculations * 0.1);

                // --- Determine the effective defensive line zone ---
                Enums.PitchZone effectiveDefensiveLineZone = Enums.PitchZone.None;

                int maxDefensiveY = isHomeDefendingTeam ? -99 : 99; // Initialize to impossible values
                Player deepestDefender = null;

                foreach (Player defender in defendingTeam.AvailableOnFieldOutfielders)
                {
                    ZoneCoordinate defenderCoords = GetZoneCoords(defender.CurrentZone);
                    if (isHomeDefendingTeam) // Home team defends, deepest is max Y (closest to their goal for this coordinate system)
                    {
                        if (defenderCoords.Y > maxDefensiveY)
                        {
                            maxDefensiveY = defenderCoords.Y;
                            deepestDefender = defender;
                        }
                    }
                    else // Away team defends, deepest is min Y (closest to their goal for this coordinate system)
                    {
                        if (defenderCoords.Y < maxDefensiveY)
                        {
                            maxDefensiveY = defenderCoords.Y;
                            deepestDefender = defender;
                        }
                    }
                }

                if (deepestDefender != null)
                {
                    effectiveDefensiveLineZone = deepestDefender.CurrentZone;
                }
                else
                {
                    effectiveDefensiveLineZone = isHomeDefendingTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                }

                // Now, modify this base chance based on team style
                switch (defendingTeam.SweeperKeeperStyle)
                {
                    case Enums.SweeperKeeperStyle.Conservative:
                        sweeperTendencyChance *= 0.6;
                        if (!attackerThroughOnGoal) sweeperTendencyChance -= 20;
                        break;
                    case Enums.SweeperKeeperStyle.Standard:
                        break;
                    case Enums.SweeperKeeperStyle.Aggressive:
                        sweeperTendencyChance *= 1.4;
                        // Use GetTeamSpecificDefensiveZone for the 'zone behind' check
                        Enums.PitchZone zoneBehindDefensiveLine = GetZoneBehind(effectiveDefensiveLineZone, isHomeDefendingTeam);
                        if (ballCarrier.CurrentZone == zoneBehindDefensiveLine && !attackerThroughOnGoal) sweeperTendencyChance += 15;
                        break;
                }

                sweeperTendencyChance = Math.Max(0, Math.Min(100, sweeperTendencyChance));

                if (Dice.d100() < sweeperTendencyChance)
                {
                    // Determine targetSweeperZone relative to the ball carrier
                    Enums.PitchZone targetSweeperZone = ballCarrier.CurrentZone;

                    ZoneCoordinate gkCoords = GetZoneCoords(goalkeeper.CurrentZone);
                    ZoneCoordinate ballCoords = GetZoneCoords(ballCarrier.CurrentZone);

                    int moveX = 0;
                    int moveY = 0;

                    if (gkCoords.X < ballCoords.X) moveX = 1;
                    else if (gkCoords.X > ballCoords.X) moveX = -1;

                    if (isHomeDefendingTeam) // Home team defends: GK moves to higher Y to get to ball
                    {
                        if (gkCoords.Y < ballCoords.Y) moveY = 1;
                    }
                    else // Away team defends: GK moves to lower Y to get to ball
                    {
                        if (gkCoords.Y > ballCoords.Y) moveY = -1;
                    }

                    // Removed isHomeDefending from GetZoneOffset call
                    Enums.PitchZone potentialZone = GetZoneOffset(goalkeeper.CurrentZone, moveX, moveY);

                    // The check GetZoneForwardValue(potentialZone, isHomeDefending) is still crucial
                    // This function likely interprets the 'forward' direction relative to the defending team's goal.
                    if (potentialZone != Enums.PitchZone.None &&
                        GetZoneForwardValue(potentialZone, isHomeDefendingTeam) <= GetZoneForwardValue(effectiveDefensiveLineZone, isHomeDefendingTeam) + 1)
                    {
                        if (potentialZone != Enums.PitchZone.None) // This check is redundant due to outer `if` but kept for existing structure
                        {
                            targetSweeperZone = potentialZone;
                        }
                    }

                    SetPlayerZone(goalkeeper, targetSweeperZone);

                    if (goalkeeper.CurrentZone == ballCarrier.CurrentZone || IsAdjacentZone(goalkeeper.CurrentZone, ballCarrier.CurrentZone))
                    {
                        AttemptGoalkeeperInterception(goalkeeper, ballCarrier, attackingTeam, defendingTeam);
                    }
                    return; // Goalkeeper acted as sweeper, end decision.
                }
                else
                {
                    //ShowMessage(string.Format("{0} ({1}) holds their line.", goalkeeper.fullName, defendingTeam.Name));
                }
            }

            // --- 3. Default Goalkeeper Positioning (If not sweeping) ---
            // This part does not use generic defensive zones, so it remains straightforward.
            Enums.PitchZone defaultGKZone = isHomeDefendingTeam ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;

            if (goalkeeper.CurrentZone != defaultGKZone)
            {
                //ShowMessage(string.Format("{0} ({1}) returns to their default position.", goalkeeper.fullName, defendingTeam.Name));
                SetPlayerZone(goalkeeper, defaultGKZone);
            }
        }

        /// <summary>
        /// Simulates a goalkeeper's attempt to save a shot, including handling of rebounds/corners.
        /// This method is called by your main shot processing logic (e.g., within AttemptShot).
        /// </summary>
        /// <param name="shooter">The player who shot the ball.</param>
        /// <param name="goalkeeper">The goalkeeper attempting the save.</param>
        /// <param name="attackingTeam">The team that shot.</param>
        /// <param name="defendingTeam">The team whose goalkeeper is saving.</param>
        /// <param name="shotZone">The PitchZone where the shot was taken.</param>
        /// <param name="shotPower">The calculated power of the shot (0-100).</param>
        /// <param name="shotAccuracy">The calculated accuracy/placement of the shot (0-100, higher is better).</param>
        /// <param name="isOneOnOne">True if this save attempt is from a one-on-one situation.</param> // Added parameter
        /// <returns>The outcome of the save (Saved, Goal, Rebound).</returns>
        private Enums.ShotOutcome AttemptGoalkeeperSave(Player shooter, Player goalkeeper, Team attackingTeam, Team defendingTeam, Enums.PitchZone shotZone, double shotPower, double shotAccuracy, bool isOneOnOne)
        {
            // Calculate base save chance based on GK attributes
            double saveChance = (goalkeeper.trueRating.GoalKeepingPositioningForGameCalculations * 0.5 +
                                 goalkeeper.trueRating.GoalKeepingReflexesForGameCalculations * 0.3 +
                                 goalkeeper.trueRating.GoalkeepingDivinghForGameCalculations * 0.1 +
                                 goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.1);

            double adjuster = 1.5;

            // Normalize to 0-100 scale for easier comparison with Dice
            // Assuming trueRating attributes are already on a 0-100 scale.
            // No need to divide by 100.0 here if the sum is already meant to be a 0-100 value.
            // If sum is higher than 100, adjust scaling. Let's assume values sum to reasonable range.

            // Difficulty increases with shooter's skill and shot quality
            double shooterSkillForSaveDifficulty = (shooter.trueRating.ShootingForGameCalculations * 0.7) + (shooter.trueRating.FinishingForGameCalculations * 0.3);
            // Scale shooter difficulty: higher skill of shooter REDUCES saveChance
            saveChance -= (shooterSkillForSaveDifficulty * 0.2);

            // Adjust for shot zone (shots from closer/central areas are harder to save)
            bool isAttackingPenaltyArea = (attackingTeam == HomeTeam && shotZone == Enums.PitchZone.PenaltyArea_Away) ||
                                          (attackingTeam == AwayTeam && shotZone == Enums.PitchZone.PenaltyArea_Home);
            bool isAttackingGoalkeeperArea = (attackingTeam == HomeTeam && shotZone == Enums.PitchZone.GoalkeeperArea_Away) ||
                                              (attackingTeam == AwayTeam && shotZone == Enums.PitchZone.GoalkeeperArea_Home);

            if (isAttackingGoalkeeperArea)
            {
                saveChance -= 15; // Shots from very close are extremely hard to save
            }
            else if (isAttackingPenaltyArea)
            {
                saveChance -= 5; // Shots from within the box are harder saves
            }

            // --- NEW: Adjust for 1-on-1 situation ---
            if (isOneOnOne)
            {
                // GKs have specific 1v1 attributes. A good 1v1 keeper is harder to beat.
                saveChance += goalkeeper.trueRating.GoalKeepingPositioningForGameCalculations * 0.15; // Bonus for 1v1 skill
                saveChance -= 10; // Overall 1v1s are harder to save than open play shots
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Debug,
                    EventType = MatchEventType.ShotOutcome,
                    Timestamp = DateTime.Now,

                    PlayerName1 = shooter.fullName,
                    Player1Pos = shooter.position,
                    TeamName1 = AttackingTeam.Name,
                    Player2Pos = goalkeeper.position,
                    PlayerName2 = goalkeeper.fullName,

                    ShotResult = ShotOutcomeSubType.SaveAdjustment,
                    Zone1 = CurrentBallZone,
                    Value1 = saveChance,
                    IsRebound = ReboundChance,
                    IsPoorDeflection = PoorDeflection,
                    IsGoodDeflection = GoodDeflection
                });
            }

            saveChance *= adjuster;

            // Clamp the final save chance within a realistic range (e.g., 40% to 99%)
            saveChance = Math.Max(40, Math.Min(99, saveChance));

            // Roll the dice to determine if the save is made
            int saveRoll = Dice.d100();

            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.ShotOutcome,
                Timestamp = DateTime.Now,

                PlayerName1 = shooter.fullName,
                Player1Pos = shooter.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,
                PlayerName2 = goalkeeper.fullName,
                Player2Pos = goalkeeper.position,

                Zone1 = CurrentBallZone,
                Value1 = saveChance,
                Value2 = shotPower,
                IsRebound = ReboundChance,
                IsPoorDeflection = PoorDeflection,
                IsGoodDeflection = GoodDeflection
            };

            if (ReboundChance)
            {
                if (GoodDeflection)
                    saveChance -= 3;
                else if (PoorDeflection)
                    saveChance -= 12; // arbitary - to make more shots on goal after rebound.
            }

            if (saveRoll < saveChance) // If roll is within the save chance
            {
                goalkeeper.gameStats.IncreaseSaves();
                if (defendingTeam == HomeTeam)
                    HomeSaves++;
                else
                    AwaySaves++;
                this.CheckForErrorNegation(goalkeeper, CurrentSecond);
                ShotBlockType saveType = ShotBlockType.GoalkeeperDeflection;

                // Determine the outcome of the save (clean catch, parry to safety, or rebound)
                double handlingSkill = goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations;
                double divingSkill = goalkeeper.trueRating.GoalkeepingDivinghForGameCalculations;
                double gkComposure = goalkeeper.trueRating.ComposureForGameCalculations;

                // Higher control score means cleaner save
                double controlScore = handlingSkill * 0.6 + gkComposure * 0.2 + divingSkill * 0.2;

                // Shot power and accuracy make it harder to control the save
                controlScore -= (shotPower * 0.2);
                controlScore -= (shotAccuracy * 0.1);

                controlScore = Math.Max(10, Math.Min(100, controlScore)); // Clamp control score

                int saveOutcomeRoll = Dice.d100();

                if (saveOutcomeRoll < controlScore * 0.6) // High control: clean catch
                {
                    //SetPossession(goalkeeper, GetPlayerZone(goalkeeper), defendingTeam); // GK gains possession
                    me.ShotBlockerType = ShotBlockType.GoalkeeperCatch;
                    me.ShotResult = ShotOutcomeSubType.Saved;
                    LogEntry(me);
                    CurrentMatchState = Enums.MatchState.GoalkeeperRecycle; // handle gk handler should set possession properly
                    return Enums.ShotOutcome.Saved;
                }
                else if (saveOutcomeRoll < controlScore * 1.0) // Medium control: parry, potentially for a corner
                {
                    // Even if parried, a good GK might try to parry wide for a corner
                    if (Dice.d100() < (divingSkill * 0.7 + gkComposure * 0.3)) // Chance to parry wide
                    {
                        me.ShotBlockerType = ShotBlockType.GoalkeeperDeflectionForCorner;
                        me.ShotResult = ShotOutcomeSubType.Saved;
                        LogEntry(me);
                        //SetLooseBall(); // Ball becomes loose, your game would then trigger a corner kick event
                        // Need to set the specific CornerKick state and zone for the attacking team
                        CurrentMatchState = (attackingTeam == HomeTeam) ? Enums.MatchState.CornerKick : Enums.MatchState.CornerKick;
                        // You'll need to set CurrentBallZone to the appropriate corner flag (e.g., Corner_AwayLeft/Right)
                        // This logic might be better handled in SetMatchStateForOutOfBounds with a 'corner' reason.
                        return Enums.ShotOutcome.Saved; // Still considered a save, but leads to set piece
                    }
                    else
                    {
                        me.ShotBlockerType = ShotBlockType.GoalkeeperDeflection;
                        me.ShotResult = ShotOutcomeSubType.Saved;
                        this.GoodDeflection = true;
                        me.IsGoodDeflection = true;
                        LogEntry(me);
                        SetLooseBall(false, goalkeeper, CornerDeliveryType.None, AttackingTeam, DefendingTeam, true, false, GoodDeflection); // Ball is loose and dangerous, assume not high unless explicitly set
                        return Enums.ShotOutcome.Rebound;
                    }
                }
                else // Low control: bad parry, very dangerous rebound or own goal
                {
                    // --- NEW: Own Goal Check for Fumbled Save ---
                    if (DetermineOwnGoalOccurred(goalkeeper, defendingTeam, GetPlayerZone(goalkeeper), isFromShotAttempt: true))
                    {
                        me.ShotBlockerType = ShotBlockType.GoalkeeperPoorDeflection;
                        me.ShotResult = ShotOutcomeSubType.Saved;
                        me.IsOwnGoal = true;
                        this.PoorDeflection = true;
                        me.IsPoorDeflection = true;
                        LogEntry(me);
                        UpdateScore(null, null, goalkeeper, false);
                        return Enums.ShotOutcome.Goal; // Ensure ShotOutcome enum has OwnGoal
                    }
                    else
                    {
                        me.ShotBlockerType = ShotBlockType.GoalkeeperPoorDeflection;
                        me.ShotResult = ShotOutcomeSubType.Saved;
                        this.PoorDeflection = true;
                        me.IsPoorDeflection = true;
                        LogEntry(me);
                        _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(goalkeeper, CurrentSecond));
                        SetLooseBall(false, goalkeeper, CornerDeliveryType.None, AttackingTeam, DefendingTeam, true, PoorDeflection); // Ball is loose and dangerous, assume not high unless explicitly set
                        return Enums.ShotOutcome.Rebound;
                    }
                }
            }
            else // Shot is not saved (it's a goal!)
            {
                me.ShotResult = ShotOutcomeSubType.Goal;
                int diceLocale = Dice.d100();
                if (diceLocale < 40)
                    me.ShotTarget = ShotTargetType.TopCorner;
                else if (diceLocale < 80)
                    me.ShotTarget = ShotTargetType.BottomCorner;
                else if (diceLocale < 97)
                    me.ShotTarget = ShotTargetType.MiddleOfNet;
                else if (diceLocale < 99)
                    me.ShotTarget = ShotTargetType.Post;
                else
                    me.ShotTarget = ShotTargetType.Crossbar;
                if (_lastPasser != null && !ReboundChance)
                {
                    me.PlayerName2 = _lastPasser.fullName;
                    me.Player2Pos = _lastPasser.position;
                }
                else
                {
                    me.PlayerName2 = null;
                    me.Player2Pos = null;
                    me.TeamName2 = null;
                }
                LogEntry(me);
                UpdateScore(_lastPasser, shooter, goalkeeper, false); // Your existing UpdateScore, pass GK for stats if needed
                CurrentMatchState = Enums.MatchState.GoalScored;
                // Reset possession for kickoff (assuming first player of defending team will take kickoff)
                return Enums.ShotOutcome.Goal;
            }
        }

        /// <summary>
        /// Simulates a one-on-one situation between an attacker and the goalkeeper.
        /// The attacker decides to shoot or dribble past.
        /// </summary>
        /// <param name="attacker">The attacking player through on goal.</param>
        /// <param name="goalkeeper">The defending goalkeeper.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <returns>The outcome of the one-on-one situation.</returns>
        private Enums.ShotOutcome SimulateOneOnOne(Player attacker, Player goalkeeper, Team attackingTeam, Team defendingTeam)
        {
            // Attacker's decision: Shoot or Dribble past?
            // Based on attacker's finishing, dribbling, composure, situation (e.g., how close to goal)
            double shootChance = (attacker.trueRating.FinishingForGameCalculations * 0.4) +
                                 (attacker.trueRating.ComposureForGameCalculations * 0.3) +
                                 (attacker.trueRating.ShootingForGameCalculations * 0.3); // High shooting for direct shot

            double dribbleChance = (attacker.trueRating.DribblingForGameCalculations * 0.4) +
                                   (attacker.trueRating.AgilityForGameCalculations * 0.3) +
                                   (attacker.trueRating.BalanceForGameCalculations * 0.2) +
                                   (attacker.trueRating.ComposureForGameCalculations * 0.1);

            // Make shooting more likely unless dribbling is much higher
            if (dribbleChance > shootChance + 10) // Dribbling significantly better
            {
                shootChance -= 15; // Incentivize dribbling
            }
            else
            {
                dribbleChance -= 10; // Incentivize shooting if balanced
            }

            shootChance = Math.Max(20, Math.Min(80, shootChance)); // Clamp shoot chance
            dribbleChance = Math.Max(10, Math.Min(60, dribbleChance)); // Clamp dribble chance

            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PlayerMoved,
                Timestamp = DateTime.Now,
                DribblePhase = DribblePhaseType.OneOnOneWithKeeper,

                PlayerName1 = attacker.fullName,
                Player1Pos = attacker.position,
                PlayerName2 = goalkeeper.fullName,
                Player2Pos = goalkeeper.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,

                Zone1 = CurrentBallZone,
                Value1 = shootChance,
                Value2 = dribbleChance
            };

            bool attackerDecidesToShoot = Dice.d100() < shootChance;

            if (attackerDecidesToShoot)
            {
                me.DribbleResult = DribbleResultType.ShotAttempt;
                LogEntry(me);
                // shot attempt will be logged in Attempt shot.
                // Call AttemptShot for a 1v1 situation.
                // You'll need to modify AttemptShot to accept an 'isOneOnOne' parameter.
                // This will influence the GK's save chance (often harder save for 1v1).
                Enums.ShotOutcome shotOutcome = AttemptShot(attacker, attackingTeam, defendingTeam, Enums.ShotType.Normal, false, null); // assuming 'isSetPiece' is false, 'assister' is null for 1v1 direct shot

                return shotOutcome; // Returns goal, save, miss etc.
            }
            else // Attacker decides to dribble past the keeper
            {
                // Simulate dribble past GK
                double dribblePastGKChance = attacker.trueRating.DribblingForGameCalculations * 0.6 + attacker.trueRating.AgilityForGameCalculations * 0.4;
                dribblePastGKChance -= goalkeeper.trueRating.GoalKeepingReflexesForGameCalculations * 0.5; // GK's 1v1 ability
                dribblePastGKChance -= goalkeeper.trueRating.AggressionForGameCalculations * 0.2; // Brave GKs are harder to beat

                // --- NEW: Check for Goalkeeper Charging Foul during dribble attempt ---
                // This is a direct confrontation during the dribble
                if (SimulateGoalkeeperCharge(goalkeeper, attacker, attacker.CurrentZone))
                {
                    me.DribbleResult = DribbleResultType.GKFoul;
                    LogEntry(me);
                    // Minor for now so the goalkeeper doesn't get red carded.
                    ProcessFoul(goalkeeper, attacker, FoulType.Minor, true, AttackingTeam);
                    // If foul occurred, ProcessFoul already handled setting the state etc.
                    return Enums.ShotOutcome.FoulByGK; // Use an outcome that reflects a foul stopping the shot
                }
                // --- End NEW ---

                dribblePastGKChance = Math.Max(10, Math.Min(85, dribblePastGKChance));

                if (Dice.d100() < dribblePastGKChance)
                {
                    _potentialChanceCreatingActions.Add(new Tuple<Player, int>(attacker, CurrentSecond));
                    _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(goalkeeper, CurrentSecond));
                    me.DribbleResult = DribbleResultType.Success;
                    this.IncreaseShotCount(attacker, true, AttackingTeam);
                    LogEntry(me);
                    // Direct goal, as GK is beaten
                    UpdateScore(_lastPasser, attacker, goalkeeper, false); // Attacker scores, no assister for direct dribble
                    return Enums.ShotOutcome.Goal;
                }
                else
                {
                    me.DribbleResult = DribbleResultType.Fail;
                    LogEntry(me);
                    this.CheckForErrorNegation(goalkeeper, CurrentSecond);
                    CurrentMatchState = MatchState.GoalkeeperRecycle;
                    //SetPossession(goalkeeper, goalkeeper.CurrentZone, defendingTeam); // GK recovers ball
                    return Enums.ShotOutcome.Saved; // Count as a save as GK won the duel
                }
            }
        }

        /// <summary>
        /// Determines the likely PitchZone where a GK's punched or fumbled cross might land.
        /// </summary>
        /// <param name="goalkeeper">The goalkeeper who made the intervention.</param>
        /// <param name="originalCrossDeliveryType">The type of the cross that the GK intercepted.</param>
        /// <param name="isHighBall">True if the ball was high in the air (implying a punch or fumbled catch).</param>
        /// <param name="attackingTeam">The team that delivered the cross.</param>
        /// <param name="defendingTeam">The team whose goalkeeper is attempting to intercept.</param>
        /// <returns>The estimated PitchZone where the ball lands.</returns>
        private Enums.PitchZone DetermineGKClearanceLandingZone(Player goalkeeper, Enums.CornerDeliveryType originalCrossDeliveryType, bool isHighBall, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DetermineGKClearanceLandingZone: goalkeeper:{0},originalCrossDeliveryType:{1}," +
            //    "isHighBall:{2},attackingTeam:{3},defendingTeam:{4}",
            //    goalkeeper.position, originalCrossDeliveryType, isHighBall, attackingTeam.Name, defendingTeam.Name));


            // Determine the defending team's goal-side zones for context
            bool isHomeDefending = (defendingTeam == HomeTeam);

            // Assign specific penalty area zones based on the defending team
            Enums.PitchZone defensivePenaltyAreaHome = Enums.PitchZone.PenaltyArea_Home;
            Enums.PitchZone defensivePenaltyAreaAway = Enums.PitchZone.PenaltyArea_Away;
            Enums.PitchZone defensiveGoalkeeperAreaHome = Enums.PitchZone.GoalkeeperArea_Home;
            Enums.PitchZone defensiveGoalkeeperAreaAway = Enums.PitchZone.GoalkeeperArea_Away;

            Enums.PitchZone defendingPenaltyAreaCentral = isHomeDefending ? defensivePenaltyAreaHome : defensivePenaltyAreaAway;
            Enums.PitchZone defendingGoalkeeperArea = isHomeDefending ? defensiveGoalkeeperAreaHome : defensiveGoalkeeperAreaAway;
            Enums.PitchZone defensiveEdgeOfBox = Enums.PitchZone.Defensive_EdgeOfBox;

            // Flanks for safe clearances (these are still from the defending team's perspective)
            Enums.PitchZone safeLeftFlank = isHomeDefending ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_RightFlank;
            Enums.PitchZone safeRightFlank = isHomeDefending ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_LeftFlank;

            // Default to where the GK is (fumbled short) or central penalty area if not specified
            Enums.PitchZone defaultZone = goalkeeper.CurrentZone;
            if (goalkeeper.Team == AwayTeam)
            {
                defaultZone = defensiveGoalkeeperAreaAway;
            }
            else
            {
                defaultZone = defensiveGoalkeeperAreaHome;
            }

            // Adjust based on the GK's attributes and the type of intervention
            double controlModifier = (goalkeeper.trueRating.GoalKeepingHandlingForGameCalculations * 0.4 + goalkeeper.trueRating.ComposureForGameCalculations * 0.6);
            double powerModifier = (goalkeeper.trueRating.StrengthForGameCalculations * 0.5 + goalkeeper.trueRating.GoalKeepingKickingForGameCalculations * 0.5); // Using GoalKicking for clearing power

            // Factor in cross delivery type for direction/difficulty
            double crossInfluenceModifier = 0;
            if (originalCrossDeliveryType == Enums.CornerDeliveryType.InswingerLofted || originalCrossDeliveryType == Enums.CornerDeliveryType.InswingerDriven)
            {
                // Inswingers curve towards goal, harder to clear wide, more likely to stay central
                crossInfluenceModifier = -10;
            }
            else if (originalCrossDeliveryType == Enums.CornerDeliveryType.OutswingerLofted || originalCrossDeliveryType == Enums.CornerDeliveryType.OutswingerDriven)
            {
                // Outswingers curve away, easier to clear wide
                crossInfluenceModifier = 10;
            }

            // A slightly more nuanced roll comparison for controlled vs. uncontrolled
            int controlRoll = Dice.d100();
            bool controlledClearance = controlRoll < (controlModifier + crossInfluenceModifier);

            if (isHighBall) // This is specifically for punches/fumbles from crosses
            {
                if (controlledClearance)
                {
                    //ShowMessage("    (GK makes a controlled clearance!)");
                    // Try to clear it wide or far
                    if (Dice.d100() < 60 + (powerModifier * 0.2)) // Power influences how far
                    {
                        // Clear to a safer flank zone in their own half or midfield
                        if (Dice.d100() < 50)
                        {
                            return safeLeftFlank;
                        }
                        else
                        {
                            return safeRightFlank;
                        }
                    }
                    else // Go further upfield to midfield
                    {
                        // CORRECTED: Using Midfield_Center as per your enum
                        return Enums.PitchZone.Midfield_Center;
                    }
                }
                else // Uncontrolled clearance (fumbled catch or poor punch)
                {
                    //ShowMessage("    (GK makes an uncontrolled clearance!)");
                    // Ball stays in or near the box, potentially to an opponent
                    if (Dice.d100() < 70 - (controlModifier * 0.2)) // Higher chance to stay dangerous if control is bad
                    {
                        // Land in a dangerous penalty area zone
                        if (Dice.d100() < 30) // Near post
                        {
                            return isHomeDefending ? Enums.PitchZone.DefensivePenaltyArea_LeftNearPost : Enums.PitchZone.DefensivePenaltyArea_RightNearPost;
                        }
                        else if (Dice.d100() < 60) // Far post
                        {
                            return isHomeDefending ? Enums.PitchZone.DefensivePenaltyArea_RightFarPost : Enums.PitchZone.DefensivePenaltyArea_LeftFarPost;
                        }
                        else // Central
                        {
                            return Enums.PitchZone.DefensivePenaltyArea_Central;
                        }
                    }
                    else // Just outside the box or short midfield
                    {
                        return defensiveEdgeOfBox;
                    }
                }
            }
            // Default fallback if not a high ball from GK
            return defaultZone;
        }

        /// <summary>
        /// Determines if the given attacking player is on a clear breakaway, facing only the goalkeeper.
        /// This means no outfield defenders are between the attacker and the goal within a critical distance.
        /// </summary>
        /// <param name="attacker">The player with the ball.</param>
        /// <param name="defendingTeam">The opposing team (whose goalkeeper the attacker is facing).</param>
        /// <param name="currentBallZone">The current zone of the ball.</param>
        /// <returns>True if it's a breakaway, false otherwise.</returns>
        private bool IsAttackerOnBreakaway(Player attacker, Team defendingTeam, Enums.PitchZone currentBallZone)
        {
            bool isAttackingTeamHome = (attacker.Team == HomeTeam);

            // 1. Attacker must be in a threatening attacking zone.
            // Use GetZoneForwardValue to check if the attacker's zone is sufficiently advanced.
            int attackerForwardValue = GetZoneForwardValue(currentBallZone, isAttackingTeamHome);

            // Define a minimum forward value for a zone to be considered "threatening" for a breakaway.
            // Based on your GetZoneForwardValue:
            // HomeDefense: 0-2 (or 1 for corners/penalty)
            // Midfield: 4
            // AwayAttack: 6
            // PenaltyArea_Away: 8
            // GoalkeeperArea_Away: 9
            // A value of 6 or higher (AwayAttack, PenaltyArea, GoalkeeperArea_Away from Home perspective) seems appropriate for a breakaway.
            const int MIN_BREAKAWAY_FORWARD_VALUE = 6;

            if (attackerForwardValue < MIN_BREAKAWAY_FORWARD_VALUE)
            {
                // Not in a forward enough position to be a breakaway
                return false;
            }

            // 2. Check for outfield defenders being "between" the attacker and the goal.
            // Iterate through all outfield defenders of the defending team.
            foreach (Player defender in defendingTeam.AvailableOnFieldOutfielders)
            {
                // Skip injured/sent-off players and the goalkeeper
                if (defender.IsInjured || defender.isSentOff || defender.Position == Enums.Positions.Goalkeeper)
                {
                    throw new Exception("no defender?");
                }

                Enums.PitchZone defenderZone = GetPlayerZone(defender);

                // Calculate conceptual distance between defender and attacker's ball zone using your CalculateDistance
                int distanceToAttacker = CalculateDistance(defenderZone, currentBallZone);

                // Define a "critical distance" for an outfield defender to prevent a breakaway.
                // A defender within this distance AND "between" the attacker and goal will stop the breakaway.
                // You can adjust this threshold (e.g., 2, 3, or 4 units of Manhattan distance).
                // 3-4 might be a good starting point for "no nearby defenders" on a whole pitch.
                const int BREAKAWAY_DEFENDER_DISTANCE_THRESHOLD = 4; // Or 3, depends on your pitch scale

                if (distanceToAttacker <= BREAKAWAY_DEFENDER_DISTANCE_THRESHOLD)
                {
                    // If the defender is close, now check if they are "between" the attacker and the goal.
                    // A defender is "between" if their GetZoneForwardValue is greater than or equal to the attacker's.
                    // This means they are either at the same forward level or further up the pitch (closer to the goal).
                    int defenderForwardValue = GetZoneForwardValue(defenderZone, isAttackingTeamHome);

                    // A defender is 'between' if they are more advanced or at the same level as the attacker
                    // This means they are effectively blocking the clear path to goal.
                    if (defenderForwardValue >= attackerForwardValue)
                    {
                        //ShowMessage(string.Format("{0} is NOT on a breakaway. Outfield defender {1} (Zone: {2}, ForwardValue: {3}) is near and in a blocking position (Attacker Zone: {4}, ForwardValue: {5}).",
                        //                            attacker.fullName, defender.fullName, defenderZone, defenderForwardValue, currentBallZone, attackerForwardValue));
                        return false; // This defender prevents a clear breakaway
                    }
                }
            }

            // If we've iterated through all outfield defenders and none are close enough AND in a blocking position,
            // then it's a clear breakaway against the goalkeeper.
            //ShowMessage(string.Format("{0} is on a clear breakaway against the goalkeeper!", attacker.fullName));
            return true;
        }

        private void HandleGoalkeeperDistribution(bool isGoalKick)
        {
            Enums.MatchState prevvms = CurrentMatchState;

            CleanPotentialAssistsCreatingActions();

            // --- 1. Choose a player to take the kick/distribution ---
            Player taker;
            Team possessingTeam;
            Team opposingTeam;

            if (isGoalKick)
            {
                possessingTeam = AttackingTeam; // AttackingTeam is already set for goal kicks
                opposingTeam = DefendingTeam;

                taker = possessingTeam.AvailableOnFieldPlayers
                            .FirstOrDefault(p => p.Position == Enums.Positions.Goalkeeper)
                            ?? possessingTeam.AvailableOnFieldPlayers
                            .FirstOrDefault(p => p.Position == Enums.Positions.CenterBack); // Fallback for goal kick
                if (taker == null)
                {
                    throw new Exception("ERROR: No suitable player found to take the goal kick!");
                }
                // For a formal goal kick, possession must be explicitly set to the kicker in the GK area.
                taker.CurrentZone = GetPlayerGoalkeeperArea(taker);
                SetPossession(taker, taker.CurrentZone, possessingTeam);
            }
            else // It's a goalkeeper distribution after a clean save
            {
                possessingTeam = DefendingTeam; // DefendingTeam now has the ball
                opposingTeam = AttackingTeam;

                this.SetPossession(possessingTeam.GoalKeeper, GetPlayerGoalkeeperArea(possessingTeam.GoalKeeper), possessingTeam);

                taker = CurrentBallHolder; // The GK who just made the save

                if (taker == null || taker.Position != Enums.Positions.Goalkeeper)
                {
                    throw new Exception("ERROR: HandleGoalkeeperDistribution called for save, but CurrentBallHolder is not the GK!");
                }
            }

            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }

            // --- 2. Position Players for Distribution ---
            foreach (Player player in HomeTeam.AvailableOnFieldPlayers.Concat(AwayTeam.AvailableOnFieldPlayers))
            {
                if (player == taker)
                {
                    continue;
                }
                else if (player.Team == opposingTeam) // Opposing team players
                {
                    if (isGoalKick)
                    {
                        // Goal kick rule: Opponents must be outside the penalty area.
                        player.CurrentZone = Enums.PitchZone.Defensive_EdgeOfBox;
                    }
                    else
                    {
                        // GK distribution after save: Opponents might press or retreat.
                        // A simple approach: attackers might press high, others fall back to general positions.
                        if ((player.Position == Enums.Positions.Striker
                            || player.Position == Enums.Positions.LeftWingForward || player.Position == Enums.Positions.RightWingForward
                            || player.Position == Enums.Positions.CentralAttackingMidfielder)
                            && Dice.d100() < 60) // High chance attackers press
                        {
                            // Press closer to the GK's area (e.g., opponent's defensive third)
                            if (opposingTeam == HomeTeam) // Home attacking, away pressing
                            {
                                player.CurrentZone = Enums.PitchZone.AwayAttack_Center;
                            }
                            else // Away attacking, home pressing
                            {
                                player.CurrentZone = Enums.PitchZone.HomeDefense_Center;
                            }
                        }
                        else
                        {
                            player.CurrentZone = GetZoneForPlayerInFormation(player.Position, possessingTeam.CurrentFormation, possessingTeam == HomeTeam); // General defensive position
                        }
                    }
                }
                else // Possessing Team players (who are not the taker)
                {
                    // Players spread out to offer options. The logic for short/long options
                    // remains similar for both goal kicks and GK distributions.
                    if (player.Position == Enums.Positions.CenterBack || player.Position == Enums.Positions.LeftBack
                        || player.Position == Enums.Positions.RightBack)
                    {
                        if (player.Team == HomeTeam)
                        {
                            player.CurrentZone = Enums.PitchZone.HomeDefense_Center;
                        }
                        else
                        {
                            player.CurrentZone = Enums.PitchZone.AwayAttack_Center;
                        }
                    }
                    else if (player.Position == Enums.Positions.CentralMidfielder || player.Position == Enums.Positions.CentralDefendingMidfielder)
                    {
                        player.CurrentZone = Enums.PitchZone.Midfield_Center;
                    }
                    else if (player.Position == Enums.Positions.Striker || player.Position == Enums.Positions.LeftWingForward || player.Position == Enums.Positions.RightWingForward)
                    {
                        if (player.Team == HomeTeam)
                        {
                            player.CurrentZone = Enums.PitchZone.AwayAttack_Center;
                        }
                        else
                        {
                            player.CurrentZone = Enums.PitchZone.HomeDefense_Center;
                        }
                    }
                    //ShowMessage(player.fullName + " (" + player.Team.Name + ") moves to offer a passing option.");
                }
            }

            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }

            // --- 3. Determine a target receiver and pass type ---
            Player receiver;
            Enums.PassType passType;

            if (isGoalKick)
            {
                // For goal kicks, we still use GetBestGoalKickReceiver
                receiver = GetBestGoalKickReceiver(taker, possessingTeam, opposingTeam);

                // Determine pass type for goal kick (your existing logic)
                bool isReceiverInDefensiveZone = false;
                if (possessingTeam == HomeTeam)
                {
                    isReceiverInDefensiveZone = (receiver.CurrentZone == Enums.PitchZone.HomeDefense_Center ||
                                                 receiver.CurrentZone == Enums.PitchZone.HomeDefense_LeftFlank ||
                                                 receiver.CurrentZone == Enums.PitchZone.HomeDefense_RightFlank);
                }
                else
                {
                    isReceiverInDefensiveZone = (receiver.CurrentZone == Enums.PitchZone.AwayAttack_Center ||
                                                 receiver.CurrentZone == Enums.PitchZone.AwayAttack_LeftFlank ||
                                                 receiver.CurrentZone == Enums.PitchZone.AwayAttack_RightFlank);
                }

                if (isReceiverInDefensiveZone && taker.trueRating.ShortPassForGameCalculations > 60)
                {
                    passType = Enums.PassType.Short;
                }
                else
                {
                    passType = Enums.PassType.Long; // Default to long for goal kicks
                }

                //ShowMessage(taker.fullName + " opts for a " + (passType == Enums.PassType.Short ? "short goal kick" : "long goal kick" + " to " + receiver.fullName + "."));
            }
            else // Goalkeeper distribution after a save
            {
                // --- Determine immediate pressure on the Goalkeeper (Taker) ---
                Player nearestDefenderToGK = FindNearestDefender(taker, opposingTeam, taker.CurrentZone);
                double gkPressureModifier = 0;
                if (nearestDefenderToGK != null && !nearestDefenderToGK.IsInjured && !nearestDefenderToGK.isSentOff)
                {
                    // Use your CalculateDistance method here!
                    double distanceToGK = CalculateDistance(taker.CurrentZone, nearestDefenderToGK.CurrentZone);

                    // If a defender is very close (e.g., in the same or adjacent zone)
                    if (distanceToGK <= 1) // "1" meaning adjacent zone, "0" meaning same zone
                    {
                        double defenderInfluence = (nearestDefenderToGK.trueRating.DefenseAwarenessForGameCalculations * 0.5) +
                                                   (nearestDefenderToGK.trueRating.DefendingForGameCalculations * 0.5); // Use a 'Pressing' stat if available, otherwise StandTackle.
                        gkPressureModifier = (defenderInfluence / 5.0); // Apply a penalty based on defender's influence
                        //ShowMessage(string.Format("  ({0} is under immediate pressure from {1}.)", taker.fullName, nearestDefenderToGK.fullName));
                    }
                }


                // This is the main point of differentiation: GK decides between short throw/pass or long kick.
                // Factors: GK's abilities, tactical instructions, and immediate pressure.
                double shortDistributionChance = taker.trueRating.GoalKeepingHandlingForGameCalculations * 0.7 + taker.trueRating.ShortPassForGameCalculations * 0.3;

                // Adjust based on opposing team aggression (general tactical pressure)
                shortDistributionChance -= (opposingTeam.CurrentPressingTrigger == Enums.PressingTrigger.Intense) ? 15 : 0;

                // Apply immediate pressure from nearest defender
                shortDistributionChance -= gkPressureModifier; // A higher modifier means a lower chance of short distribution

                if (Dice.d100() < shortDistributionChance)
                {
                    passType = Enums.PassType.Short;
                    // For short passes, GetBestGoalKickReceiver should naturally prioritize closer targets
                    receiver = GetBestGoalKickReceiver(taker, possessingTeam, opposingTeam);
                    //ShowMessage(taker.fullName + " opts for a quick, short distribution to " + receiver.fullName + ".");
                }
                else
                {
                    passType = Enums.PassType.Long;
                    // For long passes, GetBestGoalKickReceiver should naturally prioritize further targets
                    receiver = GetBestGoalKickReceiver(taker, possessingTeam, opposingTeam);
                    //ShowMessage(taker.fullName + " launches a long distribution towards " + receiver.fullName + ".");
                }
            }

            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }

            if (receiver == null)
            {
                throw new Exception("No receivers found after goal kick.");
                //ShowMessage(taker.fullName + " has no clear target for the " + (isGoalKick ? "goal kick" : "distribution") + "! Ball is loose.");
                //SetLooseBall(false, taker, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                //return;
            }

            // --- 4. Simulate the kick using AttemptPass ---
            // For both goal kicks and clean GK catches, it's a controlled distribution, so isSetPiece and isFixedSetPiece are true.
            ResetPlayerPositionsToInPlay();
            Enums.MatchState previousMatchState = CurrentMatchState;
            MatchEntry me = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PassOutcome, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = taker.fullName,
                Player1Pos = taker.position,
                Player2Pos = receiver.position,
                PlayerName2 = receiver.fullName,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,

                Zone1 = taker.CurrentZone,
                Zone2 = receiver.CurrentZone
            };

            if (isGoalKick) me.PassStyle = PassStyleType.GoalKick; else me.PassStyle = PassStyleType.GKRecycle;
            LogEntry(me);

            Enums.PassOutcome passOutcome = AttemptPass(taker, possessingTeam, opposingTeam, passType, receiver, true, true);
            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }
            if (previousMatchState == CurrentMatchState)
            {
                if (passOutcome != Enums.PassOutcome.OutOfBounds)
                {
                    ConvertPassResultToMatchCondition(passOutcome, taker, passType == PassType.Long);
                }
            }
        }

        /// <summary>
        /// Determines the best player to receive a goal kick.
        /// Prioritizes players based on positioning, passing ability of kicker, and potential to win aerial duels.
        /// </summary>
        /// <param name="kicker">The player taking the goal kick (usually GK or CB).</param>
        /// <param name="attackingTeam">The team taking the goal kick.</param>
        /// <param name="defendingTeam">The opposing team.</param>
        /// <returns>The best available player to receive the goal kick, or null if no good option.</returns>
        private Player GetBestGoalKickReceiver(Player kicker, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestGoalKickReceiver: kicker:{0},attackingTeam:{1},defendingTeam:{2}",
            //    kicker.position, attackingTeam.Name, defendingTeam.Name));


            var eligibleReceivers = attackingTeam.AvailableOnFieldOutfielders
                .Where(p => p != kicker);

            // Strategy 1: Look for short pass options (CBs/FBs in defensive third, less marked)
            var shortPassTargetZones = new List<Enums.PitchZone>();
            if (attackingTeam == HomeTeam)
            {
                shortPassTargetZones.Add(Enums.PitchZone.HomeDefense_Center);
                shortPassTargetZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                shortPassTargetZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
            }
            else // Away team is kicking from their own goal (GoalkeeperArea_Away)
            {
                // Their defensive third zones are AwayAttack_X
                shortPassTargetZones.Add(Enums.PitchZone.AwayAttack_Center);
                shortPassTargetZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                shortPassTargetZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
            }

            var shortPassOptions = eligibleReceivers
                .Where(p => shortPassTargetZones.Contains(p.CurrentZone))
                .OrderByDescending(p => p.trueRating.ShootingForGameCalculations + p.trueRating.ComposureForGameCalculations);

            if (shortPassOptions.Any() && kicker.trueRating.ShortPassForGameCalculations > 60)
            {
                return shortPassOptions.FirstOrDefault();
            }

            // Strategy 2: Look for long pass options (CMs/STs/WFs in midfield or attacking third)
            var longPassTargetZones = new List<Enums.PitchZone>
    {
        Enums.PitchZone.Midfield_Center,
        Enums.PitchZone.Midfield_LeftFlank,
        Enums.PitchZone.Midfield_RightFlank
    };
            // Add the *attacking third* for the kicking team.
            if (attackingTeam == HomeTeam)
            {
                longPassTargetZones.Add(Enums.PitchZone.AwayAttack_Center);
                longPassTargetZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                longPassTargetZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
            }
            else // Away team is kicking, their attacking third is near the Home goal
            {
                longPassTargetZones.Add(Enums.PitchZone.HomeDefense_Center); // These are the zones near the Home goal
                longPassTargetZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                longPassTargetZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
            }

            var longPassOptions = eligibleReceivers
                .Where(p => longPassTargetZones.Contains(p.CurrentZone))
                .OrderByDescending(p => p.trueRating.HeaderForGameCalculations * 0.4 +
                                        p.trueRating.PositioningForGameCalculations * 0.3 +
                                        p.trueRating.FinishingForGameCalculations * 0.2 +
                                        p.trueRating.AggressionForGameCalculations * 0.1);

            if (longPassOptions.Any())
            {
                return longPassOptions.FirstOrDefault();
            }

            // Fallback: If no good options based on preferred strategies, just pick any available player who can receive
            return eligibleReceivers
                .OrderByDescending(p => p.trueRating.ShortPassForGameCalculations)
                .FirstOrDefault();
        }

        /// <summary>
        /// Simulates a potential goalkeeper charging foul when the GK challenges an opponent for the ball.
        /// This should be called when a GK attempts to rush out and intercept/clear a ball disputed by an opponent.
        /// </summary>
        /// <param name="goalkeeper">The goalkeeper attempting the challenge.</param>
        /// <param name="opponent">The opponent disputing the ball with the goalkeeper.</param>
        /// <param name="contestZone">The PitchZone where the potential charge occurs.</param>
        /// <returns>True if a charging foul occurred, false otherwise.</returns>
        private bool SimulateGoalkeeperCharge(Player goalkeeper, Player opponent, Enums.PitchZone contestZone)
        {
            // A charging foul is more likely if:
            // - Goalkeeper has high aggression, bravery, but low discipline or composure.
            // - Goalkeeper is rushing out quickly and aggressively.
            // - The opponent is skilled at anticipating/getting to the ball (making the GK's challenge more desperate).

            double foulChance = 0;

            // Goalkeeper's attributes
            foulChance += goalkeeper.trueRating.AggressionForGameCalculations * 0.2; // High aggression is a key factor
            foulChance += goalkeeper.trueRating.PhysicalityForGameCalculations * 0.1;   // Physicality can lead to reckless charges
            foulChance -= goalkeeper.trueRating.ComposureForGameCalculations * 0.15;  // Less composed, more prone to rash decisions
            foulChance -= goalkeeper.trueRating.GoalKeepingPositioningForGameCalculations * 0.05; // Poor positioning could lead to charging mistakes

            // Opponent's attributes (influencing the need for the GK to charge/foul)
            foulChance += opponent.trueRating.PaceForGameCalculations * 0.05;       // Fast opponent, GK rushes faster
            foulChance += opponent.trueRating.PositioningForGameCalculations * 0.05; // Good movement puts pressure on GK

            // Contextual factors:
            // 1. Is the GK outside the Goalkeeper Area but still in the Penalty Area?
            //    Charges are very common here.
            if (contestZone != Enums.PitchZone.GoalkeeperArea_Home && contestZone != Enums.PitchZone.GoalkeeperArea_Away &&
                (IsBallInPenaltyArea(contestZone, opponent.Team))) // Check if it's in the opposing team's attacking box (i.e. GK's own penalty area but not small box)
            {
                foulChance += 10; // Higher chance in the general penalty area
            }
            // 2. Is the ball a through ball (high speed)?
            //    Faster balls mean less time for GK to make a clean decision.
            //    You'll need a way to determine 'ball speed' for this context.
            //    Let's add a placeholder for now.
            // if (ballSpeed > threshold) { foulChance += 5; }

            // 3. Is it a desperate situation (e.g., denying a clear goal-scoring opportunity)?
            //    Not explicitly factored here, but could lead to a red card.

            foulChance = Math.Max(0, Math.Min(90, foulChance)); // Clamp between 0% and 90%

            if (Dice.d100() < foulChance)
            {
                MatchEntry meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PlayerMoved,
                    Timestamp = DateTime.Now,
                    DribblePhase = DribblePhaseType.Duel,
                    DribbleResult = DribbleResultType.GKFoul,

                    PlayerName1 = opponent.fullName,
                    Player1Pos = opponent.position,
                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,

                    Zone1 = CurrentBallZone,
                };
                LogEntry(meOpen);
                // A goalkeeper charging foul in their own penalty area is always a penalty.
                // Outside the box, it's a direct free kick.
                bool isPenalty = IsBallInPenaltyArea(contestZone, opponent.Team);
                ProcessFoul(goalkeeper, opponent, Enums.FoulType.FoulByGKCharge, isPenalty, opponent.Team);
                return true; // Foul occurred
            }

            return false; // No foul
        }

