        #region Substitutions

        /// <summary>
        /// <summary>
        /// Executes a substitution for a specified team.
        /// Takes player IDs as input for the swap.
        /// </summary>
        /// <param name="team">The team making the substitution.</param>
        /// <param name="playerOutId">The ID of the player to be substituted out.</param>
        /// <param name="playerInId">The ID of the player to be substituted in.</param>
        /// <returns>True if the substitution was successful, false otherwise.</returns>
        public bool MakeSubstitution(Team team, Player playerOut, Player playerIn)
        {
            int subsMade = (team == HomeTeam) ? homeTeamSubstitutionsMade : awayTeamSubstitutionsMade;

            if (subsMade >= MAX_SUBSTITUTIONS)
            {
                //ShowMessage($"{team.Name}: Cannot make substitution, maximum substitutions ({MAX_SUBSTITUTIONS}) already made.");
                return false;
            }

            if (playerOut == null || playerIn == null)
            {
                //ShowMessage($"ERROR: Invalid player ID for substitution. Out: {playerOutId}, In: {playerInId}");
                return false;
            }

            if (playerOut.isSentOff)
            {
                //ShowMessage($"{team.Name}: {playerOut.fullName} was sent off and cannot be substituted. Team must play with fewer players.");
                return false;
            }
            if (playerIn.isSentOff || playerIn.IsSubstituted || playerIn.IsInjured)
            {
                //ShowMessage($"{team.Name}: {playerIn.fullName} is not available for substitution (sent off, already subbed, or injured).");
                return false;
            }
            if (!playerIn.AvailableOption)
            {
                return false;
            }
            if (!playerOut.AvailableOption)
            {
                return false;
            }

            // --- Capture the zone of the player going out BEFORE modifying player lists ---
            Enums.PitchZone playerOutZone = playerOut.CurrentZone; // <--- Capture current zone

            // --- Assign the incoming player to the zone of the player leaving ---
            playerIn.CurrentZone = playerOutZone; // <--- Set incoming player's zone

            // --- And crucially, set the outgoing player's zone to None ---
            //playerOut.CurrentZone = Enums.PitchZone.None; // <--- Set outgoing player's zone to None

            playerIn.InitializePlayerStats(leagueName, team.Name);
            playerIn.LeagueTeamSeasonStats[leagueName][team.Name].matchesPlayed++;

            // Update substitution count
            if (team == HomeTeam) homeTeamSubstitutionsMade++;
            else awayTeamSubstitutionsMade++;

            // Update Player object flags
            playerOut.IsSubstituted = true; // Mark player who left the field as substituted
            playerIn.IsSubstituted = false; // Ensure incoming player is not marked as already substituted
                                            //playerIn.isInjured = false;     // Ensure incoming player is not marked as injured
                                            //playerIn.RestoreCondition(MAX_CONDITION); // Incoming player has full condition


            playerIn.Position = playerOut.Position;
            // Perform the swap using object references
            team.CurrentEleven.Remove(playerOut);
            team.CurrentEleven.Add(playerIn);
            team.CurrentBench.Remove(playerIn);
            team.CurrentBench.Add(playerOut);
            team.SetPlayerSubstituted(playerOut);

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.Substitution, // Use the general PassOutcome event
                Timestamp = DateTime.Now,
                DribblePhase = DribblePhaseType.Duel,
                DribbleResult = DribbleResultType.GKFoul,

                PlayerName1 = playerOut.fullName,
                Player1Pos = playerOut.position,
                PlayerName2 = playerIn.fullName,
                Player2Pos = playerIn.position,
                TeamName1 = team.Name,
                TeamName2 = team.Name,

                Zone1 = CurrentBallZone,
            };
            LogEntry(meOpen);

            return true;
        }

        private bool IsInSamePositionGroup(Player player, Enums.Positions pos)
        {
            if (TeamRepository.Instance.IsForward(pos))
            {
                if (TeamRepository.Instance.IsForward(player.Position))
                    return true;
                else
                {
                    if (player.secondPos != null)
                    {
                        foreach (Enums.Positions p in player.secondPos)
                        {
                            if (TeamRepository.Instance.IsForward(p))
                                return true;
                        }
                    }
                }
            }
            else if (TeamRepository.Instance.IsMidfielder(pos))
            {
                if (TeamRepository.Instance.IsMidfielder(player.Position))
                    return true;
                else
                {
                    if (player.secondPos != null)
                    {
                        foreach (Enums.Positions p in player.secondPos)
                        {
                            if (TeamRepository.Instance.IsMidfielder(p))
                                return true;
                        }
                    }
                }
            }
            else if (TeamRepository.Instance.IsDefender(pos))
            {
                if (TeamRepository.Instance.IsDefender(player.Position))
                    return true;
                else
                {
                    if (player.secondPos != null)
                    {
                        foreach (Enums.Positions p in player.secondPos)
                        {
                            if (TeamRepository.Instance.IsDefender(p))
                                return true;
                        }
                    }
                }
            }
            else
            {
                if (TeamRepository.Instance.IsGoalKeeper(pos))
                    return true;
                else
                {
                    if (player.secondPos != null)
                    {
                        foreach (Enums.Positions p in player.secondPos)
                        {
                            if (TeamRepository.Instance.IsGoalKeeper(p))
                                return true;
                        }
                    }
                }
            }

            return false;
        }

        private void ConsiderSubstitutions(Team team, Team opponentTeam, int teamScore, int opponentScore, int currentMinute)
        {
            //LoggingStuff.LogMethodCall(string.Format("ConsiderSubstitutions: team:{0},opponentTeam:{1},teamScore:{2}," +
            //    "opponentScore:{3},currentMinute:{4}", team.Name, opponentTeam.Name, teamScore, opponentScore, currentMinute));

            int subsMade = (team == HomeTeam) ? homeTeamSubstitutionsMade : awayTeamSubstitutionsMade;

            if (subsMade >= MAX_SUBSTITUTIONS)
            {
                return; // No subs left
            }

            bool isPendingSubstitution = (team == HomeTeam) ? homeTeamPendingSubstitution : awayTeamPendingSubstitution;

            // If a substitution is already planned, don't try to plan another *unless* it's a new, more critical emergency.
            // For now, let's assume emergency injury subs are handled elsewhere and won't conflict.
            if (isPendingSubstitution)
            {
                return; // Already waiting for a sub to happen at the next stoppage.
            }

            // Prioritize emergency substitutions (red cards, severe injuries)
            // (Your existing emergency sub logic for injuries should take precedence if you have it,
            // or we can add it here if it's not handled elsewhere.)

            // --- STRATEGIC SUBSTITUTION LOGIC ---
            Player playerOut = null;
            Player playerIn = null;
            string subReason = "Tactical"; // Default reason

            // Injury-Based Substitution (if no strategic sub found)
            if (playerOut == null)
            {
                playerOut = team.CurrentEleven
                                 .Where(p => p.HasMajorInjury || ((p.HasMinorInjury || p.HasModerateInjury) && p.gameStats.MinutesPlayed > 65))
                                 .OrderBy(p => p.CurrentCondition)
                                 .FirstOrDefault();

                if (playerOut != null)
                {
                    playerIn = team.CurrentBench.Where(p => p.AvailableOption && (p.Position == playerOut.Position || IsInSamePositionGroup(p, playerOut.position) || (p.AvailableOption))).OrderByDescending(p => p.trueRating.OverallForGameCalculations).FirstOrDefault();
                    if (playerIn != null) subReason = "Injury Management";
                }
            }

            // 1. Red Card Scenario (Emergency Response)
            // If a player was sent off, and you can still make a sub, prioritize replacing them
            // (Note: Sent off players cannot be substituted, but you can change formation/replace a different player)
            bool teamHasRedCard = team.CurrentEleven.Any(p => p.isSentOff);
            if (teamHasRedCard && !team.HasMadeRedCardAdjustment && subsMade < MAX_SUBSTITUTIONS)
            {
                // Find the position most impacted by the red card (e.g., if a CB, maybe bring on another CB)
                // Or, more generally, sacrifice an attacking player for a defensive one
                Player sentOffPlayer = team.CurrentEleven.FirstOrDefault(p => p.isSentOff);
                if (sentOffPlayer != null)
                {
                    if (sentOffPlayer.Position == Enums.Positions.CenterBack ||
                        sentOffPlayer.Position == Enums.Positions.LeftBack ||
                        sentOffPlayer.Position == Enums.Positions.RightBack ||
                        sentOffPlayer.Position == Enums.Positions.CentralDefendingMidfielder)
                    {
                        // Defender sent off: Try to bring on another defender/defensive midfielder if available
                        playerIn = team.CurrentBench.Where(p => p.AvailableOption &&
                                                        (p.Position == Enums.Positions.CenterBack ||
                                                         p.Position == Enums.Positions.LeftBack ||
                                                         p.Position == Enums.Positions.RightBack ||
                                                         p.Position == Enums.Positions.CentralDefendingMidfielder))
                                            .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                            .FirstOrDefault();
                        // If bringing on a defender, who to take off? A forward or attacking midfielder is likely.
                        if (playerIn != null)
                        {
                            playerOut = team.CurrentEleven.Where(p => p.AvailableOption &&
                                                                      (p.Position == Enums.Positions.Striker ||
                                                                       p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                                       p.Position == Enums.Positions.LeftWingForward ||
                                                                       p.Position == Enums.Positions.RightWingForward))
                                                        .OrderBy(p => p.CurrentCondition) // Prefer to take off someone tired
                                                        .FirstOrDefault();
                            if (playerOut != null) subReason = "Red Card Defensive Adjustment";
                        }
                    }
                    if (playerOut != null && playerIn != null)
                    {
                        subReason = "Red Card Defensive Adjustment";
                        team.HasMadeRedCardAdjustment = true; // IMPORTANT: Set this flag!
                    }
                    // Add more specific logic for other positions if needed.
                }
            }

            // 2. Yellow Card Management (Late Game, High Risk)
            // Only consider this if no other critical sub is being planned and it's late in the game
            if (playerOut == null && currentMinute >= 70 && subsMade < MAX_SUBSTITUTIONS) // Only check late game
            {
                Player yellowCardedPlayer = team.CurrentEleven
                    .Where(p => (p.yellowCards == 1) && p.AvailableOption)
                    .OrderBy(p => p.CurrentCondition) // Prioritize removing tired yellow-carded players
                    .FirstOrDefault();

                // Check if the player is in a high-risk position (e.g., defender, defensive midfielder)
                // or if they have low discipline rating (more likely to get a second yellow)
                if (yellowCardedPlayer != null && yellowCardedPlayer.trueRating.ComposureForGameCalculations < 70 && Dice.d100() < 60) // 60% chance to sub a risky yellow
                {
                    Player suitableSub = team.CurrentBench
                        .Where(p => p.AvailableOption && p.Position == yellowCardedPlayer.Position)
                        .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                        .FirstOrDefault();

                    if (suitableSub != null)
                    {
                        playerOut = yellowCardedPlayer;
                        playerIn = suitableSub;
                        subReason = "Yellow Card Risk Management";
                    }
                }
            }

            // 3. Score Situation (Tactical Offensive/Defensive Subs)
            // Only if no other urgent sub is identified
            if (playerOut == null && subsMade < MAX_SUBSTITUTIONS)
            {
                int scoreDiff = teamScore - opponentScore;
                bool isLateGame = currentMinute >= 70; // Adjust as desired
                bool isVeryLateGame = currentMinute >= 80;

                // Losing: Push for an equalizer/winner
                if (scoreDiff < 0) // Team is losing
                {
                    if (isVeryLateGame && scoreDiff <= -1) // Down by 1 or more, very late
                    {
                        // Try to bring on an extra attacker
                        playerOut = team.CurrentEleven.Where(p => p.AvailableOption &&
                                                                    (p.Position == Enums.Positions.CentralMidfielder ||
                                                                     p.Position == Enums.Positions.CentralDefendingMidfielder ||
                                                                     p.Position == Enums.Positions.CenterBack)) // Take off a less offensive player
                                                        .OrderBy(p => p.CurrentCondition)
                                                        .FirstOrDefault();
                        playerIn = team.CurrentBench.Where(p => p.AvailableOption &&
                                                         (p.Position == Enums.Positions.Striker ||
                                                          p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                          p.Position == Enums.Positions.LeftWingForward ||
                                                          p.Position == Enums.Positions.RightWingForward))
                                             .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                             .FirstOrDefault();

                        if (playerOut != null && playerIn != null)
                        {
                            subReason = "Losing by " + -scoreDiff + " goals late game: Attacking Push";
                            // Consider changing team tactic here as well:
                            // team.CurrentTactic = Enums.TeamTactic.AllOutAttack;
                        }
                        else
                        {
                            // If no perfect attacker/defender swap, try a more general like-for-like attacker
                            playerOut = team.CurrentEleven
                                            .Where(p => p.AvailableOption && p.Role != Enums.PlayerRole.Goalkeeper)
                                            .OrderByDescending(p => p.CurrentCondition) // Prioritize removing someone who is not tired but less impactful
                                            .FirstOrDefault();
                            playerIn = team.CurrentBench
                                        .Where(p => p.AvailableOption &&
                                                    (p.Position == Enums.Positions.Striker ||
                                                     p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                     p.Position == Enums.Positions.LeftWingForward ||
                                                     p.Position == Enums.Positions.RightWingForward))
                                        .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                        .FirstOrDefault();
                            if (playerOut != null && playerIn != null) subReason = "Losing: General Attacking Change";
                        }
                    }
                    else if (isLateGame && scoreDiff <= -2 && Dice.d100() < 40) // Down by 2+, slightly earlier, 40% chance
                    {
                        // Similar logic as above, but maybe less aggressive
                        // Consider bringing on an attacker for a less impactful midfielder/defender
                        playerOut = team.CurrentEleven.Where(p => p.AvailableOption &&
                                                                   (p.Position == Enums.Positions.CentralMidfielder ||
                                                                    p.Position == Enums.Positions.CentralDefendingMidfielder ||
                                                                    p.Position == Enums.Positions.CenterBack))
                                                       .OrderBy(p => p.CurrentCondition)
                                                       .FirstOrDefault();
                        playerIn = team.CurrentBench.Where(p => p.AvailableOption &&
                                                         (p.Position == Enums.Positions.Striker ||
                                                          p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                          p.Position == Enums.Positions.LeftWingForward ||
                                                          p.Position == Enums.Positions.RightWingForward))
                                             .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                             .FirstOrDefault();
                        if (playerOut != null && playerIn != null) subReason = "Losing by " + -scoreDiff + " goals: Earlier Attacking Change";
                    }
                }
                // Winning: Protect the lead
                else if (scoreDiff > 0 && isLateGame && Dice.d100() < 70) // Up by 1 or more, late game, 70% chance to protect
                {
                    // Try to bring on an extra defender/defensive midfielder
                    playerOut = team.CurrentEleven.Where(p => p.AvailableOption &&
                                                                (p.Position == Enums.Positions.Striker ||
                                                                 p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                                 p.Position == Enums.Positions.LeftWingForward ||
                                                                 p.Position == Enums.Positions.RightWingForward))
                                                    .OrderBy(p => p.CurrentCondition)
                                                    .FirstOrDefault();
                    playerIn = team.CurrentBench.Where(p => p.AvailableOption &&
                                                    (p.Position == Enums.Positions.CenterBack ||
                                                     p.Position == Enums.Positions.CentralDefendingMidfielder ||
                                                     p.Position == Enums.Positions.CentralMidfielder))
                                         .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                         .FirstOrDefault();
                    if (playerOut != null && playerIn != null)
                    {
                        subReason = "Winning by " + scoreDiff + " goals late game: Defensive Reinforcement";
                        // Consider changing team tactic here as well:
                        // team.CurrentTactic = Enums.TeamTactic.ParkTheBus;
                    }
                }
                // Tied: Late game, consider slight adjustments (e.g., fresh legs for a push)
                else if (scoreDiff == 0 && isVeryLateGame && Dice.d100() < 50)
                {
                    // Similar to tired player logic, but higher priority for key positions
                    // Consider bringing on a fresh attacker for a tired midfielder/attacker to make a late push
                    playerOut = team.CurrentEleven
                                    .Where(p => p.AvailableOption && p.CurrentCondition < 60 &&
                                                (p.Position == Enums.Positions.Striker || p.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                 p.Position == Enums.Positions.CentralMidfielder || p.Position == Enums.Positions.LeftWingForward || p.Position == Enums.Positions.RightWingForward))
                                    .OrderBy(p => p.CurrentCondition)
                                    .FirstOrDefault();
                    playerIn = team.CurrentBench
                                     .Where(p => p.AvailableOption &&
                                                 (playerOut != null ? p.Position == playerOut.Position : true)) // FIXED LINE
                                     .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                     .FirstOrDefault();
                    if (playerOut != null && playerIn != null) subReason = "Tied Late Game: Fresh Legs Push";
                }
            }

            // 5. Fallback to Fatigue-Based Substitution (if no strategic sub found)
            if (playerOut == null)
            {
                playerOut = team.CurrentEleven
                                 .Where(p => p.AvailableOption && p.CurrentCondition < 60)
                                 .OrderBy(p => p.CurrentCondition)
                                 .FirstOrDefault();

                if (playerOut != null)
                {
                    playerIn = team.CurrentBench
                                     .Where(p => p.AvailableOption && p.Position == playerOut.Position)
                                     .OrderByDescending(p => p.trueRating.OverallForGameCalculations)
                                     .FirstOrDefault();
                    if (playerIn != null) subReason = "Fatigue Management";
                }
            }

            // --- QUEUE THE SUBSTITUTION ---
            if (playerOut != null && playerIn != null)
            {
                if (playerOut == playerIn)
                    return;
                // Only queue if there isn't one already queued for this team (prevents overwriting a pending emergency sub)
                if ((team == HomeTeam && !homeTeamPendingSubstitution) ||
                    (team == AwayTeam && !awayTeamPendingSubstitution))
                {
                    if (team == HomeTeam)
                    {
                        homeTeamPendingSubstitution = true;
                        homeTeamSubOutPlayer = playerOut;
                        homeTeamSubInPlayer = playerIn;
                    }
                    else
                    {
                        awayTeamPendingSubstitution = true;
                        awayTeamSubOutPlayer = playerOut;
                        awayTeamSubInPlayer = playerIn;
                    }
                    //ShowMessage("(" + team.Name + ") Management is planning a " + subReason + " substitution for " +
                    //    playerOut.fullName + " (OUT) and " + playerIn.fullName + " (IN) at the next stoppage.");
                }
                else
                {
                    //ShowMessage("(" + team.Name + ") already has a pending substitution. Tactical sub for " + playerOut.fullName + " delayed.");
                    // We'll prioritize the earlier queued sub if one exists
                }
            }
        }

        private void SubstituteHandler()
        {
            bool subsMadeThisMoment = false;

            // Process home team substitution if pending
            if (homeTeamPendingSubstitution)
            {
                if (MakeSubstitution(HomeTeam, homeTeamSubOutPlayer, homeTeamSubInPlayer))
                {
                    homeTeamPendingSubstitution = false;
                    homeTeamSubOutPlayer = null;
                    homeTeamSubInPlayer = null;
                    subsMadeThisMoment = true;
                }
            }

            // Process away team substitution if pending
            if (awayTeamPendingSubstitution)
            {
                if (MakeSubstitution(AwayTeam, awayTeamSubOutPlayer, awayTeamSubInPlayer))
                {
                    awayTeamPendingSubstitution = false;
                    awayTeamSubOutPlayer = null;
                    awayTeamSubInPlayer = null;
                    subsMadeThisMoment = true;
                }
            }

            if (!subsMadeThisMoment && !homeTeamPendingSubstitution && !awayTeamPendingSubstitution)
            {
                //ShowMessage("No more pending substitutions. Resuming play.");
            }
        }

