        #region LooseBall

        /// <summary>
        /// Handles a loose ball situation, determining which team's player recovers possession and its approximate landing zone.
        /// This method needs to be called when the ball becomes unpossessed (e.g., after a tackle, deflection, save, or GK punch/fumble).
        /// </summary>
        /// <param name="isBallHigh">Set to true if the loose ball is high in the air, prompting an aerial contest.</param>
        /// <param name="sourcePlayer">The player who last touched the ball or caused it to become loose (e.g., the GK who punched it). Can be null.</param>
        /// <param name="originalCrossDeliveryType">If the loose ball resulted from a cross, its original delivery type (e.g., Inswinger, Outswinger). Defaults to None.</param>
        /// <param name="attackingTeam">The current attacking team, important for contextualizing zones.</param>
        /// <param name="defendingTeam">The current defending team, important for contextualizing zones.</param>
        private void SetLooseBall(bool isBallHigh = false, Player sourcePlayer = null, Enums.CornerDeliveryType originalCrossDeliveryType = Enums.CornerDeliveryType.None, Team attackingTeam = null, Team defendingTeam = null,
            bool reboundSituation = false, bool isPoorDeflection = false, bool isGoodDeflection = false) // Modified signature
        {
            ReboundChance = false;

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.LooseBall, // Use the general PassOutcome event
                Timestamp = DateTime.Now,
                IsLooseBallHigh = isBallHigh,
                Zone1 = CurrentBallZone,

                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,
            };

            if (sourcePlayer == null)
            {
                meOpen.PlayerName1 = "Unknown Player";
            }
            else
            {
                meOpen.Player1Pos = sourcePlayer.position;
                meOpen.PlayerName1 = sourcePlayer.fullName;
            }

            // If we're setting a loose ball, let's first determine where it *might* land if not immediately recovered.
            // This is especially relevant if sourcePlayer is a GK who just punched/fumbled.
            if (sourcePlayer != null && sourcePlayer.Position == Enums.Positions.Goalkeeper)
            {
                // Logic to influence where the GK's punch/fumble sends the ball
                Enums.PitchZone potentialLandingZone = DetermineGKClearanceLandingZone(sourcePlayer, originalCrossDeliveryType, isBallHigh, attackingTeam, defendingTeam);
                CurrentBallZone = potentialLandingZone; // Update CurrentBallZone based on GK's action
                //meOpen.Zone1 = potentialLandingZone;
                //meOpen.Player1Pos = sourcePlayer.position;
                //meOpen.PlayerName1 = sourcePlayer.fullName;
            }
            else
            {
                // For other loose ball scenarios (tackles, deflections, etc.), the CurrentBallZone should already be set
                // to where the loose ball occurred. If not, it needs to be determined by the calling method.
            }

            if (isBallHigh)
            {
                int x = 0;
            }

            //LogEntry(meOpen);

            if (attackingTeam == null)
                attackingTeam = AttackingTeam;
            if (defendingTeam == null)
                defendingTeam = DefendingTeam;

            Player attackingPlayer = GetBestLooseBallPlayer(attackingTeam, CurrentBallZone, sourcePlayer);
            Player defendingPlayer = GetBestLooseBallPlayer(defendingTeam, CurrentBallZone, sourcePlayer);

            // balls that are in the center of the field cannot go out of bounds.
            if (CanBeOutOfBounds(CurrentBallZone))
            {
                // --- Introduce a chance for the loose ball to go out of bounds. ---
                double looseBallOutOfBoundsChance = 0;
                looseBallOutOfBoundsChance += 10;

                // More likely to go out if near flanks or specific goal-related/corner zones
                if (EnumCache<Enums.PitchZone>.ToString(CurrentBallZone).Contains("Flank") ||
                    CurrentBallZone == Enums.PitchZone.GoalkeeperArea_Home ||
                    CurrentBallZone == Enums.PitchZone.GoalkeeperArea_Away ||
                    CurrentBallZone == Enums.PitchZone.PenaltyArea_Home ||
                    CurrentBallZone == Enums.PitchZone.PenaltyArea_Away ||
                    CurrentBallZone == Enums.PitchZone.Corner_HomeLeft ||
                    CurrentBallZone == Enums.PitchZone.Corner_HomeRight ||
                    CurrentBallZone == Enums.PitchZone.Corner_AwayLeft ||
                    CurrentBallZone == Enums.PitchZone.Corner_AwayRight ||
                    CurrentBallZone == Enums.PitchZone.DefensivePenaltyArea_LeftNearPost ||
                    CurrentBallZone == Enums.PitchZone.DefensivePenaltyArea_RightNearPost ||
                    CurrentBallZone == Enums.PitchZone.DefensivePenaltyArea_LeftFarPost ||
                    CurrentBallZone == Enums.PitchZone.DefensivePenaltyArea_RightFarPost ||
                    CurrentBallZone == Enums.PitchZone.Defensive_EdgeOfBox) // New zones added
                {
                    looseBallOutOfBoundsChance += 30;
                }

                if (attackingPlayer == null && defendingPlayer == null)
                {
                    looseBallOutOfBoundsChance += 40;
                }
                looseBallOutOfBoundsChance = Math.Max(0, Math.Min(95, looseBallOutOfBoundsChance));

                int outOfBoundsRoll = Dice.d100();

                if (outOfBoundsRoll <= looseBallOutOfBoundsChance && CanBeOutOfBounds(CurrentBallZone))
                {
                    Team inferredLastTouchTeam;
                    // More robust logic to infer last touch, possibly based on CurrentBallZone relative to teams
                    // For simplicity, let's keep the existing logic and assume it's sound for now.
                    if ((CurrentBallZone == Enums.PitchZone.GoalkeeperArea_Home || CurrentBallZone == Enums.PitchZone.PenaltyArea_Home || CurrentBallZone == Enums.PitchZone.Corner_HomeLeft || CurrentBallZone == Enums.PitchZone.Corner_HomeRight) && defendingTeam == HomeTeam)
                    {
                        inferredLastTouchTeam = HomeTeam; // Likely cleared by defending home team
                    }
                    else if ((CurrentBallZone == Enums.PitchZone.GoalkeeperArea_Away || CurrentBallZone == Enums.PitchZone.PenaltyArea_Away || CurrentBallZone == Enums.PitchZone.Corner_AwayLeft || CurrentBallZone == Enums.PitchZone.Corner_AwayRight) && defendingTeam == AwayTeam)
                    {
                        inferredLastTouchTeam = AwayTeam; // Likely cleared by defending away team
                    }
                    else
                    {
                        inferredLastTouchTeam = attackingTeam; // Otherwise, attacking team might have put it out
                    }
                    if (attackingPlayer == null && defendingPlayer == null)
                        inferredLastTouchTeam = attackingTeam; // Likely cleared by attacking team because nobody touched it since the last action.

                    LogEntry(meOpen);
                    SetMatchStateForOutOfBounds(CurrentBallZone, inferredLastTouchTeam);
                    return;
                }
            }
            // else { int x = 0; } // Removed unnecessary empty else block

            // --- NEW: Check for Goalkeeper Charging foul (if a GK is involved in a loose ball contest) ---
            // This check applies if the defending player is a GK and there's an attacking player contesting.
            // It specifically targets situations where the GK charges out.
            if (defendingPlayer != null && defendingPlayer.Position == Enums.Positions.Goalkeeper && attackingPlayer != null)
            {
                LogEntry(meOpen);
                // Only consider charging foul if the GK is outside their immediate GoalkeeperArea (6-yard box)
                // This makes it distinct from dangerous play in aerial contests *inside* the 6-yard box.
                bool isHomeDefending = (defendingTeam == HomeTeam);
                Enums.PitchZone defendingGoalkeeperArea = isHomeDefending ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;

                if ((CurrentBallZone != defendingGoalkeeperArea) &&
                    (IsBallInPenaltyArea(CurrentBallZone, attackingTeam) || IsBallInAttackingHalf(CurrentBallZone, attackingTeam))) // Only if attacking team is getting near goal
                {
                    if (SimulateGoalkeeperCharge(defendingPlayer, attackingPlayer, CurrentBallZone))
                    {
                        // If a foul occurred, ProcessFoul has already handled setting the state etc.
                        return; // Exit as foul play has taken precedence
                    }
                }
            }

            // --- Handle Aerial Contest for HIGH loose balls if players are contesting ---
            // This is the logic for general aerial duels, potentially including the GK (who might commit dangerous play).
            // The charging foul above is a more specific "rush out" foul.
            if (isBallHigh && attackingPlayer != null && defendingPlayer != null)
            {
                LogEntry(meOpen);
                Enums.AerialContestOutcome aerialOutcome = SimulateAerialContest(
                    attackingPlayer,    // Contester1: Attacking player
                    defendingPlayer,    // Contester2: Defending player
                    attackingTeam,
                    defendingTeam,
                    CurrentBallZone, false, isPoorDeflection, isGoodDeflection);

                switch (aerialOutcome)
                {
                    case Enums.AerialContestOutcome.Player1Wins:
                        _potentialChanceCreatingActions.Add(new Tuple<Player, int>(attackingPlayer, CurrentSecond));
                        //ShowMessage(string.Format("{0} wins the aerial loose ball and recovers possession for {1}!", attackingPlayer.fullName, attackingTeam.Name));
                        SetPossession(attackingPlayer, CurrentBallZone, attackingTeam);
                        ReboundChance = reboundSituation;
                        AerialBattlePending = true;
                        CurrentMatchState = MatchState.InPlay_Possession;
                        return;
                    case Enums.AerialContestOutcome.Player2Wins:
                        //ShowMessage(string.Format("{0} wins the aerial loose ball and recovers possession for {1}!", defendingPlayer.fullName, defendingTeam.Name));
                        SetPossession(defendingPlayer, CurrentBallZone, defendingTeam);
                        AerialBattlePending = true;
                        CurrentMatchState = MatchState.InPlay_Possession;
                        return;
                    case Enums.AerialContestOutcome.LooseBall:
                        //ShowMessage("The aerial contest for the loose ball was inconclusive. Ball is still loose!");
                        break; // Continue to the ground recovery logic
                    case Enums.AerialContestOutcome.FoulOccurred:
                        // ProcessFoul (called by SimulateAerialContest) already set match state and possession.
                        //ShowMessage("A foul occurred during the loose ball aerial contest! Play stopped.");
                        return;
                }
            }

            LogEntry(meOpen);
            // --- Original Loose Ball Recovery Logic (for ground balls or after inconclusive aerial contest) ---
            // Handle cases where one or no players are found, or if aerial contest was inconclusive
            // --- NEW: Handle "No Players Found" for balls that *cannot* go out of bounds ---
            if (attackingPlayer == null && defendingPlayer == null)
            {
                //ShowMessage("No active players found near the loose ball, but it remains in play. Resetting to InPlay_Possession for immediate re-evaluation.");
                // Pick a player (e.g., a central midfielder) from the team that "should" be attacking this half
                // and give them possession. This is a "fail-safe"
                Team teamToRecover = (CurrentBallZone == Enums.PitchZone.HomeDefense_Center || CurrentBallZone == Enums.PitchZone.Midfield_Center) ? defendingTeam : attackingTeam;
                Player defaultRecoverer = teamToRecover.AvailableOnFieldOutfielders
                                            .Where(p => p != CurrentBallHolder && (p.Position == Enums.Positions.CentralMidfielder || p.Position == Enums.Positions.CentralDefendingMidfielder))
                                            .FirstOrDefault();
                if (defaultRecoverer == null) // Fallback to any player if specific role not found
                    defaultRecoverer = teamToRecover.AvailableOnFieldOutfielders.Where(p => p!= CurrentBallHolder).FirstOrDefault();

                if (defaultRecoverer != null)
                {
                    if (CurrentBallZone == Enums.PitchZone.None)
                    {
                        int x = 0;
                    }
                    meOpen = new MatchEntry
                    {
                        Level = LogLevel.Info,
                        EventType = MatchEventType.LooseBallRecovery, // Use the general PassOutcome event
                        Timestamp = DateTime.Now,
                        IsLooseBallHigh = isBallHigh,
                        Player1Pos = defaultRecoverer.position,
                        PlayerName1 = defaultRecoverer.fullName,

                        TeamName1 = AttackingTeam.Name,
                        TeamName2 = DefendingTeam.Name,
                    };
                    LogEntry(meOpen);
                    SetPossession(defaultRecoverer, CurrentBallZone, teamToRecover);
                    if (teamToRecover == AttackingTeam)
                        ReboundChance = reboundSituation;
                    //ShowMessage($"Forced possession: {defaultRecoverer.fullName} recovers the ball at {CurrentBallZone}.");
                    CurrentMatchState = Enums.MatchState.InPlay_Possession;
                }
                else
                {
                    // Absolute last resort: If no players at all are found (e.g., entire team sent off), force a whistle or stop.
                    throw new Exception("CRITICAL: No players found for recovery, even with fallback. Match stopped.");
                }
                return; // Exit after handling the no-player scenario
            }
            else if (attackingPlayer == null)
            {
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.LooseBallRecovery, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    IsLooseBallHigh = isBallHigh,
                    Player1Pos = defendingPlayer.position,
                    PlayerName1 = defendingPlayer.fullName,

                    TeamName1 = DefendingTeam.Name,
                    TeamName2 = AttackingTeam.Name,
                };
                LogEntry(meOpen);
                SetPossession(defendingPlayer, CurrentBallZone, defendingTeam);
                CurrentMatchState = Enums.MatchState.InPlay_Possession;
                return;
            }
            else if (defendingPlayer == null)
            {
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.LooseBallRecovery, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    IsLooseBallHigh = isBallHigh,
                    Player1Pos = attackingPlayer.position,
                    PlayerName1 = attackingPlayer.fullName,

                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,
                };
                LogEntry(meOpen);
                ReboundChance = reboundSituation;
                SetPossession(attackingPlayer, CurrentBallZone, attackingTeam);
                CurrentMatchState = Enums.MatchState.InPlay_Possession;
                return;
            }

            // --- Both teams have a player contesting the loose ball on the GROUND ---
            double attackingPlayerSkill = (attackingPlayer.trueRating.ReactionTimeForGameCalculations * 0.3) +
                                          (attackingPlayer.trueRating.ComposureForGameCalculations * 0.3) +
                                          (attackingPlayer.trueRating.AgilityForGameCalculations * 0.2) +
                                          (attackingPlayer.trueRating.BallControlForGameCalculations * 0.2);

            double defendingPlayerSkill = (defendingPlayer.trueRating.ReactionTimeForGameCalculations * 0.3) +
                                          (defendingPlayer.trueRating.ComposureForGameCalculations * 0.3) +
                                          (defendingPlayer.trueRating.AgilityForGameCalculations * 0.2) +
                                          (defendingPlayer.trueRating.BallControlForGameCalculations * 0.2);

            double totalContestSkill = attackingPlayerSkill + defendingPlayerSkill;
            double attackingTeamRecoveryProbability = (totalContestSkill > 0) ? (attackingPlayerSkill / totalContestSkill) : 0.5;
            if (PoorDeflection)
                attackingTeamRecoveryProbability += 0.20; // attacking more likely to get it on a poor deflection
            else if (GoodDeflection)
                attackingTeamRecoveryProbability -= 0.20; // defending more likely to get it on a good deflection
            attackingTeamRecoveryProbability = Math.Max(0.05, Math.Min(0.95, attackingTeamRecoveryProbability));

            int recoveryRoll = Dice.d100();

            if (recoveryRoll < (attackingTeamRecoveryProbability * 100))
            {
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.LooseBallRecovery, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    IsLooseBallHigh = isBallHigh,
                    Player1Pos = attackingPlayer.position,
                    PlayerName1 = attackingPlayer.fullName,

                    TeamName1 = AttackingTeam.Name,
                    TeamName2 = DefendingTeam.Name,
                };
                LogEntry(meOpen);
                SetPossession(attackingPlayer, CurrentBallZone, attackingTeam);
                ReboundChance = reboundSituation;
                CurrentMatchState = Enums.MatchState.InPlay_Possession;
            }
            else
            {
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.LooseBallRecovery, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,
                    IsLooseBallHigh = isBallHigh,
                    Player1Pos = defendingPlayer.position,
                    PlayerName1 = defendingPlayer.fullName,

                    TeamName1 = DefendingTeam.Name,
                    TeamName2 = AttackingTeam.Name,
                };
                LogEntry(meOpen);
                SetPossession(defendingPlayer, CurrentBallZone, defendingTeam);
                CurrentMatchState = Enums.MatchState.InPlay_Possession;
            }
        }

        /// <summary>
        /// Helper method to find the "best" player from a team to recover a loose ball in a given zone.
        /// This implementation is highly dependent on how player positions/zones are tracked in your game.
        /// </summary>
        /// <param name="team">The team to search within.</param>
        /// <param name="zone">The current zone where the loose ball is.</param>
        /// <returns>The best Player for loose ball recovery, or null if none found.</returns>
        private Player GetBestLooseBallPlayer(Team team, Enums.PitchZone zone, Player sourcePlayer = null)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestLooseBallPlayer: team:{0},zone:{1}",
            //    team.Name, zone));

            if (sourcePlayer != null)
            {
                // Example: Find players from the team who are currently in the specified zone,
                // then order them by a combination of reactions and anticipation (key loose ball stats).
                //return team.AvailableOnFieldOutfielders // Assumes starting11 is the list of active players
                //           .Where(p => p.CurrentZone == zone && p != sourcePlayer)
                //           .OrderByDescending(p => p.trueRating.ReactionTimeForGameCalculations + p.trueRating.ComposureForGameCalculations)
                //           .FirstOrDefault(); // Get the best one
                return team.AvailableOnFieldOutfielders
                    .Where(p => p != sourcePlayer)
                    .OrderBy(p => CalculateDistance(p.CurrentZone, CurrentBallZone)) // Prefer closest player
                    .ThenByDescending(p => p.trueRating.ReactionTimeForGameCalculations + p.trueRating.ComposureForGameCalculations)
                    .FirstOrDefault();
            }
            else
            {
                // Example: Find players from the team who are currently in the specified zone,
                // then order them by a combination of reactions and anticipation (key loose ball stats).
                //return team.AvailableOnFieldOutfielders // Assumes starting11 is the list of active players
                //           .Where(p => p.CurrentZone == zone)
                //           .OrderByDescending(p => p.trueRating.ReactionTimeForGameCalculations + p.trueRating.ComposureForGameCalculations)
                //           .FirstOrDefault(); // Get the best one
                return team.AvailableOnFieldOutfielders
                    .OrderBy(p => CalculateDistance(p.CurrentZone, CurrentBallZone)) // Prefer closest player
                    .ThenByDescending(p => p.trueRating.ReactionTimeForGameCalculations + p.trueRating.ComposureForGameCalculations)
                    .FirstOrDefault();
            }

            // IMPORTANT: This method assumes your Player class has a 'CurrentZone' property
            // that indicates where the player is on the pitch. If not, you'll need to
            // implement how players are tracked spatially.
        }

        #endregion

        #region Boundaries

        // This method's implementation is crucial for correctly identifying out-of-bounds.
        public bool CanBeOutOfBounds(Enums.PitchZone zone)
        {
            bool isFlankExitZone = (zone == Enums.PitchZone.HomeDefense_LeftFlank ||
                                    zone == Enums.PitchZone.HomeDefense_RightFlank ||
                                    zone == Enums.PitchZone.Midfield_LeftFlank ||
                                    zone == Enums.PitchZone.Midfield_RightFlank ||
                                    zone == Enums.PitchZone.AwayAttack_LeftFlank ||
                                    zone == Enums.PitchZone.AwayAttack_RightFlank);

            bool isCornerZone = (zone == Enums.PitchZone.Corner_HomeLeft ||
                                 zone == Enums.PitchZone.Corner_HomeRight ||
                                 zone == Enums.PitchZone.Corner_AwayLeft ||
                                 zone == Enums.PitchZone.Corner_AwayRight);

            // ONLY return true for zones that are definitive out-of-bounds indicators
            return isFlankExitZone || isCornerZone;
        }

        // Helper method to determine the specific out-of-bounds state
        private void SetMatchStateForOutOfBounds(Enums.PitchZone ballExitZone, Team lastTouchTeam)
        {
            CheckForChanceNegation(lastTouchTeam, CurrentSecond, negatingPlayer: null, majorOffensiveErrorOccurred: true);
            // Determine the team that will gain possession based on the rules
            Team ballWinningTeam;
            Team ballLosingTeam;
            Enums.MatchState newState;
            Enums.PitchZone newBallZone;
            string message;

            // It's more robust to define the "goal line zones" explicitly
            bool isHomeGoalLineZone = (ballExitZone == Enums.PitchZone.GoalkeeperArea_Home ||
                                       ballExitZone == Enums.PitchZone.PenaltyArea_Home ||
                                       ballExitZone == Enums.PitchZone.Corner_HomeLeft ||
                                       ballExitZone == Enums.PitchZone.Corner_HomeRight);
            bool isAwayGoalLineZone = (ballExitZone == Enums.PitchZone.GoalkeeperArea_Away ||
                                       ballExitZone == Enums.PitchZone.PenaltyArea_Away ||
                                       ballExitZone == Enums.PitchZone.Corner_AwayLeft ||
                                       ballExitZone == Enums.PitchZone.Corner_AwayRight);

            bool isBallExitInHomeDefensiveGoalLineZone = (ballExitZone == Enums.PitchZone.GoalkeeperArea_Home ||
                                                           ballExitZone == Enums.PitchZone.PenaltyArea_Home ||
                                                           ballExitZone == Enums.PitchZone.Corner_HomeLeft ||
                                                           ballExitZone == Enums.PitchZone.Corner_HomeRight ||
                                                           (lastTouchTeam == AwayTeam && (ballExitZone == Enums.PitchZone.DefensivePenaltyArea_LeftNearPost || // These zones should map to a team's defensive end
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_RightNearPost ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_Central ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_LeftFarPost ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_RightFarPost ||
                                                                                          ballExitZone == Enums.PitchZone.Defensive_EdgeOfBox))); // This logic may need refinement depending on how your PitchZones map to actual halves.

            bool isBallExitInAwayDefensiveGoalLineZone = (ballExitZone == Enums.PitchZone.GoalkeeperArea_Away ||
                                                           ballExitZone == Enums.PitchZone.PenaltyArea_Away ||
                                                           ballExitZone == Enums.PitchZone.Corner_AwayLeft ||
                                                           ballExitZone == Enums.PitchZone.Corner_AwayRight ||
                                                           (lastTouchTeam == HomeTeam && (ballExitZone == Enums.PitchZone.DefensivePenaltyArea_LeftNearPost ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_RightNearPost ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_Central ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_LeftFarPost ||
                                                                                          ballExitZone == Enums.PitchZone.DefensivePenaltyArea_RightFarPost ||
                                                                                          ballExitZone == Enums.PitchZone.Defensive_EdgeOfBox)));

            isAwayGoalLineZone = isAwayGoalLineZone || isBallExitInAwayDefensiveGoalLineZone;
            isHomeGoalLineZone = isHomeGoalLineZone || isBallExitInHomeDefensiveGoalLineZone;

            // --- SIDE LINES (Throw-In) ---
            // If the ball went out on the side lines, it's always a throw-in.
            if (ballExitZone == Enums.PitchZone.HomeDefense_LeftFlank ||
                ballExitZone == Enums.PitchZone.HomeDefense_RightFlank ||
                ballExitZone == Enums.PitchZone.Midfield_LeftFlank ||
                ballExitZone == Enums.PitchZone.Midfield_RightFlank ||
                ballExitZone == Enums.PitchZone.AwayAttack_LeftFlank ||
                ballExitZone == Enums.PitchZone.AwayAttack_RightFlank)
            {
                newState = Enums.MatchState.ThrowIn;
                newBallZone = ballExitZone; // Throw-ins are taken from where it went out
                ballWinningTeam = (lastTouchTeam == HomeTeam) ? AwayTeam : HomeTeam; // The other team gets it
                ballLosingTeam = lastTouchTeam;
                MatchEntry meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.OutOfBounds, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    TeamName1 = ballWinningTeam.Name,
                    OutOfBoundsResult = OutOfBoundsResult.ThrowIn,

                    Zone1 = CurrentBallZone,
                };
                LogEntry(meOpen);
            }
            // --- GOAL LINES (Goal Kick vs. Corner Kick) ---
            else if (isHomeGoalLineZone || isAwayGoalLineZone) // Ball went out behind a goal line
            {
                if (isHomeGoalLineZone) // Ball went out behind Home Team's goal line (Home's defending goal)
                {
                    if (lastTouchTeam == HomeTeam) // Home team (defending their goal) last touched it -> CORNER for Away
                    {
                        newState = Enums.MatchState.CornerKick;
                        ballWinningTeam = AwayTeam;
                        ballLosingTeam = HomeTeam;

                        // Use GetFlankOfZone to determine the specific corner kick zone
                        Enums.Flank exitFlank = GetFlankOfZone(ballExitZone);
                        if (exitFlank == Enums.Flank.Left)
                        {
                            newBallZone = Enums.PitchZone.Corner_HomeLeft;
                        }
                        else // Assume Right or Center, default to Right for corners on this side
                        {
                            newBallZone = Enums.PitchZone.Corner_HomeRight;
                        }
                        MatchEntry meOpen = new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.OutOfBounds, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            TeamName1 = AwayTeam.Name,
                            OutOfBoundsResult = OutOfBoundsResult.Corner,

                            Zone1 = CurrentBallZone,
                        };
                        LogEntry(meOpen);
                    }
                    else // Away team (attacking home goal) last touched it -> GOAL KICK for Home
                    {
                        newState = Enums.MatchState.GoalKick;
                        ballWinningTeam = HomeTeam;
                        ballLosingTeam = AwayTeam;
                        newBallZone = Enums.PitchZone.GoalkeeperArea_Home;
                        MatchEntry meOpen = new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.OutOfBounds, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            TeamName1 = HomeTeam.Name,
                            OutOfBoundsResult = OutOfBoundsResult.GoalKick,

                            Zone1 = CurrentBallZone,
                        };
                        LogEntry(meOpen);
                    }
                }
                else if (isAwayGoalLineZone) // Ball went out behind Away Team's goal line (Away's defending goal)
                {
                    if (lastTouchTeam == AwayTeam) // Away team (defending their goal) last touched it -> CORNER for Home
                    {
                        newState = Enums.MatchState.CornerKick;
                        ballWinningTeam = HomeTeam;
                        ballLosingTeam = AwayTeam;

                        // Use GetFlankOfZone to determine the specific corner kick zone
                        Enums.Flank exitFlank = GetFlankOfZone(ballExitZone);
                        if (exitFlank == Enums.Flank.Left)
                        {
                            newBallZone = Enums.PitchZone.Corner_AwayLeft;
                        }
                        else // Assume Right or Center, default to Right for corners on this side
                        {
                            newBallZone = Enums.PitchZone.Corner_AwayRight;
                        }
                        MatchEntry meOpen = new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.OutOfBounds, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            TeamName1 = HomeTeam.Name,
                            OutOfBoundsResult = OutOfBoundsResult.Corner,

                            Zone1 = CurrentBallZone,
                        };
                        LogEntry(meOpen);
                    }
                    else // Home team (attacking away goal) last touched it -> GOAL KICK for Away
                    {
                        newState = Enums.MatchState.GoalKick;
                        ballWinningTeam = AwayTeam;
                        ballLosingTeam = HomeTeam;
                        newBallZone = Enums.PitchZone.GoalkeeperArea_Away;
                        MatchEntry meOpen = new MatchEntry
                        {
                            Level = LogLevel.Info,
                            EventType = MatchEventType.OutOfBounds, // Use the general PassOutcome event
                            Timestamp = DateTime.Now,

                            TeamName1 = AwayTeam.Name,
                            OutOfBoundsResult = OutOfBoundsResult.GoalKick,

                            Zone1 = CurrentBallZone,
                        };
                        LogEntry(meOpen);
                    }
                }
                else
                {
                    // Fallback for unexpected goal-line zone. Should ideally not be hit.
                    throw new Exception("No zone defined!");
                }
            }
            else // Ball went out of bounds in a zone that is neither a side line nor a goal line
            {
                // This case should ideally not be hit if all pitch boundaries are covered by the above.
                // It might indicate an unmapped PitchZone.
                throw new Exception("No zone defined!");
            }

            // Apply the determined state
            AttackingTeam = ballWinningTeam;
            DefendingTeam = ballLosingTeam;
            CurrentMatchState = newState;
            CurrentBallZone = newBallZone;
            CurrentBallHolder = null; // Ball is not in possession yet for a set piece
        }

        private void ThrowInHandler()
        {
            CleanPotentialAssistsCreatingActions();

            // --- 1. Choose a player to take the throw-in ---
            Player throwInTaker = AttackingTeam.AvailableOnFieldOutfielders
                .OrderBy(p => CalculateDistance(p.CurrentZone, CurrentBallZone)) // Prefer closest player
                .ThenByDescending(p => p.trueRating.PassingForGameCalculations) // Then by throw-in ability
                .FirstOrDefault();

            if (throwInTaker == null)
            {
                throw new Exception("ERROR: No suitable player found to take throw-in!");
            }

            SetPossession(throwInTaker, CurrentBallZone, AttackingTeam);

            // --- 2. Select Offensive Throw-In Routine ---
            OffensiveThrowInRoutine chosenOffensiveRoutine; // This is now your concrete class
            DefensiveSetPieceRoutine chosenDefensiveRoutine;

            bool isInAttackingThird = IsBallInAttackingHalf(CurrentBallZone, AttackingTeam) && GetZoneForwardValue(CurrentBallZone, AttackingTeam == HomeTeam) >= 7;
            bool hasGoodLongThrower = throwInTaker.trueRating.BalanceForGameCalculations >= 75 && throwInTaker.trueRating.StrengthForGameCalculations >= 70;

            if (isInAttackingThird && hasGoodLongThrower && Dice.d100() < 40)
            {
                chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetRoutineByName<OffensiveThrowInRoutine>("Long Throw to Target Man")
                                        ?? OffensiveThrowInRoutine.CreateDefaultLongThrowRoutine();
            }
            else
            {
                chosenOffensiveRoutine = OffensiveThrowInRoutine.CreateDefaultShortThrowRoutine();
            }

            if (chosenOffensiveRoutine == null)
            {
                throw new Exception("Failed to determine an offensive throw-in routine");
            }
            //ShowMessage("Chosen offensive throw-in routine for " + AttackingTeam.Name + ": " + chosenOffensiveRoutine.Name);

            // --- 3. Determine Defensive Throw-In Routine ---
            chosenDefensiveRoutine = SetPieceRoutineDefinitions.GetDefaultDefensiveThrowInRoutine(); // This also inherits from SetPieceRoutine
            if (chosenDefensiveRoutine == null)
            {
                //ShowMessage("Failed to determine a defensive throw-in routine. Proceeding with basic defense.");
                // This fallback routine's constructor must also match the updated SetPieceRoutine constructor.
                chosenDefensiveRoutine = new DefensiveSetPieceRoutine(
                    "Basic Default Throw-In Defense", "Fallback basic defense", Enums.SetPieceType.ThrowIn,
                    Enums.DefensiveStrategy.ManMarking, false, // Strategy & No wall
                    new Dictionary<Enums.SetPieceRole, List<Enums.Positions>>(), // Empty RoleAssignments
                    new Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone>(), // Empty PreferredRoleConceptualSubZones
                    new Dictionary<Enums.SetPieceRole, Enums.SetPieceRole>() // Empty AttackerRoleToDefenderRoleMapping
                                                                             // No TargetConceptualZone needed for this basic fallback
                    );
            }
            //ShowMessage("Chosen defensive routine for " + DefendingTeam.Name + ": " + chosenDefensiveRoutine.Name);

            // --- 4. Assign Set Piece Roles and Position Players based on routines ---
            // These methods now expect SetPieceRoutine, and OffensiveThrowInRoutine/DefensiveSetPieceRoutine are compatible
            AssignSetPieceRolesForRoutine(AttackingTeam.AvailableOnFieldOutfielders, chosenOffensiveRoutine);
            AssignDefensiveSetPieceRolesForRoutine(DefendingTeam.AvailableOnFieldPlayers, chosenDefensiveRoutine, AttackingTeam.AvailableOnFieldOutfielders);

            // --- 5. Choose a player to throw to (receiver) ---
            Player throwInReceiver = GetBestThrowInReceiver(throwInTaker, AttackingTeam, DefendingTeam, CurrentBallZone, chosenOffensiveRoutine);
            if (throwInReceiver != null)
            {
                throwInReceiver.SimulatedSetPieceZone = throwInReceiver.CurrentZone;
                throwInTaker.SimulatedSetPieceZone = throwInTaker.CurrentZone;
            }
            else
            {
                throw new Exception(throwInTaker.fullName + " has no one to throw to with routine '" + chosenOffensiveRoutine.Name);
            }
            Enums.MatchState previousMatchState = CurrentMatchState;

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.ThrowIn, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                TeamName1 = AttackingTeam.Name,
                PlayerName1 = throwInTaker.fullName,
                Player1Pos = throwInTaker.position,
                PlayerName2 = throwInReceiver.fullName,
                Player2Pos = throwInReceiver.position,

                Zone1 = CurrentBallZone
            };

            PassStyleType pt = PassStyleType.ShortThrowIn;

            // --- 6. Simulate the throw-in (like a pass/cross) ---
            if (chosenOffensiveRoutine.PreferredDeliveryType == Enums.ThrowInDeliveryType.ShortThrow)
            {
                meOpen.PassStyle = pt;
                LogEntry(meOpen);
                Enums.PassOutcome passOutcome = AttemptPass(throwInTaker, AttackingTeam, DefendingTeam, Enums.PassType.Short, throwInReceiver, true,
                    false);
                if (previousMatchState == CurrentMatchState)
                    ConvertPassResultToMatchCondition(passOutcome, throwInTaker);
            }
            else // Assumed to be LongThrowIntoBox
            {
                pt = PassStyleType.LongThrowIn;
                meOpen.PassStyle = pt;
                LogEntry(meOpen);
                Enums.PassOutcome passOutcome = AttemptPass(throwInTaker, AttackingTeam, DefendingTeam, Enums.PassType.Long, throwInReceiver, true,
                    false);
                if (previousMatchState == CurrentMatchState)
                    ConvertPassResultToMatchCondition(passOutcome, throwInTaker);
            }
        }

        private Player GetBestThrowInReceiver(Player throwInTaker, Team attackingTeam, Team defendingTeam, Enums.PitchZone throwInZone, OffensiveThrowInRoutine chosenRoutine)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestThrowInReceiver: throwInTaker:{0},attackingTeam:{1},defendingTeam:{2}," +
            //    "throwInZone:{3},chosenRoutine:{4}",
            //    throwInTaker.position, attackingTeam.Name, defendingTeam.Name, throwInZone, chosenRoutine));


            //ShowMessage("Searching for best throw-in receiver based on routine: " + chosenRoutine.Name);

            Enums.SetPieceRole primaryTargetRole = Enums.SetPieceRole.None;
            // Determine the primary target role for the routine
            if (chosenRoutine.PreferredDeliveryType == Enums.ThrowInDeliveryType.ShortThrow)
            {
                primaryTargetRole = Enums.SetPieceRole.ShortOptionReceiver;
            }
            else if (chosenRoutine.PreferredDeliveryType == Enums.ThrowInDeliveryType.LongThrowIntoBox)
            {
                primaryTargetRole = Enums.SetPieceRole.TargetMan;
                if (!chosenRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.TargetMan) && chosenRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.BoxAttacker))
                {
                    primaryTargetRole = Enums.SetPieceRole.BoxAttacker; // Fallback for long throws if TargetMan not explicitly defined
                }
            }

            List<Enums.Positions> preferredTargetPositions;
            Enums.ConceptualSetPieceZone targetZoneForDelivery;

            // Use the properties from the chosen routine directly
            if (primaryTargetRole != Enums.SetPieceRole.None &&
                chosenRoutine.RoleAssignments.TryGetValue(primaryTargetRole, out preferredTargetPositions) &&
                chosenRoutine.PreferredRoleConceptualSubZones.TryGetValue(primaryTargetRole, out targetZoneForDelivery))
            {
                bool requireUnmarked = chosenRoutine.PreferredDeliveryType == Enums.ThrowInDeliveryType.ShortThrow;

                return FindBestAttackerForRoutineRole(
                    attackingTeam, defendingTeam, preferredTargetPositions, targetZoneForDelivery, throwInTaker, requireUnmarked, null, null, chosenRoutine.PreferredDeliveryType);
            }
            else
            {
                //ShowMessage("No explicit primary target role defined in throw-in routine, using general fallback logic for: " +
                //    EnumCache<Enums.ThrowInDeliveryType>.ToString(chosenRoutine.PreferredDeliveryType));
                // Fallback logic if routine doesn't fully define a target for some reason
                if (chosenRoutine.PreferredDeliveryType == Enums.ThrowInDeliveryType.ShortThrow)
                {
                    preferredTargetPositions = new List<Enums.Positions> { Enums.Positions.CentralMidfielder, Enums.Positions.LeftBack, Enums.Positions.RightBack, Enums.Positions.CentralDefendingMidfielder };
                    targetZoneForDelivery = Enums.ConceptualSetPieceZone.OpponentAttackingThird_Flank;
                    return FindBestAttackerForRoutineRole(attackingTeam, defendingTeam, preferredTargetPositions, targetZoneForDelivery, throwInTaker, true, null, null, chosenRoutine.PreferredDeliveryType);
                }
                else // Long throw fallback
                {
                    preferredTargetPositions = new List<Enums.Positions> { Enums.Positions.Striker, Enums.Positions.CenterBack, Enums.Positions.CentralMidfielder };
                    targetZoneForDelivery = Enums.ConceptualSetPieceZone.OpponentPenaltyArea_Central;
                    return FindBestAttackerForRoutineRole(attackingTeam, defendingTeam, preferredTargetPositions, targetZoneForDelivery, throwInTaker, false, null, null, chosenRoutine.PreferredDeliveryType);
                }
            }
        }

        #endregion

        #region Set Pieces Kicking

        private double CalculatePlayerScoreAttackPlayerFreeKicks(Player p)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculatePlayerScoreAttackPlayerFreeKicks: p:{0}",
            //    p.position));


            double score = p.trueRating.HeaderForGameCalculations * 0.4 +
               p.trueRating.JumpingForGameCalculations * 0.3 +
               p.trueRating.PositioningForGameCalculations * 0.2;

            if (p.Position == Enums.Positions.Striker || p.Position == Enums.Positions.CentralAttackingMidfielder)
            {
                score += 100;
            }

            return score;
        }

        // --- The Refactored FreeKickHandler Method ---
        public void FreeKickHandler(Team attackingTeam, Team defendingTeam, Enums.PitchZone freeKickZone, bool isDirect)
        {
            // Set global properties for convenience
            this.AttackingTeam = attackingTeam;
            this.DefendingTeam = defendingTeam;
            this.CurrentBallZone = freeKickZone;

            CleanPotentialAssistsCreatingActions();
            //ShowMessage("Initiating FreeKickHandler for " + AttackingTeam.Name + " (Direct: " + isDirect + ").");

            CurrentMatchState = (isDirect ? Enums.MatchState.FreeKick : Enums.MatchState.FreeKick_Indirect);

            // Position players (defensive wall, general attacking positions)
            // This method should *ideally* use the chosen defensive routine for the wall setup
            PositionPlayersForFreeKick(AttackingTeam, DefendingTeam, CurrentBallZone);

            Player freeKickTaker = AttackingTeam.AvailableOnFieldOutfielders
                .OrderByDescending(p => p.trueRating.freekicks * 0.6 + p.trueRating.PassingForGameCalculations * 0.4)
                .FirstOrDefault();

            _lastPasser = freeKickTaker;
            this.CurrentBallHolder = freeKickTaker;
            this.CurrentBallHolder.CurrentZone = freeKickZone;

            if (freeKickTaker == null)
            {
                throw new Exception("No suitable non-goalkeeper player found to take the free kick!");
            }

            freeKickTaker.CurrentZone = CurrentBallZone;
            //ShowMessage("Free kick taker " + freeKickTaker.fullName + " confirmed at " + CurrentBallZone + ".");

            // --- NEW: Select Offensive Free Kick Routine ---
            OffensiveFreeKickRoutine chosenOffensiveRoutine = null;
            DefensiveSetPieceRoutine chosenDefensiveRoutine = null;

            // First, try to select an offensive routine that matches direct/indirect and shooting range
            bool isInShootingRange = IsBallInAttackingHalf(CurrentBallZone, AttackingTeam) && GetZoneForwardValue(CurrentBallZone, AttackingTeam == HomeTeam) >= 5;

            if (isDirect && isInShootingRange)
            {
                double directShotChance = freeKickTaker.trueRating.freekicks * 0.8 * ((10 - GetZoneForwardValue(CurrentBallZone, AttackingTeam == HomeTeam)) / 10.0);
                directShotChance = Math.Min(90, directShotChance);

                int decisionRoll = Dice.d100();
                //ShowMessage("Free kick decision roll: " + decisionRoll + " (Target for direct shot: < " + directShotChance + ").");

                if (decisionRoll < directShotChance)
                {
                    chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetRoutineByName<OffensiveFreeKickRoutine>("Direct Free Kick Shot"); // You'd define this routine
                    if (chosenOffensiveRoutine == null)
                    {
                        //ShowMessage("Direct shot routine not found, falling back to default pass routine.");
                        chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetDefaultOffensiveFreeKickRoutine();
                    }
                }
                else
                {
                    // If not shooting, pick a passing routine
                    chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetDefaultOffensiveFreeKickRoutine(); // Or a more complex decision
                }
            }
            else // Indirect or not in shooting range for direct shot
            {
                //ShowMessage("This is an indirect free kick or not in ideal shooting range. Player will opt for a pass/cross.");
                chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetDefaultOffensiveFreeKickRoutine(); // Or a more complex decision for indirect
            }

            if (chosenOffensiveRoutine == null)
            {
                throw new Exception("Failed to determine an offensive free kick routine.");
            }

            //ShowMessage("Chosen offensive free kick routine for " + AttackingTeam.Name + ": " + chosenOffensiveRoutine.Name + " (Direct Shot: " + chosenOffensiveRoutine.IsDirectShotAttempt + ")");

            // Select Defensive Free Kick Routine (you'd need to create default/named ones for this too)
            // For now, let's assume a default defensive free kick routine exists.
            chosenDefensiveRoutine = SetPieceRoutineDefinitions.GetDefaultDefensiveFreeKickRoutine();
            if (chosenDefensiveRoutine == null)
            {
                //ShowMessage("Failed to determine a defensive free kick routine. Proceeding with basic defense.");
                chosenDefensiveRoutine = new DefensiveSetPieceRoutine("Basic Default Free Kick Defense", "Fallback basic defense", Enums.SetPieceType.FreeKick, Enums.DefensiveStrategy.HybridMarking, true, new Dictionary<Enums.SetPieceRole, List<Enums.Positions>>(), new Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone>(), new Dictionary<Enums.SetPieceRole, Enums.SetPieceRole>());
            }
            //ShowMessage("Chosen defensive routine for " + DefendingTeam.Name + ": " + chosenDefensiveRoutine.Name);


            // --- Assign Set Piece Roles and Position Players based on the chosen routines ---
            AssignSetPieceRolesForRoutine(AttackingTeam.AvailableOnFieldOutfielders, chosenOffensiveRoutine);
            AssignDefensiveSetPieceRolesForRoutine(DefendingTeam.AvailableOnFieldPlayers, chosenDefensiveRoutine, AttackingTeam.AvailableOnFieldOutfielders);

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.FreeKick, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = freeKickTaker.fullName,
                Player1Pos = freeKickTaker.position,
                TeamName1 = AttackingTeam.Name,

                Zone1 = CurrentBallZone,
            };
            LogEntry(meOpen);

            // --- Execute the routine ---
            if (chosenOffensiveRoutine.IsDirectShotAttempt)
            {
                //ShowMessage(freeKickTaker.fullName + " takes a shot directly from the free kick!");
                SetPossession(freeKickTaker, CurrentBallZone, AttackingTeam);

                // Defensive wall reactions (no longer tied to specific routine logic here, but overall free kick processing)
                // The WallPlayer role assignment in AssignDefensiveSetPieceRolesForRoutine implicitly positions them
                // Now they just need to react
                foreach (Player defender in DefendingTeam.AvailableOnFieldOutfielders.Where(p => p.DefensiveSetPieceRole == Enums.SetPieceRole.WallPlayer))
                {
                    // Wall players might react to the shot by jumping or moving.
                    // Their CurrentZone might already be adjusted by PositionPlayersForFreeKick if you keep it.
                }

                Enums.ShotOutcome shotOutcome = AttemptShot(freeKickTaker, AttackingTeam, DefendingTeam, Enums.ShotType.DirectFreeKick, true, null);
                //ShowMessage("Direct free kick shot outcome: " + shotOutcome + ".");
            }
            else // It's a pass/cross routine
            {
                //ShowMessage(freeKickTaker.fullName + " opts to pass/cross from the free kick.");

                // Find the best receiver for the chosen passing routine
                Player bestReceiver = null;
                Enums.ConceptualSetPieceZone bestTargetConceptualZone = chosenOffensiveRoutine.TargetConceptualZone;
                List<Enums.Positions> preferredTargetPositions = new List<Enums.Positions>();

                // For passes, generally look for a ShortOptionReceiver or TargetMan/BoxAttacker if crossing.
                Enums.SetPieceRole primaryTargetRole = Enums.SetPieceRole.None;
                if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.ShortOptionReceiver)) primaryTargetRole = Enums.SetPieceRole.ShortOptionReceiver;
                else if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.TargetMan)) primaryTargetRole = Enums.SetPieceRole.TargetMan;
                else if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.BoxAttacker)) primaryTargetRole = Enums.SetPieceRole.BoxAttacker;

                if (primaryTargetRole != Enums.SetPieceRole.None &&
                    chosenOffensiveRoutine.RoleAssignments.TryGetValue(primaryTargetRole, out preferredTargetPositions) &&
                    chosenOffensiveRoutine.PreferredRoleConceptualSubZones.TryGetValue(primaryTargetRole, out bestTargetConceptualZone))
                {
                    // If it's a short pass type, prioritize unmarked. For crosses, marked players are okay.
                    bool requireUnmarked = chosenOffensiveRoutine.PreferredDeliveryType == Enums.FreeKickDeliveryType.ShortPass;

                    bestReceiver = FindBestAttackerForRoutineRole(
                        AttackingTeam, DefendingTeam, preferredTargetPositions, bestTargetConceptualZone, freeKickTaker, requireUnmarked, null, chosenOffensiveRoutine.PreferredDeliveryType); // Pass nulls for corner type
                }
                else
                {
                    //ShowMessage("Routine '" + chosenOffensiveRoutine.Name + "' has no explicit primary target role. Using general passing logic.");
                    // Fallback: look for any attacker in the primary target zone
                    preferredTargetPositions = new List<Enums.Positions> { Enums.Positions.Striker, Enums.Positions.CentralMidfielder, Enums.Positions.LeftWingForward, Enums.Positions.RightWingForward };
                    bestReceiver = FindBestAttackerForRoutineRole(AttackingTeam, DefendingTeam, preferredTargetPositions, bestTargetConceptualZone, freeKickTaker, false, null, chosenOffensiveRoutine.PreferredDeliveryType); // Pass nulls for corner type
                }
                if (bestReceiver == null)
                {
                    bestReceiver = FindNearestTeammate(freeKickTaker, AttackingTeam, true);
                    bestReceiver.targetSetPieceZone = bestReceiver.CurrentZone;
                }
                if (bestReceiver == null)
                {
                    throw new Exception(freeKickTaker.fullName + " has no clear optimal target for the free kick pass/cross!");
                }

                //ShowMessage("Optimal target for pass/cross: " + bestReceiver.fullName + " to move into " + bestReceiver.SimulatedSetPieceZone + " (Score: calculated within FindBestAttackerForRoutineRole).");

                SetPossession(freeKickTaker, CurrentBallZone, AttackingTeam);

                // Defensive wall re-engagement (clear wall flags here, as the action is taken)
                ClearWallPlayerFlags(DefendingTeam); // Clear here as the ball is now in play or crossed
                Enums.MatchState previousMatchState = CurrentMatchState;
                if (chosenOffensiveRoutine.PreferredDeliveryType == Enums.FreeKickDeliveryType.LoftedPassIntoBox)
                {
                    //ShowMessage(freeKickTaker.fullName + " crosses the free kick towards " + bestReceiver.fullName + " in " + bestReceiver.SimulatedSetPieceZone + "!");
                    Enums.CrossOutcome crossOutcome = ProcessCrossAttempt(freeKickTaker, AttackingTeam, DefendingTeam, bestReceiver, true);
                    //ShowMessage("Cross attempt outcome: " + crossOutcome + ".");
                    if (previousMatchState == CurrentMatchState)
                        ConvertCrossResultToMatchCondition(crossOutcome, freeKickTaker);
                }
                else // Assume it's a direct pass of some kind
                {
                    Enums.PassType passType = CalculateDistance(freeKickTaker.CurrentZone, bestReceiver.SimulatedSetPieceZone) < 4.0f ? Enums.PassType.Short : Enums.PassType.Long;
                    //ShowMessage("Attempting " + passType + " pass from free kick to " + bestReceiver.fullName + " in " + bestReceiver.SimulatedSetPieceZone + "!");
                    Enums.PassOutcome passOutcome = AttemptPass(freeKickTaker, AttackingTeam, DefendingTeam, passType, bestReceiver, true);
                    //ShowMessage("Pass attempt outcome: " + passOutcome + ".");
                    if (CurrentMatchState == Enums.MatchState.FreeKick_Indirect || CurrentMatchState == Enums.MatchState.FreeKick)
                    {
                        int x = 0;
                    }
                    if (previousMatchState == CurrentMatchState)
                        ConvertPassResultToMatchCondition(passOutcome, freeKickTaker, passType == PassType.Long);
                }
            }

            //ShowMessage("FreeKickHandler finished processing.");
            //CurrentMatchState = Enums.MatchState.InPlay_Possession;
            ClearWallPlayerFlags(DefendingTeam); // Ensure cleared even if shot happened
        }

        // --- Auxiliary Handler Methods (unchanged, as they just call the main handler) ---
        public void IndirectFreeKickHandler(Team attackingTeam, Team defendingTeam, Enums.PitchZone freeKickZone)
        {
            FreeKickHandler(attackingTeam, defendingTeam, freeKickZone, false);
        }

        public void DirectFreeKickHandler(Team attackingTeam, Team defendingTeam, Enums.PitchZone freeKickZone)
        {
            FreeKickHandler(attackingTeam, defendingTeam, freeKickZone, true);
        }

        // This method would typically reside in your SetPieceRoutineDefinitions static class
        // or a similar class responsible for providing pre-defined routines.
        public OffensiveFreeKickRoutine GetDefaultOffensiveFreeKickRoutine()
        {
            // This routine represents a common free-kick strategy: a lofted ball into the box
            // targeting a player, with others positioned for rebounds or support.
            return new OffensiveFreeKickRoutine(
                name: "Default Lofted Free Kick into Box",
                description: "A standard offensive free kick, aiming for an aerial duel in the box.",
                preferredDeliveryType: Enums.FreeKickDeliveryType.LoftedPassIntoBox,
                preferredTargetType: Enums.SetPieceTargetType.SpecificPlayer, // Targeting a specific player (e.g., TargetMan)
                targetConceptualZone: Enums.ConceptualSetPieceZone.OpponentPenaltyArea_Central, // Primary target zone for the delivery
                roleAssignments: new Dictionary<Enums.SetPieceRole, List<Enums.Positions>> // Using Enums.Positions
        {
            // Set Piece Taker: Players good at passing or crossing, often midfielders or fullbacks
            { Enums.SetPieceRole.SetPieceTaker, new List<Enums.Positions> { Enums.Positions.CentralMidfielder, Enums.Positions.CentralAttackingMidfielder, Enums.Positions.LeftBack, Enums.Positions.RightBack } },

            // Target Man: Players strong in the air, typically Strikers or tall Center Backs
            { Enums.SetPieceRole.TargetMan, new List<Enums.Positions> { Enums.Positions.Striker, Enums.Positions.CenterBack } },

            // Box Attacker: Other players looking to get into the box for headers or volleys
            { Enums.SetPieceRole.BoxAttacker, new List<Enums.Positions> { Enums.Positions.Striker, Enums.Positions.CentralMidfielder, Enums.Positions.CentralAttackingMidfielder } },

            // Rebound Attacker: Players positioned outside the box for rebounds or clearances
            { Enums.SetPieceRole.ReboundAttacker, new List<Enums.Positions> { Enums.Positions.CentralDefendingMidfielder, Enums.Positions.CentralMidfielder } },

            // Midfield Support: Player stays deeper for defensive cover against counters
            { Enums.SetPieceRole.MidfieldSupport, new List<Enums.Positions> { Enums.Positions.CentralDefendingMidfielder, Enums.Positions.CentralMidfielder } }
        },
                preferredRoleConceptualSubZones: new Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone>
        {
            // Set Piece Taker
            { Enums.SetPieceRole.SetPieceTaker, Enums.ConceptualSetPieceZone.EdgeOfBox }, // Or specific FreeKickSpot zones if defined

            // Target Man: Positioned in the central penalty area for the cross
            { Enums.SetPieceRole.TargetMan, Enums.ConceptualSetPieceZone.OpponentPenaltyArea_Central },

            // Box Attackers: Run into general penalty area zones
            { Enums.SetPieceRole.BoxAttacker, Enums.ConceptualSetPieceZone.OpponentPenaltyArea_General },

            // Rebound Attacker: Positioned at the edge of the box
            { Enums.SetPieceRole.ReboundAttacker, Enums.ConceptualSetPieceZone.EdgeOfBox },

            // Midfield Support: Stays in deeper midfield
            { Enums.SetPieceRole.MidfieldSupport, Enums.ConceptualSetPieceZone.Midfield_Center }
        },
                isDirectShotAttempt: false, // This is not a direct shot routine
                applicableFlank: null,     // Applies to free kicks from both sides (if centrally located)
                isHomeTeamSpecific: false,
                isAwayTeamSpecific: false
            );
        }

        public void CornerKickHandler()
        {
            AttackingTeam.gameStats.cornerKicks++;
            //if (AttackingTeam.gameStats.cornerKicks > 15)
            //{
            //    throw new Exception("Excessive corner kicks");
            //}
            //ShowMessage("Initiating CornerKickHandler for " + AttackingTeam.Name + ".");

            // --- 1. Choose a player to take the corner kick and assign SetPieceRole ---
            Player cornerTaker = AttackingTeam.AvailableOnFieldOutfielders
                .OrderByDescending(p => p.trueRating.PassingForGameCalculations * 0.7 + p.trueRating.VisionForGameCalculations * 0.3 + p.trueRating.freekicks * 0.2)
                .FirstOrDefault();

            if (cornerTaker == null)
            {
                throw new Exception("No suitable non-goalkeeper player found to take the corner kick!");
            }

            // Set possession and taker's zone
            SetPossession(cornerTaker, CurrentBallZone, AttackingTeam);
            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.CornerKick, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = cornerTaker.fullName,
                Player1Pos = cornerTaker.position,
                TeamName1 = AttackingTeam.Name,

                Zone1 = CurrentBallZone,
            };
            LogEntry(meOpen);

            // --- 2. Select Offensive Corner Routine based on AI decision (or team strategy) ---
            OffensiveCornerRoutine chosenOffensiveRoutine;

            if (cornerTaker.trueRating.PassingForGameCalculations > 75 &&
                AttackingTeam.AvailableOnFieldOutfielders.Any(p => p.Position == Enums.Positions.CentralMidfielder && CalculateDistance(p.CurrentZone, CurrentBallZone) < 5.0f))
            {
                chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetRoutineByName<OffensiveCornerRoutine>("Short Corner Play");
            }
            else
            {
                chosenOffensiveRoutine = SetPieceRoutineDefinitions.GetDefaultOffensiveCornerRoutine();
            }

            if (chosenOffensiveRoutine == null)
            {
                throw new Exception("Failed to determine an offensive corner routine.");
            }

            //ShowMessage("Chosen offensive corner routine for " + AttackingTeam.Name + ": " + chosenOffensiveRoutine.Name);

            // --- 3. Determine the active Defensive Corner Routine ---
            DefensiveSetPieceRoutine chosenDefensiveRoutine = SetPieceRoutineDefinitions.GetDefaultDefensiveCornerRoutine();

            if (chosenDefensiveRoutine == null)
            {
                //ShowMessage("Failed to determine a defensive corner routine. Proceeding with basic defense.");
                chosenDefensiveRoutine = new DefensiveSetPieceRoutine("Basic Default Defense", "Fallback basic defense", Enums.SetPieceType.CornerKick, Enums.DefensiveStrategy.HybridMarking, false, new Dictionary<Enums.SetPieceRole, List<Enums.Positions>>(), new Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone>(), new Dictionary<Enums.SetPieceRole, Enums.SetPieceRole>());
            }
            //ShowMessage("Chosen defensive routine for " + DefendingTeam.Name + ": " + chosenDefensiveRoutine.Name);

            // --- 4. Assign Set Piece Roles and Position Players based on the chosen routines ---
            AssignSetPieceRolesForRoutine(AttackingTeam.AvailableOnFieldOutfielders, chosenOffensiveRoutine);
            AssignDefensiveSetPieceRolesForRoutine(DefendingTeam.AvailableOnFieldPlayers, chosenDefensiveRoutine, AttackingTeam.AvailableOnFieldOutfielders);

            // --- 5. Find the primary target player for the chosen offensive routine ---
            Player targetPlayerForCorner = null;
            Enums.ConceptualSetPieceZone targetZoneForDelivery = Enums.ConceptualSetPieceZone.None;
            List<Enums.Positions> preferredTargetPositions = new List<Enums.Positions>();

            if (chosenOffensiveRoutine.PreferredDeliveryType == Enums.CornerDeliveryType.ShortPass)
            {
                if (chosenOffensiveRoutine.RoleAssignments.TryGetValue(Enums.SetPieceRole.ShortOptionReceiver, out preferredTargetPositions) &&
                    chosenOffensiveRoutine.PreferredRoleConceptualSubZones.TryGetValue(Enums.SetPieceRole.ShortOptionReceiver, out targetZoneForDelivery))
                {
                    targetPlayerForCorner = FindBestAttackerForRoutineRole(AttackingTeam, DefendingTeam, preferredTargetPositions, targetZoneForDelivery, cornerTaker, true, chosenOffensiveRoutine.PreferredDeliveryType, null);
                }
                else
                {
                    //ShowMessage("Short corner routine missing ShortOptionReceiver definition. Fallback target search.");
                    targetZoneForDelivery = Enums.ConceptualSetPieceZone.ShortCornerArea;
                    preferredTargetPositions = new List<Enums.Positions> { Enums.Positions.LeftBack, Enums.Positions.RightBack, Enums.Positions.CentralMidfielder, Enums.Positions.CentralAttackingMidfielder };
                    targetPlayerForCorner = FindBestAttackerForRoutineRole(AttackingTeam, DefendingTeam, preferredTargetPositions, targetZoneForDelivery, cornerTaker, true, chosenOffensiveRoutine.PreferredDeliveryType, null); // Pass nulls for freekick types
                }
            }
            else // It's a cross-based routine
            {
                Enums.SetPieceRole primaryTargetRole = Enums.SetPieceRole.None;
                if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.TargetMan)) primaryTargetRole = Enums.SetPieceRole.TargetMan;
                else if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.NearPostRunner)) primaryTargetRole = Enums.SetPieceRole.NearPostRunner;
                else if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.FarPostThreat)) primaryTargetRole = Enums.SetPieceRole.FarPostThreat;
                else if (chosenOffensiveRoutine.RoleAssignments.ContainsKey(Enums.SetPieceRole.BoxAttacker)) primaryTargetRole = Enums.SetPieceRole.BoxAttacker;

                if (primaryTargetRole != Enums.SetPieceRole.None &&
                    chosenOffensiveRoutine.RoleAssignments.TryGetValue(primaryTargetRole, out preferredTargetPositions) &&
                    chosenOffensiveRoutine.PreferredRoleConceptualSubZones.TryGetValue(primaryTargetRole, out targetZoneForDelivery))
                {
                    targetPlayerForCorner = FindBestAttackerForRoutineRole(
                        AttackingTeam, DefendingTeam, preferredTargetPositions, targetZoneForDelivery, cornerTaker, false, chosenOffensiveRoutine.PreferredDeliveryType, null); // Pass nulls for freekick types
                }
                else
                {
                    //ShowMessage("Routine '" + chosenOffensiveRoutine.Name + "' has no explicit primary target role, defaulting to general box attacker logic.");
                    targetZoneForDelivery = chosenOffensiveRoutine.TargetConceptualZone;
                    preferredTargetPositions = new List<Enums.Positions> { Enums.Positions.Striker, Enums.Positions.CenterBack, Enums.Positions.CentralMidfielder };
                    targetPlayerForCorner = FindBestAttackerForRoutineRole(AttackingTeam, DefendingTeam, preferredTargetPositions, targetZoneForDelivery, cornerTaker, false, chosenOffensiveRoutine.PreferredDeliveryType, null); // Pass nulls for freekick types
                }
            }

            if (targetPlayerForCorner == null)
            {
                throw new Exception("No viable attacking target player found for the " + chosenOffensiveRoutine.PreferredDeliveryType);
            }

            //ShowMessage("Optimal target for " + chosenOffensiveRoutine.PreferredDeliveryType + ": " + targetPlayerForCorner.fullName + " to move into " + targetPlayerForCorner.SimulatedSetPieceZone + ".");
            Enums.MatchState previousMatchState = CurrentMatchState;

            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }

            // --- 6. Execute the routine based on its DeliveryType and roles ---
            if (chosenOffensiveRoutine.PreferredDeliveryType == Enums.CornerDeliveryType.ShortPass)
            {
                //ShowMessage(cornerTaker.fullName + " attempts a short pass to " + targetPlayerForCorner.fullName + "!");
                cornerTaker.SimulatedSetPieceZone = cornerTaker.CurrentZone;
                Enums.PassOutcome passOutcome = AttemptPass(cornerTaker, AttackingTeam, DefendingTeam, Enums.PassType.Short, targetPlayerForCorner, true);
                //ShowMessage("Short corner pass outcome: " + passOutcome + ".");
                if (previousMatchState == CurrentMatchState)
                    ConvertPassResultToMatchCondition(passOutcome, cornerTaker, true, Enums.CornerDeliveryType.ShortPass);
            }
            else // It's a cross
            {
                //ShowMessage(cornerTaker.fullName + " delivers a " +
                //EnumCache<Enums.CornerDeliveryType>.ToString(chosenOffensiveRoutine.PreferredDeliveryType).Replace("Outswinger", "outswinging ").Replace("Inswinger", "inswinging ").Replace("Lofted", "lofted ").Replace("Driven", "driven ") + "cross!");
                Enums.CrossOutcome crossOutcome = ProcessCrossAttempt(cornerTaker, AttackingTeam, DefendingTeam, targetPlayerForCorner, true, chosenOffensiveRoutine.PreferredDeliveryType);
                //ShowMessage("Corner kick cross outcome: " + crossOutcome + ".");
                if (previousMatchState == CurrentMatchState)
                    ConvertCrossResultToMatchCondition(crossOutcome, cornerTaker);
            }

            if (CurrentBallHolder == null && CurrentMatchState == MatchState.InPlay_Possession)
            {
                int x = 0;
            }

            //ShowMessage("CornerKickHandler finished processing.");
            //CurrentMatchState = Enums.MatchState.InPlay_Possession;
        }

        // Assuming this is within your MatchEngine or FreeKickHandler class
        // It might need access to 'homeTeam' variable.
        public bool IsInswinger(Player taker, Enums.PitchZone cornerZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsInswinger: taker:{0},cornerZone:{1},isAttackingTeamHome:{2}",
            //    taker.position, cornerZone, isAttackingTeamHome));


            // First, determine if the corner is on the left or right side of the pitch from the attacking team's perspective.
            bool isLeftCorner;
            if (isAttackingTeamHome)
            {
                // Home team attacking (scoring towards 'Away' goal)
                // Left corner for home team is Corner_AwayLeft
                isLeftCorner = (cornerZone == Enums.PitchZone.Corner_AwayLeft);
            }
            else
            {
                // Away team attacking (scoring towards 'Home' goal)
                // Left corner for away team is Corner_HomeLeft
                isLeftCorner = (cornerZone == Enums.PitchZone.Corner_HomeLeft);
            }

            // An inswinger means the ball curves TOWARDS the goal.
            // This happens when the taker's preferred foot is on the same side as the corner.
            // Example: Right-footed player on the right corner -> inswinger (ball curves left into goal)
            // Example: Left-footed player on the left corner -> inswinger (ball curves right into goal)
            if (isLeftCorner)
            {
                // For a left corner, a left-footed player generates inswing.
                return taker.preferredFoot == Enums.Foot.Left;
            }
            else // isRightCorner
            {
                // For a right corner, a right-footed player generates inswing.
                return taker.preferredFoot == Enums.Foot.Right;
            }
        }

        /// <summary>
        /// Decides the type of corner delivery (Lofted/Driven) based on taker and team attributes.
        /// Assumes IsInswinger has already determined the inswing/outswing.
        /// </summary>
        /// <param name="taker">The player taking the corner.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="isInswinger">True if the delivery is an inswinger, false if outswinger.</param>
        /// <returns>The chosen CornerDeliveryType (Lofted or Driven).</returns>
        public Enums.CornerDeliveryType DecideCornerDeliveryHeight(Player taker, Team attackingTeam, Team defendingTeam, bool isInswinger)
        {
            // Factors to consider:
            // 1. Taker's Power and Crossing
            // 2. Presence of aerial threats in attacking team
            // 3. Presence of tall defenders in defending team (simpler: overall height/heading defense)

            double takerDrivenPreference = taker.trueRating.LongPassForGameCalculations * 0.7 + taker.trueRating.CrossingForGameCalculations * 0.3; // Emphasize power

            // Count attacking aerial threats (e.g., players with Heading > 70 and Jumping > 70)
            int attackingAerialThreats = attackingTeam.AvailableOnFieldOutfielders
                .Count(p => p.trueRating.HeaderForGameCalculations > 70 && p.trueRating.JumpingForGameCalculations > 70);

            // Estimate defensive aerial strength (e.g., average heading/jumping of central defenders)
            double defensiveAerialStrength = defendingTeam.AvailableOnFieldOutfielders
                .Where(p => p.Position == Enums.Positions.CenterBack || p.Position == Enums.Positions.CentralDefendingMidfielder)
                .Average(p => (p.trueRating.HeaderForGameCalculations + p.trueRating.JumpingForGameCalculations) / 2.0);

            // --- Decision Logic ---
            Enums.CornerDeliveryType chosenType;
            if (takerDrivenPreference > 75 && attackingAerialThreats < 2 && defensiveAerialStrength > 70)
            {
                // Taker is powerful, fewer aerial targets, and defense is good in the air: Favor driven
                //ShowMessage(taker.fullName + " opts for a driven corner kick to bypass aerial defense.");
                chosenType = isInswinger ? Enums.CornerDeliveryType.InswingerDriven : Enums.CornerDeliveryType.OutswingerDriven;
            }
            else if (attackingAerialThreats >= 2 && defensiveAerialStrength < 75)
            {
                // Multiple aerial threats and defense not strong in air: Favor lofted
                //ShowMessage(taker.fullName + " opts for a lofted corner kick to find aerial threats.");
                chosenType = isInswinger ? Enums.CornerDeliveryType.InswingerLofted : Enums.CornerDeliveryType.OutswingerLofted;
            }
            else
            {
                // Default to lofted as it's generally safer and allows more time for runs
                //ShowMessage(taker.fullName + " opts for a standard lofted corner kick.");
                chosenType = isInswinger ? Enums.CornerDeliveryType.InswingerLofted : Enums.CornerDeliveryType.OutswingerLofted;
            }
            return chosenType;
        }

        /// <summary>
        /// Decides the overall type of corner delivery (Lofted/Driven/ShortPass, and Inswinger/Outswinger).
        /// </summary>
        /// <param name="taker">The player taking the corner.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="cornerZone">The PitchZone where the corner kick is located.</param>
        /// <returns>The chosen CornerDeliveryType.</returns>
        public Enums.CornerDeliveryType DecideCornerDeliveryType(Player taker, Team attackingTeam, Team defendingTeam, Enums.PitchZone cornerZone)
        {
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam); // Assuming 'homeTeam' is accessible

            // --- 1. Short Corner Decision Logic ---
            // Factors: Taker's passing, presence of nearby teammate, defensive pressure on the box, tactical preference.
            double shortCornerChance = 0;
            Player nearestTeammate = FindNearestTeammate(taker, attackingTeam, true, 2); // Find teammate within 2 zones

            if (nearestTeammate != null && !IsPlayerHeavilyMarked(nearestTeammate, defendingTeam)) // You'd need to implement IsMarkedHeavily() for player
            {
                // Base chance on taker's passing/vision and teammate's first touch
                shortCornerChance = (taker.trueRating.PassingForGameCalculations * 0.4 +
                                     taker.trueRating.VisionForGameCalculations * 0.3 +
                                     nearestTeammate.trueRating.FinishingForGameCalculations * 0.3) / 100.0;

                // Adjust for defensive congestion in the box (e.g., if many defenders in PenaltyArea_Away)
                int defendersInBox = CountDefendersInZone(isHomeTeamAttacking ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home, defendingTeam);
                if (defendersInBox > 5) shortCornerChance += 0.2; // Increase chance if box is crowded
                if (defendersInBox < 3) shortCornerChance -= 0.1; // Decrease chance if box is sparse

                // Tactical preference (you could add a team tactic setting here)
                // For now, let's have a base chance to consider it.
                shortCornerChance += 0.1; // Base tactical inclination for a short corner
            }

            if (Dice.d100() < (shortCornerChance * 100)) // Roll against the calculated chance
            {
                //ShowMessage(taker.fullName + " opts for a short corner.");
                return Enums.CornerDeliveryType.ShortPass;
            }

            // --- 2. Inswinger/Outswinger Decision (If not a short corner) ---
            bool isInswingerDelivery = IsInswinger(taker, cornerZone, isHomeTeamAttacking);

            // --- 3. Driven/Lofted Decision (If not a short corner) ---
            double takerDrivenPreference = taker.trueRating.LongPassForGameCalculations * 0.7 + taker.trueRating.CrossingForGameCalculations * 0.3;

            int attackingAerialThreats = attackingTeam.AvailableOnFieldOutfielders
                .Count(p => p.trueRating.HeaderForGameCalculations > 70 && p.trueRating.JumpingForGameCalculations > 70);

            double defensiveAerialStrength = defendingTeam.AvailableOnFieldOutfielders
                .Where(p => p.Position == Enums.Positions.CenterBack || p.Position == Enums.Positions.CentralDefendingMidfielder)
                .Average(p => (p.trueRating.HeaderForGameCalculations + p.trueRating.JumpingForGameCalculations) / 2.0);

            Enums.CornerDeliveryType chosenType;
            if (takerDrivenPreference > 75 && attackingAerialThreats < 2 && defensiveAerialStrength > 70)
            {
                //ShowMessage(taker.fullName + " opts for a driven corner kick.");
                chosenType = isInswingerDelivery ? Enums.CornerDeliveryType.InswingerDriven : Enums.CornerDeliveryType.OutswingerDriven;
            }
            else if (attackingAerialThreats >= 2 && defensiveAerialStrength < 75)
            {
                //ShowMessage(taker.fullName + " opts for a lofted corner kick to find aerial threats.");
                chosenType = isInswingerDelivery ? Enums.CornerDeliveryType.InswingerLofted : Enums.CornerDeliveryType.OutswingerLofted;
            }
            else
            {
                //ShowMessage(taker.fullName + " opts for a standard lofted corner kick.");
                chosenType = isInswingerDelivery ? Enums.CornerDeliveryType.InswingerLofted : Enums.CornerDeliveryType.OutswingerLofted;
            }
            return chosenType;
        }

        List<Player> GetWallPlayers(List<Player> availableDefenders, bool isDefendingTeamHome, int MaxWallPlayers)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetWallPlayers: availableDefenders:{0},isDefendingTeamHome:{1},MaxWallPlayers:{2}",
            //    string.Join(",", availableDefenders.Select(p => p.position)),
            //    isDefendingTeamHome,
            //    MaxWallPlayers));


            int wallPlayersNeeded = Math.Min(MaxWallPlayers, availableDefenders.Count);
            List<Player> wallCandidates = new List<Player>(availableDefenders);

            wallCandidates.Sort((a, b) =>
            {
                // Primary sort: Strength + Aggression (descending)
                int primaryCompare = (b.trueRating.StrengthForGameCalculations + b.trueRating.AggressionForGameCalculations)
                    .CompareTo(a.trueRating.StrengthForGameCalculations + a.trueRating.AggressionForGameCalculations);

                if (primaryCompare != 0) return primaryCompare;

                // Secondary sort: Zone forward value (ascending)
                return GetZoneForwardValue(a.CurrentZone, isDefendingTeamHome)
                    .CompareTo(GetZoneForwardValue(b.CurrentZone, isDefendingTeamHome));
            });

            return wallCandidates.GetRange(0, wallPlayersNeeded);
        }

        /// <summary>
        /// Assigns specific defensive set piece roles to players based on the chosen defensive routine.
        /// This considers marking strategies and player attributes.
        /// </summary>
        /// <param name="defendingPlayers">The array of players for the defending team.</param>
        /// <param name="defensiveRoutine">The specific DefensiveSetPieceRoutine.</param>
        /// <param name="attackingPlayers">The attacking team's players, needed for man-marking assignments.</param>
        private void AssignDefensiveSetPieceRolesForRoutine(
            IEnumerable<Player> defendingPlayers,
            DefensiveSetPieceRoutine defensiveRoutine,
            IEnumerable<Player> attackingPlayers)
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignDefensiveSetPieceRolesForRoutine: defendingPlayers:{0},defensiveRoutine:{1},attackingPlayers:{2}",
            //    string.Join(",", defendingPlayers.Select(p => p.position)),
            //    defensiveRoutine,
            //    string.Join(",", attackingPlayers.Select(p => p.position))));


            // Clear previous defensive set piece roles
            foreach (var p in defendingPlayers)
            {
                p.DefensiveSetPieceRole = Enums.SetPieceRole.None;
                p.MarkedOpponent = null; // Clear any previous marking assignments
                p.IsWallPlayerForCurrentSetPiece = false; // Clear wall status
            }

            //ShowMessage("Assigning defensive set piece roles for " + defensiveRoutine.Name + " (" + defensiveRoutine.AppliesToSetPieceType + ") to " + DefendingTeam.Name + " players.");

            List<Player> availableDefenders = new List<Player>();
            foreach (Player p in defendingPlayers)
            {
                if (!p.IsInjured && !p.isSentOff && p.Position != Enums.Positions.Goalkeeper)
                    availableDefenders.Add(p);
            }

            List<Player> attackingThreats = new List<Player>();
            foreach (Player p in attackingPlayers)
            {
                if (!p.IsInjured && !p.isSentOff && p.Position != Enums.Positions.Goalkeeper)
                    attackingThreats.Add(p);
            }

            // Assign Goalkeeper to Goalkeeper role (if you have a specific enum for it)
            Player goalkeeper = defendingPlayers.FirstOrDefault(p => p.Position == Enums.Positions.Goalkeeper);
            if (goalkeeper != null)
            {
                goalkeeper.DefensiveSetPieceRole = Enums.SetPieceRole.GoalkeeperCover; // Using GoalkeeperCover as per your enum
                //ShowMessage(goalkeeper.fullName + " assigned as GoalkeeperCover.");
            }

            // --- 1. Assign Wall Players (if applicable for Free Kicks) ---
            if (defensiveRoutine.AppliesToSetPieceType == Enums.SetPieceType.FreeKick && defensiveRoutine.Strategy != Enums.DefensiveStrategy.None) // Assuming 'FormWall' logic is implicit in strategy or separate
            {
                // This is a simplified example. You might want more sophisticated logic for wall size/placement.
                // For a direct free kick in shooting range, form a wall.
                bool isInShootingRange = IsBallInAttackingHalf(CurrentBallZone, AttackingTeam) && GetZoneForwardValue(CurrentBallZone, AttackingTeam == HomeTeam) >= 5;
                if (isInShootingRange)
                {
                    int wallPlayersNeeded = Math.Min(5, availableDefenders.Count); // Example: up to 5 players

                    List<Player> wallCandidates = GetWallPlayers(availableDefenders, DefendingTeam == HomeTeam, wallPlayersNeeded);

                    for (int i = 0; i < wallPlayersNeeded && i < wallCandidates.Count; i++)
                    {
                        Player wallPlayer = wallCandidates[i];
                        if (wallPlayer.DefensiveSetPieceRole == Enums.SetPieceRole.None) // Only assign if not already taken
                        {
                            wallPlayer.DefensiveSetPieceRole = Enums.SetPieceRole.WallPlayer;
                            wallPlayer.IsWallPlayerForCurrentSetPiece = true;
                            availableDefenders.Remove(wallPlayer); // Remove from available to avoid re-assignment
                            //ShowMessage(wallPlayer.fullName + " assigned as WallPlayer.");
                        }
                    }
                }
            }

            // --- 2. Assign Post Blockers (if routine specifies and applicable) ---
            if (defensiveRoutine.UsePostBlockers)
            {
                // Assign 2 players to PostBlocker (one for each post, usually fullbacks or tall midfielders)
                var postBlockerCandidates = GetPostBlockerCandidates(availableDefenders);

                if (postBlockerCandidates.Count >= 1)
                {
                    Player nearPostBlocker = postBlockerCandidates[0];
                    if (nearPostBlocker.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                    {
                        nearPostBlocker.DefensiveSetPieceRole = Enums.SetPieceRole.PostBlocker;
                        availableDefenders.Remove(nearPostBlocker);
                        //ShowMessage(nearPostBlocker.fullName + " assigned as Near Post Blocker.");
                    }
                }
                if (postBlockerCandidates.Count >= 2)
                {
                    Player farPostBlocker = postBlockerCandidates[1];
                    if (farPostBlocker.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                    {
                        farPostBlocker.DefensiveSetPieceRole = Enums.SetPieceRole.PostBlocker;
                        availableDefenders.Remove(farPostBlocker);
                        //ShowMessage(farPostBlocker.fullName + " assigned as Far Post Blocker.");
                    }
                }
            }


            // --- 3. Assign other defensive roles based on strategy ---
            // Prioritize Man-Marking, then Zonal, then General Support/Cleanup
            switch (defensiveRoutine.Strategy)
            {
                case Enums.DefensiveStrategy.ManMarking:
                    AssignManMarkers(availableDefenders, attackingThreats, defensiveRoutine.AttackerRoleToDefenderRoleMapping, defensiveRoutine);
                    break;
                case Enums.DefensiveStrategy.ZonalMarking:
                    AssignZonalMarkers(availableDefenders, defensiveRoutine.PreferredZoneCoverage, defensiveRoutine);
                    break;
                case Enums.DefensiveStrategy.HybridMarking:
                    AssignHybridMarkers(availableDefenders, attackingThreats, defensiveRoutine.AttackerRoleToDefenderRoleMapping, defensiveRoutine.PreferredZoneCoverage, defensiveRoutine);
                    break;
                case Enums.DefensiveStrategy.None: // Fallback for very basic defense or if no specific strategy
                    AssignClearBallDefenders(availableDefenders); // Treat as clear ball emphasis
                    break;
            }

            // Any remaining defenders not assigned a specific role
            foreach (var p in availableDefenders)
            {
                if (p.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                {
                    p.DefensiveSetPieceRole = Enums.SetPieceRole.DeepDefender; // Default to general deep defense
                    //ShowMessage(p.fullName + " assigned as DeepDefender (fallback).");
                }
            }
        }

        List<Player> GetPostBlockerCandidates(List<Player> availableDefenders)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetPostBlockerCandidates: availableDefenders:{0}",
            //    string.Join(",", availableDefenders.Select(p => p.position))));


            List<Player> postBlockerCandidates = new List<Player>(availableDefenders);

            postBlockerCandidates.Sort((a, b) =>
                (b.trueRating.PositioningForGameCalculations + b.trueRating.ComposureForGameCalculations)
                .CompareTo(a.trueRating.PositioningForGameCalculations + a.trueRating.ComposureForGameCalculations));

            return postBlockerCandidates;
        }

        private void ClearWallPlayerFlags(Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("ClearWallPlayerFlags: defendingTeam:{0}",
            //    defendingTeam.Name));


            foreach (Player p in defendingTeam.AvailableOnFieldPlayers)
            {
                p.IsWallPlayerForCurrentSetPiece = false;
            }
            //ShowMessage("Cleared IsWallPlayerForCurrentSetPiece flags for defending team.");
        }

