        #region Fouls

        /// <summary>
        /// Handles the consequences of a foul, including advantage, carding, and setting the next match state.
        /// </summary>
        /// <param name="fouler">The player who committed the foul.</param>
        /// <param name="fouled">The player who was fouled.</param>
        /// <param name="foulType">The type of foul committed.</param>
        /// <param name="inPenaltyArea">True if the foul occurred inside the penalty area.</param>
        /// <param name="attackingTeam">The team that was fouled (the one who gets the free kick/penalty).</param>
        private void ProcessFoul(Player fouler, Player fouled, Enums.FoulType foulType, bool inPenaltyArea, Team attackingTeam)
        {
            // --- 1. Check for Advantage ---
            fouler.gameStats.fouls++;
            bool advantagePlayed = false;
            if (foulType != Enums.FoulType.SeriousFoulPlay && foulType != Enums.FoulType.ViolentConduct) // Violent fouls rarely get advantage
            {
                advantagePlayed = CheckForAdvantage(fouled, attackingTeam);
            }

            if (advantagePlayed)
            {
                // If advantage is played, current possession continues, no set piece immediately.
                // The ball carrier (fouled player) should retain possession for now.
                SetPossession(fouled, CurrentBallZone, attackingTeam);
                CurrentMatchState = Enums.MatchState.InPlay_Possession; // Revert to in-play
                // However, we still need to consider cards for serious fouls even if advantage is played
                Enums.CardType card = DetermineCard(fouler, foulType, true); // True for advantage played context
                if (card != CardType.None)
                    delayedCardsAppliedDueToAdvantage.Add(fouler);

                MatchEntry meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.FoulProcessed, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    PlayerName1 = fouler.fullName,
                    Player1Pos = fouler.position,
                    PlayerName2 = fouled.fullName,
                    Player2Pos = fouler.position,
                    TeamName1 = fouler.teamName,
                    TeamName2 = fouled.teamName,
                    IsAdvantage = true,
                    IsPenalty = inPenaltyArea,
                    IsFreeKick = !inPenaltyArea,
                    IsObstruction = (foulType == FoulType.Obstruction),
                    IsHolding = (foulType == FoulType.Holding),

                    Zone1 = CurrentBallZone,
                };
                LogEntry(meOpen);

                return; // Foul handled, play continues
            }

            MatchEntry freeKickOrPenalty = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.FoulProcessed, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                PlayerName1 = fouler.fullName,
                Player1Pos = fouler.position,
                PlayerName2 = fouled.fullName,
                Player2Pos = fouler.position,
                TeamName1 = fouler.teamName,
                TeamName2 = fouled.teamName,
                IsPenalty = inPenaltyArea,
                IsFreeKick = !inPenaltyArea,
                IsObstruction = (foulType == FoulType.Obstruction),
                IsHolding = (foulType == FoulType.Holding),

                Zone1 = CurrentBallZone,
            };
            LogEntry(freeKickOrPenalty);

            // --- 2. If no Advantage, determine Set Piece and Card ---
            Enums.CardType cardToIssue = DetermineCard(fouler, foulType, false); // False for no advantage played context
            ApplyCard(fouler, cardToIssue);

            if (inPenaltyArea)
            {
                CurrentMatchState = Enums.MatchState.PenaltyKick;
                // Set the ball to the penalty spot (conceptual, could be a specific zone)
                CurrentBallZone = attackingTeam == HomeTeam ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            }
            else
            {
                CurrentMatchState = Enums.MatchState.FreeKick;
                CurrentBallZone = GetPlayerZone(fouled); // Free kick taken from where the foul occurred
            }

            SetPossession(fouled, CurrentBallZone, attackingTeam); // The fouled player's team gets possession for the set piece
        }

        /// <summary>
        /// Determines if an advantage should be played after a foul.
        /// </summary>
        /// <param name="fouledPlayer">The player who was fouled.</param>
        /// <param name="fouledTeam">The team that was fouled.</param>
        /// <returns>True if advantage is played, false otherwise.</returns>
        private bool CheckForAdvantage(Player fouledPlayer, Team fouledTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CheckForAdvantage: fouledPlayer:{0},fouledTeam:{1}",
            //    fouledPlayer.position, fouledTeam.Name));


            // Basic advantage logic:
            // 1. Is the ball still with the fouled team? (This check might be harder with loose ball states)
            // 2. Do they have clear possession and an attacking opportunity?
            // 3. Is the foul not too serious (e.g., not a red card offense that demands immediate stoppage)?

            // Simplistic check for now: If the fouled player is still considered in "possession"
            // (i.e., CurrentBallCarrier is fouledPlayer) or a teammate immediately picks up the ball nearby,
            // AND they are in an attacking area, consider advantage.
            bool isHomeAttacking = (fouledTeam == HomeTeam);
            if (CurrentBallHolder == fouledPlayer) // Fouled player still has the ball
            {
                int forwardValue = GetZoneForwardValue(fouledPlayer.CurrentZone, isHomeAttacking);
                if (forwardValue >= 4) // Midfield or attacking third
                {
                    // Small chance referee plays advantage based on strictness
                    int advantageRoll = Dice.d100();
                    if (this.referee.CurrentRefereeStrictness == Enums.RefereeStrictness.Lenient && advantageRoll > 40) return true;
                    if (this.referee.CurrentRefereeStrictness == Enums.RefereeStrictness.Normal && advantageRoll > 60) return true;
                    if (this.referee.CurrentRefereeStrictness == Enums.RefereeStrictness.Strict && advantageRoll > 80) return true;
                }
            }
            return false;
        }

        /// <summary>
        /// Determines which, if any, card should be issued for a foul.
        /// </summary>
        /// <param name="fouler">The player who committed the foul.</param>
        /// <param name="foulType">The type of foul committed.</param>
        /// <param name="advantagePlayed">True if advantage was played (can influence carding, e.g., less likely for minor fouls).</param>
        /// <returns>The type of card to issue (None, Yellow, Red).</returns>
        private Enums.CardType DetermineCard(Player fouler, Enums.FoulType foulType, bool advantagePlayed)
        {
            double cardChance = 0; // Base chance for a card

            // Base chances based on foul type
            switch (foulType)
            {
                case Enums.FoulType.Minor: cardChance = 5; break;  // Very low chance
                case Enums.FoulType.Tactical: cardChance = 40; break; // Good chance of yellow
                case Enums.FoulType.Reckless: cardChance = 70; break; // High chance of yellow, some red
                case Enums.FoulType.SeriousFoulPlay: cardChance = 90; break; // Very high chance of red
                case Enums.FoulType.Professional: cardChance = 95; break; // Almost always red (DOGSO)
                case Enums.FoulType.ViolentConduct: cardChance = 100; break; // Always red
                case Enums.FoulType.Handball: cardChance = 0; break; // Handballs usually don't get cards unless denying opportunity
                case Enums.FoulType.Other: cardChance = 5; break;
                default: return Enums.CardType.None;
            }

            // Adjust by referee strictness
            int countThreshold = 10;
            switch (this.referee.CurrentRefereeStrictness)
            {
                case Enums.RefereeStrictness.Lenient:
                    cardChance -= 15;
                    break;
                case Enums.RefereeStrictness.Strict:
                    cardChance += 15;
                    countThreshold = 8;
                    break;
                case Enums.RefereeStrictness.Normal:
                    countThreshold = 9;
                    break; // No change
            }

            // Referees get a little wary of awarding cards if there players have already been sent off.
            if (fouler.Team.AvailableOnFieldPlayers.Count <= countThreshold)
            {
                if (fouler.yellowCards > 0)
                    cardChance -= 60;
            }

            // Adjust by player's aggression and sportsmanship
            cardChance += (fouler.trueRating.AggressionForGameCalculations - 50) * 0.2; // More aggressive = more likely
            cardChance -= (fouler.trueRating.ComposureForGameCalculations - 50) * 0.1; // More sportsmanlike = less likely

            // If advantage was played, sometimes referee will be more lenient with card
            if (advantagePlayed && foulType != Enums.FoulType.SeriousFoulPlay && foulType != Enums.FoulType.ViolentConduct && foulType != Enums.FoulType.Professional)
            {
                cardChance -= 20; // Reduce card chance if advantage played for less severe fouls
            }


            // Determine card based on final chance
            int cardRoll = Dice.d100(); // 1-100

            if (foulType == Enums.FoulType.ViolentConduct || foulType == Enums.FoulType.SeriousFoulPlay)
            {
                return Enums.CardType.Red; // Direct red for these
            }
            // Specific DOGSO rule: if it was a penalty, and the foul was an attempt to play the ball, it's often yellow
            // Otherwise, still red. This is simplified.
            if (foulType == Enums.FoulType.Professional)
            {
                if (fouler.CurrentZone == CurrentBallZone && CurrentMatchState == Enums.MatchState.PenaltyKick) // Assuming the foul led to a penalty
                {
                    return Enums.CardType.Yellow; // Simplified: DOGSO in penalty box, attempted to play ball -> yellow
                }
                return Enums.CardType.Red; // DOGSO elsewhere or no attempt to play ball -> red
            }


            if (cardRoll < cardChance)
            {
                // Player already has a yellow, second yellow becomes red
                if (fouler.yellowCards >= 1)
                {
                    return Enums.CardType.Red;
                }
                else
                {
                    return Enums.CardType.Yellow;
                }
            }
            return Enums.CardType.None;
        }

        /// <summary>
        /// Applies the determined card to the player and handles consequences (e.g., sending off).
        /// </summary>
        /// <param name="player">The player receiving the card.</param>
        /// <param name="cardType">The type of card.</param>
        private void ApplyCard(Player player, Enums.CardType cardType)
        {
            if (cardType == Enums.CardType.Yellow)
            {
                player.yellowCards++;
                player.totalSeasonYellowCards++;
                player.gameStats.yellowCards++;
                if (player.yellowCards >= 2)
                {
                    player.isSentOff = true;
                    player.Team.SetPlayerSentOff(player);
                    player.totalSeasonRedCards++;
                    player.gameStats.redCards++;
                    // Reduce team's player count (if you're tracking that)
                    //if (homeTeam.StartingEleven.Contains(player)) homeTeam.PlayersOnPitchCount--;
                    //else awayTeam.PlayersOnPitchCount--;
                }
            }
            else if (cardType == Enums.CardType.Red)
            {
                player.Team.SetPlayerSentOff(player);
                player.isSentOff = true;
                player.totalSeasonRedCards++;
                player.gameStats.redCards++;
                // Reduce team's player count
                //if (homeTeam.StartingEleven.Contains(player)) homeTeam.PlayersOnPitchCount--;
                //else awayTeam.PlayersOnPitchCount--;
            }

            if (cardType != CardType.None)
            {
                LogEntry(new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.CardGiven,
                    Timestamp = DateTime.Now, // Always include for precise timing
                    IsFoulCardYellow = (cardType == Enums.CardType.Yellow),
                    IsFoulCardRed = (cardType == Enums.CardType.Red),
                    Value1 = player.yellowCards,
                    Player1Pos = player.Position,
                    PlayerName1 = player.fullName,
                    TeamName1 = player.teamName,
                });
            }
        }

        /// <summary>
        /// Evaluates potential obstruction and holding fouls between off-ball players.
        /// This method should be called periodically within SimulateMoment().
        /// </summary>
        private void EvaluateOffBallObstructionFouls() // Renamed slightly to be more generic, or consider a new name like EvaluateOffBallFouls
        {
            //LoggingStuff.LogMethodCall("EvaluateOffBallObstructionFouls");


            // A small chance to trigger this check per moment to avoid over-fouling
            if (Dice.d100() > 10) // e.g., 10% chance each moment to check for off-ball fouls
            {
                return;
            }

            foreach (Player attacker in AttackingTeam.AvailableOnFieldOutfielders)
            {
                if (CurrentBallHolder == attacker || attacker.Position == Enums.Positions.Goalkeeper) continue;

                foreach (Player defender in DefendingTeam.AvailableOnFieldOutfielders)
                {
                    if (CurrentBallHolder == defender || defender.Position == Enums.Positions.Goalkeeper) continue;

                    int distanceBetweenPlayers = CalculateDistance(attacker.CurrentZone, defender.CurrentZone);

                    if (distanceBetweenPlayers <= 1) // Players are in the same or adjacent zones
                    {
                        // Decide which type of off-ball foul to check for, or check for both.
                        // We can use another dice roll or prioritize based on player attributes.
                        // For simplicity, let's just run both checks, but with a chance of one happening.

                        // Chance to check for Obstruction
                        if (Dice.d100() < 40) // 40% chance to check for obstruction
                        {
                            SimulateObstruction(defender, attacker, DefendingTeam, AttackingTeam);
                            if (CurrentMatchState == Enums.MatchState.FreeKick) return; // If a foul occurred, stop checking
                        }

                        // Chance to check for Holding (can happen in similar close proximity)
                        if (Dice.d100() < 10) // 10% chance to check for holding
                        {
                            SimulateOpenPlayHolding(defender, attacker, DefendingTeam, AttackingTeam);
                            if (CurrentMatchState == Enums.MatchState.FreeKick) return; // If a foul occurred, stop checking
                        }
                    }
                }
            }

            // --- Specific Check for Goalkeeper Obstruction (existing logic remains) ---
            // This part should already handle the GK being obstructed during set pieces.
            // No change needed here for general holding.
            if (CurrentMatchState == Enums.MatchState.CornerKick || CurrentMatchState == Enums.MatchState.FreeKick_Indirect || CurrentMatchState == Enums.MatchState.CrossAttempted)
            {
                Player goalkeeper = DefendingTeam.GoalKeeper;
                if (goalkeeper == null) return;

                foreach (Player attackingPlayer in AttackingTeam.AvailableOnFieldOutfielders)
                {
                    if (CalculateDistance(attackingPlayer.CurrentZone, goalkeeper.CurrentZone) <= 1 &&
                        (goalkeeper.CurrentZone == Enums.PitchZone.GoalkeeperArea_Home || goalkeeper.CurrentZone == Enums.PitchZone.PenaltyArea_Home ||
                         goalkeeper.CurrentZone == Enums.PitchZone.GoalkeeperArea_Away || goalkeeper.CurrentZone == Enums.PitchZone.PenaltyArea_Away))
                    {
                        double gkObstructionFoulChance = 0;
                        gkObstructionFoulChance += attackingPlayer.trueRating.AggressionForGameCalculations * 0.1;
                        gkObstructionFoulChance += attackingPlayer.trueRating.ComposureForGameCalculations * 0.1;
                        gkObstructionFoulChance -= attackingPlayer.trueRating.PositioningForGameCalculations * 0.1;

                        gkObstructionFoulChance = Math.Max(0, Math.Min(60, gkObstructionFoulChance));

                        if (Dice.d100() < gkObstructionFoulChance)
                        {
                            ProcessFoul(attackingPlayer, goalkeeper, Enums.FoulType.Obstruction, false, DefendingTeam);
                            return;
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Simulates a holding foul in open play between two players who are in close proximity.
        /// This method should typically be called by EvaluateOffBallObstructionFouls().
        /// </summary>
        /// <param name="foulingPlayer">The player potentially committing the holding foul (e.g., defender).</param>
        /// <param name="fouledPlayer">The player being held (e.g., attacker).</param>
        /// <param name="foulingTeam">The team of the fouling player.</param>
        /// <param name="fouledTeam">The team of the fouled player.</param>
        private void SimulateOpenPlayHolding(Player foulingPlayer, Player fouledPlayer, Team foulingTeam, Team fouledTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("SimulateOpenPlayHolding: foulingPlayer:{0},fouledPlayer:{1},foulingTeam:{2},fouledTeam:{3}",
            //    foulingPlayer.position, fouledPlayer.position, foulingTeam.Name, fouledTeam.Name));


            // Holding is more likely when:
            // - Fouling player has high aggression, low discipline.
            // - Fouled player has high agility, off-the-ball (trying to break free).
            // - Fouling player is struggling to keep up with or mark the fouled player cleanly.

            double foulChance = 0;

            // Fouling player's attributes
            foulChance += foulingPlayer.trueRating.AggressionForGameCalculations * 0.2; // Strong emphasis on aggression
            foulChance -= foulingPlayer.trueRating.ComposureForGameCalculations * 0.15;
            foulChance += foulingPlayer.trueRating.PhysicalityForGameCalculations * 0.05; // Stronger players might use illegal strength

            // Fouled player's attributes (making the holding more effective or obvious)
            foulChance += fouledPlayer.trueRating.AgilityForGameCalculations * 0.1;
            foulChance += fouledPlayer.trueRating.PositioningForGameCalculations * 0.1;
            foulChance -= fouledPlayer.trueRating.BalanceForGameCalculations * 0.05; // Good balance means harder to hold

            // Contextual factors:
            // How far is the ball from these players? If very close, might be part of tackle attempt.
            // If far, it's more purely off-ball holding.
            int distanceToBall = CalculateDistance(foulingPlayer.CurrentZone, CurrentBallZone);
            if (distanceToBall > 1) // If the ball is not in their immediate zone or adjacent
            {
                foulChance += 10; // Increased chance for off-ball holding
            }

            double adjuster = 0.05;
            foulChance *= adjuster;

            // Is the fouling player being "beaten" by the fouled player?
            // This is hard to assess without explicit movement intentions or recent success/failure of getting past.
            // For now, we'll keep it general.

            foulChance = Math.Max(0, Math.Min(70, foulChance)); // Clamp between 0% and 70%

            if (Dice.d100() < foulChance)
            {
                // Open play holding is usually a direct free kick. Very rarely a penalty unless it's very cynical and denying clear goal.
                // For general open-play holding, assume not a penalty unless in attacking team's box.
                bool isPenalty = IsBallInPenaltyArea(fouledPlayer.CurrentZone, fouledTeam); // Foul by defender on attacker in attacker's box
                ProcessFoul(foulingPlayer, fouledPlayer, Enums.FoulType.Holding, isPenalty, fouledTeam);
            }
        }

        /// <summary>
        /// Simulates an obstruction attempt between a potential blocker and an attacking player.
        /// </summary>
        /// <param name="blocker">The player potentially committing obstruction (e.g., defender).</param>
        /// <param name="blockedPlayer">The player being obstructed (e.g., attacker).</param>
        /// <param name="blockingTeam">The team of the blocker.</param>
        /// <param name="blockedTeam">The team of the blocked player.</param>
        private void SimulateObstruction(Player blocker, Player blockedPlayer, Team blockingTeam, Team blockedTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("SimulateObstruction: blocker:{0},blockedPlayer:{1},blockingTeam:{2},blockedTeam:{3}",
            //    blocker.position, blockedPlayer.position, blockingTeam.Name, blockedTeam.Name));


            if (CurrentMatchState == Enums.MatchState.KickOff)
                return;

            // A foul is more likely if:
            // - Blocker has high aggression, low discipline, low awareness (misjudges spacing)
            // - Blocked player has high off-the-ball, agility (making the obstruction more obvious)
            // - The blocker is not moving directly towards the ball
            // - The blocker is moving directly into the path of the blockedPlayer

            double foulChance = 0;

            // Blocker's attributes
            foulChance += blocker.trueRating.AggressionForGameCalculations * 0.15;
            foulChance -= blocker.trueRating.ComposureForGameCalculations * 0.1;
            foulChance -= blocker.trueRating.PositioningForGameCalculations * 0.05; // Poor positioning might lead to accidental obstruction

            // Blocked player's attributes (making the foul more effective/obvious)
            foulChance += blockedPlayer.trueRating.PositioningForGameCalculations * 0.05; // Good movement makes obstruction more impactful
            foulChance += blockedPlayer.trueRating.AgilityForGameCalculations * 0.05;

            // Contextual factors
            // If the ball is very far from the blocker, their action is less likely to be "playing the ball"
            double distanceToBall = CalculateDistance(blocker.CurrentZone, CurrentBallZone);
            if (distanceToBall > 3) // Arbitrary distance, adjust based on your zone definitions
            {
                foulChance += 10; // Higher chance if blocker is far from the ball
            }

            double adjuster = 0.05;
            foulChance *= adjuster;

            // Is the blocker moving directly to impede? (This is harder to quantify without full movement AI)
            // For now, a simplified check. If you have directional vectors, you'd use them.
            // If blocker's desired position is simply to block the attacker's path, rather than get to ball/space.
            // This is where "Tactical System Integration" or "General Player AI" becomes crucial.
            // For now, let's just assume if they are close and not on the ball, it's a potential obstruction.

            foulChance = Math.Max(0, Math.Min(70, foulChance)); // Clamp between 0% and 70%

            if (Dice.d100() < foulChance)
            {
                // Obstruction is almost always an indirect free kick, rarely a penalty unless it's very cynical last-man
                // and in the box without playing ball (more like a professional foul).
                // Let's assume not a penalty for a typical obstruction.
                ProcessFoul(blocker, blockedPlayer, Enums.FoulType.Obstruction, false, blockedTeam); // false for isPenalty
            }
            // No else needed, play continues if no foul.
        }

        /// <summary>
        /// Determines the type of foul committed based on the tackle details.
        /// </summary>
        /// <param name="tackler">The player who committed the foul.</param>
        /// <param name="tackleType">The type of tackle attempted.</param>
        /// <param name="successChance">The calculated success chance of the tackle.</param>
        /// <param name="foulChance">The calculated foul chance of the tackle.</param>
        /// <returns>The determined FoulType.</returns>
        private Enums.FoulType DetermineFoulType(Player tackler, Enums.TackleType tackleType, double successChance, double foulChance)
        {
            // A simple decision tree for foul severity
            // More aggressive players and riskier tackles lead to more serious fouls.

            if (tackleType == Enums.TackleType.Sliding)
            {
                // Sliding tackles have a higher propensity for more serious fouls
                if (foulChance > 85 || tackler.trueRating.AggressionForGameCalculations > 85) return Enums.FoulType.ViolentConduct; // Very high chance of foul or aggressive player
                if (foulChance > 75 || tackler.trueRating.AggressionForGameCalculations > 80) return Enums.FoulType.SeriousFoulPlay;
                if (foulChance > 30 || tackler.trueRating.AggressionForGameCalculations > 50) return Enums.FoulType.Reckless;
                return Enums.FoulType.Tactical;
            }
            else // Standing Tackle
            {
                if (foulChance > 40 || tackler.trueRating.AggressionForGameCalculations > 80) return Enums.FoulType.Reckless;
                if (foulChance > 20 || tackler.trueRating.AggressionForGameCalculations > 45) return Enums.FoulType.Tactical;
                return Enums.FoulType.Minor;
            }
        }

        #endregion

        #region Tackling

        private Enums.TackleOutcome AttemptTackle(Player tackler, Player dribbler, Team attackingTeam, Team defendingTeam, Enums.TackleType tackleType)
        {
            double successChance = 0;
            double foulChance = 0;
            double injuryChanceMultiplier = 1.0;

            double looseBallChange = 0;
            looseBallChange += (tackleType == Enums.TackleType.Sliding) ? 20 : 5;
            looseBallChange += (100 - tackler.trueRating.ComposureForGameCalculations) * 0.1;
            if (EnumCache<Enums.PitchZone>.ToString(dribbler.CurrentZone).Contains("Flank") ||
                dribbler.CurrentZone == Enums.PitchZone.GoalkeeperArea_Home ||
                dribbler.CurrentZone == Enums.PitchZone.GoalkeeperArea_Away ||
                dribbler.CurrentZone == Enums.PitchZone.PenaltyArea_Home ||
                dribbler.CurrentZone == Enums.PitchZone.PenaltyArea_Away)
            {
                looseBallChange += 25;
            }
            looseBallChange = Math.Max(0, Math.Min(75, looseBallChange));

            if (tackleType == Enums.TackleType.Standing)
            {
                successChance = (tackler.trueRating.StandTackleForGameCalculations * 0.8) + (tackler.trueRating.DefenseAwarenessForGameCalculations * 0.2);
                foulChance = 10;
                injuryChanceMultiplier = 0.5;
            }
            else // Enums.TackleType.Sliding
            {
                successChance = (tackler.trueRating.SlideTackleForGameCalculations * 0.8) + (tackler.trueRating.AggressionForGameCalculations * 0.2);
                foulChance = 25;
                injuryChanceMultiplier = 1.5;
            }

            switch (defendingTeam.CurrentTacklingAggression)
            {
                case Enums.TacklingAggression.Cautious:
                    successChance -= 5;
                    foulChance -= 15;
                    injuryChanceMultiplier *= 0.8;
                    break;
                case Enums.TacklingAggression.Standard:
                    break;
                case Enums.TacklingAggression.Aggressive:
                    successChance += 5;
                    foulChance += 15;
                    injuryChanceMultiplier *= 1.2;
                    break;
                case Enums.TacklingAggression.VeryAggressive:
                    successChance += 10;
                    foulChance += 30;
                    injuryChanceMultiplier *= 1.5;
                    break;
            }

            successChance -= dribbler.trueRating.DribblingForGameCalculations * 0.4;
            successChance -= dribbler.trueRating.BallControlForGameCalculations * 0.2;

            foulChance += (100 - tackler.trueRating.ComposureForGameCalculations) * 0.2;

            switch (referee.CurrentRefereeStrictness)
            {
                case Enums.RefereeStrictness.Lenient: foulChance -= 10; break;
                case Enums.RefereeStrictness.Strict: foulChance += 10; break;
                case Enums.RefereeStrictness.Normal: break;
            }

            if (tackler.CurrentCondition < 50)
            {
                successChance -= (50 - tackler.CurrentCondition) * 0.5;
                foulChance += (50 - tackler.CurrentCondition) * 0.5;
            }

            successChance = Math.Max(10, Math.Min(95, successChance));
            foulChance = Math.Max(5, Math.Min(90, foulChance));
            double adjuster = 0.5;
            foulChance *= adjuster;

            int roll = Dice.d100();
            bool isFoul = (roll <= foulChance);
            bool isSuccessfulTackle = (roll <= successChance);

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.TackleOutcome,
                Timestamp = DateTime.Now,

                PlayerName1 = tackler.fullName,
                Player1Pos = tackler.position,
                PlayerName2 = dribbler.fullName,
                Player2Pos = dribbler.position,
                TeamName1 = attackingTeam.Name,
                TeamName2 = defendingTeam.Name,

                Zone1 = CurrentBallZone,
            };

            if (isFoul)
            {
                Enums.FoulType foulType = DetermineFoulType(tackler, tackleType, successChance, foulChance);
                bool inPenaltyArea = IsZoneDangerous(dribbler.CurrentZone, attackingTeam == HomeTeam);

                meOpen.TackleResult = TackleResultType.Foul;
                LogEntry(meOpen);
                ProcessFoul(tackler, dribbler, foulType, inPenaltyArea, attackingTeam);
                CheckForInjuryAfterFoul(tackler, dribbler, foulType, injuryChanceMultiplier);
                if (IsZoneDangerous(tackler.CurrentZone, defendingTeam == HomeTeam))
                {
                    _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(tackler, CurrentSecond));
                    _potentialChanceCreatingActions.Add(new Tuple<Player, int>(dribbler, CurrentSecond));
                }
                return Enums.TackleOutcome.Foul;
            }
            // --- NEW: Own Goal Check after Foul, before other outcomes ---
            else if (DetermineOwnGoalOccurred(tackler, defendingTeam, dribbler.CurrentZone, isFromShotAttempt: false)) // Not directly from a shot, but a tackle error
            {
                meOpen.TackleResult = TackleResultType.LostEncounter;
                meOpen.IsOwnGoal = true;
                LogEntry(meOpen); tackler.gameStats.OwnGoals++;
                UpdateScore(null, null, this.DefendingTeam.GoalKeeper, false);
                return Enums.TackleOutcome.OwnGoal; // Make sure Enums.TackleOutcome has OwnGoal
            }
            else if (isSuccessfulTackle)
            {
                tackler.gameStats.SuccessfulTackles++;
                this.CheckForErrorNegation(tackler, CurrentSecond);
                this.CheckForChanceNegation(dribbler.Team, CurrentSecond, negatingPlayer: tackler);
                int outOfBoundsRoll = Dice.d100();
                if (outOfBoundsRoll <= looseBallChange && CanBeOutOfBounds(dribbler.CurrentZone))
                {
                    meOpen.TackleResult = TackleResultType.BallOut;
                    LogEntry(meOpen);
                    Enums.PitchZone ballExitZone = dribbler.CurrentZone;
                    SetMatchStateForOutOfBounds(ballExitZone, tackler.Team);
                    CheckForInjuryAfterTackleSuccess(tackler, dribbler, injuryChanceMultiplier);
                    return Enums.TackleOutcome.BallOutOfBounds;
                }
                else
                {
                    tackler.gameStats.SuccessfulTackles++; // This was incremented above too, might be double counting
                    meOpen.TackleResult = TackleResultType.WonPossession;
                    LogEntry(meOpen);
                    SetPossession(tackler, tackler.CurrentZone, defendingTeam);
                    CheckForInjuryAfterTackleSuccess(tackler, dribbler, injuryChanceMultiplier);
                    return Enums.TackleOutcome.Successful;
                }
            }
            else
            {
                Enums.PitchZone possibleExitZone = dribbler.CurrentZone;
                bool possibleOutOfBounds = CanBeOutOfBounds(dribbler.CurrentZone);

                int outOfBoundsRoll = Dice.d100();
                if ((outOfBoundsRoll <= looseBallChange))
                {
                    dribbler.gameStats.Dispossessed++;
                    meOpen.TackleResult = TackleResultType.BallOut;
                    Enums.PitchZone ballExitZone = dribbler.CurrentZone;

                    if (possibleOutOfBounds)
                    {
                        meOpen.TackleResult = TackleResultType.BallOut;
                        LogEntry(meOpen);
                        Team lastTouchBeforeOutOfBounds = (Dice.d100() < 50) ? tackler.Team : dribbler.Team;
                        SetMatchStateForOutOfBounds(ballExitZone, lastTouchBeforeOutOfBounds);
                        CheckForInjuryAfterTackleSuccess(tackler, dribbler, injuryChanceMultiplier);
                        return Enums.TackleOutcome.BallOutOfBounds;
                    }
                    else
                    {
                        meOpen.TackleResult = TackleResultType.LooseBall;
                        LogEntry(meOpen);
                        SetLooseBall(false, tackler, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                        CheckForInjuryAfterTackleSuccess(tackler, dribbler, injuryChanceMultiplier);
                        return Enums.TackleOutcome.LooseBall;
                    }
                }
                else
                {
                    if (IsZoneDangerous(tackler.CurrentZone, defendingTeam == HomeTeam))
                    {
                        _potentialErrorsLeadingToGoal.Add(new Tuple<Player, int>(tackler, CurrentSecond));
                        _potentialChanceCreatingActions.Add(new Tuple<Player, int>(dribbler, CurrentSecond));
                    }
                    meOpen.TackleResult = TackleResultType.LostEncounter;
                    LogEntry(meOpen);
                    SetPossession(dribbler, dribbler.CurrentZone, attackingTeam);
                    CheckForInjuryAfterTackleFailure(tackler, dribbler, injuryChanceMultiplier);
                    return Enums.TackleOutcome.Failed;
                }
            }
        }

