        #region Scoring

        private void UpdateScore(Player assister, Player shooter, Player goalKeeper, bool fromPK = false)
        {
            Dictionary<Player, List<string>> goalTrackerTraditional = new Dictionary<Player, List<string>>();
            string goalScoredSummary = "";

            if (AttackingTeam == HomeTeam)
            {
                HomeScore += 1;
                goalTrackerTraditional = homePlayerGoalTrackerTraditional;
            }
            else
            {
                AwayScore += 1;
                goalTrackerTraditional = awayPlayerGoalTrackerTraditional;
            }

            List<string> minutes = new List<string>();

            if (shooter == null)
            {
                shooter = new Player(-1, "Own Goal");
                goalScoredSummary = "In minute number: " + CurrentMinute.ToString() + ", " + this.DefendingTeam.Name + " gave up an own goal";
            }
            else
            {
                ErrorsLeadingToGoal(shooter, AttackingTeam, CurrentSecond);
                if (goalTrackerTraditional.ContainsKey(shooter))
                {
                    minutes = goalTrackerTraditional[shooter];
                }
                shooter.gameStats.goals++;
                if (fromPK) shooter.gameStats.penaltyKickGoals++;
                this.DefendingTeam.GoalKeeper.gameStats.goalsConceded++;
                goalScoredSummary = "In minute number: " + CurrentMinute.ToString() + ", " + shooter.fullName + " on team " + this.AttackingTeam.Name + " scored";
            }

            minutes.Add(CurrentMinute.ToString() + "'");
            goalTrackerTraditional[shooter] = minutes;
            if (fromPK)
            {
                goalScoredSummary += " (from PK)";
            }

            assister = FindAssister(shooter, CurrentSecond);
            ResetRebounds();

            if (assister != null)
            {
                assister.gameStats.assists++;
                goalScoredSummary += " with the assist from " + assister.fullName;
            }
            goalScoredSummary += ".";

            gameSummary.Add(goalScoredSummary);

            NotifyScoreChange();

            referee.ResetAttitude();

            ballIsLive = false;

            kickOff = true;

            EvaluateTeamTactics();

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.NonPKScoreUpdate, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                TeamName1 = HomeTeam.Name,
                TeamName2 = AwayTeam.Name,

                Value1 = HomeScore,
                Value2 = AwayScore
            };
            LogEntry(meOpen);

            CurrentMatchState = Enums.MatchState.GoalScored;

            OnScoreUpdated?.Invoke(HomeScore, AwayScore);
            //SetPossession(DefendingTeam.StartingEleven.FirstOrDefault(), Enums.PitchZone.KickOffCircle, DefendingTeam);
            ResetForKickoff();
        }

        /// <summary>
        /// Determines if an own goal occurs based on a player's action in a specific zone,
        /// considering their attributes and the context of the play (shot, cross, clear).
        /// This method is now generic for both outfield players and goalkeepers.
        /// </summary>
        /// <param name="player">The player whose action might lead to an own goal.</param>
        /// <param name="defendingTeam">The player's team (the team that might concede the own goal).</param>
        /// <param name="actionZone">The PitchZone where the action leading to the potential own goal occurred.</param>
        /// <param name="isFromShotAttempt">True if the potential own goal resulted from blocking/fumbling a shot.</param>
        /// <param name="isFromCrossAttempt">True if the potential own goal resulted from misjudging/fumbling a cross.</param>
        /// <param name="isFromClearAttempt">True if the potential own goal resulted from a mis-hit clearance.</param>
        /// <returns>True if an own goal occurs, false otherwise.</returns>
        private bool DetermineOwnGoalOccurred(Player player, Team defendingTeam, Enums.PitchZone actionZone,
                                              bool isFromShotAttempt = false, bool isFromCrossAttempt = false,
                                              bool isFromClearAttempt = false)
        {
            double ownGoalChance = 0;

            // --- 1. Base chance based on player type and relevant attributes ---
            if (player.Position == Enums.Positions.Goalkeeper)
            {
                // Goalkeeper-specific attributes for fumbles/errors
                ownGoalChance += (100 - player.trueRating.GoalKeepingHandlingForGameCalculations) * 0.4;
                ownGoalChance += (100 - player.trueRating.ComposureForGameCalculations) * 0.3;
                ownGoalChance += (100 - player.trueRating.AggressionForGameCalculations) * 0.2; // Too eager can lead to mistakes
                //ShowMessage($"  (GK attributes: Handling {player.trueRating.GoalKeepingHandlingForGameCalculations}, Composure {player.trueRating.ComposureForGameCalculations}, Aggression {player.trueRating.AggressionForGameCalculations})");
            }
            else // Outfield player (Defender, Midfielder, Forward etc.)
            {
                // Outfield player-specific attributes for defensive errors leading to own goals
                // (e.g., mis-timed block, poor clearance, bad decision under pressure)
                ownGoalChance += (100 - player.trueRating.DefendingForGameCalculations) * 0.3;     // General defensive ability
                ownGoalChance += (100 - player.trueRating.ComposureForGameCalculations) * 0.3;      // Handling pressure
                ownGoalChance += (100 - player.trueRating.DefenseAwarenessForGameCalculations) * 0.2; // Positional awareness/decision making
                ownGoalChance += (100 - player.trueRating.BalanceForGameCalculations) * 0.1;       // Awkward body position/deflection
                ownGoalChance += (100 - player.trueRating.StrengthForGameCalculations) * 0.1;      // Weak or mis-hit clearance
                //ShowMessage((Outfielder attributes: Defending {player.trueRating.DefendingForGameCalculations}, Composure {player.trueRating.ComposureForGameCalculations}, Awareness {player.trueRating.DefenseAwarenessForGameCalculations})");
            }

            // --- 2. Modifiers based on the type of action ---
            if (isFromShotAttempt)
            {
                ownGoalChance += 10; // Blocking/fumbling a powerful shot is more likely to result in an OG
                //ShowMessage("  (Increased chance: action from a shot attempt.)");
            }
            else if (isFromCrossAttempt)
            {
                ownGoalChance += 5; // Misjudging a cross/header can lead to an OG
                //ShowMessage("  (Increased chance: action from a cross attempt.)");
            }
            else if (isFromClearAttempt)
            {
                ownGoalChance += 7; // Mis-hit clearances can be very dangerous
                //ShowMessage("  (Increased chance: action from a clearance attempt.)");
            }

            // --- 3. Modifiers based on proximity to goal (using IsZoneDangerous and specific areas) ---
            bool isHomeDefending = (defendingTeam == HomeTeam);

            // Check for general danger zone
            if (IsZoneDangerous(actionZone, isHomeDefending))
            {
                ownGoalChance += 15; // Base increase for any dangerous zone
                //ShowMessage($"  (Increased chance: action in a dangerous zone: {actionZone}.)");

                // Further increase if specifically in the goalkeeper's immediate area (6-yard box)
                Enums.PitchZone actualGoalkeeperArea = isHomeDefending ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                if (actionZone == actualGoalkeeperArea)
                {
                    ownGoalChance += 10; // Additional bonus for the most critical area (total 25 from zone)
                    //ShowMessage("  (Further increased: action directly in goalkeeper area.)");
                }
                // The new granular penalty areas (DefensivePenaltyArea_X) are implicitly covered
                // if IsZoneDangerous considers them dangerous, and the +15 is applied.
                // No need for explicit checks for each granular zone here, as they fall under the general 'dangerous' category.
            }

            // --- 4. Random variability ---
            ownGoalChance += Dice.d20() - 10; // Add/subtract up to 10 for randomness
            //ShowMessage($"  (Random modifier applied: {Dice.d20() - 10}.)");

            // --- 5. Clamp the final chance to reasonable bounds ---
            ownGoalChance = Math.Max(0, Math.Min(75, ownGoalChance)); // Clamp between 0% and 75%
            //ShowMessage($"  (Final own goal chance: {ownGoalChance:F2}%.)");

            int hundreds = (Dice.d10() - 1) * 100;
            int tens = (Dice.d10() - 1) * 10;
            int ones = (Dice.d10() - 1);

            int diceRoll = hundreds + tens + ones;
            ownGoalChance *= 0.2;

            // Must roll twice in a roll to be responsible for own goal because it was happening way too often.
            if (diceRoll < ownGoalChance)
            {
                int hundreds2 = (Dice.d10() - 1) * 100;
                int tens2 = (Dice.d10() - 1) * 10;
                int ones2 = (Dice.d10() - 1);
                int diceRoll2 = hundreds2 + tens2 + ones2;
                return diceRoll2 < ownGoalChance;
            }

            // --- 6. Roll the dice to determine if an own goal occurs ---
            return false;
        }

