        #region Penalty Kicks

        private void PenaltyKickOpenPlayHandler()
        {
            CleanPotentialAssistsCreatingActions();
            // --- 1. Choose a player to take the penalty 
            Player penaltyTaker = null;

            foreach (Player p in AttackingTeam.AvailableOnFieldPlayers)
            {
                if (p.OffensiveSetPieceRole == Enums.SetPieceRole.PenaltyTaker)
                {
                    penaltyTaker = p;
                    break;
                }
            }

            if (penaltyTaker == null)
            {
                penaltyTaker = AttackingTeam.AvailableOnFieldPlayers
                .OrderByDescending(p => p.trueRating.PenaltiesForGameCalculations * 0.5 +
                                        p.trueRating.FinishingForGameCalculations * 0.3 +
                                        p.trueRating.ComposureForGameCalculations * 0.2)
                .FirstOrDefault();
            }

            if (penaltyTaker == null)
            {
                throw new Exception("ERROR: No suitable player found to take the penalty kick!");
            }

            // --- 2. Identify the defending Goalkeeper ---
            Player defendingGK = DefendingTeam.GoalKeeper;

            // --- 3. Set up Player Positions for Penalty Kick ---
            // All players except the kicker and the defending goalkeeper must be outside the penalty area.

            // Determine the relevant defensive edge of box for the defending team
            Enums.PitchZone defendingEdgeOfBoxZone = (DefendingTeam == HomeTeam) ? Enums.PitchZone.Defensive_EdgeOfBox : Enums.PitchZone.Defensive_EdgeOfBox; // Defensive_EdgeOfBox is generic, assuming it can apply to either half.
            Enums.PitchZone attackingMidfieldCenter = (AttackingTeam == HomeTeam) ? Enums.PitchZone.Midfield_Center : Enums.PitchZone.Midfield_Center; // Using Midfield_Center for balance

            foreach (Player player in HomeTeam.AvailableOnFieldOutfielders.Concat(AwayTeam.AvailableOnFieldOutfielders))
            {
                if (player == penaltyTaker)
                {
                    // Kicker is at the penalty spot. Their CurrentBallZone is implicitly the penalty area of the defending team.
                    // No explicit zone change needed here for the kicker; assumed by context or handled elsewhere.
                    continue;
                }
                else if (player == defendingGK)
                {
                    // Goalkeeper is on the goal line in their own GoalkeeperArea.
                    player.CurrentZone = (DefendingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    continue;
                }
                else
                {
                    // All other outfield players.
                    // Move them to a zone just outside the defending team's penalty area, or midfield,
                    // to ensure they are outside the box but ready for play.

                    if (player.Team == AttackingTeam)
                    {
                        // Attacking players (not the taker) should be outside the defending team's penalty area,
                        // ready to rush in for rebounds. Place them generically at the 'Defensive_EdgeOfBox'.
                        player.CurrentZone = defendingEdgeOfBoxZone;
                    }
                    else // Defending Team outfield players
                    {
                        // Defending players (not GK) should also be outside their own penalty area,
                        // ready to clear rebounds or launch counters.
                        // Place them conceptually near the edge of their own defensive third, or midfield center for spread.
                        player.CurrentZone = defendingEdgeOfBoxZone; // Same as attackers for simplicity, or Midfield_Center.
                        // For more nuanced placement, you might use specific flank zones
                        // (e.g., HomeDefense_LeftFlank if defending home goal, etc.)
                        // Let's use Midfield_Center for a general safe distance.
                        player.CurrentZone = attackingMidfieldCenter; // Place them further back, toward midfield.
                    }
                    //ShowMessage(player.fullName + " moves to position outside the penalty area.");
                }
            }

            // --- 4. Simulate the Penalty Kick Outcome ---
            // Ensure AttackingTeam and DefendingTeam are correctly set for SimulatePenaltyOutcome
            // This is crucial for methods within SimulatePenaltyOutcome that depend on these global states (e.g., GetOpponentGoalkeeperArea)
            AttackingTeam = penaltyTaker.Team;
            DefendingTeam = (penaltyTaker.Team == HomeTeam) ? AwayTeam : HomeTeam;

            bool isGoal = SimulatePenaltyOutcome(penaltyTaker, defendingGK, false); // Not a shootout

            if (isGoal)
            {
                UpdateScore(null, penaltyTaker, defendingGK, true);
                //UpdateScore will set the match state correctly.
                //CurrentMatchState = Enums.MatchState.GoalScored;
            }
            // If not a goal, SimulatePenaltyOutcome already set the appropriate match state (LooseBall, GoalKick)
            // or implies a non-goal outcome.
        }

        /// <summary>
        /// Simulates the outcome of a single penalty kick attempt.
        /// </summary>
        /// <param name="penaltyTaker">The player taking the penalty.</param>
        /// <param name="defendingGK">The goalkeeper defending the penalty.</param>
        /// <param name="isShootout">True if this is part of a penalty shootout, false for in-play penalty.</param>
        /// <returns>True if it was a goal, false otherwise.</returns>
        private bool SimulatePenaltyOutcome(Player penaltyTaker, Player defendingGK, bool isShootout)
        {
            penaltyTaker.gameStats.penaltyKickAttempts++;

            // Calculate chances based on kicker's skill vs. goalkeeper's skill.
            double penaltyShotAccuracy = (penaltyTaker.trueRating.PenaltiesForGameCalculations * 0.6 + penaltyTaker.trueRating.FinishingForGameCalculations * 0.4);
            double goalkeeperSaveAbility = (defendingGK.trueRating.PositioningForGameCalculations * 0.5 +
                                           defendingGK.trueRating.GoalKeepingReflexesForGameCalculations * 0.3 +
                                           defendingGK.trueRating.GoalkeepingDivinghForGameCalculations * 0.1 +
                                           defendingGK.trueRating.GoalKeepingHandlingForGameCalculations * 0.1);
            goalkeeperSaveAbility *= 0.10; // goals should be common with penalty kicks

            // Penalties generally have a high base success rate
            double baseGoalChance = Math.Max(40, penaltyShotAccuracy - (goalkeeperSaveAbility)); // Kicker skill directly against a portion of GK skill
            baseGoalChance = Math.Min(95, baseGoalChance); // Cap maximum goal chance

            int shotOutcomeRoll = Dice.d100();

            bool isGoal = false; // Default outcome

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.PenaltyKickTaken, // Use the general PassOutcome event
                Timestamp = DateTime.Now,
                DribblePhase = DribblePhaseType.Duel,
                DribbleResult = DribbleResultType.NoChallenger,

                PlayerName1 = penaltyTaker.fullName,
                Player1Pos = penaltyTaker.position,
                PlayerName2 = defendingGK.fullName,
                Player2Pos = defendingGK.position,
                TeamName1 = AttackingTeam.Name,
                TeamName2 = DefendingTeam.Name,
                IsShootoutShot = isShootout,
            };

            // First, determine if it's a potential goal (on target) or a clean miss
            if (shotOutcomeRoll < baseGoalChance) // Shot is "on target" or well-struck enough to be a potential goal/save
            {
                // Small chance to hit the post/crossbar, even if the shot is good
                double postHitChance = 8; // 8% chance to hit woodwork
                if (Dice.d100() < postHitChance)
                {
                    if (Dice.d100() < 60) // 60% chance to rebound into play
                    {
                        meOpen.PKResult = PKTakenResult.HitPostLive;
                        if (!isShootout)
                        {
                            SetLooseBall(false, penaltyTaker, CornerDeliveryType.None, AttackingTeam, DefendingTeam);
                            CurrentBallZone = GetOpponentGoalkeeperArea(AttackingTeam); // Adjust for whichever team's goal
                        }
                        //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
                    }
                    else
                    {
                        meOpen.PKResult = PKTakenResult.HitPostOutOfPlay;
                        if (!isShootout)
                        {
                            CurrentMatchState = Enums.MatchState.GoalKick;
                            CurrentBallZone = GetOpponentGoalkeeperArea(AttackingTeam);
                        }
                    }
                }
                else // Shot is on target and didn't hit the woodwork
                {
                    // Now, check if the goalkeeper saves it
                    if (Dice.d100() < goalkeeperSaveAbility) // Goalkeeper makes a save!
                    {
                        //defendingGK.gameStats.IncreaseSaves();
                        if (Dice.d100() < 20) // 20% chance for a rebound
                        {
                            meOpen.PKResult = PKTakenResult.SaveDeflection;
                            CurrentBallZone = GetOpponentGoalkeeperArea(AttackingTeam);
                            if (!isShootout)
                                SetLooseBall(false, penaltyTaker, CornerDeliveryType.None, AttackingTeam, DefendingTeam, true);
                            //CurrentMatchState = Enums.MatchState.InPlay_LooseBall;
                        }
                        else // GK catches/secures the ball cleanly
                        {
                            meOpen.PKResult = PKTakenResult.SaveCatch;
                            if (!isShootout)
                                SetPossession(defendingGK, GetPlayerZone(defendingGK), DefendingTeam);
                            CurrentMatchState = Enums.MatchState.GoalkeeperRecycle;
                        }
                    }
                    else // It's a GOAL!
                    {
                        meOpen.PKResult = PKTakenResult.Goal;
                        isGoal = true;
                    }
                }
            }
            else // Shot was a clean miss (wide or over the bar, not hitting woodwork)
            {
                meOpen.PKResult = PKTakenResult.MissWide;
                if (!isShootout) // Only handle match state for in-play penalties
                {
                    CurrentMatchState = Enums.MatchState.GoalKick;
                    CurrentBallZone = GetOpponentGoalkeeperArea(AttackingTeam);
                }
            }
            LogEntry(meOpen);

            return isGoal;
        }

        bool shootOutEnded = false;
        bool homeTeamKickingNow = true;

        private void ShootOutHandler()
        {
            bool kickScored = false;

            // Determine who is taking the current kick
            // Even kick number (1st, 3rd, 5th, etc.) is home team. Odd kick number (2nd, 4th, etc.) is away team.
            if (penaltyKicksTaken % 2 == 0) // Home team's turn (0, 2, 4...)
            {
                AttackingTeam = HomeTeam;
                DefendingTeam = AwayTeam;
            }
            else // Away team's turn (1, 3, 5...)
            {
                AttackingTeam = AwayTeam;
                DefendingTeam = HomeTeam;
            }

            // Check if there are players left to take the initial 5 kicks
            if ((AttackingTeam == HomeTeam && homeTeamPenaltyTakers.Count > 0) ||
                (AttackingTeam == AwayTeam && awayTeamPenaltyTakers.Count > 0))
            {
                currentPenaltyKicker = AttackingTeam == HomeTeam ? homeTeamPenaltyTakers.Dequeue() : awayTeamPenaltyTakers.Dequeue();
                currentPenaltyGoalkeeper = DefendingTeam.GoalKeeper;

                kickScored = SimulatePenaltyOutcome(currentPenaltyKicker, currentPenaltyKicker, true);

                if (AttackingTeam == HomeTeam)
                {
                    if (kickScored) homeTeamPenaltyGoals++;
                }
                else // Away team just kicked
                {
                    if (kickScored) awayTeamPenaltyGoals++;
                }
                penaltyKicksTaken++; // Increment total kicks taken in the shootout
            }
            else // Sudden death or no more players (shouldn't happen with queue logic)
            {
                // This scenario means we've gone past the initial five kicks for both teams
                // and are in sudden death, or a team ran out of players.
                // For now, if queues are empty, it means we must be done or error.
                //ShowMessage("No more pre-determined penalty takers. Proceeding to sudden death if necessary.");
            }

            MatchEntry meOpen = new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.NonPKScoreUpdate, // Use the general PassOutcome event
                Timestamp = DateTime.Now,

                TeamName1 = HomeTeam.Name,
                TeamName2 = AwayTeam.Name,

                Value1 = homeTeamPenaltyGoals,
                Value2 = awayTeamPenaltyGoals
            };
            LogEntry(meOpen);


            // --- Check Shootout Win Conditions ---
            bool homeWins = false;
            bool awayWins = false;

            // After 5 kicks each (total 10 kicks taken)
            if (penaltyKicksTaken >= 10)
            {
                if (homeTeamPenaltyGoals > awayTeamPenaltyGoals) homeWins = true;
                else if (awayTeamPenaltyGoals > homeTeamPenaltyGoals) awayWins = true;
                // If tied, continue to sudden death (logic below will handle more kicks)
            }
            else // Before all 10 initial kicks are taken (e.g., 3-0 after 3 kicks for team A, 2 for team B)
            {
                // Calculate maximum possible goals for each team if all remaining kicks are scored
                int maxHomeGoals = homeTeamPenaltyGoals + (5 - (penaltyKicksTaken / 2 + (penaltyKicksTaken % 2 == 0 ? 0 : 1))); // Home's remaining kicks
                int maxAwayGoals = awayTeamPenaltyGoals + (5 - (penaltyKicksTaken / 2 + (penaltyKicksTaken % 2 != 0 ? 0 : 1))); // Away's remaining kicks

                // If one team's current score + remaining max kicks is less than the other's current score
                if (homeTeamPenaltyGoals > maxAwayGoals) homeWins = true;
                else if (awayTeamPenaltyGoals > maxHomeGoals) awayWins = true;
            }

            // Sudden death logic (after 10 kicks and still tied, or initial queues are empty)
            if (penaltyKicksTaken >= 10 && homeTeamPenaltyGoals == awayTeamPenaltyGoals)
            {
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.PenaltyKickExtraTimeUpdate, // Use the general PassOutcome event
                    Timestamp = DateTime.Now,

                    Value1 = homeTeamPenaltyGoals,
                    Value2 = awayTeamPenaltyGoals
                };
                LogEntry(meOpen);
                // Need to re-enqueue players if queues are empty, or cycle through remaining players
                // For simplicity, let's just re-enqueue all active players for sudden death.
                if (homeTeamPenaltyTakers.Count == 0)
                {
                    // Re-queue all active players not sent off (including those who already kicked)
                    foreach (var p in HomeTeam.AvailableOnFieldPlayers.OrderBy(p => p.ID)) // Stable order
                        homeTeamPenaltyTakers.Enqueue(p);
                }
                if (awayTeamPenaltyTakers.Count == 0)
                {
                    // Re-queue all active players not sent off (including those who already kicked)
                    foreach (var p in AwayTeam.AvailableOnFieldPlayers.OrderBy(p => p.ID))
                        awayTeamPenaltyTakers.Enqueue(p);
                }
                // If we continue here, the next iteration will take another kick.
            }


            // If a winner is found, transition to FullTime (which handles final score display)
            if (homeWins || awayWins)
            {
                // Update main game score to reflect shootout winner (optional, but good for final display)
                //if (homeWins) score++; // Award an extra goal to winner for score display
                //else awayTeam.score++;
                if (homeWins)
                {
                    GameResult = RecordGameResult(HomeTeam, GetHomeScore() + " (" + homeTeamPenaltyGoals.ToString() + ")", AwayTeam,
                        GetAwayScore() + " (" + awayTeamPenaltyGoals.ToString() + ")", true);
                }
                else
                {
                    GameResult = RecordGameResult(AwayTeam, GetHomeScore() + " (" + homeTeamPenaltyGoals.ToString() + ")", HomeTeam,
                        GetAwayScore() + " (" + awayTeamPenaltyGoals.ToString() + ")", true);
                }
                CurrentMatchState = Enums.MatchState.MatchEnded; // End the match. Winner declared.
                meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    Timestamp = DateTime.Now,
                    GamePhase = GamePhaseType.PenaltyShootoutEnd,
                    EventType = MatchEventType.GamePhaseChange,
                    TeamName1 = HomeTeam.Name,
                    TeamName2 = AwayTeam.Name,

                    HomePKScores = homeTeamPenaltyGoals,
                    AwayPKScores = awayTeamPenaltyGoals,
                    HomeScore = HomeScore,
                    AwayScore = AwayScore
                };
                LogEntry(meOpen);
            }
        }

        private void SetupPenaltyShootout()
        {
            homeTeamPenaltyGoals = 0;
            awayTeamPenaltyGoals = 0;
            penaltyKicksTaken = 0;

            homeTeamPenaltyTakers.Clear();
            awayTeamPenaltyTakers.Clear();

            // Select all eligible penalty takers for each team, sorted by penalty ability
            var homeEligibleTakers = GetEligiblePenaltyTakers(HomeTeam.AvailableOnFieldPlayers);
            var awayEligibleTakers = GetEligiblePenaltyTakers(AwayTeam.AvailableOnFieldPlayers);

            // Enqueue all eligible players for a full shootout (important for sudden death)
            foreach (var player in homeEligibleTakers)
            {
                homeTeamPenaltyTakers.Enqueue(player);
            }
            foreach (var player in awayEligibleTakers)
            {
                awayTeamPenaltyTakers.Enqueue(player);
            }

            int diceRoll = Dice.d2();
            if (diceRoll == 1)
            {
                homeTeamKickingNow = true; // Home team kicks first
            }
            else
            {
                homeTeamKickingNow = false; // Away team kicks first
            }

            LogEntry(new MatchEntry
            {
                Level = LogLevel.Info,
                EventType = MatchEventType.GamePhaseChange, // Use the general GamePhaseChange
                Timestamp = DateTime.Now, // Always include for precise timing

                // Set the specific game phase for Regulation Full Time
                GamePhase = GamePhaseType.PenaltyShootoutStart,

                // Use the specific score fields
                HomeScore = TotalHomeScore(),
                AwayScore = TotalAwayScore(),

                // Team names remain directly mapped
                TeamName1 = HomeTeam.Name,
                TeamName2 = AwayTeam.Name,
                Value1 = diceRoll
            });

            // Set match state to PenaltyShootout and transition to the first kick
            CurrentMatchState = Enums.MatchState.PenaltyShootout;
            // The next step in your game loop should call ProcessPenaltyShootoutKick()
        }

        private List<Player> GetEligiblePenaltyTakers(IEnumerable<Player> onFieldPlayers)
        {
            List<Player> eligibleTakers = new List<Player>();

            foreach (Player player in onFieldPlayers)
            {
                eligibleTakers.Add(player);
            }

            eligibleTakers.Sort((a, b) => b.trueRating.PenaltiesForGameCalculations.CompareTo(a.trueRating.PenaltiesForGameCalculations));

            return eligibleTakers;
        }

        private List<Player> GetCycledTakers(IEnumerable<Player> onFieldPlayers)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetCycledTakers: onFieldPlayers:{0}",
            //    string.Join(",", onFieldPlayers.Select(p => p.position))));


            List<Player> cycledTakers = new List<Player>();

            foreach (Player player in onFieldPlayers)
            {
                if (!player.isSentOff && !player.isInjured)
                {
                    cycledTakers.Add(player);
                }
            }

            cycledTakers.Sort((a, b) => a.gameStats.penaltyKickAttempts.CompareTo(b.gameStats.penaltyKickAttempts));

            return cycledTakers;
        }

        #endregion

        #region Injuries

        /// <summary>
        /// Checks for injury after a foul, with higher chance/severity.
        /// </summary>
        private void CheckForInjuryAfterFoul(Player tackler, Player dribbler, Enums.FoulType foulType, double baseInjuryChanceMultiplier)
        {
            double finalMultiplier = baseInjuryChanceMultiplier;

            // Further increase multiplier for very serious fouls
            if (foulType == Enums.FoulType.SeriousFoulPlay || foulType == Enums.FoulType.ViolentConduct)
            {
                finalMultiplier *= 2.0;
            }

            // Tackler might also get injured in a bad foul attempt
            ProcessTackleInjury(tackler, tackler, finalMultiplier * 0.7); // Slightly lower chance for tackler in a foul
            ProcessTackleInjury(dribbler, tackler, finalMultiplier * 1.5); // Higher chance for the fouled player
        }

        /// <summary>
        /// Checks for injury after a successful tackle, generally lower chance.
        /// </summary>
        private void CheckForInjuryAfterTackleSuccess(Player tackler, Player dribbler, double baseInjuryChanceMultiplier)
        {
            // Minor chance of injury for both players in a clean but forceful tackle
            ProcessTackleInjury(tackler, dribbler, baseInjuryChanceMultiplier * 0.05); // Low chance for tackler
            ProcessTackleInjury(dribbler, tackler, baseInjuryChanceMultiplier * 0.4); // Low chance for dribbler
        }

        /// <summary>
        /// Checks for injury after a failed tackle, generally moderate chance.
        /// </summary>
        private void CheckForInjuryAfterTackleFailure(Player tackler, Player dribbler, double baseInjuryChanceMultiplier)
        {
            // Moderate chance for both, especially the tackler who might have overextended
            ProcessTackleInjury(tackler, dribbler, baseInjuryChanceMultiplier * 0.1); // Moderate chance for tackler
            ProcessTackleInjury(dribbler, tackler, baseInjuryChanceMultiplier * 0.05); // Moderate chance for dribbler (less direct impact)
        }

        /// <summary>
        /// Central method to process potential injuries from tackles. This is where your
        /// "Injury Enhancements" logic would truly reside.
        /// </summary>
        /// <param name="injuredPlayer">The player who might get injured.</param>
        /// <param name="instigator">The player who caused the tackle/foul (can be the same as injuredPlayer if self-injury).</param>
        /// <param name="eventChanceMultiplier">A multiplier based on the tackle outcome (foul, success, failure).</param>
        // In your Game.cs or MatchEngine.cs
        private void ProcessTackleInjury(Player injuredPlayer, Player instigator, double eventChanceMultiplier)
        {
            // Only process if the player isn't already injured (or if they can get multiple injuries, check active injury type)
            // Your IsInjured property checks for ANY active injury. If you want to allow a player to get a new injury
            // while recovering from a minor one, you might remove this check, or add specific conditions.
            if (injuredPlayer.IsInjured)
            {
                return;
            }

            // Make sure ActiveInjuries and InjuryHistory lists are initialized
            if (injuredPlayer.ActiveInjuries == null) injuredPlayer.ActiveInjuries = new List<Injury>();
            if (injuredPlayer.InjuryHistory == null) injuredPlayer.InjuryHistory = new List<Injury>();

            // Base chance for any injury from a tackle (adjust this as needed)
            double baseInjuryChance = 5; // e.g., 5% base chance for a minor injury

            // Adjust by player's InjuryProneness (1-20 scale)
            // Assuming 10 is average: less than 10 reduces chance, more than 10 increases chance.
            baseInjuryChance += (injuredPlayer.InjuryResistance - 10) * 1.5; // Example adjustment

            // If you have player.Toughness, uncomment and adjust this:
            // baseInjuryChance -= (injuredPlayer.Toughness - 50) * 0.3; // Assuming Toughness is 1-100 scale, 50 is average

            // Apply event-specific multiplier (from foul, success, failure)
            double finalInjuryChance = baseInjuryChance * eventChanceMultiplier;

            // Clamp chance
            finalInjuryChance = Math.Max(0, Math.Min(100, finalInjuryChance));

            int injuryCount = injuredPlayer.ActiveInjuries.Count;
            InjuryManager.GeneratePlayerInjury(injuredPlayer, instigator, finalInjuryChance, DateTime.Now);
            if (injuredPlayer.ActiveInjuries.Count > injuryCount)
            {
                if (!injuredPlayer.AvailableOption)
                {
                    // injury severe enough to be carted off the field next stoppage.
                    injuredPlayer.Team.InvalidateOutfieldersCache();
                }
                // Call the new method to determine and apply the specific injury
                // You'll need to pass your game's current date/time here
                // Example: GeneratePlayerInjury(injuredPlayer, instigator, finalInjuryChance, CurrentGameDateTime);
                // For now, I'll use DateTime.Now as a placeholder if you don't have a game date system yet.
                MatchEntry meOpen = new MatchEntry
                {
                    Level = LogLevel.Info,
                    EventType = MatchEventType.Injury,
                    Timestamp = DateTime.Now,

                    PlayerName1 = injuredPlayer.fullName,
                    Player1Pos = injuredPlayer.position,
                    PlayerName2 = instigator.fullName,
                    Player2Pos = instigator.position,
                    TeamName1 = injuredPlayer.teamName,
                    TeamName2 = instigator.teamName,

                    Zone1 = CurrentBallZone,
                };
                LogEntry(meOpen);
            }
        }

        #endregion

        #region Positioning

        /// <summary>
        /// Evaluates potential attacking runs for an off-ball player and updates their position.
        /// Goalkeepers are excluded from making attacking runs.
        /// This method now includes logic for specific set-piece movement during Free Kicks (Indirect and Direct).
        /// </summary>
        /// <param name="player">The off-ball attacking player.</param>
        /// <param name="attackingTeam">The team currently in possession.</param>
        /// <param name="defendingTeam">The opposing team.</param>
        private void EvaluateAttackingMovement(Player player, Team attackingTeam, Team defendingTeam, Enums.SetPieceRoutine CurrentSetPieceRoutine = Enums.SetPieceRoutine.None,
            int currentMinute = 0, int currentSecond = 0)
        {
            //LoggingStuff.LogMethodCall(string.Format("EvaluateAttackingMovement: player:{0},attackingTeam:{1},defendingTeam:{2}," +
            //    "CurrentSetPieceRoutine:{3},currentMinute:{4},currentSecond:{5}",
            //    player.position, attackingTeam.Name, defendingTeam.Name, CurrentSetPieceRoutine, currentMinute, currentSecond));


            // Goalkeepers do not make attacking runs.
            if (player.Position == Enums.Positions.Goalkeeper || !player.IsAvailable || player == CurrentBallHolder)
            {
                return;
            }

            // --- Set Piece Specific Movement Logic ---
            // If the game state is a Free Kick (Indirect or Direct), override general movement logic
            if (CurrentMatchState == Enums.MatchState.FreeKick_Indirect || CurrentMatchState == Enums.MatchState.FreeKick)
            {
                //ShowMessage(player.fullName + " is evaluating movement for a Free Kick (Routine: " + CurrentSetPieceRoutine + ").");

                Enums.PitchZone determinedTargetSetPieceZone = Enums.PitchZone.None;
                bool isAttackingTeamHome = (attackingTeam == HomeTeam);

                // A. Handle specific routine-based movements first, based on the global 'CurrentSetPieceRoutine'
                if (CurrentSetPieceRoutine != Enums.SetPieceRoutine.None)
                {
                    switch (CurrentSetPieceRoutine)
                    {
                        case Enums.SetPieceRoutine.NearPostRun:
                            // Players suitable for attacking runs (strikers, CAMs, fast players)
                            if (player.Position == Enums.Positions.Striker || player.Position == Enums.Positions.CentralAttackingMidfielder || player.trueRating.AccelerationForGameCalculations > 70)
                            {
                                determinedTargetSetPieceZone = GetNearPostZone(CurrentBallZone, isAttackingTeamHome);
                                //ShowMessage(player.fullName + " making a Near Post run into " + determinedTargetSetPieceZone + " for routine " + CurrentSetPieceRoutine + ".");
                            }
                            break;
                        case Enums.SetPieceRoutine.FarPostRun:
                            // Players good at heading, or strikers
                            if (player.Position == Enums.Positions.Striker || player.trueRating.HeaderForGameCalculations > 60 || player.trueRating.JumpingForGameCalculations > 60)
                            {
                                determinedTargetSetPieceZone = GetFarPostZone(CurrentBallZone, isAttackingTeamHome);
                                //ShowMessage(player.fullName + " making a Far Post run into " + determinedTargetSetPieceZone + " for routine " + CurrentSetPieceRoutine + ".");
                            }
                            break;
                        case Enums.SetPieceRoutine.LayOffShort:
                            // Midfielders or technical players for short passes
                            if (player.Position == Enums.Positions.CentralMidfielder || player.Position == Enums.Positions.CentralDefendingMidfielder || player.trueRating.PassingForGameCalculations > 65)
                            {
                                determinedTargetSetPieceZone = GetSafeShortPassZone(CurrentBallZone, isAttackingTeamHome);
                                //ShowMessage(player.fullName + " moving short for a Lay-Off pass into " + determinedTargetSetPieceZone + " for routine " + CurrentSetPieceRoutine + ".");
                            }
                            break;
                        case Enums.SetPieceRoutine.CrowdTheBox:
                            // Target men, strong headers, or general attacking players
                            determinedTargetSetPieceZone = DetermineMovementForCrowdTheBox(player, attackingTeam, defendingTeam);
                            //ShowMessage(player.fullName + " crowding the box into " + determinedTargetSetPieceZone + " for routine " + CurrentSetPieceRoutine + ".");
                            break;
                        case Enums.SetPieceRoutine.ShotOnGoal:
                            // This routine primarily applies to the free kick taker themselves for direct shots.
                            // Other attacking players might move to cover rebound areas or simply hold position.
                            if (player == CurrentBallHolder) // This is the free kick taker
                            {
                                player.targetSetPieceZone = isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                                //ShowMessage(player.fullName + " is positioned for a direct shot on goal (" + player.targetSetPieceZone + ").");
                                player.CurrentZone = player.targetSetPieceZone; // Commit movement for taker's 'action'
                                return; // Taker's action is done for movement purposes
                            }
                            else // This is a *non-taker* attacking player
                            {
                                //ShowMessage(player.fullName + " is seeking rebound or disruption spot for direct shot routine.");
                                determinedTargetSetPieceZone = DetermineMovementForNonTakerShotSupport(player, attackingTeam, defendingTeam);
                            }
                            break;
                        case Enums.SetPieceRoutine.ThroughBallRun:
                            // Players with good pace and off-the-ball movement, usually strikers or wingers
                            determinedTargetSetPieceZone = DetermineMovementForThroughBallRun(player, attackingTeam, defendingTeam);
                            if (determinedTargetSetPieceZone != Enums.PitchZone.None)
                            {
                                //ShowMessage(player.fullName + " making a Through Ball run into " + determinedTargetSetPieceZone + " for routine " + CurrentSetPieceRoutine + ".");
                            }
                            else
                            {
                                //ShowMessage(player.fullName + " tried for Through Ball run, but no ideal zone found, defaulting.");
                            }
                            break;
                    }
                }

                // B. Fallback to general role-based set-piece positioning if no specific routine applied
                // (or if the routine didn't dictate a specific zone for this player or the player didn't qualify for the routine).
                if (determinedTargetSetPieceZone == Enums.PitchZone.None)
                {
                    determinedTargetSetPieceZone = GetZoneForPlayerInFormation(player.Position, attackingTeam.CurrentFormation, isAttackingTeamHome);
                    //ShowMessage(player.fullName + " defaults to formation-based set-piece run to " + determinedTargetSetPieceZone + ".");
                }

                // **CRITICAL ADDITION:** Ensure determinedTargetSetPieceZone is NEVER None here.
                if (determinedTargetSetPieceZone == Enums.PitchZone.None)
                {
                    // If, even after routine-specific logic AND formation-based fallback,
                    // we still don't have a valid zone, assign a sensible universal default.
                    // This prevents 'None' from ever being assigned to player.CurrentZone here.
                    if (player.Team == attackingTeam)
                    {
                        determinedTargetSetPieceZone = Enums.PitchZone.Midfield_Center;
                    }
                    else
                    {

                    }
                    // Or a defensive zone, depending on context for unassigned players
                    //ShowMessage(player.fullName + " defaulted to a safe fallback zone: " + determinedTargetSetPieceZone + ".");
                }

                if (determinedTargetSetPieceZone != Enums.PitchZone.None && player.CurrentZone != determinedTargetSetPieceZone)
                {
                    //ShowMessage(player.fullName + " (" + attackingTeam.Name + ") adjusts for Free Kick to " + EnumCache<Enums.PitchZone>.ToString(determinedTargetSetPieceZone).Replace("_", " ") + ".");
                    player.CurrentZone = determinedTargetSetPieceZone;
                }
                else
                {
                    //ShowMessage(player.fullName + " (" + attackingTeam.Name + ") holds position for Free Kick (no new target).");
                    // Also ensure player.CurrentZone isn't None if it somehow started that way and no movement occurred.
                    // This is less likely if you prevent determinedTargetSetPieceZone from being None, but good for robustness.
                    if (player.CurrentZone == Enums.PitchZone.None)
                    {
                        player.CurrentZone = GetZoneForPlayerInFormation(player.Position, attackingTeam.CurrentFormation, isAttackingTeamHome);
                        if (player.CurrentZone == Enums.PitchZone.None) player.CurrentZone = Enums.PitchZone.Midfield_Center; // Absolute last resort
                    }
                }
                return; // Set piece movement handled, exit.
            }

            // --- Existing General Movement Logic (for In-Play) ---
            // This part runs ONLY if CurrentMatchState is NOT a Free Kick (Indirect or Direct)
            double runLikelihood = (player.trueRating.PositioningForGameCalculations * 0.3) +
                                   (player.trueRating.PaceForGameCalculations * 0.3) +
                                   (player.trueRating.AccelerationForGameCalculations * 0.2) +
                                   (player.CurrentCondition * 0.2);
            runLikelihood /= 100.0;

            if (Dice.d100() > (runLikelihood * 100 * 0.8))
            {
                player.CurrentZone = DetermineOffensiveZone(player, CurrentBallZone, attackingTeam);
                //ShowMessage(player.fullName + " makes a general run based on low likelihood roll to " + player.CurrentZone + ".");
                return;
            }

            Enums.PitchZone idealOffensiveZone = DetermineOffensiveZone(player, CurrentBallZone, attackingTeam);

            Enums.PitchZone bestMoveZone = player.CurrentZone;
            double bestScore = -1.0;

            HashSet<Enums.PitchZone> uniqueZones = new HashSet<Enums.PitchZone>();

            if (idealOffensiveZone != player.CurrentZone)
            {
                uniqueZones.Add(idealOffensiveZone);
            }
            uniqueZones.Add(player.CurrentZone);

            foreach (var adjacentZone in GetAdjacentZones(player.CurrentZone, attackingTeam == HomeTeam))
            {
                uniqueZones.Add(adjacentZone);
            }

            int currentForwardValue = GetZoneForwardValue(player.CurrentZone, attackingTeam == HomeTeam);
            Enums.PitchZone zoneAhead = GetZoneAhead(player.CurrentZone, attackingTeam == HomeTeam);
            if (zoneAhead != Enums.PitchZone.None && GetZoneForwardValue(zoneAhead, attackingTeam == HomeTeam) > currentForwardValue)
            {
                uniqueZones.Add(zoneAhead);
                if (player.Position == Enums.Positions.LeftWingForward || player.Position == Enums.Positions.RightWingForward ||
                    player.Position == Enums.Positions.LeftMidfielder || player.Position == Enums.Positions.RightMidfielder)
                {
                    Enums.PitchZone flankZoneAhead = GetFlankZoneAhead(player.CurrentZone, attackingTeam == HomeTeam, player.Position);
                    if (flankZoneAhead != Enums.PitchZone.None)
                    {
                        uniqueZones.Add(flankZoneAhead);
                    }
                }
            }

            List<Enums.PitchZone> potentialZones = new List<Enums.PitchZone>(uniqueZones);

            foreach (Enums.PitchZone targetZone in potentialZones)
            {
                double score = CalculateMovementScore(player, targetZone, CurrentBallZone, attackingTeam, defendingTeam, attackingTeam.CurrentTactic, CurrentMinute, CurrentSecond);

                if (score > bestScore)
                {
                    bestScore = score;
                    bestMoveZone = targetZone;
                }
            }

            if (bestMoveZone != player.CurrentZone)
            {
                //ShowMessage(player.fullName + " (" + attackingTeam.Name + ") makes a run to " + EnumCache<Enums.PitchZone>.ToString(bestMoveZone).Replace("_", " ") + ".");
                player.DecreaseCondition(0.2); // Only decrease condition on actual movement
            }
            else
            {
                if (idealOffensiveZone == Enums.PitchZone.None)
                {
                    idealOffensiveZone = player.CurrentZone;
                    player.CurrentZone = idealOffensiveZone;
                    int x = 0;
                }
                //ShowMessage(player.fullName + " (" + attackingTeam.Name + ") holds position or moves to ideal offensive zone " + player.CurrentZone + ".");
            }
        }

        // --- DetermineMovementForNonTakerShotSupport Method ---
        /// <summary>
        /// Determines the optimal movement zone for a non-free-kick-taker attacking player when the routine is ShotOnGoal.
        /// These players will look for rebound opportunities or wall disruption.
        /// </summary>
        private Enums.PitchZone DetermineMovementForNonTakerShotSupport(Player player, Team attackingTeam, Team defendingTeam)
        {
            Enums.PitchZone freeKickZone = this.CurrentBallZone;
            bool isAttackingTeamHome = (attackingTeam == HomeTeam);

            Enums.PitchZone preferredZone = Enums.PitchZone.None;
            double bestScore = -1.0;

            HashSet<Enums.PitchZone> uniqueCandidateZones = new HashSet<Enums.PitchZone>();

            // Central dangerous zones for rebounds
            uniqueCandidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home);
            uniqueCandidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home);

            // Zones just outside the penalty area for second balls/layoffs after a blocked shot
            if (isAttackingTeamHome)
            {
                uniqueCandidateZones.Add(Enums.PitchZone.AwayAttack_Center);
                uniqueCandidateZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                uniqueCandidateZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
            }
            else
            {
                uniqueCandidateZones.Add(Enums.PitchZone.HomeDefense_Center);
                uniqueCandidateZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                uniqueCandidateZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
            }

            // Add specific wall disruption zones
            AddNonNoneZone(GetZoneAdjacentToOpponentWall(freeKickZone, isAttackingTeamHome, true), ref uniqueCandidateZones); // Near side of wall
            AddNonNoneZone(GetZoneAdjacentToOpponentWall(freeKickZone, isAttackingTeamHome, false), ref uniqueCandidateZones); // Far side of wall
            AddNonNoneZone(GetZoneBehindWall(freeKickZone, isAttackingTeamHome), ref uniqueCandidateZones); // Behind the wall for rebounds

            List<Enums.PitchZone> candidateZones = new List<Enums.PitchZone>(uniqueCandidateZones);

            foreach (var targetZone in candidateZones)
            {
                double currentZoneScore = 0;

                // Scoring for Rebound Poachers
                currentZoneScore += player.trueRating.VisionForGameCalculations * 0.25;
                currentZoneScore += player.trueRating.AgilityForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.FinishingForGameCalculations * 0.15;
                currentZoneScore += player.trueRating.PositioningForGameCalculations * 0.1;

                // Bonus for being in highly dangerous zones (penalty area, goalkeeper area)
                if (targetZone == (isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home)) currentZoneScore += 25;
                else if (targetZone == (isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home)) currentZoneScore += 15;
                else if (GetZoneForwardValue(targetZone, isAttackingTeamHome) >= GetZoneForwardValue(freeKickZone, isAttackingTeamHome))
                {
                    currentZoneScore += 5;
                }

                // Scoring for Wall Disruptors/Blockers
                if (targetZone == GetZoneAdjacentToOpponentWall(freeKickZone, isAttackingTeamHome, true) ||
                    targetZone == GetZoneAdjacentToOpponentWall(freeKickZone, isAttackingTeamHome, false))
                {
                    currentZoneScore += player.trueRating.AggressionForGameCalculations * 0.1;
                    currentZoneScore += player.trueRating.ComposureForGameCalculations * 0.1;
                    currentZoneScore += player.trueRating.StrengthForGameCalculations * 0.05;

                    if (player.Position == Enums.Positions.Striker || player.Position == Enums.Positions.CentralAttackingMidfielder || player.Position == Enums.Positions.CentralDefendingMidfielder)
                    {
                        currentZoneScore += 8; // Roles often attempting this
                    }
                }

                // Penalties:
                if (IsLikelyOffsideFromFreeKick(targetZone, attackingTeam, defendingTeam))
                {
                    currentZoneScore -= 100; // Heavy penalty
                }

                int defendersInZone = CountDefendersInZone(targetZone, defendingTeam);
                currentZoneScore -= defendersInZone * 6; // Moderate penalty for congestion

                // Ensure player's current zone is considered as an option for 'holding position'
                if (targetZone == player.CurrentZone)
                {
                    currentZoneScore += 2; // Slight bias to holding position if otherwise equal
                }

                if (currentZoneScore > bestScore)
                {
                    bestScore = currentZoneScore;
                    preferredZone = targetZone;
                }
            }

            if (preferredZone == Enums.PitchZone.None || bestScore < 0) // If no viable attacking zone, fall back
            {
                return GetZoneForPlayerInFormation(player.Position, attackingTeam.CurrentFormation, isAttackingTeamHome);
            }

            return preferredZone;
        }

        /// <summary>
        /// Determines if an attacking player is in an offside position.
        /// Simplified rules: player must be in opponent's half, closer to opponent's goal than the ball,
        /// AND closer to opponent's goal than the second-to-last outfield defender.
        /// </summary>
        /// <param name="player">The attacking player to check for offside.</param>
        /// <param name="defendingTeam">The team currently defending against the player.</param>
        /// <param name="simulatedPlayerTargetZone">Optional: The simulated future zone of the player for predictive checks (e.g., set piece routines). If null, player.CurrentZone is used.</param>
        /// <returns>True if the player is offside, false otherwise.</returns>
        private bool IsOffside(Player player, Team defendingTeam, Enums.PitchZone? simulatedPlayerTargetZone = null,
            bool isSetPiece = false)
        {
            if (isSetPiece && (CurrentMatchState == Enums.MatchState.GoalKick ||
                       CurrentMatchState == Enums.MatchState.CornerKick ||
                       CurrentMatchState == Enums.MatchState.ThrowIn))
            {
                return false; // Cannot be offside directly from these set pieces
            }
            //LoggingStuff.LogMethodCall(string.Format("IsOffside: player:{0},defendingTeam:{1},simulatedPlayerTargetZone:{2}",
            //    player.position, defendingTeam.Name, simulatedPlayerTargetZone));


            // Determine the zone to use for the player's position in the offside check.
            // Use the simulated target zone if provided, otherwise use their current zone.
            Enums.PitchZone playerCheckZone = simulatedPlayerTargetZone ?? player.CurrentZone;

            // A player cannot be offside in their own half.
            int playerForwardValue = GetZoneForwardValue(playerCheckZone, defendingTeam == HomeTeam);
            int midfieldForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, defendingTeam == HomeTeam);

            // Rule 1: Player must be in the opponent's half (or strictly speaking, beyond the halfway line).
            if (playerForwardValue <= midfieldForwardValue)
            {
                return false;
            }

            // Rule 2: Player must be closer to the opponent's goal line than the ball.
            // The ball's position at the moment of the pass/kick is what counts.
            // For set pieces, this is CurrentBallZone.
            int ballForwardValue = GetZoneForwardValue(CurrentBallZone, defendingTeam == HomeTeam); // Use CurrentBallZone for set pieces
            if (playerForwardValue <= ballForwardValue)
            {
                return false; // Player is behind or level with the ball at the moment of delivery
            }

            // Rule 3: Player must be closer to the opponent's goal line than the second-to-last defender.
            // Find all outfield defenders, sort them by their forward position (closest to their own goal first),
            // and get the second one.
            List<Player> relevantDefenders = new List<Player>();
            bool isDefendingTeamHome = defendingTeam == HomeTeam;

            foreach (var defender in defendingTeam.AvailableOnFieldOutfielders)
            {
                if (defender.Position != Enums.Positions.Goalkeeper && defender.IsAvailable)
                {
                    relevantDefenders.Add(defender);
                }
            }

            relevantDefenders.Sort((a, b) =>
                GetZoneForwardValue(a.CurrentZone, isDefendingTeamHome).CompareTo(
                GetZoneForwardValue(b.CurrentZone, isDefendingTeamHome)));

            int secondToLastDefenderForwardValue;
            if (relevantDefenders.Count >= 2)
            {
                secondToLastDefenderForwardValue = GetZoneForwardValue(relevantDefenders[1].CurrentZone, defendingTeam == HomeTeam);
            }
            else if (relevantDefenders.Count == 1)
            {
                // If only one outfield defender, they are effectively the "second-to-last" (and last)
                secondToLastDefenderForwardValue = GetZoneForwardValue(relevantDefenders[0].CurrentZone, defendingTeam == HomeTeam);
            }
            else // No outfield defenders, offside is not possible by this rule (unless vs. goal line, but standard rules require defenders)
            {
                return false;
            }

            bool isOffside = playerForwardValue > secondToLastDefenderForwardValue;

            // This CheckForChanceNegation should typically happen only when an offside is actually called during play,
            // not just when checking if a player *would be* offside for a routine.
            // If you keep it here, be mindful it might fire prematurely.
            if (isOffside)
            {
                //ShowMessage(string.Format("OFFSIDE check for {0}: Player Zone {1} (FW Value: {2}), Ball Zone {3} (FW Value: {4}), Second-to-last defender Zone: {5} (FW Value: {6}). Player is offside.",
                //    player.fullName, playerCheckZone, playerForwardValue, CurrentBallZone, ballForwardValue, relevantDefenders.Count >= 2 ? EnumCache<Enums.PitchZone>.ToString(relevantDefenders[1].CurrentZone) : (relevantDefenders.Count == 1 ? EnumCache<Enums.PitchZone>.ToString(relevantDefenders[0].CurrentZone) : "N/A"), secondToLastDefenderForwardValue));
                CheckForChanceNegation(player.Team, CurrentSecond, negatingPlayer: null, majorOffensiveErrorOccurred: true); // Reconsider if this should be here
            }

            return isOffside;
        }

        public bool CheckForOffside(Player passer, Player receiver, Enums.PitchZone ballPlayedZone, bool isSetPiece, PitchZone currentBall = PitchZone.None, Enums.PitchZone? receiverZoneForCheckOverride = null)
        {
            //LoggingStuff.LogMethodCall(string.Format("CheckForOffside: passer:{0},receiver:{1},ballPlayedZone:{2}," +
            //    "isSetPiece:{3},currentBall:{4},receiverZoneForCheckOverride{5}",
            //    passer.position, receiver.position, ballPlayedZone, isSetPiece, currentBall, receiverZoneForCheckOverride));

            // Check for indirect free kick rule:
            if (CurrentMatchState == Enums.MatchState.FreeKick_Indirect && isSetPiece)
            {
                return false;
            }

            // Ensure essential properties are available from the class scope
            if (AttackingTeam == null || DefendingTeam == null || HomeTeam == null || AwayTeam == null)
            {
                throw new Exception("Error: AttackingTeam, DefendingTeam, homeTeam, or awayTeam not initialized. Cannot check offside.");
            }

            // --- CRITICAL CHANGE: Use receiverZoneForCheckOverride if provided, else receiver.CurrentZone ---
            // This allows the AI to check a *hypothetical* receiving zone for planning.
            Enums.PitchZone actualReceiverZone = receiverZoneForCheckOverride ?? receiver.CurrentZone;

            // 1. A player cannot be offside in their own half.
            int receiverAbsoluteDepth = GetAbsolutePitchDepth(actualReceiverZone);

            if (receiverAbsoluteDepth == -1)
            {
                throw new Exception("Receiver " + receiver.fullName + " is in an undefined zone " + actualReceiverZone + ". Offside check skipped.");
            }

            bool receiverIsInAttackingHalf;
            int HalfwayLineDepth = GetAbsolutePitchDepth(Enums.PitchZone.Midfield_Center); // This is 3

            if (AttackingTeam == HomeTeam)
            {
                receiverIsInAttackingHalf = receiverAbsoluteDepth > HalfwayLineDepth;
            }
            else // AttackingTeam == awayTeam
            {
                receiverIsInAttackingHalf = receiverAbsoluteDepth < HalfwayLineDepth;
            }

            if (!receiverIsInAttackingHalf)
            {
                return false; // Not offside if in own half or on the halfway line.
            }

            // 2. Determine the "offside line" from the second-to-last opponent.
            List<Player> allDefendingPlayers = new List<Player>(DefendingTeam.AvailableOnFieldPlayers);
            Player secondToLastOpponent = null;

            if (allDefendingPlayers.Count < 2)
            {
                //ShowMessage("Not enough defenders to establish an offside line (less than 2). No offside.");
                //LogEntry(new MatchEntry
                //{
                //    Level = LogLevel.Debug,
                //    EventType = MatchEventType.NoOffside,
                //    Zone1 = ballPlayedZone,
                //    Timestamp = DateTime.Now
                //});
                return false;
            }

            // Sort defenders by their absolute pitch depth in ascending order (0 to 6).
            // This puts players closer to the Home team's goal (depth 0) at the start of the list.
            allDefendingPlayers.Sort((a, b) =>
            {
                int depthA = GetAbsolutePitchDepth(a.CurrentZone);
                int depthB = GetAbsolutePitchDepth(b.CurrentZone);

                // Handle potential -1 depths gracefully during sort
                if (depthA == -1) return (depthB == -1) ? 0 : 1; // Undefined zone is "further away" (less relevant for offside line)
                if (depthB == -1) return -1;

                return depthA.CompareTo(depthB);
            });

            if (AttackingTeam == HomeTeam)
            {
                // Home team attacks 0 -> 6. Second-to-last defender is the one with the second-highest depth.
                secondToLastOpponent = allDefendingPlayers[allDefendingPlayers.Count - 2];
            }
            else // AwayTeam is attacking 6 -> 0. Second-to-last defender is the one with the second-lowest depth.
            {
                secondToLastOpponent = allDefendingPlayers[1];
            }

            if (secondToLastOpponent == null)
            {
                //ShowMessage("Not enough defenders to establish an offside line. No offside.");
                //LogEntry(new MatchEntry
                //{
                //    Level = LogLevel.Debug,
                //    EventType = MatchEventType.NoOffside,
                //    NumericValue1 = allDefendingPlayers.Count,
                //    Zone1 = ballPlayedZone,
                //    Timestamp = DateTime.Now
                //});
                return false;
            }

            int secondToLastOpponentAbsoluteDepth = GetAbsolutePitchDepth(secondToLastOpponent.CurrentZone);
            int ballPlayedAbsoluteDepth = GetAbsolutePitchDepth(ballPlayedZone); // This is the depth of the ball when played

            // If you intend to use 'currentBall' for the ball depth instead of 'ballPlayedZone'
            // then you would use GetAbsolutePitchDepth(currentBall) here.
            // Based on the parameter name 'ballPlayedZone', it seems you intend to use that.
            // I will assume ballPlayedZone is the authoritative source for the ball's depth for offside.

            if (ballPlayedAbsoluteDepth == -1)
            {
                throw new Exception("Ball played from an undefined zone " + ballPlayedZone + ". Offside check skipped");
            }

            // 3. Compare positions: Receiver vs. Second-to-Last Opponent vs. Ball Played Zone
            bool isOffsidePosition = false;
            if (AttackingTeam == HomeTeam) // Home team attacking, higher depth is closer to opponent's goal
            {
                isOffsidePosition = (receiverAbsoluteDepth > secondToLastOpponentAbsoluteDepth) &&
                                    (receiverAbsoluteDepth > ballPlayedAbsoluteDepth);
            }
            else // Away team attacking, lower depth is closer to opponent's (Home) goal
            {
                isOffsidePosition = (receiverAbsoluteDepth < secondToLastOpponentAbsoluteDepth) &&
                                    (receiverAbsoluteDepth < ballPlayedAbsoluteDepth);
            }

            if (isOffsidePosition)
            {
                //LogMessage("OFFSIDE CALLED!");
                //LogMessage(string.Format("Passer: {0}, Receiver: {1} (Zone: {2}, Depth: {3})",
                //                           passer.fullName, receiver.fullName, actualReceiverZone, receiverAbsoluteDepth));
                //LogMessage(string.Format("Second-to-last opponent: {0} (Zone: {1}, Depth: {2})",
                //                           secondToLastOpponent.fullName, secondToLastOpponent.CurrentZone, secondToLastOpponentAbsoluteDepth));
                //LogMessage(string.Format("Ball played from Zone: {0} (Depth: {1})", ballPlayedZone, ballPlayedAbsoluteDepth));

                //string comparisonOperator = AttackingTeam == homeTeam ? ">" : "<";
                //LogMessage(string.Format("Condition: (Receiver {0} {1} Opponent {2}) && (Receiver {3} {1} Ball {4})",
                //                           receiverAbsoluteDepth, comparisonOperator, secondToLastOpponentAbsoluteDepth,
                //                           receiverAbsoluteDepth, ballPlayedAbsoluteDepth));
                //LogMessage(Environment.NewLine);

                return true;
            }

            return false;
        }

        /// <summary>
        /// Determines movement for players involved in a 'CrowdTheBox' routine.
        /// Prioritizes players with heading/jumping ability into central dangerous zones.
        /// </summary>
        private Enums.PitchZone DetermineMovementForCrowdTheBox(Player player, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DetermineMovementForCrowdTheBox: player:{0},attackingTeam:{1},defendingTeam:{2}",
            //    player.position, attackingTeam.Name, defendingTeam.Name));


            bool isAttackingTeamHome = (attackingTeam == HomeTeam);
            Enums.PitchZone preferredZone = Enums.PitchZone.None;
            double bestScore = -1.0;

            HashSet<Enums.PitchZone> uniqueCandidateZones = new HashSet<Enums.PitchZone>();

            // Most dangerous central areas
            uniqueCandidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home);
            uniqueCandidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home);

            // Near/Far Post areas for crosses
            AddNonNoneZone(GetNearPostZone(CurrentBallZone, isAttackingTeamHome), ref uniqueCandidateZones);
            AddNonNoneZone(GetFarPostZone(CurrentBallZone, isAttackingTeamHome), ref uniqueCandidateZones);

            // Edge of penalty area for cutbacks or second balls
            AddNonNoneZone(GetZoneOnEdgeOfPenaltyArea(isAttackingTeamHome, true), ref uniqueCandidateZones);
            AddNonNoneZone(GetZoneOnEdgeOfPenaltyArea(isAttackingTeamHome, false), ref uniqueCandidateZones);

            List<Enums.PitchZone> candidateZones = new List<Enums.PitchZone>(uniqueCandidateZones);

            foreach (var targetZone in candidateZones)
            {
                double currentZoneScore = 0;

                // Higher score for players with aerial ability and good positioning/off-the-ball
                currentZoneScore += player.trueRating.HeaderForGameCalculations * 0.3;
                currentZoneScore += player.trueRating.JumpingForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.PositioningForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.StrengthForGameCalculations * 0.1;
                currentZoneScore += player.trueRating.VisionForGameCalculations * 0.1;

                // Bonus for being in the most central, dangerous zones
                if (targetZone == (isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home)) currentZoneScore += 20;
                else if (targetZone == (isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home)) currentZoneScore += 10;

                // Penalty for offside (less strict than through-ball, but still important)
                if (IsLikelyOffsideFromFreeKick(targetZone, attackingTeam, defendingTeam))
                {
                    currentZoneScore -= 100;
                }

                int defendersInZone = CountDefendersInZone(targetZone, defendingTeam);
                currentZoneScore -= defendersInZone * 5;

                // Bias towards current position if no better option, or if player is already well-positioned
                if (targetZone == player.CurrentZone)
                {
                    currentZoneScore += 1;
                }

                if (currentZoneScore > bestScore)
                {
                    bestScore = currentZoneScore;
                    preferredZone = targetZone;
                }
            }

            if (preferredZone == Enums.PitchZone.None || bestScore < 0)
            {
                return GetZoneForPlayerInFormation(player.Position, attackingTeam.CurrentFormation, isAttackingTeamHome);
            }

            return preferredZone;
        }

        /// <summary>
        /// Determines movement for players making a 'ThroughBallRun'.
        /// Prioritizes fast players with good off-the-ball movement into channels behind defenders.
        /// </summary>
        private Enums.PitchZone DetermineMovementForThroughBallRun(Player player, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DetermineMovementForThroughBallRun: player:{0},attackingTeam:{1},defendingTeam:{2}",
            //    player.position, attackingTeam.Name, defendingTeam.Name));


            bool isAttackingTeamHome = (attackingTeam == HomeTeam);
            Enums.PitchZone preferredZone = Enums.PitchZone.None;
            double bestScore = -1.0;

            HashSet<Enums.PitchZone> candidateZones = new HashSet<Enums.PitchZone>(); // Initialize with capacity

            if (isAttackingTeamHome)
            {
                candidateZones.Add(Enums.PitchZone.PenaltyArea_Away);
                candidateZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                candidateZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                candidateZones.Add(Enums.PitchZone.GoalkeeperArea_Away);
            }
            else
            {
                candidateZones.Add(Enums.PitchZone.PenaltyArea_Home);
                candidateZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                candidateZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                candidateZones.Add(Enums.PitchZone.GoalkeeperArea_Home);
            }

            List<Enums.PitchZone> resultCandidateZones = new List<Enums.PitchZone>(candidateZones);

            foreach (var targetZone in resultCandidateZones)
            {
                double currentZoneScore = 0;

                // Scoring for channel runners
                currentZoneScore += player.trueRating.PaceForGameCalculations * 0.3;
                currentZoneScore += player.trueRating.AccelerationForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.PositioningForGameCalculations * 0.3;
                currentZoneScore += player.trueRating.AgilityForGameCalculations * 0.1;
                currentZoneScore += player.trueRating.FinishingForGameCalculations * 0.1;

                // Bonus for moving into a zone with fewer defenders
                //currentZoneScore += (5 - CountDefendersInZone(targetZone, defendingTeam)) * 10;

                // Critical penalty for offside
                if (IsLikelyOffsideFromFreeKick(targetZone, attackingTeam, defendingTeam))
                {
                    currentZoneScore -= 500; // Very heavy penalty
                }

                // Bias towards forward movement
                currentZoneScore += (GetZoneForwardValue(targetZone, isAttackingTeamHome) - GetZoneForwardValue(player.CurrentZone, isAttackingTeamHome)) * 5;

                // Consider player's vision/passing ability if they might receive and immediately pass
                if (player.trueRating.VisionForGameCalculations > 60 && player.trueRating.PassingForGameCalculations > 60)
                {
                    currentZoneScore += 5; // Small bonus for being able to continue the attack
                }

                if (currentZoneScore > bestScore)
                {
                    bestScore = currentZoneScore;
                    preferredZone = targetZone;
                }
            }

            if (preferredZone == Enums.PitchZone.None || bestScore < 0)
            {
                // Fallback to default formation position if no ideal run zone is found or score is negative (e.g., always offside)
                return GetZoneForPlayerInFormation(player.Position, attackingTeam.CurrentFormation, isAttackingTeamHome);
            }

            return preferredZone;
        }

        // Add this method to your Game.cs class
        private bool IsBallHolderUnderPressure(Player ballHolder)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallHolderUnderPressure: ballHolder:{0}",
            //    ballHolder.position));


            if (ballHolder == null)
            {
                return false;
            }

            Team opposingTeam = (ballHolder.Team == HomeTeam) ? AwayTeam : HomeTeam;
            bool isBallHolderHomeTeam = (ballHolder.Team == HomeTeam);

            // Get zones adjacent to the ball holder's current zone
            // Note: GetAdjacentZones needs to be provided earlier as well, if not present.
            List<Enums.PitchZone> adjacentZones = GetAdjacentZones(ballHolder.CurrentZone, isBallHolderHomeTeam).ToList();

            foreach (Player opponent in opposingTeam.AvailableOnFieldOutfielders)
            {
                if (!opponent.IsAvailable) continue;

                // Check if an opponent is in the same zone or an adjacent zone to the ball holder.
                if (opponent.CurrentZone == ballHolder.CurrentZone || adjacentZones.Contains(opponent.CurrentZone))
                {
                    return true;
                }
            }
            return false;
        }

        // Determines if a given zone is considered 'dangerous' for the specified team
        // (e.g., attacking third for the opponent, near their goal).
        private bool IsZoneDangerous(Enums.PitchZone zone, bool isForAttackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsZoneDangerous: zone:{0},isForAttackingTeam:{1}",
            //    zone, isForAttackingTeam));


            int forwardValue = GetZoneForwardValue(zone, isForAttackingTeam);
            return forwardValue >= 7; // Example: Zones 7, 8, 9 might be considered dangerous.
        }

        /// <summary>
        /// Sets a player's current pitch zone.
        /// </summary>
        /// <param name="player">The player whose zone is to be set.</param>
        /// <param name="newZone">The new PitchZone for the player.</param>
        private void SetPlayerZone(Player player, Enums.PitchZone newZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("SetPlayerZone: player:{0},newZone:{1}",
            //    player.position, newZone));


            if (player != null)
            {
                player.CurrentZone = newZone;
            }
        }

        private void RepositionDefender(Player defender, Player ballCarrier, Team defendingTeam, Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("RepositionDefender: defender:{0},ballCarrier:{1},attackingTeam:{2}," +
            //    "defendingTeam:{3},currentBallZone:{4},CurrentBallHolder:{5}",
            //    defender.fullName, ballCarrier.fullName, attackingTeam.Name, defendingTeam.Name, CurrentBallZone, CurrentBallHolder.fullName));
            Enums.PitchZone orig = ballCarrier.CurrentZone;
            if (ballCarrier.CurrentZone == Enums.PitchZone.None)
            {
                int x = 0;
            }
            // This is the player's current best tactical spot based on all priorities *before* considering specific covering for a teammate.
            Enums.PitchZone originalIdealZone = DetermineDefensiveZone(defender, CurrentBallHolder.CurrentZone, defendingTeam);
            if (ballCarrier.CurrentZone == Enums.PitchZone.None)
            {
                int x = 0;
            }
            Enums.PitchZone idealDefensiveZone = originalIdealZone; // Start with this calculated ideal zone

            bool isHomeDefending = (defendingTeam == HomeTeam);

            // --- Decision: Does THIS defender actively press the ball carrier? ---
            // This logic determines if the 'idealDefensiveZone' should be overridden by a direct press.
            bool ballIsInPressingZone = IsBallInPressingZone(ballCarrier.CurrentZone, defendingTeam, isHomeDefending);
            bool playerIsActivelyPressing = false; // Flag to track if THIS defender committed to a press decision

            if (ballIsInPressingZone && defendingTeam.PressingStyle != Enums.PressingStyle.None)
            {
                double playerPressCommitmentChance = (defender.trueRating.DefenseAwarenessForGameCalculations + defender.trueRating.PositioningForGameCalculations) / 2.0;

                switch (defendingTeam.CurrentPressingTrigger)
                {
                    case Enums.PressingTrigger.Conservative:
                        playerPressCommitmentChance *= 0.7;
                        if (!IsAdjacentZone(defender.CurrentZone, ballCarrier.CurrentZone)) { playerPressCommitmentChance -= 20; }
                        break;
                    case Enums.PressingTrigger.Standard:
                        break;
                    case Enums.PressingTrigger.Intense:
                        playerPressCommitmentChance *= 1.3;
                        break;
                }

                if (Dice.d100() < playerPressCommitmentChance)
                {
                    //ShowMessage(string.Format("{0} ({1}) is actively pressing the ball carrier!", defender.fullName, defendingTeam.Name));
                    playerIsActivelyPressing = true; // Set the flag if *this* player decides to press

                    Enums.PitchZone targetPressZone = ballCarrier.CurrentZone;
                    // Lateral adjustments for FullBack/Winger/CenterBack when pressing
                    if (defender.Role == Enums.PlayerRole.FullBack || defender.Role == Enums.PlayerRole.Winger)
                    {
                        ZoneCoordinate defenderCoords = GetZoneCoords(defender.CurrentZone);
                        ZoneCoordinate ballCoords = GetZoneCoords(ballCarrier.CurrentZone);
                        if (defenderCoords.X < ballCoords.X) { targetPressZone = GetLateralZone(targetPressZone, 1, isHomeDefending); }
                        else if (defenderCoords.X > ballCoords.X) { targetPressZone = GetLateralZone(targetPressZone, -1, isHomeDefending); }
                    }
                    else if (defender.Role == Enums.PlayerRole.CenterBack)
                    {
                        ZoneCoordinate ballCarrierCoords = GetZoneCoords(ballCarrier.CurrentZone);
                        if (ballCarrierCoords.X == 1 || ballCarrierCoords.X == 3)
                        {
                            if (Math.Abs(GetZoneCoords(defender.CurrentZone).X - ballCarrierCoords.X) <= 1) { targetPressZone = ballCarrier.CurrentZone; }
                            else { targetPressZone = GetLateralZone(targetPressZone, 0, isHomeDefending); }
                        }
                    }

                    if (!IsAdjacentZone(defender.CurrentZone, targetPressZone))
                    {
                        idealDefensiveZone = targetPressZone;
                    }

                    //LogEntry(new MatchEntry
                    //{
                    //    Level = LogLevel.Debug,
                    //    EventType = MatchEventType.PlayerPressing,
                    //    PlayerName1 = defender.fullName,
                    //    NumericValue1 = playerPressCommitmentChance,
                    //    TeamName1 = defendingTeam.Name,
                    //    Zone1 = idealDefensiveZone,
                    //    Zone2 = targetPressZone,
                    //    Timestamp = DateTime.Now
                    //});
                }
                else
                {
                    //ShowMessage(string.Format("{0} ({1}) holds position, not actively pressing.", defender.fullName, defendingTeam.Name));
                    //LogEntry(new MatchEntry
                    //{
                    //    Level = LogLevel.Debug,
                    //    EventType = MatchEventType.PlayerNotPressing,
                    //    PlayerName1 = defender.fullName,
                    //    NumericValue1 = playerPressCommitmentChance,
                    //    TeamName1 = defendingTeam.Name,
                    //    Zone1 = idealDefensiveZone,
                    //    Zone2 = ballCarrier.CurrentZone,
                    //    Timestamp = DateTime.Now
                    //});
                    // Player is not actively pressing themselves, will consider covering
                    // idealDefensiveZone remains originalIdealZone for now.
                }
            }
            else // Ball is not in pressing zone or team style is None for this defender's team
            {
                // Player is not actively pressing themselves, will consider covering
                // idealDefensiveZone remains originalIdealZone for now.
            }

            // --- Covering / Support Play Logic (Applies if not actively pressing the ball carrier) ---
            // If THIS defender is NOT pressing the ball carrier, then they should consider covering/supporting.
            if (!playerIsActivelyPressing)
            {
                // Find if any *other* teammate is currently close enough to the ball carrier to be considered "pressing"
                // This inference is based on proximity, as discussed, without needing PlayerAction enum.
                Player teammatePressingBall = defendingTeam.AvailableOnFieldOutfielders.FirstOrDefault(p =>
                    p != defender && // Not self
                    (p.CurrentZone == ballCarrier.CurrentZone || IsAdjacentZone(p.CurrentZone, ballCarrier.CurrentZone)));

                if (teammatePressingBall != null)
                {
                    //ShowMessage(string.Format("{0} ({1}) is looking to provide cover for {2}.", defender.fullName, defendingTeam.Name, teammatePressingBall.fullName));

                    Enums.PitchZone coveringTargetZone = originalIdealZone; // Start with base

                    ZoneCoordinate pressingTeammateCoords = GetZoneCoords(teammatePressingBall.CurrentZone);
                    ZoneCoordinate defenderCoords = GetZoneCoords(defender.CurrentZone);
                    ZoneCoordinate ballCoords = GetZoneCoords(ballCarrier.CurrentZone);

                    Enums.PitchZone potentialCoverZone = ballCarrier.CurrentZone;

                    if (isHomeDefending)
                    {
                        if (pressingTeammateCoords.Y > defenderCoords.Y ||
                            (pressingTeammateCoords.Y == defenderCoords.Y && Math.Abs(pressingTeammateCoords.X - ballCoords.X) > Math.Abs(defenderCoords.X - ballCoords.X)))
                        {
                            potentialCoverZone = GetZoneBehind(teammatePressingBall.CurrentZone, isHomeDefending);
                        }
                    }
                    else // Away team defending (Y decreases towards opponent goal)
                    {
                        if (pressingTeammateCoords.Y < defenderCoords.Y ||
                            (pressingTeammateCoords.Y == defenderCoords.Y && Math.Abs(pressingTeammateCoords.X - ballCoords.X) > Math.Abs(defenderCoords.X - ballCoords.X)))
                        {
                            potentialCoverZone = GetZoneAhead(teammatePressingBall.CurrentZone, isHomeDefending);
                        }
                    }

                    // Replaced `GetZoneForwardValue(defender.BaseZone, isHomeDefending)` with `GetZoneForwardValue(originalIdealZone, isHomeDefending)`
                    // This ensures the covering movement doesn't pull the player too far from their *calculated* original ideal position.
                    if (potentialCoverZone != Enums.PitchZone.None &&
                        GetZoneForwardValue(potentialCoverZone, isHomeDefending) <= GetZoneForwardValue(originalIdealZone, isHomeDefending) + 1 &&
                        CalculateDistance(potentialCoverZone, originalIdealZone) < 3)
                    {
                        idealDefensiveZone = potentialCoverZone;
                    }

                    // Option C: Double Up (if team marking style supports it and dangerous situation)
                    if ((defendingTeam.CurrentMarkingStyle == Enums.MarkingStyle.ManToMan || defendingTeam.CurrentMarkingStyle == Enums.MarkingStyle.Mixed) &&
                        CalculateDistance(defender.CurrentZone, ballCarrier.CurrentZone) <= 2 &&
                        IsZoneDangerous(ballCarrier.CurrentZone, !isHomeDefending) &&
                        defender.Role != Enums.PlayerRole.Goalkeeper)
                    {
                        // This check needs to be more robust if 'MarkedOpponent' isn't explicitly set every time,
                        // but if it is, then this is good. The key is to avoid pulling a defender off a more important mark.
                        // For now, let's keep it as is, assuming MarkedOpponent is reliable.
                        if (defender.MarkedOpponent == null || CalculateDistance(defender.CurrentZone, defender.MarkedOpponent.CurrentZone) > CalculateDistance(defender.CurrentZone, ballCarrier.CurrentZone))
                        {
                            //ShowMessage(string.Format("{0} ({1}) is doubling up on {2}.", defender.fullName, defendingTeam.Name, ballCarrier.fullName));
                            idealDefensiveZone = ballCarrier.CurrentZone;
                        }
                    }
                }
                else
                {
                    // No teammate close enough to be considered "pressing",
                    // so this defender should stick to their original ideal defensive zone (zonal/marking focus)
                    idealDefensiveZone = originalIdealZone;
                }
            }


            // If the defender is already in or very close to their ideal zone (either original or pressing-adjusted), do nothing.
            // This check applies after all adjustments have been made.
            if (defender.CurrentZone == idealDefensiveZone || IsAdjacentZone(defender.CurrentZone, idealDefensiveZone))
            {
                return;
            }

            // Move towards the ideal zone.
            //ShowMessage(string.Format("{0} ({1}) repositions to {2}.", defender.fullName, defendingTeam.Name, idealDefensiveZone));
            SetPlayerZone(defender, idealDefensiveZone);
        }

        private Player FindSecondToLastOpponent(Team defendingTeam, Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("FindSecondToLastOpponent: defendingTeam:{0},attackingTeam:{1}",
            //    defendingTeam.Name, attackingTeam.Name));


            List<Player> allDefendingPlayers = new List<Player>(defendingTeam.AvailableOnFieldPlayers);

            // If there are fewer than 2 defenders (e.g., only a goalkeeper),
            // the offside rule is usually interpreted as the ball setting the line,
            // or sometimes simply no offside can be called. For player movement AI,
            // we need a valid player to reference.
            if (allDefendingPlayers.Count < 2)
            {
                // Fallback: If only one defender (likely GK), return that defender.
                // If no defenders, return null or handle with specific depth (e.g., opponent's goal line).
                // For simplicity here, let's assume at least one defender.
                if (allDefendingPlayers.Count == 1)
                {
                    return allDefendingPlayers[0]; // The only defender available
                }
                return null; // Should ideally not happen in a full 11-a-side game
            }

            // Sort defenders by their absolute pitch depth in ascending order (0 to 6).
            // This means 0 is deepest (their own GK area), 6 is furthest (opponent's GK area).
            allDefendingPlayers.Sort((a, b) =>
            {
                int depthA = GetAbsolutePitchDepth(a.CurrentZone);
                int depthB = GetAbsolutePitchDepth(b.CurrentZone);

                // Robustly handle any remaining -1 depths by pushing them to an extreme end.
                // This ensures the sort doesn't crash and these players don't incorrectly set the line.
                if (depthA == -1) return (depthB == -1) ? 0 : (attackingTeam == HomeTeam ? int.MaxValue : int.MinValue);
                if (depthB == -1) return (depthA == -1) ? 0 : (attackingTeam == HomeTeam ? int.MinValue : int.MaxValue);

                return depthA.CompareTo(depthB); // Sorts from 0 (Home GK Area) to 6 (Away GK Area)
            });

            // After sorting from 0 (deepest for Home team) to 6 (deepest for Away team):
            if (attackingTeam == HomeTeam)
            {
                // Home team is attacking towards higher depths (Away Goal).
                // The second-to-last opponent is the one with the second-highest depth (closest to Away goal).
                // This is at allDefendingPlayers[allDefendingPlayers.Count - 2]
                return allDefendingPlayers[allDefendingPlayers.Count - 2];
            }
            else // AttackingTeam == awayTeam (attacking towards lower depths, Home Goal)
            {
                // Away team is attacking towards lower depths (Home Goal).
                // The second-to-last opponent is the one with the second-lowest depth (closest to the Home Goal).
                // This will be at index 1 of the sorted list (index 0 is the very deepest defender, typically the GK).
                return allDefendingPlayers[1];
            }
        }

        /// <summary>
        /// Determines if a given PitchZone is in 'our' (the playerTeam's) half of the field.
        /// This is crucial for distinguishing defensive vs. offensive roles based on ball location.
        /// </summary>
        private bool IsBallInOurHalfForTeam(Enums.PitchZone zone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInOurHalfForTeam: zone:{0},playerTeam:{1}",
            //    zone, playerTeam.Name));


            if (playerTeam == HomeTeam)
            {
                // For Home team, 'our' half includes HomeDefense and Midfield zones.
                return zone == Enums.PitchZone.HomeDefense_LeftFlank || zone == Enums.PitchZone.HomeDefense_Center ||
                       zone == Enums.PitchZone.HomeDefense_RightFlank ||
                       zone == Enums.PitchZone.Midfield_LeftFlank || zone == Enums.PitchZone.Midfield_Center ||
                       zone == Enums.PitchZone.Midfield_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Home || zone == Enums.PitchZone.GoalkeeperArea_Home ||
                       zone == Enums.PitchZone.KickOffCircle ||
                       zone == Enums.PitchZone.Corner_HomeLeft || zone == Enums.PitchZone.Corner_HomeRight;
            }
            else // Away Team's perspective
            {
                // For Away team, 'our' half includes AwayAttack (which is Home's defense) and Midfield zones.
                return zone == Enums.PitchZone.AwayAttack_LeftFlank || zone == Enums.PitchZone.AwayAttack_Center ||
                       zone == Enums.PitchZone.AwayAttack_RightFlank ||
                       zone == Enums.PitchZone.Midfield_LeftFlank || zone == Enums.PitchZone.Midfield_Center ||
                       zone == Enums.PitchZone.Midfield_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Away || zone == Enums.PitchZone.GoalkeeperArea_Away ||
                       zone == Enums.PitchZone.KickOffCircle ||
                       zone == Enums.PitchZone.Corner_AwayLeft || zone == Enums.PitchZone.Corner_AwayRight;
            }
        }

        /// <summary>
        /// Determines if a given PitchZone is in the 'opponent's' half relative to the playerTeam.
        /// </summary>
        private bool IsBallInOpponentHalfForTeam(Enums.PitchZone zone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInOpponentHalfForTeam: zone:{0},playerTeam:{1}",
            //    zone, playerTeam.Name));


            return !IsBallInOurHalfForTeam(zone, playerTeam); // If not in our half, it's in opponent's.
        }

        /// <summary>
        /// Determines if the ball is in 'opponent's' penalty area for the given team perspective.
        /// </summary>
        private bool IsBallInOpponentPenaltyAreaForTeam(Enums.PitchZone zone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInOpponentPenaltyAreaForTeam: zone:{0},playerTeam:{1}",
            //    zone, playerTeam.Name));


            if (playerTeam == HomeTeam)
            {
                return zone == Enums.PitchZone.PenaltyArea_Away;
            }
            else // Away Team's perspective
            {
                return zone == Enums.PitchZone.PenaltyArea_Home;
            }
        }

        public Enums.PitchZone GetTeamSpecificDefensiveZone(Enums.PitchZone genericDefensiveZone, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetTeamSpecificDefensiveZone: genericDefensiveZone:{0},defendingTeam:{1}",
            //    genericDefensiveZone, defendingTeam.Name));


            // Check if the input zone is one of the generic defensive zones that needs mapping
            bool isGenericDefensiveZone = EnumCache<Enums.PitchZone>.ToString(genericDefensiveZone).StartsWith("DefensivePenaltyArea_") ||
                                          genericDefensiveZone == Enums.PitchZone.Defensive_EdgeOfBox;

            if (!isGenericDefensiveZone)
            {
                // If it's not a generic defensive zone (e.g., Midfield_Center, HomeDefense_LeftFlank),
                // return it as is, because its coordinates are fixed on the pitch.
                return genericDefensiveZone;
            }

            // Now, we know it's a generic defensive zone (e.g., DefensivePenaltyArea_Central)
            // Its coordinate in _zoneCoordinates is set up for the HOME side.
            ZoneCoordinate baseCoords = GetZoneCoords(genericDefensiveZone);

            if (defendingTeam == HomeTeam)
            {
                Enums.PitchZone specificZone = Enums.PitchZone.None;
                if (!_coordsToZoneMap.TryGetValue(baseCoords, out specificZone))
                {
                    specificZone = Enums.PitchZone.None;
                }
                // If the home team is defending, the generic zone's coordinate is directly applicable.
                // We just need to ensure the _coordsToZoneMap can find it and return the correct enum.
                return specificZone;
            }
            else // Away team is defending, so we need the mirrored coordinate/zone.
            {
                // Calculate the mirrored Y-coordinate.
                // This mapping depends on your pitch's symmetry.
                // Based on your coordinates:
                // Y = -1 (GoalkeeperArea_Home) mirrors to Y = 5 (GoalkeeperArea_Away)
                // Y = 0 (PenaltyArea_Home) mirrors to Y = 4 (PenaltyArea_Away)
                // Y = 1 (HomeDefense_Center / Defensive_EdgeOfBox for Home) mirrors to Y = 3 (AwayAttack_Center / Defensive_EdgeOfBox for Away)

                int mirroredY;
                if (baseCoords.Y == -1) mirroredY = 5;
                else if (baseCoords.Y == 0) mirroredY = 4;
                else if (baseCoords.Y == 1) mirroredY = 3;
                else
                {
                    // This should not happen for the generic defensive zones if they are only at Home end.
                    // But as a fallback, return the original generic zone or None.
                    return Enums.PitchZone.None;
                }

                ZoneCoordinate mirroredCoords = new ZoneCoordinate(baseCoords.X, mirroredY);

                Enums.PitchZone specificZone = Enums.PitchZone.None;
                if (!_coordsToZoneMap.TryGetValue(mirroredCoords, out specificZone))
                {
                    specificZone = Enums.PitchZone.None;
                }
                // If the home team is defending, the generic zone's coordinate is directly applicable.
                // We just need to ensure the _coordsToZoneMap can find it and return the correct enum.
                return specificZone;
            }
        }

        List<Player> GetPotentialTargets(Team attackingTeam, Player excludePlayer, IEnumerable<Enums.Positions> preferredPlayerRoles)
        {
            // Logging is good, keep it.

            List<Player> potentialTargets = new List<Player>();
            bool hasPreferredRoles = preferredPlayerRoles != null && preferredPlayerRoles.Any();
            HashSet<Enums.Positions> preferredRolesSet = hasPreferredRoles ? new HashSet<Enums.Positions>(preferredPlayerRoles) : null;

            // --- Attempt 1: Strict Match (Current Logic) ---
            foreach (Player player in attackingTeam.AvailableOnFieldOutfielders)
            {
                if (player != excludePlayer &&
                    (!hasPreferredRoles || preferredRolesSet.Contains(player.Position)))
                {
                    potentialTargets.Add(player);
                }
            }

            // --- Fallback 1: If no targets found with preferred roles, find ANY available outfield player ---
            if (potentialTargets.Count == 0 && hasPreferredRoles) // Only if preferred roles were specified and found no match
            {
                //ShowMessage("GetPotentialTargets: No players found for preferred roles. Broadening search.");
                foreach (Player player in attackingTeam.AvailableOnFieldOutfielders)
                {
                    if (player != excludePlayer)
                    {
                        potentialTargets.Add(player);
                    }
                }
            }

            // --- Fallback 2: (Less likely, but for extreme cases) ---
            // If still no players (e.g., almost everyone sent off, or excludePlayer was the last one)
            // You could consider including a slightly injured player (with a penalty) or a less preferred role
            // For now, let's assume if it's empty after Fallback 1, it's genuinely no one available.

            //ShowMessage("GetPotentialTargets returning " + potentialTargets.Count); // Add a log for the final count
            return potentialTargets;
        }

        /// <summary>
        /// Finds the most suitable attacking player to fulfill a specific set piece role for a routine.
        /// </summary>
        /// <param name="attackingTeam">The team looking for a player.</param>
        /// <param name="defendingTeam">The opposing team (needed for marking checks).</param>
        /// <param name="preferredPlayerRoles">A list of preferred Enums.PlayerRole for this set piece role (e.g., Striker, CenterBack for TargetMan). Can be null.</param>
        /// <param name="targetConceptualZone">The conceptual zone where this player should be positioned or target.</param>
        /// <param name="excludePlayer">A player to exclude from consideration (e.g., the corner taker).</param>
        /// <param name="preferUnmarked">If true, heavily penalize marked players. Crucial for short passes.</param>
        /// <param name="deliveryType">The type of delivery this player is expected to receive (e.g., ShortPass, Lofted, Driven).</param> // NEW PARAMETER
        /// <returns>The best suitable Player, or null if none found.</returns>
        private Player FindBestAttackerForRoutineRole(
            Team attackingTeam,
            Team defendingTeam,
            List<Enums.Positions> preferredPlayerRoles,
            Enums.ConceptualSetPieceZone targetConceptualZone,
            Player excludePlayer,
            bool preferUnmarked,
            Enums.CornerDeliveryType? cornerDeliveryType = null,
            Enums.FreeKickDeliveryType? freeKickDeliveryType = null,
            Enums.ThrowInDeliveryType? throwInDeliveryType = null // NEW OPTIONAL PARAMETER
)
        {
            string ep = "null";
            if (excludePlayer != null)
            {
                ep = excludePlayer.position.ToString();
            }
            //LoggingStuff.LogMethodCall(string.Format("FindBestAttackerForRoutineRole: attackingTeam:{0},defendingTeam:{1}," +
            //    "preferredPlayerRoles:{2},targetConceptualZone:{3},excludePlayer:{4},preferUnmarked:{5}," +
            //    "cornerDeliveryType:{6},freeKickDeliveryType:{7},throwInDeliveryType:{8}",
            //    attackingTeam.Name, defendingTeam.Name,
            //    string.Join(",", preferredPlayerRoles),
            //    targetConceptualZone,
            //    ep,
            //    preferUnmarked,
            //    cornerDeliveryType.HasValue ? cornerDeliveryType.Value.ToString() : "null",
            //    freeKickDeliveryType.HasValue ? freeKickDeliveryType.Value.ToString() : "null",
            //    throwInDeliveryType.HasValue ? throwInDeliveryType.Value.ToString() : "null"));


            // Map the conceptual zone to a concrete PitchZone
            Enums.PitchZone actualTargetPitchZone = MapConceptualToPitchZone(
                targetConceptualZone,
                attackingTeam == HomeTeam,
                GetFlankOfZone(CurrentBallZone)
            );

            List<Player> potentialTargets = GetPotentialTargets(attackingTeam, excludePlayer, preferredPlayerRoles);

            Player bestTarget = null;
            double bestScore = -1.0;

            foreach (var player in potentialTargets)
            {
                // Set the player's simulated target zone based on the routine.
                player.SimulatedSetPieceZone = actualTargetPitchZone;

                // Calculate initial score based on proximity to target zone
                int distanceToTargetZone = CalculateDistance(player.CurrentZone, player.SimulatedSetPieceZone); // Use simulated zone
                double score = 100.0 - (distanceToTargetZone * 5.0);

                // Adjust score based on marking status
                if (IsPlayerHeavilyMarked(player, defendingTeam, player.SimulatedSetPieceZone)) // Pass simulated zone to marking check
                {
                    if (preferUnmarked)
                    {
                        score -= 50.0;
                        //ShowMessage(string.Format("    {0} is heavily marked (score -50).", player.fullName));
                    }
                    else
                    {
                        score -= 10.0;
                        //ShowMessage(string.Format("    {0} is marked (score -10).", player.fullName));
                    }
                }

                // --- Differentiate attribute bonuses based on deliveryType (now handles all three) ---
                if (cornerDeliveryType == Enums.CornerDeliveryType.ShortPass ||
                    freeKickDeliveryType == Enums.FreeKickDeliveryType.ShortPass ||
                    throwInDeliveryType == Enums.ThrowInDeliveryType.ShortThrow) // NEW: Include ThrowInDeliveryType.ShortThrow
                {
                    // Prioritize attributes for receiving and retaining a short pass
                    score += player.trueRating.BallControlForGameCalculations * 0.4; // Corrected from Finishing to BallControl
                    score += player.trueRating.PassingForGameCalculations * 0.2;
                    score += player.trueRating.ComposureForGameCalculations * 0.2;
                    score += player.trueRating.AgilityForGameCalculations * 0.1;
                    //ShowMessage(string.Format("    {0} (Short Pass attributes applied).", player.fullName));
                }
                else if (cornerDeliveryType.HasValue ||
                         freeKickDeliveryType == Enums.FreeKickDeliveryType.LoftedPassIntoBox ||
                         throwInDeliveryType == Enums.ThrowInDeliveryType.LongThrowIntoBox) // NEW: Include ThrowInDeliveryType.LongThrowIntoBox
                {
                    // Prioritize attributes for winning aerial duels or receiving crosses/lofted balls
                    score += player.trueRating.JumpingForGameCalculations * 0.3;
                    score += player.trueRating.HeaderForGameCalculations * 0.3;
                    score += player.trueRating.PositioningForGameCalculations * 0.2;
                    score += player.trueRating.StrengthForGameCalculations * 0.1;
                    //ShowMessage(string.Format("    {0} (Cross/Lofted/Long Throw attributes applied).", player.fullName));
                }
                // Add more else if blocks for other specific delivery types if their attribute needs differ

                bool isSetPiece = (CurrentMatchState == Enums.MatchState.GoalKick ||
                       CurrentMatchState == Enums.MatchState.CornerKick ||
                       CurrentMatchState == Enums.MatchState.ThrowIn || CurrentMatchState == MatchState.FreeKick ||
                       CurrentMatchState == MatchState.FreeKick_Indirect);
                // Offside check - crucial here for selection!
                if (IsOffside(player, defendingTeam, player.SimulatedSetPieceZone, isSetPiece)) // Assuming IsOffside can take a target zone
                {
                    score -= 1000.0; // Huge penalty for offside
                    //ShowMessage(string.Format("    {0} would be OFFSIDE in {1} (score -1000).", player.fullName, player.SimulatedSetPieceZone));
                }

                //ShowMessage(string.Format("    {0} (Role: {1}, Target Zone: {2}) score for routine role: {3:F2}", player.fullName, player.Position, player.SimulatedSetPieceZone, score));
                if (bestTarget == null)
                {
                    bestTarget = player;
                    bestScore = score;
                }
                else
                {
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestTarget = player;
                    }
                }
            }

            // If no potential targets found by GetPotentialTargets, pick the least worst player
            // This is the safety net to ensure we don't return null unless truly no outfield players
            if (potentialTargets.Count == 0)
            {
                //ShowMessage("FindBestAttackerForRoutineRole: GetPotentialTargets returned no players. Selecting a random fallback.");
                // Find *any* active outfield player not excluded.
                // This assumes attackingTeam.OnFieldOutfielders is never truly empty unless the team is completely decimated.
                Player fallbackPlayer = attackingTeam.AvailableOnFieldOutfielders.FirstOrDefault(p => p != excludePlayer);

                if (fallbackPlayer != null)
                {
                    //ShowMessage("FindBestAttackerForRoutineRole: Falling back to " + fallbackPlayer.fullName + ".");
                    return fallbackPlayer; // Return this fallback, even if not ideal.
                }
                else
                {
                    throw new Exception("FindBestAttackerForRoutineRole: No fallback player could be found. Returning null.");
                }
            }

            return bestTarget;
        }

        private bool IsPlayerHeavilyMarked(Player attacker, Team defendingTeam, Enums.PitchZone targetZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsPlayerHeavilyMarked: attacker:{0},defendingTeam:{1},targetZone:{2}",
            //    attacker.position, defendingTeam.Name, targetZone));


            // Check if any defender is explicitly marking this attacker
            if (defendingTeam.AvailableOnFieldOutfielders.Any(d => d.MarkedOpponent == attacker))
            {
                return true;
            }

            // Check for defenders in the immediate vicinity of the targetZone
            // You'll need a way to get "neighboring" zones or check exact positions if available.
            // For now, a simple count in the target zone:
            int defendersInTargetOrAdjacent = CountDefendersInZone(targetZone, defendingTeam);
            // You might also check adjacent zones to targetZone for even better marking logic
            // e.g., GetAdjacentZones(targetZone) and count defenders there too.

            if (defendersInTargetOrAdjacent >= 2) // Arbitrary threshold for "heavily marked"
            {
                return true;
            }

            return false;
        }

        /// <summary>
        /// Determines if a player is currently considered "heavily marked" by an opponent.
        /// This is a simplified heuristic for now.
        /// </summary>
        /// <param name="player">The player to check for marking.</param>
        /// <param name="opposingTeam">The team whose players might be marking.</param>
        /// <returns>True if heavily marked, false otherwise.</returns>
        public bool IsPlayerHeavilyMarked(Player player, Team opposingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsPlayerHeavilyMarked: player:{0},opposingTeam:{1}",
            //    player.position, opposingTeam.Name));


            // A simplified definition: if there's an opposing player within a very close zone distance, AND they have a decent Marking attribute.
            double veryCloseDistanceThreshold = 0.8; // E.g., almost in the same zone or immediately adjacent, considering smaller zone size.
            double minimumMarkingSkill = 60; // Defenders need at least this much marking to be considered effective markers.

            foreach (var defender in opposingTeam.AvailableOnFieldOutfielders)
            {
                // Exclude goalkeepers, injured, or sent-off defenders.
                if (defender.IsInjured || defender.isSentOff || defender.Position == Enums.Positions.Goalkeeper)
                {
                    continue;
                }

                // If the defender has sufficient marking skill
                if (defender.trueRating.DefendingForGameCalculations >= minimumMarkingSkill)
                {
                    double distance = CalculateDistance(player.CurrentZone, defender.CurrentZone);

                    if (distance <= veryCloseDistanceThreshold)
                    {
                        // You could add more sophisticated checks here:
                        // - Is the defender actively attempting to mark this player (e.g., ManMarkingTarget == player)?
                        // - Is the defender facing the player?
                        // - Comparison of defender's Marking vs. player's OffTheBall/Dribbling.
                        return true; // Yes, this player is heavily marked.
                    }
                }
            }
            return false; // No heavy marking found.
        }

        /// <summary>
        /// Finds the nearest available teammate to a given player.
        /// </summary>
        /// <param name="player">The player from whom to find the nearest teammate.</param>
        /// <param name="team">The team to search within.</param>
        /// <param name="excludeGoalkeeper">If true, goalkeepers are excluded from the search.</param>
        /// <param name="maxDistanceInZones">Maximum distance in zones to search. Set to 0 or negative for no limit.</param>
        /// <param name="preferUnmarked">If true, heavily penalize marked players.</param>
        /// <returns>The nearest teammate, or null if none found within criteria.</returns>
        public Player FindNearestTeammate(Player player, Team team, bool excludeGoalkeeper, int maxDistanceInZones = 0, bool preferUnmarked = false)
        {
            //LoggingStuff.LogMethodCall(string.Format("FindNearestTeammate: player:{0},team:{1},excludeGoalkeeper:{2}," +
            //    "maxDistanceInZones:{3},preferUnmarked:{4}",
            //    player.position, team.Name, excludeGoalkeeper, maxDistanceInZones, preferUnmarked));


            if (player == null || team == null)
            {
                return null;
            }

            Player nearestTeammate = null;
            double minDistanceScore = double.MaxValue; // Use a score that combines distance and other factors

            foreach (var teammate in team.AvailableOnFieldOutfielders)
            {
                if (teammate == player || teammate.IsInjured || teammate.isSentOff)
                {
                    continue; // Skip self, injured, or sent off players
                }

                if (excludeGoalkeeper && teammate.Position == Enums.Positions.Goalkeeper)
                {
                    continue; // Skip goalkeeper if excluded
                }

                int distance = CalculateDistance(player.CurrentZone, teammate.CurrentZone);

                if (maxDistanceInZones > 0 && distance > maxDistanceInZones)
                {
                    continue; // Skip if beyond max distance
                }

                // Calculate a score: lower is better
                double currentScore = distance;

                // Apply penalty for marked players if unmarked is preferred
                if (preferUnmarked && IsPlayerHeavilyMarked(teammate, DefendingTeam))
                {
                    currentScore += 100; // Large penalty for being marked
                }

                // Add small bonus for players with good off-the-ball movement
                currentScore -= (teammate.trueRating.PositioningForGameCalculations * 0.1);

                if (currentScore < minDistanceScore)
                {
                    minDistanceScore = currentScore;
                    nearestTeammate = teammate;
                }
            }

            return nearestTeammate;
        }

        /// <summary>
        /// Finds the conceptual "nearest" and most effective defender to an attacking player.
        /// This method leverages GetPlayerZone and defender attributes.
        /// </summary>
        /// <param name="attackingPlayer">The player with the ball or being marked.</param>
        /// <param name="defendingTeam">The team looking for a defender.</param>
        /// <param name="currentBallZone">The current zone of the ball.</param>
        /// <returns>The Player who is conceptually the nearest effective defender, or null if none found.</returns>
        public Player FindNearestDefender(Player attackingPlayer, Team defendingTeam, Enums.PitchZone currentBallZone)
        {
            Player bestDefender = null;
            double maxScore = -1.0; // Initialize with a value lower than any possible valid score

            Enums.PitchHalfType currentBallHalf = _zoneHalfMap[currentBallZone];

            foreach (Player defender in defendingTeam.AvailableOnFieldPlayers)
            {
                if (defender.isSentOff) continue;

                // Use Player.CurrentZone directly if it's updated as expected
                Enums.PitchZone defenderZone = GetPlayerZone(defender); // Or just defender.CurrentZone;

                // Goalkeeper check optimization
                if (defender.Position == Enums.Positions.Goalkeeper)
                {
                    // GK is only relevant if the ball is in their own penalty/goalkeeper area
                    // We can use the pre-calculated half type for the defending team's area
                    if (!((defendingTeam == HomeTeam && (currentBallZone == Enums.PitchZone.PenaltyArea_Home || currentBallZone == Enums.PitchZone.GoalkeeperArea_Home)) ||
                          (defendingTeam == AwayTeam && (currentBallZone == Enums.PitchZone.PenaltyArea_Away || currentBallZone == Enums.PitchZone.GoalkeeperArea_Away))))
                    {
                        continue; // Skip GK if ball is not in their area
                    }
                }

                double currentDefenderScore = 0.0;

                // 1. Proximity/Relevance to CurrentBallZone (Optimized string checks)
                if (defenderZone == currentBallZone)
                {
                    currentDefenderScore += 100.0; // Very high bonus for being in the same zone as the ball
                }
                else if (IsAdjacentZone(defenderZone, currentBallZone)) // Assuming IsAdjacentZone is efficient
                {
                    currentDefenderScore += 50.0; // Moderate bonus for being in an adjacent zone
                }
                else // Smallest bonus for being in the same general half (using pre-calculated map)
                {
                    // Retrieve the half type for the defender's current zone
                    Enums.PitchHalfType defenderHalf = _zoneHalfMap[defenderZone];

                    if (currentBallHalf == defenderHalf) // Direct enum comparison is fast
                    {
                        currentDefenderScore += 10.0;
                    }
                }

                // 2. Defender Attributes
                currentDefenderScore += (defender.trueRating.PositioningForGameCalculations * 0.4);
                currentDefenderScore += (defender.trueRating.DefenseAwarenessForGameCalculations * 0.3);
                currentDefenderScore += (defender.trueRating.PaceForGameCalculations * 0.2);
                currentDefenderScore += (defender.trueRating.DefendingForGameCalculations * 0.1);

                // Ensure a minimum score to avoid division by zero or negative scores in ranking
                currentDefenderScore = Math.Max(0.1, currentDefenderScore);

                // Directly track the best defender instead of adding to a list and sorting
                if (currentDefenderScore > maxScore)
                {
                    maxScore = currentDefenderScore;
                    bestDefender = defender;
                }
            }

            return bestDefender; // Returns null if no eligible defenders were found (maxScore remains -1.0)
        }

        /// <summary>
        /// Determines the size of the defensive wall based on the distance to goal.
        /// </summary>
        /// <param name="distanceToGoal">The calculated distance from the free kick to the goal.</param>
        /// <returns>The number of players that should form the wall.</returns>
        private int GetWallSize(float distanceToGoal)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetWallSize: distanceToGoal:{0}", distanceToGoal));


            if (distanceToGoal <= 1.0f) return 6; // Very close (inside/near penalty area)
            if (distanceToGoal <= 2.5f) return 4; // Close (attacking third)
            if (distanceToGoal <= 4.0f) return 2; // Medium range (midfield closer to attacking third)
            return 0; // Too far for a direct wall
        }

        /// <summary>
        /// Determines the PitchZone where the defensive wall should form.
        /// The wall forms in the defending team's defensive half, aligning with the free kick's flank.
        /// </summary>
        /// <param name="freeKickZone">The zone where the free kick is taken.</param>
        /// <param name="isAttackingHomeGoal">True if the attacking team is attacking the home goal (meaning defending team is Home).</param>
        /// <returns>The PitchZone for the defensive wall.</returns>
        private Enums.PitchZone GetWallZone(Enums.PitchZone freeKickZone, bool isAttackingHomeGoal)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetWallZone: freeKickZone:{0},isAttackingHomeGoal:{1}",
            //    freeKickZone, isAttackingHomeGoal));


            string flank = GetZoneFlank(freeKickZone);

            // If attacking team is Home, defending team is Away. Wall forms in Away's defensive half (AwayAttack_ zones).
            if (isAttackingHomeGoal)
            {
                switch (flank)
                {
                    case "Left": return Enums.PitchZone.AwayAttack_LeftFlank;
                    case "Right": return Enums.PitchZone.AwayAttack_RightFlank;
                    case "Center":
                    default: return Enums.PitchZone.AwayAttack_Center;
                }
            }
            // If attacking team is Away, defending team is Home. Wall forms in Home's defensive half (HomeDefense_ zones).
            else
            {
                switch (flank)
                {
                    case "Left": return Enums.PitchZone.HomeDefense_LeftFlank;
                    case "Right": return Enums.PitchZone.HomeDefense_RightFlank;
                    case "Center":
                    default: return Enums.PitchZone.HomeDefense_Center;
                }
            }
        }

        private void PositionPlayersForFreeKick(Team attackingTeam, Team defendingTeam, Enums.PitchZone freeKickZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("PositionPlayersForFreeKick: attackingTeam:{0},defendingTeam:{1},freeKickZone:{2}",
            //    attackingTeam.Name, defendingTeam.Name, freeKickZone));


            //ShowMessage("Positioning players for free kick at " + freeKickZone + ". Attacking team: " + attackingTeam.Name + ", Defending team: " + defendingTeam.Name + ".");

            // Reset all player zones to their default formation positions as a baseline for set-piece adjustments.
            foreach (var team in new[] { attackingTeam, defendingTeam })
            {
                foreach (var player in team.AvailableOnFieldPlayers)
                {
                    if (player.Position == Enums.Positions.Goalkeeper)
                    {
                        player.CurrentZone = (team == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    }
                    else
                    {
                        player.CurrentZone = GetZoneForPlayerInFormation(player.Position, team.CurrentFormation, team == HomeTeam);
                    }
                    // IMPORTANT: Clear any previous man-marking assignments at the start of set-piece positioning
                    player.MarkedOpponent = null;
                }
            }

            // Determine if it's an Indirect Free Kick and if it's inside the penalty area for the defending team
            bool isHomeDefendingTeam = (defendingTeam == HomeTeam); // Renamed for clarity to avoid conflict with method parameter if 'isHomeDefending' was passed
            // Use the global CurrentMatchState set at the beginning of the FreeKickHandler
            bool isIndirectFKInPenaltyArea = (CurrentMatchState == Enums.MatchState.FreeKick_Indirect &&
                                              IsBallInPenaltyArea(freeKickZone, attackingTeam)); // IsBallInPenaltyArea should handle this based on attacking team's perspective

            List<Player> availableDefenders = new List<Player>();
            foreach (Player player in defendingTeam.AvailableOnFieldOutfielders)
            {
                availableDefenders.Add(player);
            }

            // 1. Defending Team: Create the Wall (Non-Goalkeepers only)
            float distanceToGoal = CalculateDistanceToGoal(freeKickZone, attackingTeam == HomeTeam);
            int wallSize = GetWallSize(distanceToGoal);

            //ShowMessage("Distance to goal for free kick: " + distanceToGoal + ". Wall size decided: " + wallSize + " players.");

            List<Player> wallPlayers = new List<Player>();
            List<Player> goalLineDefenders = new List<Player>();

            if (wallSize > 0)
            {
                wallPlayers = new List<Player>(wallSize);
                List<Player> wallCandidates = new List<Player>();

                foreach (Player player in availableDefenders)
                {
                    if (WallPositions.Contains(player.Position))
                    {
                        wallCandidates.Add(player);
                    }
                }

                wallCandidates.Sort((a, b) =>
                    (b.trueRating.DefendingForGameCalculations + b.trueRating.StrengthForGameCalculations)
                    .CompareTo(a.trueRating.DefendingForGameCalculations + a.trueRating.StrengthForGameCalculations));

                for (int i = 0; i < Math.Min(wallSize, wallCandidates.Count); i++)
                {
                    wallPlayers.Add(wallCandidates[i]);
                }

                // Use a more specific zone for the wall, or a general penalty area depending on logic
                // For a wall, they'd be just outside the penalty area, or within the 'Defensive_EdgeOfBox'
                // We'll use Defensive_EdgeOfBox and rely on GetTeamSpecificDefensiveZone to map it.
                Enums.PitchZone baseWallZone = Enums.PitchZone.Defensive_EdgeOfBox;
                Enums.PitchZone actualWallZone = GetTeamSpecificDefensiveZone(baseWallZone, defendingTeam);

                foreach (var player in wallPlayers)
                {
                    player.CurrentZone = actualWallZone; // All wall players go to the same zone initially
                    availableDefenders.Remove(player); // Remove from available defenders pool
                    //ShowMessage("Defensive wall: " + player.fullName + " (" + player.Position + ") positioned at " + player.CurrentZone + ".");
                }
            }
            else
            {
                //ShowMessage("No wall formed for this free kick (too far or no direct threat).");
            }

            // --- Goal Line Defenders for Indirect Free Kicks inside the penalty area ---
            if (isIndirectFKInPenaltyArea)
            {
                //ShowMessage("Indirect Free Kick inside penalty area: positioning players on goal line.");
                // Find defenders not already in the wall, and suitable for goal line.
                goalLineDefenders = availableDefenders.FindAll(p =>
                    p.Position == Enums.Positions.CenterBack ||
                    p.Position == Enums.Positions.LeftBack ||
                    p.Position == Enums.Positions.RightBack);

                goalLineDefenders.Sort((a, b) =>
                    b.trueRating.DefendingForGameCalculations.CompareTo(a.trueRating.DefendingForGameCalculations));

                if (goalLineDefenders.Count > 2)
                {
                    goalLineDefenders.RemoveRange(2, goalLineDefenders.Count - 2);
                }

                // Use specific penalty area zones for more granular placement
                Enums.PitchZone baseGoalLineCentralZone = Enums.PitchZone.DefensivePenaltyArea_Central;
                Enums.PitchZone baseGoalLineLeftNearPost = Enums.PitchZone.DefensivePenaltyArea_LeftNearPost;
                Enums.PitchZone baseGoalLineRightNearPost = Enums.PitchZone.DefensivePenaltyArea_RightNearPost;

                // Resolve to actual physical zones based on defending team
                Enums.PitchZone actualGoalLineCentralZone = GetTeamSpecificDefensiveZone(baseGoalLineCentralZone, defendingTeam);
                Enums.PitchZone actualGoalLineLeftNearPost = GetTeamSpecificDefensiveZone(baseGoalLineLeftNearPost, defendingTeam);
                Enums.PitchZone actualGoalLineRightNearPost = GetTeamSpecificDefensiveZone(baseGoalLineRightNearPost, defendingTeam);

                for (int i = 0; i < goalLineDefenders.Count; i++)
                {
                    Player defender = goalLineDefenders[i];
                    Enums.PitchZone specificGoalLineZone;

                    if (i == 0)
                    {
                        specificGoalLineZone = actualGoalLineCentralZone; // First defender in the center
                    }
                    else if (i == 1)
                    {
                        // Second defender can go to one of the near posts
                        // Decide which side based on free kick zone, or just alternate
                        specificGoalLineZone = (i % 2 == 0) ? actualGoalLineLeftNearPost : actualGoalLineRightNearPost;
                    }
                    else
                    {
                        specificGoalLineZone = actualGoalLineCentralZone; // Fallback to center if more needed, though unlikely
                    }

                    if (specificGoalLineZone != PitchZone.None) defender.CurrentZone = specificGoalLineZone;
                    else defender.CurrentZone = actualGoalLineCentralZone;
                    availableDefenders.Remove(defender); // Remove from available defenders pool
                    //ShowMessage("Defending goal line: " + defender.fullName + " positioned at " + defender.CurrentZone + ".");
                }
            }


            // 2. Attacking Team: Identify key attacking targets for set pieces
            Player freeKickTakerCandidate = attackingTeam.AvailableOnFieldOutfielders
                .OrderByDescending(p => p.trueRating.freekicks * 0.6 + p.trueRating.PassingForGameCalculations * 0.4)
                .FirstOrDefault();

            // Re-evaluating attackingTargets for marking purposes:
            List<Player> keyAttackingTargets = new List<Player>();

            foreach (var player in attackingTeam.AvailableOnFieldOutfielders)
            {
                if (player.Position != Enums.Positions.Goalkeeper && player != freeKickTakerCandidate)
                {
                    keyAttackingTargets.Add(player);
                }
            }

            keyAttackingTargets.Sort((a, b) =>
            {
                double scoreA = CalculatePlayerScoreAttackPlayerFreeKicks(a);
                double scoreB = CalculatePlayerScoreAttackPlayerFreeKicks(b);
                return scoreB.CompareTo(scoreA); // Descending order
            });

            // --- Man-marking assignments for key attacking targets ---
            List<Player> assignedMarkers = new List<Player>();
            int maxMarkers = Math.Min(keyAttackingTargets.Count, availableDefenders.Count - 1); // Leave at least one defender for zonal if possible

            for (int i = 0; i < maxMarkers; i++)
            {
                Player attackingTarget = keyAttackingTargets[i];
                Player bestMarker = availableDefenders
                    .Where(p => !assignedMarkers.Contains(p) && p.Position != Enums.Positions.Goalkeeper)
                    .OrderByDescending(p => p.trueRating.DefendingForGameCalculations * 0.6 +
                                                p.trueRating.DefendingForGameCalculations * 0.4 +
                                                p.trueRating.StrengthForGameCalculations * 0.2)
                    .FirstOrDefault();

                if (bestMarker != null)
                {
                    bestMarker.MarkedOpponent = attackingTarget;

                    // Calculate potential new zone
                    Enums.PitchZone potentialNewZone = GetZoneOffset(attackingTarget.CurrentZone,
                                                                    isHomeDefendingTeam ? -1 : 1, // Stay slightly behind/to the side relative to attacking direction
                                                                    (i % 2 == 0 ? 0 : 1)); // Try to spread them slightly

                    // IMPORTANT: Handle the case where GetZoneOffset returns None
                    if (potentialNewZone != Enums.PitchZone.None)
                    {
                        bestMarker.CurrentZone = potentialNewZone;
                        //ShowMessage(bestMarker.fullName + " (" + defendingTeam.Name + ") assigned to man-mark " + attackingTarget.fullName + ". Positioned at " + bestMarker.CurrentZone + ".");
                    }
                    else
                    {
                        // Fallback: If the calculated offset zone is invalid, keep the marker in their current zone
                        // or assign them to a default safe zone nearby.
                        // For a set piece, a specific safe zone (like Defensive_EdgeOfBox) might be better than
                        // just staying wherever they were initially.
                        // For simplicity, let's keep them in their *current* zone if the offset fails,
                        // and trust that their initial `ResetPlayerPositionsToInPlay` or `GetZoneForPlayerInFormation`
                        // gave them a valid starting point.
                        //ShowMessage($"WARNING: Marker {bestMarker.fullName} attempted to move to invalid zone. Keeping at {bestMarker.CurrentZone}.");
                    }

                    assignedMarkers.Add(bestMarker);
                    availableDefenders.Remove(bestMarker);
                }
            }

            // Existing Attacking Team Positioning (minor adjustment for free kick taker)
            if (freeKickTakerCandidate != null)
            {
                // Calculate potential new zone for the taker
                Enums.PitchZone potentialTakerZone = GetZoneOffset(freeKickZone, attackingTeam == HomeTeam ? 1 : -1, 0); // Adjust based on attacking direction

                // IMPORTANT: Handle the case where GetZoneOffset returns None
                if (potentialTakerZone != Enums.PitchZone.None)
                {
                    freeKickTakerCandidate.CurrentZone = potentialTakerZone;
                    //ShowMessage("Free kick taker " + freeKickTakerCandidate.fullName + " positioned at " + freeKickTakerCandidate.CurrentZone + ".");
                }
                else
                {
                    // Fallback: If the calculated offset zone is invalid, position taker at the free kick zone itself
                    // or another logical safe zone. This is very important for the taker.
                    freeKickTakerCandidate.CurrentZone = freeKickZone; // A very sensible fallback
                    //ShowMessage($"WARNING: Taker {freeKickTakerCandidate.fullName} attempted to move to invalid offset. Positioned at free kick zone: {freeKickTakerCandidate.CurrentZone}.");
                }
            }

            // Attacking players who are not the taker and not explicitly marked by defensive assignments
            // will still get an initial starting position. The EvaluateAttackingMovement will handle their runs.
            int targetsPlaced = 0; // Use this to position other attacking players
            foreach (var target in keyAttackingTargets) // These are the initial attacking targets from before
            {
                // Ensure this player hasn't been removed (e.g., if they were the taker, though we filter that above)
                // If a defender is already marking them, their position might be less critical here as their run will be dynamic.
                if (target != freeKickTakerCandidate) // Ensure we don't reposition the taker
                {
                    // Only assign an initial 'base' zone if they aren't marked by a dedicated player already
                    // Their actual run will be determined by EvaluateAttackingMovement later.
                    // For now, give them a general dangerous area if not already marked.
                    bool isTargetMarked = assignedMarkers.Any(m => m.MarkedOpponent == target);
                    if (!isTargetMarked)
                    {
                        if (targetsPlaced == 0)
                        {
                            // Use GetTeamSpecificDefensiveZone for the attacking team's target penalty area
                            target.CurrentZone = GetTeamSpecificDefensiveZone(Enums.PitchZone.PenaltyArea_Away, attackingTeam); // This will map to PenaltyArea_Away if attacking is Home, or PenaltyArea_Home if attacking is Away
                        }
                        else if (targetsPlaced == 1)
                        {
                            target.CurrentZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.HomeDefense_LeftFlank;
                        }
                        else if (targetsPlaced == 2)
                        {
                            target.CurrentZone = (attackingTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
                        }
                        else
                        {
                            target.CurrentZone = GetZoneForPlayerInFormation(target.Position, attackingTeam.CurrentFormation, attackingTeam == HomeTeam);
                        }
                        //ShowMessage("Attacking player " + target.fullName + " positioned at " + target.CurrentZone + " for set piece (unmarked).");
                        targetsPlaced++;
                    }
                    else
                    {
                        //ShowMessage("Attacking player " + target.fullName + " is marked, initial positioning skipped as their run will be countered.");
                    }
                }
            }

            // 3. Other Defending Players (Zonal/Support):
            // These are the defenders not in the wall, on the goal line, or explicitly man-marking.
            // They will primarily rely on DetermineDefensiveZone in the main game loop.
            // Their current zones are already reset to default formation positions at the beginning.
            // We don't need to do explicit positioning here, as their AI will quickly take over to cover zones or support.
            foreach (var player in availableDefenders) // These are the remaining defenders
            {
                //ShowMessage(player.fullName + " (" + defendingTeam.Name + ") is in a zonal/support role. Initial zone: " + player.CurrentZone + ".");
            }

            //ShowMessage("Players finished positioning for free kick.");
        }

        private List<Player> GetPlayersInZone(Team team, Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetPlayersInZone: team:{0},zone:{1}",
            //    team.Name, zone));


            List<Player> result = new List<Player>();
            foreach (var player in team.AvailableOnFieldPlayers)
            {
                if (player.CurrentZone == zone)
                {
                    result.Add(player);
                }
            }
            return result;
        }

        /// <summary>
        /// Resets all player positions to their standard in-play formation zones after a set piece or major event,
        /// ensuring goalkeepers remain in their designated areas.
        /// </summary>
        private void ResetPlayerPositionsToInPlay()
        {
            //LoggingStuff.LogMethodCall("ResetPlayerPositionsToInPlay");


            //ShowMessage("Resetting player positions to in-play state.");

            foreach (var player in HomeTeam.AvailableOnFieldPlayers)
            {
                if (player.Position == Enums.Positions.Goalkeeper)
                {
                    // Goalkeepers always return to their specific goal area
                    player.CurrentZone = Enums.PitchZone.GoalkeeperArea_Home;
                }
                else
                {
                    player.CurrentZone = GetZoneForPlayerInFormation(player.Position, HomeTeam.CurrentFormation, true);
                }
            }
            foreach (var player in AwayTeam.AvailableOnFieldPlayers)
            {
                if (player.Position == Enums.Positions.Goalkeeper)
                {
                    // Goalkeepers always return to their specific goal area
                    player.CurrentZone = Enums.PitchZone.GoalkeeperArea_Away;
                }
                else
                {
                    player.CurrentZone = GetZoneForPlayerInFormation(player.Position, AwayTeam.CurrentFormation, false);
                }
            }
        }

        /// <summary>
        /// Helper method to determine if a given pitch zone is within a team's attacking penalty area.
        /// </summary>
        /// <param name="zone">The PitchZone to check.</param>
        /// <param name="attackingTeam">The team whose attacking penalty area is being considered.</param>
        /// <returns>True if the zone is within the attacking team's penalty area, false otherwise.</returns>
        private bool IsBallInPenaltyArea(Enums.PitchZone zone, Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInPenaltyArea: zone:{0},attackingTeam:{1}",
            //    zone, attackingTeam.Name));


            // Assuming you have a way to map zones to home/away penalty areas
            // And that 'homeTeam' and 'awayTeam' are properties of your MatchEngine class.

            if (attackingTeam == HomeTeam)
            {
                // For the home team attacking, their 'attacking penalty area' is the away team's penalty area
                return zone == Enums.PitchZone.PenaltyArea_Away ||
                       zone == Enums.PitchZone.GoalkeeperArea_Away ||
                       zone == Enums.PitchZone.Corner_AwayLeft ||
                       zone == Enums.PitchZone.Corner_AwayRight;
            }
            else // attackingTeam == awayTeam
            {
                // For the away team attacking, their 'attacking penalty area' is the home team's penalty area
                return zone == Enums.PitchZone.PenaltyArea_Home ||
                       zone == Enums.PitchZone.GoalkeeperArea_Home ||
                       zone == Enums.PitchZone.Corner_HomeLeft ||
                       zone == Enums.PitchZone.Corner_HomeRight;
            }
        }

        // Example helper method (add this to your MatchEngine if you don't have something similar)
        private bool IsZoneInOpponentPenaltyArea(Enums.PitchZone zone, Team teamAwardedFoul)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsZoneInOpponentPenaltyArea: zone:{0},teamAwardedFoul:{1}",
            //    zone, teamAwardedFoul.Name));


            // Assuming 'homeTeam' and 'awayTeam' are properties of your MatchEngine
            if (teamAwardedFoul == HomeTeam) // If home team was fouled, check if foul was in AWAY team's penalty area
            {
                return zone == Enums.PitchZone.PenaltyArea_Away;
            }
            else // If away team was fouled, check if foul was in HOME team's penalty area
            {
                return zone == Enums.PitchZone.PenaltyArea_Home;
            }
        }

        // You might also need a simpler FindBestAttackerInZone for the fallback if FindBestAttackerForRoutineRole doesn't find anyone
        // This is the one you already have or can easily implement
        private Player FindBestAttackerInZone(Team attackingTeam, Enums.PitchZone targetZone, bool preferAerialPlayers = false)
        {
            return attackingTeam.AvailableOnFieldOutfielders
                .Where(p => p.CurrentZone == targetZone)
                .OrderByDescending(p => preferAerialPlayers ? (p.trueRating.HeaderForGameCalculations + p.trueRating.JumpingForGameCalculations) : p.trueRating.PositioningForGameCalculations)
                .FirstOrDefault();
        }

        /// <summary>
        /// Assigns the PitchZone for each player based on their assigned set piece roles.
        /// Your match engine will then handle the visual positioning within these zones.
        /// </summary>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <param name="cornerZone">The PitchZone where the corner kick is located (ball position).</param>
        /// <param name="offensiveRoutine">The chosen offensive routine (for attacking player positioning logic).</param>
        /// <param name="defensiveRoutine">The chosen defensive routine (for defending player positioning logic).</param>
        public void AssignPlayerZonesForSetPiece(
            Team attackingTeam,
            Team defendingTeam,
            Enums.PitchZone cornerZone, // Or general SetPieceZone for free kicks etc.
            OffensiveCornerRoutine offensiveRoutine, // You'll need to define this class if not already.
            DefensiveSetPieceRoutine defensiveRoutine)
        {
            //ShowMessage("Assigning PitchZones for players for set piece...");

            // The ball is conceptually "positioned" within the cornerZone
            // Your match engine will need to know where to render the ball based on this zone.
            CurrentBallZone = cornerZone;
            //ShowMessage("Ball conceptually positioned at " + cornerZone + ".");

            // Determine the defending team's penalty area for zone mapping
            Enums.PitchZone defendingPenaltyArea = (DefendingTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Home : Enums.PitchZone.PenaltyArea_Away;
            Enums.Flank attackingCornerFlank = GetFlankOfCornerRelativeToAttacker(cornerZone); // Re-use the helper

            // --- Attacking Team Zone Assignment ---
            foreach (var player in attackingTeam.AvailableOnFieldOutfielders)
            {
                // The player assigned as SetPieceTaker is conceptually "at the ball's zone"
                if (player.OffensiveSetPieceRole == Enums.SetPieceRole.SetPieceTaker)
                {
                    player.CurrentZone = cornerZone;
                    //ShowMessage(player.fullName + " (Attacker - Taker) assigned to zone: " + player.CurrentZone + ".");
                    continue;
                }

                // If player has a specific simulated zone from their offensive routine
                if (player.SimulatedSetPieceZone != Enums.PitchZone.None)
                {
                    // For attackers, assign their specific conceptual set piece zone
                    player.CurrentZone = player.SimulatedSetPieceZone;
                    //ShowMessage(player.fullName + " (Attacker) assigned to zone: " + player.CurrentZone + " for role " + player.OffensiveSetPieceRole + ".");
                }
                else
                {
                    // Fallback for attackers without a specific set piece role or zone
                    // Assign them to a general attacking area relevant to their primary position.
                    player.CurrentZone = MapPlayerRoleToGeneralAttackingZone(player.Role, AttackingTeam == HomeTeam);
                    //ShowMessage(player.fullName + " (Attacker - Fallback) assigned to zone: " + player.CurrentZone + " for role " + player.Position + ".");
                }
            }

            // --- Defending Team Zone Assignment ---
            foreach (var player in defendingTeam.AvailableOnFieldPlayers)
            {
                if (player.Position == Enums.Positions.Goalkeeper)
                {
                    // Goalkeeper always positions conceptually in their goal area.
                    player.CurrentZone = (defendingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    //ShowMessage(player.fullName + " (Goalkeeper) assigned to zone: " + player.CurrentZone + ".");
                    continue;
                }

                // Man-marked players will conceptually try to stick close to their target's zone
                if (player.MarkedOpponent != null)
                {
                    // Assign them to the same zone as their target, or a "marking" sub-zone if you introduce one.
                    player.CurrentZone = player.MarkedOpponent.CurrentZone; // Or a closely related zone
                    //ShowMessage(player.fullName + " (Man Marker) assigned to zone: " + player.CurrentZone + " (near " + player.MarkedOpponent.fullName + ") for role " + player.DefensiveSetPieceRole + ".");
                }
                // Zonal defenders move to their assigned zones
                else if (player.SimulatedSetPieceZone != Enums.PitchZone.None)
                {
                    // For zonal players, assign them to their specific simulated set piece zone.
                    player.CurrentZone = player.SimulatedSetPieceZone;
                    //ShowMessage(player.fullName + " (Defender) assigned to zone: " + player.CurrentZone + " for role " + player.DefensiveSetPieceRole + ".");
                }
                else
                {
                    // Fallback for defenders without explicit set piece role/zone (should be rare if assignment is complete)
                    player.CurrentZone = MapPlayerRoleToGeneralDefendingZone(player.Role, DefendingTeam == HomeTeam);
                    //ShowMessage(player.fullName + " (Defender - Fallback) assigned to zone: " + player.CurrentZone + " for role " + player.Position + ".");
                }
            }
            //ShowMessage("All players' PitchZones assigned for set piece.");
        }

        // Helper to determine the flank of the corner from the attacking team's perspective
        private Enums.Flank GetFlankOfCornerRelativeToAttacker(Enums.PitchZone cornerZone)
        {
            // Assuming Corner_AwayLeft and Corner_HomeLeft are on the 'left' side from the attacking perspective
            // and Corner_AwayRight and Corner_HomeRight are on the 'right' side from the attacking perspective.
            if (cornerZone == Enums.PitchZone.Corner_AwayLeft || cornerZone == Enums.PitchZone.Corner_HomeLeft)
            {
                return Enums.Flank.Left;
            }
            else if (cornerZone == Enums.PitchZone.Corner_AwayRight || cornerZone == Enums.PitchZone.Corner_HomeRight)
            {
                return Enums.Flank.Right;
            }
            return Enums.Flank.Center; // Should not happen for a corner, but as a fallback
        }

        private Enums.PitchZone GetFarPostZoneForDefense(Enums.PitchZone defensivePenaltyArea, Enums.PitchZone cornerZone)
        {
            Enums.Flank attackingCornerFlank = GetFlankOfCornerRelativeToAttacker(cornerZone);

            if (defensivePenaltyArea == Enums.PitchZone.PenaltyArea_Home)
            {
                // Home team is defending their goal (PenaltyArea_Home)
                // If attacking from their left (Home's right), far post is HomeDefense_LeftFlank.
                return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.HomeDefense_RightFlank;
            }
            else // defensivePenaltyArea == Enums.PitchZone.PenaltyArea_Away (Away team is defending their goal)
            {
                // If attacking from their left (Away's right), far post is AwayAttack_LeftFlank.
                return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.AwayAttack_RightFlank;
            }
        }

        /// <summary>
        /// Finds the best available player for a specific defensive set piece role from a list of candidates.
        /// </summary>
        /// <param name="candidatePlayers">The list of players to consider.</param>
        /// <param name="preferredPlayerRoles">List of preferred PlayerRoles for this specific SetPieceRole.</param>
        /// <param name="excludedPlayers">Players already assigned or otherwise excluded.</param>
        /// <param name="targetSetPieceRole">The specific defensive set piece role being filled.</param>
        /// <returns>The best suitable Player, or null if none found.</returns>
        private Player FindBestPlayerForDefensiveRole(
            List<Player> candidatePlayers,
            List<Enums.PlayerRole> preferredPlayerRoles,
            List<Player> excludedPlayers,
            Enums.SetPieceRole targetSetPieceRole)
        {
            Player bestCandidate = null;
            double bestScore = -1.0;

            var availableCandidates = new List<Player>();
            var excludedSet = new HashSet<Player>(excludedPlayers);

            foreach (var player in candidatePlayers)
            {
                if (!excludedSet.Contains(player) &&
                    !player.IsInjured &&
                    !player.isSentOff &&
                    player.Position != Enums.Positions.Goalkeeper &&
                    player.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                {
                    availableCandidates.Add(player);
                }
            }

            if (preferredPlayerRoles == null || !preferredPlayerRoles.Any())
            {
                // If no preferred roles, consider any available outfield player
                preferredPlayerRoles = new List<Enums.PlayerRole>();
                foreach (Enums.PlayerRole role in EnumValuesCache<Enums.PlayerRole>.GetValues())
                {
                    if (role != Enums.PlayerRole.Goalkeeper && role != Enums.PlayerRole.None)
                    {
                        preferredPlayerRoles.Add(role);
                    }
                }
            }


            foreach (var player in availableCandidates)
            {
                if (!preferredPlayerRoles.Contains(player.Role))
                {
                    continue; // Skip if player's primary role isn't preferred for this set piece role
                }

                double score = 0;

                // Scoring logic based on the targetSetPieceRole
                switch (targetSetPieceRole)
                {
                    case Enums.SetPieceRole.PostBlocker:
                        score = (player.trueRating.VisionForGameCalculations * 0.3 + // Reading the cross
                                 player.trueRating.ComposureForGameCalculations * 0.3 + // Willingness to put body on line
                                 player.trueRating.DefenseAwarenessForGameCalculations * 0.4); // Knowing where to be
                        break;
                    case Enums.SetPieceRole.ZonalMarker:
                        score = (player.trueRating.PositioningForGameCalculations * 0.4 + // Crucial for zonal marking
                                 player.trueRating.DefenseAwarenessForGameCalculations * 0.3 +
                                 player.trueRating.HeaderForGameCalculations * 0.2 + // For clearing aerial balls
                                 player.trueRating.JumpingForGameCalculations * 0.1);
                        break;
                    case Enums.SetPieceRole.ManMarker:
                        score = (player.trueRating.DefendingForGameCalculations * 0.5 + // Direct marking ability
                                 player.trueRating.AggressionForGameCalculations * 0.2 + // To stick tight
                                 player.trueRating.StrengthForGameCalculations * 0.2 + // To outmuscle
                                 player.trueRating.AgilityForGameCalculations * 0.1);
                        break;
                    case Enums.SetPieceRole.ClearingDefender:
                        score = (player.trueRating.HeaderForGameCalculations * 0.4 +
                                 player.trueRating.JumpingForGameCalculations * 0.3 +
                                 player.trueRating.StandTackleForGameCalculations * 0.2 + // For ground balls
                                 player.trueRating.StrengthForGameCalculations * 0.1);
                        break;
                    case Enums.SetPieceRole.CounterAttackOutlet:
                        score = (player.trueRating.PaceForGameCalculations * 0.3 +
                                 player.trueRating.PositioningForGameCalculations * 0.3 +
                                 player.trueRating.PassingForGameCalculations * 0.2 +
                                 player.trueRating.DribblingForGameCalculations * 0.2);
                        break;
                    case Enums.SetPieceRole.EdgeOfBoxSweeper:
                        score = (player.trueRating.AccelerationForGameCalculations * 0.3 +
                                 player.trueRating.LongShotForGameCalculations * 0.2 + // For blocking shots
                                 player.trueRating.DefenseAwarenessForGameCalculations * 0.3 +
                                 player.trueRating.StandTackleForGameCalculations * 0.2);
                        break;
                    default:
                        score = (player.trueRating.DefenseAwarenessForGameCalculations + player.trueRating.PositioningForGameCalculations) / 2.0;
                        break;
                }

                if (score > bestScore)
                {
                    bestScore = score;
                    bestCandidate = player;
                }
            }

            return bestCandidate;
        }

        /// <summary>
        /// Assigns specific offensive set piece roles to players based on the chosen routine.
        /// </summary>
        /// <param name="players">The array of players for the attacking team.</param>
        /// <param name="offensiveRoutine">The specific OffensiveCornerRoutine or OffensiveFreeKickRoutine.</param>
        private void AssignSetPieceRolesForRoutine(IEnumerable<Player> players, SetPieceRoutine offensiveRoutine) // Changed parameter type to base SetPieceRoutine
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignSetPieceRolesForRoutine: players:{0},offensiveRoutine:{1}",
            //    string.Join(",", players.Select(p => p.position)),
            //    offensiveRoutine));


            // Clear previous set piece roles for all players
            foreach (var p in players)
            {
                p.OffensiveSetPieceRole = Enums.SetPieceRole.None;
            }

            //ShowMessage("Assigning offensive set piece roles for " + offensiveRoutine.Name + " (" + offensiveRoutine.AppliesToSetPieceType + ") to " + AttackingTeam.Name + " players.");

            List<Player> availablePlayers = new List<Player>();
            foreach (Player player in players)
            {
                if (!player.IsInjured && !player.isSentOff && player.Position != Enums.Positions.Goalkeeper)
                {
                    availablePlayers.Add(player);
                }
            }

            // Determine RoleAssignments specific to the routine type
            Dictionary<Enums.SetPieceRole, List<Enums.Positions>> roleAssignments = new Dictionary<Enums.SetPieceRole, List<Enums.Positions>>();

            OffensiveCornerRoutine cornerRoutine = offensiveRoutine as OffensiveCornerRoutine;
            OffensiveCornerRoutine freeKickRoutine = offensiveRoutine as OffensiveCornerRoutine;
            if (cornerRoutine != null)
            {
                roleAssignments = cornerRoutine.RoleAssignments;
            }
            else if (freeKickRoutine != null)
            {
                roleAssignments = freeKickRoutine.RoleAssignments;
            }
            else
            {
                //ShowMessage("Warning: Unknown offensive routine type provided for role assignment.");
                return;
            }

            // Handle the SetPieceTaker first
            Player setPieceTaker = null;
            if (cornerRoutine != null)
            {
                // Find best corner taker
                setPieceTaker = AttackingTeam.AvailableOnFieldOutfielders
                    .OrderByDescending(p => p.trueRating.crossing * 0.7 + p.trueRating.PassingForGameCalculations * 0.3)
                    .FirstOrDefault();
            }
            else if (freeKickRoutine != null)
            {
                // Find best free kick taker
                setPieceTaker = AttackingTeam.AvailableOnFieldOutfielders
                    .OrderByDescending(p => p.trueRating.freekicks * 0.6 + p.trueRating.PassingForGameCalculations * 0.4)
                    .FirstOrDefault();
            }

            if (setPieceTaker != null)
            {
                setPieceTaker.OffensiveSetPieceRole = Enums.SetPieceRole.SetPieceTaker;
                availablePlayers.Remove(setPieceTaker);
                //ShowMessage(setPieceTaker.fullName + " assigned as SetPieceTaker for " + offensiveRoutine.AppliesToSetPieceType + ".");
            }


            // Iterate through defined SetPieceRoles in the routine and assign players
            foreach (var setPieceRoleEntry in roleAssignments)
            {
                Enums.SetPieceRole spRole = setPieceRoleEntry.Key;
                List<Enums.Positions> suitablePlayerPositions = setPieceRoleEntry.Value;

                if (spRole == Enums.SetPieceRole.SetPieceTaker) continue; // Already handled

                // Find the best player for this SetPieceRole from available players
                Player bestFit = availablePlayers
                    .Where(p => suitablePlayerPositions.Contains(p.Position))
                    .OrderByDescending(p => CalculateOffensiveRoleSuitability(p, spRole)) // Use a helper for attribute scoring
                    .FirstOrDefault();

                if (bestFit != null)
                {
                    bestFit.OffensiveSetPieceRole = spRole;
                    availablePlayers.Remove(bestFit);
                    //ShowMessage(" - bestFit.fullName " + " assigned as " + spRole + ".");
                }
                else
                {
                    //ShowMessage("No suitable player found for " + spRole + ".");
                }
            }

            // Any remaining players not assigned a specific routine role can be given a default "Support" role
            foreach (var p in availablePlayers)
            {
                if (p.OffensiveSetPieceRole == Enums.SetPieceRole.None)
                {
                    p.OffensiveSetPieceRole = Enums.SetPieceRole.MidfieldSupport;
                    //ShowMessage(p.fullName + " assigned as OffensiveSupport.");
                }
            }
        }

        // This method would reset all players in the given team to their default formation positions.
        // The implementation depends on how you store player positions and formations.

        public void ResetPlayerPositionsToFormation(Team team, Enums.Formation formation, bool isHomeTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("ResetPlayerPositionsToFormation: team:{0},formation:{1},isHomeTeam:{2}",
            //    team.Name, formation, isHomeTeam));


            foreach (Player player in team.AvailableOnFieldPlayers)
            {
                // Now, we call the new method that considers the formation AND the team's perspective
                player.CurrentZone = GetZoneForPlayerInFormation(player.Position, formation, isHomeTeam);
            }
        }

        /// <summary>
        /// Determines the conceptual PitchZone a player is currently occupying based on their position and team's attacking/defending status.
        /// This is a simplified model of player positioning.
        /// </summary>
        /// <param name="player">The player whose zone is to be determined.</param>
        /// <returns>The PitchZone the player is conceptually in.</returns>
        private Enums.PitchZone GetPlayerZone(Player player)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetPlayerZone: player:{0}",
            //    player.position));


            // First, determine if the player is on their attacking team or defending team side
            bool isPlayerOnAttackingTeam = (player.Team == AttackingTeam);
            Team playersTeam = player.Team;
            Enums.Positions playerPosition = player.Position;

            // General logic for GKs and Central Defenders
            if (playerPosition == Enums.Positions.Goalkeeper)
            {
                return (playersTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
            }
            if (playerPosition == Enums.Positions.CenterBack)
            {
                return (playersTeam == HomeTeam) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
            }

            // --- Logic based on Player Position and Attacking/Defending context ---

            // Attacking Players (ST, AMC, AML, AMR)
            if (playerPosition == Enums.Positions.Striker || playerPosition == Enums.Positions.CentralAttackingMidfielder
                || playerPosition == Enums.Positions.RightWingForward || playerPosition == Enums.Positions.LeftWingForward)
            {
                if (isPlayerOnAttackingTeam)
                {
                    // Attacking players tend to be in the opponent's defensive third or midfield when their team is attacking
                    if (playerPosition == Enums.Positions.Striker) return Enums.PitchZone.Midfield_Center;
                    if (playerPosition == Enums.Positions.CentralAttackingMidfielder) return Enums.PitchZone.Midfield_Center;
                    if (playerPosition == Enums.Positions.RightWingForward) return Enums.PitchZone.Midfield_RightFlank;
                    if (playerPosition == Enums.Positions.LeftWingForward) return Enums.PitchZone.Midfield_LeftFlank;
                }
                else // Attacking players tracking back when their team is defending
                {
                    // Attacking players tend to be in the opponent's defensive third or midfield when their team is attacking
                    if (playerPosition == Enums.Positions.Striker) return Enums.PitchZone.Midfield_Center;
                    if (playerPosition == Enums.Positions.CentralAttackingMidfielder) return Enums.PitchZone.Midfield_Center;
                    if (playerPosition == Enums.Positions.RightWingForward) return Enums.PitchZone.Midfield_RightFlank;
                    if (playerPosition == Enums.Positions.LeftWingForward) return Enums.PitchZone.Midfield_LeftFlank;
                }
            }

            // Midfielders (MC, ML, MR)
            else if (playerPosition == Enums.Positions.CentralMidfielder || playerPosition == Enums.Positions.LeftMidfielder || playerPosition == Enums.Positions.RightMidfielder)
            {
                // Midfielders generally stay in midfield, but can push up or drop back
                if (isPlayerOnAttackingTeam)
                {
                    if (playerPosition == Enums.Positions.LeftMidfielder) return Enums.PitchZone.Midfield_LeftFlank;
                    if (playerPosition == Enums.Positions.RightMidfielder) return Enums.PitchZone.Midfield_RightFlank;
                    if (playerPosition == Enums.Positions.CentralMidfielder) return Enums.PitchZone.Midfield_Center;
                }
                else // Midfielders defending
                {
                    // Can drop slightly deeper or stay in midfield
                    if (playerPosition == Enums.Positions.LeftMidfielder) return Enums.PitchZone.Midfield_LeftFlank;
                    if (playerPosition == Enums.Positions.RightMidfielder) return Enums.PitchZone.Midfield_RightFlank;
                    if (playerPosition == Enums.Positions.CentralMidfielder) return Enums.PitchZone.Midfield_Center;
                }
            }

            // Defensive Players (DL, DR, DMC)
            else if (playerPosition == Enums.Positions.LeftBack || playerPosition == Enums.Positions.RightBack || playerPosition == Enums.Positions.CentralDefendingMidfielder)
            {
                if (isPlayerOnAttackingTeam)
                {
                    // Defensive players pushing forward when their team is attacking
                    if (playerPosition == Enums.Positions.LeftBack) return Enums.PitchZone.Midfield_LeftFlank;
                    if (playerPosition == Enums.Positions.RightBack) return Enums.PitchZone.Midfield_RightFlank;
                    if (playerPosition == Enums.Positions.CentralDefendingMidfielder) return Enums.PitchZone.Midfield_Center;
                }
                else // Defensive players staying in their own half when defending
                {
                    if (playerPosition == Enums.Positions.LeftBack) return Enums.PitchZone.HomeDefense_LeftFlank; // Assuming HomeDefense is their own half
                    if (playerPosition == Enums.Positions.RightBack) return Enums.PitchZone.HomeDefense_RightFlank;
                    if (playerPosition == Enums.Positions.CentralDefendingMidfielder) return Enums.PitchZone.HomeDefense_Center;
                }
            }

            // Default / Fallback
            return Enums.PitchZone.Midfield_Center;
        }

        /// <summary>
        /// Determines if two PitchZones are conceptually adjacent.
        /// This is a simplified adjacency map.
        /// </summary>
        /// <param name="zone1">The first PitchZone.</param>
        /// <param name="zone2">The second PitchZone.</param>
        /// <returns>True if the zones are considered adjacent, false otherwise.</returns>
        private bool IsAdjacentZone(Enums.PitchZone zone1, Enums.PitchZone zone2)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsAdjacentZone: zone1:{0},zone2:{1}",
            //    zone1, zone2));


            // A zone is adjacent to itself in a degenerate sense, but not for finding *other* players.
            if (zone1 == zone2) return false;

            // Common patterns for adjacency (Central <-> Flanks, Defense <-> Midfield <-> Attack)

            // General Midfield Adjacencies
            if ((zone1 == Enums.PitchZone.Midfield_Center && (zone2 == Enums.PitchZone.Midfield_LeftFlank || zone2 == Enums.PitchZone.Midfield_RightFlank)) ||
                (zone2 == Enums.PitchZone.Midfield_Center && (zone1 == Enums.PitchZone.Midfield_LeftFlank || zone1 == Enums.PitchZone.Midfield_RightFlank)))
            {
                return true;
            }

            // Home Half Adjacencies
            if ((zone1 == Enums.PitchZone.HomeDefense_Center && (zone2 == Enums.PitchZone.HomeDefense_LeftFlank || zone2 == Enums.PitchZone.HomeDefense_RightFlank || zone2 == Enums.PitchZone.Midfield_Center)) ||
                (zone2 == Enums.PitchZone.HomeDefense_Center && (zone1 == Enums.PitchZone.HomeDefense_LeftFlank || zone1 == Enums.PitchZone.HomeDefense_RightFlank || zone1 == Enums.PitchZone.Midfield_Center)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.HomeDefense_LeftFlank && (zone2 == Enums.PitchZone.HomeDefense_Center || zone2 == Enums.PitchZone.Midfield_LeftFlank)) ||
                (zone2 == Enums.PitchZone.HomeDefense_LeftFlank && (zone1 == Enums.PitchZone.HomeDefense_Center || zone1 == Enums.PitchZone.Midfield_LeftFlank)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.HomeDefense_RightFlank && (zone2 == Enums.PitchZone.HomeDefense_Center || zone2 == Enums.PitchZone.Midfield_RightFlank)) ||
                (zone2 == Enums.PitchZone.HomeDefense_RightFlank && (zone1 == Enums.PitchZone.HomeDefense_Center || zone1 == Enums.PitchZone.Midfield_RightFlank)))
            {
                return true;
            }
            // Penalty/Goalkeeper Area Adjacency
            if ((zone1 == Enums.PitchZone.PenaltyArea_Home && (zone2 == Enums.PitchZone.HomeDefense_Center || zone2 == Enums.PitchZone.GoalkeeperArea_Home)) ||
                (zone2 == Enums.PitchZone.PenaltyArea_Home && (zone1 == Enums.PitchZone.HomeDefense_Center || zone1 == Enums.PitchZone.GoalkeeperArea_Home)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.GoalkeeperArea_Home && zone2 == Enums.PitchZone.PenaltyArea_Home) ||
                (zone2 == Enums.PitchZone.GoalkeeperArea_Home && zone1 == Enums.PitchZone.PenaltyArea_Home))
            {
                return true;
            }

            // Away Half Adjacencies (Symmetrical to Home Half)
            if ((zone1 == Enums.PitchZone.AwayAttack_Center && (zone2 == Enums.PitchZone.AwayAttack_LeftFlank || zone2 == Enums.PitchZone.AwayAttack_RightFlank || zone2 == Enums.PitchZone.Midfield_Center)) ||
                (zone2 == Enums.PitchZone.AwayAttack_Center && (zone1 == Enums.PitchZone.AwayAttack_LeftFlank || zone1 == Enums.PitchZone.AwayAttack_RightFlank || zone1 == Enums.PitchZone.Midfield_Center)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.AwayAttack_LeftFlank && (zone2 == Enums.PitchZone.AwayAttack_Center || zone2 == Enums.PitchZone.Midfield_LeftFlank)) ||
                (zone2 == Enums.PitchZone.AwayAttack_LeftFlank && (zone1 == Enums.PitchZone.AwayAttack_Center || zone1 == Enums.PitchZone.Midfield_LeftFlank)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.AwayAttack_RightFlank && (zone2 == Enums.PitchZone.AwayAttack_Center || zone2 == Enums.PitchZone.Midfield_RightFlank)) ||
                (zone2 == Enums.PitchZone.AwayAttack_RightFlank && (zone1 == Enums.PitchZone.AwayAttack_Center || zone1 == Enums.PitchZone.Midfield_RightFlank)))
            {
                return true;
            }
            // Penalty/Goalkeeper Area Adjacency
            if ((zone1 == Enums.PitchZone.PenaltyArea_Away && (zone2 == Enums.PitchZone.AwayAttack_Center || zone2 == Enums.PitchZone.GoalkeeperArea_Away)) ||
                (zone2 == Enums.PitchZone.PenaltyArea_Away && (zone1 == Enums.PitchZone.AwayAttack_Center || zone1 == Enums.PitchZone.GoalkeeperArea_Away)))
            {
                return true;
            }
            if ((zone1 == Enums.PitchZone.GoalkeeperArea_Away && zone2 == Enums.PitchZone.PenaltyArea_Away) ||
                (zone2 == Enums.PitchZone.GoalkeeperArea_Away && zone1 == Enums.PitchZone.PenaltyArea_Away))
            {
                return true;
            }

            // KickOffCircle adjacency (only to Midfield_Center)
            if ((zone1 == Enums.PitchZone.KickOffCircle && zone2 == Enums.PitchZone.Midfield_Center) ||
                (zone2 == Enums.PitchZone.KickOffCircle && zone1 == Enums.PitchZone.Midfield_Center))
            {
                return true;
            }

            // Corner adjacencies (to their respective flank and penalty area)
            if ((zone1 == Enums.PitchZone.Corner_HomeLeft && (zone2 == Enums.PitchZone.HomeDefense_LeftFlank || zone2 == Enums.PitchZone.PenaltyArea_Home)) ||
                (zone2 == Enums.PitchZone.Corner_HomeLeft && (zone1 == Enums.PitchZone.HomeDefense_LeftFlank || zone1 == Enums.PitchZone.PenaltyArea_Home)))
            {
                return true;
            }
            // --- COMPLETED CORNER ADJACENCIES ---
            // Corner_HomeLeft
            if ((zone1 == Enums.PitchZone.Corner_HomeLeft && (zone2 == Enums.PitchZone.HomeDefense_LeftFlank || zone2 == Enums.PitchZone.PenaltyArea_Home)) ||
                (zone2 == Enums.PitchZone.Corner_HomeLeft && (zone1 == Enums.PitchZone.HomeDefense_LeftFlank || zone1 == Enums.PitchZone.PenaltyArea_Home)))
            {
                return true;
            }
            // Corner_HomeRight
            if ((zone1 == Enums.PitchZone.Corner_HomeRight && (zone2 == Enums.PitchZone.HomeDefense_RightFlank || zone2 == Enums.PitchZone.PenaltyArea_Home)) ||
                (zone2 == Enums.PitchZone.Corner_HomeRight && (zone1 == Enums.PitchZone.HomeDefense_RightFlank || zone1 == Enums.PitchZone.PenaltyArea_Home)))
            {
                return true;
            }
            // Corner_AwayLeft
            if ((zone1 == Enums.PitchZone.Corner_AwayLeft && (zone2 == Enums.PitchZone.AwayAttack_LeftFlank || zone2 == Enums.PitchZone.PenaltyArea_Away)) ||
                (zone2 == Enums.PitchZone.Corner_AwayLeft && (zone1 == Enums.PitchZone.AwayAttack_LeftFlank || zone1 == Enums.PitchZone.PenaltyArea_Away)))
            {
                return true;
            }
            // Corner_AwayRight
            if ((zone1 == Enums.PitchZone.Corner_AwayRight && (zone2 == Enums.PitchZone.AwayAttack_RightFlank || zone2 == Enums.PitchZone.PenaltyArea_Away)) ||
                (zone2 == Enums.PitchZone.Corner_AwayRight && (zone1 == Enums.PitchZone.AwayAttack_RightFlank || zone1 == Enums.PitchZone.PenaltyArea_Away)))
            {
                return true;
            }
            // --- END COMPLETED CORNER ADJACENCIES ---

            return false; // Not adjacent
        }

        // This helper method should be added to your Match/Game class
        // It maps zones to a numerical depth relative to the HOME goal line.
        // Lower value = closer to home goal. Higher value = closer to away goal.
        private int GetAbsolutePitchDepth(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetAbsolutePitchDepth: zone:{0}", zone));


            switch (zone)
            {
                case Enums.PitchZone.GoalkeeperArea_Home: return 0;
                case Enums.PitchZone.PenaltyArea_Home: return 1;
                // Map these specific defensive areas to appropriate depths (e.g., 1 or 2)
                case Enums.PitchZone.DefensivePenaltyArea_LeftNearPost: return 1; // Or maybe a 1.5 if you used floats, but stick to int
                case Enums.PitchZone.DefensivePenaltyArea_RightNearPost: return 1;
                case Enums.PitchZone.DefensivePenaltyArea_Central: return 1;
                case Enums.PitchZone.DefensivePenaltyArea_LeftFarPost: return 1;
                case Enums.PitchZone.DefensivePenaltyArea_RightFarPost: return 1;
                case Enums.PitchZone.Defensive_EdgeOfBox: return 2; // Just outside the box, similar to HomeDefense_Center

                case Enums.PitchZone.HomeDefense_LeftFlank:
                case Enums.PitchZone.HomeDefense_Center:
                case Enums.PitchZone.HomeDefense_RightFlank: return 2;

                case Enums.PitchZone.Midfield_LeftFlank:
                case Enums.PitchZone.Midfield_Center:
                case Enums.PitchZone.Midfield_RightFlank: return 3;
                case Enums.PitchZone.KickOffCircle: return 3; // KickOffCircle is mid-pitch

                case Enums.PitchZone.AwayAttack_LeftFlank:
                case Enums.PitchZone.AwayAttack_Center:
                case Enums.PitchZone.AwayAttack_RightFlank: return 4;
                case Enums.PitchZone.PenaltyArea_Away: return 5;
                case Enums.PitchZone.GoalkeeperArea_Away: return 6;

                // Corner zones: These are often at the "0" or "6" depth, but off to the side.
                // For a simple depth system, map them to the corresponding goal area depth.
                case Enums.PitchZone.Corner_HomeLeft: return 0;
                case Enums.PitchZone.Corner_HomeRight: return 0;
                case Enums.PitchZone.Corner_AwayLeft: return 6;
                case Enums.PitchZone.Corner_AwayRight: return 6;

                case Enums.PitchZone.None: return -99; // Or throw an exception, this state should ideally not occur for a player
                default: return -1; // Fallback, but ideally all zones are mapped
            }
        }

        #endregion

        #region General Strategy

        /// <summary>
        /// Evaluates the tactical needs of both home and away teams based on match state.
        /// This method should be called periodically during the match (e.g., every 5-10 minutes, or after goals/red cards).
        /// </summary>
        private void EvaluateTeamTactics()
        {
            //LoggingStuff.LogMethodCall("EvaluateTeamTactics");


            // Evaluate Home Team's Tactic
            EvaluateSingleTeamTactic(HomeTeam, AwayTeam, HomeScore, AwayScore, (TotalGameSecondsElapsed / 60), isHomeTeam: true);

            // Evaluate Away Team's Tactic
            EvaluateSingleTeamTactic(AwayTeam, HomeTeam, AwayScore, HomeScore, (TotalGameSecondsElapsed / 60), isHomeTeam: false);
        }

        /// <summary>
        /// Determines and sets the tactic for a single team based on the current match situation.
        /// </summary>
        private void EvaluateSingleTeamTactic(Team teamToEvaluate, Team opponentTeam, int teamScore, int opponentScore, int currentMinute, bool isHomeTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("EvaluateSingleTeamTactic: teamToEvaluate:{0},opponentTeam:{1}," +
            //    "teamScore:{2},opponentScore:{3},currentMinute:{4},isHomeTeam:{5}",
            //    teamToEvaluate.Name, opponentTeam.Name, teamScore, opponentScore, currentMinute, isHomeTeam));


            // Define some thresholds for decision making
            int losingDiffForAggressive = 1;  // If losing by this much, consider attacking/pressing
            int winningDiffForDefensive = 1; // If winning by this much, consider defensive

            // Determine current match situation
            bool isWinning = teamScore > opponentScore;
            bool isLosing = teamScore < opponentScore;
            bool isTied = teamScore == opponentScore;
            bool isLateGame = currentMinute >= 75;  // Last 15 minutes of regular time
            bool isVeryLateGame = currentMinute >= 85; // Last 5 minutes of regular time

            Enums.TeamTactic proposedTactic = teamToEvaluate.CurrentTactic; // Start with current tactic

            // --- Core Tactical Logic ---

            // 1. Losing Scenario
            if (isLosing)
            {
                if (isVeryLateGame && (opponentScore - teamScore) >= losingDiffForAggressive)
                {
                    // Desperate: Go all-out attack
                    proposedTactic = Enums.TeamTactic.Attacking;
                }
                else if (isLateGame && (opponentScore - teamScore) >= losingDiffForAggressive)
                {
                    // Pushing for an equalizer, or trying to narrow the gap
                    proposedTactic = Enums.TeamTactic.Attacking; // or Enums.TeamTactic.PressHigh
                }
                else if (isTied && currentMinute >= 80 && isHomeTeam) // Home team might push for a late win
                {
                    proposedTactic = Enums.TeamTactic.Attacking;
                }
                // If losing earlier in the game, perhaps stick to Balanced or adjust slightly
                else if (currentMinute < 75 && teamToEvaluate.CurrentTactic != Enums.TeamTactic.Balanced)
                {
                    proposedTactic = Enums.TeamTactic.Balanced; // Don't panic too early
                }
            }
            // 2. Winning Scenario
            else if (isWinning)
            {
                if (isLateGame && (teamScore - opponentScore) >= winningDiffForDefensive)
                {
                    // Protect the lead
                    proposedTactic = Enums.TeamTactic.Defensive;
                }
                else if (teamToEvaluate.CurrentTactic == Enums.TeamTactic.Attacking && (teamScore - opponentScore) >= (winningDiffForDefensive + 1))
                {
                    // If already attacking and have a comfortable lead, might revert to balanced
                    proposedTactic = Enums.TeamTactic.Balanced;
                }
            }
            // 3. Tied Scenario
            else if (isTied)
            {
                if (isVeryLateGame)
                {
                    if (isHomeTeam)
                    {
                        // Home team often pushes for a winner
                        proposedTactic = Enums.TeamTactic.Attacking;
                    }
                    else // Away team might try to secure the draw
                    {
                        proposedTactic = Enums.TeamTactic.Defensive;
                    }
                }
                else if (teamToEvaluate.CurrentTactic != Enums.TeamTactic.Balanced)
                {
                    // Mid-game, revert to balanced if tied and not in a special tactic
                    proposedTactic = Enums.TeamTactic.Balanced;
                }
            }

            // Overriding conditions: Red cards (strongest influence)
            if (teamToEvaluate.CurrentEleven.Any(p => p.isSentOff))
            {
                // If a player is sent off, become very defensive
                proposedTactic = Enums.TeamTactic.Defensive;
            }

            // Only change tactic if it's different from the current one
            if (teamToEvaluate.CurrentTactic != proposedTactic)
            {
                teamToEvaluate.CurrentTactic = proposedTactic;
                //ShowMessage(string.Format("{0} changes tactics to: {1}!", teamToEvaluate.Name, teamToEvaluate.CurrentTactic));
            }
        }

        private int GetPressingStyleTriggerY(Enums.PressingStyle style, bool isHomeTeamDefending)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetPressingStyleTriggerY: style:{0},isHomeTeamDefending:{1}",
            //    style, isHomeTeamDefending));


            // Conceptual Y-coordinates:
            // Y=-1: GoalkeeperArea_Home
            // Y=0:  PenaltyArea_Home
            // Y=1:  HomeDefense_Third
            // Y=2:  Midfield
            // Y=3:  AwayAttack_Third (Home team's attacking third / Away team's defensive third)
            // Y=4:  PenaltyArea_Away
            // Y=5:  GoalkeeperArea_Away

            if (isHomeTeamDefending)
            {
                switch (style)
                {
                    case Enums.PressingStyle.VeryLow:
                    case Enums.PressingStyle.LowBlock: return 1; // Deepest press, typically in own defensive third
                    case Enums.PressingStyle.Standard:
                    case Enums.PressingStyle.MidBlock: return 2; // Press in midfield
                    case Enums.PressingStyle.HighPress:
                    case Enums.PressingStyle.VeryHigh: return 3; // Press high, in opponent's defensive third
                    case Enums.PressingStyle.None: return 0; // If no pressing, very deep, e.g., Penalty Area
                    default: return 2; // Default to Midfield
                }
            }
            else // Away Team Defending (values are still relative to Home goal's Y-axis)
            {
                // For the Away team, their "Low Block" is when the ball is deep in their half (higher Y value).
                // Their "High Press" is when the ball is deep in the Home team's half (lower Y value).
                switch (style)
                {
                    case Enums.PressingStyle.VeryLow:
                    case Enums.PressingStyle.LowBlock: return 3; // Press from their own Defensive Third (AwayAttack_)
                    case Enums.PressingStyle.Standard:
                    case Enums.PressingStyle.MidBlock: return 2; // Press from Midfield
                    case Enums.PressingStyle.HighPress:
                    case Enums.PressingStyle.VeryHigh: return 1; // Press high, in opponent's Defensive Third (HomeDefense_)
                    case Enums.PressingStyle.None: return 4; // If no pressing, very deep, e.g., Penalty Area
                    default: return 2; // Default to Midfield
                }
            }
        }


