        private Enums.PitchZone GetOpponentGoalkeeperArea(Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetOpponentGoalkeeperArea: attackingTeam:{0}",
            //    attackingTeam.Name));


            if (attackingTeam == HomeTeam) // If home team is attacking, they are shooting at away team's goal
            {
                return Enums.PitchZone.GoalkeeperArea_Away; // So, goal kick from away's GK area
            }
            else // If away team is attacking, they are shooting at home team's goal
            {
                return Enums.PitchZone.GoalkeeperArea_Home; // So, goal kick from home's GK area
            }
        }

        /// <summary>
        /// Maps a conceptual set piece zone to a concrete PitchZone, considering the attacking team's perspective.
        /// This is crucial for translating roles like 'NearPost' into the correct HomeDefense_NearPost or AwayAttack_NearPost.
        /// </summary>
        private Enums.PitchZone MapConceptualToPitchZone(
            Enums.ConceptualSetPieceZone conceptualZone,
            bool isAttackingTeamHome, // True if the team taking the corner/free kick is the Home team
            Enums.Flank attackingCornerFlank) // The flank of the corner/set piece from the attacking team's view
        {
            //LoggingStuff.LogMethodCall(string.Format("MapConceptualToPitchZone: conceptualZone:{0},isAttackingTeamHome:{1},attackingCornerFlank:{2}",
            //    conceptualZone, isAttackingTeamHome, attackingCornerFlank));


            // These mappings are critical and need to match your PitchZone definitions
            // for both Home and Away team perspectives.

            // Example mapping for a Home Team attacking (so they are trying to score into the Away team's goal)
            if (isAttackingTeamHome)
            {
                switch (conceptualZone)
                {
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_NearPost:
                        // If the corner is from the attacking Home team's Left, their near post is the Away team's Right post.
                        // This corresponds to the AwayAttack_RightFlank or DefensivePenaltyArea_NearPost (Right side for away).
                        return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.DefensivePenaltyArea_RightNearPost : Enums.PitchZone.DefensivePenaltyArea_LeftNearPost; // Needs specific zones like these
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_Central:
                        return Enums.PitchZone.DefensivePenaltyArea_Central;
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_FarPost:
                        return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.DefensivePenaltyArea_LeftFarPost : Enums.PitchZone.DefensivePenaltyArea_RightFarPost; // Needs specific zones like these
                    case Enums.ConceptualSetPieceZone.EdgeOfBox:
                        return Enums.PitchZone.Defensive_EdgeOfBox;
                    case Enums.ConceptualSetPieceZone.Midfield_Center:
                        return Enums.PitchZone.Midfield_Center;
                    // Add other mappings as needed
                    default:
                        return Enums.PitchZone.AwayAttack_Center; // Fallback
                }
            }
            // Example mapping for an Away Team attacking (so they are trying to score into the Home team's goal)
            else
            {
                switch (conceptualZone)
                {
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_NearPost:
                        // If the corner is from the attacking Away team's Left, their near post is the Home team's Right post.
                        return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.DefensivePenaltyArea_RightNearPost : Enums.PitchZone.DefensivePenaltyArea_LeftNearPost; // Needs specific zones like these
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_Central:
                        return Enums.PitchZone.DefensivePenaltyArea_Central;
                    case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_FarPost:
                        return (attackingCornerFlank == Enums.Flank.Left) ? Enums.PitchZone.DefensivePenaltyArea_LeftFarPost : Enums.PitchZone.DefensivePenaltyArea_RightFarPost; // Needs specific zones like these
                    case Enums.ConceptualSetPieceZone.EdgeOfBox:
                        return Enums.PitchZone.Defensive_EdgeOfBox;
                    case Enums.ConceptualSetPieceZone.Midfield_Center:
                        return Enums.PitchZone.Midfield_Center;
                    // Add other mappings as needed
                    default:
                        return Enums.PitchZone.HomeDefense_Center; // Fallback
                }
            }
        }

        /// <summary>
        /// Maps a player's primary role to a general attacking zone for fallback positioning.
        /// </summary>
        private Enums.PitchZone MapPlayerRoleToGeneralAttackingZone(Enums.PlayerRole playerRole, bool isHomeAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("MapPlayerRoleToGeneralAttackingZone: playerRole:{0},isHomeAttacking:{1}",
            //    playerRole, isHomeAttacking));


            if (isHomeAttacking)
            {
                switch (playerRole)
                {
                    case Enums.PlayerRole.Striker:
                    case Enums.PlayerRole.AttackingMidfielder:
                        return Enums.PitchZone.AwayAttack_Center;
                    case Enums.PlayerRole.Winger:
                        // You'd need more logic here to distinguish left/right wingers
                        return Enums.PitchZone.AwayAttack_LeftFlank;
                    case Enums.PlayerRole.CentralMidfielder:
                        return Enums.PitchZone.Midfield_Center;
                    default:
                        return Enums.PitchZone.Midfield_Center;
                }
            }
            else // Away team is attacking
            {
                switch (playerRole)
                {
                    case Enums.PlayerRole.Striker:
                    case Enums.PlayerRole.AttackingMidfielder:
                        return Enums.PitchZone.HomeDefense_Center;
                    case Enums.PlayerRole.Winger:
                        return Enums.PitchZone.HomeDefense_LeftFlank;
                    case Enums.PlayerRole.CentralMidfielder:
                        return Enums.PitchZone.Midfield_Center;
                    default:
                        return Enums.PitchZone.Midfield_Center;
                }
            }
        }

        /// <summary>
        /// Maps a player's primary role to a general defending zone for fallback positioning.
        /// </summary>
        private Enums.PitchZone MapPlayerRoleToGeneralDefendingZone(Enums.PlayerRole playerRole, bool isHomeDefending)
        {
            //LoggingStuff.LogMethodCall(string.Format("MapPlayerRoleToGeneralDefendingZone: playerRole:{0},isHomeDefending:{1}",
            //    playerRole, isHomeDefending));


            if (isHomeDefending)
            {
                switch (playerRole)
                {
                    case Enums.PlayerRole.CenterBack:
                    case Enums.PlayerRole.DefensiveMidfielder:
                        return Enums.PitchZone.HomeDefense_Center;
                    case Enums.PlayerRole.FullBack:
                        return Enums.PitchZone.HomeDefense_LeftFlank;
                    case Enums.PlayerRole.CentralMidfielder:
                        return Enums.PitchZone.Midfield_Center;
                    default:
                        return Enums.PitchZone.Midfield_Center;
                }
            }
            else // Away team is defending
            {
                switch (playerRole)
                {
                    case Enums.PlayerRole.CenterBack:
                    case Enums.PlayerRole.DefensiveMidfielder:
                        return Enums.PitchZone.AwayAttack_Center;
                    case Enums.PlayerRole.FullBack:
                        return Enums.PitchZone.AwayAttack_LeftFlank;
                    case Enums.PlayerRole.CentralMidfielder:
                        return Enums.PitchZone.Midfield_Center;
                    default:
                        return Enums.PitchZone.Midfield_Center;
                }
            }
        }

        /// <summary>
        /// Retrieves the PitchZone enum value corresponding to a given X, Y coordinate pair.
        /// </summary>
        /// <param name="x">The X-coordinate (lateral position on the pitch).</param>
        /// <param name="y">The Y-coordinate (longitudinal position on the pitch).</param>
        /// <param name="isHomeTeamPerspective">Optional: Can be used if there are zones that differ based on team perspective,
        /// but generally coordinates should map uniquely to a zone regardless of team.</param>
        /// <returns>The PitchZone matching the coordinates, or Enums.PitchZone.None if no match is found.</returns>
        private Enums.PitchZone GetZoneFromCoords(int x, int y, bool isHomeTeamPerspective = true) // Added default for isHomeTeamPerspective
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneFromCoords: x:{0},y:{1},isHomeTeamPerspective:{2}",
            //    x, y, isHomeTeamPerspective));


            // Iterate through the dictionary to find the matching coordinates
            foreach (var entry in _zoneCoordinates)
            {
                if (entry.Value.X == x && entry.Value.Y == y)
                {
                    // Found a match, return the PitchZone
                    return entry.Key;
                }
            }
            // If no zone matches the given coordinates, return None
            return Enums.PitchZone.None;
        }

        // Revised (conceptual) TranslateConceptualZone to be passed the "perspectiveTeam"
        private Enums.PitchZone TranslateConceptualZone(Enums.ConceptualSetPieceZone conceptualZone, Team perspectiveTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("TranslateConceptualZone: conceptualZone:{0},perspectiveTeam:{1}",
            //    conceptualZone, perspectiveTeam.Name));


            switch (conceptualZone)
            {
                case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_General:
                    // This now means "the penalty area of the team OPPOSITE to perspectiveTeam"
                    return (perspectiveTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
                case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_NearPost:
                case Enums.ConceptualSetPieceZone.OpponentPenaltyArea_FarPost:
                    return (perspectiveTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
                case Enums.ConceptualSetPieceZone.OpponentAttackingThird_CentralEdge:
                    return (perspectiveTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
                case Enums.ConceptualSetPieceZone.OpponentAttackingThird_Flank:
                    // This is still tricky. Needs more context (which side the corner is from).
                    // For simplicity, let's default to a generic attacking flank relative to perspective team
                    return (perspectiveTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_RightFlank; // Example mapping
                case Enums.ConceptualSetPieceZone.None:
                default:
                    return Enums.PitchZone.None;
            }
        }

        /// <summary>
        /// Calculates the zone for a near-post run during an attacking set-piece.
        /// This will be the zone in the penalty area closest to the free kick, along the goal line.
        /// </summary>
        /// <param name="freeKickZone">The zone where the free kick is taken.</param>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <returns>The PitchZone representing the near post area.</returns>
        private Enums.PitchZone GetNearPostZone(Enums.PitchZone freeKickZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetNearPostZone: freeKickZone:{0},isAttackingTeamHome:{1}",
            //    freeKickZone, isAttackingTeamHome));


            ZoneCoordinate freeKickCoords = GetZoneCoords(freeKickZone);
            Enums.PitchZone penaltyAreaCentral = isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            ZoneCoordinate penaltyAreaCoords = GetZoneCoords(penaltyAreaCentral);

            int targetX = penaltyAreaCoords.X; // Default to central
            int targetY = penaltyAreaCoords.Y; // Penalty Area Y

            // Determine the X-coordinate of the near post based on free kick's lateral position
            // The "near post" is the one on the same lateral side as the free kick.
            if (freeKickCoords.X < GetZoneCoords(Enums.PitchZone.Midfield_Center).X) // Free kick on left side (X=1 or 0)
            {
                targetX = GetZoneCoords(Enums.PitchZone.HomeDefense_LeftFlank).X; // Map to Left Flank X (1)
            }
            else if (freeKickCoords.X > GetZoneCoords(Enums.PitchZone.Midfield_Center).X) // Free kick on right side (X=3 or 4)
            {
                targetX = GetZoneCoords(Enums.PitchZone.HomeDefense_RightFlank).X; // Map to Right Flank X (3)
            }
            // If free kick is central (X=2), the "near post" could still be slightly left or right,
            // or just the central penalty area. For now, we'll aim for penaltyAreaCentral (X=2).

            // Attempt to get the specific zone. If not found, fallback to general penalty area center.
            Enums.PitchZone nearPostZone = GetZoneFromCoords(targetX, targetY, isAttackingTeamHome);
            if (nearPostZone == Enums.PitchZone.None)
            {
                // Fallback to the penalty area center if specific flank zone isn't directly mapped
                nearPostZone = penaltyAreaCentral;
            }
            return nearPostZone;
        }

        /// <summary>
        /// Calculates the zone for a far-post run during an attacking set-piece.
        /// This will be the zone in the penalty area furthest from the free kick, along the goal line.
        /// </summary>
        /// <param name="freeKickZone">The zone where the free kick is taken.</param>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <returns>The PitchZone representing the far post area.</returns>
        private Enums.PitchZone GetFarPostZone(Enums.PitchZone freeKickZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetFarPostZone: freeKickZone:{0},isAttackingTeamHome:{1}",
            //    freeKickZone, isAttackingTeamHome));


            ZoneCoordinate freeKickCoords = GetZoneCoords(freeKickZone);
            Enums.PitchZone penaltyAreaCentral = isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            ZoneCoordinate penaltyAreaCoords = GetZoneCoords(penaltyAreaCentral);

            int targetX = penaltyAreaCoords.X; // Default to central
            int targetY = penaltyAreaCoords.Y; // Penalty Area Y

            // Determine the X-coordinate of the far post based on free kick's lateral position
            // The "far post" is the one on the opposite lateral side as the free kick.
            if (freeKickCoords.X < GetZoneCoords(Enums.PitchZone.Midfield_Center).X) // Free kick on left side (X=1 or 0)
            {
                targetX = GetZoneCoords(Enums.PitchZone.HomeDefense_RightFlank).X; // Map to Right Flank X (3)
            }
            else if (freeKickCoords.X > GetZoneCoords(Enums.PitchZone.Midfield_Center).X) // Free kick on right side (X=3 or 4)
            {
                targetX = GetZoneCoords(Enums.PitchZone.HomeDefense_LeftFlank).X; // Map to Left Flank X (1)
            }
            // If free kick is central (X=2), the "far post" concept is less distinct, could choose either flank or central
            // For central free kicks, let's arbitrarily send to the right flank's X for "far post" or a central area.
            // Given your zones, X=3 (right flank) could be a good 'far post' for central FKs.
            else
            {
                targetX = GetZoneCoords(Enums.PitchZone.HomeDefense_RightFlank).X; // Far post for central FKs, often slightly wide.
            }


            Enums.PitchZone farPostZone = GetZoneFromCoords(targetX, targetY, isAttackingTeamHome);
            if (farPostZone == Enums.PitchZone.None)
            {
                farPostZone = penaltyAreaCentral; // Fallback
            }
            return farPostZone;
        }

        // In your MatchEngine or a similar helper class
        /// <summary>
        /// Determines the specific PitchZone for the "Edge of Box" based on the attacking team's direction.
        /// This assumes a standard pitch layout where the edge of the box is in front of the penalty area.
        /// </summary>
        /// <param name="isAttackingHome">True if the home team is attacking, false if away team is attacking.</param>
        /// <returns>The PitchZone representing the edge of the box for the attacking side.</returns>
        private Enums.PitchZone GetEdgeOfBoxZone(bool isAttackingHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetEdgeOfBoxZone: isAttackingHome:{0}",
            //    isAttackingHome));


            // The "EdgeOfBox" would typically be the attacking team's attacking midfield central zone
            // just outside the opponent's penalty area.
            // Based on your PitchZone enum:
            // If home team is attacking, they are in their 'Attack' zones, targeting 'AwayDefense'
            // So, it would be the 'AwayAttack_Center' zone if that represents just outside the penalty area.
            // Or, if your zones are set up differently, it might be a specific midfield zone.

            // Assuming AwayAttack_Center and HomeDefense_Center are the central attacking/defending zones
            // that conceptually represent 'just outside the opponent's box'.
            if (isAttackingHome)
            {
                // Home team is attacking, so they are pushing into the 'Away' attacking zones.
                // The edge of the box for them would be the central zone right before the AwayPenaltyArea.
                return Enums.PitchZone.AwayAttack_Center;
            }
            else
            {
                // Away team is attacking, so they are pushing into the 'Home' attacking zones.
                // The edge of the box for them would be the central zone right before the HomePenaltyArea.
                return Enums.PitchZone.HomeDefense_Center; // This might be better named HomeAttack_Center if it's the attacking third for away team. Adjust as per your zone map's logical flow.
            }
            // IMPORTANT: Verify these zone mappings with your _zoneCoordinates to ensure they are indeed 'edge of box'
            // For example, if AwayAttack_Center is too deep, you might need a new zone like 'PenaltyArc_Away'.
        }

        /// <summary>
        /// Determines a safe zone for a short layoff pass, typically one adjacent to the free kick taker.
        /// Prioritizes zones with fewer defenders.
        /// </summary>
        /// <param name="freeKickZone">The zone where the free kick is taken.</param>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <returns>A PitchZone for a short pass.</returns>
        private Enums.PitchZone GetSafeShortPassZone(Enums.PitchZone freeKickZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetSafeShortPassZone: freeKickZone:{0},isAttackingTeamHome:{1}",
            //    freeKickZone, isAttackingTeamHome));


            List<Enums.PitchZone> potentialShortPassZones = new List<Enums.PitchZone>();

            // Get immediate adjacent zones
            foreach (Enums.PitchZone adjacentZone in GetAdjacentZones(freeKickZone, isAttackingTeamHome)) // Using your GetAdjacentZones
            {
                if (adjacentZone != Enums.PitchZone.None)
                {
                    potentialShortPassZones.Add(adjacentZone);
                }
            }

            // Add zones slightly behind (towards own goal) for a safer option, if not already covered by adjacent
            Enums.PitchZone zoneBehind = GetZoneBehind(freeKickZone, isAttackingTeamHome);
            if (zoneBehind != Enums.PitchZone.None && !potentialShortPassZones.Contains(zoneBehind))
            {
                potentialShortPassZones.Add(zoneBehind);
            }

            // Filter out zones too close to the opponent's goal or too deep in own half for a "short" pass target
            // We want relatively neutral or slightly attacking zones near the ball carrier.
            ZoneCoordinate freeKickCoords = GetZoneCoords(freeKickZone);
            ZoneCoordinate limitCoord = isAttackingTeamHome
                ? GetZoneCoords(Enums.PitchZone.AwayAttack_Center)
                : GetZoneCoords(Enums.PitchZone.HomeDefense_Center);

            // Use RemoveAll instead of Where and ToList
            potentialShortPassZones.RemoveAll(z =>
            {
                ZoneCoordinate zCoords = GetZoneCoords(z);
                if (isAttackingTeamHome)
                    return zCoords.Y > limitCoord.Y;
                else
                    return zCoords.Y < limitCoord.Y;
            });

            Enums.PitchZone bestZone = Enums.PitchZone.None;
            double bestScore = -1.0;

            foreach (var zone in potentialShortPassZones)
            {
                double currentScore = 100.0; // Base score

                // Penalize for defenders in zone
                currentScore -= GetPlayersInZone(DefendingTeam, zone).Count * 20;

                // Penalize for attacking players already in zone (avoid crowding)
                currentScore -= GetPlayersInZone(AttackingTeam, zone).Count * 5;

                // Reward for being closer to the free kick taker (it's a "short" pass)
                currentScore -= GetZoneDistance(freeKickZone, zone, isAttackingTeamHome) * 10;

                // Small bonus for being slightly ahead or central, making it a more progressive option
                ZoneCoordinate zoneCoords = GetZoneCoords(zone);
                if (isAttackingTeamHome)
                {
                    if (zoneCoords.Y > freeKickCoords.Y) currentScore += 5; // Ahead
                    if (zoneCoords.X == 2) currentScore += 5; // Central
                }
                else
                {
                    if (zoneCoords.Y < freeKickCoords.Y) currentScore += 5; // Ahead
                    if (zoneCoords.X == 2) currentScore += 5; // Central
                }


                if (currentScore > bestScore)
                {
                    bestScore = currentScore;
                    bestZone = zone;
                }
            }

            // Fallback if no ideal zone found, try zone slightly behind or lateral
            if (bestZone == Enums.PitchZone.None)
            {
                Enums.PitchZone fallbackZone = GetZoneBehind(freeKickZone, isAttackingTeamHome);
                if (fallbackZone == Enums.PitchZone.None) fallbackZone = GetLateralZone(freeKickZone, 1, isAttackingTeamHome);
                if (fallbackZone == Enums.PitchZone.None) fallbackZone = GetLateralZone(freeKickZone, -1, isAttackingTeamHome);
                bestZone = fallbackZone != Enums.PitchZone.None ? fallbackZone : freeKickZone; // Last resort: stay in free kick zone
            }

            return bestZone;
        }


        /// <summary>
        /// Finds the most advantageous central attacking zone (penalty area or attacking midfield)
        /// for players to move into when "CrowdTheBox" routine is selected.
        /// </summary>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <param name="freeKickZone">The free kick origin zone (used for proximity scoring).</param>
        /// <returns>A PitchZone for crowding the box.</returns>
        private Enums.PitchZone GetBestCentralAttackingZone(bool isAttackingTeamHome, Enums.PitchZone freeKickZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetBestCentralAttackingZone: isAttackingTeamHome:{0},freeKickZone:{1}",
            //    isAttackingTeamHome, freeKickZone));


            List<Enums.PitchZone> candidateZones = new List<Enums.PitchZone>();

            // Define the primary target zones for crowding the box
            // Penalty area central
            candidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home);
            // Attacking third central
            candidateZones.Add(isAttackingTeamHome ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center);

            // Also consider flanks of the penalty area if relevant
            // Example: if attacking team is Home, also consider AwayAttack_LeftFlank, AwayAttack_RightFlank.
            if (isAttackingTeamHome)
            {
                candidateZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                candidateZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
            }
            else
            {
                candidateZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                candidateZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
            }
            // Filter out any 'None' zones if your GetZoneFromCoords can return them for non-existent coords
            candidateZones.RemoveAll(z => z == Enums.PitchZone.None);
            for (int i = candidateZones.Count - 1; i > 0; i--)
            {
                if (candidateZones.IndexOf(candidateZones[i]) < i)
                {
                    candidateZones.RemoveAt(i);
                }
            }

            Enums.PitchZone bestZone = Enums.PitchZone.None;
            double bestScore = -1.0;

            foreach (var zone in candidateZones)
            {
                double currentScore = 0.0;

                // Reward for being closer to the opponent's goal (higher Y for home attacking, lower Y for away attacking)
                ZoneCoordinate zoneCoords = GetZoneCoords(zone);
                if (isAttackingTeamHome)
                {
                    currentScore += (zoneCoords.Y - GetZoneCoords(Enums.PitchZone.Midfield_Center).Y) * 10; // Reward for being in attacking half
                }
                else
                {
                    currentScore += (GetZoneCoords(Enums.PitchZone.Midfield_Center).Y - zoneCoords.Y) * 10; // Reward for being in attacking half
                }

                // Penalize for defenders in zone, but less severely than for short passes (crowding is part of the routine)
                currentScore -= GetPlayersInZone(DefendingTeam, zone).Count * 10;

                // Penalize for too many attacking players already in zone (avoid excessive congestion)
                currentScore -= GetPlayersInZone(AttackingTeam, zone).Count * 5;

                // Reward for being closer to the free kick zone (especially for crosses)
                currentScore -= GetZoneDistance(freeKickZone, zone, isAttackingTeamHome) * 3; // Smaller penalty for distance

                if (currentScore > bestScore)
                {
                    bestScore = currentScore;
                    bestZone = zone;
                }
            }

            // Fallback: If no good zone found, default to the central penalty area
            if (bestZone == Enums.PitchZone.None)
            {
                bestZone = isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            }

            return bestZone;
        }

        // Updated: GetZoneForPlayerInFormation method (from previous response)
        public Enums.PitchZone GetZoneForPlayerInFormation(Enums.Positions playerPosition, Enums.Formation formation, bool isHomeTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneForPlayerInFormation: playerPosition:{0},formation:{1},isHomeTeam:{2}",
            //    playerPosition, formation, isHomeTeam));


            Enums.PitchZone baseZone;

            switch (formation)
            {
                case Enums.Formation.FourThreeThree:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.LeftWingForward: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightWingForward: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.ThreeFourTwoOne:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralAttackingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.ThreeFiveTwo:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.FourFourOneOne:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.CentralAttackingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
