                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.FourTwoThreeOne:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralAttackingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.LeftWingForward: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightWingForward: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.FourOneTwoOneTwo:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.CentralAttackingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.ThreeFourthree:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.LeftWingForward: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightWingForward: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;

                case Enums.Formation.FiveThreeTwo:
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftMidfielder: baseZone = Enums.PitchZone.Midfield_LeftFlank; break;
                        case Enums.Positions.RightMidfielder: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.CentralMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;
                case Enums.Formation.FourTwoOneThree: // New formation added
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.LeftBack: baseZone = Enums.PitchZone.HomeDefense_LeftFlank; break;
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_RightFlank; break;
                        case Enums.Positions.CentralDefendingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break; // The two '2' in 4-2-1-3 (DMs)
                        case Enums.Positions.CentralAttackingMidfielder: baseZone = Enums.PitchZone.Midfield_Center; break; // The '1' in 4-2-1-3 (CAM)
                        case Enums.Positions.LeftWingForward: baseZone = Enums.PitchZone.Midfield_LeftFlank; break; // The wide attackers (part of the '3')
                        case Enums.Positions.RightWingForward: baseZone = Enums.PitchZone.Midfield_RightFlank; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break; // The main striker (part of the '3')
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;
                default:
                    //ShowMessage("Formation " + formation + " not fully defined for player positioning. Using generic zones.");
                    switch (playerPosition)
                    {
                        case Enums.Positions.Goalkeeper: baseZone = Enums.PitchZone.GoalkeeperArea_Home; break;
                        case Enums.Positions.CenterBack:
                        case Enums.Positions.LeftBack:
                        case Enums.Positions.RightBack: baseZone = Enums.PitchZone.HomeDefense_Center; break;
                        case Enums.Positions.CentralDefendingMidfielder:
                        case Enums.Positions.CentralMidfielder:
                        case Enums.Positions.CentralAttackingMidfielder:
                        case Enums.Positions.LeftMidfielder:
                        case Enums.Positions.RightMidfielder:
                        case Enums.Positions.LeftWingForward:
                        case Enums.Positions.RightWingForward: baseZone = Enums.PitchZone.Midfield_Center; break;
                        case Enums.Positions.Striker: baseZone = Enums.PitchZone.KickOffCircle; break;
                        default: baseZone = Enums.PitchZone.Midfield_Center; break;
                    }
                    break;
            }

            if (!isHomeTeam)
            {
                switch (baseZone)
                {
                    case Enums.PitchZone.GoalkeeperArea_Home: return Enums.PitchZone.GoalkeeperArea_Away;
                    case Enums.PitchZone.PenaltyArea_Home: return Enums.PitchZone.PenaltyArea_Away;

                    case Enums.PitchZone.HomeDefense_LeftFlank: return Enums.PitchZone.AwayAttack_RightFlank;
                    case Enums.PitchZone.HomeDefense_Center: return Enums.PitchZone.AwayAttack_Center;
                    case Enums.PitchZone.HomeDefense_RightFlank: return Enums.PitchZone.AwayAttack_LeftFlank;

                    case Enums.PitchZone.Midfield_LeftFlank: return Enums.PitchZone.Midfield_RightFlank;
                    case Enums.PitchZone.Midfield_Center: return Enums.PitchZone.Midfield_Center;
                    case Enums.PitchZone.Midfield_RightFlank: return Enums.PitchZone.Midfield_LeftFlank;

                    case Enums.PitchZone.KickOffCircle: return Enums.PitchZone.KickOffCircle;

                    case Enums.PitchZone.AwayAttack_LeftFlank: return Enums.PitchZone.HomeDefense_RightFlank;
                    case Enums.PitchZone.AwayAttack_Center: return Enums.PitchZone.HomeDefense_Center;
                    case Enums.PitchZone.AwayAttack_RightFlank: return Enums.PitchZone.HomeDefense_LeftFlank;

                    default: return baseZone;
                }
            }

            return baseZone;
        }

        /// <summary>
        /// Provides a numerical depth for each PitchZone, from Home Goal (0.0) to Away Goal (10.0).
        /// This allows for more accurate distance calculations.
        /// </summary>
        /// <param name="zone">The PitchZone to get the depth for.</param>
        /// <returns>A float representing the depth (0.0 = Home goal line, 10.0 = Away goal line).</returns>
        private float GetPitchZoneDepth(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetPitchZoneDepth: zone:{0}", zone));

            //
            switch (zone)
            {
                case Enums.PitchZone.GoalkeeperArea_Home: return 0.0f;
                case Enums.PitchZone.PenaltyArea_Home: return 0.5f; // Just in front of home goal
                case Enums.PitchZone.HomeDefense_LeftFlank:
                case Enums.PitchZone.HomeDefense_Center:
                case Enums.PitchZone.HomeDefense_RightFlank: return 2.0f; // Defensive third of home team

                case Enums.PitchZone.Midfield_LeftFlank:
                case Enums.PitchZone.Midfield_Center:
                case Enums.PitchZone.Midfield_RightFlank: return 5.0f; // Exact center of the pitch

                case Enums.PitchZone.AwayAttack_LeftFlank:
                case Enums.PitchZone.AwayAttack_Center:
                case Enums.PitchZone.AwayAttack_RightFlank: return 8.0f; // Attacking third of home team (defensive third of away team)
                case Enums.PitchZone.PenaltyArea_Away: return 9.5f; // Just in front of away goal
                case Enums.PitchZone.GoalkeeperArea_Away: return 10.0f;

                case Enums.PitchZone.KickOffCircle: return 5.0f; // Center of pitch
                // Corner zones are on flanks, but for depth calculation, we approximate their general third
                case Enums.PitchZone.Corner_HomeLeft:
                case Enums.PitchZone.Corner_HomeRight: return 0.2f; // Very close to home goal
                case Enums.PitchZone.Corner_AwayLeft:
                case Enums.PitchZone.Corner_AwayRight: return 9.8f; // Very close to away goal

                default: return 5.0f; // Default to midfield for unknown zones
            }
        }

        /// <summary>
        /// Extracts the flank (Left, Center, Right) from a PitchZone.
        /// Useful for aligning wall positions with kick location.
        /// </summary>
        /// <param name="zone">The PitchZone.</param>
        /// <returns>A string representing the flank ("Left", "Center", "Right"), or "Center" if not applicable.</returns>
        private string GetZoneFlank(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneFlank: zone:{0}", zone));


            if (EnumCache<Enums.PitchZone>.ToString(zone).Contains("Left")) return "Left";
            if (EnumCache<Enums.PitchZone>.ToString(zone).Contains("Right")) return "Right";
            return "Center"; // Default for center, goal areas, or unknown
        }

        /// <summary>
        /// Returns the GoalkeeperArea for the given player's team.
        /// </summary>
        private Enums.PitchZone GetPlayerGoalkeeperArea(Player player)
        {
            return player.Team == HomeTeam ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
        }

        /// <summary>
        /// Checks if a given pitch zone is in the attacking half for the specified team.
        /// </summary>
        /// <param name="zone">The PitchZone to check.</param>
        /// <param name="team">The team for whom to determine the attacking half (e.g., homeTeam or awayTeam).</param>
        /// <returns>True if the zone is in the attacking half for the specified team, false otherwise.</returns>
        private bool IsBallInAttackingHalf(Enums.PitchZone zone, Team team)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInAttackingHalf: zone:{0},team:{1}",
            //    zone, team.Name));


            if (team == HomeTeam) // If home team is attacking, their attacking half is the 'Away' zones
            {
                return zone == Enums.PitchZone.AwayAttack_LeftFlank ||
                       zone == Enums.PitchZone.AwayAttack_Center ||
                       zone == Enums.PitchZone.AwayAttack_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Away ||
                       zone == Enums.PitchZone.GoalkeeperArea_Away ||
                       zone == Enums.PitchZone.Corner_AwayLeft ||
                       zone == Enums.PitchZone.Corner_AwayRight ||
                       zone == Enums.PitchZone.Midfield_Center || // Midfield center is technically neutral but can be considered attacking for forward play
                       zone == Enums.PitchZone.Midfield_LeftFlank ||
                       zone == Enums.PitchZone.Midfield_RightFlank;
            }
            else // If away team is attacking, their attacking half is the 'Home' zones
            {
                return zone == Enums.PitchZone.HomeDefense_LeftFlank || // These are the 'defensive' zones for home, but attacking for away
                       zone == Enums.PitchZone.HomeDefense_Center ||
                       zone == Enums.PitchZone.HomeDefense_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Home ||
                       zone == Enums.PitchZone.GoalkeeperArea_Home ||
                       zone == Enums.PitchZone.Corner_HomeLeft ||
                       zone == Enums.PitchZone.Corner_HomeRight ||
                       zone == Enums.PitchZone.Midfield_Center ||
                       zone == Enums.PitchZone.Midfield_LeftFlank ||
                       zone == Enums.PitchZone.Midfield_RightFlank;
            }
        }

        /// <summary>
        /// Gets the central attacking zone for a given team (i.e., the center of the opponent's attacking third).
        /// </summary>
        private Enums.PitchZone GetAttackingCentralZoneForTeam(Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetAttackingCentralZoneForTeam: playerTeam:{0}",
            //    playerTeam.Name));


            return (playerTeam == HomeTeam) ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
        }

        /// <summary>
        /// Gets the opponent's penalty area zone for a given team.
        /// </summary>
        private Enums.PitchZone GetOpponentPenaltyAreaForTeam(Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetOpponentPenaltyAreaForTeam: playerTeam:{0}",
            //    playerTeam.Name));


            return (playerTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
        }

        /// <summary>
        /// Gets the general midfield zone where attacking midfielders would operate (relative to opponent).
        /// For this enum, Midfield_Center is the most appropriate general zone.
        /// </summary>
        private Enums.PitchZone GetOpponentMidfieldZoneForTeam(Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetOpponentMidfieldZoneForTeam: playerTeam:{0}",
            //    playerTeam.Name));


            return Enums.PitchZone.Midfield_Center;
        }

        /// <summary>
        /// Checks if two zones are "logically close" to each other, allowing a player to move directly
        /// to the ball's zone if their target is nearby. This version adds more comprehensive
        /// spatial proximity checks including adjacencies between different thirds of the pitch.
        /// </summary>
        private bool AreZonesLogicallyClose(Enums.PitchZone zone1, Enums.PitchZone zone2, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("AreZonesLogicallyClose: zone1:{0},zone2:{1},playerTeam:{2}",
            //    zone1, zone2, playerTeam.Name));


            if (zone1 == zone2) return true; // Same zone is always close

            bool isHomeTeam = (playerTeam == HomeTeam);

            // --- Adjacency within the same logical third ---

            // Midfield adjacency: All midfield zones are considered close to each other.
            bool isMidfield1 = IsMidfieldZone(zone1);
            bool isMidfield2 = IsMidfieldZone(zone2);
            if (isMidfield1 && isMidfield2) return true;

            // Defensive third adjacency (relative to the player's team)
            bool isOurDefensive1 = IsOurDefensiveZone(zone1, playerTeam);
            bool isOurDefensive2 = IsOurDefensiveZone(zone2, playerTeam);
            if (isOurDefensive1 && isOurDefensive2) return true;

            // Attacking third adjacency (relative to the player's team, i.e., opponent's defensive third)
            bool isOurAttacking1 = IsOurAttackingZone(zone1, playerTeam);
            bool isOurAttacking2 = IsOurAttackingZone(zone2, playerTeam);
            if (isOurAttacking1 && isOurAttacking2) return true;

            // --- Adjacency between different logical thirds ---

            // Defensive-Midfield Adjacency
            // If one zone is defensive and the other is midfield, check for logical adjacency.
            if ((isOurDefensive1 && isMidfield2) || (isMidfield1 && isOurDefensive2))
            {
                // Defensive Center is close to Midfield Center
                if ((zone1 == (isHomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center) && zone2 == Enums.PitchZone.Midfield_Center) ||
                    (zone2 == (isHomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center) && zone1 == Enums.PitchZone.Midfield_Center))
                    return true;

                // Defensive Flanks are close to Midfield Flanks
                if ((zone1 == (isHomeTeam ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_LeftFlank) && zone2 == Enums.PitchZone.Midfield_LeftFlank) ||
                    (zone2 == (isHomeTeam ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_LeftFlank) && zone1 == Enums.PitchZone.Midfield_LeftFlank))
                    return true;
                if ((zone1 == (isHomeTeam ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_RightFlank) && zone2 == Enums.PitchZone.Midfield_RightFlank) ||
                    (zone2 == (isHomeTeam ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_RightFlank) && zone1 == Enums.PitchZone.Midfield_RightFlank))
                    return true;

                // Penalty area can be close to defensive center
                if (((zone1 == (isHomeTeam ? Enums.PitchZone.PenaltyArea_Home : Enums.PitchZone.PenaltyArea_Away) || zone1 == (isHomeTeam ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away)) && zone2 == (isHomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center)) ||
                    ((zone2 == (isHomeTeam ? Enums.PitchZone.PenaltyArea_Home : Enums.PitchZone.PenaltyArea_Away) || zone2 == (isHomeTeam ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away)) && zone1 == (isHomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center)))
                    return true;
            }

            // Midfield-Attacking Adjacency
            // If one zone is midfield and the other is attacking, check for logical adjacency.
            if ((isMidfield1 && isOurAttacking2) || (isOurAttacking1 && isMidfield2))
            {
                // Midfield Center is close to Attacking Center
                if ((zone1 == Enums.PitchZone.Midfield_Center && zone2 == (isHomeTeam ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center)) ||
                    (zone2 == Enums.PitchZone.Midfield_Center && zone1 == (isHomeTeam ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center)))
                    return true;

                // Midfield Flanks are close to Attacking Flanks
                if ((zone1 == Enums.PitchZone.Midfield_LeftFlank && zone2 == (isHomeTeam ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_LeftFlank)) ||
                    (zone2 == Enums.PitchZone.Midfield_LeftFlank && zone1 == (isHomeTeam ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_LeftFlank)))
                    return true;
                if ((zone1 == Enums.PitchZone.Midfield_RightFlank && zone2 == (isHomeTeam ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.HomeDefense_RightFlank)) ||
                    (zone2 == Enums.PitchZone.Midfield_RightFlank && zone1 == (isHomeTeam ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.HomeDefense_RightFlank)))
                    return true;

                // Attacking penalty area can be close to attacking center
                if (((zone1 == (isHomeTeam ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home) || zone1 == (isHomeTeam ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home)) && zone2 == (isHomeTeam ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center)) ||
                    ((zone2 == (isHomeTeam ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home) || zone2 == (isHomeTeam ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home)) && zone1 == (isHomeTeam ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center)))
                    return true;
            }

            return false;
        }

        // --- New Helper Methods for AreZonesLogicallyClose ---

        private bool IsMidfieldZone(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsMidfieldZone: zone:{0}", zone));


            return zone == Enums.PitchZone.Midfield_LeftFlank ||
                   zone == Enums.PitchZone.Midfield_Center ||
                   zone == Enums.PitchZone.Midfield_RightFlank ||
                   zone == Enums.PitchZone.KickOffCircle; // KickOffCircle is effectively central midfield
        }

        private bool IsOurDefensiveZone(Enums.PitchZone zone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsOurDefensiveZone: zone:{0},playerTeam:{1}",
            //    zone, playerTeam.Name));


            bool isHomeTeam = (playerTeam == HomeTeam);
            if (isHomeTeam)
            {
                return zone == Enums.PitchZone.HomeDefense_LeftFlank ||
                       zone == Enums.PitchZone.HomeDefense_Center ||
                       zone == Enums.PitchZone.HomeDefense_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Home ||
                       zone == Enums.PitchZone.GoalkeeperArea_Home ||
                       zone == Enums.PitchZone.Corner_HomeLeft ||
                       zone == Enums.PitchZone.Corner_HomeRight;
            }
            else // Away Team's defensive zone is Home's attacking zone
            {
                // Away team's own goal is in the "Away" Penalty/Goalkeeper area, which implies Away team's defense is the "Away Attack" third in the enum.
                // This is due to the enum being named from the Home team's field perspective.
                return zone == Enums.PitchZone.AwayAttack_LeftFlank ||
                       zone == Enums.PitchZone.AwayAttack_Center ||
                       zone == Enums.PitchZone.AwayAttack_RightFlank ||
                       zone == Enums.PitchZone.PenaltyArea_Away ||
                       zone == Enums.PitchZone.GoalkeeperArea_Away ||
                       zone == Enums.PitchZone.Corner_AwayLeft ||
                       zone == Enums.PitchZone.Corner_AwayRight;
            }
        }

        private bool IsOurAttackingZone(Enums.PitchZone zone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsOurAttackingZone: zone:{0},playerTeam:{1}",
            //    zone, playerTeam.Name));


            // If it's not a midfield zone and not our defensive zone, it's our attacking zone.
            // This implicitly covers the opponent's defensive third.
            return !IsMidfieldZone(zone) && !IsOurDefensiveZone(zone, playerTeam);
        }

        /// <summary>
        /// Gets zones immediately ahead of the current zone in the direction of attack.
        /// This method is crucial for players making forward runs.
        /// </summary>
        private Enums.PitchZone GetZoneAhead(Enums.PitchZone currentZone, bool isHomeTeamAttacking)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneAhead: currentZone:{0},isHomeTeamAttacking:{1}",
            //    currentZone, isHomeTeamAttacking));


            if (isHomeTeamAttacking)
            {
                // Home team attacking -> moving towards Away goal (zones like Midfield_ and AwayAttack_)
                switch (currentZone)
                {
                    case Enums.PitchZone.GoalkeeperArea_Home: return Enums.PitchZone.HomeDefense_Center;
                    case Enums.PitchZone.PenaltyArea_Home: return Enums.PitchZone.HomeDefense_Center; // Push out of own box
                    case Enums.PitchZone.HomeDefense_LeftFlank: return Enums.PitchZone.Midfield_LeftFlank;
                    case Enums.PitchZone.HomeDefense_Center: return Enums.PitchZone.Midfield_Center;
                    case Enums.PitchZone.HomeDefense_RightFlank: return Enums.PitchZone.Midfield_RightFlank;

                    case Enums.PitchZone.Midfield_LeftFlank: return Enums.PitchZone.AwayAttack_LeftFlank;
                    case Enums.PitchZone.Midfield_Center: return Enums.PitchZone.AwayAttack_Center;
                    case Enums.PitchZone.Midfield_RightFlank: return Enums.PitchZone.AwayAttack_RightFlank;

                    case Enums.PitchZone.AwayAttack_LeftFlank: return Enums.PitchZone.PenaltyArea_Away; // Converge to central penalty area
                    case Enums.PitchZone.AwayAttack_Center: return Enums.PitchZone.PenaltyArea_Away;
                    case Enums.PitchZone.AwayAttack_RightFlank: return Enums.PitchZone.PenaltyArea_Away;

                    case Enums.PitchZone.KickOffCircle: return Enums.PitchZone.AwayAttack_Center;
                }
            }
            else // Away team attacking -> moving towards Home goal (zones like Midfield_ and HomeDefense_)
            {
                switch (currentZone)
                {
                    case Enums.PitchZone.GoalkeeperArea_Away: return Enums.PitchZone.PenaltyArea_Away; // Pushing out of their own GK area
                    case Enums.PitchZone.PenaltyArea_Away: return Enums.PitchZone.AwayAttack_Center; // Pushing out of their own box (which is the Home team's attacking center)
                    case Enums.PitchZone.AwayAttack_LeftFlank: return Enums.PitchZone.Midfield_LeftFlank; // Away attacking from their defensive flank
                    case Enums.PitchZone.AwayAttack_Center: return Enums.PitchZone.Midfield_Center;
                    case Enums.PitchZone.AwayAttack_RightFlank: return Enums.PitchZone.Midfield_RightFlank;

                    case Enums.PitchZone.Midfield_LeftFlank: return Enums.PitchZone.HomeDefense_LeftFlank; // Away attacking into Home's defensive flank
                    case Enums.PitchZone.Midfield_Center: return Enums.PitchZone.HomeDefense_Center;
                    case Enums.PitchZone.Midfield_RightFlank: return Enums.PitchZone.HomeDefense_RightFlank;

                    case Enums.PitchZone.HomeDefense_LeftFlank: return Enums.PitchZone.PenaltyArea_Home; // Away attacking into Home's penalty area
                    case Enums.PitchZone.HomeDefense_Center: return Enums.PitchZone.PenaltyArea_Home;
                    case Enums.PitchZone.HomeDefense_RightFlank: return Enums.PitchZone.PenaltyArea_Home;

                    case Enums.PitchZone.KickOffCircle: return Enums.PitchZone.HomeDefense_Center; // From kickoff, away team pushes towards home's goal
                }
            }
            return Enums.PitchZone.None; // Default case
        }

        /// <summary>
        /// Gets a flank zone ahead, specifically for wide players making runs.
        /// This needs to carefully map based on your specific PitchZone definitions.
        /// </summary>
        private Enums.PitchZone GetFlankZoneAhead(Enums.PitchZone currentZone, bool isHomeTeamAttacking, Enums.Positions playerPosition)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetFlankZoneAhead: currentZone:{0},isHomeTeamAttacking:{1},playerPosition:{2}",
            //    currentZone, isHomeTeamAttacking, playerPosition));


            // This method assumes playerPosition (LW/RW/LM/RM) matches the desired flank.
            // It returns a *flank* zone that is further forward.

            if (isHomeTeamAttacking)
            {
                if (playerPosition == Enums.Positions.LeftWingForward || playerPosition == Enums.Positions.LeftMidfielder)
                {
                    switch (currentZone)
                    {
                        case Enums.PitchZone.HomeDefense_LeftFlank: return Enums.PitchZone.Midfield_LeftFlank;
                        case Enums.PitchZone.Midfield_LeftFlank: return Enums.PitchZone.AwayAttack_LeftFlank;
                        case Enums.PitchZone.AwayAttack_LeftFlank: return Enums.PitchZone.PenaltyArea_Away; // Converge to central penalty area
                    }
                }
                else if (playerPosition == Enums.Positions.RightWingForward || playerPosition == Enums.Positions.RightMidfielder)
                {
                    switch (currentZone)
                    {
                        case Enums.PitchZone.HomeDefense_RightFlank: return Enums.PitchZone.Midfield_RightFlank;
                        case Enums.PitchZone.Midfield_RightFlank: return Enums.PitchZone.AwayAttack_RightFlank;
                        case Enums.PitchZone.AwayAttack_RightFlank: return Enums.PitchZone.PenaltyArea_Away; // Converge to central penalty area
                    }
                }
            }
            else // Away team attacking
            {
                // For away team, they attack towards the 'Home' side of the pitch
                // Note: From Home's perspective, HomeDefense_LeftFlank is on the Home's left,
                // but for Away attacking, it's on their *right* as they face the Home goal.
                // I'll assume playerPosition refers to the player's *role* on their team, not the field's fixed left/right.
                // So, a "LeftWingForward" for the away team will try to attack down the field's left flank.
                if (playerPosition == Enums.Positions.LeftWingForward || playerPosition == Enums.Positions.LeftMidfielder)
                {
                    switch (currentZone)
                    {
                        case Enums.PitchZone.AwayAttack_LeftFlank: return Enums.PitchZone.Midfield_LeftFlank; // From their defense into midfield
                        case Enums.PitchZone.Midfield_LeftFlank: return Enums.PitchZone.HomeDefense_LeftFlank; // From midfield into attacking third (Home's defense)
                        case Enums.PitchZone.HomeDefense_LeftFlank: return Enums.PitchZone.PenaltyArea_Home; // Into penalty area
                    }
                }
                else if (playerPosition == Enums.Positions.RightWingForward || playerPosition == Enums.Positions.RightMidfielder)
                {
                    switch (currentZone)
                    {
                        case Enums.PitchZone.AwayAttack_RightFlank: return Enums.PitchZone.Midfield_RightFlank; // From their defense into midfield
                        case Enums.PitchZone.Midfield_RightFlank: return Enums.PitchZone.HomeDefense_RightFlank; // From midfield into attacking third (Home's defense)
                        case Enums.PitchZone.HomeDefense_RightFlank: return Enums.PitchZone.PenaltyArea_Home; // Into penalty area
                    }
                }
            }
            return Enums.PitchZone.None;
        }

        /// <summary>
        /// Returns a list of zones logically adjacent (connected) to the given zone.
        /// This is crucial for player movement and pass calculations.
        /// This mapping is static and doesn't depend on the team perspective for its adjacency.
        /// </summary>
        /// <summary>
        /// Retrieves the pre-calculated list of zones logically adjacent (connected) to the given zone.
        /// This mapping is static and doesn't depend on the team perspective for its adjacency.
        /// The returned collection is read-only to prevent external modification of cached data.
        /// </summary>
        public ReadOnlyCollection<Enums.PitchZone> GetAdjacentZones(Enums.PitchZone currentZone, bool isHomeTeamPerspective)
        {
            if (currentZone == Enums.PitchZone.None)
            {
                return new ReadOnlyCollection<Enums.PitchZone>(new List<Enums.PitchZone>());
            }

            var cacheKey = Tuple.Create(currentZone, isHomeTeamPerspective);

            if (_adjacentZonesCache.TryGetValue(cacheKey, out ReadOnlyCollection<Enums.PitchZone> adjacentZones))
            {
                return adjacentZones;
            }
            else
            {
                throw new InvalidOperationException($"CRITICAL ERROR: Adjacent zones for ({currentZone}, {isHomeTeamPerspective}) not found in cache. Verify PopulateAdjacentZonesCache logic.");
            }
        }

        /// <summary>
        /// Determines the most advantageous zone for the attacking team to attempt an overload.
        /// This method should be called periodically (e.g., once per game tick or every few ticks)
        /// from your main game loop.
        /// </summary>
        /// <param name="attackingTeam">The team currently in possession.</param>
        /// <param name="defendingTeam">The opposing team.</param>
        public void DetermineOverloadTargetZone(Team attackingTeam, Team defendingTeam, int currentMinute, int currentSecond)
        {
            // Original logging, as provided
            //LoggingStuff.LogMethodCall(string.Format("DetermineOverloadTargetZone: attackingTeam:{0},defendingTeam:{1}," +
            //    "currentMinute:{2},currentSecond:{3}",
            //    attackingTeam.Name, defendingTeam.Name, currentMinute, currentSecond));

            // This was present in your initial version
            Enums.PitchZone ballZone = CurrentBallZone;
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);

            Enums.PitchZone? bestOverloadZone = null;
            double highestOverloadScore = -1000.0; // Start with a very low score to ensure a target is picked if possible

            // Define a set of 'critical' attacking zones to consider for overloads.
            // These are zones in the attacking half that are strategically important
            // from the *attacking team's perspective*.
            HashSet<Enums.PitchZone> potentialOverloadZones = new HashSet<Enums.PitchZone>();

            // Add relevant attacking zones based on the attacking team's perspective
            if (isHomeTeamAttacking)
            {
                potentialOverloadZones.Add(Enums.PitchZone.PenaltyArea_Away);
                potentialOverloadZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                potentialOverloadZones.Add(Enums.PitchZone.AwayAttack_Center);
                potentialOverloadZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
            }
            else
            {
                potentialOverloadZones.Add(Enums.PitchZone.PenaltyArea_Home);
                potentialOverloadZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                potentialOverloadZones.Add(Enums.PitchZone.HomeDefense_Center);
                potentialOverloadZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
            }

            // Add midfield zones (common for both scenarios)
            potentialOverloadZones.Add(Enums.PitchZone.Midfield_LeftFlank);
            potentialOverloadZones.Add(Enums.PitchZone.Midfield_Center);
            potentialOverloadZones.Add(Enums.PitchZone.Midfield_RightFlank);

            // Cache the forward value of the ball zone (this was already present in your original)
            int ballZoneForwardValue = GetZoneForwardValue(ballZone, isHomeTeamAttacking);

            // Add adjacent zones (this was already present in your original)
            foreach (var adjacentZone in GetAdjacentZones(ballZone, isHomeTeamAttacking))
            {
                if (GetZoneForwardValue(adjacentZone, isHomeTeamAttacking) >= ballZoneForwardValue - 1)
                {
                    potentialOverloadZones.Add(adjacentZone);
                }
            }

            // Add corner zones if the ball is near them (this was already present in your original)
            if (IsCornerZone(ballZone))
            {
                potentialOverloadZones.Add(ballZone);
            }

            List<Enums.PitchZone> resultPotentialOverloadZones = new List<Enums.PitchZone>(potentialOverloadZones);

            foreach (Enums.PitchZone zone in potentialOverloadZones)
            {
                // Skip goal-specific zones (GoalkeeperArea) for outfield player overloads
                if (zone == Enums.PitchZone.GoalkeeperArea_Home || zone == Enums.PitchZone.GoalkeeperArea_Away || zone == Enums.PitchZone.None)
                    continue;

                // Original Count() calls, as provided
                int attackingPlayersInZone = attackingTeam.AvailableOnFieldOutfielders.Count(p => p.CurrentZone == zone && p != CurrentBallHolder);
                int defendersInZone = defendingTeam.AvailableOnFieldOutfielders.Count(p => p.CurrentZone == zone);

                int totalPlayersInZone = attackingPlayersInZone + defendersInZone;

                double zoneOverloadScore = 0;

                // 1. Numerical Advantage Potential: The most important factor for an overload
                // Prioritize zones where we can achieve or improve a numerical advantage
                if (attackingPlayersInZone > defendersInZone)
                {
                    zoneOverloadScore += 50.0; // Strong bonus for already having an advantage
                    zoneOverloadScore += (attackingPlayersInZone - defendersInZone) * 10.0; // Bigger bonus for larger advantage
                }
                else if (attackingPlayersInZone == defendersInZone && attackingPlayersInZone > 0)
                {
                    zoneOverloadScore += 25.0; // Equal numbers, good potential to gain advantage
                }
                else // attackingPlayersInZone < defendersInZone
                {
                    // Calculate defender superiority - penalize zones where we are outnumbered
                    int defenderSuperiority = defendersInZone - attackingPlayersInZone;
                    zoneOverloadScore -= (defenderSuperiority * 15.0);
                }

                // 2. Proximity to the ball: Overloads are more effective if they are near the current play
                int distanceToBall = GetZoneDistance(zone, ballZone, isHomeTeamAttacking);
                zoneOverloadScore += (double)(5 - distanceToBall) * 7.0; // Closer zones get higher score

                // 3. Strategic Importance: Closer to opponent's goal is generally better for attacking overloads
                Enums.PitchZone opponentGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                int distanceToOpponentGoal = GetZoneDistance(zone, opponentGoalArea, isHomeTeamAttacking);
                zoneOverloadScore += (double)(10 - distanceToOpponentGoal) * 3.0; // Prioritize zones closer to goal

                // 4. Density/Openness: Prefer zones that aren't already too crowded (unless we're explicitly trying to overwhelm)
                // If the target zone is already too crowded with *all* players, it might be less effective for an overload
                if (totalPlayersInZone > 4) // More than 4 players in a single zone (arbitrary number, adjust)
                {
                    zoneOverloadScore -= 20.0;
                }

                // 5. Consideration of defensive line (for runs in behind during an overload)
                // This helper method needs to map to your specific PitchZone values
                // Original call to GetOpponentDefensiveLineZone, inside the loop
                Enums.PitchZone opponentDefensiveLineZone = GetOpponentDefensiveLineZone(defendingTeam, isHomeTeamAttacking, currentMinute, currentSecond);
                if (GetZoneForwardValue(zone, isHomeTeamAttacking) > GetZoneForwardValue(opponentDefensiveLineZone, isHomeTeamAttacking))
                {
                    zoneOverloadScore += 15; // Bonus for being behind the defensive line
                }

                // 6. Add a small random factor to prevent predictable patterns
                zoneOverloadScore += Dice.d20() * 0.5; // Slightly increased randomness influence

                // Update best zone if current zone has a higher score
                if (zoneOverloadScore > highestOverloadScore)
                {
                    highestOverloadScore = zoneOverloadScore;
                    bestOverloadZone = zone;
                }
            }

            // Set a threshold for what constitutes a "good enough" overload opportunity
            // This threshold will likely need tuning during testing.
            if (highestOverloadScore > 50) // Adjust this threshold as needed (e.g., minimum score to trigger an overload)
            {
                CurrentOverloadTargetZone = bestOverloadZone;
                //ShowMessage(string.Format("{0} identifies {1} as an overload target zone (Score: {2:F2}).", attackingTeam.Name, EnumCache<Enums.PitchZone>.ToString(CurrentOverloadTargetZone).Replace("_", " "), highestOverloadScore));
            }
            else
            {
                CurrentOverloadTargetZone = null; // No good overload opportunity found
                                                  // ShowMessage(string.Format("{0} found no high-priority overload target this tick (Highest Score: {1:F2}).", attackingTeam.Name, highestOverloadScore));
            }
        }

        // Helper method to check if a zone is a corner
        bool IsCornerZone(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsCornerZone: zone:{0}", zone));


            return zone == Enums.PitchZone.Corner_AwayLeft || zone == Enums.PitchZone.Corner_AwayRight ||
                   zone == Enums.PitchZone.Corner_HomeLeft || zone == Enums.PitchZone.Corner_HomeRight;
        }

        // Add this helper method to your Game.cs if you don't have it (from previous discussion)
        /// <summary>
        /// Gets the approximate defensive line zone for the opponent team, using cached values
        /// and recalculating only when necessary based on the current game minute and second.
        /// </summary>
        /// <param name="defendingTeam">The team whose defensive line is being sought.</param>
        /// <param name="isHomeTeamPerspective">True if the perspective is from the home team, false for away team.</param>
        /// <param name="currentMinute">The current game minute (from SimulateMoment).</param>
        /// <param name="currentSecond">The current game second (from SimulateMoment).</param>
        /// <returns>The PitchZone representing the opponent's defensive line.</returns>
        public Enums.PitchZone GetOpponentDefensiveLineZone(Team defendingTeam, bool isHomeTeamPerspective, int currentMinute, int currentSecond)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetOpponentDefensiveLineZone: defendingTeam:{0},isHomeTeamPerspective:{1}," +
            //    "currentMinute:{2},currentSecond:{3}",
            //    defendingTeam.Name, isHomeTeamPerspective, currentMinute, currentSecond));


            // Create a unique identifier for the current "moment" (your 15-second tick).
            // This is the crucial part that links the cache to your 15-second `SimulateMoment` intervals.
            int currentMomentId = (currentMinute * 60) + currentSecond; // Combines minute and second into a single integer

            // Ensure team is initialized in caches
            if (!_cachedDefensiveLines.ContainsKey(defendingTeam))
            {
                _cachedDefensiveLines[defendingTeam] = Enums.PitchZone.None;
                _cachedDefensiveLineForwardValues[defendingTeam] = -1;
                // Force immediate recalculation on first access for this team
                _lastDefensiveLineCalculationMomentId[defendingTeam] = -(DEFENSIVE_LINE_RECALCULATE_INTERVAL_MOMENTS + 1);
            }

            // --- Caching Logic ---
            // Check if recalculation is due based on whether enough "moments" have passed.
            // If currentMomentId is the same as _lastDefensiveLineCalculationMomentId,
            // this condition will be FALSE, and the cached value will be returned directly.
            if (currentMomentId >= _lastDefensiveLineCalculationMomentId[defendingTeam] + DEFENSIVE_LINE_RECALCULATE_INTERVAL_MOMENTS)
            {
                //Console.WriteLine($"Recalculating defensive line for {defendingTeam.Name} at moment ID {currentMomentId} (Minute: {currentMinute}, Second: {currentSecond})");
                // Perform the expensive calculation and update the cache
                CalculateAndCacheDefensiveLine(defendingTeam, isHomeTeamPerspective, currentMomentId);
            }
            else
            {
                // Console.WriteLine($"Using cached defensive line for {defendingTeam.Name} at moment ID {currentMomentId}"); // Uncomment for debugging
            }

            return _cachedDefensiveLines[defendingTeam];
        }

        /// <summary>
        /// Determines the ideal defensive positioning zone for a player based on their role,
        /// the ball carrier's position, and team tactics (e.g., high press, deep block).
        /// </summary>
        /// <param name="defender">The defender whose ideal zone is being determined.</param>
        /// <param name="ballCarrier">The opponent in possession.</param>
        /// <param name="defendingTeam">The defender's team.</param>
        /// <param name="attackingTeam">The opponent's team.</param>
        /// <returns>The ideal PitchZone for the defender.</returns>
        private Enums.PitchZone DetermineIdealDefensiveZone(Player defender, Player ballCarrier, Team defendingTeam, Team attackingTeam)
        {
            // Start with the player's nominal/preferred zone for their role, if applicable.
            Enums.PitchZone idealZone = defender.CurrentZone;
            Enums.PitchZone ballZone = ballCarrier.CurrentZone;

            // Get initial coordinates based on role if current zone is None
            if (idealZone == Enums.PitchZone.None)
            {
                switch (defender.Role)
                {
                    case Enums.PlayerRole.Goalkeeper: return defendingTeam == HomeTeam ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    case Enums.PlayerRole.CenterBack: return defendingTeam == HomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                    case Enums.PlayerRole.FullBack:
                        if (defender.Position == Enums.Positions.LeftBack) return defendingTeam == HomeTeam ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_LeftFlank;
                        if (defender.Position == Enums.Positions.RightBack) return defendingTeam == HomeTeam ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_RightFlank;
                        return defendingTeam == HomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                    case Enums.PlayerRole.DefensiveMidfielder: return Enums.PitchZone.Midfield_Center;
                    case Enums.PlayerRole.CentralMidfielder: return Enums.PitchZone.Midfield_Center;
                    default: return defendingTeam == HomeTeam ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                }
            }

            ZoneCoordinate idealCoords = GetZoneCoords(idealZone);
            ZoneCoordinate ballCoords = GetZoneCoords(ballZone);
            bool isHomeDefending = (defendingTeam == HomeTeam);
            bool isHomeAttacking = (defendingTeam != HomeTeam); // When defending, the other team is attacking

            // --- 1. Adjust based on Ball Carrier's Position ---
            // Defenders should generally try to stay between the ball and their own goal.
            // They also shift laterally towards the ball.

            // Use Y-coordinates for forward/backward adjustment
            // For home team defending: higher Y means further from own goal (less defensive)
            // For away team defending: lower Y means further from own goal (less defensive)
            int ballY = ballCoords.Y;
            int defenderY = idealCoords.Y;

            // Determine if ball is 'ahead' (closer to defending team's goal) or 'behind' (closer to opponent's goal)
            // relative to defender's current position.
            // For Home Team defending: Ball ahead = ballY < defenderY (since HomeDefense is Y=1, AwayAttack is Y=3)
            // For Away Team defending: Ball ahead = ballY > defenderY (since AwayDefense is Y=3, HomeAttack is Y=1)
            bool ballIsAheadOfDefender = (isHomeDefending && ballY < defenderY - 1) || (!isHomeDefending && ballY > defenderY + 1);
            bool ballIsBehindDefender = (isHomeDefending && ballY > defenderY + 1) || (!isHomeDefending && ballY < defenderY - 1);


            if (ballIsAheadOfDefender) // Ball is closer to defending team's goal
            {
                // Defender needs to drop back
                idealZone = GetZoneBehind(idealZone, isHomeDefending); // Use your GetZoneBehind
            }
            else if (ballIsBehindDefender) // Ball is closer to opponent's goal
            {
                // Defender can push up
                idealZone = GetZoneAhead(idealZone, isHomeAttacking); // Use your GetZoneAhead (defender is moving in their team's attacking direction)
            }

            // Use X-coordinates for lateral adjustment
            int ballX = ballCoords.X;
            int defenderX = GetZoneCoords(idealZone).X; // Re-fetch idealCoords after potential vertical shift

            if (ballX > defenderX) // Ball is to the defender's right (higher X)
            {
                idealZone = GetLateralZone(idealZone, 1, isHomeDefending);
            }
            else if (ballX < defenderX) // Ball is to the defender's left (lower X)
            {
                idealZone = GetLateralZone(idealZone, -1, isHomeDefending);
            }

            // Specific role-based lateral adjustments (using the new GetLateralZone)
            if (defender.Role == Enums.PlayerRole.CenterBack)
            {
                // CBs tend to tuck in more centrally unless ball is on wide flanks in their own defensive third
                // Ball needs to be on a flank and in defensive or midfield third to draw CB wide
                int currentIdealY = GetZoneCoords(idealZone).Y;
                if ((EnumCache<Enums.PitchZone>.ToString(ballZone).Contains("Flank") && ((isHomeDefending && ballY <= 2) || (!isHomeDefending && ballY >= 2))) || // Defensive or Midfield flank relative to *defending* team
                    (ballZone == Enums.PitchZone.Corner_HomeLeft || ballZone == Enums.PitchZone.Corner_HomeRight ||
                     ballZone == Enums.PitchZone.Corner_AwayLeft || ballZone == Enums.PitchZone.Corner_AwayRight))
                {
                    if (ballX < GetZoneCoords(idealZone).X) idealZone = GetLateralZone(idealZone, -1, isHomeDefending); // Ball left, shift left
                    else if (ballX > GetZoneCoords(idealZone).X) idealZone = GetLateralZone(idealZone, 1, isHomeDefending); // Ball right, shift right
                }
                else
                {
                    idealZone = GetLateralZone(idealZone, 0, isHomeDefending); // Stay central otherwise (shift 0 means force to center column 2)
                }
            }


            // --- 2. Influence of Team Tactic ---
            switch (defendingTeam.CurrentTactic)
            {
                case Enums.TeamTactic.PressHigh:
                    // Only push up if the ball is in their general area (e.g., midfield or higher)
                    // If the ball is in the opponent's half (Y >= 2 for home team defending, Y <= 2 for away team defending)
                    if ((isHomeDefending && ballCoords.Y >= 2) || (!isHomeDefending && ballCoords.Y <= 2))
                    {
                        idealZone = GetZoneAhead(idealZone, isHomeAttacking); // Push up using your GetZoneAhead
                    }
                    break;

                case Enums.TeamTactic.ParkTheBus:
                    // Encourage defenders to drop back towards their goal, staying compact.
                    // If defender is not already very deep (e.g., Y > 0 for home, Y < 4 for away)
                    if ((isHomeDefending && GetZoneCoords(idealZone).Y > 0) || (!isHomeDefending && GetZoneCoords(idealZone).Y < 4))
                    {
                        idealZone = GetZoneBehind(idealZone, isHomeDefending); // Drop back using your GetZoneBehind
                    }
                    idealZone = GetLateralZone(idealZone, 0, isHomeDefending); // Try to force to center
                    break;

                default:
                    break;
            }

            // --- NEW: Influence of Defensive Line Depth (including Offside Trap) ---
            // Apply line depth shifts iteratively using your GetZoneAhead/Behind
            int lineShiftSteps = 0;

            switch (defendingTeam.CurrentDefensiveLineDepth)
            {
                case Enums.DefensiveLineDepth.VeryDeep:
                    lineShiftSteps = 2; // Number of steps to move behind
                    break;
                case Enums.DefensiveLineDepth.Deep:
                    lineShiftSteps = 1;
                    break;
                case Enums.DefensiveLineDepth.Standard:
                    lineShiftSteps = 0;
                    break;
                case Enums.DefensiveLineDepth.High:
                    lineShiftSteps = 1; // Number of steps to move ahead
                    break;
                case Enums.DefensiveLineDepth.VeryHigh:
                    lineShiftSteps = 2;
                    break;
                case Enums.DefensiveLineDepth.OffsideTrap:
                    lineShiftSteps = 3; // Aggressive push up
                    break;
            }

            for (int i = 0; i < lineShiftSteps; i++)
            {
                if (defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.VeryDeep || defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.Deep)
                {
                    idealZone = GetZoneBehind(idealZone, isHomeDefending);
                }
                else if (defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.High || defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.VeryHigh || defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.OffsideTrap)
                {
                    idealZone = GetZoneAhead(idealZone, isHomeAttacking); // Push up (attacking direction of player's team)
                }
            }


            // --- Offside Trap Dynamic Decision ---
            if (defendingTeam.CurrentDefensiveLineDepth == Enums.DefensiveLineDepth.OffsideTrap)
            {
                // Conditions to attempt an offside trap:
                // 1. Ball carrier is in midfield or attacking third (for their team).
                bool isBallInAttackingHalfForAttacker = (isHomeDefending && ballCoords.Y >= 2) || (!isHomeDefending && ballCoords.Y <= 2);

                // 2. A threatening pass could be attempted by the ball carrier
                bool isThreateningPassPossible = Dice.d100() < (ballCarrier.trueRating.VisionForGameCalculations + ballCarrier.trueRating.PassingForGameCalculations) / 2;

                if (isBallInAttackingHalfForAttacker && isThreateningPassPossible)
                {
                    double defensiveCoordination = defendingTeam.AvailableOnFieldOutfielders
                                                        .Where(p => p.Role == Enums.PlayerRole.CenterBack || p.Role == Enums.PlayerRole.FullBack)
                                                        .Average(p => p.trueRating.DefenseAwarenessForGameCalculations + p.trueRating.PositioningForGameCalculations) / 2.0;

                    double attackingThreat = (ballCarrier.trueRating.VisionForGameCalculations + ballCarrier.trueRating.PassingForGameCalculations) / 2.0;

                    double baseSuccessChance = (defensiveCoordination - attackingThreat + 100) / 200.0;

                    switch (referee.CurrentRefereeStrictness)
                    {
                        case Enums.RefereeStrictness.Lenient: baseSuccessChance *= 0.8; break;
                        case Enums.RefereeStrictness.Strict: baseSuccessChance *= 1.2; break;
                        case Enums.RefereeStrictness.Normal: break;
                    }

                    bool trapSuccessful = Dice.d100() < (baseSuccessChance * 100);

                    if (trapSuccessful)
                    {
                        //ShowMessage(string.Format("{0} attempt an offside trap!", defendingTeam.Name));
                        // If successful, push the line even higher very aggressively
                        // Apply another step ahead using your GetZoneAhead
                        idealZone = GetZoneAhead(idealZone, isHomeAttacking);
                    }
                    else
                    {
                        //ShowMessage(string.Format("{0}'s offside trap fails!", defendingTeam.Name));
                        // If trap fails, defenders need to quickly drop back to avoid being caught out.
                        // Apply two steps behind using your GetZoneBehind
                        idealZone = GetZoneBehind(idealZone, isHomeDefending);
                        idealZone = GetZoneBehind(idealZone, isHomeDefending); // Drop back an extra step for a failed trap
                    }
                }
            }

            // Ensure the idealZone is not 'None'
            if (idealZone == Enums.PitchZone.None || GetZoneCoords(idealZone).X == -99)
            {
                // Fallback to a safe central defensive zone based on team
                idealZone = isHomeDefending ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
            }

            return idealZone;
        }

        // New helper to get coordinates directly from your dictionary
        private ZoneCoordinate GetZoneCoords(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneCoords: zone:{0}", zone));


            ZoneCoordinate coords; // Declare variable before use
            if (_zoneCoordinates.TryGetValue(zone, out coords))
            {
                return coords;
            }
            return _zoneCoordinates[Enums.PitchZone.None]; // Fallback for undefined zones
        }

        /// <summary>
        /// Calculates a new PitchZone by applying an X and Y offset to a starting zone.
        /// Handles boundaries and returns PitchZone.None if the new coordinates are out of bounds or not a valid playable zone.
        /// </summary>
        /// <param name="startZone">The starting PitchZone. This should be a concrete zone (e.g., HomeDefense_Center, PenaltyArea_Away),
        /// not a generic defensive zone that needs team-specific resolution (e.g., DefensivePenaltyArea_Central).
        /// Use GetTeamSpecificDefensiveZone first if you're dealing with generic defensive zones.</param>
        /// <param name="offsetX">The horizontal offset (e.g., -1 for left, 1 for right).</param>
        /// <param name="offsetY">The vertical offset (e.g., -1 for backward, 1 for forward relative to the pitch's inherent Y-axis, not team-relative).</param>
        /// <returns>The new PitchZone, or PitchZone.None if out of bounds or not a playable zone.</returns>
        private Enums.PitchZone GetZoneOffset(Enums.PitchZone startZone, int offsetX, int offsetY) // isHomeDefending parameter removed
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneOffset: startZone:{0},offsetX:{1},offsetY:{2}",
            //    startZone, offsetX, offsetY));


            ZoneCoordinate startCoords = GetZoneCoords(startZone);
            int newX = startCoords.X + offsetX;
            int newY = startCoords.Y + offsetY;

            // Create a new ZoneCoordinate object for the lookup
            ZoneCoordinate targetCoords = new ZoneCoordinate(newX, newY);

            // Use the reverse map to find the PitchZone
            Enums.PitchZone resultZone;
            if (_coordsToZoneMap.TryGetValue(targetCoords, out resultZone))
            {
                // Ensure the found zone is a "playable" zone for general movement
                // This explicitly allows the new granular penalty area zones as valid movement targets.
                if (resultZone == Enums.PitchZone.None ||
                    EnumCache<Enums.PitchZone>.ToString(resultZone).Contains("Corner") || // Exclude corners (e.g., Corner_HomeLeft)
                    resultZone == Enums.PitchZone.KickOffCircle) // Exclude kickoff circle
                {
                    return Enums.PitchZone.None; // Filtered out
                }

                // The specific goal area checks (like "trying to move GK too far into opponent's specific goal areas")
                // should ideally be handled by higher-level AI logic determining *where* a player is allowed to move,
                // rather than by this fundamental zone offset calculation.
                // This method's job is just to tell you *what zone* is at targetCoords, and if it's a generally playable zone.

                return resultZone; // Return the found zone if it's valid for general movement
            }

            return Enums.PitchZone.None; // Return None if coordinates are invalid or map to a non-playable zone
        }

        /// <summary>
        /// Determines a zone adjacent to where an opponent's wall would form during a free kick.
        /// This is highly dependent on your specific PitchZone mapping relative to the free kick origin.
        /// </summary>
        /// <param name="freeKickOriginZone">The PitchZone where the free kick is being taken from.</param>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <param name="isNearSide">If true, returns the zone on the side of the wall closer to the free kick origin. If false, the far side.</param>
        /// <returns>A PitchZone adjacent to the wall, or None if no logical zone can be determined.</returns>
        private Enums.PitchZone GetZoneAdjacentToOpponentWall(Enums.PitchZone freeKickOriginZone, bool isAttackingTeamHome, bool isNearSide)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneAdjacentToOpponentWall: freeKickOriginZone:{0},isAttackingTeamHome:{1},isNearSide:{2}",
            //    freeKickOriginZone, isAttackingTeamHome, isNearSide));


            // This is a highly conceptual method that depends entirely on your exact pitch zone grid
            // and how you define the "wall" in relation to free kick zones.
            // The logic below is a *simplistic interpretation* for compilation.
            // You will need to replace this with accurate mapping based on your game's pitch layout.

            int originForwardValue = GetZoneForwardValue(freeKickOriginZone, isAttackingTeamHome);
            int originSideValue = GetZoneSideValue(freeKickOriginZone);

            // Assume the wall forms generally "forward" from the free kick origin, blocking the goal.
            // It's usually slightly inside the attacking half or just inside the defending half.

            Enums.PitchZone targetPenaltyArea = isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;

            // Try to find a zone roughly between the free kick and the penalty area,
            // offset to the left or right of the central axis where the wall would be.

            // Simplistic example:
            if (isAttackingTeamHome)
            {
                if (originSideValue == 0) // Free kick on attacking left
                {
                    return isNearSide ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.AwayAttack_Center;
                }
                else if (originSideValue == 2) // Free kick on attacking right
                {
                    return isNearSide ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.AwayAttack_Center;
                }
                else // Free kick central
                {
                    // For central free kicks, the "near" side might be slightly left, "far" side slightly right
                    return isNearSide ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.AwayAttack_RightFlank;
                }
            }
            else // Away team attacking
            {
                if (originSideValue == 0) // Free kick on home left (away right)
                {
                    return isNearSide ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.HomeDefense_Center; // Away team's right is Home team's right
                }
                else if (originSideValue == 2) // Free kick on home right (away left)
                {
                    return isNearSide ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.HomeDefense_Center; // Away team's left is Home team's left
                }
                else // Free kick central
                {
                    return isNearSide ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.HomeDefense_LeftFlank;
                }
            }
        }

        /// <summary>
        /// Determines a zone for a player to position themselves *behind* the opponent's defensive wall
        /// during a free kick, typically for rebound opportunities.
        /// </summary>
        /// <param name="freeKickOriginZone">The PitchZone where the free kick is being taken from.</param>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <returns>A PitchZone behind the wall, closer to the goal, or None.</returns>
        private Enums.PitchZone GetZoneBehindWall(Enums.PitchZone freeKickOriginZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneBehindWall: freeKickOriginZone:{0},isAttackingTeamHome:{1}",
            //    freeKickOriginZone, isAttackingTeamHome));


            // This is also highly dependent on your specific PitchZone mapping.
            // A zone "behind the wall" would be one that is closer to the goal
            // than the typical wall position, but not necessarily in the goalkeeper's immediate area.
            // It's usually within the penalty box or very close to it.

            Enums.PitchZone targetPenaltyArea = isAttackingTeamHome ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            Enums.PitchZone targetGoalkeeperArea = isAttackingTeamHome ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

            // Prioritize the main penalty area or the attacking center just outside it.
            // Avoid the goalkeeper area itself unless it's a very specific poaching instruction.

            int originSideValue = GetZoneSideValue(freeKickOriginZone);

            if (isAttackingTeamHome)
            {
                // If central, aim for central penalty area
                if (originSideValue == 1) return Enums.PitchZone.PenaltyArea_Away;
                // If from left, aim for penalty area slightly right of center
                if (originSideValue == 0) return Enums.PitchZone.PenaltyArea_Away; // Could be a more specific sub-zone if available
                // If from right, aim for penalty area slightly left of center
                if (originSideValue == 2) return Enums.PitchZone.PenaltyArea_Away; // Could be a more specific sub-zone if available
            }
            else // Away team attacking
            {
                if (originSideValue == 1) return Enums.PitchZone.PenaltyArea_Home;
                if (originSideValue == 0) return Enums.PitchZone.PenaltyArea_Home;
                if (originSideValue == 2) return Enums.PitchZone.PenaltyArea_Home;
            }

            // Fallback to the main penalty area if more specific logic doesn't apply
            return targetPenaltyArea;
        }

        /// <summary>
        /// Determines movement for players offering a 'LayOffShort' option.
        /// Prioritizes players with good passing/composure in safe, nearby zones.
        /// </summary>
        private Enums.PitchZone GetSafeShortPassZone(Player player, Enums.PitchZone freeKickOriginZone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetSafeShortPassZone: player:{0},freeKickOriginZone:{1},isAttackingTeamHome:{2}",
            //    player.position, freeKickOriginZone, isAttackingTeamHome));


            // For a short layoff, players should move to a nearby, relatively safe zone.
            // This could be slightly behind, to the side, or slightly ahead of the taker, but not aggressively into defense.
            Enums.PitchZone preferredZone = player.CurrentZone;
            double bestScore = -1.0;

            HashSet<Enums.PitchZone> candidateZones = new HashSet<Enums.PitchZone>();

            // Get adjacent zones to the free kick origin and add them to the set
            foreach (var zone in GetAdjacentZones(freeKickOriginZone, isAttackingTeamHome))
            {
                if (zone != Enums.PitchZone.None)
                {
                    candidateZones.Add(zone);
                }
            }

            // Add the origin zone
            candidateZones.Add(freeKickOriginZone);

            // Add common midfield support zones
            candidateZones.Add(Enums.PitchZone.Midfield_Center);

            int zoneSideValue = GetZoneSideValue(freeKickOriginZone);
            if (isAttackingTeamHome)
            {
                if (zoneSideValue == 0) candidateZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                if (zoneSideValue == 2) candidateZones.Add(Enums.PitchZone.Midfield_RightFlank);
            }
            else
            {
                if (zoneSideValue == 0) candidateZones.Add(Enums.PitchZone.Midfield_RightFlank);
                if (zoneSideValue == 2) candidateZones.Add(Enums.PitchZone.Midfield_LeftFlank);
            }

            List<Enums.PitchZone> resultCandidateZones = new List<Enums.PitchZone>(candidateZones);

            foreach (var targetZone in resultCandidateZones)
            {
                // Avoid moving backwards excessively in attacking situations
                if (IsBallInAttackingHalf(freeKickOriginZone, isAttackingTeamHome ? HomeTeam : AwayTeam) &&
                    GetZoneForwardValue(targetZone, isAttackingTeamHome) < GetZoneForwardValue(freeKickOriginZone, isAttackingTeamHome) - 1)
                {
                    continue; // Skip zones that are too far back if in attacking half
                }

                double currentZoneScore = 0;

                // Players with good passing, vision, composure, and first touch are good for layoffs
                currentZoneScore += player.trueRating.PassingForGameCalculations * 0.3;
                currentZoneScore += player.trueRating.VisionForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.ComposureForGameCalculations * 0.2;
                currentZoneScore += player.trueRating.FinishingForGameCalculations * 0.1;

                // Prioritize zones with few defenders
                currentZoneScore += (5 - CountDefendersInZone(targetZone, DefendingTeam)) * 8;

                // Prioritize zones close to the free kick taker
                currentZoneScore -= CalculateDistance(freeKickOriginZone, targetZone) * 5;

                // Avoid zones that are too far into the opponent's crowded defense
                if (IsBallInPenaltyArea(targetZone, AttackingTeam) ||
                    (isAttackingTeamHome && targetZone == Enums.PitchZone.AwayAttack_Center) ||
                    (!isAttackingTeamHome && targetZone == Enums.PitchZone.HomeDefense_Center))
                {
                    currentZoneScore -= 15; // Penalize highly dangerous zones for a "safe" layoff
                }

                // Offside should not be a major concern for short layoffs, but still check
                if (IsLikelyOffsideFromFreeKick(targetZone, AttackingTeam, DefendingTeam))
                {
                    currentZoneScore -= 50; // Moderate penalty
                }

                if (currentZoneScore > bestScore)
                {
                    bestScore = currentZoneScore;
                    preferredZone = targetZone;
                }
            }

            if (preferredZone == Enums.PitchZone.None || bestScore < 0)
            {
                return player.CurrentZone; // Stick to current zone as safest option
            }
            return preferredZone;
        }

        /// <summary>
        /// Checks if any player from the specified opposing team is currently occupying the given pitch zone.
        /// </summary>
        /// <param name="zone">The PitchZone to check.</param>
        /// <param name="opposingTeam">The team whose players to check for occupancy.</param>
        /// <returns>True if at least one player from the opposing team is in the zone, false otherwise.</returns>
        private bool IsZoneOccupiedByOpponent(Enums.PitchZone zone, Team opposingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsZoneOccupiedByOpponent: zone:{0},opposingTeam:{1}",
            //    zone, opposingTeam.Name));


            // Iterate through all players in the opposing team's starting eleven
            foreach (Player player in opposingTeam.AvailableOnFieldPlayers)
            {
                // Check if the player is currently in the specified zone
                if (player.CurrentZone == zone)
                {
                    return true; // Found an opponent in the zone
                }
            }
            return false; // No opponent found in the zone
        }

        // Helper method to add non-None zones
        void AddNonNoneZone(Enums.PitchZone zone, ref HashSet<Enums.PitchZone> uniqueCandidateZones)
        {
            //LoggingStuff.LogMethodCall(string.Format("AddNonNoneZone: zone:{0},uniqueCandidateZones:{1}",
            //    zone, string.Join(",", uniqueCandidateZones)));


            if (zone != Enums.PitchZone.None)
            {
                uniqueCandidateZones.Add(zone);
            }
        }

        /// <summary>
        /// Determines a zone typically just outside the penalty box, suitable for cutbacks or second balls.
        /// This implementation assumes a basic understanding of your PitchZone enumeration:
        /// - Zones like AwayAttack_LeftFlank, AwayAttack_Center, AwayAttack_RightFlank are "outside" the Away Penalty Area.
        /// - Zones like HomeDefense_LeftFlank, HomeDefense_Center, HomeDefense_RightFlank are "outside" the Home Penalty Area.
        /// </summary>
        /// <param name="isAttackingTeamHome">True if the attacking team is the home team.</param>
        /// <param name="isLeftFlank">If true, aims for the left flank edge; otherwise, the right flank edge. If neither, center.</param>
        /// <returns>A PitchZone on the edge of the penalty area, or None if no logical zone can be determined.</returns>
        private Enums.PitchZone GetZoneOnEdgeOfPenaltyArea(bool isAttackingTeamHome, bool isLeftFlank)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneOnEdgeOfPenaltyArea: isAttackingTeamHome:{0},isLeftFlank:{1}",
            //    isAttackingTeamHome, isLeftFlank));


            if (isAttackingTeamHome)
            {
                // Home team is attacking, so we look at zones just outside Away team's penalty area
                if (isLeftFlank)
                {
                    return Enums.PitchZone.AwayAttack_LeftFlank;
                }
                else // Right flank or center fallback
                {
                    return Enums.PitchZone.AwayAttack_RightFlank; // Default to right flank if not left
                }
                // For a central option, you might return Enums.PitchZone.AwayAttack_Center
            }
            else
            {
                // Away team is attacking, so we look at zones just outside Home team's penalty area
                if (isLeftFlank)
                {
                    // Note: Away team's 'left flank' in attack corresponds to the Home team's 'right flank' in defense.
                    return Enums.PitchZone.HomeDefense_RightFlank;
                }
                else // Right flank or center fallback
                {
                    // Away team's 'right flank' in attack corresponds to the Home team's 'left flank' in defense.
                    return Enums.PitchZone.HomeDefense_LeftFlank; // Default to left flank if not left
                }
                // For a central option, you might return Enums.PitchZone.HomeDefense_Center
            }
        }

        /// <summary>
        /// Assigns a numerical value to a PitchZone based on its horizontal position (side of the pitch).
        /// This is a conceptual mapping and needs to align with your Enums.PitchZone definitions.
        /// 0 = Left Flank, 1 = Center, 2 = Right Flank (from attacking perspective for Home team)
        /// </summary>
        /// <param name="zone">The PitchZone to evaluate.</param>
        /// <returns>An integer representing the side value (0, 1, 2), or -1 if the zone isn't easily categorizable by side.</returns>
        private int GetZoneSideValue(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneSideValue: zone:{0}", zone));


            switch (zone)
            {
                // Home Team Half (Defense to Attack progression)
                case Enums.PitchZone.GoalkeeperArea_Home:
                case Enums.PitchZone.PenaltyArea_Home:
                case Enums.PitchZone.HomeDefense_Center:
                case Enums.PitchZone.Midfield_Center:
                case Enums.PitchZone.AwayAttack_Center:
                case Enums.PitchZone.PenaltyArea_Away: // Central for both teams relative to goal
                case Enums.PitchZone.GoalkeeperArea_Away: // Central for both teams relative to goal
                    return 1; // Center

                case Enums.PitchZone.HomeDefense_LeftFlank:
                case Enums.PitchZone.Midfield_LeftFlank:
                case Enums.PitchZone.AwayAttack_LeftFlank:
                case Enums.PitchZone.Corner_HomeLeft:
                case Enums.PitchZone.Corner_AwayLeft:
                    return 0; // Left Flank (from Home team's attacking perspective)

                case Enums.PitchZone.HomeDefense_RightFlank:
                case Enums.PitchZone.Midfield_RightFlank:
                case Enums.PitchZone.AwayAttack_RightFlank:
                case Enums.PitchZone.Corner_HomeRight:
                case Enums.PitchZone.Corner_AwayRight:
                    return 2; // Right Flank (from Home team's attacking perspective)

                // Add other zones if necessary, or refine this logic based on your specific zone grid.
                default:
                    return 1; // Default to center if ambiguous, or -1 to indicate unknown
            }
        }

        /// <summary>
        /// Determines if a player in a target zone is likely to be offside during a free kick.
        /// This implementation needs to consider:
        /// 1. The position of the second-to-last defender of the defending team.
        /// 2. The position of the ball at the moment of the free kick.
        /// This is a simplified logic. A real offside system would require precise coordinates.
        /// </summary>
        /// <param name="targetZone">The zone the attacking player is moving to.</param>
        /// <param name="attackingTeam">The team currently in possession (taking the free kick).</param>
        /// <param name="defendingTeam">The team defending against the free kick.</param>
        /// <returns>True if the player is likely offside, false otherwise.</returns>
        private bool IsLikelyOffsideFromFreeKick(Enums.PitchZone targetZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsLikelyOffsideFromFreeKick: targetZone:{0},attackingTeam:{1},defendingTeam:{2}",
            //    targetZone, attackingTeam.Name, defendingTeam.Name));


            // Rule: A player is offside if they are nearer to the opponent's goal line than both the ball
            // and the second-to-last opponent.

            // Get the forward value of the ball (free kick origin)
            int ballForwardValue = GetZoneForwardValue(CurrentBallZone, attackingTeam == HomeTeam);

            // Find the second-to-last defender's forward position.
            // For simplicity, we assume defenders are generally in defensive zones.
            // This would ideally iterate through actual defender positions on the pitch.
            List<Player> defenders = new List<Player>();
            HashSet<Enums.Positions> defenderPositions = new HashSet<Enums.Positions>
            {
                Enums.Positions.CenterBack,
                Enums.Positions.LeftBack,
                Enums.Positions.RightBack,
                Enums.Positions.CentralDefendingMidfielder,
                Enums.Positions.Goalkeeper
            };

            bool isDefendingTeamHome = defendingTeam == HomeTeam;

            foreach (Player p in defendingTeam.AvailableOnFieldPlayers)
            {
                if (defenderPositions.Contains(p.Position))
                {
                    defenders.Add(p);
                }
            }

            defenders.Sort((a, b) =>
                GetZoneForwardValue(b.CurrentZone, isDefendingTeamHome).CompareTo(
                GetZoneForwardValue(a.CurrentZone, isDefendingTeamHome)));

            // The second-to-last defender (from their own goal line, so a higher forward value for the attacking team)
            // If there are fewer than 2 defenders (e.g., only GK), then the GK is the second-to-last.
            Player secondToLastDefender = null;
            if (defenders.Count >= 2)
            {
                secondToLastDefender = defenders[1]; // Second-to-last is index 1 after sorting descending
            }
            else if (defenders.Count == 1)
            {
                secondToLastDefender = defenders[0]; // If only one, that's the reference
            }
            else
            {
                // No defenders found or edge case, assume not offside for simplicity
                // In a real game, this might imply an open goal or a very deep attacking play.
                return false;
            }

            int secondToLastDefenderForwardValue = GetZoneForwardValue(secondToLastDefender.CurrentZone, attackingTeam == HomeTeam);

            // Determine the attacking player's forward position in the target zone
            int playerTargetForwardValue = GetZoneForwardValue(targetZone, attackingTeam == HomeTeam);

            // Conditions for offside:
            // 1. Player is in the opponent's half (GetZoneForwardValue for attacking team > midfield value).
            //    Assuming GetZoneForwardValue(Midfield_Center, isAttackingTeamHome) is around 5.
            if (playerTargetForwardValue <= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, attackingTeam == HomeTeam))
            {
                return false; // Not in opponent's half
            }

            // 2. Player is nearer to the opponent's goal line than the second-to-last opponent.
            //    Higher forward value means closer to opponent's goal.
            if (playerTargetForwardValue > secondToLastDefenderForwardValue)
            {
                // 3. Player is nearer to the opponent's goal line than the ball.
                if (playerTargetForwardValue > ballForwardValue)
                {
                    // Offside position established. Now, check if "active in play" (simplified for free kicks).
                    // For free kicks, any player receiving the ball in an offside position is offside.
                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// Finds the shortest path of PitchZones between a start and end zone using a Breadth-First Search (BFS).
        /// This represents the zones a pass would roughly traverse for interception checks.
        /// </summary>
        /// <param name="startZone">The starting PitchZone of the pass.</param>
        /// <param name="endZone">The ending PitchZone of the pass.</param>
        /// <param name="isHomeTeamPerspective">Indicates if the home team's perspective (e.g., for zone traversal logic).</param>
        /// <returns>A list of PitchZones representing the path, including start and end zones. Returns an empty list if no path found (should not happen on a connected pitch).</returns>
        /// <summary>
        /// Finds the shortest pre-calculated path of PitchZones between a start and end zone using a BFS.
        /// The returned collection is read-only to prevent external modification of cached data.
        /// </summary>
        public ReadOnlyCollection<Enums.PitchZone> GetZonesAlongPath(Enums.PitchZone startZone, Enums.PitchZone endZone, bool isHomeTeamPerspective)
        {
            if (startZone == endZone)
            {
                return new ReadOnlyCollection<Enums.PitchZone>(new List<Enums.PitchZone> { startZone });
            }

            var pathKey = new PathKey(startZone, endZone, isHomeTeamPerspective);

            if (_zonePathCache.TryGetValue(pathKey, out ReadOnlyCollection<Enums.PitchZone> cachedPath))
            {
                return cachedPath;
            }
            else
            {
                throw new InvalidOperationException($"CRITICAL ERROR: Path for ({startZone}, {endZone}, {isHomeTeamPerspective}) not found in cache. Verify PopulateZonePathCache logic.");
            }
        }

        // --- Actual Calculation Logic (These are your original methods, adapted to be private static) ---

        /// <summary>
        /// Your original CalculateActualZoneDistance method, now private static.
        /// </summary>
        private int CalculateActualZoneDistance(Enums.PitchZone zone1, Enums.PitchZone zone2, bool isHomePerspective)
        {
            // This is your actual distance logic.
            int fwd1 = GetZoneForwardValue(zone1, isHomePerspective);
            int fwd2 = GetZoneForwardValue(zone2, isHomePerspective);
            int flank1 = (int)GetFlankOfZone(zone1);
            int flank2 = (int)GetFlankOfZone(zone2);

            return Math.Abs(fwd1 - fwd2) + Math.Abs(flank1 - flank2);
        }

        /// <summary>
        /// Your original GetAdjacentZones method, now private static.
        /// It will be called *only* during the initial cache population.
        /// It will also be used by CalculateActualZonesAlongPath (the BFS).
        /// </summary>
        private List<Enums.PitchZone> CalculateActualAdjacentZones(Enums.PitchZone currentZone, bool isHomeTeamPerspective)
        {
            List<Enums.PitchZone> adjacentZones = new List<Enums.PitchZone>();

            switch (currentZone)
            {
