                    adjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center);
                    adjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Midfield_RightFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Defensive_EdgeOfBox); // Added this based on your enum
                    adjacentZones.Add(Enums.PitchZone.DefensivePenaltyArea_Central); // Added this based on your enum
                    break;
                case Enums.PitchZone.HomeDefense_RightFlank:
                    adjacentZones.Add(Enums.PitchZone.GoalkeeperArea_Home);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                    adjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center); // Diagonal adjacency
