                case Enums.PitchZone.Midfield_LeftFlank:
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.KickOffCircle); // Maybe
                    break;
                case Enums.PitchZone.Midfield_Center:
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.KickOffCircle);
                    break;
                case Enums.PitchZone.Midfield_RightFlank:
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.KickOffCircle); // Maybe
                    break;
                case Enums.PitchZone.AwayAttack_LeftFlank:
                    adjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    adjacentZones.Add(Enums.PitchZone.Corner_AwayLeft); // Adding corner connection
                    break;
                case Enums.PitchZone.AwayAttack_Center:
                    adjacentZones.Add(Enums.PitchZone.Midfield_LeftFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center);
                    adjacentZones.Add(Enums.PitchZone.Midfield_RightFlank); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
