                case Enums.PitchZone.AwayAttack_RightFlank:
                    adjacentZones.Add(Enums.PitchZone.Midfield_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center); // Diagonal adjacency
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    adjacentZones.Add(Enums.PitchZone.Corner_AwayRight); // Adding corner connection
                    break;
                case Enums.PitchZone.PenaltyArea_Away:
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.GoalkeeperArea_Away);
