                case Enums.PitchZone.GoalkeeperArea_Away:
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_Center);
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank); // Assuming this is valid
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank); // Assuming this is valid
                    break;
                case Enums.PitchZone.PenaltyArea_Home: // Based on your enum, adding explicit adjacency
                    adjacentZones.Add(Enums.PitchZone.GoalkeeperArea_Home);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center); // Assuming direct connect to defense center
                    adjacentZones.Add(Enums.PitchZone.DefensivePenaltyArea_Central);
                    adjacentZones.Add(Enums.PitchZone.Defensive_EdgeOfBox);
                    break;
                case Enums.PitchZone.Corner_HomeLeft:
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_LeftFlank); // Connects to nearest flank
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Home); // Could be a diagonal pass
                    break;
                case Enums.PitchZone.Corner_HomeRight:
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                    break;
                case Enums.PitchZone.Corner_AwayLeft:
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_LeftFlank);
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    break;
                case Enums.PitchZone.Corner_AwayRight:
                    adjacentZones.Add(Enums.PitchZone.AwayAttack_RightFlank);
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    break;
                case Enums.PitchZone.KickOffCircle:
                    adjacentZones.Add(Enums.PitchZone.Midfield_Center); // Only connected to center midfield
                    break;
                case Enums.PitchZone.DefensivePenaltyArea_LeftNearPost:
                case Enums.PitchZone.DefensivePenaltyArea_RightNearPost:
                case Enums.PitchZone.DefensivePenaltyArea_Central:
                case Enums.PitchZone.DefensivePenaltyArea_LeftFarPost:
                case Enums.PitchZone.DefensivePenaltyArea_RightFarPost:
                case Enums.PitchZone.Defensive_EdgeOfBox:
                    // These would connect to PenaltyArea_Home, HomeDefense_Center, and each other.
                    // For brevity, adding general connections. YOU WILL NEED TO REFINE THESE.
                    adjacentZones.Add(Enums.PitchZone.PenaltyArea_Home);
                    adjacentZones.Add(Enums.PitchZone.HomeDefense_Center);
                    if (currentZone != Enums.PitchZone.Defensive_EdgeOfBox)
                    {
                        adjacentZones.Add(Enums.PitchZone.Defensive_EdgeOfBox);
                    }
                    if (currentZone == Enums.PitchZone.DefensivePenaltyArea_Central)
                    {
                        adjacentZones.Add(Enums.PitchZone.DefensivePenaltyArea_LeftNearPost);
                        adjacentZones.Add(Enums.PitchZone.DefensivePenaltyArea_RightNearPost);
                    }
                    break;
                case Enums.PitchZone.None:
                default:
                    break; // For 'None' or any unhandled zones, return an empty list.
            }
            return adjacentZones;
        }

        /// <summary>
        /// Your original GetZonesAlongPath (BFS) method, now private static.
        /// It will be called *only* during the initial cache population.
        /// It uses CalculateActualAdjacentZones to build the graph.
        /// </summary>
        private List<Enums.PitchZone> CalculateActualZonesAlongPath(Enums.PitchZone startZone, Enums.PitchZone endZone, bool isHomeTeamPerspective)
        {
            if (startZone == endZone)
            {
                return new List<Enums.PitchZone> { startZone };
            }

            Queue<Enums.PitchZone> queue = new Queue<Enums.PitchZone>();
            HashSet<Enums.PitchZone> visited = new HashSet<Enums.PitchZone>();
            Dictionary<Enums.PitchZone, Enums.PitchZone> parentMap = new Dictionary<Enums.PitchZone, Enums.PitchZone>();

            queue.Enqueue(startZone);
            visited.Add(startZone);

            Enums.PitchZone currentZone;
            bool pathFound = false;

            while (queue.Any())
            {
                currentZone = queue.Dequeue();

                if (currentZone == endZone)
                {
                    pathFound = true;
                    break;
                }

                // IMPORTANT: Call the *internal* CalculateActualAdjacentZones here, not the public cached one
                // This is because we are *building* the cache, not using it yet.
                foreach (var neighborZone in CalculateActualAdjacentZones(currentZone, isHomeTeamPerspective))
                {
                    if (!visited.Contains(neighborZone))
                    {
                        visited.Add(neighborZone);
                        parentMap[neighborZone] = currentZone;
                        queue.Enqueue(neighborZone);
                    }
                }
            }

            List<Enums.PitchZone> path = new List<Enums.PitchZone>();
            if (pathFound)
            {
                currentZone = endZone;
                // Reconstruct path: walk backward from endZone to startZone using parentMap
                while (currentZone != Enums.PitchZone.None && parentMap.ContainsKey(currentZone))
                {
                    path.Add(currentZone);
                    currentZone = parentMap[currentZone];
                }
                path.Add(startZone); // Add the start zone as it's the root of the pathfinding

                path.Reverse(); // Path is built backwards, so reverse it
            }

            return path;
        }

        /// <summary>
        /// Returns a numerical value representing the lateral position of a PitchZone.
        /// 0 indicates a central zone, negative values for left flank/corner, positive for right flank/corner.
        /// </summary>
        /// <param name="zone">The PitchZone to evaluate.</param>
        /// <param name="isHomeTeamPerspective">True if evaluating from the Home Team's perspective.
        /// (This parameter is actually less critical for lateral, as left/right are absolute on the pitch,
        /// but kept for consistency with forward value method and potential future logic).</param>
        /// <returns>An integer representing the lateral value (0 for center, -1 for left flank, +1 for right flank, etc.).</returns>
        private int GetZoneLateralValue(Enums.PitchZone zone, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneLateralValue: zone:{0},isHomeTeamPerspective:{1}",
            //    zone, isHomeTeamPerspective));


            // Lateral mapping:
            // Center zones: 0
            // Flank zones (left/right): -1 / +1
            // Corner zones: -2 / +2 (further out)

            switch (zone)
            {
                // Central zones
                case Enums.PitchZone.GoalkeeperArea_Home:
                case Enums.PitchZone.PenaltyArea_Home:
                case Enums.PitchZone.HomeDefense_Center:
                case Enums.PitchZone.Midfield_Center:
                case Enums.PitchZone.AwayAttack_Center:
                case Enums.PitchZone.PenaltyArea_Away:
                case Enums.PitchZone.GoalkeeperArea_Away:
                    return 0;

                // Left Flank zones (typically negative values)
                case Enums.PitchZone.HomeDefense_LeftFlank:
                case Enums.PitchZone.Midfield_LeftFlank:
                case Enums.PitchZone.AwayAttack_LeftFlank:
                    return -1;

                // Right Flank zones (typically positive values)
                case Enums.PitchZone.HomeDefense_RightFlank:
                case Enums.PitchZone.Midfield_RightFlank:
                case Enums.PitchZone.AwayAttack_RightFlank:
                    return 1;

                // Corner zones (further out, higher absolute value)
                case Enums.PitchZone.Corner_HomeLeft:
                case Enums.PitchZone.Corner_AwayLeft:
                    return -2;
                case Enums.PitchZone.Corner_HomeRight:
                case Enums.PitchZone.Corner_AwayRight:
                    return 2;

                default:
                    return 0; // Default to center for unknown or None zones
            }
        }

        /// <summary>
        /// Generates a list of PitchZones that represent a simplified path between two zones,
        /// and also includes zones adjacent to that path, useful for pass coverage.
        /// It iteratively moves from the start zone towards the end zone by picking the closest adjacent zone.
        /// </summary>
        /// <param name="startZone">The starting PitchZone (e.g., ball carrier's zone).</param>
        /// <param name="endZone">The ending PitchZone (e.g., potential receiver's zone).</param>
        /// <param name="isHomeTeamPerspective">True if evaluating from home team's perspective, false for away.</param>
        /// <returns>A collection of PitchZones that lie in or near the line between the two given zones.</returns>
        private IEnumerable<Enums.PitchZone> GetZonesInLine(Enums.PitchZone startZone, Enums.PitchZone endZone, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZonesInLine: startZone:{0},endZone:{1},isHomeTeamPerspective:{2}",
            //    startZone, endZone, isHomeTeamPerspective));


            List<Enums.PitchZone> path = new List<Enums.PitchZone>();
            Enums.PitchZone current = startZone;
            path.Add(current);

            // Safety limit to prevent infinite loops in case of complex zone layouts or bugs
            const int MaxPathIterations = 15; // Max possible zones on a path, adjust if your pitch is larger
            int iterationCount = 0;

            // Iteratively move from start to end by choosing the adjacent zone closest to the end
            while (current != endZone && iterationCount < MaxPathIterations)
            {
                Enums.PitchZone nextZoneCandidate = Enums.PitchZone.None;
                double minDistanceToEnd = CalculateDistance(current, endZone); // Distance from current to target

                bool foundCloser = false;
                foreach (var adjacent in GetAdjacentZones(current, isHomeTeamPerspective))
                {
                    double distance = CalculateDistance(adjacent, endZone);
                    if (distance < minDistanceToEnd) // Is this adjacent zone closer to the end?
                    {
                        minDistanceToEnd = distance;
                        nextZoneCandidate = adjacent;
                        foundCloser = true;
                    }
                }

                if (foundCloser && nextZoneCandidate != current)
                {
                    current = nextZoneCandidate;
                    path.Add(current);
                }
                else
                {
                    // If no adjacent zone gets us closer, or we're stuck, break the loop.
                    // This can happen if the 'endZone' is only reachable via non-decreasing distance.
                    break;
                }
                iterationCount++;
            }

            // Add zones directly adjacent to the calculated path to represent "pass coverage" area
            List<Enums.PitchZone> coveredZones = new List<Enums.PitchZone>(path);
            foreach (var zoneOnPath in path)
            {
                foreach (var adjacentToPath in GetAdjacentZones(zoneOnPath, isHomeTeamPerspective))
                {
                    coveredZones.Add(adjacentToPath);
                }
            }

            return coveredZones.Distinct(); // Return unique zones to avoid redundant checks
        }

        /// <summary>
        /// Determines the optimal defensive PitchZone for an off-ball player.
        /// Prioritizes: 1. Wall Rush/Re-engagement (for wall players) -> 2. Man-marking (with intelligence) -> 3. Pressing the ball -> 4. Intercepting passes -> 5. Explicit Zonal Marking within the Box (Set Pieces) -> 6. Returning to base defensive position.
        /// </summary>
        /// <param name="player">The off-ball defensive player.</param>
        /// <param name="currentBallZone">The current zone of the ball.</param>
        /// <param name="defendingTeam">The team currently defending.</param>
        /// <returns>The calculated target PitchZone for the player.</returns>
        public Enums.PitchZone DetermineDefensiveZone(Player player, Enums.PitchZone currentBallZone, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DetermineDefensiveZone: player:{0},currentBallZone:{1},defendingTeam:{2}",
            //    player.position, currentBallZone, defendingTeam.Name));


            bool isHomeTeamPerspective = (defendingTeam == HomeTeam);
            Enums.PitchZone targetZone = player.CurrentZone; // Default to current zone if no better option found

            Player opponentBallCarrier = null;
            if (CurrentBallHolder != null && CurrentBallHolder.Team != defendingTeam)
            {
                opponentBallCarrier = CurrentBallHolder;
            }

            // --- Dynamic thresholds based on MarkingStyle (Existing code - unchanged) ---
            int manMarkingAdherenceDistance;
            int minThreatForwardValue;
            switch (defendingTeam.CurrentMarkingStyle)
            {
                case Enums.MarkingStyle.Zonal:
                    manMarkingAdherenceDistance = 4;
                    minThreatForwardValue = 6;
                    break;
                case Enums.MarkingStyle.Mixed:
                    manMarkingAdherenceDistance = 3;
                    minThreatForwardValue = 3;
                    break;
                case Enums.MarkingStyle.ManToMan:
                    manMarkingAdherenceDistance = 1;
                    minThreatForwardValue = 0;
                    break;
                default:
                    manMarkingAdherenceDistance = 3;
                    minThreatForwardValue = 3;
                    break;
            }

            // --- Wall Player Rush/Re-engagement Logic (Highest Priority - unchanged) ---
            if (player.IsWallPlayerForCurrentSetPiece)
            {
                bool isDirectFreeKickInShootingRange = (CurrentMatchState == Enums.MatchState.FreeKick &&
                                                       opponentBallCarrier != null &&
                                                       CalculateDistanceToGoal(currentBallZone, !isHomeTeamPerspective) <= 4.0f);

                if (isDirectFreeKickInShootingRange)
                {
                    double baseRushChance = (player.trueRating.AccelerationForGameCalculations * 0.35 +
                                             player.trueRating.AggressionForGameCalculations * 0.25 +
                                             player.trueRating.AccelerationForGameCalculations * 0.2 +
                                             player.trueRating.DefenseAwarenessForGameCalculations * 0.2);
                    baseRushChance += Dice.d10() - 5;
                    if (player.trueRating.AccelerationForGameCalculations < 40) baseRushChance -= 20;
                    if (player.trueRating.AccelerationForGameCalculations < 40) baseRushChance -= 25;
                    if (player.trueRating.AccelerationForGameCalculations < 60) baseRushChance -= 10;
                    if (player.trueRating.AccelerationForGameCalculations < 60) baseRushChance -= 15;
                    baseRushChance = Math.Max(0, Math.Min(100, baseRushChance));

                    //ShowMessage("Player " + player.fullName + "'s base rush chance: " + baseRushChance + "% Bravery: " +
                    //player.trueRating.ComposureForGameCalculations + ", Aggression: " + player.trueRating.AggressionForGameCalculations +
                    //", Accel: " + player.trueRating.AccelerationForGameCalculations + ", DefAware: " +
                    //    player.trueRating.DefenseAwarenessForGameCalculations + ")");

                    if (CalculateDistance(player.CurrentZone, opponentBallCarrier.CurrentZone) > 1)
                    {
                        if (Dice.d100() < baseRushChance)
                        {
                            //ShowMessage(string.Format("{0} ({1}) **rushes** the free kick taker! (Roll: {2} < Chance: {3:F2})", player.fullName, defendingTeam.Name, Dice.d100(), baseRushChance));
                            player.IsWallPlayerForCurrentSetPiece = false;
                            return opponentBallCarrier.CurrentZone;
                        }
                        else
                        {
                            //ShowMessage(string.Format("{0} ({1}) holds position in the wall (Roll: {2} >= Chance: {3:F2}).", player.fullName, defendingTeam.Name, Dice.d100(), baseRushChance));
                            player.IsWallPlayerForCurrentSetPiece = false;
                        }
                    }
                    else
                    {
                        //ShowMessage(string.Format("{0} ({1}) is already close to the kicker, holding position.", player.fullName, defendingTeam.Name));
                        player.IsWallPlayerForCurrentSetPiece = false;
                    }
                }
                else
                {
                    player.IsWallPlayerForCurrentSetPiece = false;
                    //ShowMessage(string.Format("{0} ({1}) disengages from wall, acting as a regular defender (not a direct FK threat).", player.fullName, defendingTeam.Name));
                }
            }

            // --- 1. Man-Marking Logic (Highest Priority - unchanged) ---
            if (player.MarkedOpponent != null && player.MarkedOpponent.IsAvailable)
            {
                Enums.PitchZone markedOpponentZone = player.MarkedOpponent.CurrentZone;
                int distanceToMarkedOpponent = CalculateDistance(player.CurrentZone, markedOpponentZone);
                int markedOpponentForwardValue = GetZoneForwardValue(markedOpponentZone, !isHomeTeamPerspective);
                bool willStickToMan = false;
                if (distanceToMarkedOpponent <= manMarkingAdherenceDistance)
                {
                    if (IsZoneDangerous(markedOpponentZone, !isHomeTeamPerspective) ||
                        markedOpponentForwardValue >= minThreatForwardValue ||
                        CalculateDistance(markedOpponentZone, currentBallZone) <= 2)
                    {
                        willStickToMan = true;
                    }
                }
                if ((player.Position == Enums.Positions.CenterBack || player.Position == Enums.Positions.CentralDefendingMidfielder) &&
                    IsZoneDangerous(markedOpponentZone, !isHomeTeamPerspective))
                {
                    willStickToMan = true;
                }
                if (defendingTeam.CurrentMarkingStyle == Enums.MarkingStyle.ManToMan &&
                    distanceToMarkedOpponent <= manMarkingAdherenceDistance + 1)
                {
                    willStickToMan = true;
                }
                if (willStickToMan)
                {
                    //ShowMessage(string.Format("{0} ({1}) man-marks {2}.", player.fullName, defendingTeam.Name, player.MarkedOpponent.fullName));
                    return markedOpponentZone;
                }
            }

            // --- 2. Team Pressing Logic (High Priority - unchanged) ---
            Enums.PressingStyle teamPressingStyle = defendingTeam.PressingStyle;
            bool shouldInitiatePress = false;
            double pressBonusModifier = 1.0;
            if (opponentBallCarrier != null && opponentBallCarrier.IsAvailable)
            {
                if (IsBallHolderUnderPressure(opponentBallCarrier))
                {
                    shouldInitiatePress = true;
                    pressBonusModifier += 0.2;
                }
                bool opponentInTheirOwnDefensiveThird =
                    (isHomeTeamPerspective && GetZoneForwardValue(opponentBallCarrier.CurrentZone, false) == 0) ||
                    (!isHomeTeamPerspective && GetZoneForwardValue(opponentBallCarrier.CurrentZone, true) == 0);
                bool opponentInOwnCornerArea =
                    (isHomeTeamPerspective && (opponentBallCarrier.CurrentZone == Enums.PitchZone.Corner_HomeLeft || opponentBallCarrier.CurrentZone == Enums.PitchZone.Corner_HomeRight)) ||
                    (!isHomeTeamPerspective && (opponentBallCarrier.CurrentZone == Enums.PitchZone.Corner_AwayLeft || opponentBallCarrier.CurrentZone == Enums.PitchZone.Corner_AwayRight));
                if (opponentInTheirOwnDefensiveThird || opponentInOwnCornerArea)
                {
                    shouldInitiatePress = true;
                    pressBonusModifier += 0.4;
                }
                if (player.CurrentCondition > (opponentBallCarrier.CurrentCondition + 20))
                {
                    shouldInitiatePress = true;
                    pressBonusModifier += 0.1;
                }
                int opponentForwardValue = GetZoneForwardValue(opponentBallCarrier.CurrentZone, !isHomeTeamPerspective);
                if (teamPressingStyle == Enums.PressingStyle.HighPress)
                {
                    if (opponentForwardValue > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, !isHomeTeamPerspective))
                    {
                        shouldInitiatePress = true;
                        pressBonusModifier += 0.3;
                    }
                }
                else if (teamPressingStyle == Enums.PressingStyle.MidBlock)
                {
                    if (opponentForwardValue <= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, !isHomeTeamPerspective) &&
                        opponentForwardValue >= GetZoneForwardValue(Enums.PitchZone.HomeDefense_Center, !isHomeTeamPerspective))
                    {
                        shouldInitiatePress = true;
                        pressBonusModifier += 0.1;
                    }
                    else
                    {
                        pressBonusModifier -= 0.5;
                    }
                }
                else if (teamPressingStyle == Enums.PressingStyle.LowBlock)
                {
                    if (opponentForwardValue < GetZoneForwardValue(Enums.PitchZone.HomeDefense_Center, !isHomeTeamPerspective) + 1)
                    {
                        shouldInitiatePress = true;
                        pressBonusModifier += 0.2;
                    }
                    else
                    {
                        pressBonusModifier -= 0.8;
                    }
                }
                if (shouldInitiatePress && pressBonusModifier > 0)
                {
                    Enums.PitchZone ballCarrierZone = opponentBallCarrier.CurrentZone;
                    const int PressBallCarrierDistance = 1;
                    if (CalculateDistance(player.CurrentZone, ballCarrierZone) <= PressBallCarrierDistance)
                    {
                        //ShowMessage(string.Format("{0} ({1}) is pressing the ball carrier directly.", player.fullName, defendingTeam.Name));
                        return ballCarrierZone;
                    }
                    else
                    {
                        if (CalculateDistance(player.CurrentZone, ballCarrierZone) <= PressBallCarrierDistance + 2)
                        {
                            IEnumerable<Enums.PitchZone> adjacentToCurrent = GetAdjacentZones(player.CurrentZone, isHomeTeamPerspective);
                            Enums.PitchZone bestPressApproachZone = player.CurrentZone;
                            double minDistanceToBallCarrier = CalculateDistance(player.CurrentZone, ballCarrierZone);
                            foreach (Enums.PitchZone adjZone in adjacentToCurrent)
                            {
                                double dist = CalculateDistance(adjZone, ballCarrierZone);
                                if (dist < minDistanceToBallCarrier)
                                {
                                    minDistanceToBallCarrier = dist;
                                    bestPressApproachZone = adjZone;
                                }
                            }
                            //ShowMessage(string.Format("{0} ({1}) moves to approach the ball carrier.", player.fullName, defendingTeam.Name));
                            return bestPressApproachZone;
                        }
                    }
                }
            }

            // --- 3. Interception & Passing Lane Coverage Logic (MEDIUM-HIGH PRIORITY - REFINED FOR SET PIECES) ---
            // This section is now enhanced for set piece interceptions.
            bool isSetPiece = (CurrentMatchState == Enums.MatchState.CornerKick || CurrentMatchState == Enums.MatchState.FreeKick);

            if (opponentBallCarrier != null)
            {
                Enums.PitchZone bestInterceptionZone = Enums.PitchZone.None;
                double highestInterceptionScore = 0;

                List<Player> potentialReceivers = new List<Player>();
                Team opponentTeam = opponentBallCarrier.Team;
                int maxPassDistanceSquared = MaxPassDistance * MaxPassDistance; // Precompute squared distance

                foreach (Player p in opponentTeam.AvailableOnFieldPlayers)
                {
                    if (p != opponentBallCarrier &&
                        CalculateDistance(opponentBallCarrier.CurrentZone, p.CurrentZone) <= maxPassDistanceSquared &&
                        !IsOffside(p, defendingTeam))
                    {
                        potentialReceivers.Add(p);
                    }
                }

                foreach (Player receiver in potentialReceivers)
                {
                    IEnumerable<Enums.PitchZone> zonesInPassingLane = GetZonesInLine(opponentBallCarrier.CurrentZone, receiver.CurrentZone, isHomeTeamPerspective);

                    double laneValue = GetZoneForwardValue(receiver.CurrentZone, isHomeTeamPerspective) * 10;

                    // **SET PIECE ENHANCEMENT 1: Prioritize dangerous zones more heavily during set pieces**
                    if (receiver.CurrentZone == (isHomeTeamPerspective ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home) ||
                        receiver.CurrentZone == (isHomeTeamPerspective ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home) ||
                        receiver.CurrentZone == Enums.PitchZone.DefensivePenaltyArea_Central || // Attacker in our central box
                        (isSetPiece && (receiver.CurrentZone == Enums.PitchZone.DefensivePenaltyArea_LeftNearPost ||
                                         receiver.CurrentZone == Enums.PitchZone.DefensivePenaltyArea_RightNearPost ||
                                         receiver.CurrentZone == Enums.PitchZone.DefensivePenaltyArea_LeftFarPost ||
                                         receiver.CurrentZone == Enums.PitchZone.DefensivePenaltyArea_RightFarPost)))
                    {
                        laneValue += (isSetPiece ? 70 : 50); // Higher bonus for set pieces
                    }
                    // Add bonus for players in the edge of the box during set pieces for potential cutbacks
                    if (isSetPiece && receiver.CurrentZone == Enums.PitchZone.Defensive_EdgeOfBox)
                    {
                        laneValue += 20;
                    }


                    List<Enums.PitchZone> zonesToCheckForInterception = new List<Enums.PitchZone>(); // Assuming a maximum of 6 adjacent zones
                    foreach (var zone in GetAdjacentZones(player.CurrentZone, isHomeTeamPerspective))
                    {
                        zonesToCheckForInterception.Add(zone);
                    }
                    zonesToCheckForInterception.Add(player.CurrentZone);

                    foreach (Enums.PitchZone potentialInterceptionZone in zonesToCheckForInterception)
                    {
                        if (zonesInPassingLane.Contains(potentialInterceptionZone))
                        {
                            double interceptionProbability = CalculateInterceptionProbability(player, opponentBallCarrier, receiver, potentialInterceptionZone);

                            double currentScore = laneValue * interceptionProbability;

                            // Apply attributes, more weight for set pieces
                            currentScore += player.trueRating.ComposureForGameCalculations * (isSetPiece ? 0.7 : 0.5);
                            currentScore += player.trueRating.PositioningForGameCalculations * (isSetPiece ? 0.7 : 0.5);
                            currentScore += player.trueRating.DefenseAwarenessForGameCalculations * (isSetPiece ? 0.6 : 0.4);

                            // **SET PIECE ENHANCEMENT 2: Factor in aerial abilities for corners**
                            if (isSetPiece && CurrentMatchState == Enums.MatchState.CornerKick)
                            {
                                currentScore += player.trueRating.HeaderForGameCalculations * 0.3; // Bonus for heading ability
                                currentScore += player.trueRating.JumpingForGameCalculations * 0.2; // Bonus for jumping
                            }

                            currentScore -= CalculateDistance(player.CurrentZone, potentialInterceptionZone) * 5;

                            if (CalculateDistance(potentialInterceptionZone, GetDefensiveBasePosition(player, defendingTeam, currentBallZone)) > 2 &&
                                player.MarkedOpponent == null && opponentBallCarrier.CurrentZone != potentialInterceptionZone)
                            {
                                currentScore -= 10;
                            }

                            if (currentScore > highestInterceptionScore)
                            {
                                highestInterceptionScore = currentScore;
                                bestInterceptionZone = potentialInterceptionZone;
                            }
                        }
                    }
                }

                const double MIN_INTERCEPTION_SCORE_THRESHOLD = 20.0;
                // **SET PIECE ENHANCEMENT 3: Slightly lower interception threshold during set pieces to encourage more attempts**
                double actualInterceptionThreshold = isSetPiece ? 18.0 : MIN_INTERCEPTION_SCORE_THRESHOLD;

                if (highestInterceptionScore >= actualInterceptionThreshold)
                {
                    //ShowMessage(string.Format("{0} ({1}) moves to intercept a pass during {2} (Score: {3:F2}).", player.fullName, defendingTeam.Name, isSetPiece ? "set piece" : "open play", highestInterceptionScore));
                    return bestInterceptionZone;
                }
            }

            // --- 5. Explicit Zonal Marking within the Box (Set Pieces) - unchanged from last response ---
            bool isDangerousSetPiece = (CurrentMatchState == Enums.MatchState.CornerKick ||
                                        CurrentMatchState == Enums.MatchState.FreeKick) &&
                                        IsZoneDangerous(currentBallZone, !isHomeTeamPerspective);

            if (isDangerousSetPiece && player.MarkedOpponent == null)
            {
                Enums.PitchZone bestZonalCoverageZone = Enums.PitchZone.None;
                double highestZonalScore = -1.0;

                List<Enums.PitchZone> defendingPenaltyBoxAndEdgeZones = new List<Enums.PitchZone>();
                if (isHomeTeamPerspective)
                {
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.PenaltyArea_Home);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.GoalkeeperArea_Home);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_LeftNearPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_RightNearPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_Central);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_LeftFarPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_RightFarPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.Defensive_EdgeOfBox);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.HomeDefense_Center);
                }
                else
                {
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.PenaltyArea_Away);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.GoalkeeperArea_Away);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_LeftNearPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_RightNearPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_Central);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_LeftFarPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.DefensivePenaltyArea_RightFarPost);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.Defensive_EdgeOfBox);
                    defendingPenaltyBoxAndEdgeZones.Add(Enums.PitchZone.AwayAttack_Center);
                }

                foreach (Enums.PitchZone potentialZonalZone in defendingPenaltyBoxAndEdgeZones)
                {
                    int teammatesInZone = DefendingTeam.AvailableOnFieldOutfielders
                                            .Count(p => p != player && p.CurrentZone == potentialZonalZone);
                    if (teammatesInZone > 1)
                    {
                        continue;
                    }
                    double zonalScore = 0;
                    if (potentialZonalZone == (isHomeTeamPerspective ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away))
                    {
                        zonalScore += 50;
                    }
                    else if (potentialZonalZone == (isHomeTeamPerspective ? Enums.PitchZone.PenaltyArea_Home : Enums.PitchZone.PenaltyArea_Away) ||
                             potentialZonalZone == Enums.PitchZone.DefensivePenaltyArea_Central)
                    {
                        zonalScore += 40;
                    }
                    else if (potentialZonalZone == Enums.PitchZone.DefensivePenaltyArea_LeftNearPost ||
                             potentialZonalZone == Enums.PitchZone.DefensivePenaltyArea_RightNearPost)
                    {
                        zonalScore += 30;
                    }
                    else if (potentialZonalZone == Enums.PitchZone.DefensivePenaltyArea_LeftFarPost ||
                             potentialZonalZone == Enums.PitchZone.DefensivePenaltyArea_RightFarPost)
                    {
                        zonalScore += 20;
                    }
                    else if (potentialZonalZone == Enums.PitchZone.Defensive_EdgeOfBox)
                    {
                        zonalScore += 15;
                    }
                    zonalScore += player.trueRating.PositioningForGameCalculations * 0.7;
                    zonalScore += player.trueRating.DefenseAwarenessForGameCalculations * 0.6;
                    zonalScore += player.trueRating.HeaderForGameCalculations * 0.4;
                    zonalScore -= CalculateDistance(player.CurrentZone, potentialZonalZone) * 5;
                    if (player.Position != Enums.Positions.CenterBack && player.Position != Enums.Positions.CentralDefendingMidfielder)
                    {
                        zonalScore -= CalculateDistance(potentialZonalZone, GetDefensiveBasePosition(player, defendingTeam, currentBallZone)) * 2;
                    }
                    if (zonalScore > highestZonalScore)
                    {
                        highestZonalScore = zonalScore;
                        bestZonalCoverageZone = potentialZonalZone;
                    }
                }
                const double MIN_ZONAL_SCORE_THRESHOLD = 50.0;
                if (highestZonalScore >= MIN_ZONAL_SCORE_THRESHOLD && bestZonalCoverageZone != Enums.PitchZone.None)
                {
                    //ShowMessage(string.Format("{0} ({1}) moves to cover a key zonal area in the box during set piece ({2}). Score: {3:F2}",
                    //                          player.fullName, defendingTeam.Name, bestZonalCoverageZone, highestZonalScore));
                    return bestZonalCoverageZone;
                }
            }

            // --- 4. Zonal Defense / Return to Base Position (Lowest Priority - unchanged) ---
            targetZone = GetDefensiveBasePosition(player, defendingTeam, currentBallZone);
            //ShowMessage(string.Format("{0} ({1}) returns to/covers their base defensive zone.", player.fullName, defendingTeam.Name));
            return targetZone;
        }

        /// <summary>
        /// Determines the optimal base defensive PitchZone for a player when not actively man-marking or pressing.
        /// Considers player's natural position, ball location, teammate positions, and TEAM DEFENSIVE LINE DEPTH.
        /// </summary>
        /// <param name="player">The off-ball defensive player for whom to calculate the base position.</param>
        /// <param name="defendingTeam">The team currently defending.</param>
        /// <param name="currentBallZone">The current zone of the ball.</param>
        /// <returns>The calculated base PitchZone for the player.</returns>
        public Enums.PitchZone GetDefensiveBasePosition(Player player, Team defendingTeam, Enums.PitchZone currentBallZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetDefensiveBasePosition: player:{0},defendingTeam:{1},currentBallZone:{2}",
            //    player.position, defendingTeam.Name, currentBallZone));


            bool isHomeTeamPerspective = (defendingTeam == HomeTeam);
            int ballLateralValue = GetZoneLateralValue(currentBallZone, isHomeTeamPerspective);

            // --- 1. Base Position based on Player's Primary Role/Position ---
            Enums.PitchZone initialBaseZone;

            switch (player.Position) // Using player.Position directly now
            {
                case Enums.Positions.Goalkeeper:
                    initialBaseZone = isHomeTeamPerspective ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    break;
                case Enums.Positions.CenterBack:
                    initialBaseZone = isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                    break;
                case Enums.Positions.LeftBack:
                    initialBaseZone = isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_RightFlank;
                    break;
                case Enums.Positions.RightBack:
                    initialBaseZone = isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_LeftFlank;
                    break;
                case Enums.Positions.CentralDefendingMidfielder:
                case Enums.Positions.CentralMidfielder:
                    initialBaseZone = Enums.PitchZone.Midfield_Center;
                    break;
                case Enums.Positions.LeftMidfielder:
                    initialBaseZone = Enums.PitchZone.Midfield_LeftFlank;
                    break;
                case Enums.Positions.RightMidfielder:
                    initialBaseZone = Enums.PitchZone.Midfield_RightFlank;
                    break;
                case Enums.Positions.CentralAttackingMidfielder:
                case Enums.Positions.Striker:
                case Enums.Positions.LeftWingForward:
                case Enums.Positions.RightWingForward:
                    initialBaseZone = Enums.PitchZone.Midfield_Center; // These players will generally defend higher or midfield
                    break;
                default:
                    initialBaseZone = Enums.PitchZone.Midfield_Center;
                    break;
            }

            // --- NEW: Adjust initialBaseZone based on Team DefensiveLineDepth ---
            Enums.PitchZone depthAdjustedZone = initialBaseZone;

            int currentForwardValue = GetZoneForwardValue(initialBaseZone, isHomeTeamPerspective);
            int targetForwardValue = currentForwardValue; // Start with current, then adjust

            switch (defendingTeam.CurrentDefensiveLineDepth)
            {
                case Enums.DefensiveLineDepth.VeryDeep:
                    // Shift 2-3 steps back towards own goal, but not past GK area
                    targetForwardValue = Math.Max(0, currentForwardValue - 3); // Max(0, ...) ensures it doesn't go below 0 (GK area)
                    break;
                case Enums.DefensiveLineDepth.Deep:
                    // Shift 1-2 steps back
                    targetForwardValue = Math.Max(0, currentForwardValue - 1);
                    break;
                case Enums.DefensiveLineDepth.Standard:
                    // No shift, already at player's natural base position
                    break;
                case Enums.DefensiveLineDepth.High:
                    // Shift 1-2 steps forward towards opponent's goal
                    targetForwardValue = Math.Min(9, currentForwardValue + 1); // Min(9, ...) ensures it doesn't go above 9 (opponent GK area)
                    break;
                case Enums.DefensiveLineDepth.VeryHigh:
                    // Shift 2-3 steps forward
                    targetForwardValue = Math.Min(9, currentForwardValue + 3);
                    break;
            }

            // Now, move the zone iteratively towards the target forward value.
            // Your GetZoneCloserToGoal and GetZoneCloserToOpponentGoal are perfect for this.
            // They prefer staying in the same lateral column, which is ideal here.
            while (GetZoneForwardValue(depthAdjustedZone, isHomeTeamPerspective) < targetForwardValue)
            {
                Enums.PitchZone nextZone = GetZoneCloserToOpponentGoal(depthAdjustedZone, isHomeTeamPerspective);
                if (nextZone == depthAdjustedZone) break; // Can't move further forward
                depthAdjustedZone = nextZone;
            }
            while (GetZoneForwardValue(depthAdjustedZone, isHomeTeamPerspective) > targetForwardValue)
            {
                Enums.PitchZone nextZone = GetZoneCloserToGoal(depthAdjustedZone, isHomeTeamPerspective);
                if (nextZone == depthAdjustedZone) break; // Can't move further back
                depthAdjustedZone = nextZone;
            }

            // Use this depth-adjusted zone as the new starting point for dynamic adjustments
            Enums.PitchZone adjustedBaseZone = depthAdjustedZone;

            // --- 2. Dynamic Adjustment based on Ball Location (Shifting the Defensive Block) ---
            // (This section remains largely the same, but it now adjusts relative to `depthAdjustedZone`)
            int ballForwardValue = GetZoneForwardValue(currentBallZone, isHomeTeamPerspective);
            int playerBaseForwardValue = GetZoneForwardValue(adjustedBaseZone, isHomeTeamPerspective); // Use the new adjusted base

            // Vertical adjustment: Shift lines based on ball depth
            // The conditions here might need slight tweaks based on the new shifted base
            // but the logic of reacting to the ball's position relative to the adjusted line remains
            if (player.Position == Enums.Positions.CenterBack || player.Position == Enums.Positions.LeftBack || player.Position == Enums.Positions.RightBack)
            {
                if (ballForwardValue < playerBaseForwardValue &&
                    playerBaseForwardValue > GetZoneForwardValue(isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center, isHomeTeamPerspective))
                {
                    adjustedBaseZone = GetZoneCloserToGoal(adjustedBaseZone, isHomeTeamPerspective);
                }
                else if (ballForwardValue > playerBaseForwardValue + 1 &&
                         playerBaseForwardValue < GetZoneForwardValue(isHomeTeamPerspective ? Enums.PitchZone.Midfield_Center : Enums.PitchZone.Midfield_Center, isHomeTeamPerspective))
                {
                    adjustedBaseZone = GetZoneCloserToOpponentGoal(adjustedBaseZone, isHomeTeamPerspective);
                }
            }
            else if (player.Position == Enums.Positions.CentralDefendingMidfielder || player.Position == Enums.Positions.CentralMidfielder)
            {
                if (ballForwardValue < playerBaseForwardValue)
                {
                    adjustedBaseZone = GetZoneCloserToGoal(adjustedBaseZone, isHomeTeamPerspective);
                }
                else if (ballForwardValue > playerBaseForwardValue + 1)
                {
                    adjustedBaseZone = GetZoneCloserToOpponentGoal(adjustedBaseZone, isHomeTeamPerspective);
                }
            }
            else if (GetZoneForwardValue(adjustedBaseZone, isHomeTeamPerspective) > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamPerspective) &&
                     ballForwardValue < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamPerspective))
            {
                adjustedBaseZone = GetZoneCloserToGoal(adjustedBaseZone, isHomeTeamPerspective);
            }

            // Lateral adjustment: Shift the block sideways towards the ball (this part remains the same)
            int adjustedBaseLateralValue = GetZoneLateralValue(adjustedBaseZone, isHomeTeamPerspective);

            IEnumerable<Enums.PitchZone> potentialLateralZones = GetAdjacentZones(adjustedBaseZone, isHomeTeamPerspective)
                                                                     .Where(z => GetZoneForwardValue(z, isHomeTeamPerspective) == GetZoneForwardValue(adjustedBaseZone, isHomeTeamPerspective));

            Enums.PitchZone bestLateralShiftZone = adjustedBaseZone;
            double minLateralDistanceToBall = Math.Abs(adjustedBaseLateralValue - ballLateralValue);

            foreach (var adjZone in potentialLateralZones)
            {
                double newLateralDistanceToBall = Math.Abs(GetZoneLateralValue(adjZone, isHomeTeamPerspective) - ballLateralValue);
                if (newLateralDistanceToBall < minLateralDistanceToBall)
                {
                    minLateralDistanceToBall = newLateralDistanceToBall;
                    bestLateralShiftZone = adjZone;
                }
            }
            adjustedBaseZone = bestLateralShiftZone;


            // --- 3. Fill Gaps and Provide Cover (Considering Teammate Positions and Defensive Attributes) ---

            // Your existing HashSet<Enums.PitchZone> occupiedZonesByTeammates is still useful
            // for checking if a *specific* zone is occupied by *another teammate* to avoid collision.
            // It's separate from the total count of defenders in a zone.
            HashSet<Enums.PitchZone> occupiedZonesByTeammates = new HashSet<Enums.PitchZone>();
            foreach (Player teammate in defendingTeam.AvailableOnFieldPlayers)
            {
                if (teammate != player)
                {
                    occupiedZonesByTeammates.Add(teammate.CurrentZone);
                }
            }

            List<Enums.PitchZone> finalPotentialZones = GetAdjacentZones(adjustedBaseZone, isHomeTeamPerspective).ToList();
            finalPotentialZones.Add(adjustedBaseZone);

            double bestCohesionScore = -1000;
            Enums.PitchZone cohesiveTargetZone = adjustedBaseZone;

            foreach (var pz in finalPotentialZones)
            {
                double currentCohesionScore = 0;

                // Use the pre-calculated HashSet for O(1) average lookup time
                if (occupiedZonesByTeammates.Contains(pz))
                {
                    currentCohesionScore -= 50;
                }

                // Bonus for covering a 'dangerous' empty zone
                Enums.PitchZone centralAttackingZoneForOpponent = isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
                Enums.PitchZone penaltyAreaOpponent = isHomeTeamPerspective ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
                int defendersInThisZone;
                if (_currentZoneDefenderCounts.TryGetValue(pz, out defendersInThisZone))
                {
                    // Key was found, 'defendersInThisZone' now holds the value
                    // No need to do anything here, it's already assigned
                }
                else
                {
                    // Key was not found, assign the default value (0 in this case)
                    defendersInThisZone = 0;
                }

                if (pz == centralAttackingZoneForOpponent || pz == penaltyAreaOpponent)
                {
                    if (defendersInThisZone == 0)
                    {
                        currentCohesionScore += 30;
                    }
                    else if (defendersInThisZone < 2)
                    {
                        currentCohesionScore += 15;
                    }
                }

                // Apply player role tendencies for defensive shape
                if (player.Role == Enums.PlayerRole.Winger || player.Role == Enums.PlayerRole.FullBack)
                {
                    int lateralVal = GetZoneLateralValue(pz, isHomeTeamPerspective);
                    if (Math.Abs(lateralVal) > 0)
                    {
                        currentCohesionScore += 10;
                    }
                    if (Math.Abs(lateralVal) == 0 && player.Position != Enums.Positions.CentralMidfielder)
                    {
                        currentCohesionScore -= 5;
                    }
                }
                else if (player.Role == Enums.PlayerRole.CentralMidfielder || player.Role == Enums.PlayerRole.DefensiveMidfielder || player.Role == Enums.PlayerRole.CenterBack)
                {
                    int lateralVal = GetZoneLateralValue(pz, isHomeTeamPerspective);
                    if (Math.Abs(lateralVal) <= 1)
                    {
                        currentCohesionScore += 10;
                    }
                    if (Math.Abs(lateralVal) > 1)
                    {
                        currentCohesionScore -= 5;
                    }
                }

                // Incorporate player's defensive attributes
                currentCohesionScore += player.trueRating.PositioningForGameCalculations * 0.1;
                currentCohesionScore += player.trueRating.ComposureForGameCalculations * 0.05;


                if (currentCohesionScore > bestCohesionScore)
                {
                    bestCohesionScore = currentCohesionScore;
                    cohesiveTargetZone = pz;
                }
            }

            return cohesiveTargetZone;
        }

        /// <summary>
        /// Returns an adjacent PitchZone that is one "step" closer to the defending team's own goal.
        /// Prefers staying in the same lateral column.
        /// </summary>
        private Enums.PitchZone GetZoneCloserToGoal(Enums.PitchZone currentZone, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneCloserToGoal: currentZone:{0},isHomeTeamPerspective:{1}",
            //    currentZone, isHomeTeamPerspective));


            int currentForwardValue = GetZoneForwardValue(currentZone, isHomeTeamPerspective);
            int currentLateralValue = GetZoneLateralValue(currentZone, isHomeTeamPerspective);
            Enums.PitchZone bestZone = currentZone;
            int bestForwardValueDiff = -1; // We want to maximize the reduction in forward value (get closer to goal)

            // Iterate through adjacent zones and find the one that moves "backward" (towards own goal)
            foreach (var adjacentZone in GetAdjacentZones(currentZone, isHomeTeamPerspective))
            {
                int adjacentForwardValue = GetZoneForwardValue(adjacentZone, isHomeTeamPerspective);
                int adjacentLateralValue = GetZoneLateralValue(adjacentZone, isHomeTeamPerspective);

                if (adjacentForwardValue < currentForwardValue) // Is it actually closer to goal?
                {
                    int forwardValueDiff = currentForwardValue - adjacentForwardValue; // How much closer to goal

                    // Prioritize staying in the same lateral column, then choose the best among others
                    if (bestZone == currentZone || // If no better zone found yet
                        (Math.Abs(currentLateralValue - adjacentLateralValue) < Math.Abs(currentLateralValue - GetZoneLateralValue(bestZone, isHomeTeamPerspective))) || // Closer laterally
                        (Math.Abs(currentLateralValue - adjacentLateralValue) == Math.Abs(currentLateralValue - GetZoneLateralValue(bestZone, isHomeTeamPerspective)) && forwardValueDiff > bestForwardValueDiff)) // Same lateral, but moves more significantly back
                    {
                        bestZone = adjacentZone;
                        bestForwardValueDiff = forwardValueDiff;
                    }
                }
            }
            return bestZone;
        }

        /// <summary>
        /// Returns an adjacent PitchZone that is one "step" closer to the opponent's goal.
        /// Prefers staying in the same lateral column.
        /// </summary>
        private Enums.PitchZone GetZoneCloserToOpponentGoal(Enums.PitchZone currentZone, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneCloserToOpponentGoal: currentZone:{0},isHomeTeamPerspective:{1}",
            //    currentZone, isHomeTeamPerspective));


            int currentForwardValue = GetZoneForwardValue(currentZone, isHomeTeamPerspective);
            int currentLateralValue = GetZoneLateralValue(currentZone, isHomeTeamPerspective);
            Enums.PitchZone bestZone = currentZone;
            int bestForwardValueDiff = -1; // We want to maximize the increase in forward value (get closer to opponent goal)

            // Iterate through adjacent zones and find the one that moves "forward" (towards opponent's goal)
            foreach (var adjacentZone in GetAdjacentZones(currentZone, isHomeTeamPerspective))
            {
                int adjacentForwardValue = GetZoneForwardValue(adjacentZone, isHomeTeamPerspective);
                int adjacentLateralValue = GetZoneLateralValue(adjacentZone, isHomeTeamPerspective);

                if (adjacentForwardValue > currentForwardValue) // Is it actually closer to opponent goal?
                {
                    int forwardValueDiff = adjacentForwardValue - currentForwardValue; // How much closer to opp goal

                    // Prioritize staying in the same lateral column, then choose the best among others
                    if (bestZone == currentZone || // If no better zone found yet
                        (Math.Abs(currentLateralValue - adjacentLateralValue) < Math.Abs(currentLateralValue - GetZoneLateralValue(bestZone, isHomeTeamPerspective))) || // Closer laterally
                        (Math.Abs(currentLateralValue - adjacentLateralValue) == Math.Abs(currentLateralValue - GetZoneLateralValue(bestZone, isHomeTeamPerspective)) && forwardValueDiff > bestForwardValueDiff)) // Same lateral, but moves more significantly forward
                    {
                        bestZone = adjacentZone;
                        bestForwardValueDiff = forwardValueDiff;
                    }
                }
            }
            return bestZone;
        }

        // Also, ensure this helper is present for GetFlankOfZone to work:
        private Enums.Flank GetFlankOfZone(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetFlankOfZone: zone:{0}", zone));


            switch (zone)
            {
                case Enums.PitchZone.HomeDefense_LeftFlank:
                case Enums.PitchZone.Midfield_LeftFlank:
                case Enums.PitchZone.AwayAttack_LeftFlank:
                case Enums.PitchZone.Corner_HomeLeft:
                case Enums.PitchZone.Corner_AwayLeft:
                    return Enums.Flank.Left;
                case Enums.PitchZone.HomeDefense_RightFlank:
                case Enums.PitchZone.Midfield_RightFlank:
                case Enums.PitchZone.AwayAttack_RightFlank:
                case Enums.PitchZone.Corner_HomeRight:
                case Enums.PitchZone.Corner_AwayRight:
                    return Enums.Flank.Right;
                default:
                    return Enums.Flank.Center;
            }
        }

        /// <summary>
        /// Determines the appropriate offensive zone for a player when their team has possession.
        /// Logic is based on player's natural position and the player's team perspective.
        /// </summary>
        /// <param name="player">The player.</param>
        /// <param name="ballZone">The current zone of the ball.</param>
        /// <param name="playerTeam">The team the player belongs to (to determine home/away perspective).</param>
        /// <returns>The calculated offensive PitchZone for the player.</returns>
        private Enums.PitchZone DetermineOffensiveZone(Player player, Enums.PitchZone ballZone, Team playerTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DetermineOffensiveZone: player:{0},ballZone:{1},playerTeam:{2}",
            //    player.position, ballZone, playerTeam.Name));


            bool isHomeTeamPlayer = (playerTeam == HomeTeam);
            Enums.PitchZone targetZone; // The desired zone for the player

            // Get the flank of the ball for tactical awareness
            Enums.Flank ballFlank = GetFlankOfZone(ballZone);

            // Determine the player's natural flank based on their position, for consistent logic
            // This is an assumption, you might have player.PreferredFlank property for more realism
            Enums.Flank playerNaturalFlank = Enums.Flank.Center;
            if (player.Position == Enums.Positions.LeftBack || player.Position == Enums.Positions.LeftMidfielder || player.Position == Enums.Positions.LeftWingForward)
            {
                playerNaturalFlank = Enums.Flank.Left;
            }
            else if (player.Position == Enums.Positions.RightBack || player.Position == Enums.Positions.RightMidfielder || player.Position == Enums.Positions.RightWingForward)
            {
                playerNaturalFlank = Enums.Flank.Right;
            }


            switch (player.Position)
            {
                case Enums.Positions.Goalkeeper:
                    // Goalkeepers primarily stay in their box regardless of possession.
                    targetZone = isHomeTeamPlayer ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
                    break;

                case Enums.Positions.CenterBack:
                    // Central defenders push up cautiously, usually no further than midfield.
                    targetZone = isHomeTeamPlayer ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                    if (IsBallInOpponentHalfForTeam(ballZone, playerTeam)) // If ball is deep in opponent's half
                    {
                        targetZone = Enums.PitchZone.Midfield_Center; // Push to central midfield
                    }
                    break;

                case Enums.Positions.LeftBack:
                case Enums.Positions.RightBack:
                    // Fullbacks (LeftBack/RightBack) support on their respective flanks, pushing into midfield/attack.
                    // Default to their defensive flank
                    targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Defensive, isHomeTeamPlayer);

                    if (IsBallInOpponentHalfForTeam(ballZone, playerTeam))
                    {
                        // Push into midfield flank if ball is in opponent's half
                        targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Midfield, isHomeTeamPlayer);
                    }
                    // If ball is on their natural flank and they are deep, they might push further
                    if (ballFlank == playerNaturalFlank &&
                        GetZoneForwardValue(ballZone, !isHomeTeamPlayer) > GetZoneForwardValue(targetZone, !isHomeTeamPlayer))
                    {
                        // Ensure not pushing too far past midfield if they are a pure fullback.
                        // We'll cap their forward movement for realism.
                        int ballForwardValue = GetZoneForwardValue(ballZone, !isHomeTeamPlayer);
                        int midfieldCenterForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, !isHomeTeamPlayer);

                        if (ballForwardValue <= midfieldCenterForwardValue + 1) // Allow them to push slightly into attacking midfield
                        {
                            targetZone = ballZone; // Move towards the ball if it's ahead on their flank
                        }
                        else if (ballForwardValue > midfieldCenterForwardValue + 1)
                        {
                            // If ball is much further ahead, just aim for the advanced midfield flank
                            targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Midfield, isHomeTeamPlayer);
                        }
                    }
                    break;

                case Enums.Positions.CentralDefendingMidfielder:
                case Enums.Positions.CentralMidfielder:
                    // Central midfielders aim for the center of the pitch, pushing into attacking midfield.
                    targetZone = Enums.PitchZone.Midfield_Center;
                    if (IsBallInOpponentHalfForTeam(ballZone, playerTeam))
                    {
                        targetZone = GetOpponentMidfieldZoneForTeam(playerTeam); // Push into opponent's midfield for support
                    }
                    break;

                case Enums.Positions.LeftMidfielder:
                case Enums.Positions.RightMidfielder:
                    // Wide midfielders push high on their respective flanks in the attacking half.
                    targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Midfield, isHomeTeamPlayer);

                    if (IsBallInOpponentHalfForTeam(ballZone, playerTeam))
                    {
                        // Push to opponent's attacking flank if ball is in opponent's half
                        targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Attacking, isHomeTeamPlayer);
                    }
                    // If ball is on their natural flank, they might push up to join attack directly
                    if (ballFlank == playerNaturalFlank &&
                        GetZoneForwardValue(ballZone, !isHomeTeamPlayer) > GetZoneForwardValue(targetZone, !isHomeTeamPlayer))
                    {
                        targetZone = ballZone; // Move towards the ball if it's ahead on their flank
                    }
                    break;

                case Enums.Positions.CentralAttackingMidfielder:
                case Enums.Positions.LeftWingForward:
                case Enums.Positions.RightWingForward:
                case Enums.Positions.Striker:
                    // Attackers aim for very advanced zones near the opponent's goal.
                    targetZone = GetAttackingCentralZoneForTeam(playerTeam); // Default to central attacking zone

                    // Adjust for wide attackers
                    if (player.Position == Enums.Positions.LeftWingForward || player.Position == Enums.Positions.RightWingForward)
                    {
                        targetZone = GetZoneForPlayerFlankAndThird(playerNaturalFlank, Enums.PitchThird.Attacking, isHomeTeamPlayer);
                    }

                    // If the ball is in the opponent's penalty area, attackers flood that area.
                    if (IsBallInOpponentPenaltyAreaForTeam(ballZone, playerTeam))
                    {
                        targetZone = GetOpponentPenaltyAreaForTeam(playerTeam);
                    }
                    break;

                default:
                    targetZone = Enums.PitchZone.Midfield_Center; // Fallback for unhandled positions
                    break;
            }

            // Final Adjustment: If the target zone is logically "nearby" the ball's actual zone,
            // the player will move directly to the ball's zone to join the play.
            if (AreZonesLogicallyClose(targetZone, ballZone, playerTeam))
            {
                if (ballZone == Enums.PitchZone.None)
                {
                    return player.CurrentZone;
                }
                return ballZone;
            }

            if (targetZone == Enums.PitchZone.None)
            {
                return player.CurrentZone;
            }
            return targetZone;
        }

        private Enums.PitchZone GetZoneForPlayerFlankAndThird(Enums.Flank flank, Enums.PitchThird third, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneForPlayerFlankAndThird: flank:{0},third:{1},isHomeTeamPerspective:{2}",
            //    flank, third, isHomeTeamPerspective));



            if (flank == Enums.Flank.Center)
            {
                if (third == Enums.PitchThird.Defensive) return isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center;
                if (third == Enums.PitchThird.Midfield) return Enums.PitchZone.Midfield_Center;
                if (third == Enums.PitchThird.Attacking) return isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
            }
            else if (flank == Enums.Flank.Left)
            {
                if (third == Enums.PitchThird.Defensive) return isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_LeftFlank;
                if (third == Enums.PitchThird.Midfield) return Enums.PitchZone.Midfield_LeftFlank;
                if (third == Enums.PitchThird.Attacking) return isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_LeftFlank : Enums.PitchZone.HomeDefense_LeftFlank;
            }
            else if (flank == Enums.Flank.Right)
            {
                if (third == Enums.PitchThird.Defensive) return isHomeTeamPerspective ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_RightFlank;
                if (third == Enums.PitchThird.Midfield) return Enums.PitchZone.Midfield_RightFlank;
                if (third == Enums.PitchThird.Attacking) return isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_RightFlank : Enums.PitchZone.HomeDefense_RightFlank;
            }

            return Enums.PitchZone.Midfield_Center; // Fallback
        }

        // Now, a method to check if the ball is "in a pressable zone" based on PressingStyle
        private bool IsBallInPressingZone(Enums.PitchZone ballZone, Team defendingTeam, bool isHomeTeamDefending)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsBallInPressingZone: ballZone:{0},defendingTeam:{1},isHomeTeamDefending:{2}",
            //    ballZone, defendingTeam.Name, isHomeTeamDefending));


            ZoneCoordinate ballCoords = GetZoneCoords(ballZone);
            int triggerY = GetPressingStyleTriggerY(defendingTeam.PressingStyle, isHomeTeamDefending);

            if (isHomeTeamDefending)
            {
                // For home team defending, a higher Y means further from their own goal.
                // They want to press when the ball is at or *above* their trigger Y (further from their own goal).
                return ballCoords.Y >= triggerY;
            }
            else
            {
                // For away team defending, a lower Y means further from their own goal.
                // They want to press when the ball is at or *below* their trigger Y (further from their own goal).
                return ballCoords.Y <= triggerY;
            }
        }

        /// <summary>
        /// Finds a pitch zone "behind" the current zone from a specific team's perspective.
        /// </summary>
        /// <param name="currentZone">The zone to move behind from.</param>
        /// <param name="isHomeTeamPerspective">True if moving relative to the Home team's attacking direction, false for Away team.</param>
        /// <returns>A zone further back, or the current zone if already at the deepest point for its type.</returns>
        private Enums.PitchZone GetZoneBehind(Enums.PitchZone currentZone, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneBehind: currentZone:{0},isHomeTeamPerspective:{1}",
            //    currentZone, isHomeTeamPerspective));


            int currentForwardValue = GetZoneForwardValue(currentZone, isHomeTeamPerspective);
            Enums.PitchZone bestBehindZone = currentZone;
            int closestLowerValue = -1; // To find the next zone behind

            foreach (Enums.PitchZone zone in EnumValuesCache<Enums.PitchZone>.GetValues())
            {
                if (zone == Enums.PitchZone.None || zone == PitchZone._ZoneMax) continue;

                int zoneForwardValue = GetZoneForwardValue(zone, isHomeTeamPerspective);

                // Find a zone that is 'behind' the current one (lower forward value)
                // and is also somewhat 'adjacent' or logically connected (e.g., same flank/center)
                if (zoneForwardValue < currentForwardValue && zoneForwardValue > closestLowerValue)
                {
                    // Simple check: Is it in the same "column" (flank/center)?
                    // This is a heuristic. You might need to refine GetZoneDistance to properly categorize flanks.
                    if (EnumCache<Enums.PitchZone>.ToString(currentZone).Contains("LeftFlank") && EnumCache<Enums.PitchZone>.ToString(zone).Contains("LeftFlank") ||
                        EnumCache<Enums.PitchZone>.ToString(currentZone).Contains("RightFlank") && EnumCache<Enums.PitchZone>.ToString(zone).Contains("RightFlank") ||
                        EnumCache<Enums.PitchZone>.ToString(currentZone).Contains("Center") && EnumCache<Enums.PitchZone>.ToString(zone).Contains("Center") ||
                        EnumCache<Enums.PitchZone>.ToString(currentZone).Contains("PenaltyArea") || EnumCache<Enums.PitchZone>.ToString(currentZone).Contains("GoalkeeperArea") ||
                        (GetZoneDistance(currentZone, zone, isHomeTeamPerspective) < 3)) // Also consider if it's generally close
                    {
                        bestBehindZone = zone;
                        closestLowerValue = zoneForwardValue;
                    }
                }
            }
            return bestBehindZone; // Returns the current zone if no suitable zone found behind
        }

        private Enums.PitchZone GetLateralZone(Enums.PitchZone currentZone, int lateralShift, bool isHomeTeamPerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetLateralZone: currentZone:{0},lateralShift:{1},isHomeTeamPerspective:{2}",
            //    currentZone, lateralShift, isHomeTeamPerspective));


            // This is highly dependent on your zone naming convention or an underlying grid.
            // Example logic using string names (less robust, but demonstrates concept):
            string zoneName = EnumCache<Enums.PitchZone>.ToString(currentZone);

            if (lateralShift == 0) // Try to move to center
            {
                if (zoneName.Contains("LeftFlank")) return (currentZone == Enums.PitchZone.HomeDefense_LeftFlank) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.Midfield_Center; // Simplified
                if (zoneName.Contains("RightFlank")) return (currentZone == Enums.PitchZone.HomeDefense_RightFlank) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.Midfield_Center;
                return currentZone; // Already central or cannot shift
            }
            else if (lateralShift == -1) // Try to shift left
            {
                if (zoneName.Contains("Center")) return (currentZone == Enums.PitchZone.HomeDefense_Center) ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.Midfield_LeftFlank;
                if (zoneName.Contains("RightFlank")) return (currentZone == Enums.PitchZone.HomeDefense_RightFlank) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.Midfield_Center; // Shift to center first if on right flank
                return currentZone; // Already on left flank or cannot shift
            }
            else if (lateralShift == 1) // Try to shift right
            {
                if (zoneName.Contains("Center")) return (currentZone == Enums.PitchZone.HomeDefense_Center) ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.Midfield_RightFlank;
                if (zoneName.Contains("LeftFlank")) return (currentZone == Enums.PitchZone.HomeDefense_LeftFlank) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.Midfield_Center; // Shift to center first if on left flank
                return currentZone; // Already on right flank or cannot shift
            }
            return currentZone; // No shift
        }

        private int CountAttackersInZone(Enums.PitchZone zone, Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CountAttackersInZone: zone:{0},attackingTeam:{1}",
            //    zone, attackingTeam.Name));


            // Implementation: Count players from attackingTeam currently in 'zone'
            return attackingTeam.AvailableOnFieldOutfielders.Count(p => p.CurrentZone == zone);
        }

        /// <summary>
        /// Retrieves the conceptual forward value for a given pitch zone,
        /// adjusted based on the attacking team's perspective.
        /// This method is now extremely fast as it relies on pre-calculated data.
        /// </summary>
        /// <param name="zone">The PitchZone to evaluate.</param>
        /// <param name="isAttackingTeamHome">True if the home team is attacking, false if the away team is.</param>
        /// <returns>A conceptual forward value (0-9 scale).</returns>
        public int GetZoneForwardValue(Enums.PitchZone zone, bool isAttackingTeamHome)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetZoneForwardValue: zone:{0},isAttackingTeamHome:{1}", zone, isAttackingTeamHome));
            //
            // _zoneDataMap should be initialized by the MatchEngineHelper constructor or an explicit call.
            // If it's not initialized, this will throw a NullReferenceException, which is better
            // than silent incorrect behavior in a hot path.
            if (!_zoneDataMap.TryGetValue(zone, out ZoneData data))
            {
                // This error should only occur if a PitchZone enum value was added
                // but not initialized in the _zoneCoordinates or InitializeZoneData.
                // It's a setup error, not a runtime performance concern.
                throw new Exception("ERROR: PitchZone " + zone + " not found in _zoneDataMap during runtime lookup. Defaulting to midfield value.");
                //return 4; // Fallback to a sensible default, or throw an exception.
            }

            return isAttackingTeamHome ? data.ForwardValueHomeAttacking : data.ForwardValueAwayAttacking;
        }

        /// <summary>
        /// Retrieves the pre-calculated distance between two pitch zones.
        /// </summary>
        private int GetZoneDistance(Enums.PitchZone zone1, Enums.PitchZone zone2, bool isHomeTeamPerspective)
        {
            if (zone1 == Enums.PitchZone.None || zone2 == Enums.PitchZone.None)
            {
                return int.MaxValue; // Or some other appropriate "invalid" distance
            }

            var cacheKey = new ZoneDistanceKey(zone1, zone2, isHomeTeamPerspective);

            if (_zoneDistanceCache.TryGetValue(cacheKey, out int distance))
            {
                return distance;
            }
            else
            {
                // This should not happen if all zones are correctly populated in the static constructor.
                throw new InvalidOperationException($"CRITICAL ERROR: Distance for ({zone1}, {zone2}, {isHomeTeamPerspective}) not found in cache. Verify PopulateZoneDistanceCache logic.");
            }
        }

