        public List<Enums.PitchZone> GetForwardNeighborZones(Enums.PitchZone zone)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetForwardNeighborZones: zone:{0}", zone));


            if (_forwardNeighborsMap.TryGetValue(zone, out List<Enums.PitchZone> neighbors))
            {
                return neighbors;
            }
            return new List<Enums.PitchZone>(); // Return empty list if no forward zones
        }

        // --- 2. Optimized IsZonePathBlocked ---
        public bool IsZonePathBlocked(Enums.PitchZone startZone, Enums.PitchZone endZone, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsZonePathBlocked: startZone:{0},endZone:{1}," +
            //    "defendingTeam:{2}", startZone, endZone, defendingTeam.Name));

            // Use the pre-computed path from the MatchEngineHelper
            List<Enums.PitchZone> pathZones = GetZonesAlongPath(startZone, endZone, defendingTeam == HomeTeam).ToList();

            if (pathZones == null || !pathZones.Any())
            {
                return false;
            }

            foreach (Enums.PitchZone pathZone in pathZones)
            {
                // Defenders in the startZone are not "blocking the path" *from* that zone.
                // They are already there with the ball carrier.
                if (pathZone == startZone)
                {
                    continue;
                }

                // Use the optimized CountDefendersInZone which uses _defendersInZoneMap
                int defendersInPathZone = CountDefendersInZone(pathZone, defendingTeam);

                if (defendersInPathZone > 0)
                {
                    return true; // Path is blocked if any defender is in an intervening zone.
                }
            }
            return false; // No defenders found directly blocking the path
        }

        // Helper for CalculateActualPath (you must implement this based on your zone definitions)
        public Enums.PitchZone FindZoneByForwardAndFlank(int forwardValue, Enums.Flank flank, bool isHomePerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("FindZoneByForwardAndFlank: forwardValue:{0},flank:{1}," +
            //    "isHomePerspective:{2}",
            //    forwardValue, flank, isHomePerspective));

            // Iterate through your _zoneDataMap to find a matching zone
            foreach (var entry in _zoneDataMap)
            {
                Enums.PitchZone zone = entry.Key;
                ZoneData data = entry.Value;

                // Get the correct forward value based on perspective
                int zoneFwdValue = isHomePerspective ? data.ForwardValueHomeAttacking : data.ForwardValueAwayAttacking;

                // Convert LateralValue (from -2 to 2) to Flank enum (Left, Center, Right)
                Enums.Flank zoneFlank = GetFlankOfZone(zone); // Re-use your existing GetFlankOfZone for consistency

                // Check if both forward value and flank match
                // Prioritize exact flank match, but allow Center to match Left/Right if explicit flank isn't found
                if (zoneFwdValue == forwardValue)
                {
                    if (zoneFlank == flank)
                    {
                        return zone;
                    }
                    // If the requested flank is Center, or if it's a specific flank and this zone is Center, consider it.
                    // This logic might need fine-tuning based on how strictly you want to match flanks for pathfinding.
                    // For example, if you ask for Midfield_Center, and there's a zone with that precise flank.
                    // Or if you ask for Midfield_Left and Midfield_Center is the closest/only option.
                    if (flank == Enums.Flank.Center && zoneFlank == Enums.Flank.Center)
                    {
                        return zone; // Found a center zone at the right forward value
                    }
                    if (flank != Enums.Flank.Center && zoneFlank == Enums.Flank.Center)
                    {
                        // If we're looking for a specific flank (Left/Right) but the central zone at the
                        // correct forward value is the only option, we might return it as a fallback.
                        // This makes paths more robust.
                        // You could add further logic here to prefer closest X, or check if it's the "best fit"
                        // but for basic pathfinding, returning a central zone can be acceptable.
                        return zone;
                    }
                }
            }

            // If no exact match or suitable fallback is found, return None
            return Enums.PitchZone.None;
        }

        // --- 3. Optimized CountDefendersInZone ---
        public int CountDefendersInZone(Enums.PitchZone zone, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CountDefendersInZone: zone:{0},defendingTeam:{1}",
            //    zone, defendingTeam.Name));


            // Use the pre-populated map directly for O(1) lookup
            if (_defendersInZoneMap.TryGetValue(zone, out List<Player> defenders))
            {
                return defenders.Count;
            }
            return 0; // No defenders in this zone (or zone not in map)
        }

        // Method to populate the _defendersInZoneMap (called once per SimulateMoment)
        public void PopulateDefendersInZoneMap(Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("PopulateDefendersInZoneMap: defendingTeam:{0}", defendingTeam.Name));

            _defendersInZoneMap.Clear(); // Clear from previous moment

            // Initialize all valid zones with empty lists to avoid null checks later
            foreach (Enums.PitchZone zone in Enum.GetValues(typeof(Enums.PitchZone)))
            {
                if (zone != Enums.PitchZone.None)
                {
                    _defendersInZoneMap[zone] = new List<Player>();
                }
            }

            // Iterate through defending team's players and add them to their respective zone lists
            // I'm assuming you want to count available, non-sent off players.
            // If you only want outfielders, change defendingTeam.OnFieldPlayers to defendingTeam.OnFieldOutfielders.
            foreach (Player defender in defendingTeam.AvailableOnFieldPlayers)
            {
                // Ensure the zone exists in the map (it should if initialized above)
                if (_defendersInZoneMap.ContainsKey(defender.CurrentZone))
                {
                    _defendersInZoneMap[defender.CurrentZone].Add(defender);
                }
                else
                {
                    throw new Exception("Warning: Defender " + defender.fullName + " is in unmapped zone " + defender.CurrentZone + ".");
                }
            }
        }

