        #region Calculations

        /// <summary>
        /// Helper method to calculate a player's suitability for a specific offensive set piece role.
        /// </summary>
        private double CalculateOffensiveRoleSuitability(Player p, Enums.SetPieceRole spRole)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateOffensiveRoleSuitability: p:{0},spRole:{1}",
            //    p.position, spRole));


            switch (spRole)
            {
                case Enums.SetPieceRole.NearPostRunner:
                    return p.trueRating.SprintForGameCalculations * 0.4 + p.trueRating.AccelerationForGameCalculations * 0.3 + p.trueRating.HeaderForGameCalculations * 0.3;
                case Enums.SetPieceRole.TargetMan:
                    return p.trueRating.HeaderForGameCalculations * 0.5 + p.trueRating.JumpingForGameCalculations * 0.3 + p.trueRating.StrengthForGameCalculations * 0.2;
                case Enums.SetPieceRole.ReboundAttacker:
                    return p.trueRating.LongShotForGameCalculations * 0.5 + p.trueRating.VisionForGameCalculations * 0.3 + p.trueRating.ComposureForGameCalculations * 0.2;
                case Enums.SetPieceRole.ShortOptionReceiver:
                    return p.trueRating.PositioningForGameCalculations * 0.4 + p.trueRating.DribblingForGameCalculations * 0.3 + p.trueRating.PassingForGameCalculations * 0.3;
                case Enums.SetPieceRole.MidfieldSupport:
                    return p.trueRating.PositioningForGameCalculations * 0.4 + p.trueRating.PaceForGameCalculations * 0.3 + p.trueRating.StaminaForGameCalculations * 0.3;
                case Enums.SetPieceRole.OffensiveBlocker:
                    return p.trueRating.StrengthForGameCalculations * 0.5 + p.trueRating.AggressionForGameCalculations * 0.3 + p.trueRating.BalanceForGameCalculations * 0.2;
                case Enums.SetPieceRole.FarPostThreat:
                    return p.trueRating.PositioningForGameCalculations * 0.4 + p.trueRating.SprintForGameCalculations * 0.3 + p.trueRating.FinishingForGameCalculations * 0.3;
                case Enums.SetPieceRole.BoxAttacker:
                    return p.trueRating.FinishingForGameCalculations * 0.4 + p.trueRating.PositioningForGameCalculations * 0.3 + p.trueRating.PositioningForGameCalculations * 0.3;
                default:
                    return 0;
            }
        }

        /// <summary>
        /// Helper method to calculate a player's suitability for a specific defensive set piece role.
        /// </summary>
        private double CalculateDefensiveRoleSuitability(Player p, Enums.SetPieceRole spRole)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateDefensiveRoleSuitability: p:{0},spRole:{1}",
            //    p.position, spRole));


            switch (spRole)
            {
                case Enums.SetPieceRole.WallPlayer:
                    return p.trueRating.StrengthForGameCalculations * 0.5 + p.trueRating.AggressionForGameCalculations * 0.3 + p.trueRating.ComposureForGameCalculations * 0.2;
                case Enums.SetPieceRole.PostBlocker:
                    return p.trueRating.ComposureForGameCalculations * 0.4 + p.trueRating.PositioningForGameCalculations * 0.3 + p.trueRating.AgilityForGameCalculations * 0.3;
                case Enums.SetPieceRole.ZonalMarker:
                    return p.trueRating.PositioningForGameCalculations * 0.5 + p.trueRating.VisionForGameCalculations * 0.3 + p.trueRating.ComposureForGameCalculations * 0.2;
                case Enums.SetPieceRole.ManMarker:
                    return p.trueRating.DefendingForGameCalculations * 0.4 + p.trueRating.AgilityForGameCalculations * 0.3 + p.trueRating.StrengthForGameCalculations * 0.2 + p.trueRating.PaceForGameCalculations * 0.1;
                case Enums.SetPieceRole.ClearingDefender:
                    return p.trueRating.HeaderForGameCalculations * 0.4 + p.trueRating.JumpingForGameCalculations * 0.3 + p.trueRating.SlideTackleForGameCalculations * 0.3;
                case Enums.SetPieceRole.CounterAttackOutlet:
                    return p.trueRating.PaceForGameCalculations * 0.4 + p.trueRating.PositioningForGameCalculations * 0.3 + p.trueRating.PassingForGameCalculations * 0.3;
                case Enums.SetPieceRole.EdgeOfBoxSweeper:
                    return p.trueRating.InterceptForGameCalculations * 0.4 + p.trueRating.PositioningForGameCalculations * 0.3 + p.trueRating.SlideTackleForGameCalculations * 0.3;
                case Enums.SetPieceRole.DeepDefender:
                    return p.trueRating.PositioningForGameCalculations * 0.4 + p.trueRating.SlideTackleForGameCalculations * 0.3 + p.trueRating.ComposureForGameCalculations * 0.3;
                case Enums.SetPieceRole.GoalkeeperCover: // For the actual GK
                    return p.trueRating.GoalKeepingPositioningForGameCalculations * 1.0; // Primary attribute for GK
                default:
                    return 0;
            }
        }

        /// <summary>
        /// Calculates a relative 'distance' from the free kick zone to the defending team's goal.
        /// Lower value means closer to the goal.
        /// </summary>
        /// <param name="freeKickZone">The PitchZone where the free kick is taken.</param>
        /// <param name="isAttackingHomeGoal">True if the attacking team is attacking the home goal (meaning defending team is Home).</param>
        /// <returns>A float representing the distance. 0.0 is on the goal line.</returns>
        private float CalculateDistanceToGoal(Enums.PitchZone freeKickZone, bool isAttackingHomeGoal)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateDistanceToGoal: freeKickZone:{0},isAttackingHomeGoal:{1}",
            //    freeKickZone, isAttackingHomeGoal));


            float freeKickDepth = GetPitchZoneDepth(freeKickZone);
            float defendingGoalLineDepth = isAttackingHomeGoal ? 0.0f : 10.0f; // Home goal is 0, Away goal is 10

            // Distance is the absolute difference to the *defending* team's goal line
            return Math.Abs(freeKickDepth - defendingGoalLineDepth);
        }

        /// <summary>
        /// Performs the actual calculation of the defensive line and caches the result.
        /// This method is only called when the cache needs to be updated.
        /// </summary>
        private void CalculateAndCacheDefensiveLine(Team defendingTeam, bool isHomeTeamPerspective, int currentMomentId)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateAndCacheDefensiveLine: defendingTeam:{0},isHomeTeamPerspective:{1}," +
            //    "currentMomentId:{2}",
            //    defendingTeam.Name, isHomeTeamPerspective, currentMomentId));


            List<Player> activeDefenders = new List<Player>(6);
            foreach (Player p in defendingTeam.AvailableOnFieldOutfielders)
            {
                switch (p.Position)
                {
                    case Enums.Positions.CenterBack:
                    case Enums.Positions.LeftBack:
                    case Enums.Positions.RightBack:
                    case Enums.Positions.CentralDefendingMidfielder:
                        activeDefenders.Add(p);
                        break;
                }
            }

            Enums.PitchZone calculatedDefensiveLineZone = Enums.PitchZone.None;
            int calculatedMaxForwardValue = -1;

            if (!activeDefenders.Any())
            {
                // Fallback to a default defensive zone if no defenders found.
                calculatedDefensiveLineZone = isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
                calculatedMaxForwardValue = GetZoneForwardValue(calculatedDefensiveLineZone, isHomeTeamPerspective);
            }
            else
            {
                foreach (var defender in activeDefenders)
                {
                    int defenderForwardValue = GetZoneForwardValue(defender.CurrentZone, isHomeTeamPerspective);
                    if (defenderForwardValue > calculatedMaxForwardValue)
                    {
                        calculatedMaxForwardValue = defenderForwardValue;
                        calculatedDefensiveLineZone = defender.CurrentZone;
                    }
                }
            }

            // Final fallback just in case no suitable zone was determined
            if (calculatedDefensiveLineZone == Enums.PitchZone.None)
            {
                calculatedDefensiveLineZone = isHomeTeamPerspective ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center;
                calculatedMaxForwardValue = GetZoneForwardValue(calculatedDefensiveLineZone, isHomeTeamPerspective);
            }

            // Store the newly calculated values in the cache
            _cachedDefensiveLines[defendingTeam] = calculatedDefensiveLineZone;
            _cachedDefensiveLineForwardValues[defendingTeam] = calculatedMaxForwardValue;
            _lastDefensiveLineCalculationMomentId[defendingTeam] = currentMomentId; // Store the moment ID when it was calculated
        }

        // This method would reside in your MatchEngine or a dedicated SetPieceLogic class
        private double CalculateDefensiveSetPieceMovementScore(Player defender, DefensiveSetPieceRoutine currentRoutine, Enums.PitchZone potentialTargetZone, Team defendingTeam, List<Player> attackingPlayers)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateDefensiveSetPieceMovementScore: defender:{0},currentRoutine:{1}," +
            //    "potentialTargetZone:{2},defendingTeam:{3},attackingPlayers:{4}",
            //    defender.position, currentRoutine, potentialTargetZone, defendingTeam.Name,
            //    string.Join(",", attackingPlayers.Select(p => p.position))));


            double score = 0;

            Enums.PitchZone defendersPenaltyArea = (defendingTeam == HomeTeam) ? Enums.PitchZone.PenaltyArea_Home : Enums.PitchZone.PenaltyArea_Away;
            Enums.PitchZone defendersGoalkeeperArea = (defendingTeam == HomeTeam) ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;

            // Determine the defending team's *own* central defensive zone.
            Enums.PitchZone defendersOwnDefensiveCenter = (defendingTeam == HomeTeam) ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center; // AwayAttack_Center is the conceptual "HomeDefense_Center" when viewed from the away team's side.

            // 1. Base Score based on Role's Primary Objective
            switch (defender.DefensiveSetPieceRole)
            {
                case Enums.SetPieceRole.ManMarker:
                    if (defender.MarkedOpponent != null)
                    {
                        if (potentialTargetZone == defender.MarkedOpponent.SimulatedSetPieceZone)
                        {
                            score += 150;
                        }
                        else if (IsAdjacentZone(potentialTargetZone, defender.MarkedOpponent.SimulatedSetPieceZone))
                        {
                            score += 75;
                        }
                        score -= CalculateDistance(potentialTargetZone, defender.MarkedOpponent.SimulatedSetPieceZone) * 10;
                    }
                    break;

                case Enums.SetPieceRole.ZonalMarker:
                    Enums.ConceptualSetPieceZone conceptualZonalCoverage = Enums.ConceptualSetPieceZone.None;
                    if (!currentRoutine.PreferredZoneCoverage.TryGetValue(defender.DefensiveSetPieceRole, out conceptualZonalCoverage))
                    {
                        conceptualZonalCoverage = Enums.ConceptualSetPieceZone.None;
                    }
                    // This needs to translate the conceptual zone from the *defending team's* perspective.
                    // If the routine says "OpponentPenaltyArea_General" for zonal, that's THEIR own penalty area.
                    Enums.PitchZone actualZonalCoverage = TranslateConceptualZone(conceptualZonalCoverage, defendingTeam);

                    if (potentialTargetZone == actualZonalCoverage)
                    {
                        score += 120;
                    }
                    else if (IsAdjacentZone(potentialTargetZone, actualZonalCoverage))
                    {
                        score += 60;
                    }
                    break;

                case Enums.SetPieceRole.PostBlocker:
                    if (potentialTargetZone == defendersGoalkeeperArea)
                    {
                        score += 130;
                    }
                    break;

                case Enums.SetPieceRole.WallPlayer:
                    // Wall players should position in their *own* defensive center or flanks for free kicks
                    // For corner context, this is more about intercepting loose balls or short passes.
                    if (potentialTargetZone == defendersOwnDefensiveCenter ||
                        potentialTargetZone == ((defendingTeam == HomeTeam) ? Enums.PitchZone.HomeDefense_LeftFlank : Enums.PitchZone.AwayAttack_RightFlank) ||
                        potentialTargetZone == ((defendingTeam == HomeTeam) ? Enums.PitchZone.HomeDefense_RightFlank : Enums.PitchZone.AwayAttack_LeftFlank))
                    {
                        score += 80;
                    }
                    break;

                case Enums.SetPieceRole.ClearingDefender:
                    if (potentialTargetZone == defendersPenaltyArea)
                    {
                        score += 100;
                    }
                    score += defender.trueRating.HeaderForGameCalculations * 0.2 + defender.trueRating.JumpingForGameCalculations * 0.2;
                    break;

                case Enums.SetPieceRole.CounterAttackOutlet:
                    if (potentialTargetZone == Enums.PitchZone.Midfield_Center ||
                        potentialTargetZone == Enums.PitchZone.Midfield_LeftFlank ||
                        potentialTargetZone == Enums.PitchZone.Midfield_RightFlank)
                    {
                        score += 90;
                    }
                    break;

                case Enums.SetPieceRole.None:
                    if (potentialTargetZone == defendersPenaltyArea || potentialTargetZone == defendersGoalkeeperArea)
                    {
                        score += 30;
                    }
                    break;
            }

            // 2. Player Attributes for Defensive Positioning (no change)
            score += defender.trueRating.PositioningForGameCalculations * 0.4;
            score += defender.trueRating.AgilityForGameCalculations * 0.3;
            score += defender.trueRating.ComposureForGameCalculations * 0.2;
            score += defender.trueRating.DefendingForGameCalculations * 0.1;

            // 3. Avoid Overcrowding by Teammates (unless it's a wall or specific tactic) (no change)
            int teammatesInZone = defendingTeam.AvailableOnFieldOutfielders
                .Count(p => p != defender && p.SimulatedSetPieceZone == potentialTargetZone);

            if (teammatesInZone > 0 && defender.DefensiveSetPieceRole != Enums.SetPieceRole.WallPlayer)
            {
                score -= teammatesInZone * 20;
            }

            // 4. Consider Opponent Presence (Beyond Man-Marking) (no change)
            int attackersInZone = attackingPlayers
                .Count(ap => ap.SimulatedSetPieceZone == potentialTargetZone);

            if (attackersInZone > 0 && defender.DefensiveSetPieceRole == Enums.SetPieceRole.ZonalMarker)
            {
                score += attackersInZone * 10;
            }

            return Math.Max(0, score);
        }
        private double CalculateOffensiveSetPieceMovementScore(Player player, OffensiveCornerRoutine currentRoutine, Enums.PitchZone potentialTargetZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateOffensiveSetPieceMovementScore: player:{0},currentRoutine:{1}," +
            //    "potentialTargetZone:{2},attackingTeam:{3},defendingTeam:{4}",
            //    player.position, currentRoutine, potentialTargetZone, attackingTeam.Name, defendingTeam.Name));


            double score = 0;

            // Get the actual PitchZone for the player's preferred conceptual sub-zone
            Enums.ConceptualSetPieceZone conceptualPreferredSubZone = Enums.ConceptualSetPieceZone.None;
            if (!currentRoutine.PreferredRoleConceptualSubZones.TryGetValue(player.OffensiveSetPieceRole, out conceptualPreferredSubZone))
            {
                conceptualPreferredSubZone = Enums.ConceptualSetPieceZone.None;
            }
            Enums.PitchZone actualPreferredSubZone = TranslateConceptualZone(conceptualPreferredSubZone, attackingTeam);

            // Get the actual general opponent penalty area
            Enums.PitchZone actualOpponentPenaltyArea = TranslateConceptualZone(Enums.ConceptualSetPieceZone.OpponentPenaltyArea_General, attackingTeam);
            Enums.PitchZone actualOpponentAttackingThirdCentralEdge = TranslateConceptualZone(Enums.ConceptualSetPieceZone.OpponentAttackingThird_CentralEdge, attackingTeam);


            // 1. Base Score based on Role's Preferred Sub-Zone
            if (actualPreferredSubZone != Enums.PitchZone.None && potentialTargetZone == actualPreferredSubZone)
            {
                score += 100; // Strong bonus for being in the exact preferred zone for their role
            }
            else if (potentialTargetZone == actualOpponentPenaltyArea && actualPreferredSubZone != Enums.PitchZone.None)
            {
                score += 50; // Bonus for being in the general penalty area if their role usually operates there
            }
            // Specific bonus for rebound players positioning just outside the box, relative to the opponent's area
            else if (player.OffensiveSetPieceRole == Enums.SetPieceRole.ReboundAttacker && potentialTargetZone == actualOpponentAttackingThirdCentralEdge)
            {
                score += 70;
            }


            // 2. Player Attributes for Movement & Positioning (no change)
            score += player.trueRating.VisionForGameCalculations * 0.5;
            score += player.trueRating.PositioningForGameCalculations * 0.3;
            score += player.trueRating.AgilityForGameCalculations * 0.2;

            // 3. Role-Specific Attribute Bonuses (no change)
            switch (player.OffensiveSetPieceRole)
            {
                case Enums.SetPieceRole.TargetMan:
                case Enums.SetPieceRole.NearPostRunner:
                case Enums.SetPieceRole.FarPostThreat:
                    score += player.trueRating.HeaderForGameCalculations * 0.3;
                    score += player.trueRating.JumpingForGameCalculations * 0.2;
                    score += player.trueRating.StrengthForGameCalculations * 0.1;
                    break;
                case Enums.SetPieceRole.ReboundAttacker:
                    score += player.trueRating.LongShotForGameCalculations * 0.2;
                    score += player.trueRating.ComposureForGameCalculations * 0.1;
                    break;
                case Enums.SetPieceRole.ShortOptionReceiver:
                    score += player.trueRating.DribblingForGameCalculations * 0.2;
                    score += player.trueRating.BalanceForGameCalculations * 0.1;
                    break;
            }

            // 4. Defender Influence (same logic, assumes GetPlayerZone(d) is correct for defender's current team/zone)
            List<Player> nearbyDefenders = new List<Player>();
            foreach (Player defender in defendingTeam.AvailableOnFieldPlayers)
            {
                Enums.PitchZone defenderZone = GetPlayerZone(defender);
                if (defenderZone == potentialTargetZone || IsAdjacentZone(defenderZone, potentialTargetZone))
                {
                    nearbyDefenders.Add(defender);
                }
            }

            double markingPenalty = 0;
            foreach (var defender in nearbyDefenders)
            {
                markingPenalty += defender.trueRating.DefendingForGameCalculations * 0.5;
                markingPenalty += defender.trueRating.PositioningForGameCalculations * 0.2;

                if (nearbyDefenders.Count > 1 && potentialTargetZone == actualOpponentPenaltyArea) // Check against the correct penalty area
                {
                    markingPenalty += 20;
                }
            }
            score -= markingPenalty;

            // 5. Avoid Offside (simplified, no change)

            return Math.Max(0, score);
        }


        /// <summary>
        /// Calculates a score for a player moving to a specific target zone,
        /// considering various tactical factors.
        /// </summary>
        /// <param name="player">The player whose movement is being evaluated.</param>
        /// <param name="targetZone">The potential target PitchZone for the player.</param>
        /// <param name="ballZone">The current PitchZone of the ball.</param>
        /// <param name="attackingTeam">The team currently in possession.</param>
        /// <param name="defendingTeam">The opposing team.</param>
        /// <param name="currentTeamTactic">The current overall tactic of the attacking team.</param>
        /// <returns>A double score indicating the desirability of moving to the targetZone.</returns>
        private double CalculateMovementScore(Player player, Enums.PitchZone targetZone, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam, Enums.TeamTactic currentTeamTactic,
            int currentMinute, int currentSecond)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateMovementScore: player:{0},targetZone:{1},ballZone:{2}," +
            //    "attackingTeam:{3},defendingTeam:{4},currentTeamTactic:{5},currentMinute:{6},currentSecond:{7}",
            //    player.position, targetZone, ballZone, attackingTeam.Name, defendingTeam.Name,
            //    currentTeamTactic, currentMinute, currentSecond));


            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);
            double score = 0;

            // Ensure invalid targetZone is heavily penalized
            if (targetZone == Enums.PitchZone.None) return -100000.0;

            // --- Conditional Offside Awareness Logic ---
            // Offside rule does NOT apply directly at the moment of an indirect free kick.
            // It also doesn't apply for direct free kicks if it's a shot.
            // It *does* apply for passes from direct free kicks and once the ball is in play from indirect.

            // If we are currently in an indirect free kick state and player is deciding initial movement for the pass receiver
            // OR if it's a direct free kick and we're looking for a pass target (not a shot taker)
            // we need to be careful.

            // For the initial decision *before the kick is taken*, a player is NOT offside if they are behind the ball.
            // The standard offside rule regarding the "second to last defender" applies once the ball is played forward.

            // Simplified rule for free kicks:
            // If it's a FreeKick_Indirect, or a FreeKick where it's explicitly a pass,
            // players can be in an "offside position" *relative to the defender*,
            // but the actual offside offense only occurs if they *interfere with play*
            // or *gain an advantage* from that position *after* the ball is touched by another teammate.

            // This is tricky. For movement *before* the pass, they should only care about being behind the ball.
            // For general in-play movement, the full offside rule applies.

            // Let's assume this `CalculateMovementScore` is primarily for *receiving a pass* after a free kick is taken,
            // or for general movement.
            // If you are using this to decide where players *move to* before the pass, then the offside rule is slightly different.

            bool isCurrentlyFreeKick = (CurrentMatchState == Enums.MatchState.FreeKick || CurrentMatchState == Enums.MatchState.FreeKick_Indirect);

            if (isCurrentlyFreeKick)
            {
                // For free kicks, especially indirect, the immediate offside check is complex.
                // A player is onside if they are behind the ball at the moment of the kick.
                // If the player is deciding *where to run to receive a pass*, then the *destination* targetZone
                // needs to be evaluated against the offside line *at the moment the ball is played*.
                // This is what your current offside logic does, but it might be too strict if it prevents players
                // from making legitimate runs *behind* defenders but *behind the ball*.

                // Let's refine the offside check for free kicks:
                // A player is offside if they are in the opponent's half AND
                // they are nearer to the opponent's goal line than both the ball AND the second-to-last opponent.

                // However, from a free kick, players can be *ahead* of the ball, as long as they are onside
                // relative to the defenders. The "behind the ball" clause usually applies to throw-ins or goal kicks.
                // The *major* distinction for indirect free kicks is that you cannot score directly, and offside
                // only triggers *after* a second touch.

                // Given your issue is *repeated* offsides, the most common reason for this
                // is the offside rule being applied too strictly when a player is simply choosing a *target zone*
                // for a pass *from a free kick*.

                // Let's try this: Disable the offside check *entirely* if CurrentMatchState is FreeKick_Indirect.
                // For FreeKick (direct), we still need to check it if it's a pass attempt.

                if (CurrentMatchState != Enums.MatchState.FreeKick_Indirect) // Only apply the full offside check if NOT an indirect free kick
                {
                    Player secondToLastOpponent = FindSecondToLastOpponent(defendingTeam, attackingTeam);

                    if (secondToLastOpponent != null)
                    {
                        int receiverAbsoluteDepth = GetAbsolutePitchDepth(targetZone);
                        int secondToLastOpponentAbsoluteDepth = GetAbsolutePitchDepth(secondToLastOpponent.CurrentZone);
                        int ballPlayedAbsoluteDepth = GetAbsolutePitchDepth(ballZone);
                        int HalfwayLineDepth = GetAbsolutePitchDepth(Enums.PitchZone.Midfield_Center); // This is 3

                        bool receiverWouldBeInAttackingHalf;
                        if (attackingTeam == HomeTeam)
                        {
                            receiverWouldBeInAttackingHalf = receiverAbsoluteDepth > HalfwayLineDepth;
                        }
                        else
                        {
                            receiverWouldBeInAttackingHalf = receiverAbsoluteDepth < HalfwayLineDepth;
                        }

                        bool receiverWouldBeOffsidePosition = false;

                        if (receiverWouldBeInAttackingHalf)
                        {
                            if (attackingTeam == HomeTeam)
                            {
                                receiverWouldBeOffsidePosition = (receiverAbsoluteDepth > secondToLastOpponentAbsoluteDepth) &&
                                                                 (receiverAbsoluteDepth > ballPlayedAbsoluteDepth);
                            }
                            else
                            {
                                receiverWouldBeOffsidePosition = (receiverAbsoluteDepth < secondToLastOpponentAbsoluteDepth) &&
                                                                 (receiverAbsoluteDepth < ballPlayedAbsoluteDepth);
                            }
                        }

                        if (receiverWouldBeOffsidePosition)
                        {
                            return -100000.0; // Strong penalty
                        }
                    }
                }
            }
            // --- END OF CONDITIONAL OFFSIDE AWARENESS LOGIC ---

            // Determine key zones for reference (relying on your helper methods)
            Enums.PitchZone opponentGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
            Enums.PitchZone playerHomeGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Home : Enums.PitchZone.GoalkeeperArea_Away;
            Enums.PitchZone opponentDefensiveLineZone = GetOpponentDefensiveLineZone(defendingTeam, isHomeTeamAttacking, currentMinute, currentSecond);

            // --- Core Scoring Logic ---

            // 1. Positional Value (getting closer to opponent's goal)
            int distanceToOpponentGoal = GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking);
            score += (double)(10 - distanceToOpponentGoal) * 20;

            // 2. Proximity to Ball (offering support/being a pass option) - General proximity if no pressure
            int distanceToBallHops = GetZoneDistance(targetZone, ballZone, isHomeTeamAttacking);
            if (CurrentBallHolder != null && CurrentBallHolder.Team == attackingTeam && !IsBallHolderUnderPressure(CurrentBallHolder))
            {
                if (distanceToBallHops <= 1) score += 10; // Very close, good general pass option
                else if (distanceToBallHops <= 2) score += 5; // Close enough for general pass option
            }

            // 3. Open Space (avoiding direct marking)
            int defendersNearby = CountDefendersInZone(targetZone, defendingTeam);
            if (defendersNearby == 0) score += 15; // Unmarked space is excellent
            else if (defendersNearby == 1) score += 5; // Less ideal but manageable
            else score -= 10; // Avoid crowded areas where we're outnumbered or equal

            // 4. Player's natural position preference (stay somewhat close to role's ideal zone)
            Enums.PitchZone playerIdealZone = DetermineOffensiveZone(player, ballZone, attackingTeam);
            int distanceToIdealZone = GetZoneDistance(targetZone, playerIdealZone, isHomeTeamAttacking);
            score += (double)(5 - distanceToIdealZone) * 2;

            // 5. Player's Off-the-ball rating (skill in finding space)
            score += player.trueRating.PositioningForGameCalculations * 0.1;

            // --- Support Movement Scoring ---
            if (CurrentBallHolder != null && CurrentBallHolder.Team == attackingTeam && IsBallHolderUnderPressure(CurrentBallHolder))
            {
                if (distanceToBallHops <= MAX_SUPPORT_DIST_HOPS)
                {
                    score += (MAX_SUPPORT_DIST_HOPS - distanceToBallHops) * 25.0; // Strong bonus for close support
                    int ballCarrierForwardValue = GetZoneForwardValue(CurrentBallHolder.CurrentZone, isHomeTeamAttacking);
                    int targetZoneForwardValue = GetZoneForwardValue(targetZone, isHomeTeamAttacking);

                    // Prefer support options that are behind or level with the ball carrier
                    if (targetZoneForwardValue <= ballCarrierForwardValue)
                    {
                        score += 35.0;
                    }
                    else
                    {
                        score -= 15.0; // Penalty for running too far ahead when ball carrier needs support
                    }

                    // Incentivize support on the flanks but not too far from the ball
                    int targetZoneLateralAbs = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                    score -= (targetZoneLateralAbs * 7.0); // General penalty for being too wide for central support

                    // Specific bonus for wide players/fullbacks supporting on their flank
                    if ((player.Position == Enums.Positions.LeftWingForward && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) < 0) ||
                        (player.Position == Enums.Positions.RightWingForward && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) > 0) ||
                        (player.Position == Enums.Positions.LeftMidfielder && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) < 0) ||
                        (player.Position == Enums.Positions.RightMidfielder && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) > 0) ||
                        (player.Position == Enums.Positions.LeftBack && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) < 0) ||
                        (player.Position == Enums.Positions.RightBack && targetZoneLateralAbs > 0 && GetZoneLateralValue(targetZone, isHomeTeamAttacking) > 0))
                    {
                        score += 8.0;
                    }
                }
                // If moving backward, but not too far from ball, can be good for receiving
                if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking))
                {
                    if (distanceToBallHops <= MAX_SUPPORT_DIST_HOPS)
                    {
                        score += 10;
                    }
                    else
                    {
                        score -= 20; // Penalize dropping too deep away from the ball
                    }
                }
            }
            else // Not under pressure, or not attacking team with ball
            {
                // Discourage dropping back aimlessly if not needed for support
                if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking) && distanceToBallHops > 1)
                {
                    score -= 20;
                }
            }

            // --- Runs "In Behind" and Anticipating Through Balls (Penetration) Scoring ---
            int targetForwardValueForRun = GetZoneForwardValue(targetZone, isHomeTeamAttacking);
            // CORRECTED LINE HERE:
            int defensiveLineForwardValue = GetZoneForwardValue(GetOpponentDefensiveLineZone(defendingTeam, isHomeTeamAttacking, currentMinute, currentSecond), isHomeTeamAttacking);

            if (targetForwardValueForRun > defensiveLineForwardValue) // Running past the defensive line
            {
                double inBehindBonus = 70.0;

                inBehindBonus += (player.trueRating.PaceForGameCalculations * 0.2);
                inBehindBonus += (player.trueRating.AccelerationForGameCalculations * 0.15);
                inBehindBonus += (player.trueRating.FinishingForGameCalculations * 0.1);

                if (CurrentBallHolder != null && CurrentBallHolder.Team == attackingTeam)
                {
                    inBehindBonus += (CurrentBallHolder.trueRating.VisionForGameCalculations * 0.1);
                    inBehindBonus += (CurrentBallHolder.trueRating.PassingForGameCalculations * 0.15);

                    if (IsZonePathBlocked(CurrentBallHolder.CurrentZone, targetZone, defendingTeam))
                    {
                        inBehindBonus -= 100.0; // Significant penalty if the path is clearly blocked
                    }
                }
                else
                {
                    inBehindBonus = 0; // No ball holder, no effective in-behind run
                }

                if (CountDefendersInZone(targetZone, defendingTeam) > 0)
                {
                    inBehindBonus -= 80.0; // Don't run into directly defended space
                }

                // Less likely to make a deep run if ball is too deep
                if (GetZoneForwardValue(CurrentBallZone, isHomeTeamAttacking) < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking))
                {
                    inBehindBonus -= 40.0;
                }

                score += inBehindBonus;
            }

            // --- Creating Space (Decoy Runs & Drags) Scoring ---
            double decoyScore = 0;

            // Consider decoy runs when the ball is in midfield or attacking third
            if (GetZoneForwardValue(ballZone, isHomeTeamAttacking) >= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) - 1)
            {
                Enums.PitchZone congestedZone = Enums.PitchZone.None;
                int maxDefendersInZone = 0;

                // Identify potential congested zones in the opponent's dangerous areas
                List<Enums.PitchZone> criticalAttackingZones = new List<Enums.PitchZone>
            {
                isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center, // Center of opponent's attacking third from attacking team's perspective
                isHomeTeamAttacking ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home
            };

                foreach (Enums.PitchZone zoneToCheck in criticalAttackingZones)
                {
                    int currentDefenders = CountDefendersInZone(zoneToCheck, defendingTeam);
                    if (currentDefenders > 1 && currentDefenders > maxDefendersInZone) // Look for zones with at least 2 defenders
                    {
                        maxDefendersInZone = currentDefenders;
                        congestedZone = zoneToCheck;
                    }
                }

                if (congestedZone != Enums.PitchZone.None)
                {
                    int distanceToCongestedZoneHops = GetZoneDistance(targetZone, congestedZone, isHomeTeamAttacking);
                    int currentPlayerDistanceToCongestedZoneHops = GetZoneDistance(player.CurrentZone, congestedZone, isHomeTeamAttacking);

                    // A decoy run should move *away* from the congested zone to draw defenders
                    if (distanceToCongestedZoneHops > currentPlayerDistanceToCongestedZoneHops)
                    {
                        decoyScore += 30.0; // Base bonus for a decoy run

                        int targetZoneLateralAbs = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                        int congestedZoneLateralAbs = Math.Abs(GetZoneLateralValue(congestedZone, isHomeTeamAttacking));

                        // Prioritize moving wider or deeper (slightly) to drag defenders out of central areas
                        if (targetZoneLateralAbs > congestedZoneLateralAbs) // Moving wider
                        {
                            decoyScore += 10.0;
                        }
                        else if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(congestedZone, isHomeTeamAttacking)) // Moving deeper to receive short or drag CBs
                        {
                            decoyScore += 5.0;
                        }

                        decoyScore += (player.trueRating.PositioningForGameCalculations * 0.1);
                        score += decoyScore;
                    }
                }
            }

            // --- Overload Bonus Scoring ---
            if (CurrentOverloadTargetZone.HasValue) // Check if an overload target zone has been identified
            {
                Enums.PitchZone overloadTarget = CurrentOverloadTargetZone.Value;
                int distanceToOverloadTarget = GetZoneDistance(targetZone, overloadTarget, isHomeTeamAttacking);

                // Only give bonus if moving into or adjacent to the overload target
                if (distanceToOverloadTarget <= 1)
                {
                    double overloadBonus = 0;

                    // Base bonus for moving towards the overload target
                    overloadBonus += 30.0 - (distanceToOverloadTarget * 10.0); // Higher bonus for being exact, slight reduction for adjacent

                    // Adjust bonus based on player role - some roles are more likely to participate in overloads
                    switch (player.Role)
                    {
                        case Enums.PlayerRole.Poacher:
                        case Enums.PlayerRole.TargetMan:
                        case Enums.PlayerRole.DeepLyingForward:
                        case Enums.PlayerRole.AttackingMidfielder:
                        case Enums.PlayerRole.InsideForward:
                        case Enums.PlayerRole.AdvancedPlaymaker:
                            overloadBonus += 20;
                            break;
                        case Enums.PlayerRole.Winger:
                        case Enums.PlayerRole.WidePlaymaker:
                        case Enums.PlayerRole.BoxToBoxMidfielder:
                            overloadBonus += 10;
                            break;
                        case Enums.PlayerRole.CentralMidfielder:
                            overloadBonus += 5;
                            break;
                        case Enums.PlayerRole.FullBack:
                            overloadBonus += 15;
                            break;
                        case Enums.PlayerRole.FalseNine:
                            overloadBonus += 5;
                            break;
                        case Enums.PlayerRole.DefensiveMidfielder:
                        case Enums.PlayerRole.CenterBack:
                        case Enums.PlayerRole.Goalkeeper:
                            overloadBonus -= 50; // Significant penalty for defensive players to join attacking overloads
                            break;
                    }

                    // Prevent over-congestion: Reduce bonus if the target zone is already too crowded
                    int currentAttackersInTarget = attackingTeam.AvailableOnFieldOutfielders.Count(p => p.CurrentZone == targetZone);
                    int defendersInTarget = defendingTeam.AvailableOnFieldPlayers.Count(p => p.CurrentZone == targetZone);

                    if (currentAttackersInTarget >= (defendersInTarget + 2)) // If we already have 2 more attackers than defenders
                    {
                        overloadBonus -= 25; // Reduce the urge for more players to pile in
                    }
                    else if (currentAttackersInTarget >= 3 && targetZone != overloadTarget) // If 3+ attackers, and it's not the *primary* target, reduce
                    {
                        overloadBonus -= 15;
                    }
                    if (CountDefendersInZone(targetZone, defendingTeam) == 0 && currentAttackersInTarget >= 2)
                    {
                        overloadBonus -= 10; // If zone is already completely open and has 2 attackers, maybe others don't need to pile in.
                    }
                    // Manual Clamp for overloadBonus
                    if (overloadBonus < -20) overloadBonus = -20;
                    if (overloadBonus > 70) overloadBonus = 70;

                    score += overloadBonus;
                }
            }

            // --- Dynamic Diagonal Runs Scoring ---
            double diagonalRunBonus = 0;

            Enums.PitchZone currentPlayerZone = player.CurrentZone;
            int currentForwardValue = GetZoneForwardValue(currentPlayerZone, isHomeTeamAttacking);
            int targetForwardValue = GetZoneForwardValue(targetZone, isHomeTeamAttacking);
            int currentLateralValue = GetZoneLateralValue(currentPlayerZone, isHomeTeamAttacking);
            int targetLateralValue = GetZoneLateralValue(targetZone, isHomeTeamAttacking);

            bool movedForward = targetForwardValue > currentForwardValue;
            bool changedLateralPosition = targetLateralValue != currentLateralValue;

            int forwardMovementMagnitude = Math.Abs(targetForwardValue - currentForwardValue);
            int lateralMovementMagnitude = Math.Abs(targetLateralValue - currentLateralValue);

            // Consider it a diagonal run if it moves forward and changes lateral position significantly
            if (movedForward && changedLateralPosition && forwardMovementMagnitude >= 1 && lateralMovementMagnitude >= 1)
            {
                diagonalRunBonus += 25.0; // Base bonus for a diagonal run

                // 1. Exploit Space: Prioritize runs into less defended zones
                int defendersInTargetZone = CountDefendersInZone(targetZone, defendingTeam);
                if (defendersInTargetZone == 0)
                {
                    diagonalRunBonus += 20.0; // Large bonus for running into empty space
                }
                else if (defendersInTargetZone == 1)
                {
                    diagonalRunBonus += 10.0; // Still good if only one defender
                }
                else
                {
                    diagonalRunBonus -= 30.0; // Penalize running into crowded diagonal paths
                }

                // 2. Proximity to Opponent's Goal/Penalty Area
                int distanceToOpponentGoalForDiagonal = GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking);
                if (distanceToOpponentGoalForDiagonal <= 1) // Target is Penalty Area or adjacent
                {
                    diagonalRunBonus += 15.0;
                }
                else if (distanceToOpponentGoalForDiagonal <= 2)
                {
                    diagonalRunBonus += 5.0;
                }

                // 3. Ball Holder's Vision/Passing Ability
                if (CurrentBallHolder != null && CurrentBallHolder.Team == attackingTeam)
                {
                    double visionInfluence = CurrentBallHolder.trueRating.VisionForGameCalculations * 0.1;
                    double passingInfluence = CurrentBallHolder.trueRating.PassingForGameCalculations * 0.1;
                    diagonalRunBonus += (visionInfluence + passingInfluence) * 0.5;

                    // Check if the path is too obstructed from the ball holder's perspective
                    if (IsZonePathBlocked(CurrentBallHolder.CurrentZone, targetZone, defendingTeam))
                    {
                        diagonalRunBonus -= 50.0; // Significant penalty if the path is clearly blocked
                    }
                }
                else
                {
                    diagonalRunBonus -= 20.0; // Less valuable if no clear ball holder or not in possession
                }

                // 4. Player Role Preference for Diagonal Runs
                switch (player.Role)
                {
                    case Enums.PlayerRole.InsideForward:
                    case Enums.PlayerRole.AttackingMidfielder:
                    case Enums.PlayerRole.AdvancedPlaymaker:
                    case Enums.PlayerRole.Poacher:
                    case Enums.PlayerRole.BoxToBoxMidfielder:
                        diagonalRunBonus += 20.0;
                        break;
                    case Enums.PlayerRole.DeepLyingForward:
                    case Enums.PlayerRole.Winger:
                    case Enums.PlayerRole.CentralMidfielder:
                        diagonalRunBonus += 10.0;
                        break;
                    case Enums.PlayerRole.FalseNine:
                        diagonalRunBonus -= 5.0;
                        break;
                    case Enums.PlayerRole.TargetMan:
                    case Enums.PlayerRole.FullBack:
                    case Enums.PlayerRole.DefensiveMidfielder:
                    case Enums.PlayerRole.CenterBack:
                    case Enums.PlayerRole.Goalkeeper:
                        diagonalRunBonus -= 30.0;
                        break;
                }
            }
            else // Not a significant diagonal forward movement
            {
                // If a player moves laterally without forward progress, and it's not a decoy run
                if (changedLateralPosition && !movedForward && decoyScore <= 0)
                {
                    diagonalRunBonus -= 5.0;
                }
                else
                {
                    diagonalRunBonus = 0; // No bonus if not a relevant diagonal run
                }
            }

            // Manual Clamp for diagonalRunBonus
            if (diagonalRunBonus < -50) diagonalRunBonus = -50;
            if (diagonalRunBonus > 70) diagonalRunBonus = 70;
            score += diagonalRunBonus;

            // --- NEW: Team Tactic Adjustments ---
            double tacticAdjustment = 0; // Changed from strategyAdjustment to tacticAdjustment

            switch (currentTeamTactic)
            {
                case Enums.TeamTactic.DirectPlay:
                case Enums.TeamTactic.Attacking: // 'Attacking' can imply directness if no other specific attacking tactic is chosen
                case Enums.TeamTactic.AllOutAttack: // Even more extreme directness
                    // Strongly favor runs in behind and direct forward movement
                    if (targetForwardValueForRun > GetZoneForwardValue(opponentDefensiveLineZone, isHomeTeamAttacking))
                    {
                        tacticAdjustment += 30; // Stronger emphasis on direct runs
                    }
                    // Slightly penalize deep lateral or backward movement
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking))
                    {
                        tacticAdjustment -= 10;
                    }
                    // Less emphasis on decoy runs if it means dropping too deep
                    if (decoyScore > 0 && GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking) - 1)
                    {
                        tacticAdjustment -= 5;
                    }
                    break;

                case Enums.TeamTactic.Possession:
                    // Favor short, safe passes and keeping possession
                    // Increase bonus for proximity to ball (support options)
                    if (distanceToBallHops <= 1) tacticAdjustment += 15;
                    else if (distanceToBallHops <= 2) tacticAdjustment += 10;

                    // Penalize risky runs too far ahead or into crowded areas
                    if (targetForwardValueForRun > GetZoneForwardValue(opponentDefensiveLineZone, isHomeTeamAttacking) && CountDefendersInZone(targetZone, defendingTeam) > 0)
                    {
                        tacticAdjustment -= 20; // Discourage running into crowded areas beyond defense
                    }
                    // Players should maintain good passing triangles, so moderate lateral movement is fine
                    break;

                case Enums.TeamTactic.CounterAttack:
                    // High emphasis on speed and directness after winning ball
                    // This requires a flag indicating recent possession win.
                    // Assuming `attackingTeam.justWonPossessionFlag` exists and is managed in your MatchEngine.
                    bool justWonPossession = attackingTeam.justWonPossessionFlag; // Placeholder: You'll need to implement this
                    if (justWonPossession)
                    {
                        // Strong bonus for runs in behind
                        if (targetForwardValueForRun > GetZoneForwardValue(opponentDefensiveLineZone, isHomeTeamAttacking))
                        {
                            tacticAdjustment += 40;
                        }
                        // Strong bonus for diagonal runs that break lines
                        if (movedForward && changedLateralPosition && forwardMovementMagnitude >= 1 && lateralMovementMagnitude >= 1)
                        {
                            tacticAdjustment += 25;
                        }
                        // Penalize holding ball too long or passing sideways/backwards
                        if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) <= GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking) && distanceToBallHops > 0)
                        {
                            tacticAdjustment -= 15;
                        }
                    }
                    break;

                case Enums.TeamTactic.WidePlay:
                    // Strongly encourage movement into wide attacking zones
                    int targetZoneLateralValue = GetZoneLateralValue(targetZone, isHomeTeamAttacking);
                    if (Math.Abs(targetZoneLateralValue) >= 2) // Far flanks
                    {
                        tacticAdjustment += 20;
                    }
                    else if (Math.Abs(targetZoneLateralValue) == 1) // Inner wide zones
                    {
                        tacticAdjustment += 10;
                    }
                    // Penalize central movement for wide players unless it's a specific role (e.g., IF)
                    if (Math.Abs(targetZoneLateralValue) == 0 && (player.Position == Enums.Positions.LeftWingForward || player.Position == Enums.Positions.RightWingForward ||
                                                               player.Position == Enums.Positions.LeftMidfielder || player.Position == Enums.Positions.RightMidfielder))
                    {
                        tacticAdjustment -= 10;
                    }
                    break;

                case Enums.TeamTactic.CentralFocus:
                    // Strongly encourage movement into central attacking zones
                    if (Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking)) == 0) // Central zones
                    {
                        tacticAdjustment += 25;
                    }
                    else if (Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking)) == 1) // Slightly off-center
                    {
                        tacticAdjustment += 10;
                    }
                    // Penalize movement into far wide areas for central players
                    if (Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking)) >= 2 && (player.Position == Enums.Positions.Striker || player.Position == Enums.Positions.CentralAttackingMidfielder ||
                                                                                              player.Position == Enums.Positions.CentralMidfielder))
                    {
                        tacticAdjustment -= 15;
                    }
                    break;

                case Enums.TeamTactic.Defensive:
                case Enums.TeamTactic.ParkTheBus:
                    // Heavily penalize players pushing too far forward.
                    // Encourage staying in defensive shape.
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking))
                    {
                        tacticAdjustment -= 30; // Strong penalty for going too far forward
                    }
                    // Encourage defending players to stay deeper
                    if (player.Position == Enums.Positions.CenterBack || player.Position == Enums.Positions.CentralDefendingMidfielder || player.Position == Enums.Positions.LeftBack || player.Position == Enums.Positions.RightBack)
                    {
                        if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking) + 1)
                        {
                            tacticAdjustment -= 20;
                        }
                    }
                    // For 'ParkTheBus', even more extreme defensiveness
                    if (currentTeamTactic == Enums.TeamTactic.ParkTheBus)
                    {
                        if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking)) // Beyond own half
                        {
                            tacticAdjustment -= 40;
                        }
                    }
                    break;

                case Enums.TeamTactic.PressHigh:
                    // Encourage players to move closer to opponents/ball zone in opponent's half
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) >= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) &&
                        GetZoneDistance(targetZone, ballZone, isHomeTeamAttacking) <= 2)
                    {
                        tacticAdjustment += 20;
                    }
                    // Specifically for players in midfield/attack, encourage moving up
                    if (player.Position == Enums.Positions.Striker || player.Position == Enums.Positions.CentralAttackingMidfielder ||
                        player.Position == Enums.Positions.CentralMidfielder || player.Position == Enums.Positions.LeftWingForward ||
                        player.Position == Enums.Positions.RightWingForward)
                    {
                        if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking))
                        {
                            tacticAdjustment += 15;
                        }
                    }
                    // Penalize dropping deep too much
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(player.CurrentZone, isHomeTeamAttacking) - 1)
                    {
                        tacticAdjustment -= 10;
                    }
                    break;

                case Enums.TeamTactic.Balanced:
                default:
                    // No specific tactic adjustment beyond the base scoring for balanced
                    break;
            }

            // Manual Clamp for tacticAdjustment
            if (tacticAdjustment < -50) tacticAdjustment = -50;
            if (tacticAdjustment > 50) tacticAdjustment = 50;
            score += tacticAdjustment;


            // --- Player Roles and Tendencies Scoring Adjustments (Existing section, kept for completeness) ---
            double roleAdjustment = 0;
            // currentForwardValue is already defined above

            switch (player.Role)
            {
                case Enums.PlayerRole.Poacher:
                    if (GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking) <= 1) roleAdjustment += 40;
                    if (targetForwardValueForRun > defensiveLineForwardValue) roleAdjustment += 25;
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking)) roleAdjustment -= 20;
                    break;

                case Enums.PlayerRole.TargetMan:
                    if (targetZone == (isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center) ||
                        targetZone == Enums.PitchZone.Midfield_Center)
                    {
                        roleAdjustment += 30;
                        if (CurrentBallHolder != null && IsBallHolderUnderPressure(CurrentBallHolder)) roleAdjustment += 15;
                    }
                    if (targetForwardValueForRun > defensiveLineForwardValue) roleAdjustment -= 10;
                    if (CountDefendersInZone(targetZone, defendingTeam) >= 1) roleAdjustment += 5;
                    break;

                case Enums.PlayerRole.DeepLyingForward:
                    if (targetZone == Enums.PitchZone.Midfield_Center ||
                        targetZone == (isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center)) roleAdjustment += 15;
                    if (targetForwardValueForRun > defensiveLineForwardValue) roleAdjustment += 15;
                    break;

                case Enums.PlayerRole.FalseNine:
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) <= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) + 1 &&
                        GetZoneDistance(targetZone, Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) <= 1) roleAdjustment += 35;
                    if (GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking) <= 1 && CountDefendersInZone(targetZone, defendingTeam) > 0) roleAdjustment -= 50;
                    roleAdjustment += (decoyScore / 1.5);
                    break;

                case Enums.PlayerRole.Winger:
                    int targetZoneLateralAbsW = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                    if (targetZoneLateralAbsW >= 2 && // Wide zones
                        ((isHomeTeamAttacking && (targetZone == Enums.PitchZone.AwayAttack_LeftFlank || targetZone == Enums.PitchZone.AwayAttack_RightFlank)) ||
                         (!isHomeTeamAttacking && (targetZone == Enums.PitchZone.HomeDefense_LeftFlank || targetZone == Enums.PitchZone.HomeDefense_RightFlank)) ||
                         targetZone == Enums.PitchZone.Midfield_LeftFlank || targetZone == Enums.PitchZone.Midfield_RightFlank))
                    {
                        roleAdjustment += 30;
                    }
                    else if (targetZoneLateralAbsW == 1) roleAdjustment += 15;
                    if (targetZoneLateralAbsW < Math.Abs(GetZoneLateralValue(player.CurrentZone, isHomeTeamAttacking)) &&
                        GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking))
                    {
                        roleAdjustment -= 10;
                    }
                    break;

                case Enums.PlayerRole.InsideForward:
                    int targetZoneLateralAbsIF = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                    if (targetZoneLateralAbsIF >= 1) roleAdjustment += 15;
                    if (targetZoneLateralAbsIF < Math.Abs(GetZoneLateralValue(player.CurrentZone, isHomeTeamAttacking)) &&
                        GetZoneForwardValue(targetZone, isHomeTeamAttacking) >= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) + 1) roleAdjustment += 25;
                    if (targetForwardValueForRun > defensiveLineForwardValue) roleAdjustment += 10;
                    break;

                case Enums.PlayerRole.WidePlaymaker:
                    int targetZoneLateralAbsWP = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                    if (targetZoneLateralAbsWP >= 1) roleAdjustment += 20;
                    if (CountDefendersInZone(targetZone, defendingTeam) < 2) roleAdjustment += 10;
                    roleAdjustment += (decoyScore / 3.0);
                    break;

                case Enums.PlayerRole.AdvancedPlaymaker:
                    if (targetZone == (isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center) ||
                        (GetZoneForwardValue(targetZone, isHomeTeamAttacking) == GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) + 1 && Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking)) <= 1))
                    {
                        roleAdjustment += 35;
                    }
                    if (CountDefendersInZone(targetZone, defendingTeam) < 2) roleAdjustment += 20;
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) - 1) roleAdjustment -= 25;
                    break;

                case Enums.PlayerRole.AttackingMidfielder:
                    if (targetZone == (isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center) ||
                        GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking) <= 2) roleAdjustment += 25;
                    if (GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking) <= 0) roleAdjustment += 15;
                    break;

                case Enums.PlayerRole.DefensiveMidfielder:
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) <= GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) &&
                        GetZoneDistance(targetZone, playerHomeGoalArea, isHomeTeamAttacking) <= 3) roleAdjustment += 30;
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) + 1) roleAdjustment -= 30;
                    if (GetZoneForwardValue(ballZone, isHomeTeamAttacking) < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking)) roleAdjustment += (MAX_SUPPORT_DIST_HOPS - distanceToBallHops) * 10.0;
                    break;

                case Enums.PlayerRole.BoxToBoxMidfielder:
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) >= GetZoneForwardValue(Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking) &&
                        GetZoneForwardValue(targetZone, isHomeTeamAttacking) <= GetZoneForwardValue((isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center), isHomeTeamAttacking) + 1) roleAdjustment += 10;
                    roleAdjustment += (MAX_SUPPORT_DIST_HOPS - distanceToBallHops) * 5.0;
                    break;

                case Enums.PlayerRole.CentralMidfielder:
                    if (targetZone == Enums.PitchZone.Midfield_Center ||
                        (GetZoneForwardValue(targetZone, isHomeTeamAttacking) >= GetZoneForwardValue(Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking) &&
                         GetZoneForwardValue(targetZone, isHomeTeamAttacking) <= GetZoneForwardValue((isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center), isHomeTeamAttacking))) roleAdjustment += 15;
                    break;

                case Enums.PlayerRole.FullBack:
                    int targetZoneLateralAbsFB = Math.Abs(GetZoneLateralValue(targetZone, isHomeTeamAttacking));
                    if (isHomeTeamAttacking)
                    {
                        if (targetZoneLateralAbsFB >= 2 &&
                            (targetZone == Enums.PitchZone.AwayAttack_LeftFlank || targetZone == Enums.PitchZone.AwayAttack_RightFlank) &&
                            GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking))
                        {
                            roleAdjustment += 30;
                        }
                    }
                    else // Away team Fullback
                    {
                        if (targetZoneLateralAbsFB >= 1 &&
                            (targetZone == Enums.PitchZone.HomeDefense_LeftFlank || targetZone == Enums.PitchZone.HomeDefense_RightFlank ||
                             targetZone == Enums.PitchZone.Midfield_LeftFlank || targetZone == Enums.PitchZone.Midfield_RightFlank) &&
                            GetZoneForwardValue(targetZone, isHomeTeamAttacking) < GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking) + 1)
                        {
                            roleAdjustment += 15;
                        }
                    }
                    if (targetZoneLateralAbsFB == 0) roleAdjustment -= 10;
                    break;

                case Enums.PlayerRole.CenterBack:
                    int distanceToOwnGoalForCB = GetZoneDistance(targetZone, playerHomeGoalArea, isHomeTeamAttacking);
                    if (distanceToOwnGoalForCB <= 2) roleAdjustment += 40;
                    if (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking)) roleAdjustment -= 50;
                    break;

                case Enums.PlayerRole.Goalkeeper:
                    if (targetZone != playerHomeGoalArea) roleAdjustment -= 1000;
                    break;

                case Enums.PlayerRole.None:
                    break;
            }
            score += roleAdjustment;

            // 8. Add some small randomness to vary decisions and prevent perfect predictability
            score += Dice.d50() * 0.1; // Using d50 for a wider range of randomness

            return score;
        }

        /// <summary>
        /// Calculates the probability that 'interceptor' can intercept a pass from 'passer' to 'receiver'
        /// if positioned in 'interceptionZone'.
        /// </summary>
        /// <param name="interceptor">The defending player attempting the interception.</param>
        /// <param name="passer">The opponent player making the pass.</param>
        /// <param name="receiver">The opponent player intended to receive the pass.</param>
        /// <param name="interceptionZone">The zone the interceptor would move to.</param>
        /// <returns>A probability (0.0 to 1.0) of successful interception.</returns>
        private double CalculateInterceptionProbability(Player interceptor, Player passer, Player receiver, Enums.PitchZone interceptionZone)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateInterceptionProbability: interceptor:{0},passer:{1},receiver:{2},interceptionZone:{3}",
            //    interceptor.position, passer.position, receiver.position, interceptionZone));


            double prob = 0.5; // Base probability (e.g., 50/50 starting point)

            // --- 1. Interceptor's Attributes ---
            // Higher anticipation and positioning make the interceptor better at reading the pass.
            prob += (interceptor.trueRating.ComposureForGameCalculations / 100.0) * 0.2; // 0-20% bonus based on 0-100 rating
            prob += (interceptor.trueRating.PositioningForGameCalculations / 100.0) * 0.1; // 0-10% bonus

            // --- 2. Passer's Attributes ---
            // Higher passing and vision make the pass harder to intercept.
            prob -= (passer.trueRating.PassingForGameCalculations / 100.0) * 0.1; // 0-10% penalty
            prob -= (passer.trueRating.VisionForGameCalculations / 100.0) * 0.05; // 0-5% penalty

            // --- 3. Positional Factors ---
            double distancePasserToReceiver = CalculateDistance(passer.CurrentZone, receiver.CurrentZone);
            if (distancePasserToReceiver <= 0.01) distancePasserToReceiver = 0.01; // Avoid division by zero

            double distToPasser = CalculateDistance(interceptionZone, passer.CurrentZone);
            double distToReceiver = CalculateDistance(interceptionZone, receiver.CurrentZone);

            // Bonus if interceptor is near the midpoint of the pass (good intercepting position)
            // If interceptor is perfectly on the line, and equidistant, this would be 1.0, giving a 20% bonus.
            double positionalAdvantage = 1.0 - ((distToPasser + distToReceiver) / (distancePasserToReceiver + 0.01));
            prob += positionalAdvantage * 0.2; // Max 20% bonus

            // Penalty if the pass is very short (harder to react) or very long (more time to close, but also more chance for error)
            // Tune these thresholds
            if (distancePasserToReceiver < 2) prob -= 0.05; // Short pass penalty
            if (distancePasserToReceiver > MaxPassDistance - 1) prob += 0.05; // Longer pass slight bonus (more air time)

            // --- 4. Ball Carrier Pressure ---
            // If the passer is under pressure, their pass accuracy might be lower, increasing interception chance.
            if (IsBallHolderUnderPressure(passer))
            {
                prob += 0.1; // 10% bonus for interception
            }

            // --- 5. Opponent Coverage on Receiver (Implicit) ---
            if (CountDefendersInZone(receiver.CurrentZone, interceptor.Team) > 1) prob += 0.05;

            // Clamp the final probability between 0 and 1
            return Math.Max(0.0, Math.Min(1.0, prob));
        }

        /// <summary>
        /// Calculates a defender's desire or chance to attempt a tackle.
        /// </summary>
        /// <param name="defender">The player considering the tackle.</param>
        /// <param name="ballCarrier">The opponent in possession.</param>
        /// <param name="defendingTeam">The defender's team (to consider tactics).</param>
        /// <returns>A score (0-100) indicating the likelihood of attempting a tackle.</returns>
        private double CalculateTackleDesire(Player defender, Player ballCarrier, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateTackleDesire: defender:{0},ballCarrier:{1},defendingTeam:{2}",
            //    defender.position, ballCarrier.position, defendingTeam.Name));


            double desire = 0;

            // --- 1. Base on Defender Attributes ---
            desire += defender.trueRating.AggressionForGameCalculations * 0.4; // Aggression directly impacts tackle desire
            desire += defender.trueRating.StandTackleForGameCalculations * 0.3; // Tackling skill
            desire += defender.trueRating.DefenseAwarenessForGameCalculations * 0.2; // Knowing when to tackle

            // Composure can make them less rash, so it might slightly *reduce* excessive desire for unnecessary tackles
            desire -= defender.trueRating.ComposureForGameCalculations * 0.1;

            // --- 2. Opponent's Vulnerability ---
            desire -= ballCarrier.trueRating.DribblingForGameCalculations * 0.2; // Less desire to tackle a great dribbler
            desire -= ballCarrier.trueRating.BallControlForGameCalculations * 0.1; // Less desire if opponent has tight control

            // More desire if opponent is vulnerable (e.g., low balance, just received a difficult pass)
            // You'll need to add game state checks for this, e.g.:
            // if (ballCarrier.isOffBalance) desire += 15;

            // --- 3. Contextual Factors ---
            bool isHomeTeamDefending = (defendingTeam == HomeTeam); // Assuming 'homeTeam' is accessible
            bool inDangerousArea = IsZoneDangerous(defender.CurrentZone, !isHomeTeamDefending); // Dangerous for the defending team
            if (inDangerousArea)
            {
                // More cautious tackling in dangerous areas unless very high aggression/skill
                desire -= 20; // Default: reduce desire in dangerous areas
                if (defender.trueRating.AggressionForGameCalculations > 70 || defender.trueRating.StandTackleForGameCalculations > 75)
                {
                    desire += 10; // Aggressive/skilled defenders might still go for it
                }
            }

            // --- 4. Player Card Status ---
            if (defender.yellowCards >= 1 && defendingTeam.CurrentTactic != Enums.TeamTactic.AllOutAttack) // If player has a yellow, reduce desire unless team is desperate
            {
                desire -= 25;
            }

            // --- 5. Team Tactic Influence (General Team Tactic, not just aggression) ---
            // Example:
            // if (defendingTeam.CurrentTactic == Enums.TeamTactic.HighPress) desire += 15;
            // if (defendingTeam.CurrentTactic == Enums.TeamTactic.ParkTheBus) desire -= 10;

            // --- NEW: Apply Team Tackling Aggression Modifier ---
            switch (defendingTeam.CurrentTacklingAggression) // Using the team's specific tackling aggression setting
            {
                case Enums.TacklingAggression.Cautious:
                    desire -= 15; // Less likely to attempt tackles
                    break;
                case Enums.TacklingAggression.Standard:
                    // No change
                    break;
                case Enums.TacklingAggression.Aggressive:
                    desire += 15; // More likely to attempt tackles
                    break;
                case Enums.TacklingAggression.VeryAggressive:
                    desire += 30; // Much more likely to attempt tackles
                    break;
            }

            // Ensure desire stays within reasonable bounds (e.g., 0-100)
            desire = Math.Max(0, Math.Min(100, desire));

            return desire * 0.7;
        }

        /// <summary>
        /// Calculates a score for a player's opportunity to cross the ball.
        /// Higher score means a more desirable cross.
        /// </summary>
        /// <param name="crossingPlayer">The player attempting the cross.</param>
        /// <param name="targetPlayer">The potential recipient of the cross (e.g., a striker in the box).</param>
        /// <param name="ballZone">The current zone of the ball (where the cross originates).</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <returns>A double representing the cross opportunity score.</returns>
        private double CalculateCrossOpportunity(Player crossingPlayer, Player targetPlayer, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateCrossOpportunity: crossingPlayer:{0},targetPlayer:{1},ballZone:{2}," +
            //    "attackingTeam:{3},defendingTeam:{4}", crossingPlayer.position, targetPlayer.position, ballZone, attackingTeam.Name, defendingTeam.Name));
            //
            double score = 0;
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);

            // --- Initial Validity Checks ---
            // Ensure the crossing player is in a wide zone suitable for crossing
            Enums.Flank crosserFlank = GetFlankOfZone(ballZone);
            if (crosserFlank == Enums.Flank.Center) // Must be in a flank zone (or wider, if you have those)
            {
                return -9999; // Very low score if not in a wide area for crossing
            }

            // Ensure there's a valid target player
            if (targetPlayer == null || !targetPlayer.IsAvailable)
            {
                return -9999;
            }

            // Use the correct enum names: PenaltyArea_Away/Home
            Enums.PitchZone opponentPenaltyArea = isHomeTeamAttacking ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            Enums.PitchZone opponentGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

            // Determine the ideal target zone for the cross, slightly ahead of the target player's current position,
            // and within or very near the opponent's penalty area.
            Enums.PitchZone idealCrossReceivingZone = GetIdealCrossReceivingZone(targetPlayer, attackingTeam, isHomeTeamAttacking);

            // If no ideal zone is found or it's completely unviable, return low score.
            if (idealCrossReceivingZone == Enums.PitchZone.None ||
                GetZoneDistance(idealCrossReceivingZone, opponentGoalArea, isHomeTeamAttacking) > 2) // Must be close to goal
            {
                return -9999;
            }

            // Use the ideal receiving zone for subsequent calculations
            Enums.PitchZone targetZoneForCross = idealCrossReceivingZone;


            // --- Core Scoring Logic ---

            // 1. Player Attributes (Crossing, Vision, Passing, Composure)
            score += crossingPlayer.trueRating.CrossingForGameCalculations * 0.7; // Crossing is paramount
            score += crossingPlayer.trueRating.VisionForGameCalculations * 0.1; // Vision to pick out target and space
            score += crossingPlayer.trueRating.PassingForGameCalculations * 0.1; // General passing ability
            score += crossingPlayer.trueRating.ComposureForGameCalculations * 0.05; // Helps under pressure

            // 2. Distance and Angle of Cross
            double crossDistance = GetZoneDistance(ballZone, targetZoneForCross, isHomeTeamAttacking);
            score -= crossDistance * 5; // Penalize longer crosses (harder to execute)

            // Bonus for crossing from deeper wide positions if a deep cross is preferred by tactic/player
            // (e.g., often fullbacks deliver from deeper areas)
            // This could be influenced by tactical settings later.
            int currentForwardValue = GetZoneForwardValue(ballZone, isHomeTeamAttacking);
            int attackingThirdForwardValue = GetZoneForwardValue(isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking);
            int midfieldForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking);

            if (currentForwardValue >= attackingThirdForwardValue)
            {
                score += 20; // Bonus for crossing from advanced positions
            }
            else if (currentForwardValue >= midfieldForwardValue && crosserFlank != Enums.Flank.Center)
            {
                score += 5; // Small bonus from midfield flanks
            }

            // 3. Defender Presence / Pressure on Crosser
            int defendersNearCrosser = CountDefendersInZone(ballZone, defendingTeam);
            if (defendersNearCrosser > 0)
            {
                score -= defendersNearCrosser * 20; // Penalty for pressure on the crosser
                if (IsBallHolderUnderPressure(crossingPlayer))
                {
                    score -= 15; // Additional penalty if under direct pressure
                }
            }

            // 4. Defender Presence / Pressure on Target Zone and Target Player
            int defendersInTargetZone = CountDefendersInZone(targetZoneForCross, defendingTeam);
            if (defendersInTargetZone > 0)
            {
                score -= defendersInTargetZone * 25; // Significant penalty if target zone is crowded
            }

            // Explicit check for a defender intercepting the *path* of the cross
            if (IsZonePathBlocked(ballZone, targetZoneForCross, defendingTeam))
            {
                score -= 50; // Heavy penalty if path is clearly blocked
            }
            else // If path is clear, check if the target player is directly marked at destination
            {
                Player nearestDefenderToTarget = FindNearestDefender(targetPlayer, defendingTeam, targetZoneForCross);
                if (nearestDefenderToTarget != null && GetZoneDistance(targetZoneForCross, nearestDefenderToTarget.CurrentZone, isHomeTeamAttacking) <= 1)
                {
                    score -= 30; // Significant penalty for passing to a tightly marked player in the box
                }
            }

            // 5. Goalkeeper Threat Assessment
            // Evaluate if the goalkeeper is likely to intercept the cross
            Player opponentGK = defendingTeam.GoalKeeper; // Assuming one GK
            if (opponentGK != null)
            {
                double gkDistanceToTargetZone = GetZoneDistance(targetZoneForCross, opponentGK.CurrentZone, isHomeTeamAttacking);
                double gkAbility = opponentGK.trueRating.GoalKeepingHandlingForGameCalculations * 0.5 + opponentGK.trueRating.JumpingForGameCalculations * 0.5;

                // If GK is close to the target zone and has good aerial/handling, it's riskier
                if (gkDistanceToTargetZone <= 1) // GK is in or very near the target zone
                {
                    score -= gkAbility * 0.5; // Penalize based on GK ability
                }
                else if (gkDistanceToTargetZone <= 2) // GK is one zone away
                {
                    score -= gkAbility * 0.2; // Smaller penalty
                }
            }


            // 6. Target Player Attributes (Heading, Jumping Reach, Off-the-Ball, Attacking Positioning, Strength)
            score += targetPlayer.trueRating.HeaderForGameCalculations * 0.4; // Crucial for receiving crosses
            score += targetPlayer.trueRating.JumpingForGameCalculations * 0.2; // For aerial crosses
            score += targetPlayer.trueRating.PositioningForGameCalculations * 0.2; // For finding space
            score += targetPlayer.trueRating.PositioningForGameCalculations * 0.1; // For being in the right place
            score += targetPlayer.trueRating.PhysicalityForGameCalculations * 0.1; // For battling defenders


            // 7. Tactical Context: Target Player Role Appropriateness
            // Evaluate if the target player's role makes them a suitable recipient for a cross.
            double targetRoleAdjustment = 0;
            switch (targetPlayer.Role)
            {
                case Enums.PlayerRole.Poacher:
                case Enums.PlayerRole.TargetMan:
                    // Ideal targets for crosses
                    if (targetZoneForCross == opponentPenaltyArea || targetZoneForCross == opponentGoalArea)
                    {
                        targetRoleAdjustment += 40; // High bonus for strikers in the box
                    }
                    break;
                case Enums.PlayerRole.DeepLyingForward:
                case Enums.PlayerRole.FalseNine:
                    // Can be targets, but less specialized in aerial duels or pure finishing
                    if (targetZoneForCross == opponentPenaltyArea)
                    {
                        targetRoleAdjustment += 20; // Moderate bonus
                    }
                    break;
                case Enums.PlayerRole.AttackingMidfielder:
                case Enums.PlayerRole.InsideForward:
                    // Can make runs into the box and finish, but less likely to be primary aerial threats
                    if (targetZoneForCross == opponentPenaltyArea)
                    {
                        targetRoleAdjustment += 15; // Small bonus
                    }
                    break;
                case Enums.PlayerRole.CentralMidfielder:
                case Enums.PlayerRole.BoxToBoxMidfielder:
                    // Less likely to be primary cross targets, but might arrive late
                    if (targetZoneForCross == opponentPenaltyArea)
                    {
                        targetRoleAdjustment += 5; // Very small bonus, mostly for late runs
                    }
                    break;
                case Enums.PlayerRole.DefensiveMidfielder:
                case Enums.PlayerRole.CenterBack:
                case Enums.PlayerRole.FullBack:
                case Enums.PlayerRole.Winger: // Wingers typically cross, not receive crosses in the box from wide
                case Enums.PlayerRole.WidePlaymaker: // Wide playmakers typically cross, not receive crosses in the box from wide
                    targetRoleAdjustment -= 50; // Heavy penalty for inappropriate target roles
                    break;
            }
            score += targetRoleAdjustment;


            // 8. Passing Player Role Adjustments (from your existing code)
            double crossingPlayerRoleAdjustment = 0;

            switch (crossingPlayer.Role)
            {
                case Enums.PlayerRole.Winger:
                    if (crosserFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        crossingPlayerRoleAdjustment += 60; // Huge bonus for typical winger crossing
                    }
                    break;
                case Enums.PlayerRole.FullBack:
                    if (crosserFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        crossingPlayerRoleAdjustment += 55; // Strong bonus for overlapping full-back crosses
                    }
                    break;
                case Enums.PlayerRole.WidePlaymaker:
                    if (crosserFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        crossingPlayerRoleAdjustment += 30; // Good bonus for creative crosses from wide
                    }
                    break;
                case Enums.PlayerRole.InsideForward:
                    if (crosserFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        crossingPlayerRoleAdjustment += 15; // Moderate bonus, but less than pure wingers
                    }
                    break;
                case Enums.PlayerRole.AttackingMidfielder:
                case Enums.PlayerRole.AdvancedPlaymaker:
                    if (crosserFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        crossingPlayerRoleAdjustment -= 10; // Small penalty, generally prefer central play
                    }
                    else
                    {
                        crossingPlayerRoleAdjustment -= 30; // Penalize if not in an ideal wide crossing position
                    }
                    break;
                case Enums.PlayerRole.BoxToBoxMidfielder:
                case Enums.PlayerRole.CentralMidfielder:
                    crossingPlayerRoleAdjustment -= 40; // Significant penalty
                    break;
                case Enums.PlayerRole.Poacher:
                case Enums.PlayerRole.TargetMan:
                case Enums.PlayerRole.DeepLyingForward:
                case Enums.PlayerRole.FalseNine:
                    crossingPlayerRoleAdjustment -= 80; // Heavy penalty, almost never cross
                    break;
                case Enums.PlayerRole.DefensiveMidfielder:
                case Enums.PlayerRole.CenterBack:
                    crossingPlayerRoleAdjustment -= 100; // Extreme penalty
                    break;
                case Enums.PlayerRole.None:
                    break;
            }
            score += crossingPlayerRoleAdjustment;

            // 9. Add some small randomness to vary decisions
            score += Dice.d50() * 0.1; // Small random boost

            return score;
        }


        /// <summary>
        /// Calculates a score for a player's shot opportunity from the current ball zone.
        /// Higher score means a better shot opportunity.
        /// </summary>
        /// <param name="shootingPlayer">The player attempting the shot.</param>
        /// <param name="ballZone">The current zone of the ball.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <returns>A double representing the shot opportunity score.</returns>
        private double CalculateShotOpportunity(Player shootingPlayer, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateShotOpportunity: shootingPlayer:{0},ballZone:{1}," +
            //    "attackingTeam:{2},defendingTeam:{3}", shootingPlayer.position, ballZone, attackingTeam.Name, defendingTeam.Name));


            double score = 0;
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);
            double adjuster = 1.1; // arbitrary - apply at end to scale everything down if > 0

            // Determine opponent's goal area for distance calculations
            Enums.PitchZone opponentGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
            Enums.PitchZone opponentPenaltyArea = isHomeTeamAttacking ? Enums.PitchZone.PenaltyArea_Away : Enums.PitchZone.PenaltyArea_Home;
            // Assuming you have an 'EdgeOfBox' zone, or distance 3 is usually just outside
            // Enums.PitchZone opponentEdgeOfBox = isHomeTeamAttacking ? Enums.PitchZone.Attack_EdgeOfBox : Enums.PitchZone.Defensive_EdgeOfBox; 

            // Get current zonal context
            Enums.Flank currentFlank = GetFlankOfZone(ballZone);
            int lateralDistance = Math.Abs(GetZoneLateralValue(ballZone, isHomeTeamAttacking));
            int distanceToGoal = GetZoneDistance(ballZone, opponentGoalArea, isHomeTeamAttacking);

            // --- 1. Distance to Goal Scaling (Unified and Stronger Penalty for Distance) ---
            if (distanceToGoal <= 1) // Inside or very near goalkeeper area
            {
                score += 300; // Very high bonus for very close range
            }
            else if (ballZone == opponentPenaltyArea) // Inside penalty area, but not super close
            {
                score += 250; // High bonus
            }
            else if (distanceToGoal <= 3) // Edge of box to just outside penalty area (e.g., attacking midfield zones)
            {
                score += 200; // Good range for a shot, but less than in the box
            }
            else if (distanceToGoal <= 5) // Mid-range / Central Midfield (like KickOffCircle)
            {
                score -= 50; // Start penalizing significantly for midfield shots
                             //ShowMessage($"  ({shootingPlayer.fullName} is at midfield range ({distanceToGoal} zones), base score penalised by 50.)");
            }
            else // Very long range (e.g., own half or deeper midfield)
            {
                score -= 200; // Heavy base penalty for shooting from too far out
                              //ShowMessage($"  ({shootingPlayer.fullName} is very far from goal ({distanceToGoal} zones), base score penalised by 200.)");
            }

            // --- 2. Player Attributes ---
            score += shootingPlayer.trueRating.FinishingForGameCalculations * 0.5; // Finishing is primary
            score += shootingPlayer.trueRating.LongShotForGameCalculations * 0.3; // Important for shots outside box
            score += shootingPlayer.trueRating.ComposureForGameCalculations * 0.2; // Helps under pressure
            score += shootingPlayer.trueRating.PositioningForGameCalculations * 0.2; // Getting into good shooting spots

            // --- 3. Defender Presence / Pressure ---
            int defendersInZone = CountDefendersInZone(ballZone, defendingTeam);
            if (defendersInZone > 0)
            {
                score -= defendersInZone * 20; // Significant penalty for defenders in current zone
                if (IsBallHolderUnderPressure(shootingPlayer))
                {
                    score -= 30; // Extra penalty if under direct pressure
                }
            }

            // --- 4. Angle to Goal ---
            score -= lateralDistance * 10; // Penalize wider angles
            if (currentFlank != Enums.Flank.Center && lateralDistance > 1)
            {
                score -= 5;
            }

            // --- 5. Open Space ---
            if (defendersInZone == 0 && !IsBallHolderUnderPressure(shootingPlayer))
            {
                score += 15; // Bonus for shooting with no immediate pressure
            }

            // --- 6. Player Roles and Tendencies (Refined Penalties for Long Shots) ---
            double roleAdjustment = 0;

            switch (shootingPlayer.Role)
            {
                case Enums.PlayerRole.Poacher:
                    if (distanceToGoal > 3) // Penalize poachers for shooting from outside attacking third
                    {
                        roleAdjustment -= 100; // Heavy penalty for long shots
                    }
                    else if (distanceToGoal <= 2) // Bonus for being close to goal
                    {
                        roleAdjustment += 20; // Additional bonus for proximity
                    }
                    break;

                case Enums.PlayerRole.TargetMan:
                    if (distanceToGoal > 3) // Penalize target men for shooting from outside attacking third
                    {
                        roleAdjustment -= 80; // Heavy penalty for long shots. Target Man heavily penalised for long shot.);
                    }
                    else if (currentFlank == Enums.Flank.Center && distanceToGoal <= 3)
                    {
                        roleAdjustment += 15; // Bonus for central, closer shots
                    }
                    break;

                case Enums.PlayerRole.DeepLyingForward:
                case Enums.PlayerRole.FalseNine:
                    if (distanceToGoal > 4) // More severe penalty for very long shots from these roles
                    {
                        roleAdjustment -= 70;
                    }
                    else if (defendersInZone > 0 && ballZone != opponentGoalArea) // Penalize if not clear chance in box
                    {
                        roleAdjustment -= 30;
                    }
                    break;

                case Enums.PlayerRole.Winger:
                case Enums.PlayerRole.WidePlaymaker:
                case Enums.PlayerRole.InsideForward: // Inside forwards can shoot from distance but are less likely from very far
                    if (distanceToGoal > 4)
                    {
                        roleAdjustment -= 50; // Significant penalty for very long shots
                    }
                    else if (distanceToGoal > 3 && currentFlank != Enums.Flank.Center)
                    {
                        roleAdjustment -= 20; // Penalty for long shots from wide areas
                    }
                    break;

                case Enums.PlayerRole.AdvancedPlaymaker:
                case Enums.PlayerRole.AttackingMidfielder:
                case Enums.PlayerRole.BoxToBoxMidfielder:
                case Enums.PlayerRole.CentralMidfielder:
                    // These roles are generally more comfortable with shots from outside the box,
                    // but still need a penalty for extreme range (e.g., own half, very deep midfield)
                    if (distanceToGoal > 5)
                    {
                        roleAdjustment -= 60; // Penalize very long shots
                    }
                    else if (distanceToGoal > 4)
                    {
                        roleAdjustment -= 20; // Moderate penalty for long shots from deep midfield
                    }
                    // Retain existing positive adjustments for their preferred ranges (already covered by initial distance scoring + their base tendencies)
                    break;

                case Enums.PlayerRole.DefensiveMidfielder:
                    roleAdjustment -= 150; // Extremely heavy penalty for DM shooting, regardless of range
                    break;

                case Enums.PlayerRole.FullBack:
                case Enums.PlayerRole.CenterBack:
                    roleAdjustment -= 250; // Almost impossible for FBs/CBs to shoot unless extremely close and clear
                    if ((ballZone == opponentPenaltyArea || ballZone == opponentGoalArea) && defendersInZone == 0 && !IsBallHolderUnderPressure(shootingPlayer))
                    {
                        roleAdjustment += 100; // Small recovery if truly a clear tap-in/open goal in the box
                    }
                    break;

                case Enums.PlayerRole.Goalkeeper:
                    roleAdjustment -= 1000;
                    break;

                case Enums.PlayerRole.None:
                    break;
            }

            //LogEntry(new MatchEntry
            //{
            //    Level = LogLevel.Debug,
            //    EventType = MatchEventType.RoleAdjustment,
            //    PlayerName1 = shootingPlayer.fullName,
            //    NumericValue1 = roleAdjustment,
            //    TeamName1 = shootingPlayer.teamName,
            //    Zone1 = ballZone,
            //    Zone2 = shootingPlayer.CurrentZone,
            //    Timestamp = DateTime.Now
            //});

            score += roleAdjustment;

            // --- 7. Add some small randomness to vary decisions ---
            score += Dice.d5(); // Small random boost

            // --- Final Adjustment ---
            if (score > 0) score *= adjuster; // Apply the overall adjuster if score is positive
            else score /= Math.Abs(adjuster); // If negative, make it even more negative to ensure low chance

            if (ReboundChance)
            {
                if (score > 0)
                    score *= 3; // if you have a rebound chance, you're more likely to take a shot.
            }
            if (AerialBattlePending)
            {
                if (IsBallInOpponentPenaltyAreaForTeam(CurrentBallZone, attackingTeam))
                {
                    score *= 15; // header is iminent.
                }
            }

            //LogEntry(new MatchEntry
            //{
            //    Level = LogLevel.Debug,
            //    EventType = MatchEventType.ZoneDistanceCalled,
            //    PlayerName1 = shootingPlayer.fullName,
            //    NumericValue1 = distanceToGoal,
            //    TeamName1 = shootingPlayer.teamName,
            //    Zone1 = ballZone,
            //    Zone2 = shootingPlayer.CurrentZone,
            //    Timestamp = DateTime.Now
            //});

            return score;
        }

        /// <summary>
        /// Calculates a score for attempting a pass to a specific target player.
        /// Higher score means a more desirable pass.
        /// </summary>
        /// <param name="passingPlayer">The player currently attempting the pass.</param>
        /// <param name="targetPlayer">The potential recipient of the pass.</param>
        /// <param name="passType">The type of pass being attempted (e.g., Short, Long, ThroughBall, Cross).</param>
        /// <param name="ballZone">The current zone of the ball.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defending team.</param>
        /// <returns>A double representing the pass opportunity score.</returns>
        private double CalculatePassOpportunity(Player passingPlayer, Player targetPlayer, Enums.PassType passType, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculatePassOpportunity: passingPlayer:{0},targetPlayer:{1}," +
            //    "passType:{2},ballZone:{3},attackingTeam:{4},defendingTeam:{5}", passingPlayer.position, targetPlayer.position,
            //    passType, ballZone, attackingTeam.Name, defendingTeam.Name));


            double score = 0;
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);

            if (targetPlayer == null || !targetPlayer.IsAvailable)
            {
                return -9999;
            }

            // Determine the *effective* target zone for the pass.
            // For ThroughBalls, this might be a zone the player *will* run into.
            // For other passes, it's the player's current zone.
            Enums.PitchZone effectiveTargetZoneForPass = targetPlayer.CurrentZone; // Default to current zone

            if (passType == Enums.PassType.ThroughBall)
            {
                Enums.PitchZone idealReceivingZone = GetIdealThroughBallReceivingZone(targetPlayer, defendingTeam, isHomeTeamAttacking);

                if (idealReceivingZone != Enums.PitchZone.None && !IsZonePathBlocked(ballZone, idealReceivingZone, defendingTeam))
                {
                    effectiveTargetZoneForPass = idealReceivingZone; // Use the ideal zone for through balls
                }
                // If ideal zone is None or blocked, it will stay as targetPlayer.CurrentZone (from default)
            }

            // --- CRITICAL CHANGE: Check for Offside Position using the effectiveTargetZoneForPass ---
            // We now tell CheckForOffside to evaluate if the target player would be offside
            // IF they were in the 'effectiveTargetZoneForPass' when the ball is played.
            // Pass PitchZone.None for 'currentBall' to use its default value, or whatever is appropriate for your logic.
            bool targetWouldBeOffside = CheckForOffside(passingPlayer, targetPlayer, ballZone, false, PitchZone.None, effectiveTargetZoneForPass);

            double baseVisionScore = passingPlayer.trueRating.VisionForGameCalculations * 0.8 + passingPlayer.trueRating.ComposureForGameCalculations * 0.2;

            if (targetWouldBeOffside)
            {
                score += (baseVisionScore * -2.1);
                // Option 1: AI makes a mistake sometimes
                if (Dice.d100() < baseVisionScore)
                {
                    // If the pass was offside, give it a slightly less terrible score to make it "choosable"
                    score -= 100;
                }
                // Penalize heavily if the target is offside at the intended receiving zone
                //return -9999;
            }

            // Assign the 'effectiveTargetZoneForPass' to the 'targetZone' variable for subsequent scoring logic.
            // All scoring calculations below will now correctly use this potentially future zone for ThroughBalls.
            Enums.PitchZone targetZone = effectiveTargetZoneForPass;

            Enums.PitchZone opponentGoalArea = isHomeTeamAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;

            // --- Core Scoring Logic ---
            double passDistance = GetZoneDistance(ballZone, targetZone, isHomeTeamAttacking);
            double passAccuracyBase = passingPlayer.trueRating.PassingForGameCalculations;

            switch (passType)
            {
                case Enums.PassType.Short:
                    passAccuracyBase += passingPlayer.trueRating.ShortPassForGameCalculations * 0.9;
                    if (passDistance > 3) passAccuracyBase -= passDistance * 2;
                    break;
                case Enums.PassType.Long:
                    passAccuracyBase += passingPlayer.trueRating.LongPassForGameCalculations * 0.5;
                    passAccuracyBase -= passDistance * 5;
                    break;
                case Enums.PassType.ThroughBall:
                    passAccuracyBase += passingPlayer.trueRating.VisionForGameCalculations * 0.3;
                    passAccuracyBase += passingPlayer.trueRating.PassingForGameCalculations * 0.4;
                    passAccuracyBase -= passDistance * 3; // Through balls are riskier over distance
                    passAccuracyBase += targetPlayer.trueRating.PositioningForGameCalculations * 0.2;
                    break;
                case Enums.PassType.Cross:
                    passAccuracyBase += passingPlayer.trueRating.CrossingForGameCalculations * 0.5;
                    passAccuracyBase -= passDistance * 2;
                    if (GetFlankOfZone(ballZone) != Enums.Flank.Center)
                    {
                        passAccuracyBase += 10;
                    }
                    break;
            }

            if (IsBallHolderUnderPressure(passingPlayer))
            {
                passAccuracyBase -= (100 - passingPlayer.trueRating.ComposureForGameCalculations) * 0.5;
            }

            score += Math.Max(0, passAccuracyBase);

            // 2. Tactical Relevance / Positional Value
            int currentBallForwardValue = GetZoneForwardValue(ballZone, isHomeTeamAttacking);
            int targetZoneForwardValue = GetZoneForwardValue(targetZone, isHomeTeamAttacking);

            if (targetZoneForwardValue > currentBallForwardValue)
            {
                score += (targetZoneForwardValue - currentBallForwardValue) * 10;
            }
            else if (targetZoneForwardValue < currentBallForwardValue)
            {
                score -= (currentBallForwardValue - targetZoneForwardValue) * 5;
            }

            if (targetZone == GetOpponentPenaltyAreaForTeam(attackingTeam) ||
                targetZone == GetAttackingCentralZoneForTeam(attackingTeam))
            {
                int defendersInDangerousZone = CountDefendersInZone(targetZone, defendingTeam);
                score += 20 * (1 - Math.Min(1, defendersInDangerousZone / 3.0));
            }

            Enums.PitchZone idealOffensiveZoneForTarget = DetermineOffensiveZone(targetPlayer, ballZone, attackingTeam);
            if (targetPlayer.CurrentZone == idealOffensiveZoneForTarget)
            {
                score += 10;
            }

            // 3. Defender Presence at Target Zone (Risk Assessment)
            int defendersInTargetZone = CountDefendersInZone(targetZone, defendingTeam);
            if (defendersInTargetZone > 0)
            {
                score -= (defendersInTargetZone * 30);
            }

            if (IsZonePathBlocked(ballZone, targetZone, defendingTeam))
            {
                score -= 100;
            }
            else
            {
                if (IsAttackerMarked(targetPlayer))
                {
                    score -= 25;
                }
            }

            // 4. Target Player Attributes
            score += targetPlayer.trueRating.BallControlForGameCalculations * 0.2;
            score += targetPlayer.trueRating.DribblingForGameCalculations * 0.2;
            score += targetPlayer.trueRating.PositioningForGameCalculations * 0.1;
            score += targetPlayer.trueRating.ComposureForGameCalculations * 0.15;


            // 5. Target Player Position and Role Appropriateness + Passing Player Role Adjustments
            double targetRoleAdjustment = 0;
            if ((targetPlayer.Role == Enums.PlayerRole.CenterBack || targetPlayer.Role == Enums.PlayerRole.FullBack || targetPlayer.Role == Enums.PlayerRole.DefensiveMidfielder) &&
                (passType == Enums.PassType.ThroughBall || passType == Enums.PassType.Cross) &&
                (GetZoneForwardValue(targetZone, isHomeTeamAttacking) > currentBallForwardValue + 1))
            {
                targetRoleAdjustment -= 30;
            }
            if ((targetPlayer.Role == Enums.PlayerRole.Poacher || targetPlayer.Role == Enums.PlayerRole.DeepLyingForward || targetPlayer.Role == Enums.PlayerRole.FalseNine || targetPlayer.Role == Enums.PlayerRole.TargetMan || targetPlayer.Role == Enums.PlayerRole.InsideForward) &&
                passType == Enums.PassType.ThroughBall &&
                GetZoneForwardValue(targetZone, isHomeTeamAttacking) >= GetZoneForwardValue(GetOpponentPenaltyAreaForTeam(attackingTeam), isHomeTeamAttacking) - 1)
            {
                targetRoleAdjustment += 35;
            }
            if ((targetPlayer.Role == Enums.PlayerRole.Winger || targetPlayer.Role == Enums.PlayerRole.FullBack || targetPlayer.Role == Enums.PlayerRole.InsideForward) &&
                passType == Enums.PassType.Cross &&
                targetZone == GetOpponentPenaltyAreaForTeam(attackingTeam))
            {
                targetRoleAdjustment += 25;
            }
            if (targetPlayer.Role == Enums.PlayerRole.DefensiveMidfielder &&
                passType == Enums.PassType.Short &&
                targetZoneForwardValue <= currentBallForwardValue + 1)
            {
                targetRoleAdjustment += 10;
            }
            score += targetRoleAdjustment;

            double passingPlayerRoleAdjustment = 0;
            switch (passingPlayer.Role)
            {
                case Enums.PlayerRole.Poacher:
                    if (passType == Enums.PassType.Short && GetZoneDistance(targetZone, ballZone, isHomeTeamAttacking) < 2) { passingPlayerRoleAdjustment += 5; }
                    if (targetZoneForwardValue < currentBallForwardValue) { passingPlayerRoleAdjustment -= 10; }
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment -= 15; }
                    break;
                case Enums.PlayerRole.TargetMan:
                    if (passType == Enums.PassType.Short && targetPlayer.Role != Enums.PlayerRole.CenterBack && targetPlayer.Role != Enums.PlayerRole.FullBack) { passingPlayerRoleAdjustment += 15; }
                    if (passType == Enums.PassType.Long) { passingPlayerRoleAdjustment -= 10; }
                    break;
                case Enums.PlayerRole.DeepLyingForward:
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment += 20; }
                    if (targetZoneForwardValue > currentBallForwardValue) { passingPlayerRoleAdjustment += 5; }
                    break;
                case Enums.PlayerRole.FalseNine:
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment += 30; }
                    if (targetZoneForwardValue > currentBallForwardValue) { passingPlayerRoleAdjustment += 10; }
                    if (targetPlayer.Role == Enums.PlayerRole.Poacher || targetPlayer.Role == Enums.PlayerRole.AttackingMidfielder || targetPlayer.Role == Enums.PlayerRole.InsideForward) { passingPlayerRoleAdjustment += 15; }
                    break;
                case Enums.PlayerRole.Winger:
                    if (passType == Enums.PassType.Cross) { passingPlayerRoleAdjustment += 40; }
                    if (targetZoneForwardValue < currentBallForwardValue && GetZoneDistance(ballZone, targetZone, isHomeTeamAttacking) > 1) { passingPlayerRoleAdjustment -= 5; }
                    break;
                case Enums.PlayerRole.InsideForward:
                    if (passType == Enums.PassType.ThroughBall && GetZoneDistance(targetZone, opponentGoalArea, isHomeTeamAttacking) <= 2) { passingPlayerRoleAdjustment += 10; }
                    if (targetPlayer.Role == Enums.PlayerRole.Poacher || targetPlayer.Role == Enums.PlayerRole.AttackingMidfielder) { passingPlayerRoleAdjustment += 10; }
                    break;
                case Enums.PlayerRole.WidePlaymaker:
                    if (passType == Enums.PassType.ThroughBall || passType == Enums.PassType.Long) { passingPlayerRoleAdjustment += 25; }
                    if (targetPlayer.Role == Enums.PlayerRole.Poacher || targetPlayer.Role == Enums.PlayerRole.TargetMan || targetPlayer.Role == Enums.PlayerRole.AttackingMidfielder) { passingPlayerRoleAdjustment += 15; }
                    break;
                case Enums.PlayerRole.AdvancedPlaymaker:
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment += 40; }
                    if (targetPlayer.Team == attackingTeam && targetZoneForwardValue > currentBallForwardValue) { passingPlayerRoleAdjustment += 20; }
                    if (targetZoneForwardValue < currentBallForwardValue && !IsBallHolderUnderPressure(passingPlayer)) { passingPlayerRoleAdjustment -= 15; }
                    break;
                case Enums.PlayerRole.AttackingMidfielder:
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment += 20; }
                    if (targetPlayer.Role == Enums.PlayerRole.Poacher || targetPlayer.Role == Enums.PlayerRole.TargetMan) { passingPlayerRoleAdjustment += 15; }
                    break;
                case Enums.PlayerRole.DefensiveMidfielder:
                    if (passType == Enums.PassType.Short && targetZoneForwardValue <= currentBallForwardValue + 1) { passingPlayerRoleAdjustment += 25; }
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment -= 30; }
                    if (targetZoneForwardValue > currentBallForwardValue + 1) { passingPlayerRoleAdjustment -= 15; }
                    if (targetZoneForwardValue < currentBallForwardValue) { passingPlayerRoleAdjustment += 5; }
                    break;
                case Enums.PlayerRole.BoxToBoxMidfielder:
                    if (passType == Enums.PassType.Short || passType == Enums.PassType.Long) { passingPlayerRoleAdjustment += 5; }
                    if (targetZoneForwardValue > currentBallForwardValue) { passingPlayerRoleAdjustment += 5; }
                    break;
                case Enums.PlayerRole.CentralMidfielder:
                    if (passType == Enums.PassType.Short || passType == Enums.PassType.Long) { passingPlayerRoleAdjustment += 8; }
                    break;
                case Enums.PlayerRole.FullBack:
                    if (passType == Enums.PassType.Cross) { passingPlayerRoleAdjustment += 30; }
                    if (passType == Enums.PassType.Long && targetZoneForwardValue > currentBallForwardValue + 1) { passingPlayerRoleAdjustment += 10; }
                    if (targetZoneForwardValue < currentBallForwardValue && passDistance > 2) { passingPlayerRoleAdjustment -= 10; }
                    break;
                case Enums.PlayerRole.CenterBack:
                    if (passType == Enums.PassType.Short && targetZoneForwardValue < currentBallForwardValue + 1) { passingPlayerRoleAdjustment += 20; }
                    if (passType == Enums.PassType.Long && targetZoneForwardValue > currentBallForwardValue + 2) { passingPlayerRoleAdjustment += 15; }
                    if (passType == Enums.PassType.ThroughBall) { passingPlayerRoleAdjustment -= 50; }
                    if (targetZoneForwardValue > currentBallForwardValue + 1 && passDistance < 3) { passingPlayerRoleAdjustment -= 20; }
                    break;
                case Enums.PlayerRole.None:
                    break;
            }
            score += passingPlayerRoleAdjustment;

            // 6. Final Score Adjustments
            double adjuster = 1.0;
            score += Dice.d50() * 0.1;
            if (score > 0) score *= adjuster;

            if (ReboundChance)
            {
                if (score > 0)
                    score /= 2; // much less likely to pass if player can rebound the ball
            }
            if (AerialBattlePending)
            {
                if (IsMidfieldZone(CurrentBallZone))
                {
                    if (score > 0)
                    {
                        if (passType == PassType.Short)
                            score *= 10;
                        else if (passType == PassType.Long)
                            score *= 8;
                    }
                }
            }

            return score;
        }

        private List<Enums.PitchZone> CalculateActualPath(Enums.PitchZone startZone, Enums.PitchZone endZone, bool isHomePerspective)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateActualPath: startZone:{0},endZone:{1}," +
            //    "isHomePerspective:{2}",
            //startZone, endZone, isHomePerspective));


            List<Enums.PitchZone> path = new List<Enums.PitchZone>();
            // Simple placeholder: if start and end are the same, return just that zone.
            if (startZone == endZone)
            {
                path.Add(startZone);
                return path;
            }

            // More complex logic would involve:
            // 1. A graph representation of your zones (nodes and adjacent connections).
            // 2. A pathfinding algorithm like Breadth-First Search (BFS) or Dijkstra's.
            // For a simple linear progression:
            int startFwd = GetZoneForwardValue(startZone, isHomePerspective);
            int endFwd = GetZoneForwardValue(endZone, isHomePerspective);
            Enums.Flank startFlank = GetFlankOfZone(startZone);
            Enums.Flank endFlank = GetFlankOfZone(endZone);

            // Add start zone
            path.Add(startZone);

            // Simple straight line path (this will need refinement based on your actual zone layout)
            if (Math.Abs(startFwd - endFwd) <= 1 && (startFlank == endFlank || startFlank == Enums.Flank.Center || endFlank == Enums.Flank.Center))
            {
                // Direct connection
            }
            else if (startFwd < endFwd) // Moving forward
            {
                // Iterate through forward values to build a conceptual path
                for (int f = startFwd + 1; f <= endFwd; f++)
                {
                    // Try to find a zone that matches the forward value and is relevant to the end flank
                    Enums.PitchZone intermediateZone = FindZoneByForwardAndFlank(f, endFlank, isHomePerspective);
                    if (intermediateZone != Enums.PitchZone.None && !path.Contains(intermediateZone))
                    {
                        path.Add(intermediateZone);
                    }
                    else
                    {
                        // Fallback or more complex pathfinding if simple logic fails
                    }
                }
            }
            else if (startFwd > endFwd) // Moving backward
            {
                for (int f = startFwd - 1; f >= endFwd; f--)
                {
                    Enums.PitchZone intermediateZone = FindZoneByForwardAndFlank(f, endFlank, isHomePerspective);
                    if (intermediateZone != Enums.PitchZone.None && !path.Contains(intermediateZone))
                    {
                        path.Add(intermediateZone);
                    }
                    else
                    {
                        // Fallback
                    }
                }
            }

            // Ensure the end zone is included if it's distinct and not already there
            if (!path.Contains(endZone))
            {
                path.Add(endZone);
            }

            return path;
        }

        /// <summary>
        /// Calculates a conceptual distance between two PitchZones based on their predefined coordinates.
        /// Uses Euclidean Distance.
        /// </summary>
        /// <param name="zone1">The first PitchZone.</param>
        /// <param name="zone2">The second PitchZone.</param>
        /// <returns>The calculated integer distance. Returns a very high number if a zone is not mapped (error).</returns>
        public int CalculateDistance(Enums.PitchZone zone1, Enums.PitchZone zone2)
        {
            ZoneCoordinate coord1;
            ZoneCoordinate coord2;

            if (!_zoneCoordinates.TryGetValue(zone1, out coord1))
            {
                throw new Exception(string.Format("WARNING: PitchZone {0} not found in _zoneCoordinates map for distance calculation.", zone1));
                //return 999; // Indicate error or unknown zone
            }
            if (!_zoneCoordinates.TryGetValue(zone2, out coord2))
            {
                throw new Exception(string.Format("WARNING: PitchZone {0} not found in _zoneCoordinates map for distance calculation.", zone2));
                //return 999; // Indicate error or unknown zone
            }

            // Calculate differences in coordinates
            double deltaX = coord1.X - coord2.X;
            double deltaY = coord1.Y - coord2.Y;

            // Calculate Euclidean distance: sqrt((x2-x1)^2 + (y2-y1)^2)
            // We cast to int at the end because your method currently returns int.
            // If you can change the method's return type to 'double', that would be ideal
            // for full precision (e.g., 'public double CalculateDistance(...)').
            return (int)Math.Sqrt((deltaX * deltaX) + (deltaY * deltaY));
        }

        /// <summary>
        /// Calculates a score for a player's opportunity to dribble.
        /// Higher score means a more desirable dribble.
        /// This method assesses a general dribble opportunity (e.g., to advance play, beat a man, or escape pressure).
        /// </summary>
        /// <param name="dribblingPlayer">The player currently attempting to dribble.</param>
        /// <param name="ballZone">The current zone of the ball.</param>
        /// <param name="attackingTeam">The attacking team.</param>
        /// <param name="defendingTeam">The defendingTeam.</param>
        /// <returns>A double representing the dribble opportunity score.</returns>
        private double CalculateDribbleOpportunity(Player dribblingPlayer, Enums.PitchZone ballZone, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("CalculateDribbleOpportunity: dribblingPlayer:{0},ballZone:{1}," +
            //    "attackingTeam:{2},defendingTeam:{3}", dribblingPlayer.position, ballZone, attackingTeam.Name, defendingTeam.Name));


            double score = 0;
            bool isHomeTeamAttacking = (attackingTeam == HomeTeam);

            // Get current zonal context
            Enums.Flank currentFlank = GetFlankOfZone(ballZone);
            int currentForwardValue = GetZoneForwardValue(ballZone, isHomeTeamAttacking);

            int midfieldForwardValue = GetZoneForwardValue(Enums.PitchZone.Midfield_Center, isHomeTeamAttacking);
            int attackingThirdForwardValue = GetZoneForwardValue(isHomeTeamAttacking ? Enums.PitchZone.AwayAttack_Center : Enums.PitchZone.HomeDefense_Center, isHomeTeamAttacking);
            int defensiveThirdForwardValue = GetZoneForwardValue(isHomeTeamAttacking ? Enums.PitchZone.HomeDefense_Center : Enums.PitchZone.AwayAttack_Center, isHomeTeamAttacking); // For player's own defensive third

            // 1. Player Attributes (Dribbling, Agility, Balance, Flair, Pace, Acceleration, Composure)
            score += dribblingPlayer.trueRating.DribblingForGameCalculations * 0.6; // Core dribbling skill
            score += dribblingPlayer.trueRating.AgilityForGameCalculations * 0.15; // Quick changes of direction
            score += dribblingPlayer.trueRating.BalanceForGameCalculations * 0.1; // Stay on feet, resist challenges
            score += dribblingPlayer.trueRating.SprintForGameCalculations * 0.05; // Speed with ball for direct runs
            score += dribblingPlayer.trueRating.PaceForGameCalculations * 0.05; // Overall speed
            score += dribblingPlayer.trueRating.AccelerationForGameCalculations * 0.05; // Burst past defenders
            score += dribblingPlayer.trueRating.ComposureForGameCalculations * 0.0; // Composure is more about execution under pressure, less about the initial decision. (Adjusted weight)

            // 2. Defender Presence / Pressure
            int defendersNearby = CountDefendersInZone(ballZone, defendingTeam);
            bool isUnderDirectPressure = IsBallHolderUnderPressure(dribblingPlayer);

            if (defendersNearby > 0)
            {
                score -= defendersNearby * 30; // Heavy penalty for defenders in the immediate zone
                if (isUnderDirectPressure)
                {
                    score -= 20; // Additional penalty if under direct, close-up pressure
                }
            }

            // 3. Open Space / Potential to Advance
            // Evaluate if there's an adjacent zone to dribble *into* that is less congested and offers forward progress.
            Enums.PitchZone targetDribbleZone = GetBestAdjacentDribbleZone(ballZone, attackingTeam, defendingTeam, isHomeTeamAttacking);

            if (targetDribbleZone != Enums.PitchZone.None)
            {
                int defendersInTargetZone = CountDefendersInZone(targetDribbleZone, defendingTeam);
                // Bonus for having clear space to dribble into
                if (defendersInTargetZone == 0)
                {
                    score += 30; // Significant bonus for open space ahead
                }
                else if (defendersInTargetZone < defendersNearby) // Dribbling into less crowded space
                {
                    score += 10; // Moderate bonus
                }

                // Add bonus if dribbling into the target zone advances the ball towards goal
                if (GetZoneForwardValue(targetDribbleZone, isHomeTeamAttacking) > currentForwardValue)
                {
                    score += 15; // Bonus for forward dribble
                }
            }
            else // No good zone to dribble into, or all adjacent zones are worse
            {
                score -= 40; // Heavy penalty if stuck with nowhere to go or only bad options
            }


            // 4. Positional Context / Field Zone
            // Dribbling is generally more valuable in attacking zones for creating chances,
            // but also valuable in defensive zones to escape pressure.

            if (currentForwardValue >= attackingThirdForwardValue)
            {
                score += 30; // Strong bonus in the attacking third (creating chances)
            }
            else if (currentForwardValue >= midfieldForwardValue)
            {
                score += 10; // Moderate bonus in midfield (advancing play)
            }
            else // Defensive third
            {
                // Dribbling in own defensive half is usually risky, but has value if escaping pressure.
                // The base penalty for defendersNearby and bonus for open space already handle this somewhat.
                // Add a general penalty for dribbling in defensive zones *unless* under pressure and needs to escape.
                if (!isUnderDirectPressure && defendersNearby > 0) // Risky dribble with defenders nearby but not direct pressure
                {
                    score -= 20;
                }
                else if (isUnderDirectPressure && currentForwardValue < midfieldForwardValue)
                {
                    score += 10; // Small bonus for dribbling to escape deep pressure
                }
                else
                {
                    score -= 30; // General penalty for risky dribbling in deep defense
                }
            }


            // --- Player Roles and Tendencies Scoring Adjustments (Role Nuances!) ---
            double roleAdjustment = 0;

            switch (dribblingPlayer.Role)
            {
                case Enums.PlayerRole.Poacher:
                    // Rarely dribbles unless to create space for a very quick shot, or escape immediate pressure in final third.
                    if (currentForwardValue >= attackingThirdForwardValue && defendersNearby <= 1)
                    {
                        roleAdjustment += 10; // Small bonus for dribbling into shooting space/beating last man
                    }
                    else
                    {
                        roleAdjustment -= 30; // Penalize other dribbles
                    }
                    break;

                case Enums.PlayerRole.TargetMan:
                    // Almost never dribbles. Focus on holding up ball.
                    roleAdjustment -= 50; // Heavy penalty for dribbling to carry ball
                    // Small exception for shielding the ball (retaining possession under pressure)
                    if (isUnderDirectPressure && defendersNearby >= 1 && currentForwardValue < attackingThirdForwardValue)
                    {
                        roleAdjustment += 15; // Allowance for shielding dribble to retain possession
                    }
                    break;

                case Enums.PlayerRole.DeepLyingForward:
                    // Can dribble to link play, move into space, or pull defenders out.
                    if (currentForwardValue >= midfieldForwardValue && currentForwardValue < attackingThirdForwardValue)
                    {
                        roleAdjustment += 20; // Moderate bonus for dribbling through midfield
                    }
                    else if (isUnderDirectPressure && defendersNearby <= 1)
                    {
                        roleAdjustment += 10; // Bonus for escaping pressure
                    }
                    break;

                case Enums.PlayerRole.FalseNine:
                    // Dribbles to create space, penetrate, or link up. Good ball control.
                    if (currentForwardValue >= midfieldForwardValue && currentFlank == Enums.Flank.Center)
                    {
                        roleAdjustment += 35; // Strong bonus for central dribbling to create
                    }
                    if (isUnderDirectPressure && defendersNearby <= 1)
                    {
                        roleAdjustment += 15; // Bonus for dribbling out of tight spaces
                    }
                    break;

                case Enums.PlayerRole.Winger:
                    // Primary dribblers, especially in wide attacking areas to beat defenders.
                    if (currentFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue)
                    {
                        roleAdjustment += 60; // Huge bonus for typical winger dribbling to beat a man
                    }
                    break;

                case Enums.PlayerRole.InsideForward:
                    // Dribbles to cut inside and shoot/pass, or to beat a wide defender.
                    if (currentFlank != Enums.Flank.Center && currentForwardValue >= attackingThirdForwardValue)
                    {
                        roleAdjustment += 55; // Strong bonus for dribbling to cut inside/penetrate
                    }
                    // Bonus for dribbling from wide towards central attacking zones
                    if (currentFlank != Enums.Flank.Center && defendersNearby < 2)
                    {
                        roleAdjustment += 20;
                    }
                    break;

                case Enums.PlayerRole.WidePlaymaker:
                    // Dribbles to retain possession, find passing lanes, or open space for crosses. Not primarily for beating multiple players.
                    if (defendersNearby <= 1 && currentForwardValue >= midfieldForwardValue && currentFlank != Enums.Flank.Center)
                    {
                        roleAdjustment += 25; // Moderate bonus for dribbling into space to control play
                    }
                    else
                    {
                        roleAdjustment -= 10; // Slight penalty for risky dribbling to beat a man
                    }
                    break;

                case Enums.PlayerRole.AdvancedPlaymaker:
                    // Dribbles to create space, carry the ball through midfield, or break lines.
                    if (currentForwardValue >= midfieldForwardValue && currentForwardValue <= attackingThirdForwardValue && currentFlank == Enums.Flank.Center)
                    {
                        roleAdjustment += 40; // Strong bonus for central dribbling to advance play
                    }
                    if (isUnderDirectPressure && defendersNearby <= 1)
                    {
                        roleAdjustment += 15; // Bonus for escaping pressure to maintain possession/build attack
                    }
                    break;

                case Enums.PlayerRole.AttackingMidfielder:
                    // Can dribble to create shooting chances, beat a man, or link play in the final third.
                    if (currentForwardValue >= attackingThirdForwardValue && defendersNearby <= 1)
                    {
                        roleAdjustment += 35; // Good bonus for dribbling in dangerous areas
                    }
                    break;

                case Enums.PlayerRole.DefensiveMidfielder:
                    // Dribbles primarily to escape immediate pressure in their own half and retain possession.
                    if (currentForwardValue < midfieldForwardValue && isUnderDirectPressure)
                    {
                        roleAdjustment += 15; // Small allowance for dribbling out of defensive trouble
                    }
                    else
                    {
                        roleAdjustment -= 60; // Heavy penalty for general dribbling to advance play
                    }
                    break;

                case Enums.PlayerRole.BoxToBoxMidfielder:
                    // Can dribble to carry the ball forward if space is available, especially in transitional play.
                    if (defendersNearby <= 1 && currentForwardValue >= midfieldForwardValue && currentForwardValue <= attackingThirdForwardValue)
                    {
                        roleAdjustment += 15; // Moderate bonus for carrying ball through midfield
                    }
                    break;

                case Enums.PlayerRole.CentralMidfielder:
                    // Dribbles to retain possession, shift position, or evade initial pressure. Not typically for beating multiple players.
                    if (defendersNearby <= 1 && currentForwardValue >= midfieldForwardValue && currentFlank == Enums.Flank.Center)
                    {
                        roleAdjustment += 10; // Small bonus for controlled dribbling in midfield
                    }
                    else
                    {
                        roleAdjustment -= 20; // Penalize aggressive or risky dribbles
                    }
                    break;

                case Enums.PlayerRole.FullBack:
                    // Can dribble to overlap, escape pressure on the flank, or initiate attacks from deep.
                    if (currentFlank != Enums.Flank.Center && currentForwardValue >= midfieldForwardValue && defendersNearby <= 1)
                    {
                        roleAdjustment += 25; // Moderate bonus for overlapping runs with ball
                    }
                    else if (currentForwardValue < midfieldForwardValue && isUnderDirectPressure)
                    {
                        roleAdjustment += 10; // Small allowance for escaping pressure in defense
                    }
                    else
                    {
                        roleAdjustment -= 20; // Penalize general dribbling in central areas or risky situations
                    }
                    break;

                case Enums.PlayerRole.CenterBack:
                    // Almost never dribbles, only to escape immediate, critical pressure within their own defensive third.
                    if (currentForwardValue <= defensiveThirdForwardValue && isUnderDirectPressure && defendersNearby <= 1)
                    {
                        roleAdjustment += 10; // Tiny allowance for dribbling to escape extreme pressure in own box/defensive zone
                    }
                    else
                    {
                        roleAdjustment -= 150; // Extreme penalty for any other dribble
                    }
                    break;

                case Enums.PlayerRole.Goalkeeper:
                    roleAdjustment -= 1000; // Goalkeepers almost never dribble in open play
                    break;

                case Enums.PlayerRole.None:
                    // Default or unassigned roles get no specific adjustment.
                    break;
            }

            score += roleAdjustment;


            // 6. Add some small randomness to vary decisions
            score += Dice.d50() * 0.1; // Small random boost
            //double adjuster = 1.1;
            //score *= adjuster;

            return score;
        }

