        #region General Defense

        // New method to check if an attacker is marked (fast lookup)
        public bool IsAttackerMarked(Player attacker)
        {
            //LoggingStuff.LogMethodCall(string.Format("IsAttackerMarked: attacker{0}", attacker.position));

            return _currentlyMarkedAttackers.Contains(attacker);
        }

        // New method to set an attacker as marked
        public void SetAttackerMarked(Player attacker, Player marker)
        {
            //LoggingStuff.LogMethodCall(string.Format("SetAttackerMarked: attacker:{0},marker:{1}",
            //    attacker.position, marker.position));

            _currentlyMarkedAttackers.Add(attacker);
            _attackerToMarkerMap[attacker] = marker; // Track who is marking them
        }

        // You will need a new method to *calculate* these assignments
        // This is where the logic previously spread across FindNearestDefender and DecideMarkingTarget converges.
        // This method needs to be called ONCE per 15-second moment.
        public void UpdateAllMarkingAssignments(Team attackingTeam, Team defendingTeam, Player currentBallHolder, int currentMinute, int currentSecond)
        {
            //LoggingStuff.LogMethodCall(string.Format("UpdateAllMarkingsAssignments: attackingTeam:{0},defendingTeam:{1},currentBallHolder:{2}," +
            //    "currentMinute:{3},currentSecond:{4}", attackingTeam.Name, defendingTeam.Name, currentBallHolder.fullName,
            //    CurrentMinute.ToString(), CurrentSecond.ToString()));

            ResetMarkingStatus();

            // 1. Identify all potentially markable attackers (excluding ball holder)
            var activeAttackers = attackingTeam.AvailableOnFieldOutfielders
                .Where(p => p != currentBallHolder)
                .ToList(); // Convert to List to avoid multiple enumerations

            foreach (Player defender in defendingTeam.AvailableOnFieldPlayers)
            {
                Player bestMarkTargetForThisDefender = null;
                double highestThreatScoreForThisDefender = -1.0;

                // Defender's marking preference based on role (similar to your existing logic)
                // Consider extracting this into a helper method if it gets complex.
                Func<Player, double> getRoleBonus = (potentialMark) =>
                {
                    double bonus = 0;
                    switch (defender.Role)
                    {
                        case Enums.PlayerRole.CenterBack:
                            if (potentialMark.Role == Enums.PlayerRole.Poacher || potentialMark.Role == Enums.PlayerRole.TargetMan || potentialMark.Role == Enums.PlayerRole.DeepLyingForward)
                                bonus += 25;
                            break;
                        case Enums.PlayerRole.FullBack:
                            if (potentialMark.Role == Enums.PlayerRole.Winger || potentialMark.Role == Enums.PlayerRole.InsideForward)
                                bonus += 25;
                            break;
                        case Enums.PlayerRole.DefensiveMidfielder:
                            if (potentialMark.Role == Enums.PlayerRole.AdvancedPlaymaker || potentialMark.Role == Enums.PlayerRole.AttackingMidfielder || potentialMark.Role == Enums.PlayerRole.FalseNine)
                                bonus += 20;
                            break;
                    }
                    return bonus;
                };

                foreach (Player potentialMark in activeAttackers)
                {
                    // Only consider marking if the attacker isn't already marked by someone else
                    if (IsAttackerMarked(potentialMark)) continue;

                    double currentThreatScore = 0;

                    // 1. Proximity to Goal (from attacker's perspective)
                    bool isHomeAttacking = (attackingTeam == HomeTeam);
                    Enums.PitchZone opponentGoalZone = isHomeAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                    int distanceToOpponentGoal = GetZoneDistance(potentialMark.CurrentZone, opponentGoalZone, isHomeAttacking);
                    currentThreatScore += (10 - distanceToOpponentGoal) * 10;

                    // 2. Player's Offensive Threat Attributes
                    currentThreatScore += potentialMark.trueRating.FinishingForGameCalculations * 0.3;
                    currentThreatScore += potentialMark.trueRating.PositioningForGameCalculations * 0.3;
                    currentThreatScore += potentialMark.trueRating.AggressionForGameCalculations * 0.4;

                    // 3. Proximity to Ball Carrier
                    int distanceToBallCarrier = GetZoneDistance(potentialMark.CurrentZone, currentBallHolder.CurrentZone, isHomeAttacking);
                    if (distanceToBallCarrier <= 2)
                    {
                        currentThreatScore += 20;
                    }

                    // 4. Defender's Role Influence (applied here as a bonus for this defender)
                    currentThreatScore += getRoleBonus(potentialMark);

                    currentThreatScore = Math.Max(0.1, currentThreatScore); // Ensure min score

                    if (currentThreatScore > highestThreatScoreForThisDefender)
                    {
                        highestThreatScoreForThisDefender = currentThreatScore;
                        bestMarkTargetForThisDefender = potentialMark;
                    }
                }

                // If this defender found a suitable target, assign them and mark the attacker as taken
                if (bestMarkTargetForThisDefender != null && highestThreatScoreForThisDefender > 30) // Use your threshold
                {
                    SetAttackerMarked(bestMarkTargetForThisDefender, defender);
                }
            }
        }

        /// <summary>
        /// Dictates a defensive player's actions when an opponent has the ball, including tackle decision and type,
        /// and now also marking or repositioning if a tackle isn't chosen.
        /// This method now delegates goalkeeper actions to `DecideGoalkeeperAction`.
        /// </summary>
        /// <param name="defender">The defensive player.</param>
        /// <param name="ballCarrier">The opponent in possession.</param>
        /// <param name="defendingTeam">The defender's team.</param>
        /// <param name="attackingTeam">The opponent's team (ball carrier's team).</param>
        private void DecideDefensiveAction(Player defender, Player ballCarrier, Team defendingTeam, Team attackingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DecideDefensiveAction: defender:{0},ballCarrier:{1}," +
            //    "defendingTeam:{2},attackingTeam:{3}", defender.position, ballCarrier.position,
            //    defendingTeam.Name, attackingTeam.Name));


            // Ensure the defender is active and on the pitcho
            if (defender.IsInjured || defender.isSentOff)
            {
                return;
            }

            // **IMPORTANT CHANGE**: If the player is a Goalkeeper, delegate to the dedicated GK action method.
            if (defender.Position == Enums.Positions.Goalkeeper)
            {
                DecideGoalkeeperAction(defender, ballCarrier, defendingTeam, attackingTeam);
                return; // GK action handled, exit this method for the goalkeeper.
            }

            // --- Outfield Player Logic Below ---

            bool isCloseEnoughForTackle = (defender.CurrentZone == ballCarrier.CurrentZone || IsAdjacentZone(defender.CurrentZone, ballCarrier.CurrentZone));

            if (isCloseEnoughForTackle)
            {
                double tackleDesire = CalculateTackleDesire(defender, ballCarrier, defendingTeam);
                if (Dice.d100() < tackleDesire)
                {
                    Enums.TackleType chosenTackleType = Enums.TackleType.Standing;

                    double standingSkill = defender.trueRating.StandTackleForGameCalculations;
                    double slidingSkill = defender.trueRating.SlideTackleForGameCalculations;
                    double aggression = defender.trueRating.AggressionForGameCalculations;
                    double composure = defender.trueRating.ComposureForGameCalculations;

                    bool inDangerousArea = IsZoneDangerous(defender.CurrentZone, attackingTeam == HomeTeam);

                    if (slidingSkill > standingSkill + 15)
                    {
                        chosenTackleType = Enums.TackleType.Sliding;
                    }
                    else if (inDangerousArea)
                    {
                        if (composure > 60 && standingSkill >= slidingSkill - 10)
                        {
                            chosenTackleType = Enums.TackleType.Standing;
                        }
                        else if (aggression > 80 && slidingSkill > standingSkill)
                        {
                            chosenTackleType = Enums.TackleType.Sliding;
                        }
                    }
                    else
                    {
                        if (slidingSkill > standingSkill - 5)
                        {
                            chosenTackleType = Enums.TackleType.Sliding;
                        }
                    }

                    if (Dice.d100() < aggression * 0.3 && chosenTackleType == Enums.TackleType.Standing && slidingSkill > 40)
                    {
                        chosenTackleType = Enums.TackleType.Sliding;
                    }
                    else if (Dice.d100() < composure * 0.2 && chosenTackleType == Enums.TackleType.Sliding && standingSkill > 40)
                    {
                        chosenTackleType = Enums.TackleType.Standing;
                    }

                    // *** CRITICAL CHANGE HERE: Capture the outcome of AttemptTackle ***
                    Enums.TackleOutcome tackleOutcome = AttemptTackle(defender, ballCarrier, attackingTeam, defendingTeam, chosenTackleType);
                    int x = 0;
                    //MatchEntry meOpen = new MatchEntry
                    //{
                    //    Level = LogLevel.Info,
                    //    EventType = MatchEventType.TackleOutcome,
                    //    Timestamp = DateTime.Now,

                    //    PlayerName1 = defender.fullName,
                    //    Player1Pos = defender.position,
                    //    PlayerName2 = ballCarrier.fullName,
                    //    Player2Pos = ballCarrier.position,
                    //    TeamName1 = defendingTeam.Name,
                    //    TeamName2 = attackingTeam.Name,

                    //    Zone1 = CurrentBallZone,
                    //};

                    // *** Now, handle the tackleOutcome explicitly - NO NEED! AttemptTackle does everything you need!
                    //if (tackleOutcome == Enums.TackleOutcome.Successful)
                    //{
                    //    //meOpen.TackleResult = TackleResultType.WonPossession;
                    //    // Possession is already transferred to the tackler within AttemptTackle
                    //    // No further action needed here for possession, as it's resolved.
                    //}
                    //else if (tackleOutcome == Enums.TackleOutcome.Foul)
                    //{
                    //    //meOpen.TackleResult = TackleResultType.Foul;
                    //    // Foul handling (setting match state to FreeKick/Penalty) is done inside AttemptTackle
                    //    // No further action needed here.
                    //}
                    //else if (tackleOutcome == Enums.TackleOutcome.BallOutOfBounds)
                    //{
                    //    //meOpen.TackleResult = TackleResultType.BallOut;
                    //    // Out of bounds handling (setting match state) is done inside AttemptTackle
                    //    // No further action needed here.
                    //}
                    //else if (tackleOutcome == Enums.TackleOutcome.OwnGoal)
                    //{
                    //    //meOpen.TackleResult = TackleResultType.LostEncounter;
                    //    //meOpen.IsOwnGoal = true;
                    //    // Own goal handling is done inside AttemptTackle
                    //    // No further action needed here.
                    //}
                    //else if (tackleOutcome == Enums.TackleOutcome.Failed)
                    //{
                    //    //// The tackle failed to win the ball cleanly.
                    //    //// Apply the 'dribbler retains' vs. 'loose ball' logic here.
                    //    //double retentionChanceAfterFailedTackle =
                    //    //    (ballCarrier.trueRating.DribblingForGameCalculations * 0.5) +
                    //    //    (ballCarrier.trueRating.BallControlForGameCalculations * 0.5);

                    //    //int finalRetentionRoll = Dice.d100();

                    //    //if (finalRetentionRoll <= retentionChanceAfterFailedTackle)
                    //    //{
                    //    //    // Dribbler successfully shrugged off the tackle and maintained control.
                    //    //    //meOpen.TackleResult = TackleResultType.LostEncounter;
                    //    //    // Ensure the ball carrier still has possession.
                    //    //SetPossession(ballCarrier, ballCarrier.CurrentZone, attackingTeam);
                    //    //}
                    //    //else
                    //    //{
                    //    //    // The tackle failed, and the ball broke loose.
                    //    //    //meOpen.TackleResult = TackleResultType.LooseBall;
                    //    //    // Set the ball to loose, allowing other players to contest it.
                    //    //    CurrentBallZone = ballCarrier.CurrentZone; // Ball becomes loose where the tackle happened
                    //    //    SetLooseBall(false, ballCarrier, Enums.CornerDeliveryType.None, attackingTeam, defendingTeam); // This should set CurrentBallHolder = null and trigger loose ball handling
                    //    //}
