                    //    throw new Exception("ERROR: Unhandled tackle outcome from " + defender.fullName + ".");
                    //}
                    //LogEntry(meOpen);
                    return;
                }
            }

            // If tackle wasn't attempted or didn't succeed in changing possession immediately,
            // proceed with marking or repositioning.
            Player markedPlayer = DecideMarkingTarget(defender, attackingTeam, defendingTeam);
            if (markedPlayer != null)
            {
                //ShowMessage(string.Format("{0} ({1}) is marking {2}.", defender.fullName, defendingTeam.Name, markedPlayer.fullName));
                RepositionDefender(defender, markedPlayer, defendingTeam, attackingTeam);
                return;
            }

            RepositionDefender(defender, ballCarrier, defendingTeam, attackingTeam);
        }

        /// <summary>
        /// Determines which attacking player a defender should prioritize marking.
        /// </summary>
        /// <param name="defender">The defender looking for a mark.</param>
        /// <param name="attackingTeam">The team currently attacking.</param>
        /// <param name="defendingTeam">The team currently defending (defender's team).</param>
        /// <returns>The Player to mark, or null if no immediate mark is necessary/possible.</returns>
        public Player DecideMarkingTarget(Player defender, Team attackingTeam, Team defendingTeam)
        {
            //LoggingStuff.LogMethodCall(string.Format("DecideMarkingTarget: defender:{0},attackingTeam:{1},defendingTeam:{2}," +
            //    "currentBallZone:{3},CurrentBallHolder:{4}",
            //    defender.fullName, attackingTeam.Name, defendingTeam.Name, CurrentBallZone, CurrentBallHolder.fullName));
            // Check the global/cached marking assignments.
            // If this defender has already been assigned a specific mark in UpdateAllMarkingAssignments, return that.
            // Otherwise, find the highest threat *unmarked* player that this defender *could* mark.

            Player bestMarkTarget = null;
            double highestThreatScore = -1.0;
            bool isHomeAttacking = (attackingTeam == HomeTeam);

            // Get all active attacking players (still need to iterate to find the *best available* for THIS defender)
            // We filter out those already explicitly marked by another defender.
            var activeAttackers = attackingTeam.AvailableOnFieldOutfielders
                .Where(p => p != CurrentBallHolder && !IsAttackerMarked(p));


            foreach (Player potentialMark in activeAttackers)
            {
                // IMPORTANT: The "unmarked" check is now handled by the .Where clause above,
                // and by the pre-calculation in UpdateAllMarkingAssignments.
                // We are now looking for the *most suitable* unmarked player for THIS defender.

                double currentThreatScore = 0;

                // 1. Proximity to Goal:
                Enums.PitchZone opponentGoalZone = isHomeAttacking ? Enums.PitchZone.GoalkeeperArea_Away : Enums.PitchZone.GoalkeeperArea_Home;
                int distanceToOpponentGoal = GetZoneDistance(potentialMark.CurrentZone, opponentGoalZone, isHomeAttacking);
                currentThreatScore += (10 - distanceToOpponentGoal) * 10;

                // 2. Player's Offensive Threat Attributes:
                currentThreatScore += potentialMark.trueRating.FinishingForGameCalculations * 0.3;
                currentThreatScore += potentialMark.trueRating.PositioningForGameCalculations * 0.3;
                currentThreatScore += potentialMark.trueRating.AggressionForGameCalculations * 0.4;

                // 3. Proximity to Ball Carrier:
                int distanceToBallCarrier = GetZoneDistance(potentialMark.CurrentZone, CurrentBallHolder.CurrentZone, isHomeAttacking);
                if (distanceToBallCarrier <= 2)
                {
                    currentThreatScore += 20;
                }

                // 4. Defender's Role Influence on Marking Preference
                switch (defender.Role)
                {
                    case Enums.PlayerRole.CenterBack:
                        if (potentialMark.Role == Enums.PlayerRole.Poacher || potentialMark.Role == Enums.PlayerRole.TargetMan || potentialMark.Role == Enums.PlayerRole.DeepLyingForward)
                        {
                            currentThreatScore += 25;
                        }
                        break;
                    case Enums.PlayerRole.FullBack:
                        if (potentialMark.Role == Enums.PlayerRole.Winger || potentialMark.Role == Enums.PlayerRole.InsideForward)
                        {
                            currentThreatScore += 25;
                        }
                        break;
                    case Enums.PlayerRole.DefensiveMidfielder:
                        if (potentialMark.Role == Enums.PlayerRole.AdvancedPlaymaker || potentialMark.Role == Enums.PlayerRole.AttackingMidfielder || potentialMark.Role == Enums.PlayerRole.FalseNine)
                        {
                            currentThreatScore += 20;
                        }
                        break;
                }

                currentThreatScore = Math.Max(0.1, currentThreatScore);

                if (currentThreatScore > highestThreatScore)
                {
                    highestThreatScore = currentThreatScore;
                    bestMarkTarget = potentialMark;
                }
            }

            // Return the best target if it's above a threshold AND it's not already marked by *another* defender
            // The IsAttackerMarked check in the LINQ query already handles the latter.
            return highestThreatScore > 30 ? bestMarkTarget : null;
        }

        List<Player> GetUnmarkedAttackers(List<Player> attackingThreats)
        {
            //LoggingStuff.LogMethodCall(string.Format("GetUnmarkedAttackers: attackingThreats:{0}",
            //    string.Join(",", attackingThreats.Select(p => p.position))));


            List<Player> unmarkedAttackers = new List<Player>();
            foreach (var attacker in attackingThreats)
            {
                if (attacker.OffensiveSetPieceRole != Enums.SetPieceRole.SetPieceTaker && attacker.MarkedOpponent == null)
                {
                    unmarkedAttackers.Add(attacker);
                }
            }
            return unmarkedAttackers;
        }

        void AssignManMarking(ref List<Player> availableDefenders, List<Player> unmarkedAttackers)
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignManMarking: availableDefenders:{0},unmarkedAttackers:{1}",
            //    string.Join(",", availableDefenders.Select(p => p.position)),
            //    string.Join(",", unmarkedAttackers.Select(p => p.position))));


            for (int i = availableDefenders.Count - 1; i >= 0; i--)
            {
                Player defender = availableDefenders[i];

                // Your logic to assign the defender to mark an attacker
                // For example:
                if (unmarkedAttackers.Count > 0)
                {
                    Player attackerToMark = unmarkedAttackers[0];
                    defender.MarkedOpponent = attackerToMark; // Assuming you have a method like this
                    unmarkedAttackers.RemoveAt(0);
                    availableDefenders.RemoveAt(i);
                }
                else
                {
                    break; // No more unmarked attackers to assign
                }
            }
        }

        private void AssignManMarkers(List<Player> availableDefenders, List<Player> attackingThreats, Dictionary<Enums.SetPieceRole, Enums.SetPieceRole> attackerRoleToDefenderRoleMapping,
            DefensiveSetPieceRoutine defensiveRoutine)
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignManMarkers: availableDefenders:{0},attackingThreats:{1}," +
            //    "attackerRoleToDefenderRoleMapping:{2},defensiveRoutine:{3}",
            //    string.Join(",", availableDefenders.Select(p => p.position)),
            //    string.Join(",", attackingThreats.Select(p => p.position)),
            //    string.Join(",", attackerRoleToDefenderRoleMapping.Select(kvp => $"{kvp.Key}:{kvp.Value}")),
            //    defensiveRoutine));


            //ShowMessage(" - Assigning Man-Marking roles.");

            // First, assign defenders to specific attackers as defined in the routine's mapping
            foreach (var mapEntry in attackerRoleToDefenderRoleMapping)
            {
                Enums.SetPieceRole attackingRole = mapEntry.Key;
                Enums.SetPieceRole requiredDefensiveRole = mapEntry.Value; // This is the role the defender should take (e.g., ManMarker)

                // Find the specific attacker with that role
                Player targetAttacker = attackingThreats.FirstOrDefault(a => a.OffensiveSetPieceRole == attackingRole && a.MarkedOpponent == null);

                if (targetAttacker != null)
                {
                    // Find the best available defender for this specific marking task
                    Player bestMarker = availableDefenders
                        .Where(p => defensiveRoutine.RoleAssignments.ContainsKey(requiredDefensiveRole) && defensiveRoutine.RoleAssignments[requiredDefensiveRole].Contains(p.Position)) // Ensure defender's position is suitable for this role
                        .OrderByDescending(p => CalculateDefensiveRoleSuitability(p, requiredDefensiveRole))
                        .ThenBy(p => CalculateDistance(p.CurrentZone, targetAttacker.CurrentZone)) // Prioritize closer defenders
                        .FirstOrDefault();

                    if (bestMarker != null)
                    {
                        bestMarker.DefensiveSetPieceRole = requiredDefensiveRole; // Assign the role from the routine
                        bestMarker.MarkedOpponent = targetAttacker;
                        availableDefenders.Remove(bestMarker);
                        //ShowMessage(bestMarker.fullName + " ( " + requiredDefensiveRole + ") marking " + targetAttacker.fullName + " (" + attackingRole + ").");
                    }
                }
            }

            // Assign remaining available defenders to man-mark the most dangerous *unmarked* attacking players
            List<Player> unmarkedAttackers = GetUnmarkedAttackers(attackingThreats);
            AssignManMarking(ref availableDefenders, unmarkedAttackers);
            foreach (var defender in availableDefenders)
            {
                if (!unmarkedAttackers.Any()) break;

                // Find the "most dangerous" or "closest" unmarked attacker for this defender
                Player bestAttackerToMark = unmarkedAttackers
                    .OrderByDescending(a => a.trueRating.OverallForGameCalculations) // Prioritize higher rated attackers
                    .ThenBy(a => CalculateDistance(defender.CurrentZone, a.CurrentZone)) // Then closest
                    .FirstOrDefault();

                if (bestAttackerToMark != null)
                {
                    defender.DefensiveSetPieceRole = Enums.SetPieceRole.ManMarker; // Assign a generic ManMarker role
                    defender.MarkedOpponent = bestAttackerToMark;
                    availableDefenders.Remove(defender);
                    unmarkedAttackers.Remove(bestAttackerToMark);
                    //ShowMessage(defender.fullName + " marking (" + bestAttackerToMark.fullName + ").");
                }
            }
        }

        private void AssignZonalMarkers(List<Player> availableDefenders, Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone> preferredZoneCoverage,
            DefensiveSetPieceRoutine defensiveRoutine)
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignZonalMarkers: availableDefenders:{0},preferredZoneCoverage:{1}," +
            //    "defensiveRoutine:{2}",
            //    string.Join(",", availableDefenders.Select(p => p.position)),
            //    string.Join(",", preferredZoneCoverage.Select(kvp => $"{kvp.Key}:{kvp.Value}")),
            //    defensiveRoutine));


            //ShowMessage(" - Assigning Zonal-Marking roles.");
            // Distribute defenders across specified zonal marking zones
            foreach (var zoneEntry in preferredZoneCoverage)
            {
                Enums.SetPieceRole role = zoneEntry.Key; // This should be a ZonalMarker role like ZonalMarker, EdgeOfBoxSweeper etc.
                Enums.ConceptualSetPieceZone conceptualZone = zoneEntry.Value;
                Enums.PitchZone actualZone = MapConceptualToPitchZone(conceptualZone, DefendingTeam == HomeTeam, GetFlankOfZone(CurrentBallZone));

                Player bestZonalMarker = availableDefenders
                    .Where(p => defensiveRoutine.RoleAssignments.ContainsKey(role) && defensiveRoutine.RoleAssignments[role].Contains(p.Position))
                    .OrderByDescending(p => CalculateDefensiveRoleSuitability(p, role))
                    .ThenBy(p => CalculateDistance(p.CurrentZone, actualZone)) // Prioritize closer players
                    .FirstOrDefault();

                if (bestZonalMarker != null)
                {
                    bestZonalMarker.DefensiveSetPieceRole = role;
                    // Optionally, set a specific zone property for zonal markers if they need to 'anchor' to it
                    // bestZonalMarker.ZonalMarkingArea = actualZone; // You might add this property to Player
                    availableDefenders.Remove(bestZonalMarker);
                    //ShowMessage(bestZonalMarker.fullName + " assigned as " + role + " covering zone " + actualZone + ".");
                }
            }
            // Any remaining players not assigned a specific zonal role, default them to DeepDefender or ClearingDefender
            for (int i = availableDefenders.Count - 1; i >= 0; i--)
            {
                Player defender = availableDefenders[i];
                if (defender.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                {
                    defender.DefensiveSetPieceRole = Enums.SetPieceRole.ClearingDefender;
                    //ShowMessage(defender.fullName + " assigned as ClearingDefender (zonal fallback).");
                    availableDefenders.RemoveAt(i); // Remove the defender from the list if needed
                }
            }
        }

        private void AssignHybridMarkers(List<Player> availableDefenders, List<Player> attackingThreats, Dictionary<Enums.SetPieceRole, Enums.SetPieceRole> attackerRoleToDefenderRoleMapping, Dictionary<Enums.SetPieceRole, Enums.ConceptualSetPieceZone> preferredZoneCoverage,
            DefensiveSetPieceRoutine defensiveRoutine)
        {
            //LoggingStuff.LogMethodCall(string.Format("AssignHybridMarkers: availableDefenders:{0},attackingThreats:{1}," +
            //    "attackerRoleToDefenderRoleMapping:{2},preferredZoneCoverage:{3},defensiveRoutine:{4}",
            //    string.Join(",", availableDefenders.Select(p => p.position)),
            //    string.Join(",", attackingThreats.Select(p => p.position)),
            //    string.Join(",", attackerRoleToDefenderRoleMapping.Select(kvp => $"{kvp.Key}:{kvp.Value}")),
            //    string.Join(",", preferredZoneCoverage.Select(kvp => $"{kvp.Key}:{kvp.Value}")),
            //    defensiveRoutine));


            //ShowMessage(" - Assigning Hybrid-Marking roles.");
            // This is a more complex blend. Example: high-threat attackers man-marked, others fill zones.
            // 1. Man-mark key attacking threats first, based on attackerRoleToDefenderRoleMapping or just general threat.
            AssignManMarkers(availableDefenders, attackingThreats, attackerRoleToDefenderRoleMapping, defensiveRoutine);

            // 2. Then assign remaining defenders to zonal duties
            AssignZonalMarkers(availableDefenders, preferredZoneCoverage, defensiveRoutine);

            // Any players still unassigned (e.g., if there were more defenders than specific man/zonal roles)
            foreach (var defender in availableDefenders)
            {
                if (defender.DefensiveSetPieceRole == Enums.SetPieceRole.None)
                {
                    defender.DefensiveSetPieceRole = Enums.SetPieceRole.DeepDefender;
                    //ShowMessage(defender.fullName + " assigned as DeepDefender (hybrid fallback).");
                }
            }
        }

