        public void ErrorsLeadingToGoal(Player goalScorer, Team scoringTeam, int CurrentSecond)
        {
            //LoggingStuff.LogMethodCall(string.Format("ErrorsLeadingToGoal: goalScorer:{0},scoringTeam:{1},CurrentSecond:{2}",
            //    goalScorer.position, scoringTeam.Name, CurrentSecond));


            // First, clean up old entries
            CleanPotentialErrorsLeadingToGoal(CurrentSecond);

            HashSet<Player> creditedPlayersForThisGoal = new HashSet<Player>();

            for (int i = _potentialErrorsLeadingToGoal.Count - 1; i >= 0; i--)
            {
                var errorAction = _potentialErrorsLeadingToGoal[i];
                Player errorPlayer = errorAction.Item1;
                int actionTimestamp = errorAction.Item2;

                if (CurrentSecond - actionTimestamp > ERROR_LEADING_TO_GOAL_TIME_WINDOW_SECONDS)
                {
                    _potentialErrorsLeadingToGoal.RemoveAt(i);
                    continue;
                }

                if (errorPlayer.Team != scoringTeam && !creditedPlayersForThisGoal.Contains(errorPlayer))
                {
                    errorPlayer.gameStats.ErrorsLeadingToGoal++;
                    creditedPlayersForThisGoal.Add(errorPlayer);
                    //ShowMessage(errorPlayer.fullName + " committed an error leading to " + goalScorer.fullName + "'s goal (Goal at " +
                    //    CurrentSecond + "'s, error at " + actionTimestamp + "s).");

                    // Remove the error action after crediting
                    _potentialErrorsLeadingToGoal.RemoveAt(i);
                }
            }
        }

        private void ChanceCreated(Player shooter)
        {
            //LoggingStuff.LogMethodCall(string.Format("ChanceCreated: shooter:{0}",
            //    shooter.position));


            HashSet<Player> creditedPlayersForThisShot = new HashSet<Player>();
            int currentSecond = CurrentSecond; // Cache this to avoid repeated property access

            for (int i = _potentialChanceCreatingActions.Count - 1; i >= 0; i--)
            {
                var action = _potentialChanceCreatingActions[i];
                Player potentialCreator = action.Item1;
                int actionTimestamp = action.Item2;

                if (currentSecond - actionTimestamp > CHANCE_CREATED_TIME_WINDOW_SECONDS)
                {
                    _potentialChanceCreatingActions.RemoveAt(i);
                    continue;
                }

                if (potentialCreator != shooter && !creditedPlayersForThisShot.Contains(potentialCreator))
                {
                    potentialCreator.gameStats.ChancesCreated++;
                    creditedPlayersForThisShot.Add(potentialCreator);
                    //ShowMessage(potentialCreator.fullName + " created a chance for " + shooter.fullName +
                    //    "(Shot at " + currentSecond + "s, action at " + actionTimestamp + "s).");

                    // Optional: Remove the action after crediting
                    // _potentialChanceCreatingActions.RemoveAt(i);
                }
            }
        }

        private void IncreaseShotCount(Player shooter, bool shotOnTarget, Team attackingTeam)
        {
            shooter.gameStats.IncreaseShotOnGoal(shotOnTarget);
            if (attackingTeam == HomeTeam)
            {
                if (shotOnTarget)
                    HomeShotsOnTarget++;
                HomeShots++;
            }
            else
            {
                if (shotOnTarget)
                    AwayShotsOnTarget++;
                AwayShots++;
            }
        }

        private void PassStatsResolve(Player passer, bool successfulPass, int currentMathTimeInSeconds, bool isSetPiece, bool isHeaderPass,
            bool gkPass)
        {
            if (isSetPiece || isHeaderPass || gkPass) // we shouldn't count headers to teammates or free kicks/goal kicks
                return;
            passer.gameStats.IncreasePassCount(successfulPass);
            // New passer
            CleanPotentialAssistsCreatingActions();
            if (successfulPass)
            {
                _potentialChanceCreatingActions.Add(new Tuple<Player, int>(passer, currentMathTimeInSeconds));
                _potentialAssister.Add(new Tuple<Player, int>(passer, currentMathTimeInSeconds));
            }
        }

