        private const int NEGATION_TIME_WINDOW_SECONDS = 30; // Or 5, depends on desired strictness

        /// <summary>
        /// Checks for and negates potential 'Chances Created' if a subsequent defensive action by an opponent
        /// or a major offensive error by the attacking team occurs very quickly after the initial chance-creating action.
        /// </summary>
        /// <param name="teamWhoseChanceMightBeNegated">The team that initially created the potential chance.</param>
        /// <param name="currentMatchTimeInSeconds">The current game time in seconds.</param>
        /// <param name="negatingPlayer">The opposing player who performed a negating defensive action (optional).</param>
        /// <param name="majorOffensiveErrorOccurred">True if a major offensive error by the attacking team occurred (optional).</param>
        public void CheckForChanceNegation(Team teamWhoseChanceMightBeNegated, int currentMatchTimeInSeconds, Player negatingPlayer = null, bool majorOffensiveErrorOccurred = false)
        {
            string np = "null";
            if (negatingPlayer != null)
            {
                np = negatingPlayer.position.ToString();
            }
            //LoggingStuff.LogMethodCall(string.Format("CheckForChanceNegation: teamWhoseChanceMightBeNegated:{0}," +
            //    "currentMatchTimeInSeconds:{1},negatingPlayer:{2},majorOffensiveErrorOccurred:{3}",
            //    teamWhoseChanceMightBeNegated.Name, currentMatchTimeInSeconds,
            //    np, majorOffensiveErrorOccurred));


            // NEGATION_TIME_WINDOW_SECONDS should be defined as a const, e.g., private const int NEGATION_TIME_WINDOW_SECONDS = 10;
            // CHANCE_CREATED_TIME_WINDOW_SECONDS should also be defined, e.g., private const int CHANCE_CREATED_TIME_WINDOW_SECONDS = 120;

            // Iterate through _potentialChanceCreatingActions backwards to safely remove elements during iteration
            for (int i = _potentialChanceCreatingActions.Count - 1; i >= 0; i--)
            {
                var chanceEntry = _potentialChanceCreatingActions[i];
                Player creatorPlayer = chanceEntry.Item1;
                int actionTimestamp = chanceEntry.Item2;

                // 1. Only process entries from the team whose chance is being considered for negation
                if (creatorPlayer.Team != teamWhoseChanceMightBeNegated)
                {
                    continue; // Skip entries from the other team
                }

                // 2. Check if the original chance-creating action is within the short negation window
                if ((currentMatchTimeInSeconds - actionTimestamp) <= NEGATION_TIME_WINDOW_SECONDS)
                {
                    // Negation condition met if:
                    // a) An opponent performed a negating defensive action, OR
                    // b) A major offensive error occurred by the attacking team (e.g., bad touch, offside before shot)
                    bool negatedByOpponentDefense = (negatingPlayer != null && negatingPlayer.Team != teamWhoseChanceMightBeNegated);
                    bool negatedByAttackerError = majorOffensiveErrorOccurred;

                    if (negatedByOpponentDefense || negatedByAttackerError)
                    {
                        _potentialChanceCreatingActions.RemoveAt(i); // Safely remove the chance entry
                        string reason = negatedByOpponentDefense ? "opponent action" : "attacker's error";
                        //ShowMessage(string.Format("NEGATION: {0}'s potential chance at {1}s was negated by {2} at {3}s.",
                        //                            creatorPlayer.fullName, actionTimestamp, reason, currentMatchTimeInSeconds));
                    }
                }
                else if ((currentMatchTimeInSeconds - actionTimestamp) > CHANCE_CREATED_TIME_WINDOW_SECONDS)
                {
                    // This condition is a secondary cleanup. Primary cleanup for the main window happens
                    // in ProcessShotAttempt and HandlePossessionChange. This ensures very old entries are removed.
                    _potentialChanceCreatingActions.RemoveAt(i);
                }
            }
        }

        public void CheckForErrorNegation(Player negatingPlayer, int currentMatchTimeInSeconds)
        {
            // Iterate through _potentialErrorsLeadingToGoal backwards for safe removal
            for (int i = _potentialErrorsLeadingToGoal.Count - 1; i >= 0; i--)
            {
                var errorEntry = _potentialErrorsLeadingToGoal[i];
                Player errorPlayer = errorEntry.Item1;
                int errorTimestamp = errorEntry.Item2;

                // Check if the error is within the short negation window
                if ((currentMatchTimeInSeconds - errorTimestamp) <= NEGATION_TIME_WINDOW_SECONDS)
                {
                    // The negating player must be on the same team as the erroring player
                    if (negatingPlayer.Team == errorPlayer.Team)
                    {
                        // This 'negatingPlayer' has made a play that potentially negates the error.
                        // We assume if *any* negating action by a teammate happens quickly, it negates the error.
                        _potentialErrorsLeadingToGoal.RemoveAt(i); // Remove the error entry
                        //ShowMessage(string.Format("NEGATION: {0}'s error at {1}s was negated by {2}'s action at {3}s.",
                        //                            errorPlayer.fullName, errorTimestamp, negatingPlayer.fullName, currentMatchTimeInSeconds));
                    }
                }
                else if ((currentMatchTimeInSeconds - errorTimestamp) > ERROR_LEADING_TO_GOAL_TIME_WINDOW_SECONDS)
                {
                    // If the error is older than the main 120-second window, it should have been cleaned by ProcessGoalScored or HandlePossessionChange.
                    // This is just a safeguard, but primary cleanup is elsewhere.
                    _potentialErrorsLeadingToGoal.RemoveAt(i);
                }
            }
        }

