        // --- In your Game.cs (simplified EndMatch or a new SeasonManager class) ---
        public void ProcessMatchResults(Team homeTeam, Team awayTeam)
        {
            // Example yellow card accumulation thresholds
            int[] yellowCardThresholds = { 5, 10, 15 }; // 1-match ban at 5, another at 10, etc.

            foreach (Player player in homeTeam.completeRoster.Concat(awayTeam.completeRoster)) // Get all players who played
            {
                // 1. Update Season Yellow Cards & Reset Match Yellows
                player.totalSeasonYellowCards += player.yellowCards;
                player.yellowCards = 0; // Reset for next match

                // 2. Handle Red Card Suspensions (if sent off in THIS match)
                if (player.isSentOff)
                {
                    // Determine ban length (example: 1 match for 2 yellows, 3 for direct red)
                    int banLength = player.yellowCards == 2 ? 1 : 3; // Simplified: 2 yellows is 1 ban, direct red is 3
                    player.redCardSuspensionMatches = banLength;
                    player.isSuspendedForNextMatch = true; // Also mark as suspended for next immediate match
                    player.isSentOff = false; // Reset for next match
                }

                // 3. Check Yellow Card Accumulation for future matches
                foreach (int threshold in yellowCardThresholds)
                {
                    if (player.totalSeasonYellowCards == threshold && !player.isSuspendedForNextMatch) // Check if they just hit a threshold
                    {
                        player.isSuspendedForNextMatch = true;
                        //Console.WriteLine(player.fullName + " is suspended for 1 match due to yellow card accumulation (" + threshold + " yellows).");
                        break; // Only suspend once per threshold hit
                    }
                }
            }
            CheckCleanSheets();
        }

        // --- In your Game.cs (simplified StartMatch or a new SeasonManager class) ---
        public void PrepareForNextMatch(Team teamToPrepare)
        {
            List<Player> availablePlayers = new List<Player>();
            foreach (Player player in teamToPrepare.completeRoster) // Assuming team has a full squad list
            {
                if (player.isSuspendedForNextMatch)
                {
                    //Console.WriteLine(player.fullName + " is suspended for this match.");
                    player.isSuspendedForNextMatch = false; // Serve the suspension
                }
                else if (player.redCardSuspensionMatches > 0)
                {
                    //Console.WriteLine(player.fullName + " is serving a red card suspension (" + player.redCardSuspensionMatches + " matches remaining).");
                    player.redCardSuspensionMatches--; // Serve one match of the red card ban
                }
                else
                {
                    availablePlayers.Add(player); // Player is available
                }
                player.IsSubstituted = false; // They haven't been subtituted out of the next game, naturally.
                // Just resetting everything to try and simulate a season for now.
                player.ActiveInjuries = new List<Injury>();
                player.isInjured = false;
                player.gameStats.SecondsPlayed = 0;
                player.redCardSuspensionMatches = 0;
                player.yellowCards = 0;
                player.totalSeasonYellowCards = 0;
                player.totalSeasonRedCards = 0;
            }
            //teamToPrepare.SelectStarting11(availablePlayers);
            teamToPrepare.ConfigureRoster();
            teamToPrepare.HasMadeRedCardAdjustment = false;
            // teamToPrepare.starting11 = SelectStarting11(availablePlayers); // Logic to select starting 11 from available players
        }

        private string RecordGameResult(Team winningTeam, string homeScore, Team losingTeam, string awayScore, bool wasAWinner)
        {
            string homeRank = "";
            string awayRank = "";
            if (Season.Instance.teamRankInLeague.ContainsKey(leagueName))
            {
                homeRank = Season.Instance.teamRankInLeague[leagueName][HomeTeam].ToString() + " ";
                awayRank = Season.Instance.teamRankInLeague[leagueName][AwayTeam].ToString() + " ";
            }

            string GameResult = homeRank + HomeTeam.Name + ": " + homeScore + " - " + awayRank + AwayTeam.Name + ": " + awayScore;
            winningTeam.CreateSeasonStats(leagueName);
            losingTeam.CreateSeasonStats(leagueName);
            if (wasAWinner)
            {
                this.Winner = winningTeam;
                this.Loser = losingTeam;
                if (!isPlayoffOrFriendly && !isEuroKnockoutRound)
                {
                    this.Winner.seasonStats[leagueName].wins++;
                    this.Loser.seasonStats[leagueName].losses++;
                }
            }
            else
            {
                if (!isPlayoffOrFriendly && !isEuroKnockoutRound)
                {
                    winningTeam.seasonStats[leagueName].draws++;
                    losingTeam.seasonStats[leagueName].draws++;
                }
            }

            ProcessMatchResults(HomeTeam, AwayTeam);

            this.PrepareForNextMatch(HomeTeam);
            this.PrepareForNextMatch(AwayTeam);

            return GameResult;
        }

        private void CheckCleanSheets()
        {
            if (AwayScore == 0)
            {
                this.HomeTeam.GoalKeeper.gameStats.cleansheets++;
            }
            if (HomeScore == 0)
            {
                this.AwayTeam.GoalKeeper.gameStats.cleansheets++;
            }
        }

        private void StoreStatsForGame(GameStats gs, Team team)
        {
            gs.assists += team.gameStats.assists;
            gs.fouls += team.gameStats.fouls;
            gs.goals += team.gameStats.goals;
            gs.goalsConceded += team.gameStats.goalsConceded;
            gs.penaltyKickAttempts += team.gameStats.penaltyKickAttempts;
            gs.penaltyKickGoals += team.gameStats.penaltyKickGoals;
            gs.redCards += team.gameStats.redCards;
            gs.Saves += team.gameStats.Saves;
            gs.shotsOnGoal += team.gameStats.shotsOnGoal;
            gs.shotsTotal += team.gameStats.shotsTotal;
            gs.yellowCards += team.gameStats.yellowCards;
            gs.SecondsWithBall += team.gameStats.SecondsWithBall;
            if (((double)gs.SecondsWithBall / 60.0) > 75)
            {
                //throw new Exception("One team dominated time of possession. Probably a loop.");
            }
            gs.cornerKicks += team.gameStats.cornerKicks;
            gs.offsides += team.gameStats.offsides;
            gs.PassAttempts += team.gameStats.PassAttempts;
            gs.SuccessfulPasses += team.gameStats.SuccessfulPasses;
        }

        #endregion

        public async void LogEntry(MatchEntry me)
        {
            // Publish the event
            if (this.watchingGame)
                OnMatchEntryCreated?.Invoke(me);
            me.CurrentMatchMinute = CurrentMinute;
            me.CurrentMatchSecond = CurrentSecond;
            //logger.LogMatchEntryToFile(me);
            MyLogger2.LogMatchEntry(me);
        }
    }
